# ۶ اکتبر — «Flow» از نوار رفت و «Portfolio» به منوی والت؛ هیچ‌کدام دیگر تبِ مستقیم نیستند.
# ۱۸ اکتبر — Markets بازشو نیست: انتخابِ ذخیره‌شده zaexa.markets.v1 = flow را می‌گذاریم و روی تبِ Markets کلیک می‌کنیم.
# این کمکی همان مسیرِ کاربر را می‌رود: swap = کلیکِ تب، flow = کلیکِ تبِ Markets با انتخابِ flow،
# folio = setView("folio") (همان کاری که دکمه‌ی «Portfolio» در منوی والت می‌کند؛ منوی والت خودش در [wallet portfolio] سنجیده می‌شود).
async def go_view(pg, v):
    if v == "flow":
        await pg.evaluate("() => localStorage.setItem('zaexa.markets.v1', 'flow')")
        await pg.click("#navMarkets")
    elif v == "folio":
        await pg.evaluate("() => setView('folio')")
    else:
        await pg.click('#nav [data-view="%s"]' % v)


# دکمه‌ی گردِ تم (۶ اکتبر): یک آیکونِ دیده‌شده در هر تم، ۳۸×۳۸، کاملاً گرد.
THEME_BTN_JS = """(a) => {
    const b = document.querySelector(a.btn);
    const r = b.getBoundingClientRect();
    const cs = getComputedStyle(b);
    const op = s => { const e = b.querySelector(s); return e ? getComputedStyle(e).opacity : null; };
    return {theme: document.documentElement.dataset.theme, checked: b.getAttribute('aria-checked'),
            w: r.width, h: r.height, radius: cs.borderRadius, sun: op(a.sun), moon: op(a.moon),
            shadow: cs.boxShadow, color: cs.color, bg: cs.backgroundColor,
            borderW: cs.borderTopWidth, borderC: cs.borderTopColor,
            before: getComputedStyle(b, '::before').display,
            ...(() => {
              // ۶ اکتبر (دورِ سوم): مرجع = دکمه‌ی تنظیماتِ فشرده (#setBtn با aria-expanded=true، گذار خاموش)؛
              // در صفحه‌هایی که #setBtn ندارند (لندینگ/گزارش) عنصرِ موقتی با همان توکن‌های سایه/زمینه/حاشیه.
              const t = document.createElement('i');
              t.style.cssText = 'position:absolute;visibility:hidden;color:var(--acc);background:var(--bg);border:1px solid var(--line);box-shadow:inset 2px 2px 5px var(--soft-lo),inset -2px -2px 5px var(--soft-hi)';
              document.body.appendChild(t);
              const ts = getComputedStyle(t), res = {accColor: ts.color, litShadow: ts.boxShadow, litBg: ts.backgroundColor, litBorderC: ts.borderTopColor,
                setShadow: null, setBg: null, setColor: null, setBorderC: null};
              t.remove();
              const sb = document.getElementById('setBtn');
              if (sb) {
                const prevT = sb.style.transition, prevE = sb.getAttribute('aria-expanded');
                sb.style.transition = 'none'; sb.setAttribute('aria-expanded', 'true');
                const ss = getComputedStyle(sb);
                // سایه‌ی «تعریف‌شده»ی حالتِ فشرده را از خودِ قاعده‌ی CSS می‌خوانیم، نه از computed: قاعده‌ی عمومیِ
                // .chip:not(.solid):not(#themeBtn) (ویژگیِ بالاتر) سایه‌ی computedِ #setBtn را همیشه برآمده نگه می‌دارد.
                let decl = null;
                for (const sh of document.styleSheets) { let rules; try { rules = sh.cssRules; } catch (e) { continue; }
                  for (const r of rules) if (r.selectorText && r.selectorText.includes('#setBtn[aria-expanded') && r.style && r.style.boxShadow) decl = r.style.boxShadow; }
                if (decl) { const t2 = document.createElement('i'); t2.style.cssText = 'position:absolute;visibility:hidden'; t2.style.boxShadow = decl; document.body.appendChild(t2); res.setShadow = getComputedStyle(t2).boxShadow; t2.remove(); }
                res.setBg = ss.backgroundColor; res.setColor = ss.color; res.setBorderC = ss.borderTopColor;
                if (prevE === null) sb.removeAttribute('aria-expanded'); else sb.setAttribute('aria-expanded', prevE);
                sb.style.transition = prevT;
              }
              return res;
            })()};
}"""

async def theme_button_probe(pg, label, btn, sun, moon):
    """هر دو تم را می‌سنجد: اندازه، گردی، فقط یک آیکونِ دیده‌شده، و اینکه کلیک
    تم و aria-checked را برمی‌گرداند و آیکونِ دیگر دیده می‌شود. خلاصه برمی‌گرداند."""
    a = {"btn": btn, "sun": sun, "moon": moon}
    seen = []
    await pg.wait_for_timeout(400)  # گذارِ opacity/transform پس از اعمالِ تمِ آغازین تمام شود
    for _ in range(2):
        # زیرِ بارِ سنگینِ سوئیت گذارِ opacity دیرتر تمام می‌شود؛ تا ۳ ثانیه تکرار می‌کنیم
        # (سنجشِ ثابت ۴۰۰ms زیرِ بار وسطِ گذار می‌افتاد).
        for _try in range(20):
            st = await pg.evaluate(THEME_BTN_JS, a)
            if sorted(n for n in ("sun", "moon") if st[n] == "1") in (["sun"], ["moon"]) and st["color"] == st["accColor"]:
                break  # رنگ هم گذارِ .2s دارد؛ تا نشستن صبر می‌کنیم
            await pg.wait_for_timeout(150)
        dark = st["theme"] == "dark"
        assert abs(st["w"] - 38) <= 0.5 and abs(st["h"] - 38) <= 0.5, \
            "[theme button] %s %s: expected 38x38, got %sx%s" % (label, st["theme"], st["w"], st["h"])
        assert st["radius"] == "50%", "[theme button] %s: border-radius %r is not 50%%" % (label, st["radius"])
        vis = [n for n in ("sun", "moon") if st[n] == "1"]
        assert vis == (["moon"] if dark else ["sun"]), \
            "[theme button] %s %s: visible icons %s (sun=%s moon=%s)" % (label, st["theme"], vis, st["sun"], st["moon"])
        assert st["checked"] == ("true" if dark else "false"), \
            "[theme button] %s: aria-checked %r in %s" % (label, st["checked"], st["theme"])
        # ۶ اکتبر (دورِ سوم، مالک): دکمه‌ی تم همیشه همان ظاهرِ دکمه‌ی تنظیماتِ فشرده است
        ctx = "[theme button] %s %s" % (label, st["theme"])
        want_sh = st["setShadow"] or st["litShadow"]
        assert st["shadow"] == want_sh, "%s: button box-shadow %r != the shadow declared for the settings button's pressed state %r" % (ctx, st["shadow"], want_sh)
        assert st["shadow"].count("inset") == 2 and len(re.findall(r"rgba?\(", st["shadow"])) == 2, \
            "%s: shadow must be exactly the two pressed (inset) layers: %r" % (ctx, st["shadow"])
        want_bg = st["setBg"] or ("rgb(8, 7, 13)" if dark else st["litBg"])
        assert st["bg"] == want_bg, "%s: background %r != the settings button's pressed background %r" % (ctx, st["bg"], want_bg)
        assert st["borderW"] == "1px" and st["borderC"] == (st["setBorderC"] or st["litBorderC"]), \
            "%s: border %s %r != the settings button's 1px line border %r" % (ctx, st["borderW"], st["borderC"], st["setBorderC"] or st["litBorderC"])
        assert st["before"] == "none", "%s: the old raised-disc ::before must be gone (display none): %r" % (ctx, st["before"])
        assert st["color"] == st["accColor"] and (st["setColor"] is None or st["color"] == st["setColor"]), \
            "%s: icon colour %r != accent %r / pressed settings colour %r" % (ctx, st["color"], st["accColor"], st["setColor"])
        if dark:
            assert st["bg"] == "rgb(8, 7, 13)", "%s: dark background %r is not rgb(8, 7, 13)" % (ctx, st["bg"])
        seen.append(st["theme"])
        await pg.click(btn)
        await pg.wait_for_timeout(400)
        st2 = await pg.evaluate(THEME_BTN_JS, a)
        assert st2["theme"] != st["theme"], "[theme button] %s: click did not toggle data-theme" % label
        assert st2["checked"] != st["checked"], "[theme button] %s: click did not toggle aria-checked" % label
    return "%s %s->%s ok" % (label, seen[0], seen[1] if len(seen) > 1 else "")

async def check_theme_button(p, errors):
    """[theme button] اپ، pairs و لندینگ — دسکتاپ و موبایل ۳۹۰ (گزارش جداگانه در check_report_page)."""
    out = []
    b = await p.chromium.launch()
    for name, btn, sun, moon in (("index.html", "#themeBtn", ".themeSun", ".themeMoon"),
                                 ("pairs.html", "#themeBtn", ".themeSun", ".themeMoon"),
                                 ("landing.html", "#themeToggle", ".sun", ".moon")):
        for vw in (1440, 390):
            for scheme in ("light", "dark"):
                pg = await b.new_page(viewport={"width": vw, "height": 900}, color_scheme=scheme)
                await pg.route("**/*", lambda route: route.continue_() if route.request.url.startswith("file:") else route.abort())
                await pg.goto("file://" + os.path.join(HERE, "..", name), wait_until="domcontentloaded")
                await pg.wait_for_timeout(500)
                out.append(await theme_button_probe(pg, "%s@%d/%s" % (name, vw, scheme), btn, sun, moon))
                await pg.close()
    await b.close()
    print("[theme button] round 38x38 push button, border-radius 50%%, exactly one icon visible per theme, click toggles theme+aria-checked: %d runs on app/pairs/landing" % len(out))

async def check_light_scrollbar(p, errors):
    """[light scrollbar] تمِ روشن: ترکِ اسکرولِ صفحه هم‌رنگِ پس‌زمینه (app، pairs، landing؛ report در check_report_page)."""
    b = await p.chromium.launch()
    rows = []
    for name in ("index.html", "pairs.html", "landing.html"):
        for scheme in ("light", "dark"):
            pg = await b.new_page(viewport={"width": 1440, "height": 900}, color_scheme=scheme)
            await pg.route("**/*", lambda route: route.continue_() if route.request.url.startswith("file:") else route.abort())
            await pg.goto("file://" + os.path.join(HERE, "..", name), wait_until="domcontentloaded")
            await pg.wait_for_timeout(400)
            st = await pg.evaluate("() => { const c = getComputedStyle(document.documentElement); return { t: document.documentElement.dataset.theme, cs: c.colorScheme, sc: c.scrollbarColor }; }")
            assert st["t"] == scheme, "[light scrollbar] %s: expected theme %s, got %s" % (name, scheme, st["t"])
            if scheme == "light":
                assert st["cs"] == "light", "[light scrollbar] %s light: color-scheme is %r" % (name, st["cs"])
                assert st["sc"] == "rgb(214, 218, 225) rgb(244, 245, 247)", "[light scrollbar] %s light: scrollbar-color is %r" % (name, st["sc"])
            else:
                assert st["cs"] == "dark", "[light scrollbar] %s dark: color-scheme is %r" % (name, st["cs"])
            rows.append("%s/%s=%s" % (name, scheme, st["cs"]))
            await pg.close()
    await b.close()
    print("[light scrollbar] light theme: color-scheme light and scrollbar track rgb(244, 245, 247) on app/pairs/landing; dark stays dark (%s)" % ", ".join(rows))

# [landing dither] (دانه‌ی دیترینگِ پس‌زمینه) در ۲۴ اکتبر به تصمیمِ مالک حذف شد؛ نگهبانش عمداً بازنمی‌گردد.
async def check_setbtn_pressed(p, errors):
    """[settings pressed] ۶ اکتبر — دکمه‌ی تنظیمات با کلیک (active) و با منوی باز باید گود شود؛
    قبلاً .chip:not(.solid):not(#themeBtn) سایه‌ی برآمده را نگه می‌داشت."""
    b = await p.chromium.launch()
    rows = []
    for name in ("index.html", "pairs.html"):
        for scheme in ("light", "dark"):
            pg = await b.new_page(viewport={"width": 1440, "height": 900}, color_scheme=scheme)
            await pg.route("**/*", lambda route: route.continue_() if route.request.url.startswith("file:") else route.abort())
            await pg.goto("file://" + os.path.join(HERE, "..", name), wait_until="domcontentloaded")
            await pg.wait_for_timeout(400)
            rest = await pg.evaluate("() => getComputedStyle(document.getElementById('setBtn')).boxShadow")
            exp = await pg.evaluate("() => { const b = document.getElementById('setBtn'); b.setAttribute('aria-expanded','true'); const s = getComputedStyle(b).boxShadow; b.setAttribute('aria-expanded','false'); return s; }")
            bb = await (await pg.query_selector("#setBtn")).bounding_box()
            await pg.mouse.move(bb["x"] + bb["width"] / 2, bb["y"] + bb["height"] / 2)
            await pg.mouse.down()
            act = await pg.evaluate("() => getComputedStyle(document.getElementById('setBtn')).boxShadow")
            await pg.mouse.up()
            await pg.close()
            rows.append((name, scheme, "inset" in rest, "inset" in exp, "inset" in act))
            assert "inset" not in rest, "[settings pressed] %s/%s: resting settings button must stay raised: %r" % (name, scheme, rest)
            assert "inset" in exp, "[settings pressed] %s/%s: expanded settings button must be inset: %r" % (name, scheme, exp)
            assert "inset" in act, "[settings pressed] %s/%s: settings button under the mouse (active) must be inset: %r" % (name, scheme, act)
    await b.close()
    print("[settings pressed] " + "; ".join("%s/%s rest=%s expanded=%s active=%s" % r for r in rows))

async def check_theme_migration(p, errors):
    """رفعِ باگِ «تم بین صفحه‌ها زنده نمی‌ماند» — پروبِ ۶ (پویا): مهاجرتِ
    یک‌باره‌ی کلیدِ localStorage واقعاً روی یک صفحه‌ی بارگذاری‌شده اتفاق
    می‌افتد، نه فقط داخلِ متنِ اسکریپت به‌نظر درست می‌آید.

    حالتِ ۱: فقط کلیدِ قدیمی (zaexa.landing.theme) روی "dark" است. صفحه باید
    تیره باز شود *و* بلافاصله همان مقدار را در کلیدِ تازه هم بنویسد —
    وگرنه دفعه‌ی بعد که کلیدِ قدیمی هم پاک شود، انتخابِ کاربر گم می‌شود.
    حالتِ ۲: هر دو کلید ست‌اند، قدیمی="dark"، تازه="light". کلیدِ تازه
    باید برنده باشد — یعنی از این پس فقط همان یکی منبعِ حقیقت است."""
    path = os.path.join(HERE, "..", "landing.html")
    idx_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
    new_key = theme_key_from_index(idx_src)

    b = await p.chromium.launch()

    ctx1 = await b.new_context()
    pg1 = await ctx1.new_page()
    pg1.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await ctx1.add_init_script("localStorage.setItem(%r, 'dark');" % OLD_THEME_KEY)
    await pg1.goto("file://" + path)
    await pg1.wait_for_timeout(300)
    state1 = await pg1.evaluate(
        "(k) => ({theme: document.documentElement.dataset.theme, "
        "newVal: localStorage.getItem(k)})", new_key)
    await ctx1.close()
    assert state1["theme"] == "dark", (
        "with only the old key (%r) set to 'dark', web/landing.html ended up in %r theme "
        "instead of dark — the one-time migration did not run" % (OLD_THEME_KEY, state1["theme"]))
    assert state1["newVal"] == "dark", (
        "with only the old key (%r) set to 'dark', web/landing.html did not write 'dark' into "
        "the new key (%r) — got %r. Without this, the choice is lost the moment the old key "
        "is gone" % (OLD_THEME_KEY, new_key, state1["newVal"]))

    ctx2 = await b.new_context()
    pg2 = await ctx2.new_page()
    pg2.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await ctx2.add_init_script(
        "localStorage.setItem(%r, 'light'); localStorage.setItem(%r, 'dark');"
        % (new_key, OLD_THEME_KEY))
    await pg2.goto("file://" + path)
    await pg2.wait_for_timeout(300)
    theme2 = await pg2.evaluate("() => document.documentElement.dataset.theme")
    await ctx2.close()
    assert theme2 == "light", (
        "with the new key (%r) set to 'light' and the old key (%r) set to 'dark', "
        "web/landing.html ended up %r — the new key must win once it holds a valid choice"
        % (new_key, OLD_THEME_KEY, theme2))

    await b.close()
    print("[theme migration] old-key-only -> dark and migrated into %r; "
          "new-key-present -> new key wins" % new_key)


async def check_landing_mobile(p, errors):
    """صفحه‌ی معرفی (نه اپ) را با file:// روی موبایل واقعی باز کن — ۳۹۰×۸۴۴،
    isMobile، hasTouch — و سه باگِ زنده‌ی گزارش‌شده روی گوشیِ صاحب‌کار را
    اندازه بگیر، نه حدس بزن.

    باگِ اول: گروهِ راستِ هدر (دکمه‌ی تم + همبرگر) بدونِ margin-left:auto —
    که با حذفِ .desktop-nav روی موبایل، ستونِ گریدِ وسط را می‌گرفت نه ستونِ
    سومِ 1fr را — وسطِ عرض می‌نشست و سمتِ راست یک شکافِ خالیِ بزرگ می‌ماند.
    اندازه‌گیریِ زنده پیش از رفع: burgerRight≈257 در ویوپورتِ ۳۹۰ (یعنی ۱۳۳px
    فاصله تا لبه). بعد از رفع: ≈372.

    باگِ دوم: قانونِ .exitcheck برای گرید تک‌ستونه در مدیاکوئریِ اول همین فایل
    نوشته شده بود، ولی تعریفِ بدون‌مدیای .exitcheck پایین‌ترِ همان فایل با
    اسپسیفیسیتیِ برابر و ترتیبِ متن‌یِ بعدی رویش غالب می‌شد — یعنی کارت روی
    موبایل هم دوستونه می‌ماند. اندازه‌گیریِ زنده پیش از رفع: عرضِ کارت=141px و
    ردیفِ عنوان (stageHd) با سه‌خط پیچیدن به ۵۸px قد می‌کشید. بعد از رفع:
    عرض≈354px، ارتفاعِ ردیف≈19px.

    باگِ سوم: .trust-art (مدار‌ها + نشانِ «؟» بخشِ THE TRUST LAYER) برایش عرضی
    تعریف نشده بود — فقط max-width. روی گریدِ تک‌ستونه‌ی موبایل، چون .trust
    خودش align-items:center دارد (بدونِ کشش روی محورِ بلاک) و همه‌ی فرزندانِ
    trust-art با position:absolute از جریان بیرون‌اند، aspect-ratio نتوانست
    اندازه را حل کند و جعبه صفر×صفر ماند. متنِ «؟» با font-size:75px هنوز
    رسم می‌شد چون overflow پیش‌فرض visible است — یعنی جوهرِ واقعیِ نویسه از
    جعبه‌ی نامرئی‌اش سرریز کرده و مستقیم روی eyebrow و تیترِ بخش می‌نشست، در
    حالی که جعبه‌ی خودِ عنصر (۱۶×۱۶px) هیچ‌وقت با جعبه‌ی تیتر تلاقی نداشت.
    ⚠️ همین «جعبه تلاقی ندارد ولی جوهر تلاقی دارد» دقیقاً همان چیزی است که
    یک سوئیپِ هم‌پوشانیِ قبلی (که فقط getBoundingClientRect خودِ عنصر را
    می‌سنجید، نه Range روی متنِ داخلش) از قلم انداخته بود — آن سوئیپ می‌گفت
    «فقط هم‌پوشانی‌های عمدی: آواتارهای پشته‌ای، لایه‌های SVG» چون تنها
    هم‌پوشانی‌هایی که می‌دید همان‌ها بودند؛ این یکی جعبه‌اش اصلاً به تیتر
    نمی‌رسید. نگهبانِ [landing mobile trust glyph] و overlap sweep پایین‌تر
    هر دو روی جوهرِ واقعیِ متن (Range) کار می‌کنند، نه فقط جعبه‌ی عنصر.
    اندازه‌گیریِ زنده پیش از رفع (۳۹۰px): جوهرِ نویسه تا y≈5749 پایین می‌آمد،
    eyebrow از y≈5690.8 شروع می‌شد — هم‌پوشانی. بعد از رفع: پایینِ جوهر
    y≈5848، بالای eyebrow y≈5978.6 — فاصله≈130px. دسکتاپ (۱۲۸۰px) دست‌نخورده
    می‌ماند چون رفع فقط داخلِ @media(max-width:900px) است.

    ⚠️ آستانه‌ها را روی خودِ عددهای اندازه‌گرفته‌شده قفل می‌کنیم، نه فقط
    «داخلِ ویوپورت» — چون نسخه‌ی شکسته هم داخلِ ویوپورت بود، فقط له‌شده."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    ctx = await b.new_context(viewport={"width": 390, "height": 844},
                               device_scale_factor=2, is_mobile=True, has_touch=True)
    pg = await ctx.new_page()
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(400)

    header = await pg.evaluate("""() => {
        const r = el => el.getBoundingClientRect();
        const toggle = r(document.getElementById('themeToggle'));
        const burger = r(document.getElementById('menuToggle'));
        return {toggleRight: toggle.right, burgerRight: burger.right,
                docW: document.documentElement.scrollWidth,
                vw: document.documentElement.clientWidth};
    }""")
    print("[landing mobile header] toggleRight=%.1f burgerRight=%.1f doc=%s viewport=%s"
          % (header["toggleRight"], header["burgerRight"], header["docW"], header["vw"]))
    tol = 20
    assert header["burgerRight"] >= header["vw"] - tol, (
        "the hamburger sits %.1fpx from the right edge of a %spx viewport (measured live at "
        "~133px away — roughly mid-width — when the header's right-hand group loses its grid "
        "placement): %s" % (header["vw"] - header["burgerRight"], header["vw"], header))
    assert header["docW"] <= header["vw"] + 1, (
        "web/landing.html scrolls sideways at %spx: scrollWidth=%s"
        % (header["vw"], header["docW"]))

    exit_info = await pg.evaluate("""() => {
        const rect = el => el ? (({x,y,width,height,top,left,right,bottom}) => (
            {x,y,width,height,top,left,right,bottom}))(el.getBoundingClientRect()) : null;
        return {card: rect(document.querySelector('.exitStage .stage')),
                stageHd: rect(document.querySelector('.stageHd')),
                ttl: rect(document.querySelector('.stageTtl')),
                sub: rect(document.querySelector('.stageSub')),
                vw: document.documentElement.clientWidth};
    }""")
    print("[landing mobile exit-test] cardWidth=%.1f cardRight=%.1f stageHdHeight=%.1f"
          % (exit_info["card"]["width"], exit_info["card"]["right"],
             exit_info["stageHd"]["height"]))
    assert exit_info["card"]["right"] <= exit_info["vw"] + 1, (
        "the exit-test card overflows a %spx viewport: %s" % (exit_info["vw"], exit_info["card"]))
    assert exit_info["card"]["width"] >= 260, (
        "the exit-test card is only %.1fpx wide at a %spx viewport (measured live at 141px "
        "when .exitcheck stays two-column on mobile — a later unmediaed rule in this same "
        "file overrides the mobile media query's grid-template-columns:1fr) — it should span "
        "the section's usable width" % (exit_info["card"]["width"], exit_info["vw"]))

    def overlaps(a, b):
        ox = max(0, min(a["right"], b["right"]) - max(a["left"], b["left"]))
        oy = max(0, min(a["bottom"], b["bottom"]) - max(a["top"], b["top"]))
        return ox > 1 and oy > 1
    assert not overlaps(exit_info["ttl"], exit_info["sub"]), (
        "the exit-test card's title and subtitle rectangles overlap: %s / %s"
        % (exit_info["ttl"], exit_info["sub"]))
    assert exit_info["stageHd"]["height"] <= 30, (
        "the exit-test card's title row is %.1fpx tall (measured live at 58px when the title "
        "wraps across three lines because the card is squashed two-column) — it should fit "
        "on one line" % exit_info["stageHd"]["height"])

    # ---- [landing mobile overlap sweep] ----
    # سوئیپِ قبلی فقط getBoundingClientRect خودِ عنصر را می‌سنجید. آن کافی
    # نیست وقتی جعبه‌ی یک عنصرِ تزئینی جمع‌شده (صفر یا نزدیکِ صفر) ولی
    # overflow:visible اجازه می‌دهد متن/گلیفِ داخلش از جعبه بیرون بزند —
    # دقیقاً حالتِ نشانِ «؟» بخشِ trust. این نسخه برای هر عنصرِ تزئینیِ برگ
    # (بدونِ فرزندِ عنصری) که فقط متن دارد، به‌جای جعبه‌ی خودش، جعبه‌ی
    # Range روی متنش را می‌سنجد — یعنی جوهرِ واقعیِ رسم‌شده را.
    #
    # «تزئینی بودن» ساختاری تشخیص داده می‌شود، نه با فهرستِ دستیِ idها:
    # هر برگی که زیرِ [aria-hidden="true"] یا زیرِ یک <svg> است. «متنِ
    # واقعی» هم h1/h2/h3/p/li است — نه هر span، پس آواتارهای پشته‌ایِ
    # .proof-avatar (که هرکدام حرفِ واقعی دارند، نه تزئین) از اساس در این
    # سوئیپ شرکت نمی‌کنند؛ پشته‌شدنِ عمدی‌شان تصمیمِ محتوا-با-محتواست، نه
    # چیزی که این نگهبان قرار است داوری کند. دو راهِ فرارِ صریح هم هست، هر دو
    # ساختاری: (۱) اگر تزئینی و متن هر دو زیرِ همان <svg> باشند (لایه‌های
    # داخلیِ یک دیاگرام)، (۲) اگر عنصر یا یکی از اجدادش data-overlap-ok
    # داشته باشد — مثلِ .page-glow که چون z-index:-1 و position:fixed دارد،
    # با تقریباً هر تیتری هم‌پوشانیِ هندسی دارد ولی همیشه پشتِ محتواست.
    sweep = await pg.evaluate("""() => {
        function isVisible(el) {
            const r = el.getBoundingClientRect();
            if (r.width <= 0 || r.height <= 0) return false;
            const cs = getComputedStyle(el);
            return cs.visibility !== 'hidden' && cs.display !== 'none'
                && parseFloat(cs.opacity) > 0;
        }
        function inkRect(el) {
            if (el.children.length === 0 && el.textContent.trim().length) {
                const rg = document.createRange();
                rg.selectNodeContents(el);
                const rc = rg.getBoundingClientRect();
                if (rc.width > 0 || rc.height > 0) return rc;
            }
            // شکلِ بدونِ متن (مثلِ حلقه‌های نقطه‌چینِ .trust-orbit) با
            // rotate+skew جعبه‌ی محاطی‌اش را چند برابرِ خودِ حلقه‌ی نازک
            // بزرگ می‌کند — جعبه‌ی بعدِ تبدیل، نه جوهرِ واقعی. transform را
            // موقتاً خاموش می‌کنیم، جعبه‌ی پیش‌از-تبدیل را می‌سنجیم (که برای
            // یک عنصرِ inset:0 دقیقاً جعبه‌ی والدش است، تقریبِ معقولی برای
            // جوهر)، و بعد برمی‌گردانیم — وگرنه دسکتاپِ ۱۲۸۰px هم به‌غلط
            // «هم‌پوشانی» می‌گرفت (اندازه‌گیریِ زنده: بدونِ این رفع، جعبه‌ی
            // orbit-1 در ۱۲۸۰px از x=-66 تا x=666 می‌رفت و ستونِ trust-copy
            // را قورت می‌داد، در حالی که خودِ حلقه فقط یک نوارِ نازک است).
            const cs = getComputedStyle(el);
            if (cs.transform && cs.transform !== 'none') {
                const prevT = el.style.transform, prevA = el.style.animation,
                      prevTr = el.style.transition;
                el.style.setProperty('transition', 'none', 'important');
                el.style.setProperty('animation', 'none', 'important');
                el.style.setProperty('transform', 'none', 'important');
                const rc = el.getBoundingClientRect();
                el.style.transform = prevT; el.style.animation = prevA;
                el.style.transition = prevTr;
                return rc;
            }
            return el.getBoundingClientRect();
        }
        const plain = r => ({x: r.x, y: r.y, width: r.width, height: r.height,
            top: r.top, left: r.left, right: r.right, bottom: r.bottom});

        const decorative = Array.from(document.querySelectorAll('*'))
            .filter(el => el.children.length === 0)
            .filter(el => el.closest('[aria-hidden="true"]') || el.closest('svg'))
            .filter(isVisible);
        const protectedText = Array.from(document.querySelectorAll('h1,h2,h3,p,li'))
            .filter(el => !el.closest('[aria-hidden="true"]'))
            .filter(el => el.textContent.trim().length)
            .filter(isVisible);

        const violations = [];
        for (const d of decorative) {
            if (d.closest('[data-overlap-ok]')) continue;
            const dRect = inkRect(d);
            const dSvg = d.closest('svg');
            for (const t of protectedText) {
                if (t.closest('[data-overlap-ok]')) continue;
                if (dSvg && dSvg === t.closest('svg')) continue;
                const tRect = t.getBoundingClientRect();
                const ox = Math.max(0, Math.min(dRect.right, tRect.right)
                    - Math.max(dRect.left, tRect.left));
                const oy = Math.max(0, Math.min(dRect.bottom, tRect.bottom)
                    - Math.max(dRect.top, tRect.top));
                if (ox > 1 && oy > 1) {
                    violations.push({
                        decorative: (d.className && d.className.toString) ? d.className.toString() : d.tagName,
                        text: t.tagName + ':' + t.textContent.trim().slice(0, 40),
                        decRect: plain(dRect), textRect: plain(tRect)
                    });
                }
            }
        }
        return {decorativeCount: decorative.length, protectedCount: protectedText.length,
                violations};
    }""")
    print("[landing mobile overlap sweep] decorative=%d protected-text=%d violations=%d"
          % (sweep["decorativeCount"], sweep["protectedCount"], len(sweep["violations"])))
    assert not sweep["violations"], (
        "a decorative element's rendered ink overlaps real heading/paragraph text at %spx "
        "wide, checked by ink extent (a Range over the text node) rather than just the "
        "element's own box — found: %s" % (header["vw"], sweep["violations"][:3]))

    # ---- [landing mobile trust glyph] ----
    # پیامدِ زنده‌ی همان باگِ سوم: نشانِ «؟» تزئینیِ بخشِ trust در برابرِ
    # eyebrow و h2 همان بخش، با آستانه‌ی عددیِ قفل‌شده (نه فقط «هم‌پوشانی
    # ندارد») — چون یک نگهبانِ شل («داخلِ ویوپورت است») همان زمانی که جعبه
    # له شده بود هم سبز می‌شد.
    trust = await pg.evaluate("""() => {
        const rect = el => { const r = el.getBoundingClientRect();
            return {top: r.top, left: r.left, right: r.right, bottom: r.bottom}; };
        const signal = document.querySelector('.trust-signal');
        const rg = document.createRange();
        rg.selectNodeContents(signal.firstChild);
        const ink = rg.getBoundingClientRect();
        return {
            glyphInk: {top: ink.top, left: ink.left, right: ink.right, bottom: ink.bottom},
            eyebrow: rect(document.querySelector('#trust .eyebrow')),
            h2: rect(document.querySelector('#trust h2'))
        };
    }""")
    clearance = trust["eyebrow"]["top"] - trust["glyphInk"]["bottom"]
    print("[landing mobile trust glyph] glyphInkBottom=%.1f eyebrowTop=%.1f h2Top=%.1f "
          "clearance=%.1f" % (trust["glyphInk"]["bottom"], trust["eyebrow"]["top"],
                               trust["h2"]["top"], clearance))
    assert not overlaps(trust["glyphInk"], trust["h2"]), (
        "the trust section's decorative \"?\" glyph visually overlaps the heading "
        "at %spx wide: glyph ink=%s heading=%s"
        % (header["vw"], trust["glyphInk"], trust["h2"]))
    assert clearance >= 20, (
        "the trust glyph's rendered ink clears the eyebrow text by only %.1fpx at %spx wide "
        "(pinned minimum: 20px) — measured live before the fix this was negative: glyph ink "
        "ran to y=%.1f while the eyebrow starts at y=%.1f" % (
            clearance, header["vw"], trust["glyphInk"]["bottom"], trust["eyebrow"]["top"]))

    await b.close()


async def check_token_page_hash_links(p, errors):
    """صفحه‌ی /t/<آدرس>: لینک‌های هش-تنها باید روی همین صفحه بمانند.

    دو باگِ واقعی، هر دو گزارشِ مالک (۱۳ و ۱۴ سپتامبر ۲۰۲۶):

    ۱) از لینکِ «Copy this check»، چهار لینکِ فوتر — Swap، Portfolio، Flow،
       FAQ — کاربر را به صفحه‌ی معرفی می‌بردند. علت یک عارضه‌ی <base> بود:
       صفحه‌ی توکن یک `<base href="/">` تزریق می‌کند تا باندل‌های نسبی حل
       شوند، و همان base هر `href="#x"` را هم «/#x» می‌کند.
    ۲) بعدِ رفعِ اول، یکی‌درمیان صفحه‌ی توکن از نو بار می‌شد: خودِ اپ وقتی از
       صفحه‌ی توکن بیرون می‌رود آدرس را با pushState عوض می‌کند، پس hrefی که
       به مسیرِ توکن قفل شده بود از کلیکِ بعدی یک ناوبریِ واقعی می‌شد.

    پس این پروب رفتارِ کلیک را می‌سنجد، نه فقط متنِ href: صفحه روی یک آدرسِ
    واقعیِ /t/ بالا می‌آید، هر چهار لینک کلیک می‌شوند، و هیچ‌کدام نباید یک
    بارگذاریِ تازه راه بیندازد یا pathname را عوض کند."""
    html = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
    addr = "0x" + "a" * 40
    origin = "https://zaexa.example"
    here = "/t/" + addr

    b = await p.chromium.launch()
    ctx = await b.new_context()
    pg = await ctx.new_page()
    loads = []
    pg.on("load", lambda _: loads.append(1))

    async def handler(route):
        path = route.request.url.split("?")[0][len(origin):]
        if path.startswith("/t/"):
            await route.fulfill(status=200, content_type="text/html; charset=utf-8", body=html)
        elif path.endswith(".js"):
            await route.fulfill(status=200, content_type="text/javascript", body="")
        else:
            await route.fulfill(status=404, body="")
    await ctx.route(origin + "/**", handler)
    await pg.goto(origin + here)
    await pg.wait_for_timeout(500)

    head = await pg.evaluate("""() => ({
        base: (document.querySelector('base') || {}).href || null,
        bundles: [...document.scripts].map(s => s.src).filter(Boolean),
        marked: [...document.querySelectorAll('a[data-hash-link]')]
            .map(a => a.getAttribute('data-hash-link')),
        placeholders: [...document.querySelectorAll('a')]
            .map(a => a.getAttribute('href'))
            .filter(h => h === '#').length,
    })""")
    assert head["base"] == origin + "/", (
        "the /t/ page no longer injects <base href=\"/\"> (got %r). Without it the relative "
        "bundles 404 and the page dies on 'Could not load ethers'." % head["base"])
    assert any(u.startswith(origin + "/ethers") for u in head["bundles"]), (
        "the ethers bundle no longer resolves to the site root on a /t/ page: %r"
        % head["bundles"])
    for frag in ("swap", "folio", "flow", "faq"):
        assert frag in head["marked"], (
            "the footer link #%s is not marked as an in-page hash link on /t/<address> "
            "(marked: %r). Unmarked, it inherits <base href=\"/\"> and walks the visitor out "
            "of the app onto the landing page." % (frag, head["marked"]))

    for frag in ("swap", "folio", "flow", "faq"):
        before = len(loads)
        await pg.click('a[data-hash-link="%s"]' % frag)
        await pg.wait_for_timeout(250)
        state = await pg.evaluate("() => [location.pathname, location.hash]")
        assert len(loads) == before, (
            "clicking the footer's #%s on /t/<address> triggered a full page load. That is the "
            "every-other-click bug: the app rewrites the URL with pushState when it leaves the "
            "token page, and a link pinned to the old path then navigates for real." % frag)
        assert state[0] == here, (
            "clicking #%s moved the path to %r; it must stay on the token's own page (%r). A "
            "path of '/' is the landing page." % (frag, state[0], here))
        assert state[1] == "#" + frag, (
            "clicking #%s left the hash at %r" % (frag, state[1]))

    await b.close()
    print("[token page links] /t/<address> keeps <base href=\"/\"> for the bundles; clicking "
          "#swap/#folio/#flow/#faq stays on the token's own path with no page load "
          "(%d placeholder '#' links left alone)" % head["placeholders"])


async def check_logo_parity(p, errors):
    """نشانِ برند باید در صفحه‌ی معرفی و اپ دقیقاً یک‌جا بنشیند.

    ۱۴ سپتامبر ۲۰۲۶، از روی یک ویدیوی ضبط‌شده‌ی مالک: لوگو موقعِ رفت‌وآمد بین
    دو صفحه می‌پرید و — حرفِ خودش — «مخاطب نباید فکر کند صفحه‌ها از هم جدا
    هستند». اندازه یکی بود (۳۸ در ۲۷)، جا نه: نوارِ بالای اپ ۷۲ پیکسل و
    فاصله‌ی کناری‌اش ۲۶ ثابت بود، در حالی که صفحه‌ی معرفی ۹۰ و
    clamp(20px,3.4vw,56px) داشت. یعنی تا ۳۰ پیکسل افقی و ۹ پیکسل عمودی پرش.
    ⚠️ جهتِ جورشدن یک بار عوض شد: اول اپ با صفحه‌ی معرفی جور شد، بعد مالک
    پشیمان شد و گفت اپ به حالتِ قبل برگردد و صفحه‌ی معرفی با اپ جور شود.
    همین حالتِ دوم است که اینجا قفل شده.

    ⚠️ یک باندِ باریک استثناست و عمداً در فهرستِ عرض‌ها نیست: بین ۹۰۰ و ۹۶۰
    پیکسل نشان یک پیکسل اختلاف دارد. دلیلش قابلِ رفع با این توکن‌ها نیست —
    بلوکِ برندِ اپ ۳۸ پیکسل خط‌بندی دارد و همان بلوک در صفحه‌ی معرفی ۲۷، پس
    وسط‌چین‌شدنشان در یک نوارِ هم‌ارتفاع یک پیکسل فرق می‌کند. بستنِ آن یعنی
    عوض‌کردنِ اندازه‌ی نوشتارِ برند در صفحه‌ی معرفی، که کسی نخواسته.

    این پروب همان چیزی را می‌سنجد که چشم می‌بیند — مختصاتِ واقعیِ نشان روی
    صفحه، نه متنِ CSS — و در چند عرض، چون اختلاف از یک clamp می‌آمد که فقط
    در بعضی عرض‌ها خودش را نشان می‌دهد. ⚠️ صفحه‌ی جفت‌ها عمداً بیرون است:
    نشانش کوچک‌تر است (۲۲ در ۱۵) و کسی نخواسته آن عوض شود."""
    landing = "file://" + os.path.join(os.path.dirname(HERE), "landing.html")
    app = "file://" + os.path.join(os.path.dirname(HERE), "index.html")
    js = """() => {
        const brand = document.querySelector('.brand') || document.querySelector('.logo');
        const mark = brand && brand.querySelector('.mark');
        if (!mark) return null;
        const b = mark.getBoundingClientRect();
        return [Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)];
    }"""
    b = await p.chromium.launch()
    seen = {}
    for w in (1920, 1440, 1024, 900, 760, 430):
        ctx = await b.new_context(viewport={"width": w, "height": 900})
        pg = await ctx.new_page()
        await ctx.add_init_script("localStorage.setItem('zaexa.theme.v1','dark');")
        got = {}
        for name, url in (("landing", landing), ("app", app)):
            await pg.goto(url)
            await pg.wait_for_timeout(250)
            got[name] = await pg.evaluate(js)
        await ctx.close()
        assert got["landing"] and got["app"], (
            "could not find the brand mark on one of the two pages at %dpx: %r" % (w, got))
        assert got["landing"] == got["app"], (
            "at %dpx the brand mark sits at %r on the landing page and %r in the app "
            "(x, y, width, height). It has to be the same rectangle on both, or the logo "
            "jumps as the visitor moves between them \u2014 which is what made it look like "
            "two separate sites." % (w, got["landing"], got["app"]))
        seen[w] = got["app"]
    await b.close()
    print("[logo parity] brand mark identical on the landing page and the app at %s: %s"
          % (", ".join("%dpx" % w for w in seen), seen[1440]))


async def check_canvas_palette_live(p, errors):
    """پروبِ ۵ (پویا): پالتِ زنده‌ی canvas بدونِ ریلود دنبالِ عوض‌شدنِ
    data-theme می‌رود.

    web/landing.html را با تمِ ذخیره‌شده‌ی "light" بار می‌کنیم، پالتی که
    اسکریپت واقعاً خواند (window.__zaexaViz — همان شیءِ viz که readViz
    داخلش می‌نویسد) را می‌سنجیم که ست روشن باشد، سپس data-theme را روی
    خودِ <html> به "dark" برمی‌گردانیم — دقیقاً همان کاری که MutationObserver
    باید ببیند — بدونِ هیچ reloadی، و دوباره همان شیء را می‌خوانیم که باید
    ست تیره شده باشد. اگر MutationObserver برداشته شود، پالت روی مقادیرِ
    روشنِ بارگذاریِ اول گیر می‌ماند و این پروب با پیام واضح FAIL می‌شود، نه
    کرش."""
    path = os.path.join(HERE, "..", "landing.html")
    idx_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
    new_key = theme_key_from_index(idx_src)

    b = await p.chromium.launch()
    ctx = await b.new_context()
    pg = await ctx.new_page()
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await ctx.add_init_script("localStorage.setItem(%r, 'light');" % new_key)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(400)

    assert await pg.query_selector("#routeCanvas") is not None, (
        "web/landing.html: #routeCanvas is missing right after load")

    light_live = await pg.evaluate("() => window.__zaexaViz ? {...window.__zaexaViz} : null")
    assert light_live, (
        "window.__zaexaViz is not exposed by the routeCanvas script — cannot verify the live "
        "palette without a reload (the script must expose the palette it resolved, or this "
        "probe has nothing to read)")
    # مقادیرِ انتظار از خودِ فایل خوانده می‌شوند، نه هاردکد: چیزی که این پروب
    # ثابت می‌کند این است که بوم *همان* توکن‌های تمِ روشن را می‌خواند، نه اینکه
    # آن توکن‌ها یک رنگِ بخصوص‌اند — درستیِ خودِ رنگ‌ها کارِ check_viz_contrast است.
    # عمداً: readViz حالا --hero1/--hero2 را می‌خواند، نه --viz1/--viz2
    # مستقیم — چون در تمِ روشن رنگِ canvas باید همان رنگِ حرفِ n در «can»
    # باشد (owner decision)، نه فیروزه‌ایِ viz1 قدیمی. --vizline دست‌نخورده
    # می‌ماند.
    light_decls_f = merged_root_decls(
        open(path, encoding="utf-8").read())
    want_light = {k: _expand_hex(resolve_css_var(light_decls_f, n)).lower()
                  for k, n in (("v1", "hero1"), ("v2", "hero2"), ("vl", "vizline"))}
    got_light = {k: light_live.get(k, "").lower() for k in want_light}
    assert got_light == want_light, (
        "on load with the light theme active, the canvas script resolved %r instead of the "
        "light --hero1/--hero2/--vizline set declared in landing.html (%r)" % (
            got_light, want_light))

    await pg.evaluate("() => { document.documentElement.dataset.theme = 'dark'; }")
    await pg.wait_for_timeout(200)
    dark_live = await pg.evaluate("() => ({...window.__zaexaViz})")
    assert (dark_live.get("v1", "").lower() == "#22eff6"
            and dark_live.get("v2", "").lower() == "#c56cf5"
            and dark_live.get("vl", "").lower() == "#667496"), (
        "flipping data-theme to 'dark' on the root element (no reload) left the canvas "
        "script's live palette at %r instead of the dark set (#22EFF6/#C56CF5/#667496) — is "
        "the MutationObserver on data-theme missing or not re-reading the tokens?" % dark_live)

    assert await pg.query_selector("#routeCanvas") is not None, (
        "#routeCanvas disappeared after the theme flip")

    await ctx.close()
    await b.close()
    print("[canvas palette live] light on load -> %s; flipped data-theme to dark without "
          "reload -> %s" % (light_live, dark_live))


_CANVAS_PHASE_ORDER = ["quote", "split", "simulate", "settle"]
_CANVAS_PHASE_TO_STEP = {"quote": "quote", "split": "quote", "simulate": "simulate", "settle": "settle"}


async def check_canvas_phases(p, errors):
    """پروبِ [canvas phases]: هر ۱۵۰ میلی‌ثانیه، برای ۱۰ ثانیه، فازِ زنده
    (window.__zaexaCanvasPhase) را نمونه‌برداری می‌کنیم. باید فقط به ترتیبِ
    چرخه‌ای quote→split→simulate→settle→quote... پیش برود (هیچ فازی نپرد)
    و در هر نمونه، اسپَنِ readout-right با کلاسِ on دقیقاً همان که نگاشتِ
    فاز می‌گوید باشد."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    pg = await b.new_page(viewport={"width": 1440, "height": 900})
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(300)

    samples = []
    for _ in range(67):  # ~10s / 150ms
        got = await pg.evaluate(
            "() => ({phase: window.__zaexaCanvasPhase, "
            "on: (document.querySelector('.readout-right .step.on')||{}).dataset && "
            "(document.querySelector('.readout-right .step.on')||{}).dataset.step})")
        samples.append(got)
        await pg.wait_for_timeout(150)
    await b.close()

    seen_phases = set()
    prev_idx = None
    for i, s in enumerate(samples):
        phase = s.get("phase")
        assert phase in _CANVAS_PHASE_ORDER, (
            "window.__zaexaCanvasPhase is %r at sample %d, not one of %s" % (phase, i, _CANVAS_PHASE_ORDER))
        seen_phases.add(phase)
        idx = _CANVAS_PHASE_ORDER.index(phase)
        if prev_idx is not None and idx != prev_idx:
            expected_next = (prev_idx + 1) % 4
            assert idx == expected_next, (
                "canvas phase jumped from %r to %r between consecutive 150ms samples (sample %d) "
                "— a phase was skipped instead of the cyclic quote→split→simulate"
                "→settle order" % (_CANVAS_PHASE_ORDER[prev_idx], phase, i))
        prev_idx = idx
        want_step = _CANVAS_PHASE_TO_STEP[phase]
        assert s.get("on") == want_step, (
            "at sample %d the canvas phase is %r but the readout-right span with class 'on' has "
            "data-step=%r, expected %r" % (i, phase, s.get("on"), want_step))
    missing = set(_CANVAS_PHASE_ORDER) - seen_phases
    assert not missing, (
        "10s of sampling at 150ms never visited phase(s) %s — each phase must be long enough "
        "to be observed" % sorted(missing))
    print("[canvas phases] %d samples over ~10s visited all 4 phases in cyclic order, "
          "readout 'on' span matched the mapping every time" % len(samples))


async def check_canvas_cost(p, errors):
    """پروبِ [canvas cost]: بعد از ۳ ثانیه اجرا، میانگینِ هزینه‌ی رسمِ هر
    فریم (window.__zaexaCanvasCost، محاسبه‌شده با performance.now داخلِ
    draw) باید زیرِ ۴ میلی‌ثانیه بماند."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    pg = await b.new_page(viewport={"width": 1440, "height": 900})
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(3000)
    cost = await pg.evaluate("() => window.__zaexaCanvasCost")
    await b.close()
    assert isinstance(cost, (int, float)) and cost == cost, (
        "window.__zaexaCanvasCost is not a number after 3s: %r" % (cost,))
    assert cost < 4, (
        "the routeCanvas rolling average draw cost is %.3fms after 3s — must stay under 4ms" % cost)
    print("[canvas cost] rolling average draw cost after 3s: %.3fms" % cost)


async def check_canvas_reduced_motion(p, errors):
    """پروبِ [canvas reduced motion]: با prefers-reduced-motion:reduce،
    هیچ requestAnimationFrameِ مربوط به canvas (پشته‌اش شاملِ draw یا frame
    باشد) نباید صدا زده شود، و بومِ کشیده‌شده هم نباید کاملاً خالی/شفاف
    بماند."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    ctx = await b.new_context(reduced_motion="reduce", viewport={"width": 1440, "height": 900})
    await ctx.add_init_script("""
      window.__rafCanvasCalls = 0;
      const orig = window.requestAnimationFrame.bind(window);
      window.requestAnimationFrame = function(cb) {
        const stack = (new Error()).stack || '';
        const cbName = (cb && cb.name) || '';
        if (/\\bdraw\\b/.test(stack) || /\\bframe\\b/.test(stack)
            || /^(draw|frame)$/.test(cbName)) { window.__rafCanvasCalls++; }
        return orig(cb);
      };
    """)
    pg = await ctx.new_page()
    errs = []
    pg.on("console", lambda m: errs.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(1200)

    raf_calls = await pg.evaluate("() => window.__rafCanvasCalls")
    non_blank = await pg.evaluate("""
      () => {
        const c = document.getElementById('routeCanvas');
        const ctx = c.getContext('2d');
        const data = ctx.getImageData(0, 0, c.width, c.height).data;
        for (let i = 3; i < data.length; i += 4) { if (data[i] > 0) return true; }
        return false;
      }
    """)
    await ctx.close()
    await b.close()
    for e in errs:
        errors.append(e)
    assert raf_calls == 0, (
        "with prefers-reduced-motion:reduce, %d requestAnimationFrame call(s) from the canvas "
        "script's draw/frame functions were made — the reduced-motion path must never call "
        "requestAnimationFrame" % raf_calls)
    assert non_blank, (
        "with prefers-reduced-motion:reduce, #routeCanvas is fully transparent — the static "
        "frame must still draw the split-phase illustration")
    print("[canvas reduced motion] 0 requestAnimationFrame calls from draw/frame, canvas has "
          "non-transparent pixels")


async def check_canvas_labels(p, errors):
    """پروبِ [canvas labels]: در ۱۴۴۰/۱۰۲۴/۷۶۸/۳۷۵ هیچ دو جعبه‌ی برچسبی
    هم‌پوشانی ندارند و همه داخلِ خودِ canvas می‌مانند."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    # ۲۳ سپتامبر: گوشیِ واقعیِ مالک ~۳۹۳px بود و برچسب‌ها زیرِ کادرها می‌رفتند؛
    # عرض‌های رایجِ گوشی هم سنجیده می‌شوند.
    for width in (1440, 1024, 768, 430, 412, 393, 375, 360):
        pg = await b.new_page(viewport={"width": width, "height": 900})
        pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        await pg.goto("file://" + path)
        await pg.wait_for_timeout(300)
        info = await pg.evaluate("""
          () => {
            const c = document.getElementById('routeCanvas');
            const r = c.getBoundingClientRect();
            return {labels: window.__zaexaCanvasLabels || [], w: r.width, h: r.height,
                    avoid: window.__zaexaCanvasAvoid || null};
          }
        """)
        await pg.close()
        labels = info["labels"]
        if width <= 480:
            # ۲۴ اکتبر: روی گوشی برچسب‌ها پنهان‌اند و فقط گره‌ها می‌مانند
            assert labels == [], "labels must be hidden at %dpx, got %r" % (width, labels)
            continue
        assert labels, "window.__zaexaCanvasLabels is empty at %dpx" % width
        cw, ch = info["w"], info["h"]
        for i, box in enumerate(labels):
            assert box["x"] >= -0.5 and box["y"] >= -0.5 and box["x"] + box["w"] <= cw + 0.5 \
                and box["y"] + box["h"] <= ch + 0.5, (
                "label box %d %r falls outside the %dpx canvas (%.1fx%.1f) at %dpx width"
                % (i, box, width, cw, ch, width))
        for i in range(len(labels)):
            for j in range(i + 1, len(labels)):
                a, bx = labels[i], labels[j]
                overlap = (a["x"] < bx["x"] + bx["w"] and a["x"] + a["w"] > bx["x"]
                           and a["y"] < bx["y"] + bx["h"] and a["y"] + a["h"] > bx["y"])
                assert not overlap, (
                    "label boxes %d %r and %d %r overlap at %dpx width" % (i, a, j, bx, width))
        # کادرهای readoutِ DOM روی canvas: هیچ برچسبی نباید زیرشان برود
        # (۲۳ سپتامبر: «ALIENBASE» زیرِ کادرِ ROUTE ENGINE بریده می‌شد).
        avoid = info["avoid"]
        assert avoid, "window.__zaexaCanvasAvoid is missing at %dpx" % width
        for i, a in enumerate(labels):
            for r in avoid:
                hit = (a["x"] < r["x"] + r["w"] and a["x"] + a["w"] > r["x"]
                       and a["y"] < r["y"] + r["h"] and a["y"] + a["h"] > r["y"])
                assert not hit, (
                    "label box %d %r sits under a readout box %r at %dpx width" % (i, a, r, width))
        print("[canvas labels] %dpx: %d label boxes, none overlapping, all inside the canvas, "
              "clear of %d readout boxes" % (width, len(labels), len(avoid)))
    await b.close()


_HUB_NAMES = ["Uniswap", "Aerodrome", "PancakeSwap", "SushiSwap", "BaseSwap"]
_HUB_PAIRS = [(0, 2), (1, 3), (2, 4), (3, 0), (4, 1)]


async def check_hero_hub(p, errors):
    """[hero hub] — مرکزِ هیرو: فقط نشانِ رسمی روی var(--bg)، بدونِ هیچ حلقه/گرادیان؛
    پنج گرهِ DEX رویِ مدارها با برچسبِ بی‌هم‌پوشانی (در گوشی پنهان)، و نقطه‌ی مسیرِ
    A→مرکز→B با ترتیبِ ثابتِ جفت‌ها. در reduced-motion هیچ‌چیز حرکت نمی‌کند."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    # رنگ‌های tokenِ تم را از خودِ مرورگر به rgb تبدیل می‌کنیم (نه حدس)
    JS_COL = """v => { const d = document.createElement('div'); d.style.color = 'var(' + v + ')';
        document.body.appendChild(d); const c = getComputedStyle(d).color; d.remove(); return c; }"""
    JS_STATE = """() => {
      const r = e => { const k = e.getBoundingClientRect(); return {x:k.x,y:k.y,w:k.width,h:k.height}; };
      const hv = document.querySelector('.hero-visual'), cv = document.getElementById('routeCanvas');
      const core = document.querySelector('.visual-core'), mark = core.querySelector('.core-mark');
      const word = core.querySelector('.core-word');
      const R = window.__zaexaCanvasRoutePts || {};
      const cr = cv.getBoundingClientRect();
      const nodes = [...document.querySelectorAll('.hero-visual .hub-node')].map(g => {
        const c = g.querySelector('circle'), t = g.querySelector('text'), pl = g.querySelector('.hub-pill'), cs = getComputedStyle(c), ts = getComputedStyle(t);
        return {circle:r(c), label:r(pl), text:t.textContent, textBox:r(t), pillFill:getComputedStyle(pl).fill, on:g.classList.contains('on'),
                stroke:cs.stroke, fill:cs.fill, sw:cs.strokeWidth, fs:ts.fontSize, tfill:ts.fill, tdisp:ts.display, vis:ts.visibility};
      });
      const dot = document.getElementById('hubDot'), route = document.getElementById('hubRoute');
      const kids = [core, ...core.querySelectorAll('*')].map(e => {
        const s = getComputedStyle(e), bw = ['Top','Right','Bottom','Left'].map(k => parseFloat(s['border'+k+'Width'])*(s['border'+k+'Style']!=='none'?1:0));
        const bef = getComputedStyle(e, '::before'), aft = getComputedStyle(e, '::after');
        return {tag:e.tagName+'.'+(e.getAttribute('class')||''), bgi:s.backgroundImage, bw:Math.max(...bw), br:s.borderRadius,
                bs:s.boxShadow, filter:s.filter, stroke:s.stroke, bef:bef.content, aft:aft.content};
      });
      return {mark:r(mark), word:r(word), core:r(core), canvas:{x:cr.x,y:cr.y}, R:R, nodes:nodes, kids:kids,
              readouts:[...document.querySelectorAll('.hero-visual .visual-readout')].map(r),
              hv:r(hv), dot:r(dot), dotOp:getComputedStyle(dot).opacity, dotDisp:getComputedStyle(dot).display,
              dotFill:getComputedStyle(dot).fill, dotStroke:getComputedStyle(dot).stroke,
              route:route ? {op:+getComputedStyle(route).opacity, disp:getComputedStyle(route).display, sw:getComputedStyle(route).strokeWidth, stroke:getComputedStyle(route).stroke} : null,
              markOp:getComputedStyle(mark).opacity, viz:{...window.__zaexaViz},
              rings:document.querySelectorAll('.hero-visual .core-dial,.hero-visual .core-rim,.hero-visual .core-inner,.hero-visual .core-satellite,.hero-visual linearGradient,#coreRim').length,
              bg:getComputedStyle(document.body).backgroundColor, coreBg:getComputedStyle(core).backgroundColor,
              cv1:getComputedStyle(document.documentElement).getPropertyValue('--viz1').trim(),
              cv2:getComputedStyle(document.documentElement).getPropertyValue('--viz2').trim()};
    }"""
    def hit(a, c):
        return a["x"] < c["x"] + c["w"] and a["x"] + a["w"] > c["x"] and a["y"] < c["y"] + c["h"] and a["y"] + a["h"] > c["y"]
    summary = []
    for (vw, vh, core_size, word_w) in ((1440, 900, 145, 57.6), (1280, 800, 145, 57.6), (1024, 768, 145, 57.6),
                                        (768, 1024, 145, 57.6), (390, 844, 96, 37.8)):
        for theme in (("light", "dark") if vw in (1440, 390) else ("light",)):
            tag = "%dpx %s" % (vw, theme)
            ctx = await b.new_context(reduced_motion="no-preference", viewport={"width": vw, "height": vh})
            pg = await ctx.new_page()
            pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
            await pg.goto("file://" + path)
            await pg.evaluate("t => { document.documentElement.dataset.theme = t; }", theme)
            await pg.wait_for_timeout(700)
            cols = {k: await pg.evaluate(JS_COL, k) for k in ("--card", "--line2", "--tx2", "--tx3", "--hero1", "--bg")}
            worst_dx = 0.0
            # چند نمونه در طولِ ~۳ ثانیه: برچسب‌ها پویا جا می‌گیرند و مدارها می‌چرخند
            for sample in range(8):
                m = await pg.evaluate(JS_STATE)
                R = m["R"]
                assert R.get("cx") is not None, "[hero hub] window.__zaexaCanvasRoutePts is missing at %s" % tag
                mk = m["mark"]
                dx = mk["x"] + mk["w"] / 2 - (m["canvas"]["x"] + R["cx"])
                dy = mk["y"] + mk["h"] / 2 - (m["canvas"]["y"] + R["cy"])
                worst_dx = max(worst_dx, abs(dx), abs(dy))
                assert abs(dx) <= 1 and abs(dy) <= 1, (
                    "[hero hub] mark centre is off the orbits' centre at %s: dx=%.2f dy=%.2f" % (tag, dx, dy))
                if sample == 0:
                    c, sm = m["core"], m["word"]
                    assert m["rings"] == 0, "[hero hub] an old ring/gradient element is back in the hero centre at %s" % tag
                    assert m["coreBg"] in ("rgba(0, 0, 0, 0)", "transparent"), (
                        "[hero hub] hero centre has a backing colour %s (must be transparent) at %s" % (m["coreBg"], tag))
                    for k in m["kids"]:
                        assert k["bgi"] == "none", "[hero hub] %s inside the hero centre has background-image %s at %s" % (k["tag"], k["bgi"], tag)
                        assert k["bw"] == 0, "[hero hub] %s inside the hero centre has a visible border at %s" % (k["tag"], tag)
                        assert "50%" not in k["br"], "[hero hub] %s inside the hero centre has border-radius %s (ring) at %s" % (k["tag"], k["br"], tag)
                        assert k["bs"] == "none" and k["filter"] == "none", (
                            "[hero hub] %s inside the hero centre has shadow/filter (glow) at %s" % (k["tag"], tag))
                        assert "url(" not in k["stroke"], "[hero hub] %s strokes with a gradient/url at %s" % (k["tag"], tag)
                        assert k["bef"] in ("none", "normal") and k["aft"] in ("none", "normal"), (
                            "[hero hub] %s inside the hero centre has a pseudo-element at %s" % (k["tag"], tag))
                    assert abs(c["w"] - core_size) < 0.01 and abs(c["h"] - core_size) < 0.01, (
                        "[hero hub] hero centre size changed at %s: %.2fx%.2f, expected %d" % (tag, c["w"], c["h"], core_size))
                    assert abs(sm["w"] - word_w) < 0.01, "[hero hub] ZAEXA label width at %s is %.2f, expected %g" % (tag, sm["w"], word_w)
                    gap = sm["y"] - (mk["y"] + mk["h"])
                    want_gap = 6 if vw > 480 else 4
                    assert abs(gap - want_gap) <= 0.5, "[hero hub] gap between mark and ZAEXA label is %.2fpx, expected %d at %s" % (gap, want_gap, tag)
                    ratio = sm["w"] / mk["w"]
                    assert 0.88 <= ratio <= 0.92, "[hero hub] ZAEXA width / mark width is %.3f, expected 0.88..0.92 at %s" % (ratio, tag)
                    assert abs((sm["x"] + sm["w"] / 2) - (mk["x"] + mk["w"] / 2)) <= 0.6, "[hero hub] ZAEXA label is not centred under the mark at %s" % tag
                    assert m["route"] is not None, "[hero hub] the route line #hubRoute is missing at %s" % tag
                    assert m["route"]["sw"] == "1.5px" and m["route"]["stroke"] == cols["--hero1"], "[hero hub] route line style is %r at %s" % (m["route"], tag)
                    assert m["dotFill"] == cols["--hero1"] and m["dotStroke"] == cols["--bg"], "[hero hub] dot fill/ring is %s/%s at %s" % (m["dotFill"], m["dotStroke"], tag)
                    v = m["viz"]
                    if theme == "light":
                        assert v["v1"].lower() == "#3f7cf2" and v["v2"].lower() == "#7a5af0" and abs(v["oa"] - 0.65) < 1e-9, (
                            "[hero hub] light live palette is %r at %s" % (v, tag))
                    else:
                        assert v["v1"].lower() == m["cv1"].lower() and v["v2"].lower() == m["cv2"].lower() and abs(v["oa"] - 0.52) < 1e-9, (
                            "[hero hub] dark live palette is %r at %s" % (v, tag))
                nodes = m["nodes"]
                assert len(nodes) == 5, "[hero hub] expected exactly 5 DEX nodes, found %d at %s" % (len(nodes), tag)
                assert [n["text"] for n in nodes] == _HUB_NAMES, "[hero hub] node labels are %r at %s" % ([n["text"] for n in nodes], tag)
                for i, n in enumerate(nodes):
                    cr_ = n["circle"]
                    assert abs(cr_["w"] - 9) < 0.01 and abs(cr_["h"] - 9) < 0.01, "[hero hub] node %d is %.2fx%.2f, expected 9px at %s" % (i, cr_["w"], cr_["h"], tag)
                    assert n["fill"] == cols["--card"] and n["sw"] == "1.5px", "[hero hub] node %d fill/stroke-width is %s/%s at %s" % (i, n["fill"], n["sw"], tag)
                    assert n["stroke"] == (cols["--hero1"] if n["on"] else cols["--line2"]), (
                        "[hero hub] node %d stroke is %s (active=%s) at %s" % (i, n["stroke"], n["on"], tag))
                    assert n["fs"] == "11px" and n["tfill"] == (cols["--tx2"] if n["on"] else cols["--tx3"]), (
                        "[hero hub] label %d is %s %s (active=%s; idle var(--tx3), active var(--tx2)) at %s" % (i, n["fs"], n["tfill"], n["on"], tag))
                    if vw > 480 and n["vis"] != "hidden":
                        assert n["pillFill"] == cols["--bg"], "[hero hub] label %d has no var(--bg) background pill (fill %s) at %s" % (i, n["pillFill"], tag)
                        tb_, pl_ = n["textBox"], n["label"]
                        assert pl_["x"] <= tb_["x"] + 0.5 and pl_["x"] + pl_["w"] >= tb_["x"] + tb_["w"] - 0.5 and pl_["y"] <= tb_["y"] + 0.5 and pl_["y"] + pl_["h"] >= tb_["y"] + tb_["h"] - 0.5, (
                            "[hero hub] label %d text is not inside its background pill at %s" % (i, tag))
                    # گره دقیقاً رویِ بیضیِ مدارِ خودش (قابِ چرخان) و نزدیکِ موقعیتِ اعلام‌شده
                    pt, orb = R["pts"][i], R["orbits"][n_orbit(R, i)]
                    ex, ey = pt["x"] - R["cx"], pt["y"] - R["cy"]
                    cs_, sn_ = math.cos(orb["rot"]), math.sin(orb["rot"])
                    u, w_ = ex * cs_ + ey * sn_, -ex * sn_ + ey * cs_
                    val = (u / orb["rx"]) ** 2 + (w_ / orb["ry"]) ** 2
                    assert 0.99 <= val <= 1.01, "[hero hub] node %d is off its orbit ellipse (term %.4f) at %s" % (i, val, tag)
                    gx = cr_["x"] + cr_["w"] / 2 - (m["canvas"]["x"] + pt["x"])
                    gy = cr_["y"] + cr_["h"] / 2 - (m["canvas"]["y"] + pt["y"])
                    assert abs(gx) <= 1.5 and abs(gy) <= 1.5, "[hero hub] node %d DOM position differs from its orbit position by %.1f,%.1f at %s" % (i, gx, gy, tag)
                    assert cr_["x"] >= m["hv"]["x"] and cr_["x"] + 9 <= m["hv"]["x"] + m["hv"]["w"], "[hero hub] node %d leaves the hero at %s" % (i, tag)
                if vw > 480:
                    # برچسبی که جای آزاد ندارد (گره زیرِ readout) پنهان می‌شود؛ حداقل ۳ برچسب باید دیده شوند
                    labs = [n["label"] if n["vis"] != "hidden" else {"x": -9e9, "y": -9e9, "w": 0, "h": 0} for n in nodes]
                    assert sum(1 for n in nodes if n["vis"] != "hidden") >= 3, "[hero hub] fewer than 3 labels visible at %s" % tag
                    for i in range(5):
                        if nodes[i]["vis"] == "hidden": continue
                        assert labs[i]["w"] > 0, "[hero hub] label %d has no box at %s" % (i, tag)
                        assert labs[i]["x"] >= m["hv"]["x"] and labs[i]["x"] + labs[i]["w"] <= m["hv"]["x"] + m["hv"]["w"], "[hero hub] label %d leaves the hero at %s" % (i, tag)
                        for j in range(i + 1, 5):
                            assert not hit(labs[i], labs[j]), "[hero hub] labels %d and %d overlap at %s" % (i, j, tag)
                        for k, ro in enumerate(m["readouts"]):
                            assert not hit(labs[i], ro), "[hero hub] label %d overlaps readout %d at %s" % (i, k, tag)
                        assert not hit(labs[i], m["mark"]) and not hit(labs[i], m["word"]), "[hero hub] label %d overlaps the mark at %s" % (i, tag)
                else:
                    for i, n in enumerate(nodes):
                        assert n["tdisp"] == "none" or n["label"]["w"] == 0, "[hero hub] label %d is visible at %s (hidden below 480px)" % (i, tag)
                await pg.wait_for_timeout(400)
            if vw == 1440 and theme == "light":
                # ترتیبِ جفت‌ها + حرکتِ نقطه، در یک پنجره‌ی ~۱۰ ثانیه‌ای
                seq, dots, routes = [], [], []
                for _ in range(100):
                    st = await pg.evaluate("""() => ({on:[...document.querySelectorAll('.hub-node')].map((g,i)=>g.classList.contains('on')?i:-1).filter(i=>i>=0),
                        dot:(()=>{const k=document.getElementById('hubDot').getBoundingClientRect();return [k.x,k.y,+getComputedStyle(document.getElementById('hubDot')).opacity,k.width]})(),
                        route:+getComputedStyle(document.getElementById('hubRoute')).opacity})""")
                    if len(st["on"]) == 2:
                        pr = tuple(sorted(st["on"]))
                        if not seq or seq[-1] != pr: seq.append(pr)
                    if st["dot"][2] > 0:
                        dots.append(st["dot"][:2])
                        assert abs(st["dot"][3] - 7) < 0.1, "[hero hub] the dot is %.2fpx wide, expected 7px" % st["dot"][3]
                    routes.append(st["route"])
                    await pg.wait_for_timeout(100)
                want_sorted = [tuple(sorted(q)) for q in _HUB_PAIRS]
                assert len(seq) >= 3, "[hero hub] saw only %d active pair(s) in 10s: %r" % (len(seq), seq)
                k0 = want_sorted.index(seq[0]) if seq[0] in want_sorted else None
                assert k0 is not None, "[hero hub] unknown active pair %r" % (seq[0],)
                for j, pr in enumerate(seq):
                    assert pr == want_sorted[(k0 + j) % 5], (
                        "[hero hub] active pairs went %r; expected the fixed order %r (0,2)(1,3)(2,4)(3,0)(4,1)" % (seq, _HUB_PAIRS))
                assert max(routes) >= 0.5 and min(routes) == 0, "[hero hub] route line opacity over a cycle is %.2f..%.2f; expected up to ~0.55 mid-cycle and 0 between cycles" % (min(routes), max(routes))
                span = max(max(d[0] for d in dots) - min(d[0] for d in dots), max(d[1] for d in dots) - min(d[1] for d in dots)) if dots else 0
                assert span > 20, "[hero hub] with normal motion the dot never moved (span %.1fpx)" % span
                summary.append("pairs %s, dot span %.0fpx" % ("->".join("%d%d" % q for q in seq), span))
            await ctx.close()
            summary.append("%s mark off by <=%.2fpx" % (tag, worst_dx))
    # (a) هر سه مدار هم‌سرعت و هم‌جهت‌اند: همان .00006 rad/ms کامیتِ 1916a01 (دو نمونه به فاصله‌ی ۱ ثانیه)
    pg = await b.new_page(viewport={"width": 1440, "height": 900})
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(600)
    rots0 = await pg.evaluate("() => window.__zaexaCanvasRoutePts.orbits.map(o => o.rot)")
    await pg.wait_for_timeout(1000)
    rots1 = await pg.evaluate("() => window.__zaexaCanvasRoutePts.orbits.map(o => o.rot)")
    ow = await pg.evaluate("() => window.__zaexaOrbitW")
    await pg.close()
    dl = [r1 - r0 for r0, r1 in zip(rots0, rots1)]
    assert ow == [0.00006, 0.00006, 0.00006], "[hero hub] every orbit must turn at 1916a01's .00006 rad/ms in the same direction: %r" % ow
    assert len(dl) == 3 and all(0.04 <= d <= 0.08 for d in dl), "[hero hub] orbit speeds are %r rad/s, expected all ~0.06 and the same direction (1916a01)" % dl
    assert max(dl) - min(dl) < 0.01, "[hero hub] orbits do not turn at one rate: %r" % dl
    # کوچک‌ترین مدار (نزدیکِ لوگو) رنگِ --hero2 دارد و دو مدارِ بیرونی --hero1؛ در هر دو تم و بعد از تعویضِ زنده
    pg = await b.new_page(viewport={"width": 1440, "height": 900}, reduced_motion="no-preference")
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.evaluate("() => { document.documentElement.dataset.theme = 'light'; }")
    await pg.wait_for_timeout(700)
    for step in range(3):
        if step:
            await pg.click("#themeToggle")
            await pg.wait_for_timeout(700)
        oc = await pg.evaluate("""() => { const parse = c => c.match(/[\\d.]+/g).map(Number);
            const col = v => { const d = document.createElement('div'); d.style.color = 'var(' + v + ')'; document.body.appendChild(d); const c = getComputedStyle(d).color; d.remove(); return parse(c).slice(0, 3); };
            const O = window.__zaexaCanvasRoutePts.orbits;
            return {theme: document.documentElement.dataset.theme || 'light', h1: col('--hero1'), h2: col('--hero2'), rx: O.map(o => o.rx), st: O.map(o => parse(o.stroke)), oa: window.__zaexaViz.oa}; }""")
        inner = min(range(3), key=lambda k: oc["rx"][k])
        outer = [k for k in range(3) if k != inner]
        assert oc["st"][inner][:3] == oc["h2"] and all(oc["st"][k][:3] == oc["h1"] for k in outer) and oc["h1"] != oc["h2"], \
            "[hero hub] the inner orbit must stroke with --hero2 and the two outer ones with --hero1 (%s): %r" % (oc["theme"], oc)
        assert all(abs(oc["st"][k][3] - oc["oa"]) < 0.005 for k in range(3)) and oc["oa"] > 0, "[hero hub] orbit alpha differs from the live orbit opacity (%s): %r" % (oc["theme"], oc["st"])
    await pg.close()
    # (b) عرضِ لوگوتایپ ۰٫۹ عرضِ نشان در ۱۴۴۰ و ۳۹۰ و (c) بدونِ مربعِ پشتِ نشان بعد از هر تعویضِ تم
    # (d) هیچ عنصر/rect پشتِ نشان پر یا پس‌زمینه‌ی غیرشفاف ندارد
    import io
    from PIL import Image
    for vw, vh in ((1440, 900), (390, 844)):
        ctx = await b.new_context(reduced_motion="no-preference", viewport={"width": vw, "height": vh})
        pg = await ctx.new_page()
        pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        await pg.goto("file://" + path)
        await pg.evaluate("() => { document.documentElement.dataset.theme = 'light'; }")
        await pg.wait_for_timeout(700)
        dims = await pg.evaluate("""() => { const m = document.querySelector('.visual-core .core-mark').getBoundingClientRect(),
            w = document.querySelector('.visual-core .core-word').getBoundingClientRect(); return [m.width, w.width]; }""")
        assert 0.88 <= dims[1] / dims[0] <= 0.92, "[hero hub] wordmark/mark width %.3f at %dpx" % (dims[1] / dims[0], vw)
        for step in range(2):
            await pg.click("#themeToggle")
            await pg.wait_for_timeout(700)
            theme = await pg.evaluate("() => document.documentElement.dataset.theme || 'light'")
            await pg.evaluate("() => document.querySelector('.visual-core').scrollIntoView({block: 'center'})")
            await pg.wait_for_timeout(300)
            behind = await pg.evaluate("""() => {
              const mk = document.querySelector('.visual-core .core-mark').getBoundingClientRect();
              const cx = mk.x + mk.width / 2, cy = mk.y + mk.height / 2, out = [];
              const clear = c => !c || c === 'transparent' || /rgba\(\s*\d+,\s*\d+,\s*\d+,\s*0\s*\)/.test(c);
              for (const el of document.elementsFromPoint(cx, cy)) {
                if (el === document.body || el === document.documentElement || el.id === 'landingParticles' || el.classList.contains('hero-visual') ) continue;
                if (el.closest('.hero-visual') === null) continue;
                const s = getComputedStyle(el);
                if (el.tagName === 'use' || el.closest('.core-mark')) { continue; }
                if (!clear(s.backgroundColor) || s.backgroundImage !== 'none')
                  out.push(el.tagName + '.' + el.className + ' bg=' + s.backgroundColor);
                if (el.tagName.toLowerCase() === 'rect' && s.fill !== 'none' && !clear(s.fill)) out.push('rect fill ' + s.fill);
              }
              for (const r of document.querySelectorAll('.visual-core rect, .visual-core img, .visual-core canvas'))
                out.push('backing node ' + r.tagName);
              const bg = getComputedStyle(document.body).backgroundColor;
              return {out, bg, box: [mk.x, mk.y, mk.width, mk.height]};
            }""")
            assert not behind["out"], "[hero hub] something non-transparent sits behind the mark at %dpx %s: %r" % (vw, theme, behind["out"])
            # نشان و لوگوتایپ را نامرئی می‌کنیم تا جوهرِ خودِ نشان در گوشه‌ها پیکسلِ بدلی نسازد؛ مربعِ پشتش می‌ماند
            # ۲۵ اکتبر: مدارها و خطِ مسیرِ متحرک هم پنهان می‌شوند (زیرِ بارِ سوییتِ کامل گاهی از گوشه رد می‌شدند و پیکسلِ فیروزه‌ای
            # را «مربع» می‌خواندیم)؛ خودِ مرکز و نیاکانش دیده می‌مانند، پس هر پس‌زمینه‌ی واقعی پشتِ نشان هنوز گرفته می‌شود.
            HIDE = """(on) => { const sel = '.visual-core svg, #landingParticles';
              for (const e of document.querySelectorAll(sel)) e.style.visibility = on ? 'hidden' : '';
              for (const e of document.querySelectorAll('.hero-visual *')) {
                if (e.closest('.visual-core') || e.querySelector('.visual-core')) continue;
                e.style.visibility = on ? 'hidden' : ''; } }"""
            await pg.evaluate(HIDE, True)
            png = await pg.screenshot()
            await pg.evaluate(HIDE, False)
            im = Image.open(io.BytesIO(png)).convert("RGB")
            bgc = [int(v) for v in re.findall(r"\d+", behind["bg"])[:3]]
            x, y, bw, bh = behind["box"]
            for (px, py) in ((x + 2, y + 2), (x + bw - 3, y + 2), (x + 2, y + bh - 3), (x + bw - 3, y + bh - 3)):
                got = im.getpixel((int(px), int(py)))
                assert all(abs(got[k] - bgc[k]) <= 3 for k in range(3)), (
                    "[hero hub] a square shows behind the mark after toggling to %s at %dpx: pixel (%d,%d)=%r, page bg %r"
                    % (theme, vw, px, py, got, bgc))
        await ctx.close()
    # reduced-motion: نه نقطه، نه پالس، گره‌ها ثابت
    for (vw, vh) in ((1440, 900), (390, 844)):
        ctx = await b.new_context(reduced_motion="reduce", viewport={"width": vw, "height": vh})
        pg = await ctx.new_page()
        pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        await pg.goto("file://" + path)
        await pg.wait_for_timeout(600)
        a = await pg.evaluate(JS_STATE)
        await pg.wait_for_timeout(700)
        c2 = await pg.evaluate(JS_STATE)
        await ctx.close()
        assert a["dot"] == c2["dot"], "[hero hub] reduced motion: the dot moved %r -> %r at %dpx" % (a["dot"], c2["dot"], vw)
        assert a["dotDisp"] == "none" or a["dotOp"] == "0", "[hero hub] reduced motion: the dot is visible at %dpx" % vw
        assert [n["circle"] for n in a["nodes"]] == [n["circle"] for n in c2["nodes"]], "[hero hub] reduced motion: nodes moved at %dpx" % vw
        assert not any(n["on"] for n in a["nodes"] + c2["nodes"]), "[hero hub] reduced motion: a node is marked active at %dpx" % vw
        assert a["route"] is not None and (a["route"]["disp"] == "none" or a["route"]["op"] == 0) and (c2["route"]["disp"] == "none" or c2["route"]["op"] == 0), (
            "[hero hub] reduced motion: the route line is visible at %dpx: %r" % (vw, a["route"]))
        assert a["markOp"] == "1" and c2["markOp"] == "1", "[hero hub] reduced motion: the mark pulsed at %dpx" % vw
    await b.close()
    print("[hero hub] 1440/1280/1024/768/390 (light, +dark at 1440 and 390): %s; 5 nodes on orbits, labels clear at 1440 / hidden at 390; "
          "no ring/gradient/glow in the centre; reduced motion keeps dot and nodes still" % "; ".join(summary))


def n_orbit(R, i):
    return R["pts"][i]["o"]


async def check_canvas_route_on_ellipse(p, errors):
    """پروبِ [canvas on ellipse]: صاحبِ‌کار گفت مسیرها در فازهای split و
    simulate از داخلِ حلقه‌های سیگنال رد می‌شوند و بی‌نظم به نظر می‌رسند.
    قاعده‌ی تازه این است که هر مسیر/کمان/ذره/دنباله‌ای که کشیده می‌شود
    دقیقاً رویِ بیضیِ venue بنشیند. در ۱۴۴۰x۹۰۰، هر ۱۰۰ میلی‌ثانیه برای
    ۱۰ ثانیه window.__zaexaCanvasRoutePts را می‌خوانیم و هر نقطه را با
    معادله‌ی بیضی می‌سنجیم (۰.۹۶ تا ۱.۰۴، برای رواداریِ اعشاری) و مطمئن
    می‌شویم هیچ نقطه‌ای به فاصله‌ی کمتر از coreR+4 از مرکز نیفتاده باشد."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    pg = await b.new_page(viewport={"width": 1440, "height": 900})
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(300)

    total = 0
    for i in range(100):  # ~10s / 100ms
        info = await pg.evaluate("() => window.__zaexaCanvasRoutePts || null")
        if info and info.get("pts"):
            # ۲۴ اکتبر: مرکزِ هیرو فقط پنج گرهِ DEX است و هر گره رویِ بیضیِ مدارِ خودش (قابِ چرخان)؛
            # هر کمان، ذره یا ردی که برگردد تعداد را بالا می‌برد و این‌جا قرمز می‌شود.
            assert len(info["pts"]) == 5, (
                "sample %d carries %d drawn points in phase %r; only the 5 DEX nodes may be drawn"
                % (i, len(info["pts"]), await pg.evaluate("() => window.__zaexaCanvasPhase")))
            cx, cy, core_r = info["cx"], info["cy"], info["coreR"]
            for j, pt in enumerate(info["pts"]):
                dx, dy = pt["x"] - cx, pt["y"] - cy
                orb = info["orbits"][pt["o"]]
                u = dx * math.cos(orb["rot"]) + dy * math.sin(orb["rot"])
                v = -dx * math.sin(orb["rot"]) + dy * math.cos(orb["rot"])
                val = (u / orb["rx"]) ** 2 + (v / orb["ry"]) ** 2
                assert 0.99 <= val <= 1.01, (
                    "sample %d point %d %r is off its orbit ellipse (term = %.4f, want 0.99..1.01) — "
                    "cx=%.1f cy=%.1f orbit %r" % (i, j, pt, val, cx, cy, orb))
                dist = (dx * dx + dy * dy) ** 0.5
                assert dist >= core_r + 4, (
                    "sample %d point %d %r is only %.1fpx from the centre, inside coreR+4 "
                    "(coreR=%.1f) — a route must never cross over the core ring/logo"
                    % (i, j, pt, dist, core_r))
                total += 1
        await pg.wait_for_timeout(100)
    await b.close()
    assert total > 0, (
        "window.__zaexaCanvasRoutePts never carried any points over ~10s of sampling — "
        "the canvas script must expose the sampled points of every route/lane/particle/trail "
        "it draws")
    print("[canvas on ellipse] %d node positions checked over ~10s, all on their orbit ellipses and clear "
          "of the centre mark" % total)


async def check_trust_glyph_in_circle(p, errors):
    """[trust glyph in circle] — ۲۳ سپتامبر: روی گوشیِ مالک علامتِ «?» بخشِ اعتماد
    از دایره‌ی کوچکش بیرون می‌زد (دایره ۵۲px، فونت ۷۵px). جوهرِ «?» (با Range) باید
    در هر عرض داخلِ کادرِ .trust-signal بماند."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    for width in (1440, 768, 430, 393, 360):
        pg = await b.new_page(viewport={"width": width, "height": 900})
        pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        await pg.goto("file://" + path)
        await pg.wait_for_timeout(300)
        r = await pg.evaluate("""() => {
            const s = document.querySelector('.trust-signal');
            const c = s.getBoundingClientRect();
            const rg = document.createRange(); rg.selectNodeContents(s);
            const g = rg.getBoundingClientRect();
            return {c: [c.left, c.top, c.right, c.bottom], g: [g.left, g.top, g.right, g.bottom]};
        }""")
        await pg.close()
        c, g = r["c"], r["g"]
        assert g[0] >= c[0] - 1 and g[1] >= c[1] - 1 and g[2] <= c[2] + 1 and g[3] <= c[3] + 1, (
            "[trust glyph in circle] at %dpx the '?' box %r leaves its circle %r" % (width, g, c))
    await b.close()
    print("[trust glyph in circle] the '?' stays inside its circle at 1440/768/430/393/360px")


async def check_canvas_resize(p, errors):
    """[canvas resize] — ۲۳ سپتامبر: کوچک و دوباره بزرگ‌کردنِ پنجره بوم را از قابش
    بلندتر می‌کرد (ارتفاع از نسبتِ width/height‌ِ خودِ بوم می‌آمد) و مرکزِ رسم از
    لوگوی وسط جدا می‌افتاد. بعد از هر تغییرِ اندازه، بوم باید دقیقاً هم‌اندازه‌ی
    .hero-visual باشد و مرکزِ رسم (window.__zaexaCanvasRoutePts) روی مرکزِ .visual-core."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    pg = await b.new_page(viewport={"width": 1900, "height": 1000})
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    await pg.goto("file://" + path)
    await pg.wait_for_timeout(600)
    for (w, h) in [(1150, 1000), (1900, 1000), (800, 1000), (1440, 900), (393, 851), (1900, 1000)]:
        await pg.set_viewport_size({"width": w, "height": h})
        await pg.wait_for_timeout(500)
        # ۲۴ سپتامبر: مرکزِ رسم فقط در فریمِ بعدیِ انیمیشن به‌روز می‌شود؛ زیرِ بار، ۵۰۰ms
        # گاهی کم بود و کاوشگر با مختصاتِ فریمِ قبلی می‌لرزید (۲ از ۳ اجرا). تا ۳ ثانیه برای
        # همان شرط صبر می‌کنیم — آستانه و ادعا دست نخورده‌اند.
        try:
            await pg.wait_for_function("""() => {
                const c = document.getElementById('routeCanvas').getBoundingClientRect();
                const k = document.querySelector('.visual-core').getBoundingClientRect();
                const R = window.__zaexaCanvasRoutePts || {};
                return R.cx != null && Math.abs(R.cx - (k.x + k.width / 2 - c.x)) <= 2
                    && Math.abs(R.cy - (k.y + k.height / 2 - c.y)) <= 2;
            }""", timeout=3000)
        except Exception:
            pass  # ادعای پایین همان شکست را با عدد گزارش می‌کند
        r = await pg.evaluate("""() => {
            const c = document.getElementById('routeCanvas').getBoundingClientRect();
            const v = document.querySelector('.hero-visual').getBoundingClientRect();
            const k = document.querySelector('.visual-core').getBoundingClientRect();
            const R = window.__zaexaCanvasRoutePts || {};
            return {c: [c.width, c.height], v: [v.width, v.height],
                    core: [k.x + k.width / 2 - c.x, k.y + k.height / 2 - c.y], draw: [R.cx, R.cy]};
        }""")
        assert abs(r["c"][0] - r["v"][0]) <= 1 and abs(r["c"][1] - r["v"][1]) <= 1, (
            "[canvas resize] at %dx%d the canvas is %r but its frame is %r" % (w, h, r["c"], r["v"]))
        assert r["draw"][0] is not None and abs(r["draw"][0] - r["core"][0]) <= 2 and abs(r["draw"][1] - r["core"][1]) <= 2, (
            "[canvas resize] at %dx%d the drawing centre %r is off the logo centre %r" % (w, h, r["draw"], r["core"]))
    await b.close()
    print("[canvas resize] after 6 window resizes (1900->1150->1900->800->1440->393->1900) the canvas "
          "matches its frame and the drawing stays centred on the logo")


async def check_logo_hit_area(p, errors):
    """[logo hit area] — ۲۳ سپتامبر: روی گوشیِ مالک، لمسِ لوگو در اپ کادرِ آبیِ لمس را سه
    برابرِ خودِ نشان نشان می‌داد (لینک کلِ ستونِ گرید را پر می‌کرد). کادرِ لینکِ لوگو باید
    در هر سه صفحه و هر عرض فقط به اندازه‌ی جوهرِ نشان و نوشتارِ دیدنی باشد (±۴px)."""
    b = await p.chromium.launch()
    for name, sel in (("index.html", ".logo"), ("pairs.html", ".logo"), ("landing.html", ".landing-header .brand")):
        for width in (360, 390, 768, 1440):
            pg = await b.new_page(viewport={"width": width, "height": 800})
            # بدونِ شنونده‌ی کنسول: pairs.html روی file:// نمی‌تواند /pairs.json را بخواند و این
            # کاوشگر فقط هندسه‌ی هدر را می‌سنجد (کاوشگرهای pairs آن را با سرورِ محلی باز می‌کنند).
            await pg.goto("file://" + os.path.join(HERE, "..", name))
            await pg.wait_for_timeout(250)
            r = await pg.evaluate("""s => {
                const e = document.querySelector(s); const box = e.getBoundingClientRect();
                const ink = [...e.querySelectorAll('svg')].map(x => x.getBoundingClientRect()).filter(x => x.width > 0);
                return {left: box.left, right: box.right, inkLeft: Math.min(...ink.map(k => k.left)), inkRight: Math.max(...ink.map(k => k.right))};
            }""", sel)
            await pg.close()
            assert abs(r["left"] - r["inkLeft"]) <= 4 and abs(r["right"] - r["inkRight"]) <= 4, (
                "[logo hit area] %s@%dpx: the logo link spans %.0f..%.0f but its ink is %.0f..%.0f"
                % (name, width, r["left"], r["right"], r["inkLeft"], r["inkRight"]))
    await b.close()
    print("[logo hit area] the logo link hugs its ink on app, pairs and landing at 360/390/768/1440px")


async def check_nav_chevron_mobile(p, errors):
    """[nav chevron mobile] — ۱۸ اکتبر: «Markets» دیگر بازشو نیست و شورون ندارد؛ روی نوارِ موبایل باید دقیقاً مثلِ
    بقیه‌ی تب‌ها باشد (آیکون بالا، برچسب زیرش، هر دو وسط‌چین، هم‌قد و هم‌پهنای Stocks). قبلاً شورونِ ۹ تا ۱۱ پیکسلی
    و باز/بسته‌شدنش سنجیده می‌شد؛ آن بخش‌ها عمداً حذف شد چون شورون و منو دیگر وجود ندارند."""
    b = await p.chromium.launch()
    js = """() => {
        const r = e => e.getBoundingClientRect();
        const btn = document.querySelector('.nav .navMarkets');
        const sib = document.querySelector('.nav [title="Stocks"]');
        const lab = btn.querySelector('span'), ico = btn.querySelector('svg');
        return {chev: !!btn.querySelector('.navChev') || !!document.querySelector('.navChev'), kids: btn.children.length, disp: getComputedStyle(btn).display,
                btn: r(btn), sib: r(sib), lab: r(lab), ico: r(ico), haspopup: btn.getAttribute('aria-haspopup'), expanded: btn.getAttribute('aria-expanded')};
    }"""
    n = 0
    for name in ("index.html", "pairs.html"):
        for (w, h) in ((360, 780), (390, 844), (430, 932)):
            for theme in ("light", "dark"):
                pg = await b.new_page(viewport={"width": w, "height": h})
                await pg.goto("file://" + os.path.join(HERE, "..", name))
                await pg.wait_for_timeout(250)
                await pg.evaluate("t => { document.documentElement.dataset.theme = t; }", theme)
                await pg.wait_for_timeout(150)
                m = await pg.evaluate(js)
                tag = "%s@%dx%d/%s" % (name, w, h, theme)
                assert not m["chev"], "[nav chevron mobile] %s: a chevron is still in the DOM" % tag
                assert m["kids"] == 2, "[nav chevron mobile] %s: Markets button has %d children, expected icon + label" % (tag, m["kids"])
                assert m["haspopup"] is None and m["expanded"] is None, "[nav chevron mobile] %s: Markets still carries menu aria attributes" % tag
                assert m["disp"] == "flex", "[nav chevron mobile] %s: Markets display is %s, expected flex like the other tabs" % (tag, m["disp"])
                icx = m["ico"]["x"] + m["ico"]["width"] / 2
                lcx = m["lab"]["x"] + m["lab"]["width"] / 2
                bcx = m["btn"]["x"] + m["btn"]["width"] / 2
                assert abs(icx - bcx) <= 1.5 and abs(lcx - bcx) <= 1.5, (
                    "[nav chevron mobile] %s: icon centre %.1f / label centre %.1f vs button centre %.1f" % (tag, icx, lcx, bcx))
                assert m["lab"]["y"] >= m["ico"]["y"] + m["ico"]["height"] - 0.5, "[nav chevron mobile] %s: label is not below the icon" % tag
                assert abs(m["btn"]["height"] - m["sib"]["height"]) <= 1 and abs(m["btn"]["width"] - m["sib"]["width"]) <= 1.5, (
                    "[nav chevron mobile] %s: Markets %.1fx%.1f vs Stocks %.1fx%.1f" % (tag, m["btn"]["width"], m["btn"]["height"], m["sib"]["width"], m["sib"]["height"]))
                await pg.close()
                n += 1
        pg = await b.new_page(viewport={"width": 1280, "height": 800})
        await pg.goto("file://" + os.path.join(HERE, "..", name))
        await pg.wait_for_timeout(250)
        m = await pg.evaluate(js)
        assert not m["chev"] and m["kids"] == 2, "[nav chevron mobile] %s desktop: chevron present or extra children" % name
        assert m["lab"]["x"] >= m["ico"]["x"] + m["ico"]["width"] - 0.5, "[nav chevron mobile] %s desktop: label not to the right of the icon" % name
        await pg.close()
    await b.close()
    print("[nav chevron mobile] no chevron; Markets is built and sized like Stocks on the phone bar of app and pairs (%d phone combos); desktop label sits right of the icon" % n)


async def check_landing_no_ambient_glow(p, errors):
    """Ambient radial halos are removed; orbit rendering has its own checks."""
    b = await p.chromium.launch()
    try:
        pg = await b.new_page(viewport={"width":390,"height":844})
        await pg.goto("file://" + os.path.join(HERE, "..", "landing.html"))
        for theme in ("light", "dark"):
            await pg.evaluate("theme => document.documentElement.dataset.theme=theme", theme)
            state = await pg.evaluate("""() => ({
                layers: document.querySelectorAll('.page-glow,.glow-blob').length,
                hero: getComputedStyle(document.querySelector('.hero-visual'),'::before').content,
                trust: getComputedStyle(document.querySelector('.trust-art')).backgroundImage,
                overlay: getComputedStyle(document.body,'::after').content
            })""")
            assert state["layers"] == 0, state
            assert state["hero"] in ("none", "normal"), state
            assert state["trust"] == "none", state
            assert state["overlay"] in ("none", "normal"), state
    finally:
        await b.close()
    print("[landing background] no ambient radial halos or grain overlay in either theme")


async def check_landing_menu(p, errors):
    """[landing menu fits] و [landing menu cta text] — ۷ اکتبر: منوی موبایلِ landing با max-height:320px
    دکمه‌ی «Open the app» را می‌برید، و قاعده‌ی .mobile-menu a روی .button-primary غالب می‌شد و متنِ
    دکمه‌ی گرادیانی خاکستری/کمرنگ می‌شد."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    rows = []
    for theme, want in (("light", "rgb(255, 255, 255)"), ("dark", "rgb(5, 18, 26)")):
        ctx = await b.new_context(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
        pg = await ctx.new_page()
        await pg.goto("file://" + path)
        await pg.wait_for_timeout(300)
        await pg.evaluate("t => { document.documentElement.dataset.theme = t; }", theme)
        await pg.wait_for_timeout(150)
        await pg.click("#menuToggle")
        await pg.wait_for_timeout(450)
        m = await pg.evaluate("""() => {
            const menu = document.getElementById('mobileMenu'), cta = menu.querySelector('a.button-primary');
            const hero = document.querySelector('.hero .button-primary');
            return {menuBottom: menu.getBoundingClientRect().bottom, ctaBottom: cta.getBoundingClientRect().bottom,
                    sh: menu.scrollHeight, ch: menu.clientHeight,
                    ctaColor: getComputedStyle(cta).color, heroColor: getComputedStyle(hero).color};
        }""")
        await ctx.close()
        assert m["ctaBottom"] <= m["menuBottom"] - 8, (
            "[landing menu fits] %s: CTA bottom %.1f is not 8px above menu bottom %.1f (button clipped)" % (theme, m["ctaBottom"], m["menuBottom"]))
        assert m["sh"] <= m["ch"] + 1, "[landing menu fits] %s: menu scrollHeight %s > clientHeight %s" % (theme, m["sh"], m["ch"])
        assert m["ctaColor"] == want, "[landing menu cta text] %s: CTA colour %s, expected %s" % (theme, m["ctaColor"], want)
        assert m["ctaColor"] == m["heroColor"], "[landing menu cta text] %s: CTA colour %s != hero button %s" % (theme, m["ctaColor"], m["heroColor"])
        rows.append("%s cta=%s" % (theme, m["ctaColor"]))
    await b.close()
    print("[landing menu fits] open menu holds the whole CTA at 390x844 in light and dark")
    print("[landing menu cta text] CTA text matches the hero button (%s)" % "; ".join(rows))


async def check_hero_desktop_mode(p, errors):
    """[hero desktop-mode] — ۷ اکتبر: گوشی در حالتِ «سایتِ دسکتاپ» (~۹۸۰×۲۰۰۰) هیرو را ۱۹۰۰px
    می‌کرد و انیمیشن وسطِ فضای خالی شناور بود؛ min-height حالا با max(680px,62.5vw) سقف دارد."""
    path = os.path.join(HERE, "..", "landing.html")
    b = await p.chromium.launch()
    out = {}
    for (w, h) in ((980, 2000), (1440, 900), (1920, 1080)):
        pg = await b.new_page(viewport={"width": w, "height": h})
        await pg.goto("file://" + path)
        await pg.wait_for_timeout(300)
        out[(w, h)] = await pg.evaluate("""() => { const r = e => e.getBoundingClientRect();
            const hero = document.querySelector('.hero'), v = hero.querySelector('.hero-visual');
            return {h: r(hero).height, mh: parseFloat(getComputedStyle(hero).minHeight), hero: r(hero), vis: r(v)}; }""")
        await pg.close()
    await b.close()
    d = out[(980, 2000)]
    assert d["h"] <= 1000, "[hero desktop-mode] hero is %.0fpx tall at 980x2000 (cap is 1000)" % d["h"]
    hr, vr = d["hero"], d["vis"]
    assert (vr["x"] >= hr["x"] - 0.5 and vr["y"] >= hr["y"] - 0.5 and vr["x"] + vr["width"] <= hr["x"] + hr["width"] + 0.5
            and vr["y"] + vr["height"] <= hr["y"] + hr["height"] + 0.5), (
        "[hero desktop-mode] hero visual %s is not inside the hero %s at 980x2000" % (vr, hr))
    # در این دو اندازه ارتفاعِ واقعیِ هیرو را محتوا تعیین می‌کند (padding + ستون‌ها) نه min-height؛ پس خودِ
    # min-height محاسبه‌شده باید همان 100vh-90 بماند (۸۱۰ و ۹۹۰) — یعنی سقفِ تازه آن‌جا اثری ندارد.
    assert abs(out[(1440, 900)]["mh"] - 810) <= 1, "[hero desktop-mode] hero min-height %.1f at 1440x900, expected 810" % out[(1440, 900)]["mh"]
    assert abs(out[(1920, 1080)]["mh"] - 990) <= 1, "[hero desktop-mode] hero min-height %.1f at 1920x1080, expected 990" % out[(1920, 1080)]["mh"]
    print("[hero desktop-mode] hero %.0fpx at 980x2000 (visual inside), min-height 810 at 1440x900, 990 at 1920x1080" % d["h"])


async def check_live_strip(p, errors):
    """نوارِ «فعالیتِ زنده» زیرِ کارتِ سواپ روی /app — فقط نمای swap.

    داده فقط از همان /pairs.json?chain=… (هم‌مبدأ)؛ اینجا با page.route استاب می‌شود و فیکسچرها
    شکلِ واقعیِ پاسخِ زنده را دارند (rows تازه‌ترین-اول، v = sell|nosell|null، why برای null).
    قاعده‌ی ثابتِ مالک: سولانا هرگز حالتِ fail نشان نمی‌دهد."""
    import functools, http.server, threading, json as _j
    from datetime import datetime, timedelta, timezone

    class Quiet(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def translate_path(self, path):
            clean = path.split("?")[0]
            if clean in ("/app", "/app/"):
                return os.path.join(HERE, "harness.html")
            if re.match(r"^/t/(0x[0-9a-fA-F]{40}|[1-9A-HJ-NP-Za-km-z]{32,44})/?$", clean):
                return os.path.join(HERE, "harness.html")
            if clean == "/stub-ethers.js":
                return os.path.join(HERE, "stub-ethers.js")
            return super().translate_path(path)

    srv = http.server.ThreadingHTTPServer(
        ("127.0.0.1", 0), functools.partial(Quiet, directory=os.path.join(HERE, "..")))
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    port = srv.server_address[1]
    origin = "http://127.0.0.1:%d" % port
    b = await p.chromium.launch()

    def iso(sec_ago):
        t = datetime.now(timezone.utc) - timedelta(seconds=sec_ago)
        return t.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (t.microsecond // 1000)

    def row(chain, addr, symbol, v, why, ago, name="ZZNAME"):
        return {"chain": chain, "address": addr, "symbol": symbol, "name": name, "v": v,
                "checkKind": "roundtrip", "checkedAt": iso(ago), "poolCreatedAt": iso(ago + 60),
                "priceUsd": 0.000012177989966011157, "reserveUsd": 21069.2534, "vol24hUsd": 1723.47,
                "fdvUsd": 12143.31939, "dex": "meteora-damm-v2", "why": why}

    def evm(i):
        return "0x" + ("%x" % i) * 40 if i < 16 else "0x" + "%040x" % i

    A_TRUMP = "0x41c9" + "0" * 32 + "a134"
    A_IMG = "0x7777777777777777777777777777777777777777"
    sol = lambda i: "S" + "ABCDEFGHJKLMN"[i] + "X" + "A" * 41

    base_rows = [
        row("base", evm(1), "PEPE", "sell", None, 125),
        row("base", A_TRUMP, "Trump Moron Cake", "nosell", None, 300),
        row("base", evm(2), "SKIPME", None, "no-quote", 400),
        row("base", A_IMG, "<img src=x onerror=1>", "sell", None, 600),
        row("solana", sol(1), "WRONGCHAIN", "sell", None, 650),
    ] + [row("base", evm(i), "T%d" % i, "sell", None, 700 + i * 60) for i in range(4, 12)] + [
        row("base", evm(3), "OLDIE", "sell", None, 25 * 3600),
    ]
    BASE_NAMES = ["PEPE", "0x41c9…a134", "0x7777…7777", "T4", "T5", "T6", "T7", "T8"]
    # 12 ردیفِ base در ۲۴ ساعت: ۱+۱+۱+۱ + ۸ ؛ ردیفِ زنجیره‌ی دیگر و ردیفِ ۲۵ ساعته نباید شمرده شوند
    BASE_COUNT = "12 checked in 24h"

    sol_rows = [
        row("solana", sol(1), "WIF", "sell", None, 100),
        row("solana", sol(2), "NOSELLY", "nosell", "x", 200),
        row("solana", sol(3), "UNCONF", None, "sol:unconfirmed", 300),
        row("solana", sol(4), "HIDDEN", None, "sells:recent", 350),
        row("solana", sol(5), "SKIP429", None, "jup:swap-instructions:429", 380),
    ] + [row("solana", sol(i), "S%d" % i, "sell", None, 400 + i * 60) for i in range(6, 12)]
    SOL_COUNT = "11 checked in 24h"

    SKIP_HOSTS = ("127.0.0.1",)

    async def open_page(path="/app", chains=None, viewport=None, scheme="light", abort=False,
                        status=200, raw=None, init=None, calls=None, errs=None):
        chains = chains if chains is not None else {"base": base_rows, "solana": sol_rows}
        pg = await b.new_page(viewport=viewport or {"width": 1440, "height": 900}, color_scheme=scheme)
        if errs is not None:
            def on_msg(m):
                if m.type == "error" and (m.location.get("url") or "").startswith(origin):
                    errs.append(m.text)
            pg.on("console", on_msg)
            pg.on("pageerror", lambda e: errs.append("PAGEERROR " + str(e)))
        await pg.add_init_script("""(()=>{const si=window.setInterval,ci=window.clearInterval;window.__iv=new Set();
            window.setInterval=function(f,d,...a){const id=si.call(window,f,d,...a);if(d===4000)window.__iv.add(id);return id;};
            window.clearInterval=function(id){window.__iv.delete(id);return ci.call(window,id);};})();""")
        if init:
            await pg.add_init_script(init)

        async def external(route):
            await route.abort()

        async def empty(route):
            await route.fulfill(status=200, content_type="application/json", body='{"data":[]}')

        async def ok204(route):
            await route.fulfill(status=204, body="")

        async def vd(route):
            await route.fulfill(status=200, content_type="application/json", body='{"v":"sell","ms":100}')

        async def solstub(route):
            await route.fulfill(status=200, content_type="application/json", body='{"result":null}')

        async def pairs(route):
            ch = "solana" if "chain=solana" in route.request.url else "base"
            if calls is not None:
                calls.append(ch)
            if abort:
                await route.abort()
                return
            if raw is not None:
                await route.fulfill(status=status, content_type="application/json", body=raw)
                return
            await route.fulfill(status=status, content_type="application/json",
                                body=_j.dumps({"chain": ch, "rows": chains.get(ch, []), "store": True}))
        await pg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(origin) else external(r))
        await pg.route("**/gt/**", empty)
        await pg.route("**/ev", ok204)
        await pg.route("**/vd/**", vd)
        await pg.route("**/sol/**", solstub)
        await pg.route("**/pairs.json**", pairs)
        await pg.goto(origin + path)
        await pg.wait_for_timeout(700)
        return pg

    INFO = """() => { const s = document.getElementById('liveStrip'), a = s.querySelector('.lsItem'), st = a.querySelector('.state');
        return {hidden: s.hidden, display: getComputedStyle(s).display, text: a.textContent,
                name: (a.querySelector('b') || {}).textContent, href: a.getAttribute('href'),
                state: st ? st.className : null, count: s.querySelector('.lsCount').textContent,
                imgs: s.querySelectorAll('img').length, scripts: s.querySelectorAll('script').length,
                nameLeak: s.textContent.includes('ZZNAME')}; }"""
    CYCLE = """(n) => { const a = document.querySelector('#liveStrip .lsItem'), out = [];
        const probe = document.createElement('span'); probe.style.color = 'var(--warn)'; document.body.appendChild(probe);
        const warn = getComputedStyle(probe).color; probe.remove();
        for (let i = 0; i < n; i++) { const st = a.querySelector('.state');
            out.push({name: a.querySelector('b').textContent, text: a.textContent, href: a.getAttribute('href'),
                      state: st.className, color: getComputedStyle(st).color, warn});
            liveStripTick(); }
        return out; }"""

    # ---- 1) Base ----
    errs1 = []
    pg = await open_page(errs=errs1)
    i1 = await pg.evaluate(INFO)
    cyc = await pg.evaluate(CYCLE, 17)
    await pg.close()
    names = [c["name"] for c in cyc]
    print("[live strip base] visible=%s first=%r state=%r href=%s count=%r cycle=%s imgs=%d nameLeak=%s"
          % (not i1["hidden"], i1["text"], i1["state"], i1["href"], i1["count"], names[:9],
             i1["imgs"], i1["nameLeak"]))
    assert not i1["hidden"] and i1["display"] != "none", "the live strip is not shown on Base with live-shaped rows: %s" % i1
    assert i1["text"] == "PEPE · 2m ago · ✓ sell-back passed", "first item text: %r" % i1["text"]
    assert i1["state"] == "state pass", "first item state class: %r" % i1["state"]
    assert i1["href"] == "/t/" + evm(1), "first item href: %r" % i1["href"]
    assert i1["count"] == BASE_COUNT, "counter text: %r (want %r)" % (i1["count"], BASE_COUNT)
    assert names[:8] == BASE_NAMES, (
        "rotation order/labels wrong (symbol regex, short address, 24h cut, wrong-chain, null skip): %s" % names[:8])
    assert names[8] == BASE_NAMES[0] and names[16] == BASE_NAMES[0], "rotation must cycle over exactly 8 items: %s" % names
    assert cyc[1]["text"].endswith("✕ sell-back failed") and cyc[1]["state"] == "state fail", "Base nosell must show the fail state: %s" % cyc[1]
    assert i1["imgs"] == 0 and i1["scripts"] == 0, "a symbol with markup injected an element into the strip"
    assert not i1["nameLeak"] and not any("SKIPME" in c["text"] or "OLDIE" in c["text"] or "WRONGCHAIN" in c["text"] for c in cyc), (
        "the strip rendered `name`, a skipped null row, a >24h row or another chain's row")
    assert not errs1, "console errors on the Base live strip page: %s" % errs1

    # ---- 2) Solana: هرگز fail ----
    errs2 = []
    pg = await open_page("/app#swap?chain=solana", errs=errs2)
    i2 = await pg.evaluate(INFO)
    cyc = await pg.evaluate(CYCLE, 17)
    await pg.close()
    texts = [c["text"] for c in cyc]
    print("[live strip solana] visible=%s first=%r count=%r cycle=%s failedAnywhere=%s"
          % (not i2["hidden"], i2["text"], i2["count"], [c["name"] for c in cyc[:9]],
             any("failed" in t or "fail" in c["state"] for t, c in zip(texts, cyc))))
    assert not i2["hidden"] and i2["text"] == "WIF · 1m ago · ✓ sell-back passed", "Solana first item: %s" % i2
    assert i2["count"] == SOL_COUNT, "Solana counter: %r" % i2["count"]
    assert not any("failed" in t or "✕" in t for t in texts), "Solana rendered a sell-back failed item: %s" % texts
    assert not any("fail" in c["state"] for c in cyc), "Solana got a fail state class: %s" % cyc
    assert [c["name"] for c in cyc[:8]] == ["WIF", "NOSELLY", "UNCONF", "S6", "S7", "S8", "S9", "S10"], (
        "Solana rotation labels: %s" % [c["name"] for c in cyc[:8]])
    unc = [c for c in cyc[:8] if c["name"] in ("NOSELLY", "UNCONF")]
    assert len(unc) == 2 and all(c["text"].endswith("! unconfirmed") and c["state"] == "state unconfirmed"
                                 and c["color"] == c["warn"] for c in unc), "unconfirmed must render amber: %s" % unc
    assert not any(c["name"] in ("HIDDEN", "SKIP429") for c in cyc), "a sells:recent / other-null Solana row was shown"
    assert not errs2, "console errors on the Solana live strip page: %s" % errs2

    # ---- 3) خالی / خطا / store:false -> کاملاً پنهان ----
    hid = {}
    for label, kw in (("empty", dict(chains={"base": []})), ("abort", dict(abort=True)),
                      ("store-false", dict(raw='{"chain":"base","rows":[],"store":false}')),
                      ("store-false-with-rows", dict(raw=_j.dumps({"chain": "base", "rows": base_rows, "store": False}))),
                      ("http-500", dict(status=500, raw="{}")),
                      ("only-skippable", dict(chains={"base": [row("base", evm(2), "X", None, "no-quote", 60)]}))):
        e = []
        pg = await open_page(errs=e, **kw)
        info = await pg.evaluate(INFO)
        iv = await pg.evaluate("() => window.__iv.size")
        await pg.close()
        hid[label] = (info["hidden"], info["display"], iv, [x for x in e if "pairs.json" not in x and "ERR_" not in x and "status of 500" not in x])
    print("[live strip hidden] %s" % hid)
    for label, (h, d, iv, e) in hid.items():
        assert h and d == "none", "live strip must be fully hidden for %s (hidden=%s display=%s)" % (label, h, d)
        assert iv == 0, "no rotation timer may run while the strip is hidden (%s: %d)" % (label, iv)
        assert not e, "console errors for %s: %s" % (label, e)

    # ---- 4) جای نوار ----
    GEO = """(solana) => { const r = e => e ? e.getBoundingClientRect() : null;
        const s = document.getElementById('liveStrip');
        const card = solana ? document.getElementById('solSwap') : document.querySelector('#baseHeroRow section.card.swapCard');
        const chart = document.querySelector(solana ? '#appSolHero .swapChartCard' : '#baseHeroRow .swapChartCard');
        const S = r(s), C = r(card), H = r(chart);
        return {sTop: S.top, sBottom: S.bottom, sLeft: S.left, sW: S.width, sH: S.height, cBottom: C.bottom, cLeft: C.left, cW: C.width,
                chartTop: H.top, chartBottom: H.bottom, sibling: card.nextElementSibling === s, hidden: s.hidden,
                overflowX: document.documentElement.scrollWidth > innerWidth}; }"""
    geo = {}
    for vw in (1440, 390):
        for chain in ("base", "solana"):
            e = []
            pg = await open_page("/app" + ("#swap?chain=solana" if chain == "solana" else ""),
                                 viewport={"width": vw, "height": 900}, errs=e)
            # ۱۸ اکتبر [mobile compact]: روی گوشی فقط کارتِ تبِ انتخاب‌شده دیده می‌شود، و توکنِ پیش‌فرضِ هارنس
            # (استاب) یافته‌ی critical دارد و تبِ Exit check را خودکار انتخاب می‌کند؛ این کاوشگر موقعیتِ
            # کارتِ نمودار را می‌سنجد، پس تبِ Chart را صریحاً انتخاب می‌کند.
            await pg.evaluate("mtabSelect('chart', false)")
            g = await pg.evaluate(GEO, chain == "solana")
            geo[(vw, chain)] = g
            assert not e, "console errors in geometry probe %s/%s: %s" % (vw, chain, e)
            await pg.close()
    print("[live strip geometry] %s" % {"%d-%s" % k: (round(v["sTop"] - v["cBottom"], 1), round(v["sW"] - v["cW"], 1),
                                                     round(v["sH"]), v["sibling"]) for k, v in geo.items()})
    for (vw, chain), g in geo.items():
        tag = "%d/%s" % (vw, chain)
        assert not g["hidden"], "%s: strip hidden" % tag
        assert g["sTop"] >= g["cBottom"] - 0.5, "%s: strip is not below the swap card (strip top %.1f, card bottom %.1f)" % (tag, g["sTop"], g["cBottom"])
        assert g["sTop"] - g["cBottom"] <= 20, "%s: gap between swap card and strip is %.1f" % (tag, g["sTop"] - g["cBottom"])
        assert abs(g["sLeft"] - g["cLeft"]) <= 1 and abs(g["sW"] - g["cW"]) <= 1, "%s: strip left/width differ from the swap card: %s" % (tag, g)
        assert g["sibling"], "%s: the strip is not the next sibling of the active swap card" % tag
        assert abs(g["sH"] - 42) <= 1, "%s: strip height %.1f, want 42" % (tag, g["sH"])
        assert not g["overflowX"], "%s: horizontal page scroll" % tag
        if vw == 390:
            assert g["sBottom"] <= g["chartTop"] + 0.5, "%s: on mobile the strip must come before the chart card (strip bottom %.1f, chart top %.1f)" % (tag, g["sBottom"], g["chartTop"])

    # صفحه‌ی توکن و نماهای دیگر: پنهان، بی‌تایمر، بی‌درخواست
    calls_t = []
    pg = await open_page("/t/" + evm(1), calls=calls_t)
    tinfo = await pg.evaluate(INFO)
    tiv = await pg.evaluate("() => window.__iv.size")
    await pg.close()
    calls_v = []
    pg = await open_page(calls=calls_v)
    shown = (await pg.evaluate(INFO))["hidden"]
    await pg.evaluate("() => { location.hash = 'folio'; }")
    await pg.wait_for_timeout(400)
    vinfo = await pg.evaluate(INFO)
    viv = await pg.evaluate("() => window.__iv.size")
    await pg.evaluate("() => { location.hash = 'swap'; }")
    await pg.wait_for_timeout(500)
    back = await pg.evaluate(INFO)
    await pg.close()
    print("[live strip views] token page hidden=%s timers=%d requests=%s; folio hidden=%s timers=%d; back on swap hidden=%s"
          % (tinfo["hidden"], tiv, calls_t, vinfo["hidden"], viv, back["hidden"]))
    assert tinfo["hidden"] and tinfo["display"] == "none" and tiv == 0 and not calls_t, (
        "the strip must be hidden, timer-less and request-less on a /t/<address> page: %s %s %s" % (tinfo, tiv, calls_t))
    assert not shown and vinfo["hidden"] and viv == 0, "leaving the swap view must hide the strip and stop its timer: %s %s" % (vinfo, viv)
    assert not back["hidden"] and back["text"].startswith("PEPE"), "returning to the swap view must bring the strip back: %s" % back

    # ---- 5) تلگرام ----
    pg = await open_page()
    tg = await pg.evaluate("""() => { const a = document.querySelector('#liveStrip .lsTg');
        return {href: a.getAttribute('href'), target: a.target, rel: a.rel, label: a.getAttribute('aria-label'), title: a.title, span: a.querySelector('span').textContent,
                d: a.querySelector('svg path').getAttribute('d'), foot: document.querySelector('#lnkTg svg path').getAttribute('d')}; }""")
    await pg.close()
    print("[live strip telegram] href=%s target=%s rel=%s sameIconAsFooter=%s title=%r span=%r" % (tg["href"], tg["target"], tg["rel"], tg["d"] == tg["foot"], tg["title"], tg["span"]))
    assert tg["title"] == "Daily Exit Report and updates on our Telegram channel" and tg["span"] == "Daily report", tg
    assert tg["href"] == app_telegram_link(), "the strip's Telegram button must use LINKS.telegram (%r), got %r" % (app_telegram_link(), tg["href"])
    assert tg["target"] == "_blank" and "noopener" in tg["rel"] and tg["label"] == "Zaexa on Telegram", tg
    assert tg["d"] == tg["foot"], "the Telegram icon path differs from the footer's #lnkTg"

    # ---- 6) فقط یک interval، یک قدم در هر تیک، توقف روی hover/focus، کش ----
    calls6 = []
    errs6 = []
    pg = await open_page(calls=calls6, errs=errs6)
    for ch in ("solana", "base", "solana", "base"):
        await pg.evaluate("(c) => setChain(c)", ch)
        await pg.wait_for_timeout(250)
    iv = await pg.evaluate("() => window.__iv.size")
    first = (await pg.evaluate(INFO))["name"]
    await pg.wait_for_timeout(4600)
    second = (await pg.evaluate(INFO))["name"]
    # hover: تیک نباید جلو ببرد
    box = await pg.evaluate("() => { const e = document.getElementById('liveStrip'); e.scrollIntoView({block: 'center'}); const r = e.getBoundingClientRect(); return [r.left + 60, r.top + r.height / 2]; }")
    await pg.mouse.move(box[0], box[1])
    before_h = (await pg.evaluate(INFO))["name"]
    await pg.evaluate("() => liveStripTick()")
    after_h = (await pg.evaluate(INFO))["name"]
    await pg.mouse.move(5, 5)
    await pg.evaluate("() => document.querySelector('#liveStrip .lsItem').focus()")
    await pg.evaluate("() => liveStripTick()")
    after_f = (await pg.evaluate(INFO))["name"]
    await pg.close()
    print("[live strip rotation] intervals=%d after 4 switches; first=%s then %s after one tick period; hover %s->%s focus ->%s; requests=%s"
          % (iv, first, second, before_h, after_h, after_f, calls6))
    assert iv == 1, "exactly one 4s rotation interval may exist, found %d" % iv
    assert first == BASE_NAMES[0] and second == BASE_NAMES[1], (
        "one tick period must advance exactly one item (got %s -> %s); several intervals advance several" % (first, second))
    assert after_h == before_h, "rotation must pause while the strip is hovered"
    assert after_f == before_h, "rotation must pause while the strip has focus"
    assert sorted(calls6) == ["base", "solana"], "each chain's /pairs.json must be fetched once and cached for 5 minutes: %s" % calls6
    assert not errs6, "console errors in the rotation probe: %s" % errs6

    # ---- اسکرین‌شات‌ها ----
    shots = "/tmp/claude-0/ls_shots"
    os.makedirs(shots, exist_ok=True)
    for scheme in ("light", "dark"):
        for vw, vh in ((1440, 900), (390, 844)):
            for chain in ("base", "solana"):
                pg = await open_page("/app" + ("#swap?chain=solana" if chain == "solana" else ""),
                                     viewport={"width": vw, "height": vh}, scheme=scheme)
                await pg.evaluate("() => document.getElementById('liveStrip').scrollIntoView({block: 'center'})")
                await pg.wait_for_timeout(250)
                await pg.screenshot(path=os.path.join(shots, "%s-%d-%s.png" % (scheme, vw, chain)))
                await pg.close()
    print("[live strip shots] written to %s" % shots)

    await b.close()
    srv.shutdown()


async def check_mobile_compact(p, errors):
    """[mobile compact] / [desktop unchanged] — نمای سواپِ /app روی گوشی با نوارِ تب و فوترِ جمع‌شونده.

    زیر ۹۴۱px زیرِ کارتِ سواپ یک نوارِ تب (Chart / Every pool / Exit check) است و فقط یکی از
    سه کارت دیده می‌شود؛ زیر ۷۲۱px «Market watch» پنهان است و ستون‌های فوتر در یک
    <details class="fMore"> جمع می‌شوند. قاعده‌ی ایمنی: نتیجه‌ی منفیِ Exit check هرگز بی‌صدا
    پشتِ یک تبِ دیگر نمی‌ماند. ≥۹۴۱px هیچ پیکسلی نباید عوض شود — با رندرِ index.html
    از کامیتِ پدر در همین اجرا مقایسه می‌شود."""
    import functools, http.server, json as _j, subprocess, tempfile, threading

    root = os.path.abspath(os.path.join(HERE, "..", ".."))
    shots = os.environ.get("ZX_MOB_SHOTS", "/tmp/claude-0/mob_shots")
    os.makedirs(shots, exist_ok=True)

    # ---- خطِ پایه: index.html از کامیتِ پدر ----
    # اگر index.html/pairs.html/report_page.js هنوز کامیت نشده‌اند، پدر = HEAD؛ بعد از کامیت = HEAD~1.
    def git(*a):
        return subprocess.run(["git", "-C", root] + list(a), capture_output=True, text=True)
    # پدر = نزدیک‌ترین کامیتِ (HEAD، HEAD~1، …) که هنوز نوارِ تبِ mtabBuild را ندارد.
    rev = "HEAD"
    for cand in ("HEAD", "HEAD~1", "HEAD~2", "HEAD~3"):
        o_ = git("show", cand + ":web/index.html")
        if o_.returncode == 0 and "mtabBuild" not in o_.stdout:
            rev = cand
            break
    old = git("show", rev + ":web/index.html")
    base_dir = tempfile.mkdtemp(prefix="mc_base_")
    base_ok = old.returncode == 0 and "mtabBuild" not in old.stdout
    if base_ok:
        src = old.stdout
        src = re.sub(r'const ETHERS_SRC="[^"]*";', 'const ETHERS_SRC="./stub-ethers.js";', src, count=1)
        src = re.sub(r'const ETHERS_SRI="[^"]*";', 'const ETHERS_SRI="";', src, count=1)
        open(os.path.join(base_dir, "harness.html"), "w", encoding="utf-8").write(src)

    def make_server(app_file):
        class Quiet(http.server.SimpleHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def translate_path(self, path):
                clean = path.split("?")[0]
                if clean in ("/app", "/app/"):
                    return app_file
                if clean == "/stub-ethers.js":
                    return os.path.join(HERE, "stub-ethers.js")
                return super().translate_path(path)
        srv = http.server.ThreadingHTTPServer(
            ("127.0.0.1", 0), functools.partial(Quiet, directory=os.path.join(HERE, "..")))
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        return srv, "http://127.0.0.1:%d" % srv.server_address[1]

    srv_new, origin_new = make_server(os.path.join(HERE, "harness.html"))
    srv_old, origin_old = (make_server(os.path.join(base_dir, "harness.html")) if base_ok else (None, None))
    b = await p.chromium.launch()

    SOL_ADDR = "So11111111111111111111111111111111111111112"
    # ⚠️ توکنِ پیش‌فرضِ هارنس (USDC با بایت‌کدِ استاب) خودش یافته‌ی critical دارد («Fee is mutable») و طبقِ
    # قاعده‌ی ایمنی تبِ Exit check را خودکار انتخاب می‌کند. پس کاوشگرهای چیدمان بعد از بارگذاری وضعیتِ
    # ایمنی را پاک می‌کنند تا «تبِ پیش‌فرض» سنجیده شود؛ کاوشگرهای ایمنی خودشان نتیجه تزریق می‌کنند.
    RESET = "mtabParts = Object.create(null); mtabForced.clear(); mtabSelect('chart', false); mtabRefresh();"
    # اولین مقداری که data-mtab می‌گیرد (قبل از اینکه اسکن/چکِ خروج چیزی عوض کند) = خواندنِ localStorage.
    FIRST = ("window.__firstMtab = null; new MutationObserver(() => { if (window.__firstMtab === null) { "
             "const h = document.querySelector('.row.hero[data-mtab]'); if (h) window.__firstMtab = h.dataset.mtab; } })"
             ".observe(document, {subtree: true, attributes: true, attributeFilter: ['data-mtab']});")

    async def open_app(origin, path, vw=390, vh=844, scheme="light", vd=None, sol_mint=None, init=None, errs=None, wait=1300):
        pg = await b.new_page(viewport={"width": vw, "height": vh}, color_scheme=scheme)
        await pg.add_init_script(FIRST)
        if errs is not None:
            pg.on("console", lambda m: errs.append(m.text) if m.type == "error" and (m.location.get("url") or "").startswith(origin) else None)
            pg.on("pageerror", lambda e: errs.append("PAGEERROR " + str(e)))
        if init:
            await pg.add_init_script(init)

        async def external(route):
            await route.abort()

        async def empty(route):
            await route.fulfill(status=200, content_type="application/json", body='{"data":[]}')

        async def ok204(route):
            await route.fulfill(status=204, body="")

        async def vd_h(route):
            await route.fulfill(status=200, content_type="application/json",
                                body=_j.dumps(vd or {"v": "sell", "ms": 100}))

        async def rpc(route):
            payload = _j.loads(route.request.post_data or "{}")
            m = payload.get("method")
            result = None
            if sol_mint is not None and m == "getAccountInfo":
                result = {"value": {"owner": "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA", "data": {"parsed": {
                    "type": "mint", "info": dict({"decimals": 6, "supply": "1000", "isInitialized": True,
                                                  "mintAuthority": None, "freezeAuthority": None}, **sol_mint)}}}}
            elif sol_mint is not None and m == "getTokenLargestAccounts":
                result = {"value": []}
            elif sol_mint is not None and m == "getEpochInfo":
                result = {"epoch": 700}
            await route.fulfill(status=200, content_type="application/json", body=_j.dumps({"result": result}))

        await pg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(origin) else external(r))
        await pg.route("**/gt/**", empty)
        await pg.route("**/ev", ok204)
        await pg.route("**/vd/**", vd_h)
        await pg.route("**/sol/rpc", rpc)
        await pg.route("**/pairs.json**", lambda r: r.fulfill(status=200, content_type="application/json", body='{"rows":[],"store":false}'))
        await pg.goto(origin + path)
        await pg.wait_for_timeout(wait)
        return pg

    STATE = """() => {
        const vis = e => { if (!e) return false; const cs = getComputedStyle(e), r = e.getBoundingClientRect();
                           return cs.display !== 'none' && cs.visibility !== 'hidden' && r.height > 0; };
        const hero = [...document.querySelectorAll('.row.hero')].find(h => !h.hidden);
        const sol = hero.id === 'appSolHero';
        const cards = {chart: hero.querySelector('.swapChartCard'),
                       pools: sol ? document.getElementById('solPools') : document.getElementById('venueBody').closest('.card'),
                       exit: hero.querySelector('.swapSafetyCard')};
        const swap = sol ? document.getElementById('solSwap') : hero.querySelector('.swapCard');
        const strips = [...document.querySelectorAll('.mTabs')];
        const strip = strips.find(vis) || null;
        const tabs = strip ? [...strip.querySelectorAll('[role=tab]')] : [];
        const mw = document.querySelector('.marketWatch');
        const mwv = [...document.querySelectorAll('.marketWatch')].some(vis);
        const exitTab = tabs[2] || null;
        return {sol, stripCount: strips.length, stripVisible: !!strip, role: strip ? strip.getAttribute('role') : null,
                names: tabs.map(t => t.textContent.trim()), roles: tabs.map(t => t.getAttribute('role')),
                selected: tabs.map(t => t.getAttribute('aria-selected')),
                dot: exitTab ? (exitTab.classList.contains('warn') ? 'warn' : exitTab.classList.contains('ok') ? 'ok' : 'none') : null,
                dotShown: exitTab ? getComputedStyle(exitTab, '::after').content !== 'none' : null,
                mtab: hero.dataset.mtab || null,
                visible: Object.keys(cards).filter(k => vis(cards[k])),
                stripTop: strip ? Math.round(strip.getBoundingClientRect().top + scrollY) : null,
                stripW: strip ? Math.round(strip.getBoundingClientRect().width) : null, swapW: Math.round(swap.getBoundingClientRect().width),
                swapBottom: Math.round(swap.getBoundingClientRect().bottom + scrollY),
                pageH: document.documentElement.scrollHeight, overflowX: document.documentElement.scrollWidth > innerWidth,
                plotH: Math.round(hero.querySelector('.plot').getBoundingClientRect().height),
                mwVisible: mwv, mwCount: document.querySelectorAll('.marketWatch').length,
                stored: (() => { try { return localStorage.getItem('zaexa.mtab.v1'); } catch (e) { return 'ERR'; } })()};
    }"""
    FOOT = """() => {
        const vis = e => { if (!e) return false; const r = e.getBoundingClientRect();
                           return e.checkVisibility({contentVisibilityAuto: true, visibilityProperty: true}) && r.height > 0; };
        const f = document.querySelector('footer'), d = f.querySelector('details.fMore');
        const cols = [...f.querySelectorAll('.footCol')];
        return {hasDetails: !!d, summary: d ? d.querySelector('summary').textContent.trim() : null,
                summaryVisible: d ? vis(d.querySelector('summary')) : false, open: d ? d.open : null,
                colsVisible: cols.filter(vis).length, cols: cols.length,
                linksVisible: [...f.querySelectorAll('.footCol a')].filter(vis).length,
                brand: vis(f.querySelector('.footBrand')), fine: vis(f.querySelector('.fine')), bottom: vis(f.querySelector('.footBottom')),
                copyright: /2026 Zaexa/.test(f.querySelector('.footBottom').textContent),
                lefts: [...new Set(cols.filter(vis).map(c => Math.round(c.getBoundingClientRect().left)))].length,
                overflowX: document.documentElement.scrollWidth > innerWidth};
    }"""

    async def foot_collapsed_and_opens(pg, label):
        await pg.evaluate("document.querySelector('footer').scrollIntoView()")
        f0 = await pg.evaluate(FOOT)
        assert f0["hasDetails"] and f0["summary"] == "About, links & support", "%s: footer lost the fMore details row: %s" % (label, f0)
        assert f0["summaryVisible"] and f0["open"] is False, "%s: the fMore row must show closed on a phone: %s" % (label, f0)
        assert f0["colsVisible"] == 0 and f0["linksVisible"] == 0, "%s: footer link columns are still visible while collapsed: %s" % (label, f0)
        assert f0["brand"] and f0["fine"] and f0["bottom"] and f0["copyright"], "%s: brand, legal line and copyright must stay visible: %s" % (label, f0)
        await pg.click("footer details.fMore > summary"); await pg.wait_for_timeout(250)
        f1 = await pg.evaluate(FOOT)
        assert f1["open"] is True and f1["colsVisible"] == 3 and f1["linksVisible"] >= 6, "%s: tapping the row did not open the link columns: %s" % (label, f1)
        assert not f1["overflowX"], "%s: opened footer overflows horizontally" % label
        return f0, f1

    # ================== الف) نمای سواپ، Base و Solana، ۳۹۰px ==================
    results = {}
    for name, path, scheme in (("base-light", "/app#swap", "light"), ("base-dark", "/app#swap", "dark"),
                               ("sol-light", "/app#swap?chain=solana", "light")):
        errs = []
        pg = await open_app(origin_new, path, scheme=scheme, errs=errs)
        if not name.startswith("sol"):
            await pg.evaluate(RESET)
        s = await pg.evaluate(STATE)
        results[name] = s
        assert s["stripCount"] == 2 and s["stripVisible"], "%s: the tab strip is missing from the swap view: %s" % (name, s)
        assert s["role"] == "tablist" and s["roles"] == ["tab"] * 3 and s["names"] == ["Chart", "Every pool", "Exit check"], \
            "%s: the strip needs a tablist with the three named tabs: %s" % (name, s)
        assert s["stripTop"] >= s["swapBottom"] - 1, "%s: the strip must sit under the swap card (strip top %s, card bottom %s)" % (name, s["stripTop"], s["swapBottom"])
        assert abs(s["stripW"] - s["swapW"]) <= 1, "%s: the strip must span the full column (strip %s, swap card %s)" % (name, s["stripW"], s["swapW"])
        assert len(s["visible"]) == 1 and s["visible"] == ["chart"] and s["selected"][0] == "true" and s["mtab"] == "chart", \
            "%s: default must show exactly the chart card: %s" % (name, s)
        assert s["plotH"] == 200, "%s: the chart plot must be 200px on a phone, got %s" % (name, s["plotH"])
        assert not s["mwVisible"], "%s: Market watch must be hidden at 390px" % name
        assert not s["overflowX"], "%s: horizontal overflow at 390px" % name
        assert s["pageH"] <= 1600, "%s: page is %spx tall, target <= 1600" % (name, s["pageH"])
        before = None
        if base_ok:
            og = await open_app(origin_old, path, scheme=scheme)
            before = (await og.evaluate("document.documentElement.scrollHeight"))
            await og.close()
        results[name]["before"] = before
        # روی گوشی عنوانِ «همه‌ی استخرها» و «Exit check» با کلیک عوض می‌شود
        for idx, key in ((1, "pools"), (2, "exit"), (0, "chart")):
            await pg.click('.mTabs:visible [role=tab] >> nth=%d' % idx) if False else await pg.locator(".mTabs >> visible=true").locator("[role=tab]").nth(idx).click()
            await pg.wait_for_timeout(150)
            t = await pg.evaluate(STATE)
            assert t["visible"] == [key] and t["selected"][idx] == "true" and t["selected"].count("true") == 1 and t["mtab"] == key, \
                "%s: switching to %s should show exactly that card: %s" % (name, key, t)
            assert not t["overflowX"], "%s: horizontal overflow on tab %s" % (name, key)
        await pg.locator(".mTabs >> visible=true").locator("[role=tab]").nth(1).click()
        await pg.wait_for_timeout(150)
        stored = (await pg.evaluate(STATE))["stored"]
        await pg.reload(); await pg.wait_for_timeout(1300)
        first = await pg.evaluate("window.__firstMtab")
        await pg.evaluate(RESET.replace("mtabSelect('chart', false);", "mtabInit();"))
        r = await pg.evaluate(STATE)
        assert stored == "pools" and first == "pools" and r["visible"] == ["pools"] and r["mtab"] == "pools", \
            "%s: the chosen tab did not persist across reload (stored=%r, first paint=%r): %s" % (name, stored, first, r)
        # مقدارِ نامعتبر -> chart
        await pg.evaluate("localStorage.setItem('zaexa.mtab.v1','nope')"); await pg.reload(); await pg.wait_for_timeout(1300)
        first2 = await pg.evaluate("window.__firstMtab")
        assert first2 == "chart", "%s: an invalid stored tab must fall back to the chart, first paint was %r" % (name, first2)
        await pg.evaluate("localStorage.removeItem('zaexa.mtab.v1')")
        await pg.reload(); await pg.wait_for_timeout(1300)
        if not name.startswith("sol"):
            await pg.evaluate(RESET)
        await pg.evaluate("window.scrollTo(0,0)")
        # برچسب‌ها بعد از تمام‌شدنِ transition سنجیده می‌شوند: RESET همین الان تب را عوض کرده بود و عکسِ وسطِ
        # transition (.16s) برچسب‌های «Chart» و «Exit check» را کمرنگ نشان می‌داد.
        await pg.wait_for_timeout(600)
        lab = await pg.evaluate("""() => {
            const p = document.createElement('span'); p.style.color = 'var(--tx2)'; document.body.appendChild(p);
            const tx2 = getComputedStyle(p).color; p.remove();
            const strip = [...document.querySelectorAll('.mTabs')].find(e => e.getBoundingClientRect().height > 0);
            return {tx2, tabs: [...strip.querySelectorAll('[role=tab]')].map(t => {
                const cs = getComputedStyle(t);
                return {sel: t.getAttribute('aria-selected') === 'true', color: cs.color, opacity: cs.opacity};
            })};
        }""")
        for i, t in enumerate(lab["tabs"]):
            want_c = "rgb(255, 255, 255)" if t["sel"] else lab["tx2"]
            assert t["color"] == want_c and t["opacity"] == "1", \
                "%s: tab %d label is %s at opacity %s, want %s at 1 (selected=%s)" % (name, i, t["color"], t["opacity"], want_c, t["sel"])
        await pg.screenshot(path=os.path.join(shots, "%s-390-top.png" % name), full_page=True)
        await foot_collapsed_and_opens(pg, name)
        await pg.close()
        assert not errs, "%s: console errors: %s" % (name, errs)
        print("[mobile compact] %s: strip=%s visible=%s plot=%spx page %s -> %spx marketWatch=%s overflow=%s"
              % (name, s["names"], s["visible"], s["plotH"], before, s["pageH"], s["mwVisible"], s["overflowX"]))

    # ================== ب) قاعده‌ی ایمنی ==================
    BAD_X = "renderExit({state:'noexit', lossPct:null, recovered:null, reason:'no pool'})"
    OK_X = "renderExit({state:'verified', lossPct:0.4, recovered:99.6, reason:null})"
    UNK_X = "renderExit({state:'unknown', lossPct:null, recovered:null, reason:'no quote'})"
    rep = ("(level, canSell) => ({address: tokenOut.address, findings: [{level: level, title: 'T', detail: 'D'}], "
           "verdict: {txt: 'Caution', tone: 'warn'}, score: 30, unknown: 0, canSell: canSell, owner: null})")
    for label, inj, forces in (
            ("no-sell exit result", BAD_X, True),
            ("no sell quote (canSell=false, critical finding)", "renderSafety((%s)('critical', false))" % rep, True),
            ("high safety finding with a positive sell verdict", "renderSafety((%s)('high', true)); %s" % (rep, OK_X), False),
            ("critical safety finding with a positive sell verdict", "renderSafety((%s)('critical', true)); %s" % (rep, OK_X), False)):
        pg = await open_app(origin_new, "/app#swap")
        await pg.evaluate(RESET)
        await pg.evaluate(inj); await pg.wait_for_timeout(200)
        s = await pg.evaluate(STATE)
        want = ["exit"] if forces else ["chart"]
        assert s["dot"] == "warn" and s["dotShown"] and s["visible"] == want and s["mtab"] == want[0], \
            "Base %s: red dot always; the tab is switched automatically only for a negative exit verdict (want %s): %s" % (label, want, s)
        assert s["stored"] in (None, "ERR") or s["stored"] == "", "Base %s: the automatic switch must not overwrite the saved choice: %r" % (label, s["stored"])
        if forces:
            await pg.locator(".mTabs >> visible=true").locator("[role=tab]").nth(0).click(); await pg.wait_for_timeout(150)
            s2 = await pg.evaluate(STATE)
            assert s2["dot"] == "warn" and s2["dotShown"] and s2["visible"] == ["chart"], \
                "Base %s: the red dot must stay visible while another tab is selected: %s" % (label, s2)
            await pg.evaluate(inj); await pg.wait_for_timeout(150)
            s3 = await pg.evaluate(STATE)
            assert s3["visible"] == ["chart"], "Base %s: the switch happens once per token, not on every repaint: %s" % (label, s3)
        else:
            await pg.locator(".mTabs >> visible=true").locator("[role=tab]").nth(1).click(); await pg.wait_for_timeout(150)
            s2 = await pg.evaluate(STATE)
            assert s2["dot"] == "warn" and s2["visible"] == ["pools"], "Base %s: dot must survive a manual tab change: %s" % (label, s2)
        if label == "no-sell exit result":
            await pg.locator(".mTabs >> visible=true").locator("[role=tab]").nth(2).click(); await pg.wait_for_timeout(500)
            await pg.screenshot(path=os.path.join(shots, "base-light-390-exit-warning.png"), full_page=True)
        await pg.close()
        print("[mobile compact] Base %s -> red dot, %s" % (label, "Exit check selected once" if forces else "tab NOT changed"))
    pg = await open_app(origin_new, "/app#swap")
    await pg.evaluate(RESET)
    await pg.evaluate("renderSafety((%s)('ok', true))" % rep); await pg.evaluate(OK_X); await pg.wait_for_timeout(200)
    s = await pg.evaluate(STATE)
    assert s["dot"] == "ok" and s["dotShown"] and s["visible"] == ["chart"] and s["mtab"] == "chart", \
        "Base clean result: green dot and the tab must not be forced: %s" % s
    await pg.evaluate(RESET)
    await pg.evaluate(UNK_X); await pg.wait_for_timeout(200)
    s = await pg.evaluate(STATE)
    assert s["dot"] == "none" and s["visible"] == ["chart"], "Base unknown exit: no dot, not forced: %s" % s
    await pg.evaluate(RESET)
    s = await pg.evaluate(STATE)
    assert s["dot"] == "none", "pending state shows a dot: %s" % s
    await pg.close()
    print("[mobile compact] Base clean -> green dot, tab not forced; unknown/pending -> no dot")

    for label, kw, want_dot, want_vis in (
            ("no-sell verdict", dict(vd={"v": "nosell", "ms": 100}), "warn", ["exit"]),
            ("unconfirmed sell-back", dict(vd={"v": None, "why": "sol:unconfirmed", "ms": 100}), "warn", ["exit"]),
            ("active mint authority (high finding, positive sell verdict: dot only)", dict(sol_mint={"mintAuthority": SOL_ADDR}), "warn", ["chart"]),
            ("clean", dict(sol_mint={}), "ok", ["chart"]),
            ("unknown verdict", dict(vd={"v": None, "why": "internal", "ms": 100}), "none", ["chart"])):
        pg = await open_app(origin_new, "/app#swap?chain=solana", wait=1800, **kw)
        s = await pg.evaluate(STATE)
        assert s["sol"] and s["dot"] == want_dot and s["visible"] == want_vis, \
            "Solana %s: expected dot=%s with %s shown: %s" % (label, want_dot, want_vis, s)
        if label == "no-sell verdict":
            await pg.screenshot(path=os.path.join(shots, "sol-light-390-exit-warning.png"), full_page=True)
        await pg.close()
    print("[mobile compact] Solana no-sell / unconfirmed -> red dot + Exit check; high finding alone -> red dot only; clean -> green; unknown -> none")

    # ================== پ) فوتر روی pairs و صفحه‌ی گزارش ==================
    pairs_pg = await b.new_page(viewport={"width": 390, "height": 844})
    async def ext(route):
        await route.abort()
    await pairs_pg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(origin_new) else ext(r))
    await pairs_pg.route("**/pairs.json**", lambda r: r.fulfill(status=200, content_type="application/json", body='{"rows":[],"store":false}'))
    await pairs_pg.goto(origin_new + "/pairs.html"); await pairs_pg.wait_for_timeout(900)
    await foot_collapsed_and_opens(pairs_pg, "pairs")
    await pairs_pg.close()

    worker_dir = os.path.join(root, "worker")
    out = tempfile.mkdtemp(prefix="mc_report_")
    gen = ('import fs from "node:fs"; import { renderReportPage } from "./report_page.js"; '
           'fs.writeFileSync(process.argv[1], renderReportPage({ date: "2026-10-04", today: "2026-10-04", '
           'firstDate: "2026-09-08", rows: [], history: [] }));')
    rp = os.path.join(out, "report.html")
    r = subprocess.run(["node", "--input-type=module", "-e", gen, rp], cwd=worker_dir, capture_output=True, text=True)
    assert r.returncode == 0 and os.path.exists(rp), "could not render the report page: %s" % r.stderr[-400:]
    report_html = open(rp, encoding="utf-8").read()
    rpg = await b.new_page(viewport={"width": 390, "height": 844})
    await rpg.route("**/*", lambda r: r.abort())
    await rpg.set_content(report_html); await rpg.wait_for_timeout(500)
    await foot_collapsed_and_opens(rpg, "report")
    await rpg.close()
    # دسکتاپ: هر سه فوتر عیناً همان سه ستون و بدون ردیفِ summary
    for label, loader in (("app", None), ("pairs", "/pairs.html"), ("report", "report")):
        if label == "app":
            dpg = await open_app(origin_new, "/app#swap", vw=1440, vh=900)
        else:
            dpg = await b.new_page(viewport={"width": 1440, "height": 900})
            await dpg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(origin_new) else r.abort())
            await dpg.route("**/pairs.json**", lambda r: r.fulfill(status=200, content_type="application/json", body='{"rows":[],"store":false}'))
            if loader == "report":
                await dpg.set_content(report_html)
            else:
                await dpg.goto(origin_new + loader)
            await dpg.wait_for_timeout(700)
        fd = await dpg.evaluate(FOOT)
        if label == "app":
            st1440 = await dpg.evaluate("[...document.querySelectorAll('.mTabs')].map(e => getComputedStyle(e).display)")
            assert st1440 and all(d == "none" for d in st1440), "the tab strip must stay hidden at 1440, got display=%s" % st1440
        await dpg.close()
        assert fd["hasDetails"] and not fd["summaryVisible"] and fd["colsVisible"] == 3 and fd["lefts"] == 3, \
            "%s: at 1440 the footer must show its three columns with no summary row: %s" % (label, fd)
    print("[mobile compact] footer: collapsed + opens on tap at 390 (app, pairs, report); three columns and no summary row at 1440")

    # ================== پ-۲) landing.html و تکرارِ فوتر در report_page.js ==================
    # ⚠️ بلوکِ GENERATED در report_page.js با یک اسکریپتِ یک‌باره (که در مخزن نیست) از landing.html ساخته شده بود؛
    # پس منبع landing.html است. این کاوشگر ثابت می‌کند فوترِ report_page.js و قاعده‌های CSSِ جمع‌شدن عیناً همان
    # landing.html هستند (به‌جز لینکِ Exit Report که فقط در گزارش هست)، تا بازسازیِ دوباره یا ویرایشِ یکی از
    # آن‌ها بی‌صدا از دیگری جدا نشود.
    landing_src = open(os.path.join(HERE, "..", "landing.html"), encoding="utf-8").read()
    rep_src = open(os.path.join(worker_dir, "report_page.js"), encoding="utf-8").read()
    gen2 = ('import { LANDING_FOOTER_HTML as f } from "./report_page.js"; process.stdout.write(f);')
    rf = subprocess.run(["node", "--input-type=module", "-e", gen2], cwd=worker_dir, capture_output=True, text=True)
    assert rf.returncode == 0, rf.stderr[-300:]
    lf = re.search(r"<footer.*?</footer>", landing_src, re.S).group(0)
    rf_norm = "\n".join(l for l in rf.stdout.split("\n") if '<a href="/report">Exit Report</a>' not in l)
    assert rf_norm == lf, "worker/report_page.js's footer HTML no longer matches web/landing.html's footer (apart from the Exit Report link)"
    css_start = rep_src.index("@media(max-width:720px){.footGrid{grid-template-columns:1fr}}\n")
    css_blk = rep_src[css_start:rep_src.index("`;\n", css_start)]
    assert "fMore" in css_blk and css_blk in landing_src, "the footer-collapse CSS in worker/report_page.js is not byte-identical to the one in web/landing.html"
    land_new = landing_src
    # ۲۴ اکتبر: فوترِ landing را مالک در 1916a01 پذیرفت؛ پایه دیگر «نزدیک‌ترین نیاکان بدونِ fMore» نیست و روی
    # همان کامیتِ ثابت قفل است (مثلِ [report body unchanged] که 6944652 را قفل می‌کند).
    LANDING_FOOTER_BASE = "1916a01"
    lg = git("show", LANDING_FOOTER_BASE + ":web/landing.html")
    assert lg.returncode == 0, "cannot read %s:web/landing.html (a shallow clone needs: git fetch --deepen=20): %s" % (LANDING_FOOTER_BASE, lg.stderr[-200:])
    land_old = lg.stdout
    # Footer parity excludes intentionally changed decorative page backgrounds.
    LFREEZE = "*,*::before,*::after{animation:none!important;transition:none!important}#landingParticles,.page-glow,body::after{display:none!important}"
    async def land_page(html, vw, scheme):
        lp = await b.new_page(viewport={"width": vw, "height": 900}, color_scheme=scheme)
        await lp.route("**/*", lambda r: r.abort())
        await lp.set_content(html); await lp.add_style_tag(content=LFREEZE); await lp.wait_for_timeout(400)
        return lp
    for scheme in ("light", "dark"):
        shots_l = []
        for html in (land_old, land_new):
            lp = await land_page(html, 1440, scheme)
            shots_l.append(await lp.locator("footer").screenshot())
            await lp.close()
        assert shots_l[0] == shots_l[1], "landing footer at 1440 (%s) differs from the accepted render in %s" % (scheme, LANDING_FOOTER_BASE)
    lp = await land_page(land_new, 390, "light")
    await foot_collapsed_and_opens(lp, "landing")
    await lp.close()
    print("[mobile compact] landing.html: footer byte-identical at 1440 (light/dark), collapsed + opens at 390; report_page.js footer HTML and CSS identical to landing.html (source of the GENERATED block)")

    # ================== ت) [desktop unchanged] ==================
    # ۲۰ اکتبر: خطِ پایه دیگر کامیتِ پدر نیست (با هر کامیتِ تازه کهنه می‌شد و روی main هم می‌افتاد).
    # همان صفحه دو بار رندر می‌شود: یک بار عادی، یک بار با نوارِ تب و data-mtab حذف‌شده — باید یکی باشند.
    NEUTRAL = ("document.querySelectorAll('.mTabs').forEach(e=>e.remove());"
               "document.querySelectorAll('[data-mtab]').forEach(e=>e.removeAttribute('data-mtab'));")
    FREEZE = ("document.addEventListener('DOMContentLoaded',()=>{const s=document.createElement('style');"
              "s.textContent='*,*::before,*::after{animation:none!important;transition:none!important;caret-color:transparent!important}';"
              "document.head.appendChild(s)});")
    compared = []
    for path, scheme in (("/app#swap", "light"), ("/app#swap", "dark"), ("/app#swap?chain=solana", "light")):
        for vw in (1440, 1000):
            shot = []
            pg = await open_app(origin_new, path, vw=vw, vh=900, scheme=scheme, init=FREEZE, wait=1800)
            await pg.evaluate("window.scrollTo(0,0)")
            shot.append(await pg.screenshot(full_page=True))
            await pg.evaluate(NEUTRAL)
            await pg.wait_for_timeout(150)
            shot.append(await pg.screenshot(full_page=True))
            await pg.close()
            compared.append((path, scheme, vw, len(shot[1])))
            assert shot[0] == shot[1], \
                ("[desktop unchanged] %s %s at %dpx: the mobile tab strip / data-mtab changes the desktop render (%d vs %d bytes)"
                 % (path, scheme, vw, len(shot[0]), len(shot[1])))
    print("[desktop unchanged] /app swap at 1440 and 1000, Base light/dark and Solana, animations off: %d renders byte-identical with and without the mobile tab strip"
          % len(compared))
    srv_new.shutdown()
    if srv_old:
        srv_old.shutdown()
    await b.close()


async def check_first_visit_tour(p, errors):
    """[first-visit tour] — تورِ شش‌قدمیِ اولین بازدید روی نمای swapِ /app.

    فقط یک‌بار (zaexa.tour.v1)، فقط روی /app swap (نه /t/، نه flow، نه لینکِ اشتراکی)، با لکه‌ی نور روی
    هدفِ هر قدم، تبِ Exit check روی گوشی، باز/بسته شدنِ تنظیمات در قدم‌های ۴ تا ۶، تله‌ی فوکوس،
    و بدونِ هیچ رویدادِ /ev یا درخواستِ شبکه‌ی تازه. «Take the tour» ته‌ی پنلِ تنظیمات دوباره شروعش می‌کند."""
    import functools, http.server, json as _j, threading
    shots = os.environ.get("ZX_TOUR_SHOTS", "/tmp/claude-0/tour_shots")
    os.makedirs(shots, exist_ok=True)

    class Quiet(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def translate_path(self, path):
            clean = path.split("?")[0]
            if clean in ("/app", "/app/") or clean.startswith("/t/"):
                return os.path.join(HERE, "harness.html")
            if clean == "/stub-ethers.js":
                return os.path.join(HERE, "stub-ethers.js")
            return super().translate_path(path)
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), functools.partial(Quiet, directory=os.path.join(HERE, "..")))
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    origin = "http://127.0.0.1:%d" % srv.server_address[1]
    prev_default = TOUR_DEFAULT["on"]
    TOUR_DEFAULT["on"] = False
    b = await p.chromium.launch()
    errs, ev_seen = [], []
    TITLES = ["Swap on Base and Solana", "Every token gets an exit check", "Your wallet, your keys",
              "Your portfolio", "Approvals: exact by default", "Use your own RPC"]
    BODIES = ["Pick what you pay and what you receive. We check every pool and split your order when that pays you more.",
              "Before you buy, we simulate selling it back. “No sell quote” means no venue we cover would buy it back — treat that as a warning, not a bug.",
              "Zaexa never holds your funds. Every swap is one transaction you sign in your own wallet.",
              "After you connect, Portfolio is the first item in your wallet menu — balances and recent swaps in one place.",
              "By default you approve only the amount of each swap. Turning this on approves an unlimited amount so later swaps skip that step — only do it if you trust the contract.",
              "Paste your own https RPC address here if public nodes are slow. We check that it answers as Base before saving it."]

    async def open_app(path="/app", vw=1440, vh=900, scheme="light", init=None, wait_tour=True):
        pg = await b.new_page(viewport={"width": vw, "height": vh}, color_scheme=scheme)
        pg.on("console", lambda m: errs.append(m.text) if m.type == "error" and (m.location.get("url") or "").startswith(origin) else None)
        pg.on("pageerror", lambda e: errs.append("PAGEERROR " + str(e)))
        if init:
            await pg.add_init_script(init)

        async def external(route):
            await route.abort()

        async def empty(route):
            await route.fulfill(status=200, content_type="application/json", body='{"data":[]}')

        async def ev204(route):
            ev_seen.append(route.request.url + " " + (route.request.post_data or ""))
            await route.fulfill(status=204, body="")

        async def vd_h(route):
            await route.fulfill(status=200, content_type="application/json", body='{"v":"sell","ms":100}')

        async def rpc(route):
            await route.fulfill(status=200, content_type="application/json", body='{"result":null}')
        await pg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(origin) else external(r))
        await pg.route("**/gt/**", empty)
        await pg.route("**/ev", ev204)
        await pg.route("**/vd/**", vd_h)
        await pg.route("**/sol/rpc", rpc)
        await pg.route("**/pairs.json**", lambda r: r.fulfill(status=200, content_type="application/json", body='{"rows":[],"store":false}'))
        await pg.goto(origin + path)
        if wait_tour:
            await pg.wait_for_selector("#zxTour .tCard", timeout=15000)
        return pg

    async def absent(pg, why, ms=2600):
        await pg.wait_for_timeout(ms)
        n = await pg.evaluate("document.querySelectorAll('#zxTour').length")
        assert n == 0, "[first-visit tour] the tour must not appear: %s" % why

    async def stored(pg):
        return await pg.evaluate("(() => { try { return localStorage.getItem('zaexa.tour.v1'); } catch (e) { return 'ERR'; } })()")

    TARGET = """(i) => {
        const sol = typeof activeChain !== 'undefined' && activeChain === 'solana';
        const q = s => document.querySelector(s);
        let els;
        if (i === 0) els = [sol ? q('#solSwap') : q('#baseHeroRow .swapCard')];
        else if (i === 1) els = [sol ? q('#appSolSafetyCard') : q('#baseHeroRow .swapSafetyCard')];
        else if (i === 2) els = [sol ? q('#solSwapBtn') : q('#actBtn')];
        else if (i === 3) els = [q('#connectBtn')];
        else if (i === 4) els = [q('#unlimApprove').closest('.optrow')];
        else els = [[...document.querySelectorAll('#setPop h4')].find(h => /custom rpc/i.test(h.textContent)), q('#rpcSave').parentElement];
        let L = 1e9, T = 1e9, R = -1e9, B = -1e9;
        for (const e of els) { const r = e.getBoundingClientRect(); L = Math.min(L, r.left); T = Math.min(T, r.top); R = Math.max(R, r.right); B = Math.max(B, r.bottom); }
        return {left: L, top: T, right: R, bottom: B};
    }"""
    STEP = """() => {
        const c = document.querySelector('#zxTour .tCard'), s = document.querySelector('#zxTour .tSpot');
        const cr = c.getBoundingClientRect(), sr = s.getBoundingClientRect();
        const pop = document.getElementById('setPop');
        const hero = [...document.querySelectorAll('.row.hero')].find(h => !h.hidden);
        const ex = document.querySelector('.mTabs [data-mtab="exit"]');
        const vis = b => !b.hidden && getComputedStyle(b).display !== 'none';
        return {count: c.querySelector('.tCount').textContent, title: c.querySelector('.tTitle').textContent,
                body: c.querySelector('.tBody').textContent, popOn: pop.classList.contains('on'),
                spot: {left: sr.left, top: sr.top, right: sr.right, bottom: sr.bottom},
                card: {left: cr.left, top: cr.top, right: cr.right, bottom: cr.bottom, width: cr.width},
                btns: [...c.querySelectorAll('button')].filter(vis).map(b => b.textContent),
                dots: [...c.querySelectorAll('.tDots i')].map(d => d.classList.contains('on')),
                mtab: hero ? hero.dataset.mtab : null, exitSel: ex ? ex.getAttribute('aria-selected') : null,
                vw: document.getElementById('zxTour').getBoundingClientRect().width, vh: document.getElementById('zxTour').getBoundingClientRect().height,
                navTop: document.getElementById('nav').getBoundingClientRect().top,
                hdrBottom: document.querySelector('body > header').getBoundingClientRect().bottom,
                inCard: c.contains(document.activeElement)};
    }"""
    COLORS = """() => {
        const c = document.querySelector('#zxTour .tCard'), pr = document.createElement('span');
        document.body.appendChild(pr);
        const col = v => { pr.style.color = v; return getComputedStyle(pr).color; };
        const out = {title: getComputedStyle(c.querySelector('.tTitle')).color, body: getComputedStyle(c.querySelector('.tBody')).color,
                     tx: col('var(--tx)'), tx2: col('var(--tx2)'), card: getComputedStyle(c).backgroundColor, cardVar: (pr.style.color = 'var(--card)', pr.style.backgroundColor = 'var(--card)', getComputedStyle(pr).backgroundColor),
                     next: getComputedStyle(c.querySelector('.tNext')).color, nextBg: getComputedStyle(c.querySelector('.tNext')).backgroundImage,
                     outline: getComputedStyle(document.querySelector('#zxTour .tSpot')).outline,
                     shadow: getComputedStyle(document.querySelector('#zxTour .tSpot')).boxShadow};
        pr.remove(); return out;
    }"""

    def lum(rgb):
        ch = [int(x) / 255 for x in re.findall(r"\d+", rgb)[:3]]
        ch = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4 for c in ch]
        return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2]

    def contrast(a, b_):
        la, lb = sorted((lum(a), lum(b_)), reverse=True)
        return (la + 0.05) / (lb + 0.05)

    def near(spot, t, what):
        for k, d in (("left", -8), ("top", -8), ("right", 8), ("bottom", 8)):
            assert abs(spot[k] - (t[k] + d)) <= 12, "[first-visit tour] %s: spotlight %s %.1f is not within 12px of the target rect + 8px padding (%.1f)" % (what, k, spot[k], t[k] + d)

    async def walk(pg, vw, scheme, tag, shot_steps=()):
        """از قدمِ ۱ تا ۶ با Next؛ هر قدم را می‌سنجد."""
        prev_tab = await pg.evaluate("document.querySelector('.row.hero[data-mtab]') && document.querySelector('.row.hero[data-mtab]').dataset.mtab")
        for i in range(6):
            st = await pg.evaluate(STEP)
            what = "%s step %d" % (tag, i + 1)
            assert st["count"] == "WELCOME TO ZAEXA · %d OF 6" % (i + 1), "[first-visit tour] %s counter: %r" % (what, st["count"])
            assert st["title"] == TITLES[i] and st["body"] == BODIES[i], "[first-visit tour] %s text: %r" % (what, st["title"])
            assert st["dots"] == [k == i for k in range(6)], "[first-visit tour] %s dots: %s" % (what, st["dots"])
            assert st["btns"] == (["Skip", "Next"] if i == 0 else (["Back", "Skip", "Done"] if i == 5 else ["Back", "Skip", "Next"])), "[first-visit tour] %s buttons: %s" % (what, st["btns"])
            assert st["popOn"] == (i in (4, 5)), "[first-visit tour] %s: #setPop open=%s but it must be open only on steps 5 and 6" % (what, st["popOn"])
            t = await pg.evaluate(TARGET, i)
            near(st["spot"], t, what)
            c = st["card"]
            assert c["left"] >= 0 and c["right"] <= st["vw"] + 0.5 and c["top"] >= 0 and c["bottom"] <= st["vh"] + 0.5, "[first-visit tour] %s: card leaves the viewport %s" % (what, c)
            if vw > 720:
                assert abs(c["width"] - 330) < 1, "[first-visit tour] %s: desktop card width %s" % (what, c["width"])
                inter = not (c["right"] <= t["left"] or c["left"] >= t["right"] or c["bottom"] <= t["top"] or c["top"] >= t["bottom"])
                assert not inter, "[first-visit tour] %s: the card covers its target %s %s" % (what, c, t)
            else:
                assert abs(c["left"] - 16) < 1 and abs(st["vw"] - c["right"] - 16) < 1, "[first-visit tour] %s: docked card must keep 16px gutters %s" % (what, c)
                assert c["bottom"] <= st["navTop"] + 0.5, "[first-visit tour] %s: docked card sits on the bottom bar (%s vs %s)" % (what, c["bottom"], st["navTop"])
                assert t["top"] >= (0 if i == 3 else st["hdrBottom"] - 1) and t["top"] < c["top"] - 16, "[first-visit tour] %s: the target must be scrolled into view above the card %s %s" % (what, t, c)
                if t["bottom"] - t["top"] <= c["top"] - st["hdrBottom"] - 30:
                    assert t["bottom"] <= c["top"] + 1, "[first-visit tour] %s: target hidden under the docked card %s %s" % (what, t, c)
            if vw <= 940 and i == 1:
                assert st["mtab"] == "exit" and st["exitSel"] == "true", "[first-visit tour] %s: the Exit check tab must be selected (%s)" % (what, st["mtab"])
            elif vw <= 940:
                assert st["mtab"] == prev_tab, "[first-visit tour] %s: the previous tab %r must be restored, got %r" % (what, prev_tab, st["mtab"])
            assert st["inCard"], "[first-visit tour] %s: focus must sit inside the card" % what
            if i in shot_steps:
                await pg.screenshot(path=os.path.join(shots, "%s-step%d.png" % (tag, i + 1)))
            if i < 5:
                await pg.click("#zxTour .tNext")
        return

    # ---- 1) ۱۴۴۰ روشن: قدم‌ها، رنگ‌ها، اسکرین‌شات ----
    for vw, vh, scheme, shot_steps in ((1440, 900, "light", (0, 1, 3, 5)), (390, 844, "dark", (1, 4)), (390, 844, "light", ()), (1440, 900, "dark", ())):
        tag = "%d-%s" % (vw, scheme)
        pg = await open_app("/app", vw, vh, scheme)
        assert await stored(pg) in ("pending", None), "[first-visit tour] a first visit must not already be done"
        st = await pg.evaluate(STEP)
        assert st["count"].endswith("1 OF 6") and st["btns"] == ["Skip", "Next"], "[first-visit tour] first visit must show step 1 (%s)" % st
        col = await pg.evaluate(COLORS)
        assert col["title"] == col["tx"], "[first-visit tour] %s: the title must use var(--tx) (%s vs %s)" % (tag, col["title"], col["tx"])
        assert col["body"] == col["tx2"], "[first-visit tour] %s: the body must use var(--tx2)" % tag
        assert col["next"] == "rgb(255, 255, 255)" and "gradient" in col["nextBg"], "[first-visit tour] %s: Next must be white on var(--grad): %s %s" % (tag, col["next"], col["nextBg"])
        assert contrast(col["title"], col["card"]) >= 7 and contrast(col["body"], col["card"]) >= 4.5, "[first-visit tour] %s: title/body not legible on the card %s" % (tag, col)
        assert "rgba(10, 14, 30, 0.62) 0px 0px 0px 9999px" in col["shadow"] and ("2px" in col["outline"] and "solid" in col["outline"] and "197, 108, 245" in col["outline"] or "var(--g2)" in col["outline"]), "[first-visit tour] %s: spotlight style %s | %s" % (tag, col["shadow"], col["outline"])
        await walk(pg, vw, scheme, tag, shot_steps)
        # Back از قدمِ ۶ تا ۴ و دوباره جلو (۱۹ اکتبر: پورتفولیو قدمِ ۴، تنظیمات ۵ و ۶)
        await pg.click("#zxTour .tBack")
        st = await pg.evaluate(STEP)
        assert st["count"].endswith("5 OF 6") and st["popOn"], "[first-visit tour] %s: Back from step 6 must land on step 5 with Settings open (%s)" % (tag, st["count"])
        await pg.click("#zxTour .tBack")
        st = await pg.evaluate(STEP)
        assert st["count"].endswith("4 OF 6") and not st["popOn"], "[first-visit tour] %s: Back to step 4 must close Settings" % tag
        for _ in range(2):
            await pg.click("#zxTour .tNext")
        st = await pg.evaluate(STEP)
        assert st["count"].endswith("6 OF 6") and st["btns"] == ["Back", "Skip", "Done"], "[first-visit tour] %s: step 6 ends with Done" % tag
        await pg.click("#zxTour .tNext")
        assert await pg.evaluate("document.querySelectorAll('#zxTour').length") == 0, "[first-visit tour] %s: Done must remove the tour" % tag
        assert await stored(pg) == "done", "[first-visit tour] %s: Done must write 'done'" % tag
        assert not await pg.evaluate("document.getElementById('setPop').classList.contains('on')"), "[first-visit tour] %s: Settings closed after Done" % tag
        await pg.reload()
        await absent(pg, "a reload after Done (%s)" % tag)
        await pg.close()
    print("[first-visit tour] first visit shows step 1; Next walks 1 to 6 with the spotlight within 12px of each target (swap card, exit-check card, main Connect button, header wallet chip, unlimited-approval row, Custom RPC block) at 1440 and 390, light and dark; Settings open on steps 5 and 6 only; Back works; Done writes 'done' and a reload shows nothing; shots in %s" % shots)

    # ---- 2) تبِ موبایل: قدمِ ۲ انتخاب، بعد برمی‌گرداند — از تبِ غیرپیش‌فرض ----
    pg = await open_app("/app", 390, 844, "light", init="try{localStorage.setItem('zaexa.mtab.v1','pools')}catch(e){}")
    await pg.evaluate("mtabParts = Object.create(null); mtabForced.clear(); mtabSelect('pools', false); mtabRefresh();")
    await pg.click("#zxTour .tNext")
    assert (await pg.evaluate(STEP))["mtab"] == "exit", "[first-visit tour] step 2 on a phone must select the Exit check tab"
    await pg.click("#zxTour .tNext")
    st = await pg.evaluate(STEP)
    assert st["mtab"] == "pools" and st["exitSel"] == "false", "[first-visit tour] leaving step 2 must restore the previous tab (pools), got %s" % st["mtab"]
    await pg.click("#zxTour .tBack")
    assert (await pg.evaluate(STEP))["mtab"] == "exit"
    await pg.click("#zxTour .tBack")
    assert (await pg.evaluate(STEP))["mtab"] == "pools", "[first-visit tour] Back from step 2 must restore the previous tab"
    await pg.click("#zxTour .tNext")
    await pg.click("#zxTour .tSkip")
    assert (await pg.evaluate("document.querySelector('.row.hero').dataset.mtab")) == "pools", "[first-visit tour] Skip on step 2 must restore the tab"
    assert await stored(pg) == "done", "[first-visit tour] Skip must write 'done'"
    assert await pg.evaluate("localStorage.getItem('zaexa.mtab.v1')") == "pools", "[first-visit tour] the tour must never persist its temporary tab choice"
    await pg.close()

    # ---- 3) Skip / Esc روی قدم‌های با تنظیماتِ باز ----
    pg = await open_app("/app", 1440, 900, "light")
    for _ in range(4):
        await pg.click("#zxTour .tNext")
    assert (await pg.evaluate(STEP))["popOn"]
    await pg.click("#zxTour .tSkip")
    assert await stored(pg) == "done" and not await pg.evaluate("document.getElementById('setPop').classList.contains('on')"), "[first-visit tour] Skip must write 'done' and close the Settings the tour opened"
    await pg.reload(); await absent(pg, "a reload after Skip")
    await pg.close()
    pg = await open_app("/app", 1440, 900, "light")
    for _ in range(5):
        await pg.click("#zxTour .tNext")
    assert (await pg.evaluate(STEP))["popOn"]
    await pg.keyboard.press("Escape")
    assert await pg.evaluate("document.querySelectorAll('#zxTour').length") == 0 and await stored(pg) == "done", "[first-visit tour] Esc must skip and write 'done'"
    assert not await pg.evaluate("document.getElementById('setPop').classList.contains('on')"), "[first-visit tour] Esc must close the Settings the tour opened"
    await pg.reload(); await absent(pg, "a reload after Esc")
    await pg.close()
    print("[first-visit tour] Skip and Esc write 'done', close the Settings the tour opened, restore the phone tab, and a reload shows nothing")

    # ---- 4) فوکوس و کلیکِ بیرون از کارت ----
    pg = await open_app("/app", 1440, 900, "light")
    for _ in range(4):
        await pg.click("#zxTour .tNext")
    for k in range(9):
        await pg.keyboard.press("Tab")
        assert (await pg.evaluate(STEP))["inCard"], "[first-visit tour] Tab #%d left the card" % k
    for k in range(5):
        await pg.keyboard.press("Shift+Tab")
        assert (await pg.evaluate(STEP))["inCard"], "[first-visit tour] Shift+Tab #%d left the card" % k
    await pg.mouse.click(120, 520)
    await pg.mouse.click(700, 300)
    st = await pg.evaluate(STEP)
    assert st["count"].endswith("5 OF 6") and st["popOn"], "[first-visit tour] a click outside the card must do nothing (step %s, Settings open=%s)" % (st["count"], st["popOn"])
    assert await pg.evaluate("document.querySelectorAll('.ov.on').length") == 0, "[first-visit tour] a click outside the card must not open anything"
    await pg.keyboard.press("Escape")
    await pg.close()

    # ---- 5) «Take the tour» ----
    for vw, vh in ((1440, 900), (390, 844)):
        pg = await open_app("/app", vw, vh, "light", init="try{localStorage.setItem('zaexa.tour.v1','done')}catch(e){}", wait_tour=False)
        await absent(pg, "a visitor who already finished it", 1800)
        await pg.click("#setBtn")
        label = (await pg.inner_text("#setPop .tourBtn")).strip()
        assert label == "Take the tour", "[first-visit tour] the Settings popover must end with a 'Take the tour' button, got %r" % label
        last = await pg.evaluate("document.querySelector('#setPop').lastElementChild.id")
        assert last == "tourBtn", "[first-visit tour] 'Take the tour' must be the last thing in Settings (%s)" % last
        await pg.click("#tourBtn")
        await pg.wait_for_selector("#zxTour .tCard", timeout=4000)
        st = await pg.evaluate(STEP)
        assert st["count"].endswith("1 OF 6") and not st["popOn"], "[first-visit tour] 'Take the tour' must restart at step 1 with Settings closed (%s)" % st["count"]
        await pg.keyboard.press("Escape")
        assert await stored(pg) == "done"
        await pg.close()
    print("[first-visit tour] 'Take the tour' at the bottom of Settings restarts the tour at 1440 and 390 even after it was finished")

    # ---- 6) فوکوس‌اولیه و localStorageی که پرتاب می‌کند ----
    THROW_GET = "Storage.prototype.getItem = function(){ throw new Error('blocked'); };"
    THROW_SET = "(() => { const s = Storage.prototype.setItem; Storage.prototype.setItem = function(k){ if (k === 'zaexa.tour.v1') throw new Error('blocked'); return s.apply(this, arguments); }; })();"
    for name, init in (("getItem throws", THROW_GET), ("setItem throws", THROW_SET)):
        pg = await open_app("/app", 1440, 900, "light", init=init, wait_tour=False)
        await absent(pg, "localStorage %s, so the tour would nag on every visit" % name, 3000)
        await pg.close()
    print("[first-visit tour] localStorage that throws (read or write) -> the tour never shows")

    # ---- 7) جاهایی که نباید نشان دهد ----
    for path, why in (("/t/0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913", "a /t/<token> page"),
                      ("/app#flow", "the Flow view"), ("/app#folio", "the Portfolio view"), ("/app#stocks", "the Stocks view"),
                      ("/app#swap?in=ETH&out=USDC&amt=1", "a shared swap link"), ("/app#swap?amt=2", "a shared amount")):
        pg = await open_app(path, 1440, 900, "light", wait_tour=False)
        await absent(pg, why)
        assert await stored(pg) is None, "[first-visit tour] %s must not touch the stored flag (%r)" % (why, await stored(pg))
        await pg.close()
    print("[first-visit tour] no tour on /t/<token>, #flow, #folio, #stocks, or a shared swap link / amount")

    # ---- 8) Solana: همان هدف‌ها با معادلِ سولانا ----
    pg = await open_app("/app#swap?chain=solana", 1440, 900, "light")
    for i in range(3):
        st = await pg.evaluate(STEP)
        t = await pg.evaluate(TARGET, i)
        assert st["count"].startswith("WELCOME TO ZAEXA") and st["count"].endswith("%d OF 6" % (i + 1))
        near(st["spot"], t, "solana step %d" % (i + 1))
        assert t["right"] - t["left"] > 100, "[first-visit tour] solana step %d target is empty %s" % (i + 1, t)
        await pg.click("#zxTour .tNext")
    assert await pg.evaluate("activeChain") == "solana"
    await pg.keyboard.press("Escape")
    await pg.close()
    print("[first-visit tour] on Solana the spotlight uses the Solana swap card, exit-check card and Connect button; nothing is switched")

    # ---- 9) هیچ رویدادِ /ev و هیچ خطا ----
    bad = [e for e in ev_seen if "tour" in e.lower()]
    assert not bad, "[first-visit tour] the tour must not send any /ev event: %s" % bad
    assert not errs, "[first-visit tour] console errors: %s" % errs[:5]
    print("[first-visit tour] no /ev event mentions the tour (%d /ev requests seen), no console errors" % len(ev_seen))
    TOUR_DEFAULT["on"] = prev_default
    srv.shutdown()
    await b.close()


async def check_report_page(p, errors):
    """صفحه‌ی گزارش (/report) و تبِ پنجمِ «Exit Report» در هدرِ اپ و pairs.

    HTML همان renderReportPage واقعیِ worker/report_page.js است، از یک فیکسچرِ
    «شکلِ زنده» (ردیف‌ها از publishGuardRow می‌گذرند)، و با *همان* CSP فایلِ
    web/_headers سرو می‌شود — پس هر اسکریپت/استایل/فونتی که CSP نپذیرد اینجا
    خطای کنسول می‌دهد، نه فقط روی سایتِ زنده."""
    import functools, http.server, json as _j, subprocess, tempfile, threading

    worker_dir = os.path.join(HERE, "..", "..", "worker")
    out_dir = tempfile.mkdtemp(prefix="r11_page_")
    html_path = os.path.join(out_dir, "report.html")
    meta_path = os.path.join(out_dir, "meta.json")
    gen = r"""
    import fs from "node:fs";
    import { renderReportPage, dayCounts, addDays } from "./report_page.js";
    import { publishGuardRow } from "./report.js";
    const DATE = "2026-10-04", FIRST = "2026-09-08";
    const addr = (n) => "0x" + n.toString(16).padStart(40, "0");
    const solA = (n) => "S" + String(n).padStart(2, "0") + "x".repeat(40);
    const rows = [];
    const t = (h, m) => DATE + "T" + String(h).padStart(2, "0") + ":" + String(m).padStart(2, "0") + ":00.000Z";
    let i = 0;
    const NAMES = ["Pepe Classic", "Zaexa Test Token With A Very Long Name Indeed", "Base God", "Tiny Cat", "Moon Dog", "Aero Bunny"];
    // Base: ۸۰ sell (۱۲ با follow: ۳ خالی، ۹ هنوز هست)، ۳ nosell، ۱۴ نامعلوم
    for (let k = 0; k < 80; k++, i++) {
      const r = { chain: "base", address: addr(1000 + i), symbol: "T" + i, name: NAMES[i % NAMES.length], v: "sell", checkKind: "sell-quote",
        checkedAt: t(0 + (i % 23), (i * 7) % 60), poolCreatedAt: null, priceUsd: 0.01, reserveUsd: 1000 + i * 913.7, vol24hUsd: 10, fdvUsd: 1000, dex: "aerodrome",
        why: null, ret: 90 + (i % 10) + 0.5 };
      if (k < 3) { r.follow = "pool-empty"; r.followAt = new Date(Date.parse(r.checkedAt) + 2 * 3600e3).toISOString(); }
      else if (k < 12) { r.follow = "pool-there"; r.followAt = new Date(Date.parse(r.checkedAt) + 1.4 * 3600e3).toISOString(); }
      rows.push(r);
    }
    for (let k = 0; k < 3; k++, i++) rows.push({ chain: "base", address: addr(1000 + i), symbol: "N" + k, name: "No exit " + k, v: "nosell", checkKind: "sell-quote",
      checkedAt: t(5 + k, 10), poolCreatedAt: null, priceUsd: null, reserveUsd: 2500, vol24hUsd: null, fdvUsd: null, dex: "aerodrome", why: null, cause: k === 2 ? "sell-reverts" : "empty-pool" });
    const WHYS = ["rpc-down", "no-quote", "meta:429", "cover:false", "internal", "deadline", "v4:unproven", "sells:recent", "usdc-no-proof", "cover:503", "meta:timeout", "proof-rpc", "cause:unproven", "no-amount"];
    for (let k = 0; k < 14; k++, i++) rows.push({ chain: "base", address: addr(1000 + i), symbol: "U" + k, name: "Unknown " + k, v: null, checkKind: "sell-quote",
      checkedAt: t(9, k), poolCreatedAt: null, priceUsd: null, reserveUsd: null, vol24hUsd: null, fdvUsd: null, dex: null, why: WHYS[k] });
    // دو ردیفِ خامِ ناقضِ گارد باید از publishGuardRow بگذرند
    rows.push({ chain: "base", address: addr(9001), symbol: "NOCAUSE", name: "no cause", v: "nosell", checkKind: "sell-quote", checkedAt: t(11, 1), reserveUsd: 10, why: null });
    // Solana: ۲۸ sell، ۳ نامعلوم، و یک nosell خام که گارد باید بپوشاند
    for (let k = 0; k < 28; k++, i++) rows.push({ chain: "solana", address: solA(k), symbol: "S" + k, name: "Sol token " + k, v: "sell", checkKind: "roundtrip",
      checkedAt: t(12, k), poolCreatedAt: null, priceUsd: null, reserveUsd: 8000 + k * 100, vol24hUsd: null, fdvUsd: null, dex: "raydium", why: null });
    const SW = ["jup:quote:429", "internal", "rpc:getBalance:500"];
    for (let k = 0; k < 3; k++) rows.push({ chain: "solana", address: solA(40 + k), symbol: "X" + k, name: "Sol unknown " + k, v: null, checkKind: "roundtrip", checkedAt: t(13, k), reserveUsd: null, why: SW[k] });
    rows.push({ chain: "solana", address: solA(60), symbol: "SOLNOSELL", name: "raw solana nosell", v: "nosell", checkKind: "roundtrip", checkedAt: t(14, 0), reserveUsd: 1, why: null, cause: "empty-pool" });
    // یک نامِ خصمانه
    rows.push({ chain: "base", address: addr(9002), symbol: "<b>BOLD</b>", name: "</script><img src=x onerror=window.__xss=1>", v: "sell", checkKind: "sell-quote", checkedAt: t(15, 0), reserveUsd: 500, ret: 97, why: null });
    // نمادِ ؟ / خالی / null و بازگشتِ بالای ۱۰۰٪ — کلاینت نباید «$?» بنویسد و ret>100 باید «—» با یادداشت باشد
    rows.push({ chain: "base", address: "0xabcdef0123456789abcdef0123456789abcdef01", symbol: "?", name: "SymQ", v: "sell", checkKind: "sell-quote", checkedAt: t(16, 0), reserveUsd: 700, ret: 140, why: null });
    rows.push({ chain: "base", address: "0x1234567890123456789012345678901234567890", symbol: "", name: "SymE", v: "sell", checkKind: "sell-quote", checkedAt: t(16, 1), reserveUsd: 700, ret: 96, why: null });
    rows.push({ chain: "base", address: "0x9999999999999999999999999999999999999999", symbol: null, name: "SymN", v: "sell", checkKind: "sell-quote", checkedAt: t(16, 2), reserveUsd: 700, ret: 97, why: null });
    const guarded = rows.map((r) => publishGuardRow(r, undefined));
    const history = [];
    for (let d = 13; d >= 0; d--) {
      const date = addDays(DATE, -d);
      history.push(d === 0 ? dayCounts(date, guarded) : { date, b: 60 + d * 3, bSell: 50 + d, bNo: d % 4, bNa: 10 + d * 2 - (d % 4), bEmpty: d % 3, bFollowed: 8 + d });
    }
    const html = renderReportPage({ date: DATE, today: DATE, firstDate: FIRST, rows: guarded, history });
    fs.writeFileSync(process.argv[1], html);
    // روزِ پیش از شروعِ Solana: همان ردیف‌ها، ولی صفحه نباید Solana نشان بدهد
    fs.writeFileSync(process.argv[1] + ".early", renderReportPage({ date: "2026-09-21", today: DATE, firstDate: FIRST, rows: guarded, history: [] }));
    const cnt = (f) => guarded.filter(f).length;
    const isB = (r) => r.chain === "base", isS = (r) => r.chain === "solana";
    const meta = { date: DATE, bytes: Buffer.byteLength(html), days: history.map((h) => h.date) };
    for (const [k, f] of Object.entries({ all: () => true, base: isB, solana: isS })) {
      meta[k] = { all: cnt((r) => f(r)), nosell: cnt((r) => f(r) && r.v === "nosell"), sell: cnt((r) => f(r) && r.v === "sell"),
        na: cnt((r) => f(r) && r.v !== "sell" && r.v !== "nosell"), empty: cnt((r) => f(r) && r.v === "sell" && r.follow === "pool-empty") };
    }
    fs.writeFileSync(process.argv[2], JSON.stringify(meta));
    """
    r = subprocess.run(["node", "--input-type=module", "-e", gen, html_path, meta_path],
                       capture_output=True, text=True, cwd=worker_dir)
    assert r.returncode == 0, "[report page] could not render the fixture page:\n%s" % r.stderr
    meta = _j.load(open(meta_path))
    page_html = open(html_path, "rb").read()
    early_html = open(html_path + ".early", "rb").read()

    hdrs = parse_headers_blocks(open(os.path.join(HERE, "..", "_headers"), encoding="utf-8").read())
    assert "/*" in hdrs, "[report page] web/_headers has no /* block"
    star = {ln.split(":", 1)[0].strip().lower(): ln.split(":", 1)[1].strip() for ln in hdrs["/*"]}
    csp = star["content-security-policy"]

    app_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
    theme_key = theme_key_from_index(app_src)
    shots = "/tmp/claude-0/r11_shots"
    os.makedirs(shots, exist_ok=True)
    seen = []

    class Quiet(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def do_GET(self):
            clean = self.path.split("?")[0]
            if clean == "/report" or re.match(r"^/report/\d{4}-\d{2}-\d{2}$", clean):
                seen.append(clean)
                body = early_html if clean == "/report/2026-09-21" else page_html
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Security-Policy", csp)
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            return super().do_GET()

        def translate_path(self, path):
            clean = path.split("?")[0]
            if clean in ("/app", "/app/"):
                return os.path.join(HERE, "harness.html")
            if clean == "/pairs":
                return os.path.join(HERE, "..", "pairs.html")
            if clean == "/stub-ethers.js":
                return os.path.join(HERE, "stub-ethers.js")
            return super().translate_path(path)

    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), functools.partial(Quiet, directory=os.path.join(HERE, "..")))
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    origin = "http://127.0.0.1:%d" % srv.server_address[1]
    b = await p.chromium.launch()
    errs = []

    async def open_report(vw, vh, scheme="light", path="/report", init=None):
        pg = await b.new_page(viewport={"width": vw, "height": vh}, color_scheme=scheme)
        def on_msg(m):
            if m.type == "error":
                errs.append("[%sx%s %s] %s" % (vw, vh, scheme, m.text))
        pg.on("console", on_msg)
        pg.on("pageerror", lambda e: errs.append("PAGEERROR %s" % e))
        await pg.add_init_script("localStorage.setItem(%s, %s);" % (_j.dumps(theme_key), _j.dumps(scheme)))
        if init:
            await pg.add_init_script(init)
        await pg.route("**/*", lambda route: route.continue_() if route.request.url.startswith(origin) else route.abort())
        await pg.goto(origin + path)
        await pg.wait_for_selector("#tb tr", timeout=10000)
        return pg

    # ---- [header identical] ۱۱ اکتبر — هدرِ بالا روی /app (هر سه نما)، /pairs و /report دقیقاً یکی است و با عوض‌شدنِ تبِ فعال نمی‌پرد ----
    # علتِ اندازه‌گیری‌شده: (۱) هدرِ /app فونتِ ui-sans-serif دارد ولی بدنه‌ی /pairs و /report با Manrope است → پهنای نوار و x هر دکمه فرق می‌کرد؛
    # (۲) تبِ فعال وزن ۶۲۰ می‌گیرد و پهن‌تر می‌شود → نوار با عوض‌شدنِ تبِ فعال می‌پرید.
    HID_JS = """() => { const q = s => document.querySelector(s);
        const r5 = v => Math.round(v * 2) / 2;
        const bx = e => { if (!e) return null; const x = e.getBoundingClientRect(); return [r5(x.left), r5(x.width)]; };
        const ff = e => e ? getComputedStyle(e).fontFamily : null;
        const nav = q('#nav'), items = {};
        [...nav.children].forEach(e => { items[e.getAttribute('title')] = bx(e); });
        const labels = {};
        [...nav.querySelectorAll('span[data-t]')].forEach(e => { labels[e.getAttribute('data-t')] = ff(e); });
        return { logo: bx(q('.logo')), nav: bx(nav), items: items, setBtn: bx(q('#setBtn')), themeBtn: bx(q('#themeBtn')), connectBtn: bx(q('#connectBtn')),
                 connectTxt: q('#connectBtn').textContent.trim(),
                 fonts: { nav: ff(nav), connectBtn: ff(q('#connectBtn')), labels: labels, setH4: ff(q('#setPop h4')),
                          slip: ff(q('#slipCustom')), walletPop: ff(q('#walletPop button')), walletOv: ff(q('#walletOv h3')) },
                 manrope: [...document.fonts].some(f => f.family.replace(/['"]/g, '') === 'Manrope' && f.status === 'loaded'),
                 ghosts: [...nav.querySelectorAll('span[data-t]')].map(e => getComputedStyle(e, '::after').content) }; }"""
    async def hid_open(vw, vh, path):
        pg = await b.new_page(viewport={"width": vw, "height": vh}, color_scheme="light")
        pg.on("pageerror", lambda e: errs.append("PAGEERROR %s" % e))
        await pg.add_init_script("localStorage.setItem(%s, %s);" % (_j.dumps(theme_key), _j.dumps("light")))
        async def hid_stub(route):
            u = route.request.url
            if not u.startswith(origin):
                return await route.abort()
            if "pairs.json" in u:
                return await route.fulfill(status=200, content_type="application/json", body='{"chain":"base","rows":[],"store":true}')
            if "/gt/" in u or "/vd/" in u or "/sol/" in u:
                return await route.fulfill(status=200, content_type="application/json", body="{}")
            if u.endswith("/ev"):
                return await route.fulfill(status=204, body="")
            return await route.continue_()
        await pg.route("**/*", hid_stub)
        await pg.goto(origin + path)
        await pg.wait_for_selector("#nav", timeout=10000)
        await pg.wait_for_timeout(900)
        await pg.evaluate("() => document.fonts.ready")
        return pg
    def hid_diff(a, ref, tol=0.5, skip=()):
        out = []
        for k in tuple(x for x in ("logo", "nav", "setBtn", "themeBtn", "connectBtn") if x not in skip):
            if a[k] is None or ref[k] is None or any(abs(u - v) > tol for u, v in zip(a[k], ref[k])):
                out.append("%s %s vs %s" % (k, a[k], ref[k]))
        if sorted(a["items"]) != sorted(ref["items"]):
            out.append("nav items %s vs %s" % (sorted(a["items"]), sorted(ref["items"])))
        for t, v in a["items"].items():
            if t in ref["items"] and any(abs(u - w) > tol for u, w in zip(v, ref["items"][t])):
                out.append("nav item %s %s vs %s" % (t, v, ref["items"][t]))
        if a["fonts"] != ref["fonts"]:
            out.append("computed font-family %s vs %s" % (a["fonts"], ref["fonts"]))
        return out
    HID_STATES = (("/app#swap", "app#swap"), ("/app#stocks", "app#stocks"), ("/app#flow", "app#flow"), ("/pairs", "pairs"), ("/report", "report"))
    hid_nav = {}
    for vw, vh in ((1906, 900), (1280, 800), (390, 844)):
        ref = None
        for path, name in HID_STATES:
            pg = await hid_open(vw, vh, path)
            m = await pg.evaluate(HID_JS)
            await pg.close()
            tag = "[header identical] %dx%d %s" % (vw, vh, name)
            assert m["connectTxt"] == "Connect wallet", "%s: the probe needs the 'Connect wallet' state, got %r" % (tag, m["connectTxt"])
            if name in ("pairs", "report"):
                assert m["manrope"], "%s: the embedded Manrope did not load, so this probe could not see a font difference" % tag
            if name == "app#swap":
                ref = m
            d = hid_diff(m, ref)
            assert not d, "%s differs from /app#swap: %s" % (tag, d)
            if vw >= 1121:
                assert m["ghosts"] and all(g not in ("none", "normal") for g in m["ghosts"]), "%s: the bold ghost is missing on a nav label: %s" % (tag, m["ghosts"])
            hid_nav[(vw, name)] = m["nav"][1]
    print("[header identical] 1906x900, 1280x800 and 390x844, light: logo, nav, every nav item, settings, theme and 'Connect wallet' (x and width, 0.5 px) and the computed font-family of nav, labels, popovers and the connect button are equal on /app (swap, stocks, flow), /pairs and /report; Manrope verified loaded on /pairs and /report; nav width 1906 app#swap %s vs report %s" % (hid_nav[(1906, "app#swap")], hid_nav[(1906, "report")]))

    # ---- [nav width stable] با عوض‌شدنِ تبِ فعال روی /app (Swap → Stocks → Flow) پهنای نوار و x هر آیتم ثابت می‌ماند ----
    for vw, vh in ((1906, 900), (1280, 800), (390, 844)):
        pg = await hid_open(vw, vh, "/app#swap")
        seq = []
        for step, js in (("swap", "() => document.querySelector('#nav button[data-view=\"swap\"]').click()"),
                         ("stocks", "() => document.querySelector('#nav button[data-view=\"stocks\"]').click()"),
                         ("flow", "() => { localStorage.setItem('zaexa.markets.v1', 'flow'); document.getElementById('navMarkets').click(); }")):
            await pg.evaluate(js)
            await pg.wait_for_timeout(500)
            on = await pg.evaluate("() => [...document.querySelectorAll('#nav .on, #nav #navMarkets[style]')].map(e => e.getAttribute('title') || e.id).join(',')")
            m = await pg.evaluate(HID_JS)
            seq.append((step, on, m))
        await pg.close()
        for step, on, m in seq[1:]:
            d = hid_diff(m, seq[0][2])
            assert not d, "[nav width stable] %dx%d: switching the active tab %s -> %s moved the header: %s" % (vw, vh, seq[0][0], step, d)
    print("[nav width stable] 1906x900, 1280x800 and 390x844: switching the active tab Swap -> Stocks -> Flow on /app leaves the nav width and every item x (0.5 px) unchanged")

    # ---- [markets switch] ۱۸ اکتبر — «Markets» تبِ ساده است؛ انتخاب بین Flow و New pairs سوییچِ بالای خودِ صفحه است.
    # کلید zaexa.markets.v1 («flow» یا «pairs»؛ هر چیزِ دیگر = pairs) تصمیم می‌گیرد کلیکِ تب کجا برود. ----
    MKT_KEY = "zaexa.markets.v1"
    mkt_shots = "/tmp/claude-0/mkt_shots"
    os.makedirs(mkt_shots, exist_ok=True)
    MS_JS = """() => {
        const sw = document.querySelector('.mktSwitch'); if (!sw) return null;
        const probe = document.createElement('div'); probe.style.cssText = 'color:var(--tx2);background:var(--card);position:absolute;left:-9999px';
        document.body.appendChild(probe); const pcs = getComputedStyle(probe), tx2 = pcs.color, card = pcs.backgroundColor; probe.remove();
        const cs = getComputedStyle(sw), r = sw.getBoundingClientRect();
        const links = [...sw.querySelectorAll('a')];
        const host = sw.parentElement;
        const title = document.querySelector('#view-flow .ttl, .pairs-main h1');
        const vis = links.map(a => { const c = getComputedStyle(a); return {t: a.textContent, href: a.getAttribute('href'), mkt: a.dataset.mkt, on: a.classList.contains('on'), cur: a.getAttribute('aria-current'),
            color: c.color, bg: c.backgroundColor, bgi: c.backgroundImage, pad: c.padding, fs: c.fontSize, fw: c.fontWeight, rad: c.borderRadius}; });
        const cb = document.getElementById('connectBtn');
        return {connect: cb ? getComputedStyle(cb).color : null, tag: sw.tagName, aria: sw.getAttribute('aria-label'), first: host.firstElementChild === sw, hostId: host.id || host.className,
                disp: cs.display, pad: cs.padding, gap: cs.columnGap, rad: cs.borderRadius, bg: cs.backgroundColor, card: card, tx2: tx2, sh: cs.boxShadow, mb: cs.marginBottom,
                links: vis, left: r.left, right: r.right, bottom: r.bottom, vw: innerWidth, sw: document.documentElement.scrollWidth,
                titleTop: title ? title.getBoundingClientRect().top : null, stored: (() => { try { return localStorage.getItem('zaexa.markets.v1'); } catch (e) { return 'ERR'; } })()};
    }"""
    for ms_page, ms_path, ms_on in (("app-flow", "/app#flow", "flow"), ("pairs", "/pairs", "pairs")):
        for ms_scheme in ("light", "dark"):
            for ms_vw, ms_vh in ((1440, 900), (390, 844)):
                pg = await hid_open(ms_vw, ms_vh, ms_path)
                await pg.evaluate("t => { document.documentElement.dataset.theme = t; }", ms_scheme)
                await pg.wait_for_timeout(300)
                m = await pg.evaluate(MS_JS)
                tag = "[markets switch] %s %s %dpx" % (ms_page, ms_scheme, ms_vw)
                assert m, "%s: no .mktSwitch on the page" % tag
                assert m["tag"] == "NAV" and m["aria"] == "Markets" and m["first"], "%s: the switch must be a <nav aria-label=Markets> and the first element of its page content (%s): %s" % (tag, m["hostId"], m)
                assert [(l["t"], l["href"], l["mkt"]) for l in m["links"]] == [("Flow", "/app#flow", "flow"), ("New pairs", "/pairs", "pairs")], "%s: links: %s" % (tag, m["links"])
                assert [l["on"] for l in m["links"]] == [ms_on == "flow", ms_on == "pairs"], "%s: wrong item carries .on: %s" % (tag, m["links"])
                assert [l["cur"] for l in m["links"]] == [("page" if ms_on == "flow" else None), ("page" if ms_on == "pairs" else None)], "%s: aria-current: %s" % (tag, m["links"])
                assert m["disp"] in ("inline-flex", "flex") and m["pad"] == "4px" and m["gap"] == "4px" and m["rad"] == "999px", "%s: container css: %s" % (tag, m)
                assert m["bg"] == m["card"] and m["mb"] == "18px" and m["sh"] not in ("none", ""), "%s: container background must be var(--card), margin-bottom 18px, with a shadow: %s" % (tag, m)
                for l in m["links"]:
                    assert l["pad"] == "8px 18px" and l["fs"] == "14px" and l["fw"] == "560" and l["rad"] == "999px", "%s: link metrics: %s" % (tag, l)
                    if l["on"]:
                        # ۲۵ اکتبر: متنِ قسمتِ فعال همان رنگِ دکمه‌ی «Connect wallet» است (--on-acc: روشن سفید، تیره تیره)، نه همیشه سفید
                        assert m["connect"] and l["color"] == m["connect"] and "gradient" in l["bgi"], "%s: the current item must use the same ink as the Connect wallet button on the CTA gradient: %s vs %s" % (tag, l, m["connect"])
                        assert (l["color"] == "rgb(255, 255, 255)") == (ms_scheme == "light"), "%s: white in light, dark ink in dark: %s" % (tag, l["color"])
                    else:
                        assert l["color"] == m["tx2"] and l["bgi"] == "none", "%s: an inactive item must use var(--tx2) and no fill: %s" % (tag, l)
                assert m["titleTop"] is None or m["bottom"] <= m["titleTop"], "%s: the switch must sit above the page title (%s vs %s)" % (tag, m["bottom"], m["titleTop"])
                assert m["stored"] == ms_on, "%s: visiting the page must store %r, got %r" % (tag, ms_on, m["stored"])
                assert m["left"] >= 0 and m["right"] <= m["vw"] and m["sw"] <= m["vw"], "%s: the switch overflows the viewport / page scrolls horizontally: %s" % (tag, m)
                await pg.screenshot(path=os.path.join(mkt_shots, "%s-%s-%d.png" % (ms_page, ms_scheme, ms_vw)))
                await pg.close()
    # کلیکِ تب: از اپ، /pairs و /report؛ انتخابِ ذخیره‌شده: flow، pairs، هیچ، و مقدارِ بی‌معنی
    async def ms_click(path, stored):
        pg = await hid_open(1440, 900, path)
        await pg.evaluate("() => { window.__noReload = 1; }")
        if stored == "none":
            await pg.evaluate("k => localStorage.removeItem(k)", MKT_KEY)
        else:
            await pg.evaluate("([k, v]) => localStorage.setItem(k, v)", [MKT_KEY, stored])
        await pg.click("#navMarkets")
        await pg.wait_for_timeout(1200)
        out = await pg.evaluate("() => ({path: location.pathname, hash: location.hash, noReload: window.__noReload === 1, flow: !!document.getElementById('view-flow') && document.getElementById('view-flow').classList.contains('on')})")
        await pg.close()
        return out
    for ms_from in ("/app#swap", "/pairs", "/report"):
        for ms_stored, ms_want in (("flow", "flow"), ("pairs", "pairs"), ("none", "pairs"), ("garbage", "pairs")):
            o = await ms_click(ms_from, ms_stored)
            tag = "[markets switch] Markets tab on %s with stored %s" % (ms_from, ms_stored)
            if ms_want == "flow":
                if ms_from == "/app#swap":
                    assert o["path"] == "/app" and o["hash"] == "#flow" and o["flow"] and o["noReload"], "%s: must switch to the Flow view in place (no reload): %s" % (tag, o)
                else:
                    assert o["path"] == "/app" and o["hash"] == "#flow", "%s: must navigate to /app#flow: %s" % (tag, o)
            else:
                if ms_from == "/pairs":
                    assert o["path"] == "/pairs" and o["noReload"], "%s: on /pairs it must do nothing: %s" % (tag, o)
                else:
                    assert o["path"] == "/pairs", "%s: must open /pairs: %s" % (tag, o)
    # کلیک روی آیتم‌های سوییچ: مقدار پیش از ناوبری نوشته می‌شود؛ Flow در اپ درجا عوض می‌کند
    pg = await hid_open(1440, 900, "/app#flow")
    await pg.evaluate("([k]) => { window.__noReload = 1; localStorage.setItem(k, 'pairs'); }", [MKT_KEY])
    await pg.click('.mktSwitch a[data-mkt="flow"]')
    await pg.wait_for_timeout(500)
    o = await pg.evaluate("([k]) => ({v: localStorage.getItem(k), nr: window.__noReload === 1, h: location.hash, flow: document.getElementById('view-flow').classList.contains('on')})", [MKT_KEY])
    assert o == {"v": "flow", "nr": True, "h": "#flow", "flow": True}, "[markets switch] the Flow link in the app must store flow and stay in place (no reload): %s" % o
    await pg.evaluate("""() => { const a = document.querySelector('.mktSwitch a[data-mkt="pairs"]');
        a.addEventListener('click', e => { window.__seen = localStorage.getItem('zaexa.markets.v1'); e.preventDefault(); }); }""")
    await pg.click('.mktSwitch a[data-mkt="pairs"]')
    assert await pg.evaluate("() => window.__seen") == "pairs", "[markets switch] the New pairs link must write 'pairs' before navigating"
    await pg.close()
    pg = await hid_open(1440, 900, "/pairs")
    await pg.evaluate("""() => { const a = document.querySelector('.mktSwitch a[data-mkt="flow"]');
        a.addEventListener('click', e => { window.__seen = localStorage.getItem('zaexa.markets.v1'); e.preventDefault(); }); }""")
    await pg.click('.mktSwitch a[data-mkt="flow"]')
    assert await pg.evaluate("() => window.__seen") == "flow", "[markets switch] the Flow link on /pairs must write 'flow' before navigating"
    await pg.close()
    # هیچ #navMenu / .navChev: در DOMِ هر سه صفحه و در متنِ سه فایل
    for ms_path in ("/app#flow", "/pairs", "/report"):
        pg = await hid_open(1440, 900, ms_path)
        n = await pg.evaluate("() => document.querySelectorAll('#navMenu, .navChev, .navMenuWrap, [aria-haspopup=\"menu\"]#navMarkets').length")
        await pg.close()
        assert n == 0, "[markets switch] %s still has a navMenu/navChev/navMenuWrap in the DOM" % ms_path
    for ms_file in (os.path.join(HERE, "..", "index.html"), os.path.join(HERE, "..", "pairs.html"), os.path.join(HERE, "..", "..", "worker", "report_page.js")):
        ms_src = open(ms_file, encoding="utf-8").read()
        for ms_bad in ("navMenu", "navChev", "closeNavMenu"):
            assert ms_bad not in ms_src, "[markets switch] %s still contains %r" % (os.path.basename(ms_file), ms_bad)
    print("[markets switch] /app Flow view and /pairs carry the same segmented switch as the first element (light + dark, 1440 + 390: current item white on the gradient, others var(--tx2), no overflow, above the title), "
          "visiting stores flow/pairs, the Markets tab opens Flow for stored flow and /pairs for pairs/none/garbage (in place on /app, navigation from /pairs and /report, nothing on /pairs), switch clicks store before navigating and Flow stays in place, "
          "no navMenu/navChev in the DOM or the source of the three files; screenshots in %s" % mkt_shots)

    ROWS_JS = "() => document.querySelectorAll('#tb tr').length"
    CHIP_JS = """() => Object.fromEntries([...document.querySelectorAll('#filters .chip')].map(c =>
        [c.dataset.g + ':' + c.dataset.k, +c.querySelector('span').textContent]))"""

    # ---- [report header desktop] هدرِ اپ روی دسکتاپ: نوارِ تب داخلِ هدر (نه fixed)، چسبان، بدونِ همبرگر ----
    HDRDOM_JS = """() => { const nav = document.getElementById('nav'), cs = getComputedStyle(nav), hd = document.querySelector('header');
        const t = e => (e.getAttribute('title') || (e.querySelector('button') || {getAttribute: () => ''}).getAttribute('title'));
        return { nav: cs.display, pos: cs.position, hdPos: getComputedStyle(hd).position, hdCls: hd.className, hdZ: getComputedStyle(hd).zIndex,
                 titles: [...nav.children].map(e => e.getAttribute('title')),
                 labels: [...nav.querySelectorAll(':scope > a, :scope button')].map(e => e.textContent.trim()),
                 spans: [...nav.querySelectorAll(':scope > a > span')].map(e => getComputedStyle(e).display),
                 on: [...nav.querySelectorAll(':scope > a.on')].map(e => [e.textContent.trim(), e.getAttribute('aria-current'), e.getAttribute('href')]),
                 gone: ['.landing-header', '.desktop-nav', '#menuToggle', '.mobile-menu', '#mobileMenu', '#themeToggle', '.header-cta', '.navSoon', '.soonPill'].filter(q => document.querySelector(q)),
                 ids: ['setBtn', 'setPop', 'themeBtn', 'connectBtn', 'walletMenu', 'walletPop', 'navMarkets', 'walletOv'].filter(i => !document.getElementById(i)),
                 menu: document.querySelectorAll('#navMenu, .navChev, .navMenuWrap').length,
                 stocks: (document.querySelector('#nav a[href="/app#stocks"]') || {}).tagName || null }; }"""
    pg = await open_report(1440, 900)
    d = await pg.evaluate(HDRDOM_JS)
    assert d["nav"] == "flex" and d["pos"] != "fixed", "[report header desktop] at 1440 the tab bar sits in the header, not fixed: %s" % d
    assert d["hdPos"] == "sticky" and d["hdZ"] == "30" and "site-header" in d["hdCls"], "[report header desktop] the header must be sticky with z-index 30: %s" % d
    assert d["labels"] == ["Swap", "Markets", "Stocks", "Exit Report"], "[report header desktop] tab order must be Swap, Markets, Stocks, Exit Report: %s" % d["labels"]
    assert d["titles"] == ["Swap", "Markets", "Stocks", "Exit Report"], "[report header desktop] tab titles: %s" % d["titles"]
    assert d["on"] == [["Exit Report", "page", "/report"]], "[report header desktop] only Exit Report is active (aria-current=page): %s" % d["on"]
    assert d["stocks"] == "A", "[report header desktop] Stocks is a real link to /app#stocks (no Soon span): %s" % d["stocks"]
    assert d["menu"] == 0, "[report header desktop] Markets is a plain tab now: no #navMenu, .navChev or .navMenuWrap in the DOM (%s found)" % d["menu"]
    assert not d["gone"], "[report header desktop] the landing header leftovers must be gone from the DOM: %s" % d["gone"]
    assert not d["ids"], "[report header desktop] app-header ids missing: %s" % d["ids"]
    await pg.evaluate("() => window.scrollTo(0, 500)")
    await pg.wait_for_timeout(450)
    st = await pg.evaluate("() => ({ top: document.querySelector('header').getBoundingClientRect().top, cls: document.querySelector('header').className, sy: scrollY, bf: getComputedStyle(document.querySelector('header')).backdropFilter, tf: getComputedStyle(document.querySelector('header')).transform })")
    assert st["sy"] > 100 and abs(st["top"]) <= 0.5 and "scrolled" in st["cls"], "[report header desktop] after scrolling the header stays at the top and gets .scrolled: %s" % st
    assert st["bf"] == "none" and st["tf"] == "none", "[report header desktop] no backdrop-filter/transform on the <header> itself: %s" % st
    await pg.close()
    pg = await open_report(800, 900)
    d = await pg.evaluate(HDRDOM_JS)
    assert d["nav"] == "flex" and d["pos"] != "fixed" and set(d["spans"]) == {"none"}, "[report header desktop] at 800 the bar stays in the header with icons only: %s" % d
    await pg.close()
    print("[report header desktop] 1440: sticky app header (z 30, .scrolled glass on scroll, no filter/transform on the element), tab bar in the header in the order Swap, Markets, Stocks, Exit Report with only Exit Report active, Stocks a real link, Markets a plain tab (no menu/chevron); 800: icons only; no landing-header/hamburger/mobile-menu/Soon left")

    # ---- [report page render] روشن و تیره، دو اندازه ----
    for scheme in ("light", "dark"):
        for vw, vh in ((1440, 900), (390, 844)):
            pg = await open_report(vw, vh, scheme)
            info = await pg.evaluate("""() => ({
                theme: document.documentElement.dataset.theme,
                bg: getComputedStyle(document.body).backgroundColor,
                h1: document.getElementById('h1').textContent,
                baseTiles: document.querySelectorAll('#top .chain:nth-of-type(1) .tile').length,
                allTiles: document.querySelectorAll('.tile').length,
                cols: document.querySelectorAll('svg.chart a.col').length,
                header: !!document.querySelector('header.site-header #nav a.on[href="/report"]'),
                font: getComputedStyle(document.body).fontFamily.slice(0, 20),
                gradClip: getComputedStyle(document.querySelector('h1 em')).webkitBackgroundClip,
                shown: document.querySelectorAll('#tb tr').length })""")
            assert info["theme"] == scheme, "[report page render] theme %s expected, got %s" % (scheme, info["theme"])
            assert info["h1"] == "Exit Report, 4 Oct", "[report page render] h1: %r" % info["h1"]
            assert info["allTiles"] == 7 and info["cols"] == 14 and info["header"], "[report page render] structure: %s" % info
            assert info["shown"] == 25, "[report page render] first 25 rows, got %s" % info["shown"]
            dark_bg = info["bg"] == "rgb(10, 8, 16)"
            assert dark_bg == (scheme == "dark"), "[report page render] body background %s in %s" % (info["bg"], scheme)
            await pg.screenshot(path=os.path.join(shots, "report-%s-%d.png" % (scheme, vw)), full_page=True)
            await pg.close()
    print("[report page render] light and dark at 1440 and 390: theme token applied, background %s/%s, 7 tiles, 14 chart links, 25 rows first; real page %d bytes served under the web/_headers CSP"
          % ("rgb(244, 245, 247)", "rgb(10, 8, 16)", meta["bytes"]))

    # ---- [report page overflow] ----
    for vw in (360, 390, 1440):
        pg = await open_report(vw, 900)
        m = await pg.evaluate("""() => { const w = document.querySelector('.tblwrap'), t = document.querySelector('.tblwrap table');
            const lefts = new Set([...document.querySelectorAll('.tiles')][0] ? [...document.querySelectorAll('.tiles')[0].children].map(e => Math.round(e.getBoundingClientRect().left)) : []);
            return { sw: document.documentElement.scrollWidth, bw: document.body.scrollWidth, iw: innerWidth, wrapScroll: w.scrollWidth, wrapClient: w.clientWidth,
                     ov: getComputedStyle(w).overflowX, tableW: t.getBoundingClientRect().width, tileCols: lefts.size }; }""")
        assert m["sw"] <= m["iw"] and m["bw"] <= m["iw"], "[report page overflow] page scrolls horizontally at %d: %s" % (vw, m)
        if vw <= 390:
            assert m["wrapScroll"] > m["wrapClient"] and m["ov"] == "auto", "[report page overflow] the table must scroll inside .tblwrap at %d: %s" % (vw, m)
            assert m["tileCols"] == 2, "[report page overflow] tiles must be 2 columns at %d: %s" % (vw, m)
        else:
            assert m["tileCols"] == 4, "[report page overflow] Base tiles are 4 columns at 1440: %s" % m
        await pg.close()
    print("[report page overflow] 360/390/1440: no page-level horizontal scroll; at phone widths the table scrolls inside .tblwrap and the tiles are 2 columns")

    # ---- [report page filters] + «Show more» ----
    pg = await open_report(1440, 900)
    chips = await pg.evaluate(CHIP_JS)
    assert chips["c:all"] == meta["all"]["all"] and chips["c:base"] == meta["base"]["all"] and chips["c:solana"] == meta["solana"]["all"], "[report page filters] chain chips %s vs %s" % (chips, meta)
    assert chips["r:nosell"] == meta["all"]["nosell"] and chips["r:sell"] == meta["all"]["sell"] and chips["r:na"] == meta["all"]["na"] and chips["r:empty"] == meta["all"]["empty"], "[report page filters] result chips %s vs %s" % (chips, meta["all"])
    assert meta["solana"]["nosell"] == 0, "[report page filters] the guard must have removed every Solana nosell from the fixture"
    total = meta["all"]["all"]
    more_txt = await pg.inner_text("#more")
    assert more_txt == "Show 50 more of %d" % (total - 25), "[report page filters] button: %r" % more_txt
    shown = 25
    while total - shown > 0:
        await pg.click("#more")
        shown = min(total, shown + 50)
        assert await pg.evaluate(ROWS_JS) == shown, "[report page filters] Show more must reveal 50 at a time, expected %d" % shown
    assert await pg.evaluate("() => document.getElementById('more').hidden"), "[report page filters] the button hides when everything is shown"
    await pg.click('#filters [data-g="c"][data-k="solana"]')
    assert await pg.evaluate(ROWS_JS) == min(25, meta["solana"]["all"]), "[report page filters] Solana chip row count (first 25, then Show more)"
    assert await pg.inner_text("#more") == "Show %d more of %d" % (min(50, meta["solana"]["all"] - 25), meta["solana"]["all"] - 25), "[report page filters] Solana chip: Show more counts the remainder"
    chips = await pg.evaluate(CHIP_JS)
    assert chips["r:empty"] == 0 and chips["r:nosell"] == 0 and chips["r:na"] == meta["solana"]["na"], "[report page filters] result chips follow the chain chip: %s" % chips
    await pg.click('#filters [data-g="r"][data-k="na"]')
    n_na = await pg.evaluate(ROWS_JS)
    assert n_na == meta["solana"]["na"], "[report page filters] Solana + not checked: %d" % n_na
    reasons = await pg.evaluate("() => [...document.querySelectorAll('#tb .why')].map(e => e.textContent)")
    assert len(reasons) == n_na and all(r and ":" not in r and r[-1] == "." for r in reasons), "[report page filters] each unchecked row shows a plain sentence: %s" % reasons
    await pg.click('#filters [data-g="c"][data-k="base"]')
    await pg.click('#filters [data-g="r"][data-k="nosell"]')
    rows_txt = await pg.evaluate("() => [...document.querySelectorAll('#tb tr td:nth-child(2)')].map(e => e.textContent)")
    assert len(rows_txt) == meta["base"]["nosell"] and any("pool is empty" in t for t in rows_txt) and any("the sell reverts" in t for t in rows_txt), "[report page filters] nosell rows carry the cause in words: %s" % rows_txt
    await pg.click('#filters [data-g="r"][data-k="empty"]')
    follow = await pg.evaluate("() => [...document.querySelectorAll('#tb tr td:nth-child(5)')].map(e => e.textContent)")
    assert len(follow) == meta["base"]["empty"] and all(t.startswith("⚠ Pool empty 2 h later") for t in follow), "[report page filters] follow-up column: %s" % follow
    await pg.click('#filters [data-g="r"][data-k="all"]')
    await pg.click('#filters [data-g="c"][data-k="all"]')
    await pg.close()
    print("[report page filters] chain and result chips change the row counts (%d/%d/%d chain, result chips from the guarded rows), 'Show more' reveals 50 at a time and hides at the end, unchecked rows show a plain reason, no-sell rows carry the cause, follow-up column says 'Pool empty 2 h later'"
          % (meta["all"]["all"], meta["base"]["all"], meta["solana"]["all"]))

    # ---- [report page xss] ----
    pg = await open_report(1440, 900)
    await pg.click('#filters [data-g="c"][data-k="base"]')
    await pg.click('#filters [data-g="r"][data-k="sell"]')
    while await pg.evaluate("() => !document.getElementById('more').hidden"):
        await pg.click("#more")
    cells = await pg.evaluate("() => [...document.querySelectorAll('#tb .nm')].map(e => e.textContent)")
    assert "</script><img src=x onerror=window.__xss=1>" in cells, "[report page xss] the hostile name must show as plain text"
    assert await pg.evaluate("() => window.__xss === undefined && !document.querySelector('#tb img') && !document.querySelector('#tb b')"), "[report page xss] nothing injected ran or rendered"
    await pg.close()
    print("[report page xss] a token named </script><img onerror=...> and a <b> symbol render as text only; no handler ran")

    # ---- [report page symbol+ret+solana-hidden] ----
    pg = await open_report(1440, 900)
