# ۲۱ اکتبر — تابلوی «Where money is flowing»، کارت «Early buyers» و حکمِ صادرکننده برای توکن‌های سهام.
# هر کاوشگر یک تابع جداست تا با ZX_ONLY=<نام تابع> تنها همان اجرا شود (برای شکستنِ عمدیِ نگهبان‌ها).
# فیکسچرها شکلِ واقعیِ GeckoTerminal را دارند: حجم/ذخیره/مقدار توکن *رشته*، شمارِ معاملات *عدد*.
# =====================================================================
import functools as _fbft, http.server as _fbhttp, threading as _fbth, json as _fbj
from datetime import datetime as _fbdt, timedelta as _fbtd, timezone as _fbtz

FB_BAD_RE = re.compile(r"NaN|undefined|\$0\.00|Infinity|\[object")
FB_PNG = base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==")
FB_SOL_USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"
FB_SOL_WSOL = "So11111111111111111111111111111111111111112"


def fb_iso(sec_ago):
    t = _fbdt.now(_fbtz.utc) - _fbtd(seconds=sec_ago)
    return t.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (t.microsecond // 1000)


def fb_serve():
    class Quiet(_fbhttp.SimpleHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def translate_path(self, path):
            clean = path.split("?")[0]
            if clean in ("/app", "/app/"):
                return os.path.join(HERE, "harness.html")
            if clean == "/stub-ethers.js":
                return os.path.join(HERE, "stub-ethers.js")
            return super().translate_path(path)
    srv = _fbhttp.ThreadingHTTPServer(("127.0.0.1", 0), _fbft.partial(Quiet, directory=os.path.join(HERE, "..")))
    _fbth.Thread(target=srv.serve_forever, daemon=True).start()
    return srv, "http://127.0.0.1:%d" % srv.server_address[1]


def fb_b58(i, n=44):
    A = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
    s = ""
    x = i + 1
    while x:
        x, r = divmod(x, 58)
        s = A[r] + s
    return (s + "z" * n)[:n] if len(s) < n else s


def fb_evm(i):
    return "0x" + "%040x" % i


class FbEnv:
    """صفحه‌ی اپ روی سرور محلی؛ pairs.json و GT از فیکسچر. calls = (مسیرِ GT) به ترتیب."""

    def __init__(self, b, origin, errs):
        self.b, self.origin, self.errs = b, origin, errs
        self.pairs = {"status": 200, "body": {"store": True, "rows": []}, "delay": 0}
        self.gt = lambda path: None            # path -> (status, obj) | None (= {"data": []})
        self.rpc = None
        self.calls, self.pairs_calls = [], []

    async def open(self, hash_="#flow", vw=1280, vh=900, scheme="dark", board=True, init=None, path="/app"):
        ctx = await self.b.new_context(viewport={"width": vw, "height": vh}, color_scheme=scheme)
        pg = await ctx.new_page()
        pg._zx_board = board
        pg.on("pageerror", lambda e: self.errs.append("PAGEERROR %s" % e))
        pg.on("console", lambda m: self.errs.append("CONSOLE %s" % m.text) if m.type == "error" and
              "Failed to load resource" not in m.text else None)
        for sc in (init or []):
            await pg.add_init_script(sc)

        async def ok(route, body, status=200):
            await route.fulfill(status=status, content_type="application/json",
                                headers={"access-control-allow-origin": "*", "x-zaexa-proxy": "t"}, body=body)

        async def handler(route):
            u = route.request.url
            clean = u.split("?")[0]
            if u.startswith(self.origin):
                rest = clean[len(self.origin):]
                if rest == "/pairs.json":
                    self.pairs_calls.append(u)
                    if self.pairs["delay"]:
                        await asyncio.sleep(self.pairs["delay"])
                    return await ok(route, _fbj.dumps(self.pairs["body"]), self.pairs["status"])
                if rest == "/ev":
                    return await route.fulfill(status=204, body="")
                if rest.startswith("/vd/"):
                    return await ok(route, '{"v":"sell","ms":100}')
                if rest.startswith("/sol/"):
                    if rest.endswith("/rpc") and self.rpc:
                        pl = _fbj.loads(route.request.post_data or "{}")
                        return await ok(route, _fbj.dumps({"result": self.rpc(pl.get("method"), pl.get("params"))}))
                    return await ok(route, '{"result":null}')
                if rest.startswith("/gt/"):
                    gp = u.split("/gt/", 1)[1]
                else:
                    return await route.continue_()
            elif u.startswith("https://api.geckoterminal.com/api/v2/"):
                gp = u.split("/api/v2/", 1)[1]
            elif u.startswith("https://assets.geckoterminal.com/"):
                return await route.fulfill(status=200, content_type="image/png", body=FB_PNG)
            else:
                return await route.abort()
            self.calls.append(gp)
            r = self.gt(gp.split("?")[0])
            if r is None:
                return await ok(route, '{"data":[]}')
            return await ok(route, _fbj.dumps(r[1]), r[0])

        await pg.route("**/*", handler)
        await pg.goto(self.origin + path + hash_)
        return pg


# ---------- فیکسچرهای تابلو ----------
def fb_tok(addr, sym, pool, net="base", img=None):
    return {"id": "%s_%s" % (net, addr), "type": "token",
            "attributes": {"address": addr, "symbol": sym, "image_url": img or "missing.png"},
            "relationships": {"top_pools": {"data": [{"id": "%s_%s" % (net, pool), "type": "pool"}]}}}


def fb_pool(pool, h1, h6, net="base"):
    def w(t):
        return {"buys": t[2], "sells": t[3], "buyers": t[0], "sellers": t[1]}
    return {"id": "%s_%s" % (net, pool), "type": "pool", "attributes": {
        "address": pool, "reserve_in_usd": "250000.5",
        "volume_usd": {"h1": h1[4], "h6": h6[4]},
        "transactions": {"h1": w(h1), "h6": w(h6)}}}


# (buyers, sellers, buys, sells, volume-string)
FB_ROWS = [
    # sym, v, created sec ago, h1, h6
    ("ALPHA", "sell", 30 * 60, (48, 14, 90, 27, "12400"), (120, 70, 300, 200, "98000")),
    ("BETA", "sell", 2 * 3600 + 1200, (30, 36, 40, 60, "850.2"), (80, 20, 200, 50, "5000")),
    ("GAMMA", "sell", 3 * 86400 + 4 * 3600, (10, 10, 12, 12, "0"), (15, 40, 20, 70, "120")),
    ("DELTA", "nosell", 40 * 60, (99, 1, 150, 2, "250000"), (200, 10, 500, 30, "900000")),
    ("EPS", None, 50 * 60, (55, 5, 70, 9, "3100000"), (150, 100, 400, 300, "7000000")),
    ("ZETA", "sell", 5 * 3600, None, None),          # استخرش در pools/multi نیست
]


def fb_fixture(net="base", rows=None, hostile_eps=True):
    rows = rows or FB_ROWS
    mk = (lambda i: fb_evm(0xA00 + i)) if net == "base" else (lambda i: fb_b58(0xA00 + i))
    pools = lambda i: (fb_evm(0xB00 + i) if net == "base" else fb_b58(0xB00 + i))
    prow, toks, pls = [], [], []
    for i, (sym, v, ago, h1, h6) in enumerate(rows):
        a = mk(i)
        shown = "<img src=x onerror=1>" if (hostile_eps and sym == "EPS") else sym
        prow.append({"chain": net, "address": a, "symbol": shown, "name": "N" + sym, "v": v,
                     "checkKind": "roundtrip", "checkedAt": fb_iso(300 + i * 60), "poolCreatedAt": fb_iso(ago),
                     "dex": "uniswap-v3"})
        img = {"ALPHA": "https://assets.geckoterminal.com/alpha.png", "BETA": "http://evil.example/x.png"}.get(sym)
        toks.append(fb_tok(a, sym, pools(i), net, img))
        if h1:
            pls.append(fb_pool(pools(i), h1, h6, net))
    return prow, toks, pls, mk, pools


def fb_gt_for(toks, pls, net="base", pools_status=200, tokens_status=200):
    def gt(path):
        if "/tokens/multi/" in path:
            want = path.split("/tokens/multi/")[1].split(",")
            return (tokens_status, {"data": [t for t in toks if t["attributes"]["address"] in want]})
        if "/pools/multi/" in path:
            want = path.split("/pools/multi/")[1].split(",")
            return (pools_status, {"data": [p for p in pls if p["attributes"]["address"] in want]})
        return None
    return gt


FB_TBL_JS = """() => [...document.querySelectorAll('#flowBody .fbRow')].map(r => {
    // ستون ۰ = ستاره
    const c = r.children, cs = x => getComputedStyle(x).color;
    return {sym: r.querySelector('.fbTkTx b').textContent, age: r.querySelector('.fbAge').textContent,
            net: c[2].textContent.trim(), netColor: cs(c[2].firstElementChild || c[2]),
            bs: c[3].textContent.trim(), share: c[4].textContent.trim(), bar: !!c[4].querySelector('.fbBar'),
            vol: c[5].textContent.trim(), chip: c[6].textContent.trim(), title: c[6].firstElementChild.title,
            chipCls: c[6].firstElementChild.className, img: !!r.querySelector('.fbAv img')};
})"""


async def fb_wait_rows(pg, n=None, timeout=20000):
    await pg.wait_for_function(
        "(n) => { const r = document.querySelectorAll('#flowBody .fbRow'); return n === null ? r.length > 0 : r.length === n; }",
        arg=n, timeout=timeout)


async def fb_color(pg, var):
    return await pg.evaluate("""(v) => { const t = document.createElement('i'); t.style.color = 'var(' + v + ')';
        document.body.appendChild(t); const c = getComputedStyle(t).color; t.remove(); return c; }""", var)


async def check_flow_board(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    try:
        env = FbEnv(b, origin, errs)
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)

        # ---- loading: 6 skeleton rows while pairs.json is slow ----
        env.pairs["delay"] = 1.5
        pg = await env.open()
        await pg.wait_for_selector("#flowBody .skRow", timeout=8000)
        sk = await pg.evaluate("() => document.querySelectorAll('#flowBody .skRow').length")
        assert sk == 6, "[flow board] loading state must show 6 skeleton rows, got %d" % sk
        await pg.context.close()
        env.pairs["delay"] = 0

        # ---- default: toggle ON, 1h ----
        env.calls.clear(); env.pairs_calls.clear()
        pg = await env.open()
        await fb_wait_rows(pg)
        head = await pg.evaluate("() => [document.querySelector('.fbTtl').textContent, document.querySelector('.fbSub').textContent, document.querySelector('.fbTog').getAttribute('aria-checked'), document.querySelector('.fbTog').textContent, [...document.querySelectorAll('[data-fbw]')].map(x => x.textContent + (x.classList.contains('on') ? '*' : ''))]")
        assert head == ["Where money is flowing", "New Base pairs · last hour · by unique wallets", "true", "Only tokens with a sell route", ["1h*", "6h"]], "[flow board] header: %s" % head
        tms = [c for c in env.calls if "/tokens/multi/" in c and "include=top_pools" in c]
        assert len(tms) == 1 and len([c for c in env.calls if "/pools/multi/" in c]) == 1, \
            "[flow board] exactly one tokens/multi and one pools/multi for the board: %s" % env.calls
        assert tms[0].endswith("?include=top_pools"), "[flow board] tokens/multi must ask include=top_pools: %s" % tms[0]
        rows = await pg.evaluate(FB_TBL_JS)
        want_syms = ["ALPHA", "GAMMA", "BETA", "ZETA"]
        assert [r["sym"] for r in rows] == want_syms, "[flow board] toggle ON, 1h: net buyers desc, unknown last, only sell rows: %s" % [r["sym"] for r in rows]
        by = {r["sym"]: r for r in rows}
        assert (by["ALPHA"]["net"], by["ALPHA"]["bs"], by["ALPHA"]["share"], by["ALPHA"]["vol"], by["ALPHA"]["age"]) == ("+34", "48 / 14", "77%", "$12.4K", "<1h"), by["ALPHA"]
        assert (by["BETA"]["net"], by["BETA"]["bs"], by["BETA"]["share"], by["BETA"]["vol"], by["BETA"]["age"]) == ("-6", "30 / 36", "40%", "$850", "2h"), by["BETA"]
        assert (by["GAMMA"]["net"], by["GAMMA"]["bs"], by["GAMMA"]["share"], by["GAMMA"]["vol"], by["GAMMA"]["age"]) == ("0", "10 / 10", "50%", "$0", "3d"), by["GAMMA"]
        z = by["ZETA"]
        assert (z["net"], z["bs"], z["share"], z["vol"], z["bar"]) == ("—", "— / —", "—", "—", False), "[flow board] a row without activity shows dashes, never 0: %s" % z
        pos, neg, tx2 = await fb_color(pg, "--pos"), await fb_color(pg, "--neg"), await fb_color(pg, "--tx2")
        assert (by["ALPHA"]["netColor"], by["BETA"]["netColor"], by["GAMMA"]["netColor"]) == (pos, neg, tx2), "[flow board] net colours --pos/--neg/--tx2: %s" % [r["netColor"] for r in rows]
        assert all(r["chip"] == "Sell route quoted" and r["chipCls"].endswith(" p") for r in rows), "[flow board] toggle ON: only sell chips: %s" % [r["chip"] for r in rows]
        assert re.match(r"^Checked \d+m ago$", by["ALPHA"]["title"]), "[flow board] chip title: %r" % by["ALPHA"]["title"]
        assert by["ALPHA"]["img"] and not by["BETA"]["img"], "[flow board] only the https image_url becomes a logo (BETA has an http one): %s" % [(r["sym"], r["img"]) for r in rows]
        geo = await pg.evaluate("() => { const a = document.querySelector('.fbAv').getBoundingClientRect(); const bar = document.querySelector('.fbBar').getBoundingClientRect(); return [a.width, a.height, bar.height]; }")
        assert geo == [28, 28, 4], "[flow board] avatar 28px, bar 4px: %s" % geo
        txt = await pg.inner_text("#flowBody")
        assert not FB_BAD_RE.search(txt), "[flow board] bad text in the board: %r" % FB_BAD_RE.search(txt).group(0)
        assert "Counts are GeckoTerminal's pool totals for the window. Net buyers = unique buyers − unique sellers. Not a recommendation." in txt, "[flow board] footer note"
        assert await pg.evaluate("() => document.getElementById('flowTfs').offsetParent === null && document.getElementById('flowBackRow').hidden"), \
            "[flow board] the 5-window switch is hidden and there is no Back link on the board"

        # ---- toggle OFF: everything, with Unknown / No sell route chips ----
        await pg.click(".fbTog")
        await pg.wait_for_function("() => document.querySelectorAll('#flowBody .fbRow').length === 6")
        rows = await pg.evaluate(FB_TBL_JS)
        by = {r["sym"]: r for r in rows}
        assert [r["sym"] for r in rows] == ["DELTA", "0x0000…0a04", "ALPHA", "GAMMA", "BETA", "ZETA"], "[flow board] toggle OFF order (the hostile symbol falls back to the short address): %s" % [r["sym"] for r in rows]
        assert [r["net"] for r in rows] == ["+98", "+50", "+34", "0", "-6", "—"], "[flow board] toggle OFF: sorted by net buyers, unknown last: %s" % [r["net"] for r in rows]
        assert by["DELTA"]["chip"] == "No sell route" and by["DELTA"]["chipCls"].endswith(" n"), by["DELTA"]
        unk = [r for r in rows if r["chip"] == "Unknown"]
        assert len(unk) == 1 and not unk[0]["chipCls"].endswith(" p") and not unk[0]["chipCls"].endswith(" n"), "[flow board] v=null -> neutral Unknown chip: %s" % unk
        assert await pg.evaluate("() => !document.querySelector('#flowBody img[src=\"x\"]') && document.querySelectorAll('#flowBody table img').length <= 1"), "[flow board] hostile symbol must not create an element"
        stored = await pg.evaluate("() => localStorage.getItem('zaexa.flowboard.v1')")
        assert _fbj.loads(stored) == {"only": False, "w": "h1"}, "[flow board] the toggle is remembered: %r" % stored

        # ---- 6h changes the numbers ----
        await pg.click('[data-fbw="h6"]')
        await pg.wait_for_function("() => document.querySelector('.fbSub').textContent.includes('last 6 hours')")
        rows6 = await pg.evaluate(FB_TBL_JS)
        by6 = {r["sym"]: r for r in rows6}
        assert [r["net"] for r in rows6] == ["+190", "+60", "+50", "+50", "-25", "—"], "[flow board] 6h net buyers (a tie falls to volume): %s" % [r["net"] for r in rows6]
        assert [r["sym"] for r in rows6][2:4] == ["0x0000…0a04", "ALPHA"], "[flow board] net-buyer tie -> larger volume first: %s" % [r["sym"] for r in rows6]
        assert (by6["ALPHA"]["net"], by6["ALPHA"]["bs"], by6["ALPHA"]["share"], by6["ALPHA"]["vol"]) == ("+50", "120 / 70", "60%", "$98.0K"), "[flow board] 6h numbers: %s" % by6["ALPHA"]
        assert by6["ALPHA"]["net"] != by["ALPHA"]["net"], "[flow board] the 6h window must change the numbers"
        sub = await pg.inner_text(".fbSub")
        assert sub == "New Base pairs · last 6 hours · by unique wallets", sub
        assert not FB_BAD_RE.search(await pg.inner_text("#flowBody")), "[flow board] 6h: bad text"
        assert _fbj.loads(await pg.evaluate("() => localStorage.getItem('zaexa.flowboard.v1')")) == {"only": False, "w": "h6"}
        # ---- window and toggle survive a reload ----
        await pg.reload()
        await fb_wait_rows(pg, 6)
        st = await pg.evaluate("() => [document.querySelector('.fbTog').getAttribute('aria-checked'), document.querySelector('[data-fbw].on').textContent]")
        assert st == ["false", "6h"], "[flow board] reload restores toggle and window: %s" % st
        # ---- toggle ON with zero sell rows: explicit message + Show all ----
        none_rows = [r for r in prow if r["v"] != "sell"]
        env.pairs["body"] = {"store": True, "rows": none_rows}
        await pg.evaluate("() => localStorage.setItem('zaexa.flowboard.v1', JSON.stringify({only: true, w: 'h1'}))")
        await pg.reload()
        await pg.wait_for_selector("[data-fbshowall]", timeout=20000)
        msg = await pg.inner_text("#flowBody .fbMsg")
        assert "No new pair has a quoted sell route in this list right now." in msg, "[flow board] zero sell rows: %r" % msg
        await pg.click("[data-fbshowall]")
        await fb_wait_rows(pg, len(none_rows))
        assert await pg.evaluate("() => document.querySelector('.fbTog').getAttribute('aria-checked')") == "false"
        # یادداشتِ «استخرِ همین توکن» زیرِ تابلو نباید دیده شود
        assert await pg.evaluate("() => { const n=document.querySelector('#view-flow > p'); return !n || getComputedStyle(n).display==='none'; }"), "[flow board] per-token note visible under the board"
        await pg.context.close()
        print("[flow board] Base board: 6 skeleton rows while loading, one tokens/multi (include=top_pools) + one pools/multi, toggle ON shows only sell rows sorted by net buyers (+34, 0, -6, then the row without activity as dashes), toggle OFF adds No sell route / Unknown chips, 6h changes every number, exact header/footer/cells/colours, https-only logos, no NaN/undefined/$0.00, choices survive a reload, zero sell rows -> message + Show all")
    finally:
        await b.close()
        srv.shutdown()


async def check_flow_board_gt_down(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    try:
        env = FbEnv(b, origin, errs)
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        # pools/multi 500: ردیف‌ها و چیپِ Exit می‌مانند، عددها «—»
        env.gt = fb_gt_for(toks, pls, pools_status=500)
        pg = await env.open()
        await fb_wait_rows(pg, 4, timeout=30000)
        await pg.wait_for_selector("#flowBody .fnote", timeout=5000)
        rows = await pg.evaluate(FB_TBL_JS)
        assert [r["sym"] for r in rows].count("ALPHA") == 1, "[flow board gt down] tokens still listed: %s" % [r["sym"] for r in rows]
        assert all(r["net"] == "—" and r["bs"] == "— / —" and r["share"] == "—" and r["vol"] == "—" for r in rows), "[flow board gt down] every number must be a dash: %s" % rows
        assert all(r["chip"] == "Sell route quoted" for r in rows), "[flow board gt down] Exit chips stay"
        txt = await pg.inner_text("#flowBody")
        assert "Market activity is unavailable right now — unknown, not zero." in txt, "[flow board gt down] note: %r" % txt[-200:]
        assert not FB_BAD_RE.search(txt) and "$0" not in txt, "[flow board gt down] bad text %r" % FB_BAD_RE.search(txt)
        assert await pg.evaluate("() => document.querySelector('.fbAv img') !== null"), "[flow board gt down] logos from tokens/multi still show"
        await pg.context.close()
        # tokens/multi 500
        env.gt = fb_gt_for(toks, pls, tokens_status=500)
        pg = await env.open()
        await fb_wait_rows(pg, 4, timeout=30000)
        rows = await pg.evaluate(FB_TBL_JS)
        assert all(r["net"] == "—" for r in rows) and "unavailable right now" in await pg.inner_text("#flowBody"), "[flow board gt down] tokens/multi down: %s" % rows
        await pg.context.close()
        # شمارهای خراب/غایب در پاسخِ *موفق*: همه «—»، هرگز ۰
        one = [("QQQ", "sell", 600, None, None)]
        prow1, toks1, _p, mk1, pools1 = fb_fixture(rows=one)
        bad_pool = {"id": "base_" + pools1(0), "type": "pool", "attributes": {"address": pools1(0), "volume_usd": {"h1": "", "h6": "abc"},
                    "transactions": {"h1": {"buys": "x", "sells": None, "buyers": None, "sellers": ""}}}}
        env.pairs["body"] = {"store": True, "rows": prow1}
        env.gt = fb_gt_for(toks1, [bad_pool])
        pg = await env.open()
        await fb_wait_rows(pg, 1)
        r1 = (await pg.evaluate(FB_TBL_JS))[0]
        assert (r1["net"], r1["bs"], r1["share"], r1["vol"]) == ("—", "— / —", "—", "—"), "[flow board gt down] invalid or missing numbers render a dash, never 0: %s" % r1
        assert not FB_BAD_RE.search(await pg.inner_text("#flowBody")), "[flow board gt down] bad text in a row with invalid numbers"
        await pg.context.close()
        env.pairs["body"] = {"store": True, "rows": prow}
        # pairs.json 500
        env.pairs["status"] = 500
        env.gt = fb_gt_for(toks, pls)
        pg = await env.open()
        await pg.wait_for_selector("#flowBody .fbMsg", timeout=15000)
        msg = await pg.inner_text("#flowBody .fbMsg")
        assert msg == "New pairs could not be loaded. Activity is unknown, not zero.", "[flow board gt down] pairs.json 500: %r" % msg
        assert await pg.evaluate("() => document.querySelectorAll('#flowBody .fbRow').length") == 0
        await pg.context.close()
        # pairs.json is garbage (200 but wrong shape)
        env.pairs.update(status=200, body={"rows": "nope"})
        pg = await env.open()
        await pg.wait_for_selector("#flowBody .fbMsg", timeout=15000)
        assert (await pg.inner_text("#flowBody .fbMsg")).startswith("New pairs could not be loaded."), "[flow board gt down] bad shape"
        await pg.context.close()
        print("[flow board gt down] pools/multi 500 or tokens/multi 500: tokens and Exit chips stay, every number is a dash, the unavailable note shows, no 0/NaN; pairs.json 500 or a wrong shape: 'New pairs could not be loaded. Activity is unknown, not zero.' and no table")
    finally:
        await b.close()
        srv.shutdown()


async def check_flow_board_click(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    AERO = "0x940181a94A35A4569E4529A3CDfB74e38FD98631"
    try:
        env = FbEnv(b, origin, errs)
        rows_ = [("AERO", "sell", 600, (20, 5, 30, 8, "5000"), (40, 9, 60, 14, "9000")),
                 ("NEWT", "sell", 1200, (12, 2, 15, 3, "800"), (22, 4, 30, 5, "1500"))]
        prow, toks, pls, mk, pools = fb_fixture(rows=rows_)
        prow[0]["address"] = AERO
        toks[0]["attributes"]["address"] = AERO
        toks[0]["id"] = "base_" + AERO
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)
        pg = await env.open()
        await fb_wait_rows(pg, 2)
        before = await pg.evaluate("() => ({out: tokenOut.symbol, inn: tokenIn.symbol})")
        await pg.click('.fbRow[data-addr="%s"]' % AERO)
        await pg.wait_for_function("() => !document.getElementById('flowBackRow').hidden", timeout=20000)
        st = await pg.evaluate("() => ({out: tokenOut.symbol, sym: document.getElementById('flowTokSym').textContent, board: document.getElementById('fbHead').getClientRects().length > 0, tfs: document.getElementById('flowTfs').offsetParent !== null, back: document.getElementById('flowBack').textContent})")
        assert st["out"] == "AERO" and st["sym"] == "AERO" and not st["board"] and st["tfs"] and st["back"] == "← Back to all tokens", "[flow board click] row click opens the per-token flow: %s" % st
        await pg.click("#flowBack")
        await pg.wait_for_selector("#flowBody .fbRow", timeout=20000)
        st = await pg.evaluate("() => ({out: tokenOut.symbol, back: document.getElementById('flowBackRow').hidden, tfs: document.getElementById('flowTfs').offsetParent === null})")
        assert st == {"out": "AERO", "back": True, "tfs": True}, "[flow board click] Back returns to the board and leaves the swap token alone: %s" % st
        # فشارِ دوباره روی ردیفِ دیگر: وارد کردنِ توکنِ ناشناس یا خطای صریح، نه بی‌صدا
        await pg.click('.fbRow[data-addr="%s"]' % prow[1]["address"])
        await pg.wait_for_function("() => !document.getElementById('flowBackRow').hidden || document.querySelector('#flowBody .note.err')", timeout=20000)
        after = await pg.evaluate("() => ({back: !document.getElementById('flowBackRow').hidden, err: (document.querySelector('#flowBody .note.err') || {}).textContent || '', out: tokenOut.symbol})")
        assert after["back"] or after["err"].startswith("Could not open this token"), "[flow board click] an unopenable token must show an error: %s" % after
        await pg.context.close()
        # گزارشِ خطا: توکنی که import نمی‌شود (RPC نمی‌داند) خطای صریح می‌دهد و تابلو می‌ماند
        pg = await env.open(init=["window.__fbBreak = true;"])
        await fb_wait_rows(pg, 2)
        await pg.evaluate("() => { window.importToken = async function () {}; }")
        # importToken تابعِ اعلانی است؛ با جایگزینی، ردیفِ ناشناس باید خطا بدهد
        await pg.click('.fbRow[data-addr="%s"]' % prow[1]["address"])
        await pg.wait_for_selector("#flowBody .note.err", timeout=10000)
        err = await pg.inner_text("#flowBody .note.err")
        assert err.startswith("Could not open this token"), "[flow board click] %r" % err
        assert await pg.evaluate("() => document.querySelectorAll('#flowBody .fbRow').length") == 2, "[flow board click] the board stays after a failed open"
        await pg.context.close()

        # سولانا
        srows = [("AAA", "sell", 600, (20, 5, 30, 8, "5000"), (40, 9, 60, 14, "9000")),
                 ("BBB", "sell", 1200, (12, 2, 15, 3, "800"), (22, 4, 30, 5, "1500"))]
        prow, toks, pls, mk, pools = fb_fixture(net="solana", rows=srows)
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)
        pg = await env.open(hash_="#flow?chain=solana")
        await fb_wait_rows(pg, 2)
        sub = await pg.inner_text(".fbSub")
        assert sub == "New Solana pairs · last hour · by unique wallets", "[flow board click] Solana subtitle: %r" % sub
        assert any("networks/solana/tokens/multi/" in c for c in env.calls) and any("networks/solana/pools/multi/" in c for c in env.calls)
        target = prow[0]["address"]
        await pg.click('.fbRow[data-addr="%s"]' % target)
        await pg.wait_for_function("(m) => solMintCur === m && !document.getElementById('flowBackRow').hidden", arg=target, timeout=20000)
        await pg.click("#flowBack")
        await pg.wait_for_selector("#flowBody .fbRow", timeout=15000)
        assert await pg.evaluate("(m) => solMintCur === m", target), "[flow board click] Solana: Back leaves the selected token alone"
        await pg.context.close()
        print("[flow board click] Base row click opens that token's flow (swap token follows, 5-window switch back, Back link), 'Back to all tokens' returns to the board without touching the token, an unopenable token shows 'Could not open this token' and keeps the board; Solana: subtitle, tokens/multi + pools/multi on solana, row click selects the mint, Back returns")
    finally:
        await b.close()
        srv.shutdown()


# ۲۵ اکتبر: پهنای کارتِ جریانِ یک توکن روی c188094 (پایه‌ی زنده) در ۱۴۴۰ و ۱۲۸۰ — اندازه‌گیری‌شده با همین کاوشگر: ۱۱۰۰px
FB_BASE_TOKEN_CARD_W = 1100


async def check_flow_board_width(p, errors):
    """[flow board width] ۲۵ اکتبر: روی دسکتاپ کارتِ تابلو هم‌پهنای کارتِ Stocks (ستونِ محتوای اپ) است؛ کارتِ جریانِ یک توکن عوض نشده."""
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    try:
        env = FbEnv(b, origin, errs)
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)
        res = {}
        for vw in (1440, 1280):
            pg = await env.open("#flow", vw=vw, vh=900, scheme="dark", board=True)
            await fb_wait_rows(pg)
            board = await pg.evaluate("() => document.querySelector('#view-flow > .card').getBoundingClientRect().width")
            tbl = await pg.evaluate("() => { const t = document.querySelector('.fbTbl').getBoundingClientRect(), c = document.querySelector('#view-flow > .card').getBoundingClientRect(); return [t.left - c.left, c.right - t.right]; }")
            await pg.context.close()
            pg = await env.open("#stocks", vw=vw, vh=900, scheme="dark", board=False)
            await pg.wait_for_selector("#view-stocks .card", state="attached")
            await pg.wait_for_timeout(800)
            stocks = await pg.evaluate("() => document.querySelector('#view-stocks .card').getBoundingClientRect().width")
            await pg.context.close()
            pg = await env.open("#flow", vw=vw, vh=900, scheme="dark", board=False)
            await pg.wait_for_timeout(500)
            token = await pg.evaluate("() => document.querySelector('#view-flow > .card').getBoundingClientRect().width")
            await pg.context.close()
            res[vw] = (round(board, 1), round(stocks, 1), round(token, 1))
            assert abs(board - stocks) <= 1, "[flow board width] %d: the board card (%s) must be as wide as the Stocks card (%s)" % (vw, board, stocks)
            assert board >= 1000 and abs(tbl[0]) <= 1 and abs(tbl[1]) <= 1, "[flow board width] %d: the table fills the card: %s %s" % (vw, board, tbl)
            assert abs(token - FB_BASE_TOKEN_CARD_W) <= 1, "[flow board width] %d: the per-token flow card changed: %s vs the base %s" % (vw, token, FB_BASE_TOKEN_CARD_W)
        assert not errs, "[flow board width] console errors: %s" % errs
        print("[flow board width] board card = Stocks card within 1px at 1440 and 1280 (board, stocks, per-token: %s); the per-token flow card is still %dpx" % (res, FB_BASE_TOKEN_CARD_W))
    finally:
        await b.close()
        srv.shutdown()


async def check_flow_board_parity(p, errors):
    """[flow board preview parity] ۲۵ اکتبر: تابلو مثل پیش‌نمایشِ تأییدشده — بدونِ ردیفِ eyebrow؛ شبکه، قطعه‌ی ۱h|۶h و سوییچ در ردیفِ عنوان؛ سوییچِ role=switch؛ ردیف ۵۲px؛ ستون‌ها."""
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    try:
        env = FbEnv(b, origin, errs)
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)
        pg = await env.open("#flow", vw=1440, vh=900, scheme="dark", board=True)
        await fb_wait_rows(pg)
        await pg.wait_for_timeout(500)
        m = await pg.evaluate("""() => { const q = s => document.querySelector(s), r = e => e.getBoundingClientRect(), cs = e => getComputedStyle(e);
            const hd = q('#view-flow > .card > header'), head = q('#fbHead'), ttl = q('.fbTtl'), net = q('#fbNetSlot'), tfs = q('#fbHead .tfs'), tog = q('.fbTog'), menu = q('#srcMenu'), chip = menu.querySelector('.chip') || menu;
            const visText = [...document.querySelectorAll('#view-flow *')].filter(e => e.children.length === 0 && e.getClientRects().length && e.textContent.trim().toLowerCase() === 'money flow').length;
            const rows = [...document.querySelectorAll('.fbRow')], row = rows[0], tr = r(row);
            const th = [...document.querySelectorAll('.fbTbl thead th')], ths = th.map(x => [x.textContent.trim(), cs(x).textAlign]);
            const td = [...row.children].map(x => cs(x).textAlign);
            const probe = document.createElement('i'); probe.style.cssText = 'color:var(--tx3);position:absolute'; document.body.appendChild(probe); const tx3 = cs(probe).color; probe.remove();
            const volTd = row.children[5], exitTd = row.children[6], ch = exitTd.firstElementChild;
            const bar = row.querySelector('.fbBar'), star = row.querySelector('.fbStar');
            return {hdShown: hd.getClientRects().length > 0, eyebrow: visText, headTop: r(head).top, ttlTop: r(ttl).top, inHead: head.contains(menu) && head.contains(tfs) && head.contains(tog) && net.contains(menu),
                    rowOf: [r(menu).top, r(tfs).top, r(tog).top].map(x => Math.round(x)), ctlTop: r(q('.fbCtl')).top, subBottom: r(q('.fbSub')).bottom,
                    order: [r(net).right, r(tfs).left, r(tfs).right, r(tog).left], menuH: r(chip).height, tfsH: r(tfs).height, togH: r(tog).height,
                    role: tog.getAttribute('role'), checked: tog.getAttribute('aria-checked'), pressed: tog.getAttribute('aria-pressed'), swSize: [r(tog.querySelector('.fbSw')).width, r(tog.querySelector('.fbSw')).height],
                    swOn: cs(tog.querySelector('.fbSw')).backgroundColor, acc: (() => { const p2 = document.createElement('i'); p2.style.cssText = 'color:var(--acc);position:absolute'; document.body.appendChild(p2); const c = cs(p2).color; p2.remove(); return c; })(),
                    rowH: rows.map(x => r(x).height), av: [r(row.querySelector('.fbAv')).width, r(row.querySelector('.fbAv')).height], ageColor: cs(row.querySelector('.fbAge')).color, tx3,
                    ths, td, barW: r(bar).width, volRight: r(volTd).right, chipLeft: r(ch).left, volPadR: parseFloat(cs(volTd).paddingRight), chipTdLeft: r(exitTd).left,
                    starW: [r(star).width, r(star).height], starTd: row.firstElementChild === star.closest('td'), firstTh: th[0].textContent.trim(), thW: r(th[0]).width,
                    foot: q('.fnote').textContent, fnoteColor: cs(q('.fnote')).color, sw: document.documentElement.scrollWidth, iw: innerWidth}; }""")
        assert not m["hdShown"] and m["eyebrow"] == 0, "[flow board preview parity] no separate 'Money flow' eyebrow row above the board: %s" % {k: m[k] for k in ("hdShown", "eyebrow")}
        assert m["inHead"] and abs(m["rowOf"][0] - m["rowOf"][1]) <= 4 and abs(m["rowOf"][1] - m["rowOf"][2]) <= 4 and m["ctlTop"] < m["subBottom"], "[flow board preview parity] network selector, 1h|6h and the switch are in the title row: %s" % m
        assert m["order"][0] <= m["order"][1] + 0.5 and m["order"][2] <= m["order"][3] + 0.5, "[flow board preview parity] order: network selector, then 1h|6h, then the toggle: %s" % m["order"]
        assert abs(m["menuH"] - m["tfsH"]) <= 1 and abs(m["togH"] - m["tfsH"]) <= 1, "[flow board preview parity] the network selector and the toggle are as tall as the segmented control: %s" % {k: m[k] for k in ("menuH", "tfsH", "togH")}
        assert m["role"] == "switch" and m["checked"] == "true" and m["pressed"] is None and m["swSize"] == [28, 16], "[flow board preview parity] the toggle is a role=switch pill with a 28x16 track: %s" % {k: m[k] for k in ("role", "checked", "pressed", "swSize")}
        assert m["swOn"] == m["acc"], "[flow board preview parity] the track is --acc when on: %s vs %s" % (m["swOn"], m["acc"])
        assert all(abs(h - 52) <= 1 for h in m["rowH"]) and m["av"] == [28, 28], "[flow board preview parity] row height 52 and avatar 28: %s %s" % (m["rowH"], m["av"])
        assert m["ageColor"] == m["tx3"] and m["fnoteColor"] == m["tx3"], "[flow board preview parity] the age and the footer note use --tx3: %s %s" % (m["ageColor"], m["fnoteColor"])
        al = dict(m["ths"][1:])
        assert al["Token"] == "left" and al["Net buyers"] == "right" and al["Buyers / Sellers"] == "left" and al["Buy share"] == "left" and al["Volume 1h"] == "right" and al["Exit"] == "left", "[flow board preview parity] header alignment: %s" % m["ths"]
        assert m["td"][1] == "left" and m["td"][2] == "right" and m["td"][3] == "left" and m["td"][4] == "left" and m["td"][5] == "right" and m["td"][6] == "left", "[flow board preview parity] cell alignment: %s" % m["td"]
        assert abs(m["barW"] - 140) <= 0.5, "[flow board preview parity] the buy-share bar is 140px: %s" % m["barW"]
        assert 0 <= m["chipLeft"] - m["volRight"] <= m["volPadR"] + 14, "[flow board preview parity] the exit chip sits right after the volume: %s" % {k: m[k] for k in ("chipLeft", "volRight", "volPadR")}
        assert m["starTd"] and m["firstTh"] == "" and m["starW"] == [28, 28] and m["thW"] <= 50, "[flow board preview parity] the star is a narrow first column with no header text: %s" % {k: m[k] for k in ("starTd", "firstTh", "starW", "thW")}
        assert m["foot"].startswith("Counts are GeckoTerminal's pool totals") and m["sw"] <= m["iw"], "[flow board preview parity] footer note and no sideways scroll: %s" % m
        await pg.screenshot(path=os.path.join(SHOTS2, "board-1440-dark-page.png"))
        await pg.locator("#view-flow > .card").screenshot(path=os.path.join(SHOTS2, "board-1440-dark.png"))
        # سوییچ با صفحه‌کلید و کلیک
        n0 = await pg.evaluate("() => document.querySelectorAll('.fbRow').length")
        await pg.focus(".fbTog")
        await pg.keyboard.press("Space")
        await pg.wait_for_function("() => document.querySelector('.fbTog').getAttribute('aria-checked') === 'false'")
        n1 = await pg.evaluate("() => document.querySelectorAll('.fbRow').length")
        await pg.wait_for_timeout(350)   # گذارِ .16s ی ترک
        sw_off = await pg.evaluate("() => getComputedStyle(document.querySelector('.fbSw')).backgroundColor")
        assert n1 > n0 and sw_off != m["swOn"], "[flow board preview parity] the switch toggles with the keyboard and shows more rows when off: %s -> %s" % (n0, n1)
        # شبکه: انتخابگر در ردیف عنوان؛ شناختنِ سولانا (زیرعنوان)
        st = await pg.evaluate("() => [document.getElementById('fbNetSlot').contains(document.getElementById('srcMenu')), document.querySelector('.fbSub').textContent]")
        assert st[0] and st[1].startswith("New Base pairs"), "[flow board preview parity] %s" % st
        # برگشت به جریان یک توکن: ردیف eyebrow و انتخابگر به جای قبلی برمی‌گردند
        await pg.evaluate("() => { flowBoard = false; renderFlow(); }")
        await pg.wait_for_timeout(400)
        back = await pg.evaluate("() => [document.querySelector('#view-flow > .card > header').getClientRects().length > 0, document.getElementById('flowNetworkSlot').contains(document.getElementById('srcMenu')), document.getElementById('fbHead').getClientRects().length]")
        assert back == [True, True, 0], "[flow board preview parity] the per-token flow keeps its own header and the network selector goes back to it: %s" % back
        await pg.context.close()
        # ۳۹۰: بدونِ اسکرولِ افقی، بدون eyebrow، با سوییچ
        pg = await env.open("#flow", vw=390, vh=844, scheme="dark", board=True)
        await fb_wait_rows(pg)
        await pg.wait_for_timeout(400)
        mm = await pg.evaluate("""() => { const card = document.querySelector('#view-flow > .card').getBoundingClientRect(), t = document.querySelector('.fbTbl').getBoundingClientRect();
            return {sw: document.documentElement.scrollWidth, hd: document.querySelector('#view-flow > .card > header').getClientRects().length, tog: document.querySelector('.fbTog').getAttribute('role'),
                    inCard: t.left >= card.left - 0.5 && t.right <= card.right + 0.5, sym: [...document.querySelectorAll('.fbTkTx b')].map(x => x.getBoundingClientRect().width > 20)}; }""")
        assert mm["sw"] <= 390 and mm["hd"] == 0 and mm["tog"] == "switch" and mm["inCard"] and all(mm["sym"]), "[flow board preview parity] 390: %s" % mm
        await pg.locator("#view-flow > .card").screenshot(path=os.path.join(SHOTS2, "board-390-dark.png"))
        await pg.context.close()
        assert not errs, "[flow board preview parity] console errors: %s" % errs
        print("[flow board preview parity] 1440 dark: no 'Money flow' eyebrow row; network selector, 1h|6h and the role=switch toggle (28x16 track, --acc when on) share the title row and the segmented control's height; rows 52px with 28px avatars and --tx3 ages; Token/Buyers-Sellers/Buy share/Exit left, Net buyers/Volume right; 140px bar; exit chip right after Volume; 28px star column without a header; footer note; the per-token flow gets its header back; 390 has no sideways scroll")
    finally:
        await b.close()
        srv.shutdown()


async def check_flow_board_mobile(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    try:
        env = FbEnv(b, origin, errs)
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        env.gt = fb_gt_for(toks, pls)
        for chain in ("base", "solana"):
            if chain == "solana":
                prow, toks, pls, mk, pools = fb_fixture(net="solana")
                env.pairs["body"] = {"store": True, "rows": prow}
                env.gt = fb_gt_for(toks, pls)
            pg = await env.open(vw=390, vh=844, hash_="#flow" + ("?chain=solana" if chain == "solana" else ""))
            await fb_wait_rows(pg)
            await pg.click(".fbTog")
            await fb_wait_rows(pg, 6)
            m = await pg.evaluate("""() => { const se = document.scrollingElement;
                const vis = s => [...document.querySelectorAll(s)].map(e => getComputedStyle(e).display !== 'none');
                const card = document.querySelector('#view-flow > .card').getBoundingClientRect();
                const t = document.querySelector('.fbTbl').getBoundingClientRect();
                return {sw: se.scrollWidth, iw: innerWidth, bs: vis('.fbBS'), vol: vis('.fbVol'), tbl: [t.left, t.right], card: [card.left, card.right],
                        chips: [...document.querySelectorAll('.fbChip')].map(c => c.getBoundingClientRect().right).reduce((a, b) => Math.max(a, b), 0)}; }""")
            assert m["sw"] <= 390, "[flow board mobile] %s: page scrolls horizontally at 390: %s" % (chain, m)
            assert not any(m["bs"]) and not any(m["vol"]), "[flow board mobile] %s: Buyers / Sellers and Volume columns must be hidden: %s" % (chain, m)
            assert m["tbl"][0] >= m["card"][0] - 0.5 and m["tbl"][1] <= m["card"][1] + 0.5 and m["chips"] <= m["card"][1] + 0.5, "[flow board mobile] %s: table inside the card: %s" % (chain, m)
            await pg.context.close()
        # جریانِ یک توکن + کارت Early buyers هم در ۳۹۰ سر نرود
        env.gt = eb_gt(eb_trades_ok(), quote=False)
        pg = await env.open(vw=390, vh=844, board=False)
        await pg.wait_for_selector("#flowEarly .ebBar", timeout=20000)
        sw = await pg.evaluate("() => document.scrollingElement.scrollWidth")
        assert sw <= 390, "[flow board mobile] the per-token flow with the Early buyers card scrolls horizontally: %d" % sw
        await pg.context.close()
        print("[flow board mobile] at 390px (Base and Solana) the board and the per-token flow with the Early buyers card never scroll horizontally, Buyers / Sellers and Volume are hidden, the table stays inside the card")
    finally:
        await b.close()
        srv.shutdown()


# ---------- Early buyers ----------
EB_TOK = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913"   # USDC: توکنِ پیش‌فرضِ خروجی روی Base
EB_OTHER = "0xcbB7C0000aB88B473b1f5aFd9ef808440eed33Bf"
EB_POOL = "0x1111111111111111111111111111111111111111"
EB_SEQ = ([(i, "buy", 100) for i in range(25)] + [(6, "buy", 100), (0, "sell", 100), (1, "sell", 96), (2, "sell", 50),
          (3, "sell", 5), (4, "sell", 5.5), (5, "sell", 95), (6, "sell", 150), (7, "sell", 10), (8, "sell", 4),
          (20, "sell", 100), (10, "sell", 30), (10, "sell", 30), (11, "sell", 49), (11, "sell", 51)])
# دستی: ۲۰ خریدارِ اول = W0..W19؛ Sold all = W0,W1,W5,W11 (۴)؛ Sold part = W2,W4,W6,W7,W10 (۵)؛ Still holding = ۱۱
# خریدِ ۲۰ نفر = ۱۹×۱۰۰ + W6 (۲۰۰) = ۲۱۰۰؛ فروش = ۱۰۰+۹۶+۵۰+۵+۵٫۵+۹۵+۱۵۰+۱۰+۴+۶۰+۱۰۰ = ۶۷۵٫۵ → ۳۲٪ (W20 در شمار نیست)
EB_EXPECT = {"all": 4, "part": 5, "hold": 11, "pct": "32%"}


def eb_wallet(i, solana=False, upper=False):
    if solana:
        w = fb_b58(0x300 + i)
        return w
    h = "%040x" % (0x300 + i)
    return "0x" + (h.upper() if upper else h)


def eb_trades_ok(seq=None, solana=False, tok=None, other=None, quote=False, start_after=10, step=10, case_twin=False):
    """seq = [(کیف، buy|sell، مقدار)]؛ خروجی = (created_ago_sec, trades تازه‌ترین‌اول)."""
    seq = seq or EB_SEQ
    tok = tok or (FB_SOL_USDC if solana else EB_TOK)
    other = other or (FB_SOL_WSOL if solana else EB_OTHER)
    created_ago = 3 * 3600
    out = []
    for n, (w, side, amt) in enumerate(seq):
        buy = side == "buy"
        who = eb_wallet(w, solana, upper=(not solana and not buy and w in (0, 1)))
        if case_twin and solana and w == 24:
            who = eb_wallet(0, True).lower()
        base_kind = side if not quote else ("sell" if buy else "buy")
        out.append({"id": "t%d" % n, "type": "trade", "attributes": {
            "block_timestamp": fb_iso(created_ago - start_after - n * step),
            "kind": base_kind, "tx_from_address": who, "tx_hash": "h%d" % n,
            "from_token_address": other if buy else tok, "to_token_address": tok if buy else other,
            "from_token_amount": ("%g" % (amt * 0.01)) if buy else ("%g" % amt),
            "to_token_amount": ("%g" % amt) if buy else ("%g" % (amt * 0.01))}})
    out.reverse()
    return created_ago, out, quote


def eb_gt(spec, quote=False, created_override=None, trades_status=200, tok=None, solana=False, in_pool=True, pool=None):
    created_ago, trades, q = spec
    tok = tok or (FB_SOL_USDC if solana else EB_TOK)
    other = FB_SOL_WSOL if solana else EB_OTHER
    net = "solana" if solana else "base"
    pool = pool or (fb_b58(0x500) if solana else EB_POOL)
    base_id, quote_id = ("%s_%s" % (net, other), "%s_%s" % (net, tok)) if q else ("%s_%s" % (net, tok), "%s_%s" % (net, other))
    if not in_pool:
        base_id, quote_id = "%s_%s" % (net, other), "%s_%s" % (net, fb_evm(0x999) if not solana else fb_b58(0x999))
    pool_obj = {"id": "%s_%s" % (net, pool), "type": "pool", "attributes": {
        "address": pool, "name": "T / O", "reserve_in_usd": "250000.5", "pool_created_at": fb_iso(
            created_override if created_override is not None else created_ago),
        "volume_usd": {"h1": "1000", "h6": "5000", "h24": "9000000"},
        "transactions": {"h1": {"buys": 10, "sells": 5, "buyers": 7, "sellers": 4}, "h6": {"buys": 10, "sells": 5, "buyers": 7, "sellers": 4},
                         "h24": {"buys": 10, "sells": 5, "buyers": 7, "sellers": 4}}},
        "relationships": {"base_token": {"data": {"id": base_id, "type": "token"}}, "quote_token": {"data": {"id": quote_id, "type": "token"}}}}

    def gt(path):
        if solana:
            if path.endswith("/tokens/%s/pools" % tok):
                return (200, {"data": [pool_obj]})
            if path.endswith("/pools/%s/trades" % pool):
                return (trades_status, {"data": trades})
            if "/tokens/" in path and "/multi/" not in path:
                return (200, {"data": {"attributes": {"name": "USD Coin", "symbol": "USDC", "decimals": 6, "price_usd": "1"}}})
            return None
        if "/tokens/%s" % tok in path and "/multi/" not in path and not path.endswith("/pools"):
            return (200, {"data": {"id": "base_" + tok, "attributes": {"address": tok, "symbol": "USDC"},
                                   "relationships": {"top_pools": {"data": [{"id": "base_" + pool, "type": "pool"}]}}}})
        if path.endswith("/pools/%s" % pool):
            return (200, {"data": pool_obj})
        if path.endswith("/pools/%s/trades" % pool):
            return (trades_status, {"data": trades})
        return None
    return gt


EB_TEXT_JS = "() => { const e = document.getElementById('flowEarly'); return e.hidden ? null : e.innerText.replace(/\\s+/g, ' ').trim(); }"


async def eb_card(pg, timeout=20000):
    await pg.wait_for_function("() => { const e = document.getElementById('flowEarly'); return !e.hidden && e.textContent.trim() !== '' && !e.querySelector('.sk'); }", timeout=timeout)
    return await pg.evaluate(EB_TEXT_JS)


async def check_early_buyers(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    MANY = "Early buyers: unknown — this pool has too many trades to see its first buyers. Unknown, not zero."
    NA = "Early buyers: unknown — trade history is unavailable. Unknown, not zero."
    OK = ("Early buyers First 20 buyers of USDC Sold all 4 · Sold part 5 · Still holding 11 32% of their tokens sold "
          "Only sells through this pool are counted; tokens moved to another wallet look like holding.")
    try:
        env = FbEnv(b, origin, errs)

        async def run(spec, **kw):
            env.calls.clear()
            env.gt = eb_gt(spec, **kw)
            pg = await env.open(board=False)
            assert await pg.evaluate("() => tokenOut.address") == EB_TOK, "[early buyers] fixture assumes the default flow token is USDC"
            return pg, await eb_card(pg)

        # 1) ۴۰ معامله از لحظه‌ی ساخت: اعدادِ دستی
        pg, t = await run(eb_trades_ok())
        assert t == OK, "[early buyers] 40 trades from creation: %r" % t
        segs = await pg.evaluate("() => { const b = document.querySelector('#flowEarly .ebBar'); return {h: b.getBoundingClientRect().height, w: [...b.children].map(i => i.className + ':' + Math.round(i.getBoundingClientRect().width / b.getBoundingClientRect().width * 100)), n: getComputedStyle(b.querySelector('.n')).backgroundColor, wr: getComputedStyle(b.querySelector('.w')).backgroundColor, p: getComputedStyle(b.querySelector('.p')).backgroundColor}; }")
        assert segs["h"] == 10 and segs["w"] == ["n:20", "w:25", "p:55"], "[early buyers] 10px stacked bar neg/warn/pos with 4/5/11 of 20: %s" % segs
        assert (segs["n"], segs["wr"], segs["p"]) == (await fb_color(pg, "--neg"), await fb_color(pg, "--warn"), await fb_color(pg, "--pos")), "[early buyers] bar colours"
        assert await pg.evaluate("() => document.querySelectorAll('#flowBody .flowkv').length > 0 || document.querySelector('#flowBody').textContent.trim().length > 0"), "[early buyers] the per-token flow is still there"
        trades_calls = [c for c in env.calls if c.endswith("/trades")]
        assert len(trades_calls) == 1, "[early buyers] one trades request: %s" % env.calls
        assert not FB_BAD_RE.search(t), "[early buyers] bad text"
        await pg.context.close()
        # 2) توکن «مقابل» (quote): kind وارونه، نتیجه همان
        pg, t = await run(eb_trades_ok(quote=True), quote=True)
        assert t == OK, "[early buyers] token as quote token: %r" % t
        await pg.context.close()
        # 3) ۳۰۰ معامله، قدیمی‌ترین دو ساعت بعد از ساخت، توکن در استخر نیست، معاملات 500، بدون خریدار، کمتر از ۲۰
        spec = eb_trades_ok()
        big = (spec[0], (spec[1] * 8)[:300], False)
        assert len(big[1]) == 300
        pg, t = await run(big)
        assert t == MANY, "[early buyers] 300 trades -> unknown (too many): %r" % t
        await pg.context.close()
        pg, t = await run((4 * 3600, spec[1], False), created_override=5 * 3600)
        assert t == MANY, "[early buyers] oldest trade 2h after creation -> unknown (too many): %r" % t
        await pg.context.close()
        pg, t = await run(spec, in_pool=False)
        assert t == NA, "[early buyers] token neither base nor quote -> unknown: %r" % t
        await pg.context.close()
        pg, t = await run(spec, trades_status=500)
        assert t == NA, "[early buyers] trades 500 -> unknown (unavailable): %r" % t
        assert await pg.evaluate("() => document.getElementById('flowBody').textContent.trim().length > 0 && !!document.getElementById('flowTokSym')"), "[early buyers] a failed fetch never breaks the rest of the flow"
        await pg.context.close()
        only_sells = eb_trades_ok(seq=[(1, "sell", 5), (2, "sell", 6)])
        pg, t = await run(only_sells)
        assert t == NA, "[early buyers] zero buyers -> unknown: %r" % t
        await pg.context.close()
        seven = eb_trades_ok(seq=[(i, "buy", 10) for i in range(7)] + [(0, "sell", 10), (1, "sell", 1)])
        pg, t = await run(seven)
        assert t.startswith("Early buyers First 7 buyers of USDC Sold all 1 · Sold part 1 · Still holding 5 ") and "16% of their tokens sold" in t, "[early buyers] fewer than 20 buyers uses however many: %r" % t
        await pg.context.close()
        # 4) سولانا: همان معاملاتِ renderSolFlow (درخواستِ trades فقط یکی)، آدرسِ کیف عیناً (بدون lowercase)
        sol_spec = eb_trades_ok(solana=True, case_twin=True)
        env.calls.clear()
        env.gt = eb_gt(sol_spec, solana=True)
        pg = await env.open(hash_="#flow?chain=solana", board=False)
        t = await eb_card(pg)
        assert t == OK, "[early buyers] Solana: %r" % t
        assert len([c for c in env.calls if c.endswith("/trades")]) == 1, "[early buyers] Solana reuses the trades renderSolFlow fetched: %s" % env.calls
        # تغییرِ پنجره دوباره نمی‌پرسد
        await pg.click('#flowTfs [data-w="h6"]')
        await pg.wait_for_timeout(500)
        assert len([c for c in env.calls if c.endswith("/trades")]) == 1 and await pg.evaluate("() => !document.getElementById('flowEarly').hidden"), "[early buyers] window change keeps the card, no new request"
        await pg.context.close()
        print("[early buyers] 40 trades from creation: 20 first buyers -> Sold all 4 · Sold part 5 · Still holding 11, 32% of tokens sold (hand-computed, the 21st buyer's sell and a second buy counted correctly, upper-case Base wallets merged), 10px neg/warn/pos bar; token as quote token gives the same numbers; 300 trades / oldest 2h after creation -> 'too many trades'; token not in pool / trades 500 / zero buyers -> 'trade history is unavailable'; 7 buyers -> 'First 7 buyers'; Solana reuses the existing trades request and keeps wallet case")
    finally:
        await b.close()
        srv.shutdown()


# ---------- حکمِ صادرکننده برای سهام ----------
SI_NOTE = "The issuer can freeze accounts and recover tokens. This is expected for regulated stock tokens and is shown below for transparency."
SI_CHIP = "Issuer-controlled · regulated"


async def check_stock_issuer(p, errors):
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    errs = []
    src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
    prog = re.search(r'const SOL_TOKEN_PROGRAMS=\[\s*"([^"]+)"', src)
    assert prog, "[stocks issuer verdict] SOL_TOKEN_PROGRAMS not found"
    try:
        env = FbEnv(b, origin, errs)
        # --- Base: همان rep که scanToken می‌سازد، با آدرسِ سهام / آدرسِ عادی ---
        pg = await env.open(hash_="#swap", board=False)
        res = await pg.evaluate("""() => {
            const mk = (addr) => { const rep = {address: addr, symbol: 'X', findings: [
                {level: 'high', title: 'Owner can mint', detail: 'd1'}, {level: 'medium', title: 'Proxy', detail: 'd2'},
                {level: 'ok', title: 'Sellable', detail: 'd3'}, {level: 'info', title: 'Tradability unknown', detail: 'd4'}],
                owner: null, native: false, isProxy: false, liqUsd: 20000, canBuy: null, canSell: null, unknown: 1};
              rep.score = riskScore(rep); rep.verdict = verdictOf(rep); return rep; };
            const out = {};
            for (const [k, a] of [['tsla', BASE_TOKENS.find(t => t.symbol === 'TSLAc').address], ['tslaLow', BASE_TOKENS.find(t => t.symbol === 'TSLAc').address.toLowerCase()],
                                  ['aero', BASE_TOKENS.find(t => t.symbol === 'AERO').address]]) {
              const rep = mk(a), score0 = rep.score, verdict0 = JSON.stringify(rep.verdict);
              renderSafety(rep);
              const bx = document.getElementById('safetyBody');
              out[k] = {text: bx.textContent.replace(/\\s+/g, ' ').trim(), chip: (bx.querySelector('.issChip') || {}).textContent || null, ring: !!bx.querySelector('.ring'),
                        chk: bx.querySelectorAll('.chk').length, titles: [...bx.querySelectorAll('.chk b')].map(e => e.textContent),
                        rv: (bx.querySelector('.rv') || {}).textContent || null, score: rep.score === score0 && JSON.stringify(rep.verdict) === verdict0, scoreVal: score0, verdict: rep.verdict.txt};
              const cs = bx.querySelector('.issChip') && getComputedStyle(bx.querySelector('.issChip'));
              out[k].css = cs ? [cs.color, cs.backgroundColor] : null;
            }
            // دومین چیدمانِ گزارش (صفحه‌ی توکن / فشرده)
            const rep2 = mk(BASE_TOKENS.find(t => t.symbol === 'MSTRc').address);
            for (const compact of [true, false]) {
              renderSafetyReport(rep2, 'solSafety', 'zz', compact);
              const bx = document.getElementById('solSafety');
              out['rep' + compact] = {chip: (bx.querySelector('.issChip') || {}).textContent || null, ring: !!bx.querySelector('.ring'), text: bx.textContent.replace(/\\s+/g, ' ').trim(),
                                      titles: [...bx.querySelectorAll('b')].map(e => e.textContent).filter(t => ['Owner can mint', 'Proxy', 'Sellable', 'Tradability unknown'].includes(t))};
            }
            return out;
        }""")
        for k in ("tsla", "tslaLow"):
            r = res[k]
            assert r["chip"] == SI_CHIP and not r["ring"] and SI_NOTE in r["text"] and "Risk " not in r["text"] and "/100" not in r["text"], "[stocks issuer verdict] Base %s: %s" % (k, r)
            assert r["titles"] == ["Owner can mint", "Proxy", "Tradability unknown", "Sellable"] and r["chk"] == res["aero"]["chk"], "[stocks issuer verdict] Base %s: every finding stays: %s" % (k, r)
            assert r["score"], "[stocks issuer verdict] riskScore and rep.verdict are not modified"
        ar = res["aero"]
        assert ar["chip"] is None and ar["ring"] and ar["rv"] == ar["verdict"] and "Risk %d/100 · lower is safer" % ar["scoreVal"] in ar["text"] and SI_NOTE not in ar["text"], "[stocks issuer verdict] a normal token keeps the old verdict and score: %s" % ar
        for compact in ("reptrue", "repfalse"):
            r = res[compact]
            assert r["chip"] == SI_CHIP and not r["ring"] and SI_NOTE in r["text"] and "Risk " not in r["text"] and sorted(r["titles"]) == ["Owner can mint", "Proxy", "Sellable", "Tradability unknown"], "[stocks issuer verdict] report layout %s: %s" % (compact, r)
        css = res["tsla"]["css"]
        want = await pg.evaluate("""() => { const t = document.createElement('i'); t.style.color = 'var(--acc)'; t.style.background = 'color-mix(in srgb, var(--acc) 14%, transparent)'; document.body.appendChild(t);
            const c = getComputedStyle(t); const r = [c.color, c.backgroundColor]; t.remove(); return r; }""")
        assert css == want, "[stocks issuer verdict] chip is --acc text on a 14%% --acc tint: %s vs %s" % (css, want)
        # --- تشخیص: Base بی‌حساس به حروف، سولانا عیناً ---
        iso = await pg.evaluate("""() => { const m = STK_SOL[0].mint, a = BASE_TOKENS.find(t => t.symbol === 'AAPLc').address;
            return [isStockRep({solana: true, mint: m}), isStockRep({solana: true, mint: m.toLowerCase()}), isStockRep({solana: true, mint: m.toUpperCase()}),
                    isStockRep({address: a}), isStockRep({address: a.toLowerCase()}), isStockRep({address: a.toUpperCase().replace('0X', '0x')}), isStockRep({address: BASE_TOKENS[0].address, native: true}), isStockRep(null)]; }""")
        assert iso == [True, False, False, True, True, True, False, False], "[stocks issuer verdict] detection (Solana mint exact, Base case-insensitive): %s" % iso
        await pg.context.close()

        # --- Solana: مسیر کاملِ solLoadDetails با RPC جعلی ---
        stock_mint = re.search(r'\{sym:"TSLAx",name:"Tesla",mint:"([^"]+)"', src).group(1)

        def rpc(method, params):
            if method == "getAccountInfo":
                return {"value": {"owner": prog.group(1), "data": {"parsed": {"type": "mint", "info": {
                    "mintAuthority": None, "freezeAuthority": fb_b58(0x777), "supply": "1000000", "decimals": 6}}}}}
            if method == "getTokenLargestAccounts":
                return {"value": [{"amount": "100000", "address": fb_b58(0x778)}]}
            if method == "getEpochInfo":
                return {"epoch": 700}
            return None
        env.rpc = rpc
        env.gt = lambda path: ((200, {"data": {"attributes": {"name": "Tesla xStock", "symbol": "TSLAx", "decimals": 6, "price_usd": "250"}}}) if "/tokens/" in path and "/multi/" not in path and not path.endswith("/pools") else None)
        pg = await env.open(hash_="#swap?chain=solana", board=False)
        await pg.wait_for_function("() => document.getElementById('solSafety').textContent.includes('Freeze authority')", timeout=20000)
        usdc = await pg.evaluate("() => ({text: document.getElementById('solSafety').textContent.replace(/\\s+/g, ' '), chip: !!document.querySelector('#solSafety .issChip'), rv: (document.querySelector('#solSafety .rv') || {}).textContent})")
        assert not usdc["chip"] and usdc["rv"] in ("High risk", "Caution", "Acceptable with care", "No obvious red flags", "Checks incomplete", "Risk not assessed") and "out of 100" in usdc["text"], "[stocks issuer verdict] normal Solana token keeps the old verdict: %s" % usdc
        await pg.evaluate("(m) => solAppLoadToken(m)", stock_mint)
        await pg.wait_for_function("() => !!document.querySelector('#solSafety .issChip')", timeout=20000)
        sk = await pg.evaluate("() => ({text: document.getElementById('solSafety').textContent.replace(/\\s+/g, ' '), ring: !!document.querySelector('#solSafety .ring'), b: [...document.querySelectorAll('#solSafety b')].map(e => e.textContent)})")
        assert SI_CHIP in sk["text"] and SI_NOTE in sk["text"] and not sk["ring"] and "Risk " not in sk["text"] and "out of 100" not in sk["text"], "[stocks issuer verdict] Solana stock: %s" % sk
        for title in ("Mint authority", "Freeze authority", "Transfer fee", "Largest 20 token accounts"):
            assert title in sk["b"], "[stocks issuer verdict] Solana finding %r must stay in the list: %s" % (title, sk["b"])
        await pg.context.close()
        print("[stocks issuer verdict] Base STK token (checksummed or lower-case address) and Solana STK_SOL mint (exact match; lower/upper-case rejected) show the 'Issuer-controlled · regulated' chip (--acc on a 14% tint) with the exact note, no ring and no score, every finding still listed in both report layouts, riskScore/verdict untouched; a normal Base and Solana token keeps its old verdict and 'Risk N/100'")
    finally:
        await b.close()
        srv.shutdown()


async def check_flow_screens(p, errors):
    """فقط با ZX_ONLY=check_flow_screens و ZX_SHOTS=<پوشه>: عکسِ تابلو، کارت Early buyers و کارتِ ایمنیِ سهام (تیره، ۱۲۸۰ و ۳۹۰)."""
    out = os.environ.get("ZX_SHOTS")
    if not out:
        return
    os.makedirs(out, exist_ok=True)
    srv, origin = fb_serve()
    b = await p.chromium.launch()
    try:
        env = FbEnv(b, origin, [])
        prow, toks, pls, mk, pools = fb_fixture()
        env.pairs["body"] = {"store": True, "rows": prow}
        for vw, vh, tag in ((1280, 900, "desktop"), (390, 844, "mobile")):
            env.gt = fb_gt_for(toks, pls)
            pg = await env.open(vw=vw, vh=vh)
            await fb_wait_rows(pg)
            await pg.click(".fbTog")
            await fb_wait_rows(pg, 6)
            await pg.add_style_tag(content="#nav{display:none!important}" if tag == "mobile" else "i{}")
            await pg.wait_for_timeout(500)
            await pg.screenshot(path=os.path.join(out, "board-%s.png" % tag), full_page=True)
            await pg.context.close()
            env.gt = eb_gt(eb_trades_ok(), quote=False)
            pg = await env.open(vw=vw, vh=vh, board=False)
            await eb_card(pg)
            await pg.add_style_tag(content="#nav{display:none!important}" if tag == "mobile" else "i{}")
            await pg.wait_for_timeout(1500)
            await pg.screenshot(path=os.path.join(out, "early-%s.png" % tag), full_page=True)
            await pg.context.close()
            pg = await env.open(vw=vw, vh=vh, hash_="#swap", board=False)
            await pg.evaluate("""() => { const rep = {address: BASE_TOKENS.find(t => t.symbol === 'TSLAc').address, symbol: 'TSLAc', findings: [
                {level: 'high', title: 'Owner can mint', detail: 'The owner can create new tokens at will.'}, {level: 'medium', title: 'Upgradeable proxy', detail: 'The contract logic can be replaced.'},
                {level: 'ok', title: 'Sellable', detail: 'A sell quote was returned.'}, {level: 'info', title: 'Tradability unknown', detail: 'Not checked.'}],
                owner: null, native: false, isProxy: true, liqUsd: 20000, canBuy: null, canSell: null, unknown: 1};
              rep.score = riskScore(rep); rep.verdict = verdictOf(rep); renderSafety(rep); }""")
            await pg.add_style_tag(content="#nav{display:none!important}" if tag == "mobile" else "i{}")
            await pg.evaluate("() => mtabSelect('exit', false)")
            await pg.wait_for_timeout(300)
            box = await pg.evaluate("""() => { const r = document.querySelector('#safetyBody').closest('section').getBoundingClientRect();
                return {x: r.left + scrollX, y: r.top + scrollY, width: r.width, height: r.height}; }""")
            await pg.screenshot(path=os.path.join(out, "stock-safety-%s.png" % tag), full_page=True, clip=box)
            await pg.context.close()
    finally:
        await b.close()
        srv.shutdown()


async def main():
    errors = []
    # خطاهایی که یک کاوشگر *عمداً* تولید می‌کند. اجازه‌ی عبور می‌گیرند ولی
    # جمع می‌شوند تا همان کاوشگر بتواند ادعا کند واقعاً رخ داده‌اند — وگرنه
    # allowlist فقط یک راه بی‌صدا برای پنهان‌کردن خطا می‌شد.
    gate_errs = []
    # خطاهای عمدیِ کاوشگر «کف fallback»: آن کاوشگر ارسال را وسط راه قطع می‌کند،
    # پس showError درست کار کرده و لاگ کرده. جمعشان می‌کنیم تا خودِ کاوشگر
    # بتواند ادعا کند رخ داده‌اند — وگرنه allowlist فقط یک راه بی‌صدا برای
    # قایم‌کردن خطای واقعی می‌شد.
    probe_errs = []
    # خطای عمدیِ کاوشگر «گیرنده‌ی جاروکننده»: showError درست کار کرده و لاگ
    # کرده. با نشانِ خودِ تشخیص جدا می‌شود، نه با متن revert — وگرنه یک شکست
    # واقعیِ لغزش هم بی‌صدا از همین در رد می‌شد.
    sweep_errs = []

    def on_console(m):
        if m.type != "error":
            return
        if "[zaexa] gate check failed" in m.text:
            gate_errs.append(m.text)
        elif "probe: stop before sending" in m.text:
            probe_errs.append(m.text)
        elif "recipient forwarded the output" in m.text:
            sweep_errs.append(m.text)
        else:
            errors.append(m.text)

    async with async_playwright() as p:
        await check_real_page_from_disk(p)
        await check_theme_migration(p, errors)
        await check_theme_button(p, errors)
        await check_light_scrollbar(p, errors)
        # [landing dither] به تصمیمِ مالک در ۲۴ اکتبر حذف شد (دانه‌ی پس‌زمینه برنگشت)؛ برنگردانید.
        await check_setbtn_pressed(p, errors)
        await check_landing_mobile(p, errors)
        await check_canvas_palette_live(p, errors)
        await check_canvas_phases(p, errors)
        await check_canvas_cost(p, errors)
        await check_canvas_reduced_motion(p, errors)
        await check_canvas_labels(p, errors)
        await check_hero_hub(p, errors)
        await check_canvas_route_on_ellipse(p, errors)
        await check_trust_glyph_in_circle(p, errors)
        await check_canvas_resize(p, errors)
        await check_logo_hit_area(p, errors)
        await check_nav_chevron_mobile(p, errors)
        await check_landing_no_ambient_glow(p, errors)
        await check_landing_menu(p, errors)
        await check_hero_desktop_mode(p, errors)
        await check_logo_parity(p, errors)
        await check_token_page_hash_links(p, errors)
        await check_live_strip(p, errors)
        await check_mobile_compact(p, errors)
        await check_first_visit_tour(p, errors)
        await check_report_page(p, errors)
        await check_report_picker(p, errors)
        await check_stocks(p, errors)
        await check_stocks_sol(p, errors)
        await check_wallet_watch(p, errors)
        await check_report_chain(p, errors)
        await check_gt_direct_first(p, errors)
        await check_sol_boot_gt(p, errors)
        await check_flow_board(p, errors)
        await check_flow_board_gt_down(p, errors)
        await check_flow_board_click(p, errors)
        await check_flow_board_mobile(p, errors)
        await check_flow_board_width(p, errors)
        await check_flow_board_parity(p, errors)
        await check_exit_header_icons(p, errors)
        await check_watch_panel_views(p, errors)
        await check_strip_watch_merge(p, errors)
        await check_watch_rail(p, errors)
        await check_watch_popover(p, errors)
        await check_watch_sheet_mobile(p, errors)
        await check_watch_single_label(p, errors)
        await check_no_tap_squares(p, errors)
        await check_watch_exit_chips(p, errors)
        await check_board_star(p, errors)
        await check_pairs_star(p, errors)
        await check_early_buyers(p, errors)
        await check_stock_issuer(p, errors)
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1240, "height": 1000}, color_scheme="dark")
        pg.on("console", on_console)
        pg.on("pageerror", lambda e: errors.append(f"PAGEERROR {e}"))
        await pg.goto(URL)
        await pg.wait_for_timeout(900)

        # ---- 0-pre. چک‌سام EIP-55 هر آدرسی که در کد نوشته‌ایم ----
        # چرا با ethers *واقعی* و نه با استاب: در stub-ethers.js تابع getAddress
        # عملاً `a => a` است و هیچ اعتبارسنجی نمی‌کند. یعنی همان چیزی که باید
        # این باگ را می‌گرفت، خودش پنهانش کرده بود — کوتر پنکیک با `cEF` به‌جای
        # `CeF` نوشته شده بود و روی سایت زنده «شبکه جواب نداد» گزارش می‌شد.
        # ماک باید واقعیت را آینه کند؛ جایی که نمی‌تواند، با نسخه‌ی واقعی بسنج.
        src_all = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
        cands = sorted(set(re.findall(r"0x[0-9a-fA-F]{40}", src_all)))
        chk = await b.new_page()
        await chk.set_content("<html></html>")
        await chk.add_script_tag(path=vendor_path("ethers.umd.min"))
        bad = await chk.evaluate(
            "list => list.filter(a => { try { ethers.getAddress(a); return false; }"
            " catch { return true; } })", cands)
        await chk.close()
        print("[checksum] %d addresses in index.html, %d with a bad EIP-55 checksum"
              % (len(cands), len(bad)))
        assert not bad, ("these addresses are written with the wrong capitalisation, so "
                         "ethers rejects them before any call is made: %s" % bad)

        # پیش‌فرض عمداً ETH → USDC است: کسی که تازه می‌رسد معمولاً ETH دارد
        # و می‌خواهد بفروشد، نه برعکس.
        print("[default pair] %s -> %s"
              % (await pg.inner_text("#tokInSym"), await pg.inner_text("#tokOutSym")))
        assert await pg.inner_text("#tokInSym") == "ETH"
        assert await pg.inner_text("#tokOutSym") == "USDC"

        # ---- 0. price chart ----
        await pg.wait_for_selector("#plot svg", timeout=15000)
        pts = await pg.eval_on_selector_all("#plot svg path", "els => els.length")
        print("[chart] %s  %s  (%s svg paths)" % (
            await pg.inner_text("#pairName"), await pg.inner_text("#pxNow"), pts))
        print("        change: %s" % await pg.inner_text("#pxChg"))
        assert pts >= 2, "chart line + fill missing"
        assert "\u2014" not in await pg.inner_text("#pxNow"), "no headline price"
        box = await (await pg.query_selector("#plot svg")).bounding_box()
        await pg.mouse.move(box["x"] + box["width"] * 0.62, box["y"] + box["height"] * 0.5)
        await pg.wait_for_timeout(250)
        assert await pg.eval_on_selector("#tip", "e => getComputedStyle(e).opacity") == "1", "crosshair tooltip did not show"
        print("[chart] tooltip: %s" % (await pg.inner_text("#tip")).replace("\n", " "))
        for tf in ("1W", "1H"):
            await pg.click(f'#tfs [data-tf="{tf}"]'); await pg.wait_for_timeout(700)
            assert await pg.query_selector("#plot svg"), f"chart broke on {tf}"
        await pg.click('#tfs [data-tf="1D"]'); await pg.wait_for_timeout(600)

        # ---- 1. quote + venue comparison table ----
        await pg.fill("#amtIn", "1000")
        await pg.wait_for_function("() => document.getElementById('amtOut').value !== ''", timeout=20000)
        print("[quote 1000 USDC] out=%s  rate=%s  impact=%s  min=%s" % (
            await pg.input_value("#amtOut"), await pg.inner_text("#kRate"),
            await pg.inner_text("#kImpact"), await pg.inner_text("#kMin")))

        # ---- 1a. عددی که خودمان در فیلد خروجی می‌نویسیم باید خوانا باشد ----
        # قبلاً بی‌جداکننده و با ۸ رقم اعشار بود: 2148785.216084.
        # سه ادعا، چون گروه‌بندی به‌تنهایی می‌توانست تایپ در همین فیلد را بشکند:
        #   الف) شکل نمایش گروه‌بندی‌شده است،
        #   ب) با فوکوس به عدد خام برمی‌گردد تا ویرایش نشکند،
        #   ج) «1,5» — اعشار به سبک اروپایی — همچنان نامعتبر است و بی‌صدا
        #      ۱۵ خوانده نمی‌شود. این سومی مهم‌ترین است: یک replace ساده‌ی
        #      کاما همان‌جا یک باگ خاموشِ پولی می‌ساخت.
        shown = await pg.input_value("#amtOut")
        assert re.fullmatch(r"\d{1,3}(,\d{3})+\.\d{1,2}", shown), \
            "the receive field is not grouped and rounded for a large amount: " + shown
        await pg.focus("#amtOut"); await pg.wait_for_timeout(150)
        raw = await pg.input_value("#amtOut")
        assert "," not in raw and float(raw) > 0, \
            "focusing the receive field must hand back a raw number to edit, got: " + raw
        euro = await pg.evaluate("""() => {
            const el = document.getElementById("amtOut");
            el.value = "1,5";
            return parsedTargetOut() === null;
        }""")
        print("[amount grouping] shown=%s  on focus=%s  '1,5' still rejected=%s"
              % (shown, raw, euro))
        assert euro, \
            ("'1,5' is being read as 15 — a plain comma strip turns a European decimal into a "
             "number fifteen times too big")
        await pg.fill("#amtIn", "1000")
        await pg.wait_for_function("() => document.getElementById('amtOut').value !== ''", timeout=20000)
        assert await pg.evaluate("""() => {
            const el = document.getElementById("amtOut");
            el.value = "2,148,785.22";
            return parsedTargetOut() !== null;
        }"""), "the grouped amount we write ourselves does not parse back"

        print("[venues] %s" % await pg.inner_text("#venueMeta"))
        # ردیف «نسبت به یونی‌سواپ» — ادعای رقابتی محصول، پس باید صادق بماند
        print("[vs uniswap] %s  (tip: %s)" % (
            await pg.inner_text("#kVs"),
            (await pg.get_attribute("#vsRow", "title") or "")[:80]))
        vs = await pg.inner_text("#kVs")
        assert vs in ("same", "—") or vs.startswith("+") or vs.startswith("-"), \
            "unexpected comparison value: " + vs
        assert vs != "+0.00%", "a zero difference must read as 'same', not as a win"

        # همان ردیف، در دو حالتی که دستی نمی‌شود به آن رسید
        async def vs_probe(mutator):
            return await pg.evaluate("""(m) => {
                const saved = lastDirect;
                lastDirect = lastDirect.map(r =>
                    r.venue && r.venue.dex.id === "uniswap-v3"
                        ? (m === "worse" && r.out ? Object.assign({}, r, {out: (r.out * 99n) / 100n})
                                                  : Object.assign({}, r, {out: null, status: "unknown"}))
                        : r);
                renderVsUniswap(currentPlan);
                const out = {v: document.getElementById("kVs").innerText,
                             t: document.getElementById("vsRow").title};
                lastDirect = saved; renderVsUniswap(currentPlan);
                return out;
            }""", mutator)

        r = await vs_probe("worse")
        print("[vs uniswap:cheaper-elsewhere] %s" % r["v"])
        assert r["v"].startswith("+") and float(r["v"].rstrip("%")) > 0.5, \
            "a real edge over Uniswap must be shown: " + r["v"]
        assert "gas" in r["t"].lower(), "the gas caveat must travel with the claim"

        r = await vs_probe("unknown")
        print("[vs uniswap:uniswap-silent] %s" % r["v"])
        assert r["v"] == "unknown", \
            "with no Uniswap quote we cannot claim an edge: " + r["v"]
        rows = await pg.eval_on_selector_all(
            "#venueBody .vrow", "els => els.map(e => e.innerText.replace(/\\n+/g, ' | '))")
        for r in rows:
            print("        ", r)
        assert any("best" in r.lower() for r in rows), "no best venue marked"
        assert any("no pool" in r for r in rows), "empty pools must be shown, not hidden"
        # هر دو نسل V3 باید در جدول باشند. پنکیک نسل اول است (0x414bf389) و
        # قبلاً با kind=V3 ثبت شده بود، یعنی به تابعی صدا زده می‌شد که ندارد.
        assert any("PancakeSwap" in r for r in rows), \
            "a legacy-generation V3 DEX must be quoted like any other V3"

        # ---- 2. safety panel (scanner.py port) ----
        await pg.wait_for_selector("#safetyBody .rhead", timeout=20000)
        print("[safety] %s | %s" % (
            await pg.inner_text("#safetyBody .rv"),
            (await pg.inner_text("#safetyBody .rs")).replace("\n", " ")))
        checks = await pg.eval_on_selector_all(
            "#safetyBody .chk", "els => els.filter(e => e.querySelector('b')).map(e => e.className + ': ' + e.querySelector('b').innerText)")
        for c in checks:
            print("        ", c)
        assert any("Fee is mutable" in c for c in checks), "bytecode selector scan did not fire"

        # ---- 2a-bis. Bug 5 رگرسیون: حلقه‌ی ریسکِ نمای اصلی هم باید انیمیت شود ----
        # renderSafetyReport (صفحه‌ی توکن) از صفر پر می‌شد؛ renderSafety (نمای
        # اصلی) مستقیم مقدار نهایی را می‌نوشت و هرگز حرکت نمی‌کرد. اینجا هم
        # حرکتِ عادی سنجیده می‌شود و هم حالتِ prefers-reduced-motion.
        sf_key = await pg.evaluate("() => Object.keys(safetyCache)[0]")
        assert sf_key, "no safety scan is cached on the main view yet — nothing to re-animate"
        C_ring = 2 * 3.141592653589793 * 25
        pre_off = await pg.evaluate(
            """(k) => { renderSafety(safetyCache[k]);
               return document.getElementById("sf-arc").getAttribute("stroke-dashoffset"); }""",
            sf_key)
        assert abs(float(pre_off) - C_ring) < 0.5, (
            "the main-site ring must start fully empty (offset=circumference) the instant the "
            "scan lands, got %s" % pre_off)
        await pg.wait_for_timeout(1200)
        rs_text = await pg.inner_text("#safetyBody .rs")
        score_m = re.search(r"Risk (\d+)/100", rs_text)
        assert score_m, "could not read the score off the main safety panel: %r" % rs_text
        score = int(score_m.group(1))
        expected_off = C_ring * (1 - max(4, score) / 100)
        settled_off = float(await pg.get_attribute("#sf-arc", "stroke-dashoffset"))
        settled_num = (await pg.inner_text("#sf-score")).strip()
        print("[risk] main-site ring animates from empty: start=%.1f settled=%.1f expected=%.1f score=%s"
              % (float(pre_off), settled_off, expected_off, settled_num))
        assert abs(settled_off - expected_off) < 0.5, (
            "the ring did not settle where the scanned score says it should: got %.2f, "
            "expected %.2f" % (settled_off, expected_off))
        assert settled_num == str(score), (
            "the number never finished counting up to the final score: shows %r, scan says %d"
            % (settled_num, score))

        rmpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await rmpg.emulate_media(reduced_motion="reduce")
        await rmpg.goto(URL)
        await rmpg.wait_for_selector("#safetyBody .rhead", timeout=20000)
        rm_off = float(await rmpg.get_attribute("#sf-arc", "stroke-dashoffset"))
        rm_num = (await rmpg.inner_text("#sf-score")).strip()
        rm_rs = await rmpg.inner_text("#safetyBody .rs")
        rm_m = re.search(r"Risk (\d+)/100", rm_rs)
        assert rm_m, "could not read the score with reduced motion emulated: %r" % rm_rs
        rm_score = int(rm_m.group(1))
        rm_expected = C_ring * (1 - max(4, rm_score) / 100)
        await rmpg.close()
        print("[risk] prefers-reduced-motion is final immediately: offset=%.1f expected=%.1f score=%s"
              % (rm_off, rm_expected, rm_num))
        assert abs(rm_off - rm_expected) < 0.5, (
            "with prefers-reduced-motion: reduce the ring must land on the final value "
            "immediately, not mid-animation: got %.2f, expected %.2f" % (rm_off, rm_expected))
        assert rm_num == str(rm_score), (
            "with prefers-reduced-motion: reduce the number must show the final score right "
            "away: shows %r, scan says %d" % (rm_num, rm_score))

        # ---- 2b. exit check (round-trip) ----
        await pg.wait_for_selector("#exitBox .exit", timeout=20000)
        print("[exit] %s | %s" % (
            await pg.inner_text("#exitBox .exitTtl"),
            await pg.inner_text("#exitBox .exitBadge")))
        print("      %s" % (await pg.inner_text("#exitBox")).replace("\n", " ")[:190])
        assert "estimated" in (await pg.inner_text("#exitBox .exitBadge")).lower(), \
            "with no wallet the exit check must be labelled an estimate, not a proof"
        await pg.screenshot(path=os.path.join(HERE, "shot-desk.png"), full_page=True)

        # ---- 2b-bis. THE exit-check regression test --------------------
        # پس‌زمینه: در اسکرین‌شات ۹ آگوست، USDC قرمز شد با
        # «SELL SIMULATION REVERTED — transferFrom failed»، در حالی که همان
        # پنل می‌گفت Sellable و round-trip صفر درصد. علت، توکن نبود: قرارداد
        # نتوانسته بود توکن را از کیف پول بکشد. یعنی یک مشکل پیش‌شرطِ سمت ما
        # به‌عنوان حکم علیه توکن نمایش داده شد — «نمی‌دانم» در نقش «نه».
        # این چهار حالت مرز را قفل می‌کنند.
        EXIT_PROBE = """async ([msg, alw, down, cachedBal, cachedAlw]) => {
            const realContract = E.Contract;
            const realCall = readProvider.call.bind(readProvider);
            window.__STUB_ALLOWANCE__ = BigInt(alw);
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            signer = {}; walletChainId = CHAIN.id;
            /* state کش‌شده. پیش‌فرض «کافی» است، ولی تست می‌تواند عددی *بین*
               پای شبیه‌سازی و کل سفارش بگذارد — همان بازه‌ای که دو نگهبان
               زودهنگام قبلاً با مقدار اشتباه می‌سنجیدند. */
            balances[balKey(tokenIn)] = cachedBal ? BigInt(cachedBal) : 10n ** 30n;
            allowance = cachedAlw ? BigInt(cachedAlw) : 10n ** 30n;
            allowanceKnown = true;
            E.Contract = function () {
                return { executeSwap: { staticCall: async () => { throw new Error(msg); } } };
            };
            if (down) readProvider.call = async () => { throw new Error("fetch failed"); };
            let res = null;
            try {
                res = await runExitCheck(currentPlan, parsedAmountIn());
                renderExit(res);
            } finally {
                E.Contract = realContract;
                readProvider.call = realCall;
            }
            return { state: res && res.state, reason: res && res.reason,
                     badge: document.querySelector("#exitBox .exitBadge").innerText,
                     title: document.querySelector("#exitBox .exitTtl").innerText };
        }"""

        async def exit_case(label, msg, allowance="0", down=False,
                            cached_bal=None, cached_alw=None):
            r = await pg.evaluate(EXIT_PROBE, [msg, allowance, down, cached_bal, cached_alw])
            print("[exit:%s] state=%s  title=%r" % (label, r["state"], r["title"]))
            print("          %s" % (r["reason"] or "")[:120])
            return r

        BIG = str(10 ** 30)
        NEVER = "You may not be able to sell this back"

        # این بخش مسیر approve را می‌سنجد، پس ورودی باید یک ERC-20 باشد.
        # ETH بومی approve نمی‌خواهد، و از وقتی پیش‌فرضِ صفحه ETH شد این
        # کاوشگرها به جفتِ پیش‌فرض گره خورده بودند. حالا صریح است.
        await pg.evaluate("""() => {
            tokenIn = allTokens().find(t => t.symbol === "USDC");
            tokenOut = allTokens().find(t => t.symbol === "WETH");
            paintToken("in", tokenIn); paintToken("out", tokenOut);
            loadChart();
        }""")
        await pg.fill("#amtIn", "1000")
        await pg.wait_for_timeout(3000)

        # الف) همان باگ اسکرین‌شات: revert چون کیف پول approve نکرده.
        r = await exit_case("no-approval", 'execution reverted: "transferFrom failed"', allowance="0")
        assert r["state"] == "estimated", "a missing approval must not read as a verdict on the token"
        assert NEVER not in r["title"], "screenshot bug is back: " + r["title"]
        assert "approve" in (r["reason"] or "").lower()

        # ب) کیف پول approve کرده و باز هم revert → این بار واقعاً سیگنال توکن است.
        r = await exit_case("honeypot", 'execution reverted: "Blacklisted"', allowance=BIG)
        assert r["state"] == "blocked", "a real sell-side revert must still be reported"
        assert NEVER in r["title"]

        # ج) حتی با پیام transferFrom، اگر پیش‌شرط‌ها برقرارند revert مال توکن است.
        #     (رگرسیون نسخه‌ی قبل که فقط رشته را تطبیق می‌داد و اینجا کور بود.)
        r = await exit_case("hostile-msg", 'execution reverted: "transferFrom failed"', allowance=BIG)
        assert r["state"] == "blocked", "message matching must not excuse a genuine revert"

        # د) شبکه جواب نداد → «نمی‌دانم»، هرگز «نه».
        r = await exit_case("rpc-down", "fetch failed", allowance=BIG, down=True)
        assert r["state"] == "unknown", "an outage must never be reported as a verdict"
        assert NEVER not in r["title"], "outage reported as unsellable: " + r["title"]

        # ---- 2b-quater. مورد ۰۵ ریویو: پیش‌شرط با *مقدار شبیه‌سازی‌شده* ----
        # روی نقشه‌ی split، شبیه‌سازی روی بزرگ‌ترین پا اجرا می‌شود، پس مقداری
        # که لازم دارد از کل سفارش کمتر است. اگر پیش‌شرط با کل سفارش سنجیده
        # شود، کیف پولی که allowance‌اش بین این دو است پیام «اول approve کن»
        # می‌گیرد و پنل روی estimated می‌نشیند — در حالی که revert واقعاً از
        # سمت توکن آمده. یک `blocked` واقعی نرم می‌شود به «نتوانستیم بسنجیم»؛
        # همان «نمی‌دانم در نقش نه»، در گران‌ترین جهت.
        await pg.fill("#amtIn", "900000")            # مبلغی که مسیر را تقسیم می‌کند
        await pg.wait_for_timeout(3200)
        legs = await pg.evaluate("""() => {
            if (!currentPlan) return null;
            const big = currentPlan.parts.slice().sort((a,b)=>b.amountIn>a.amountIn?1:-1)[0];
            return {parts: currentPlan.parts.length,
                    total: currentPlan.totalIn.toString(),
                    biggest: big.amountIn.toString()};
        }""")
        assert legs and legs["parts"] > 1, \
            "this probe needs a split plan; got %s — the amount may no longer split" % legs
        # موجودی زیاد، ولی allowance دقیقاً *بین* پای بزرگ و کل سفارش
        between = (int(legs["biggest"]) + int(legs["total"])) // 2
        assert int(legs["biggest"]) < between < int(legs["total"])
        await pg.evaluate("v => { window.__STUB_BALANCE__ = v; }", str(10 ** 40))
        r = await exit_case("split-precondition",
                            'execution reverted: "Blacklisted"', allowance=str(between))
        await pg.evaluate("() => { delete window.__STUB_BALANCE__; }")
        print("[exit:split-precondition] parts=%s biggest=%s total=%s allowance=between"
              % (legs["parts"], legs["biggest"][:8] + "…", legs["total"][:8] + "…"))
        assert r["state"] == "blocked", (
            "the simulation only needed the biggest leg, and the wallet had approved more "
            "than that — a genuine sell-side revert was softened into %r (%s). This is the "
            "first rule of the project failing in its expensive direction."
            % (r["state"], (r["reason"] or "")[:90]))
        assert NEVER in r["title"], "a real block must still say so: " + r["title"]

        # همان مقدار اشتباه در دو نگهبان *زودهنگام* هم بود: موجودی و allowance
        # کش‌شده با کل سفارش سنجیده می‌شدند، پس شبیه‌سازی‌ای که موفق می‌شد
        # بی‌دلیل رد می‌شد و پنل هرگز به «blocked» نمی‌رسید.
        for label, kw in (("cached-balance", {"cached_bal": str(between)}),
                          ("cached-allowance", {"cached_alw": str(between)})):
            await pg.evaluate("v => { window.__STUB_BALANCE__ = v; }", str(10 ** 40))
            r2 = await exit_case(label, 'execution reverted: "Blacklisted"',
                                 allowance=str(10 ** 40), **kw)
            await pg.evaluate("() => { delete window.__STUB_BALANCE__; }")
            assert r2["state"] == "blocked", (
                "the %s guard was measured against the whole order instead of the leg that "
                "is actually simulated, so a real block came back as %r (%s)"
                % (label, r2["state"], (r2["reason"] or "")[:80]))

        # ------------------------------------------------------------
        # بازطراحی کارت سواپ (۲۴ سپتامبر ۲۰۲۶): پیلِ فروش، نوارِ تقسیمِ
        # مسیر، بلوکِ نتیجه، و هالهٔ کارت. currentPlan همین‌جا همان نقشه‌ی
        # تقسیم‌شده‌ی USDC->WETH با ۹۰۰٬۰۰۰ است که `legs` بالاتر تأییدش کرد،
        # پس همان راه‌اندازیِ کوت را دوباره استفاده می‌کنیم.
        # ------------------------------------------------------------

        # ---- [sell pill] پیلِ «قابل‌فروش» — تنها نویسنده‌اش paintSellPill ----
        sell_pill = await pg.evaluate("""() => {
            const savedHTML = document.getElementById("exitBox").innerHTML;
            const savedTokenPage = tokenPage;
            tokenPage = false;
            const pill = document.getElementById("sellPill");
            const mk = (state, lossPct) => ({state, lossPct, recovered: null, reason: null});
            const snap = () => ({cls: pill.className.split(" "), text: pill.textContent, hidden: pill.hidden,
                display: getComputedStyle(pill).display});
            const out = {};
            renderExit(mk("verified", 0.3));  out.ok03 = snap();
            renderExit(mk("estimated", 8));   out.warn8 = snap();
            renderExit(mk("estimated", 20));  out.no20 = snap();
            renderExit({state: "blocked", lossPct: null, recovered: null, reason: null}); out.blocked = snap();
            renderExit({state: "noexit", lossPct: null, recovered: null, reason: null});  out.noexit = snap();
            renderExit({state: "unknown", lossPct: null, recovered: null, reason: null}); out.unknown = snap();
            renderExit(mk("verified", -50));  out.implausible = snap();
            renderExit(null);                 out.hiddenNull = snap();
            document.getElementById("exitBox").innerHTML = savedHTML;
            tokenPage = savedTokenPage;
            return out;
        }""")

        # بازخوردِ مالک ۲۴ سپتامبر: موجودیِ سمتِ دریافتی حذف شد (فقط سمتِ
        # پرداختی موجودی نشان می‌دهد)، پس «۸px فاصله‌ی موجودی→پیل» و «موجودی
        # روی لبه‌ی دکمه وقتی پیل پنهان است» دیگر معنا ندارند — این دو چک
        # برداشته شدند؛ جایشان: #balOut همیشه display:none است، و نوشتنِ متن
        # در #balOut (که جاوااسکریپت هنوز انجامش می‌دهد) جای پیل را عوض نمی‌کند.
        async def sell_pill_geometry(width):
            gp = await b.new_page(viewport={"width": width, "height": 900}, color_scheme="dark")
            await gp.goto(URL); await gp.wait_for_timeout(900)
            geo = await gp.evaluate("""() => {
                paintSellPill("exit", {state: "estimated", lossPct: 2, recovered: null, reason: null});
                const p = document.getElementById("sellPill"), btn = document.getElementById("tokOutBtn");
                const balOut = document.getElementById("balOut");
                const before = p.getBoundingClientRect();
                const balOutDisplay = getComputedStyle(balOut).display;
                balOut.textContent = "123.45";
                const after = p.getBoundingClientRect();
                return {pillRight: before.right, btnRight: btn.getBoundingClientRect().right,
                        balOutDisplay,
                        shift: Math.max(Math.abs(after.left - before.left), Math.abs(after.right - before.right))};
            }""")
            await gp.close()
            return geo
        geo1440 = await sell_pill_geometry(1440)
        geo390 = await sell_pill_geometry(390)

        print("[sell pill] ok03=%s/%r warn8=%s no20=%s/%r blocked=%r noexit=%r unknown=%s/%r "
              "implausible=%s hiddenNull=%s | geom 1440 pill=%.1f btn=%.1f balOutDisplay=%s shift=%.2f "
              "390 pill=%.1f btn=%.1f balOutDisplay=%s shift=%.2f"
              % (sell_pill["ok03"]["cls"], sell_pill["ok03"]["text"], sell_pill["warn8"]["cls"],
                 sell_pill["no20"]["cls"], sell_pill["no20"]["text"], sell_pill["blocked"]["text"],
                 sell_pill["noexit"]["text"], sell_pill["unknown"]["cls"], sell_pill["unknown"]["text"],
                 sell_pill["implausible"]["cls"], sell_pill["hiddenNull"]["hidden"],
                 geo1440["pillRight"], geo1440["btnRight"], geo1440["balOutDisplay"], geo1440["shift"],
                 geo390["pillRight"], geo390["btnRight"], geo390["balOutDisplay"], geo390["shift"]))
        assert "ok" in sell_pill["ok03"]["cls"] and "99.7% back" in sell_pill["ok03"]["text"], sell_pill["ok03"]
        assert "warn" in sell_pill["warn8"]["cls"], sell_pill["warn8"]
        assert "no" in sell_pill["no20"]["cls"] and "Sellable" in sell_pill["no20"]["text"], sell_pill["no20"]
        assert "no" in sell_pill["blocked"]["cls"] and "Can't sell" in sell_pill["blocked"]["text"], sell_pill["blocked"]
        assert "no" in sell_pill["noexit"]["cls"] and "Can't sell" in sell_pill["noexit"]["text"], sell_pill["noexit"]
        assert "unk" in sell_pill["unknown"]["cls"] and "Sellable" not in sell_pill["unknown"]["text"], sell_pill["unknown"]
        assert "unk" in sell_pill["implausible"]["cls"] and "Sellable" not in sell_pill["implausible"]["text"], \
            sell_pill["implausible"]
        assert sell_pill["hiddenNull"]["hidden"], "renderExit(null) must hide the sell pill"
        # 🔴 ویژگیِ hidden در برابرِ display:inline-flexِ خودِ .sellPill می‌بازد؛ بدونِ
        # .sellPill[hidden]{display:none} یک قرصِ خالیِ نامرئی جا می‌گیرد و موجودی را هل می‌دهد.
        assert sell_pill["hiddenNull"]["display"] == "none", \
            "a hidden sell pill must not take space (display=%s)" % sell_pill["hiddenNull"]["display"]
        assert abs(geo1440["pillRight"] - geo1440["btnRight"]) <= 1, \
            "sell pill right edge does not track #tokOutBtn at 1440px: %s" % geo1440
        assert abs(geo390["pillRight"] - geo390["btnRight"]) <= 1, \
            "sell pill right edge does not track #tokOutBtn at 390px: %s" % geo390
        assert geo1440["balOutDisplay"] == "none", "#balOut must be display:none at 1440px: %s" % geo1440
        assert geo390["balOutDisplay"] == "none", "#balOut must be display:none at 390px: %s" % geo390
        assert geo1440["shift"] <= 0.5, \
            "writing a wallet-balance string into #balOut moved the sell pill at 1440px: %s" % geo1440
        assert geo390["shift"] <= 0.5, \
            "writing a wallet-balance string into #balOut moved the sell pill at 390px: %s" % geo390

        # ---- [route bar] نوارِ تقسیمِ مسیر ----
        # مبلغِ ۹۰۰٬۰۰۰ بالاتر تصادفاً ۵۰/۵۰ تقسیم می‌شود — تفاوتِ عرض را
        # نمی‌سنجد. ۱۰۰۰ روی همین جفت یک تقسیمِ نامساویِ ۷۵/۲۵ می‌دهد، جایی
        # که «عرض به‌جای رنگ بر اساسِ اندیس» واقعاً قابل‌دیدن است.
        await pg.fill("#amtIn", "1000"); await pg.wait_for_timeout(3000)
        route_bar = await pg.evaluate("""() => {
            const bar = document.getElementById("routeBar");
            const track = document.getElementById("rbTrack");
            const legend = document.getElementById("rbLegend");
            const segs = [...track.children];
            const shares = currentPlan.parts.map(p => Number((p.amountIn * 10000n) / currentPlan.totalIn) / 100);
            const trackW = track.getBoundingClientRect().width;
            const availW = trackW - 2 * (segs.length - 1);
            const widths = segs.map(s => s.getBoundingClientRect().width);
            const expected = shares.map(sh => sh / 100 * availW);
            return {
                hidden: bar.hidden, partsCount: currentPlan.parts.length, segCount: segs.length,
                widths, expected,
                legendTexts: [...legend.children].map(e => e.textContent.trim()),
                meta: document.getElementById("rbMeta").textContent
            };
        }""")
        # بازخوردِ مالک ۲۴ سپتامبر: نوار مسیر دیگر هیچ‌وقت hidden نمی‌شود —
        # scheduleQuote حالا حالتِ بی‌مبلغش را می‌کشد (paintRouteIdle)، نه
        # اینکه پنهانش کند.
        after_schedule = await pg.evaluate("""() => {
            scheduleQuote();
            return {
                hidden: document.getElementById("routeBar").hidden,
                meta: document.getElementById("rbMeta").textContent,
                segCount: document.getElementById("rbTrack").children.length,
                legend: document.getElementById("rbLegend").textContent.trim()
            };
        }""")
        max_diff = max(abs(w - e) for w, e in zip(route_bar["widths"], route_bar["expected"]))
        print("[route bar] visible=%s parts=%s segments=%s max width diff=%.2fpx legend=%s meta=%r "
              "after scheduleQuote: hidden=%s meta=%r segments=%s legend=%r"
              % (not route_bar["hidden"], route_bar["partsCount"], route_bar["segCount"], max_diff,
                 route_bar["legendTexts"], route_bar["meta"],
                 after_schedule["hidden"], after_schedule["meta"], after_schedule["segCount"],
                 after_schedule["legend"]))
        assert not route_bar["hidden"], "routeBar must be visible once a plan renders"
        assert route_bar["segCount"] == route_bar["partsCount"], \
            "segment count %s does not match plan.parts.length %s" % (route_bar["segCount"], route_bar["partsCount"])
        assert max_diff <= 1.5, "segment widths are not proportional to their share: %s" % route_bar
        assert all(t and re.search(r"\d+%", t) for t in route_bar["legendTexts"]), \
            "every legend item must show a name and a percent: %s" % route_bar["legendTexts"]
        assert not after_schedule["hidden"], \
            "routeBar must stay visible (never hidden) after scheduleQuote resets the plan: %s" % after_schedule
        assert after_schedule["meta"] == "—", \
            "idle route bar meta must read '—': %r" % after_schedule["meta"]
        assert after_schedule["segCount"] == 0, \
            "idle route bar must have no segments: %s" % after_schedule["segCount"]
        assert "Enter an amount to see the route" in after_schedule["legend"], \
            "idle route bar must show the idle legend text: %r" % after_schedule["legend"]

        # ---- [swap done] بلوکِ نتیجه بعد از یک سواپِ تأییدشده ----
        swap_done_1 = await pg.evaluate("""() => {
            const cardBefore = Math.round(document.querySelector("section.card.swapCard").getBoundingClientRect().height);
            showSwapDone({paidTxt: "1 ETH", gotTxt: "≈ 2,500 USDC", vs: "+1.20%",
                          url: "https://basescan.org/tx/0xabc",
                          hash: "0x" + "ab".repeat(32), secs: 4.2});
            const block = document.getElementById("swapDone");
            const card = block.closest("section.card");
            return {
                hidden: block.hidden, isDone: card.classList.contains("isDone"),
                actBtnDisplay: getComputedStyle(document.getElementById("actBtn")).display,
                factsDisplay: getComputedStyle(document.querySelector("section.card .facts")).display,
                text: block.textContent,
                cardBefore, cardAfter: Math.round(card.getBoundingClientRect().height)
            };
        }""")
        await pg.click("#swapAgain"); await pg.wait_for_timeout(150)
        after_again = await pg.evaluate("""() => {
            const block = document.getElementById("swapDone");
            const card = block.closest("section.card");
            return {hidden: block.hidden, isDone: card.classList.contains("isDone"),
                    focused: document.activeElement && document.activeElement.id,
                    minH: card.style.minHeight};
        }""")
        after_second = await pg.evaluate("""() => {
            showSwapDone({paidTxt: "1 ETH", gotTxt: "≈ 2,500 USDC", vs: null,
                          url: "https://basescan.org/tx/0xdef",
                          hash: "0x" + "cd".repeat(32), secs: 3.1});
            scheduleQuote();
            return document.getElementById("swapDone").hidden;
        }""")
        print("[swap done] visible=%s isDone=%s actBtn=%s facts=%s hasComplete=%s hasApprox=%s | "
              "after swapAgain: hidden=%s isDone=%s focused=%s | after 2nd + scheduleQuote hidden=%s"
              % (not swap_done_1["hidden"], swap_done_1["isDone"], swap_done_1["actBtnDisplay"],
                 swap_done_1["factsDisplay"], "Swap complete" in swap_done_1["text"],
                 "≈" in swap_done_1["text"], after_again["hidden"], after_again["isDone"],
                 after_again["focused"], after_second))
        assert not swap_done_1["hidden"], "showSwapDone must reveal #swapDone"
        assert swap_done_1["isDone"], "showSwapDone must add .isDone to the swap card"
        assert swap_done_1["actBtnDisplay"] == "none", "#actBtn must be hidden while .isDone"
        assert swap_done_1["factsDisplay"] == "none", ".facts must be hidden while .isDone"
        assert "Swap complete" in swap_done_1["text"], swap_done_1["text"]
        assert "≈" in swap_done_1["text"], "the received amount must keep its ≈ — it is a quote, not a receipt"
        assert after_again["hidden"] and not after_again["isDone"], \
            "#swapAgain must hide the block and drop .isDone"
        assert after_again["focused"] == "amtIn", "#swapAgain must focus #amtIn"
        # ۲۴ سپتامبر: کارت بعد از سواپ نباید کوچک شود
        print("[swap done] card height before=%s after=%s | height lock after swapAgain=%r"
              % (swap_done_1["cardBefore"], swap_done_1["cardAfter"], after_again["minH"]))
        assert abs(swap_done_1["cardAfter"] - swap_done_1["cardBefore"]) <= 1, \
            "the swap card must keep its height when the result block shows: %s -> %s" \
            % (swap_done_1["cardBefore"], swap_done_1["cardAfter"])
        assert after_again["minH"] == "", "hideSwapDone must release the height lock: %r" % after_again["minH"]
        assert after_second, "scheduleQuote must hide #swapDone again"
        await pg.fill("#amtIn", "900000"); await pg.wait_for_timeout(3200)

        # ---- [swap halo] هالهٔ حذف‌شدهٔ کارتِ سواپ ----
        # بازخوردِ مالک ۲۴ سپتامبر: هاله برداشته شد. کاوشگر حالا می‌سنجد که
        # سایه‌ی محاسبه‌شده‌ی کارتِ سواپ دقیقاً همان سایه‌ی کارتِ نمودار
        # (اولین .card در .row.hero) است — یعنی هیچ هاله‌ای نمانده.
        async def halo_probe(color_scheme):
            hp = await b.new_page(viewport={"width": 1100, "height": 900}, color_scheme=color_scheme)
            await hp.goto(URL); await hp.wait_for_timeout(900)
            data = await hp.evaluate("""() => {
                const swap = document.querySelector("section.card.swapCard");
                const chart = document.querySelector("#baseHeroRow .swapChartCard");
                return {
                    swapShadow: getComputedStyle(swap).boxShadow,
                    chartShadow: getComputedStyle(chart).boxShadow
                };
            }""")
            await hp.close()
            return data
        halo_dark = await halo_probe("dark")
        halo_light = await halo_probe("light")
        print("[swap halo] removed: dark swap=%r chart=%r equal=%s | light swap=%r chart=%r equal=%s"
              % (halo_dark["swapShadow"], halo_dark["chartShadow"],
                 halo_dark["swapShadow"] == halo_dark["chartShadow"],
                 halo_light["swapShadow"], halo_light["chartShadow"],
                 halo_light["swapShadow"] == halo_light["chartShadow"]))
        assert halo_dark["swapShadow"] == halo_dark["chartShadow"], \
            "dark: swap card box-shadow still differs from the chart card's — halo not removed: %s vs %s" \
            % (halo_dark["swapShadow"], halo_dark["chartShadow"])
        assert halo_light["swapShadow"] == halo_light["chartShadow"], \
            "light: swap card box-shadow still differs from the chart card's — halo not removed: %s vs %s" \
            % (halo_light["swapShadow"], halo_light["chartShadow"])

        # ---- [page glow] ۲۴ سپتامبر: امتحان شد و به تصمیمِ مالک از اپ برداشته شد ----
        gp = await b.new_page(viewport={"width": 1100, "height": 900}, color_scheme="dark")
        await gp.goto(URL); await gp.wait_for_timeout(500)
        glow_n = await gp.evaluate("() => document.querySelectorAll('.page-glow,.glow-blob').length")
        await gp.close()
        print("[page glow] removed from the app: .page-glow/.glow-blob elements=%s" % glow_n)
        assert glow_n == 0, "the page glow was removed from the app by the owner, but %s element(s) remain" % glow_n

        # ---- [quote split] ۲۴ سپتامبر: فروشِ cbBTC «۳۶ از ۳۶ کوت شکست» می‌داد ----
        # کلِ دسته‌ی aggregate3 از سقفِ گازِ eth_call رد می‌شد (چند کوتِ Slipstream
        # تقریباً همه‌ی گاز را می‌سوزاندند). حالا شکستِ اجراییِ دسته نصف می‌شود تا
        # فقط همان فراخوانی نامعلوم بماند؛ خطای انتقال هرگز نصف نمی‌شود.
        qp = await b.new_page(viewport={"width": 1100, "height": 900})
        await qp.goto(URL)
        await qp.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        split = await qp.evaluate("""async () => {
            const all = allTokens();
            const A = routable(all.find(t => t.symbol === "USDC")), B = routable(all.find(t => t.symbol === "WETH"));
            const specs = allVenues().map(v => ({venue: v, tokenIn: A.address, tokenOut: B.address, amountIn: 1000000n}));
            const BAD = 5;
            const badData = encodeQuote(specs[BAD].venue, A.address, B.address, 1000000n).data;
            const real = multicall;
            let n = 0;
            multicall = async (calls) => {
                n++;
                if (calls.some(c => c.data === badData)) {
                    const e = new Error("missing revert data");
                    e.code = "CALL_EXCEPTION";
                    e.info = {error: {code: -32003, message: "out of gas: gas required exceeds: 50000000"}};
                    throw e;
                }
                return calls.map(() => ({ok: false, data: "0x"}));
            };
            const st1 = newStats();
            const r1 = await quoteMany(specs, st1);
            const n1 = n;
            n = 0;
            multicall = async () => { n++; throw new TypeError("Failed to fetch"); };
            const st2 = newStats();
            const r2 = await quoteMany(specs, st2);
            const n2 = n;
            multicall = real;
            // یادداشتِ کوتِ معکوسِ قبلی نباید بعد از پاک‌شدنِ فیلدها بماند
            document.getElementById("revNote").innerHTML = "Solved for your target: stale";
            scheduleQuote();
            const revAfter = document.getElementById("revNote").innerHTML;
            return {N: specs.length, st1, badStatus: r1[BAD].status,
                    others: r1.filter((x, i) => i !== BAD).map(x => x.status),
                    calls1: n1, st2, calls2: n2, unknown2: r2.every(x => x.status === "unknown"), revAfter};
        }""")
        await qp.close()
        print("[quote split] gas-cap batch of %s: bad=%s others=%s attempted=%s rpcFailed=%s noPool=%s calls=%s | "
              "transport failure: rpcFailed=%s calls=%s | stale reverse note cleared=%s"
              % (split["N"], split["badStatus"], sorted(set(split["others"])), split["st1"]["attempted"],
                 split["st1"]["rpcFailed"], split["st1"]["noPool"], split["calls1"],
                 split["st2"]["rpcFailed"], split["calls2"], split["revAfter"] == ""))
        assert split["badStatus"] == "unknown", split
        assert set(split["others"]) == {"nopool"}, "the other quotes must still be answered: %s" % split
        assert split["st1"]["attempted"] == split["N"], "attempted must be counted once, not per retry: %s" % split
        assert split["st1"]["rpcFailed"] == 1 and split["st1"]["noPool"] == split["N"] - 1, split
        assert split["calls1"] > 1, "a gas-cap failure must be retried in halves: %s" % split
        # ۶ اکتبر: دسته حالا در تکه‌های ۱۶تایی می‌رود؛ خطای انتقال باز هم نصف نمی‌شود،
        # پس هر تکه دقیقاً یک بار پرسیده می‌شود (نه یک بار برای کل)
        assert split["st2"]["rpcFailed"] == split["N"] and split["calls2"] == -(-split["N"] // 16) and split["unknown2"], \
            "a transport failure must never be split: %s" % split
        assert split["revAfter"] == "", "a stale reverse-quote note survived scheduleQuote: %r" % split["revAfter"]

        # ---- [quote chunks] ۶ اکتبر: دسته‌ی ~۶۹تایی (cbETH→wstETH) revert می‌کرد و نیمه‌کردنِ
        # پشت‌سرهم یک دور را ۱٫۰۵ تا ۱٫۳۵ ثانیه می‌کرد؛ تکه‌های ۱۶تایی و موازی ۰٫۲۳ ثانیه. ----
        qc = await b.new_page(viewport={"width": 1100, "height": 900})
        await qc.goto(URL)
        await qc.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        qchunks = await qc.evaluate("""async () => {
            const all = allTokens();
            const A = routable(all.find(t => t.symbol === "USDC")), B = routable(all.find(t => t.symbol === "WETH"));
            const V = allVenues();
            const N = 69;
            const specs = Array.from({length: N}, (_, i) => ({venue: V[i % V.length], tokenIn: A.address,
                                                               tokenOut: B.address, amountIn: BigInt(i + 1) * 1000n}));
            const realMc = multicall, realEnc = encodeQuote;
            // کوت به‌جای ABI، مبلغ ورودی را در calldata می‌گذارد و جوابش همان را برمی‌گرداند
            encodeQuote = (v, a, b2, amt) => ({target: "0x" + "11".repeat(20),
                data: "0x" + amt.toString(16).padStart(64, "0"), dec: d => BigInt(d)});
            const run = async (limit) => {
                const sizes = []; let inflight = 0, maxInflight = 0, resolved = 0, issuedBeforeFirst = null;
                multicall = async (calls) => {
                    sizes.push(calls.length); inflight++; maxInflight = Math.max(maxInflight, inflight);
                    await new Promise(r => setTimeout(r, 15));
                    if (issuedBeforeFirst === null) issuedBeforeFirst = sizes.length;
                    inflight--; resolved++;
                    if (limit && calls.length > limit) {
                        const e = new Error("missing revert data"); e.code = "CALL_EXCEPTION";
                        e.info = {error: {code: -32003, message: "out of gas: gas required exceeds: 50000000"}};
                        throw e;
                    }
                    return calls.map(c => ({ok: true, data: c.data}));
                };
                const st = newStats();
                const r = await quoteMany(specs, st);
                const ordered = r.length === N && r.every((x, i) => x.status === "ok" && x.out === BigInt(i + 1) * 1000n);
                return {sizes, maxInflight, issuedBeforeFirst, ordered, attempted: st.attempted, ok: st.ok, rpcFailed: st.rpcFailed};
            };
            try {
                const plain = await run(0);
                const bis = await run(8);
                return {plain, bis};
            } finally { multicall = realMc; encodeQuote = realEnc; }
        }""")
        await qc.close()
        qp_, qb_ = qchunks["plain"], qchunks["bis"]
        print("[quote chunks] 69 specs: calls=%s maxSize=%s maxInflight=%s issuedBeforeFirstResolve=%s ordered=%s attempted=%s"
              % (len(qp_["sizes"]), max(qp_["sizes"]), qp_["maxInflight"], qp_["issuedBeforeFirst"], qp_["ordered"], qp_["attempted"]))
        print("[quote chunks] bisect (batch>8 reverts): calls=%s ok=%s rpcFailed=%s maxInflight=%s ordered=%s"
              % (len(qb_["sizes"]), qb_["ok"], qb_["rpcFailed"], qb_["maxInflight"], qb_["ordered"]))
        assert max(qp_["sizes"]) <= 16 and len(qp_["sizes"]) == 5 and sum(qp_["sizes"]) == 69, \
            "69 quotes must go out as 5 multicalls of at most 16: %s" % qp_
        assert qp_["issuedBeforeFirst"] == 5 and qp_["maxInflight"] >= 2, \
            "the chunks must be in flight together, not one after another: %s" % qp_
        assert qp_["ordered"] and qp_["attempted"] == 69 and qp_["ok"] == 69, \
            "results must keep the original order and attempted must count once: %s" % qp_
        assert qb_["ordered"] and qb_["ok"] == 69 and qb_["rpcFailed"] == 0 and qb_["maxInflight"] >= 2, \
            "a reverting batch must still return everything in order, halves in parallel: %s" % qb_

        # ---- [impact parallel] ۶ اکتبر: نرخِ مبلغ کوچک هم‌زمان با تقسیم‌بندی؛ عددها باید همان قبلی باشند ----
        ip = await b.new_page(viewport={"width": 1100, "height": 900})
        await ip.goto(URL)
        await ip.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        impact = await ip.evaluate("""async () => {
            const realFR = findRoutes;
            const oldImpact = async (tIn, tOut, amountIn, plan, stats) => {   // نسخه‌ی قبلیِ priceImpact، عیناً
                const small = amountIn / 1000n > 0n ? amountIn / 1000n : 1n;
                const {routes} = await findRoutes(tIn, tOut, small, stats);
                if (!routes.length) return null;
                const SC = 10n ** 18n;
                const rs = (routes[0].amountOut * SC) / small, rb = (plan.totalOut * SC) / amountIn;
                if (rs <= 0n) return null;
                return Math.max(0, Number(((rs - rb) * 10000n) / rs) / 100);
            };
            const cases = [
                {amountIn: 1000000000000000000n, smallOut: 2010000000000000n, totalOut: 1980000000000000000n},
                {amountIn: 5n, smallOut: 7n, totalOut: 9n},
                {amountIn: 1000n, smallOut: 0n, totalOut: 500n},
                {amountIn: 1000000n, smallOut: 3000n, totalOut: 3100000n},
                {amountIn: 777777777n, smallOut: 123456n, totalOut: 98765432n},
            ];
            const out = [];
            try {
                for (const c of cases) {
                    findRoutes = async () => ({routes: [{amountOut: c.smallOut}], direct: []});
                    const plan = {totalOut: c.totalOut};
                    const o = await oldImpact({}, {}, c.amountIn, plan, newStats());
                    const n = await priceImpact({}, {}, c.amountIn, plan, newStats());
                    const sr = await smallRate({}, {}, c.amountIn, newStats());
                    const n2 = impactFrom(sr, c.amountIn, plan);
                    out.push({o, n, n2});
                }
                findRoutes = async () => ({routes: [], direct: []});
                const none = [await priceImpact({}, {}, 1000n, {totalOut: 1n}, newStats()),
                              await smallRate({}, {}, 1000n, newStats())];
                return {out, none};
            } finally { findRoutes = realFR; }
        }""")
        await ip.close()
        print("[impact parallel] %s cases identical=%s no-route=%s"
              % (len(impact["out"]), all(x["o"] == x["n"] == x["n2"] for x in impact["out"]), impact["none"]))
        for x in impact["out"]:
            assert x["o"] == x["n"] == x["n2"], "price impact differs from the old formula: %s" % impact
        assert impact["none"] == [None, None], impact

        # ---- [cta one line] ۶ اکتبر (حسام): ارتفاع دکمه‌ی سواپ هرگز عوض نشود ----
        cta_res = {}
        for vw in (390, 1440):
            cp = await b.new_page(viewport={"width": vw, "height": 900})
            await cp.goto(URL)
            await cp.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
            cta_res[vw] = await cp.evaluate("""() => {
                const bt = document.getElementById("actBtn");
                setBusy(true, "Swap"); const h0 = bt.getBoundingClientRect().height;
                setBusy(true, "Confirm 0.8254 MORPHO → DEGEN in wallet… and a much longer tail to be sure it overflows"); const h1 = bt.getBoundingClientRect().height;
                setBusy(false); refreshButton();
                return {h0, h1};
            }""")
            await cp.close()
        print("[cta one line] 390px short=%.1f long=%.1f | 1440px short=%.1f long=%.1f"
              % (cta_res[390]["h0"], cta_res[390]["h1"], cta_res[1440]["h0"], cta_res[1440]["h1"]))
        for vw in (390, 1440):
            assert abs(cta_res[vw]["h0"] - cta_res[vw]["h1"]) <= 0.5 and cta_res[vw]["h0"] > 20, \
                "the swap button changed height with a long busy label at %spx: %s" % (vw, cta_res)

        # ---- [base autoconnect] ۶ اکتبر: Base فقط به کیفی وصل می‌شود که کاربر برای Base انتخاب کرده ----
        # فانتوم یک اجازه‌ی سایت را بین زنجیره‌ها مشترک دارد؛ بعد از اتصال روی سولانا،
        # eth_accounts آن هم جواب می‌داد و Base بی‌صدا به آدرس EVM فانتوم وصل می‌شد.
        PH_ADDR = "0x1111111111111111111111111111111111111111"
        MM_ADDR = "0x2222222222222222222222222222222222222222"
        def two_wallets_script(pre=""):
            return pre + """
                window.__m = {phantom: [], metamask: []};
                (function(){
                    function mk(tag, addr){
                        return {request: function(a){
                            window.__m[tag].push(a && a.method);
                            if (a.method === 'eth_accounts' || a.method === 'eth_requestAccounts') return Promise.resolve([addr]);
                            if (a.method === 'eth_chainId') return Promise.resolve('0x2105');
                            return Promise.resolve(null);
                        }, on: function(){}, removeListener: function(){}};
                    }
                    var W = [
                        {info: {name: 'Phantom', rdns: 'app.phantom', uuid: 'u-ph'}, provider: mk('phantom', '%s')},
                        {info: {name: 'MetaMask', rdns: 'io.metamask', uuid: 'u-mm'}, provider: mk('metamask', '%s')}];
                    window.addEventListener('eip6963:requestProvider', function(){
                        W.forEach(function(w){ window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {detail: w})); });
                    });
                })();
            """ % (PH_ADDR, MM_ADDR)
        async def autoconnect_page(pre, wait_ms):
            ap = await b.new_page(viewport={"width": 1100, "height": 900})
            await ap.add_init_script(two_wallets_script(pre))
            await ap.goto(URL)
            await ap.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
            await ap.wait_for_timeout(wait_ms)
            st = await ap.evaluate("""() => ({account: account, m: window.__m,
                key: localStorage.getItem("zaexa.base.wallet")})""")
            return ap, st
        # (ii) اول، تا زمانِ لازم برای پایانِ راه‌اندازی اندازه‌گیری شود
        import time as _t
        t_ii = _t.time()
        ap2, st2 = await autoconnect_page("localStorage.setItem('zaexa.base.wallet','io.metamask');", 0)
        await ap2.wait_for_function("() => !!account", timeout=60000)
        st2 = await ap2.evaluate("() => ({account: account, m: window.__m})")
        settle_ms = int((_t.time() - t_ii) * 1000) + 2500
        await ap2.close()
        ap1, st1 = await autoconnect_page("", settle_ms)
        await ap1.close()
        ap3, st3 = await autoconnect_page(
            "localStorage.setItem('zaexa.base.wallet','io.metamask');localStorage.setItem('zaexa.disconnected','1');", settle_ms)
        await ap3.close()
        # (iv) و (v): انتخاب صریح فانتوم از انتخاب‌گر، سپس Disconnect
        ap4, st4 = await autoconnect_page("", settle_ms)
        # استابِ ethers بدونِ getNetwork است؛ بدونِ این، اتصالِ «کامل» در هارنس هرگز تمام نمی‌شود
        await ap4.evaluate("""() => { E.BrowserProvider = function(){
            this.getNetwork = async () => ({chainId: 8453n});
            this.getSigner = async () => ({getAddress: async () => account}); }; }""")
        await ap4.evaluate("() => openWalletPicker()")
        await ap4.wait_for_timeout(300)
        await ap4.evaluate("""() => [...document.querySelectorAll('#walList .walRow')]
                                     .find(r => /Phantom/.test(r.textContent)).click()""")
        # کلید فقط بعد از اتصالِ کامل (بعد از خواندن موجودی‌ها) ذخیره می‌شود
        await ap4.wait_for_function("() => !!account && !!localStorage.getItem('zaexa.base.wallet')", timeout=60000)
        st4b = await ap4.evaluate("""() => ({account: account, key: localStorage.getItem("zaexa.base.wallet"),
                                              m: window.__m})""")
        await ap4.evaluate("() => disconnect()")
        st5 = await ap4.evaluate("""() => ({account: account, key: localStorage.getItem("zaexa.base.wallet")})""")
        await ap4.close()
        print("[base autoconnect] (i) no key: account=%s asked=%s | (ii) key=io.metamask: account=%s phantomAsked=%s"
              % (st1["account"], st1["m"], st2["account"], st2["m"]["phantom"]))
        print("[base autoconnect] (iii) key + disconnected flag: account=%s asked=%s | (iv) explicit Phantom: key=%r account=%s | (v) after disconnect: key=%r account=%s"
              % (st3["account"], st3["m"], st4b["key"], st4b["account"], st5["key"], st5["account"]))
        assert not st1["account"] and st1["m"]["phantom"] == [] and st1["m"]["metamask"] == [], \
            "with no stored Base wallet nothing may connect silently or even be asked: %s" % st1
        assert st2["account"] and st2["account"].lower() == MM_ADDR and st2["m"]["phantom"] == [], \
            "the stored wallet must be the only one asked and connected: %s" % st2
        assert not st3["account"] and st3["m"]["phantom"] == [] and st3["m"]["metamask"] == [], \
            "the disconnected flag must beat the stored wallet: %s" % st3
        assert st4b["account"] and st4b["account"].lower() == PH_ADDR and st4b["key"] == "app.phantom", \
            "an explicit pick must connect and remember that wallet: %s" % st4b
        assert st5["key"] is None and not st5["account"], "disconnect must forget the Base wallet: %s" % st5

        # ---- [swap refresh] ۶ اکتبر: کلیکِ سواپ منتظرِ exit check نمی‌ماند، ولی نتیجه رندر می‌شود ----
        sr = await b.new_page(viewport={"width": 1100, "height": 900})
        await sr.goto(URL)
        await sr.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        swr = await sr.evaluate("""async () => {
            const save = {findRoutes, findBestSplit, smallRate, renderVenues, renderPlan, refreshAllowance,
                          refreshButton, runExitCheck, renderExit, tokenIn, tokenOut};
            tokenIn = routable(allTokens().find(t => t.symbol === "USDC"));
            tokenOut = routable(allTokens().find(t => t.symbol === "WETH"));
            $("amtIn").value = "1";
            findRoutes = async () => ({routes: [{amountOut: 5n}], direct: []});
            findBestSplit = async () => ({totalOut: 5n, parts: [], totalIn: 1000000n});
            smallRate = async () => null;
            renderVenues = () => {}; renderPlan = () => {}; refreshAllowance = async () => {}; refreshButton = () => {};
            let exitResolved = false, rendered = 0, called = 0;
            runExitCheck = () => { called++; return new Promise(r => setTimeout(() => { exitResolved = true; r({state: "verified", lossPct: 1}); }, 400)); };
            renderExit = () => { rendered++; };
            const out = {};
            try {
                await runQuote({forSwap: true});
                out.swapReturnedBeforeExit = !exitResolved; out.swapCalled = called; out.swapRenderedAtReturn = rendered;
                await new Promise(r => setTimeout(r, 600));
                out.swapRenderedAfter = rendered;
                exitResolved = false; rendered = 0; called = 0;
                await runQuote();
                out.plainReturnedAfterExit = exitResolved; out.plainCalled = called; out.plainRendered = rendered;
            } finally { ({findRoutes, findBestSplit, smallRate, renderVenues, renderPlan, refreshAllowance,
                          refreshButton, runExitCheck, renderExit, tokenIn, tokenOut} = save); }
            return out;
        }""")
        await sr.close()
        print("[swap refresh] forSwap: returnedBeforeExit=%s exitCalls=%s renderedAtReturn=%s renderedAfter=%s | plain: returnedAfterExit=%s exitCalls=%s rendered=%s"
              % (swr["swapReturnedBeforeExit"], swr["swapCalled"], swr["swapRenderedAtReturn"], swr["swapRenderedAfter"],
                 swr["plainReturnedAfterExit"], swr["plainCalled"], swr["plainRendered"]))
        assert swr["swapReturnedBeforeExit"] and swr["swapCalled"] == 1 and swr["swapRenderedAtReturn"] == 0 \
            and swr["swapRenderedAfter"] == 1, "a swap refresh must not wait for the exit check, but must still render it: %s" % swr
        assert swr["plainReturnedAfterExit"] and swr["plainCalled"] == 1 and swr["plainRendered"] == 1, \
            "a normal quote must still await the exit check: %s" % swr

        # ---- [switch rejected] ۶ اکتبر: رد کردنِ تعویض شبکه در والت بنرِ «Something stopped working» نسازد ----
        sw = await b.new_page(viewport={"width": 1100, "height": 900})
        await sw.goto(URL)
        await sw.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        swres = {}
        for label, err in (("4001", "{code: 4001, message: 'User rejected the request.'}"),
                           ("boom", "{code: -32603, message: 'boom'}")):
            swres[label] = await sw.evaluate("""async (errSrc) => {
                setNotice("");
                const err = eval("(" + errSrc + ")");
                walletEip1193 = {request: async (a) => { if (a.method === "wallet_switchEthereumChain") throw err; return null; }};
                account = "0x1111111111111111111111111111111111111111"; walletChainId = 1; walletIsRemote = false;
                paintWallet();
                const label = document.getElementById("connectBtn").textContent.trim();
                document.getElementById("connectBtn").click();
                await new Promise(r => setTimeout(r, 400));
                return {label, notice: document.getElementById("notices").innerText,
                        bannerHidden: document.getElementById("errBanner").hidden};
            }""", err)
        await sw.close()
        print("[switch rejected] rejection 4001: button=%r notice=%r bannerHidden=%s | error boom: notice=%r bannerHidden=%s"
              % (swres["4001"]["label"], swres["4001"]["notice"][:60], swres["4001"]["bannerHidden"],
                 swres["boom"]["notice"][:60], swres["boom"]["bannerHidden"]))
        assert swres["4001"]["label"] == "Switch to Base" and "Network switch cancelled" in swres["4001"]["notice"] \
            and swres["4001"]["bannerHidden"], "a rejected switch must show the warn notice and no banner: %s" % swres
        assert "boom" in swres["boom"]["notice"] and swres["boom"]["bannerHidden"], \
            "any other switch error must show the err notice and no banner: %s" % swres

        # ---- [counter mids] ۲۶ سپتامبر: مسیریابی از طریق جفتِ اصلیِ خودِ توکن ----
        # (SN80 -> TAO -> WETH). GT/multicall را با gtBook/erc20 دستی جواب می‌دهیم؛
        # quoteMany عوض می‌شود تا فقط X->TAO (روی aerodrome-cl-v1) و TAO->WETH
        # واقعاً کوت بدهند — دقیقاً شکلِ زنده‌ی اندازه‌گیری‌شده.
        cmp_page = await b.new_page(viewport={"width": 1100, "height": 900})
        await cmp_page.goto(URL)
        await cmp_page.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        cm = await cmp_page.evaluate("""async () => {
            const WETH = tokenBySymbol("WETH");
            const XA = "0x1111111111111111111111111111111111111a";
            const XB = "0x1111111111111111111111111111111111111b";
            const XC = "0x1111111111111111111111111111111111111c";
            const XD = "0x1111111111111111111111111111111111111d";
            const XE = "0x1111111111111111111111111111111111111e";
            const XF = "0x1111111111111111111111111111111111111f";
            const TAO = "0x2222222222222222222222222222222222222a";

            const realFetch = window.fetch, realMulticall = multicall, realQuoteMany = quoteMany;
            const symCall = iErc.encodeFunctionData("symbol", []);
            const decCall = iErc.encodeFunctionData("decimals", []);
            const packRet = v => "0x" + Array.from(new TextEncoder().encode(
                JSON.stringify({ret: v}))).map(x => x.toString(16).padStart(2, "0")).join("");
            const erc20 = {};
            erc20[TAO.toLowerCase()] = {symbol: "TAO", decimals: 18};
            multicall = async (calls) => calls.map(c => {
                const info = erc20[String(c.target).toLowerCase()];
                if (!info) return {ok: false, data: "0x"};
                if (c.data === symCall) return {ok: true, data: packRet([info.symbol])};
                if (c.data === decCall) return {ok: true, data: packRet([info.decimals])};
                return {ok: false, data: "0x"};
            });

            function pool(dexId, reserve, ourAddr, counterAddr) {
                return {relationships: {dex: {data: {id: dexId}},
                    base_token: {data: {id: "base_" + ourAddr}},
                    quote_token: {data: {id: "base_" + counterAddr}}},
                    attributes: {reserve_in_usd: reserve}};
            }
            const gtBook = {};
            window.fetch = async (url, opts) => {
                const u = String(url);
                const m = u.match(/\\/tokens\\/(0x[0-9a-fA-Fx]+)\\/pools/i);
                if (!m) return realFetch(url, opts);
                const addr = m[1].toLowerCase();
                const book = gtBook[addr];
                if (book === undefined) return new Response("{}", {status: 200});
                if (book === "fail500") return new Response("boom", {status: 500});
                return new Response(JSON.stringify({data: book}), {status: 200,
                    headers: {"content-type": "application/json"}});
            };

            function qmFor(x) {
                return async (specs, stats) => {
                    stats.attempted += specs.length;
                    return specs.map(s => {
                        const tin = s.tokenIn.toLowerCase(), tout = s.tokenOut.toLowerCase();
                        if (tin === x.toLowerCase() && tout === TAO.toLowerCase()
                            && s.venue.dex.id === "aerodrome-cl-v1") { stats.ok++; return {out: 500n, status: "ok"}; }
                        if (tin === TAO.toLowerCase() && tout === WETH.address.toLowerCase()) { stats.ok++; return {out: 700n, status: "ok"}; }
                        stats.noPool++; return {out: null, status: "nopool"};
                    });
                };
            }
            async function runWith(qm, tIn, amountIn, stats) {
                quoteMany = qm;
                try { return await findRoutes(tIn, WETH, amountIn, stats); }
                finally { quoteMany = realQuoteMany; }
            }
            const has2hopViaTao = r => r.routes.some(rt => rt.hops.length === 2 && rt.hops[0].tokenOut.symbol === "TAO");
            const out = {};

            // (a) real liquid counter pool -> 2-hop X->TAO->WETH, rendered leg shows TAO
            gtBook[XA.toLowerCase()] = [pool("aerodrome-slipstream", "96575.12", XA, TAO)];
            const rA = await runWith(qmFor(XA), {symbol: "SN80A", address: XA, decimals: 18}, 1000000n, newStats());
            out.a_has2hop = has2hopViaTao(rA);

            // (b) reserve below the $10k threshold -> no TAO mid, hub-only behaviour
            gtBook[XB.toLowerCase()] = [pool("aerodrome-slipstream", "9000", XB, TAO)];
            const rB = await runWith(qmFor(XB), {symbol: "SN80B", address: XB, decimals: 18}, 1000000n, newStats());
            out.b_has2hop = has2hopViaTao(rB);

            // (c) GT 500 -> never throws, degrades to hub-only
            gtBook[XC.toLowerCase()] = "fail500";
            let threwC = false, rC = {routes: []};
            try { rC = await runWith(qmFor(XC), {symbol: "SN80C", address: XC, decimals: 18}, 1000000n, newStats()); }
            catch (e) { threwC = true; }
            out.c_threw = threwC;
            out.c_has2hop = has2hopViaTao(rC);
            // یک GT 500 مصنوعی مدارِ قطع‌کننده را برای واقعی می‌اندازد — پاکش کن
            // تا سنجش‌های بعدی (که در همین صفحه‌اند) قربانیِ همین یک شکست نشوند.
            gtCoolUntil = 0; gtFails = 0;

            // (d) pool on an unmapped dex id -> ignored
            gtBook[XD.toLowerCase()] = [pool("aerodrome-slipstream-2", "999999", XD, TAO)];
            const rD = await runWith(qmFor(XD), {symbol: "SN80D", address: XD, decimals: 18}, 1000000n, newStats());
            out.d_has2hop = has2hopViaTao(rD);

            // (e) a second findRoutes/priceImpact for the same (fresh) pair must not refetch GT
            gtBook[XE.toLowerCase()] = [pool("aerodrome-slipstream", "96575.12", XE, TAO)];
            let fetchHits = 0;
            const countingFetch = window.fetch;
            // ۳ اکتبر — نوارِ «Market watch» (اتر/AERO/cbBTC) هم‌زمان استخرهای خودش را از GT می‌گیرد؛
            // آن درخواست‌ها مالِ این توکن نیستند. فقط درخواستی شمرده می‌شود که آدرسِ همین توکن را دارد.
            window.fetch = async (...args) => { const u = String(args[0] && args[0].url || args[0]).toLowerCase(); if (u.includes(XE.toLowerCase())) fetchHits++; return countingFetch(...args); };
            const tokE = {symbol: "SN80E", address: XE, decimals: 18};
            await runWith(qmFor(XE), tokE, 1000000n, newStats());
            out.e_firstCallFetches = fetchHits;
            quoteMany = qmFor(XE);
            try { await priceImpact(tokE, WETH, 1000000n, {totalOut: 1n}, newStats()); }
            finally { quoteMany = realQuoteMany; }
            out.e_secondCallExtraFetches = fetchHits - out.e_firstCallFetches;
            window.fetch = countingFetch;

            // (f) a pool whose counter is WETH itself must never become a duplicate hub mid
            gtBook[XF.toLowerCase()] = [pool("aerodrome-slipstream", "999999", XF, WETH.address)];
            let midCountF = -1;
            const qmF = async (specs, stats) => {
                stats.attempted += specs.length;
                midCountF = new Set(specs.filter(s => s.tag === "h1").map(s => s.mid.address.toLowerCase())).size;
                return specs.map(() => { stats.noPool++; return {out: null, status: "nopool"}; });
            };
            await runWith(qmF, {symbol: "SN80F", address: XF, decimals: 18}, 1000000n, newStats());
            out.f_midCount = midCountF;   // expected: 1 (USDC hub only), never 2

            // (g) two mids sharing a symbol (spoofed counter symbol "USDC") must not collide —
            // b1/b2 are keyed by lower-cased address, not symbol, so both must survive.
            const XG = "0x1111111111111111111111111111111111111111";
            const FAKE_USDC = "0x3333333333333333333333333333333333333a";
            const REAL_USDC = tokenBySymbol("USDC").address.toLowerCase();
            erc20[FAKE_USDC.toLowerCase()] = {symbol: "USDC", decimals: 6};
            gtBook[XG.toLowerCase()] = [pool("aerodrome-slipstream", "96575.12", XG, FAKE_USDC)];
            const qmG = async (specs, stats) => {
                stats.attempted += specs.length;
                return specs.map(s => {
                    const tin = s.tokenIn.toLowerCase(), tout = s.tokenOut.toLowerCase();
                    if (tin === XG.toLowerCase() && tout === REAL_USDC) { stats.ok++; return {out: 400n, status: "ok"}; }
                    if (tin === REAL_USDC && tout === WETH.address.toLowerCase()) { stats.ok++; return {out: 600n, status: "ok"}; }
                    if (tin === XG.toLowerCase() && tout === FAKE_USDC.toLowerCase()) { stats.ok++; return {out: 500n, status: "ok"}; }
                    if (tin === FAKE_USDC.toLowerCase() && tout === WETH.address.toLowerCase()) { stats.ok++; return {out: 700n, status: "ok"}; }
                    stats.noPool++; return {out: null, status: "nopool"};
                });
            };
            const rG = await runWith(qmG, {symbol: "SN80G", address: XG, decimals: 18}, 1000000n, newStats());
            out.g_midAddrs = [...new Set(rG.routes.filter(rt => rt.hops.length === 2)
                .map(rt => rt.hops[0].tokenOut.address.toLowerCase()))];

            window.fetch = realFetch; multicall = realMulticall; quoteMany = realQuoteMany;
            return out;
        }""")
        await cmp_page.close()
        print("[counter mids] a(2hop via TAO)=%s b(thin pool, hub-only)=%s c(GT 500 threw=%s, hub-only)=%s "
              "d(unmapped dex, hub-only)=%s e(fetches: first=%s, second-extra=%s) f(mid count, no dup hub)=%s "
              "g(distinct mid addrs despite same symbol)=%s"
              % (cm["a_has2hop"], not cm["b_has2hop"], cm["c_threw"], not cm["c_has2hop"],
                 not cm["d_has2hop"], cm["e_firstCallFetches"], cm["e_secondCallExtraFetches"], cm["f_midCount"],
                 len(cm["g_midAddrs"])))
        assert cm["a_has2hop"], "no 2-hop route via TAO found for a liquid counter pool: %s" % cm
        assert not cm["b_has2hop"], "a $9000 pool (below the $10k threshold) must not become a mid: %s" % cm
        assert cm["c_threw"] is False, "counterMids must never throw, even on a GT 500: %s" % cm
        assert not cm["c_has2hop"], "a GT 500 must degrade to hub-only routing, not a TAO mid: %s" % cm
        assert not cm["d_has2hop"], "a pool on an unmapped dex id must be ignored: %s" % cm
        assert cm["e_firstCallFetches"] == 1, "the first lookup for a fresh token must hit GT once: %s" % cm
        assert cm["e_secondCallExtraFetches"] == 0, \
            "a second findRoutes/priceImpact for the same pair must be served from cache: %s" % cm
        assert cm["f_midCount"] == 1, "a counter equal to WETH must never become a duplicate hub mid: %s" % cm
        assert len(cm["g_midAddrs"]) == 2, \
            "two mids sharing a symbol collided — b1/b2 must be keyed by address, not symbol: %s" % cm

        # ---- [light frames] computed box-shadow: 1px ring in light, none in dark ----
        lf_page = await b.new_page(viewport={"width": 1100, "height": 900})
        await lf_page.goto(URL)
        await lf_page.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        lf = await lf_page.evaluate("""() => {
            // بدنه transition:background دارد — بدونِ این، رنگِ وسطِ گذار خوانده می‌شود.
            const off = document.createElement("style");
            off.textContent = "*{transition:none!important}";
            document.head.appendChild(off);
            document.documentElement.setAttribute("data-theme", "light");
            const card = document.querySelector("section.card");
            const light = getComputedStyle(card).boxShadow;
            const lightBg = getComputedStyle(document.body).backgroundColor;
            const cardBg = getComputedStyle(card).backgroundColor;
            document.documentElement.setAttribute("data-theme", "dark");
            const dark = getComputedStyle(card).boxShadow;
            const darkBg = getComputedStyle(document.body).backgroundColor;
            return {light, dark, lightBg, cardBg, darkBg};
        }""")
        await lf_page.close()
        print("[light frames] computed — light body=%s card=%s ring=%s; dark body=%s"
              % (lf["lightBg"], lf["cardBg"], "0px 0px 0px 1px" in lf["light"], lf["darkBg"]))
        assert lf["lightBg"] == "rgb(244, 245, 247)", "light body background is %r, expected #f4f5f7" % lf["lightBg"]
        assert lf["cardBg"] == "rgb(255, 255, 255)", "light card is %r, expected white" % lf["cardBg"]
        assert "0px 0px 0px 1px" not in lf["light"], "light .card still carries the rejected 1px ring: %r" % lf["light"]
        assert lf["darkBg"] == "rgb(10, 8, 16)", "dark body background moved: %r (must stay #0a0810)" % lf["darkBg"]

        # ---- [wallet unlock] ۲۴ سپتامبر: ربیِ قفل «Already processing unlock» می‌داد ----
        # ethers getSigner() بعد از eth_requestAccounts یک درخواستِ دوم می‌فرستاد؛ حالا
        # فقط یک درخواست، و «در حالِ باز کردنِ قفل» با eth_accountsِ بی‌پنجره صبر می‌شود.
        up = await b.new_page(viewport={"width": 1100, "height": 900})
        await up.goto(URL)
        await up.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        ul = await up.evaluate("""async () => {
            const ADDR = "0x2222222222222222222222222222222222222222";
            const mk = (script) => { const seen = []; let n = 0; return {seen, request: async (a) => {
                seen.push(a.method); return script(a.method, n++); }}; };
            const out = {};
            const plain = mk((m) => [ADDR]);
            out.plain = {a: await requestWalletAccounts(plain, true, 2000, 20), seen: plain.seen};
            let acc = 0;
            const rabby = mk((m) => {
                if (m === "eth_requestAccounts") throw new Error("Already processing unlock. Please wait.");
                return (acc++ < 2) ? [] : [ADDR];
            });
            out.rabby = {a: await requestWalletAccounts(rabby, true, 2000, 20), seen: rabby.seen};
            const rej = mk((m) => { throw Object.assign(new Error("User rejected the request."), {code: 4001}); });
            try { await requestWalletAccounts(rej, true, 2000, 20); out.rej = {threw: false}; }
            catch (e) { out.rej = {threw: true, seen: rej.seen, isRej: isUserRejection(e)}; }
            const sent = [];
            const bp = {send: async (m) => { sent.push(m); return []; }, getSigner: async () => { sent.push("getSigner"); }};
            const sg = await makeSigner(bp, ADDR);
            out.signer = {address: sg && sg.address, sent};
            out.rejShapes = [isUserRejection({code: "ACTION_REJECTED"}), isUserRejection({info: {error: {code: 4001}}}),
                             isUserRejection(new Error("x"))];
            return out;
        }""")
        await up.close()
        print("[wallet unlock] plain=%s rabby-race=%s -> %s | rejected: calls=%s isRejection=%s | signer sent=%s | shapes=%s"
              % (ul["plain"]["seen"], ul["rabby"]["seen"], ul["rabby"]["a"], ul["rej"].get("seen"),
                 ul["rej"].get("isRej"), ul["signer"]["sent"], ul["rejShapes"]))
        assert ul["plain"]["seen"] == ["eth_requestAccounts"], ul
        assert ul["rabby"]["a"] and ul["rabby"]["seen"].count("eth_requestAccounts") == 1 \
            and ul["rabby"]["seen"][1:] == ["eth_accounts"] * 3, \
            "a busy/unlocking wallet must be waited out with eth_accounts only, never a second popup: %s" % ul
        assert ul["rej"]["threw"] and ul["rej"]["seen"] == ["eth_requestAccounts"] and ul["rej"]["isRej"], \
            "a user rejection must be rethrown at once, not polled: %s" % ul
        assert ul["signer"]["sent"] == [] and ul["signer"]["address"], \
            "the signer must be built from the address, with no extra wallet request: %s" % ul
        assert ul["rejShapes"] == [True, True, False], ul

        # ---- [wallet revoke] ۲۴ سپتامبر: Disconnect اجازه را در خودِ والت هم لغو کند ----
        wp = await b.new_page(viewport={"width": 1100, "height": 900})
        await wp.goto(URL)
        await wp.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
        rv = await wp.evaluate("""async () => {
            const out = {};
            const mk = (ok) => { const seen = []; return {seen, request: async (a) => { seen.push(a.method);
                if (!ok) throw Object.assign(new Error("unsupported"), {code: 4200}); return null; }}; };
            for (const ok of [true, false]) {
                const p = mk(ok);
                walletEip1193 = p; walletIsRemote = false; account = "0x1111111111111111111111111111111111111111";
                try { localStorage.removeItem("zaexa.disconnected"); } catch (e) {}
                await disconnect();
                out[ok ? "ok" : "fail"] = {methods: p.seen, flag: localStorage.getItem("zaexa.disconnected"),
                    notice: document.getElementById("notices").innerText, account};
            }
            setNotice("");
            return out;
        }""")
        await wp.close()
        print("[wallet revoke] supported: methods=%s flag=%s notice=%r | unsupported: flag=%s notice=%r"
              % (rv["ok"]["methods"], rv["ok"]["flag"], rv["ok"]["notice"][:60], rv["fail"]["flag"], rv["fail"]["notice"][:60]))
        assert rv["ok"]["methods"] == ["wallet_revokePermissions"], rv
        assert rv["ok"]["flag"] == "1" and rv["fail"]["flag"] == "1", "the disconnect flag must be kept either way: %s" % rv
        assert "removed in your wallet" in rv["ok"]["notice"], rv
        assert "may still" in rv["fail"]["notice"] and "removed in your wallet" not in rv["fail"]["notice"], \
            "an unsupported revoke must not claim access was removed: %s" % rv
        assert rv["ok"]["account"] is None and rv["fail"]["account"] is None, rv

        # پاک کردن کیف پول ساختگی تا تست‌های بعدی حالت «بدون کیف پول» ببینند
        await pg.evaluate("""() => {
            account = null; signer = null; walletChainId = null;
            balances = {}; allowance = 0n; delete window.__STUB_ALLOWANCE__;
        }""")
        await pg.fill("#amtIn", "1000")
        await pg.wait_for_timeout(2500)

        # ---- 2b-ter. shareable quote link ----
        # وضعیت باید در URL برود و برگردد، بدون بک‌اند. و مهم‌تر: لینکی که
        # توکن ناشناس دارد نباید بی‌صدا روی پیش‌فرض بنشیند.
        url = await pg.evaluate("() => shareUrl()")
        print("[share] %s" % url.split("#")[-1])
        assert "in=USDC" in url and "out=WETH" in url and "amt=1000" in url, url

        applied = await pg.evaluate("""async () => {
            location.hash = "swap?in=WETH&out=USDC&amt=2";
            await applyShareParams();
            return {inSym: document.getElementById("tokInSym").innerText,
                    outSym: document.getElementById("tokOutSym").innerText,
                    amt: document.getElementById("amtIn").value};
        }""")
        print("[share] round trip -> %s -> %s  amt=%s" % (
            applied["inSym"], applied["outSym"], applied["amt"]))
        assert applied["inSym"] == "WETH" and applied["outSym"] == "USDC" and applied["amt"] == "2", applied

        bad = await pg.evaluate("""async () => {
            location.hash = "swap?in=USDC&out=0x000000000000000000000000000000000000dEaD&amt=5";
            await applyShareParams();
            return {outSym: document.getElementById("tokOutSym").innerText,
                    notice: document.getElementById("notices").innerText};
        }""")
        print("[share] hostile link -> out=%s | %s" % (bad["outSym"], bad["notice"].replace("\n", " ")[:90]))
        assert "could not be opened" in bad["notice"].lower(), \
            "a link with a token we cannot verify must say so, not fall back silently"

        # برگشت به حالت اول برای بقیه‌ی تست‌ها
        await pg.evaluate("""async () => {
            location.hash = "swap?in=USDC&out=WETH&amt=1000";
            await applyShareParams();
        }""")
        await pg.wait_for_timeout(2500)

        # ---- 2b-quater. exit-check result carried into the token picker ----
        # فقط چیزی که همین جلسه واقعاً بررسی شده نشان داده می‌شود؛ پیکر
        # هیچ بررسی تازه‌ای اجرا نمی‌کند.
        await pg.click("#tokOutBtn"); await pg.wait_for_timeout(300)
        badges = await pg.eval_on_selector_all(
            "#tokList .trow",
            "els => els.map(e => { const b = e.querySelector('.xb');"
            " return {sym: e.querySelector('.s').innerText, badge: b ? b.innerText : null,"
            "         tip: b ? b.title : null}; })")
        shown = [row for row in badges if row["badge"]]
        for row in shown:
            print("[picker] %-6s %-9s %s" % (row["sym"], row["badge"], row["tip"]))
        assert shown, "the token we just checked must carry its result into the picker"
        assert all("checked" in row["tip"] for row in shown), "a cached result must always show its age"
        unchecked = [row for row in badges if not row["badge"]]
        assert unchecked, "tokens we never checked must have no badge at all — absence means unknown, not safe"
        await pg.keyboard.press("Escape"); await pg.wait_for_timeout(250)

        # یک نتیجه‌ی منفی هم باید تا پیکر برسد
        await pg.evaluate("""() => {
            exitCache[balKey(tokenOut)] = {state: "blocked", lossPct: null, at: Date.now()};
        }""")
        await pg.click("#tokOutBtn"); await pg.wait_for_timeout(300)
        neg = await pg.eval_on_selector_all(
            "#tokList .trow .xb", "els => els.map(e => e.innerText)")
        print("[picker] after a blocked result: %s" % neg)
        assert any("no exit" in n for n in neg), "a blocked exit must be visible in the picker"
        await pg.keyboard.press("Escape"); await pg.wait_for_timeout(250)

        # ---- 2b-quinquies. findings from the line-by-line review ----
        # الف) نماد توکن نباید به‌عنوان markup اجرا شود. توکن مهاجم می‌تواند
        #      هر رشته‌ای را از symbol() برگرداند و لینک اشتراکی آن را انتخابی کند.
        xss = await pg.evaluate("""() => {
            const saved = tokenOut;
            tokenOut = Object.assign({}, tokenOut, {symbol: '<img src=x onerror=window.__PWNED__=1>'});
            renderVenues(lastDirect, currentPlan);
            const html = document.getElementById("venueBody").innerHTML;
            const imgs = document.querySelectorAll("#venueBody img").length;
            tokenOut = saved; renderVenues(lastDirect, currentPlan);
            return {pwned: !!window.__PWNED__, imgs, escaped: html.includes("&lt;img")};
        }""")
        print("[xss] injected symbol -> imgs=%s pwned=%s escaped=%s"
              % (xss["imgs"], xss["pwned"], xss["escaped"]))
        assert xss["imgs"] == 0 and not xss["pwned"], "token symbol reached the DOM as markup"

        # ب) hash بدشکل نباید راه‌اندازی را بیندازد
        broken = await pg.evaluate("""() => {
            const h = location.hash;
            location.hash = "%";
            let ok = true;
            try { parseHash(); } catch (e) { ok = false; }
            location.hash = h;
            return ok;
        }""")
        print("[hash] malformed '#%%' survived: %s" % broken)
        assert broken, "a malformed hash must not throw — it runs during init"

        # ج) کوت فروش که نیامده، هانی‌پات نیست
        verdict = await pg.evaluate("""async () => {
            const real = quoteMany;
            let call = 0;
            quoteMany = async (specs, stats) => {
                call++;
                if (call === 1) return real(specs, stats);          // خرید: سالم
                stats.attempted += specs.length;                     // فروش: شبکه نداد
                stats.rpcFailed += specs.length;
                return specs.map(() => ({out: null, status: "unknown"}));
            };
            const t = await checkTradability(tokenOut);
            quoteMany = real;
            return t;
        }""")
        print("[tradability] buy ok, sell silent -> %s" % verdict)
        assert verdict["unknown"], "a failed sell quote must be flagged unknown, not as a honeypot"

        # ---- باگ ۱۵: نبودِ کوتِ فروشِ این صفحه داور نهایی نیست — سرور
        # (/vd/<address>) با پوششِ وسیع‌تر (از جمله Uniswap v4) داور است.
        # هر چهار حالت: null (نامعلوم)، sell (نجات)، nosell (اتهامِ واقعی
        # بدونِ کلمه‌ی «هانی‌پات»)، و شاهدِ مثبت (کوتِ فروش خودِ صفحه که
        # اصلاً نباید سراغ سرور برود).
        r15_unknown = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: null, why: null});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            const withFalsePenalty = riskScore(Object.assign({}, rep, {canSell: false}));
            return {titles: rep.findings.map(f => f.title), canSell: rep.canSell,
                    score: rep.score, withFalsePenalty};
        }""")
        print("[risk 15] server verdict unknown -> titles=%s canSell=%s score=%s vs +40=%s"
              % (r15_unknown["titles"], r15_unknown["canSell"], r15_unknown["score"],
                 r15_unknown["withFalsePenalty"]))
        assert "Tradability unknown" in r15_unknown["titles"]
        assert "Cannot get a sell quote" not in r15_unknown["titles"]
        assert r15_unknown["canSell"] is None
        assert r15_unknown["score"] < r15_unknown["withFalsePenalty"], \
            "an unresolved server verdict must not carry the +40 unsellable penalty"

        r15_sell = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: "sell", why: null});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            return {findings: rep.findings.map(f => ({title: f.title, level: f.level})),
                    canSell: rep.canSell};
        }""")
        print("[risk 15] server verdict sell -> canSell=%s findings=%s"
              % (r15_sell["canSell"], r15_sell["findings"]))
        hit = next((x for x in r15_sell["findings"]
                    if x["title"] == "No sell quote from the pools we quote"), None)
        assert hit is not None, "a server-confirmed sell must be reported"
        assert hit["level"] == "info"
        assert r15_sell["canSell"] is True
        assert not any(x["title"] == "Cannot get a sell quote" for x in r15_sell["findings"]), \
            "a server-confirmed sell must not leave the tradability-critical finding behind"

        r15_nosell = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: "nosell", why: null});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            return {findings: rep.findings.map(f => ({title: f.title, level: f.level, detail: f.detail})),
                    canSell: rep.canSell};
        }""")
        print("[risk 15] server verdict nosell -> canSell=%s" % r15_nosell["canSell"])
        hit = next((x for x in r15_nosell["findings"] if x["title"] == "Cannot get a sell quote"), None)
        assert hit is not None, "a server-confirmed no-sell must still be reported critical"
        assert hit["level"] == "critical"
        assert "honeypot" not in hit["detail"].lower(), \
            "most nosell verdicts are pulled liquidity, not honeypot contracts — the word must not appear"
        assert r15_nosell["canSell"] is False

        r15_control = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            let vdCalls = 0;
            checkTradability = async () => ({buy: true, sell: true, roundTrip: 0.5, unknown: false});
            fetchVdVerdict = async () => { vdCalls++; return {v: "sell", why: null}; };
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            return {titles: rep.findings.map(f => f.title), vdCalls};
        }""")
        print("[risk 15] positive control, page itself sold -> titles=%s vdCalls=%s"
              % (r15_control["titles"], r15_control["vdCalls"]))
        assert r15_control["vdCalls"] == 0, \
            "the server verdict must not be consulted when this page's own quotes already sold"
        assert "Sellable" in r15_control["titles"]

        r15_rescue = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: false, sell: false, roundTrip: null, unknown: true});
            fetchVdVerdict = async () => ({v: "sell", why: null});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            return {canSell: rep.canSell, canBuy: rep.canBuy};
        }""")
        print("[risk 15] browser unknown, server sell -> canSell=%s canBuy=%s"
              % (r15_rescue["canSell"], r15_rescue["canBuy"]))
        assert r15_rescue["canSell"] is True, \
            "a server-confirmed sell must rescue a browser-side unknown"

        # ---- fix9: علتِ «empty-pool» رویِ یک nosellِ سروری — «استخر خالی است»
        # به‌جای جمله‌ی همیشگیِ چندپهلو، فقط وقتی سرور خودش cause را داده.
        r_cause_yes = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: "nosell", why: null, cause: "empty-pool"});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            const hit = rep.findings.find(f => f.title === "Cannot get a sell quote");
            return {detail: hit ? hit.detail : null};
        }""")
        print("[risk cause] server verdict nosell with empty-pool cause -> detail=%r" % r_cause_yes["detail"])
        assert r_cause_yes["detail"] is not None and "no liquidity left in the pool" in r_cause_yes["detail"], \
            "an empty-pool cause must produce the pool-specific wording, got %r" % r_cause_yes["detail"]

        r_cause_no = await pg.evaluate("""async () => {
            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: "nosell", why: null});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            const hit = rep.findings.find(f => f.title === "Cannot get a sell quote");
            return {detail: hit ? hit.detail : null};
        }""")
        print("[risk cause] server verdict nosell without cause -> detail=%r" % r_cause_no["detail"])
        assert r_cause_no["detail"] == (
            "No pool we quote would sell this back, and the server check found no way to sell it "
            "either. That can be a token that blocks selling or a pool whose liquidity was pulled "
            "— either way there is no exit right now."
        ), "without a cause, the detail must stay byte-for-byte today's wording, got %r" % r_cause_no["detail"]

        # fetchVdVerdict itself must reject any cause other than "empty-pool" —
        # a junk upstream value must never reach the panel as a claim.
        r_cause_junk = await pg.evaluate("""async () => {
            const realFetch = window.fetch;
            window.fetch = async () => new Response(JSON.stringify({v: "nosell", cause: "whatever"}),
                {status: 200});
            const direct = await fetchVdVerdict("0x" + "16".repeat(20));
            window.fetch = realFetch;

            const realCT = checkTradability, realVD = fetchVdVerdict, realML = measureLiquidity;
            checkTradability = async () => ({buy: true, sell: false, roundTrip: null, unknown: false});
            fetchVdVerdict = async () => ({v: "nosell", why: null, cause: "whatever"});
            measureLiquidity = async () => 200000;
            const rep = await scanToken(tokenOut);
            checkTradability = realCT; fetchVdVerdict = realVD; measureLiquidity = realML;
            const hit = rep.findings.find(f => f.title === "Cannot get a sell quote");
            return {directCause: direct.cause, detail: hit ? hit.detail : null};
        }""")
        print("[fetchVdVerdict cause] junk cause from upstream -> directCause=%s detail=%r"
              % (r_cause_junk["directCause"], r_cause_junk["detail"]))
        assert r_cause_junk["directCause"] is None, \
            "fetchVdVerdict must turn any non-\"empty-pool\" cause into null, got %r" % r_cause_junk["directCause"]
        assert r_cause_junk["detail"] == r_cause_no["detail"], \
            "a junk cause must fall back to the neutral panel wording, got %r" % r_cause_junk["detail"]

        # ---- باگ ۱۶: عددِ کمِ نقدینگی بدونِ شاهدِ پوشش اتهام نیست ----
        r16_false = await pg.evaluate("""async () => {
            const realML = measureLiquidity, realCov = liqCoverage, realCT = checkTradability;
            measureLiquidity = async () => 0;
            liqCoverage = async () => false;
            checkTradability = async () => ({buy: true, sell: true, roundTrip: 0, unknown: false});
            const rep = await scanToken(tokenOut);
            measureLiquidity = realML; liqCoverage = realCov; checkTradability = realCT;
            return {titles: rep.findings.map(f => f.title), liqUsd: rep.liqUsd, unknown: rep.unknown};
        }""")
        print("[liquidity 16] coverage false -> titles=%s liqUsd=%s unknown=%s"
              % (r16_false["titles"], r16_false["liqUsd"], r16_false["unknown"]))
        assert "Very thin liquidity" not in r16_false["titles"]
        assert "Liquidity not fully measured" in r16_false["titles"]
        assert r16_false["liqUsd"] is None
        assert r16_false["unknown"] == 0

        r16_null = await pg.evaluate("""async () => {
            const realML = measureLiquidity, realCov = liqCoverage, realCT = checkTradability;
            measureLiquidity = async () => 0;
            liqCoverage = async () => null;
            checkTradability = async () => ({buy: true, sell: true, roundTrip: 0, unknown: false});
            const rep = await scanToken(tokenOut);
            measureLiquidity = realML; liqCoverage = realCov; checkTradability = realCT;
            return {titles: rep.findings.map(f => f.title), liqUsd: rep.liqUsd, unknown: rep.unknown};
        }""")
        print("[liquidity 16] coverage null -> titles=%s liqUsd=%s unknown=%s"
              % (r16_null["titles"], r16_null["liqUsd"], r16_null["unknown"]))
        assert "Very thin liquidity" not in r16_null["titles"]
        assert "Liquidity not fully measured" in r16_null["titles"]
        assert r16_null["liqUsd"] is None
        assert r16_null["unknown"] >= 1, \
            "an unresolved coverage check must count toward the unknown total"

        r16_control = await pg.evaluate("""async () => {
            const realML = measureLiquidity, realCov = liqCoverage, realCT = checkTradability;
            let covCalls = 0;
            measureLiquidity = async () => 0;
            liqCoverage = async () => { covCalls++; return true; };
            checkTradability = async () => ({buy: true, sell: true, roundTrip: 0, unknown: false});
            const rep = await scanToken(tokenOut);
            measureLiquidity = realML; liqCoverage = realCov; checkTradability = realCT;
            return {titles: rep.findings.map(f => f.title), liqUsd: rep.liqUsd, covCalls};
        }""")
        print("[liquidity 16] positive control, coverage true -> titles=%s liqUsd=%s"
              % (r16_control["titles"], r16_control["liqUsd"]))
        assert "Very thin liquidity" in r16_control["titles"]
        assert r16_control["liqUsd"] == 0
        assert r16_control["covCalls"] == 1

        # ---- liqCoverage به‌تنهایی: شکل‌های واقعی و لبه‌ایِ GeckoTerminal ----
        our_addr = "0x4f795d79f9bcec1dc51083249dddb9ee4ccfe87e"
        usdc_addr = "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913"
        weth_addr = "0x4200000000000000000000000000000000000006"
        other_addr = "0x1234567890123456789012345678901234567890"

        def gt_pool(dex, base, quote):
            return {"relationships": {
                "base_token": {"data": {"id": "base_" + base}},
                "quote_token": {"data": {"id": "base_" + quote}},
                "dex": {"data": {"id": dex}},
            }}

        cov_cases = [
            ("real v4 payload", {"data": [gt_pool("uniswap-v4-base", our_addr, weth_addr)]}, False),
            ("v3 vs USDC", {"data": [gt_pool("uniswap-v3-base", our_addr, usdc_addr)]}, True),
            ("v3 vs other token", {"data": [gt_pool("uniswap-v3-base", our_addr, other_addr)]}, False),
            ("empty pools", {"data": []}, None),
            ("full page (20)", {"data": [gt_pool("uniswap-v3-base", our_addr, usdc_addr)
                                          for _ in range(20)]}, None),
            ("pool missing dex", {"data": [{"relationships": {
                "base_token": {"data": {"id": "base_" + our_addr}},
                "quote_token": {"data": {"id": "base_" + usdc_addr}}}}]}, None),
        ]
        for label, payload, expect in cov_cases:
            got = await pg.evaluate("""async (args) => {
                const real = gtJson;
                gtJson = async () => args.payload;
                const v = await liqCoverage({address: args.addr});
                gtJson = real;
                return v;
            }""", {"payload": payload, "addr": our_addr})
            print("[liqCoverage] %s -> %s" % (label, got))
            assert got == expect, "%s: expected %r, got %r" % (label, expect, got)

        thrown = await pg.evaluate("""async (addr) => {
            const real = gtJson;
            gtJson = async () => { throw new Error("boom"); };
            const v = await liqCoverage({address: addr});
            gtJson = real;
            return v;
        }""", our_addr)
        print("[liqCoverage] gtJson throws -> %s" % thrown)
        assert thrown is None

        # ---- نگهبانِ ایستا: GT_DEX_TO_DEX زیرمجموعه‌ی دقیقِ GT_DEX_TO_VENUE ----
        idx_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
        wk_src = open(os.path.join(HERE, "..", "..", "worker", "index.js"), encoding="utf-8").read()
        gd_m = re.search(r"const GT_DEX_TO_DEX=Object\.freeze\((.*?)\);", idx_src, re.S)
        assert gd_m, "web/index.html no longer declares GT_DEX_TO_DEX"
        gd_pairs = re.findall(r'"([^"]+)":"([^"]+)"', gd_m.group(1))
        assert gd_pairs, "GT_DEX_TO_DEX parsed empty"
        gv_m = re.search(r"GT_DEX_TO_VENUE = Object\.freeze\((.*?)\);", wk_src, re.S)
        assert gv_m, "worker/index.js no longer declares GT_DEX_TO_VENUE"
        gv_pairs = dict(re.findall(r'"([^"]+)":\s*"([^"]+)"', gv_m.group(1)))
        dexes_m = re.search(r"const DEXES=\[(.*?)\];", idx_src, re.S)
        assert dexes_m, "web/index.html no longer declares DEXES"
        dex_ids = set(re.findall(r'\{id:"([^"]+)"', dexes_m.group(1)))
        print("[static guard] GT_DEX_TO_DEX pairs=%d dex_ids=%s" % (len(gd_pairs), sorted(dex_ids)))
        # uniswap-v4-base: مسیرِ حکمِ Worker (VD_VENUES) برای v4 ایندکسِ کلیدِ خودش را دارد
        # (V4_GT_DEX_ID در v4index.js) و در GT_DEX_TO_VENUE نیست؛ ردیفِ v4 این صفحه از
        # آداپتر می‌آید. پس فقط همین یک نگاشت از برابریِ جدولِ Worker معاف است.
        wk_v4 = open(os.path.join(HERE, "..", "..", "worker", "v4index.js"), encoding="utf-8").read()
        assert re.search(r'V4_GT_DEX_ID = "uniswap-v4-base"', wk_v4), "worker's v4 GT dex id changed"
        gd_pairs = [(k, v) for k, v in gd_pairs if not (k == "uniswap-v4-base" and v == "uniswap-v4")]
        for k, v in gd_pairs:
            assert gv_pairs.get(k) == v, \
                "GT_DEX_TO_DEX[%r]=%r does not match worker's GT_DEX_TO_VENUE[%r]=%r" \
                % (k, v, k, gv_pairs.get(k))
            assert v in dex_ids, \
                "GT_DEX_TO_DEX maps %r to %r, which is not a DEXES id in web/index.html" % (k, v)
        # کامل‌بودن هم، نه فقط زیرمجموعه: هر نگاشتِ ورکر که صرافی‌اش در DEXES این صفحه هست باید
        # این‌جا هم باشد — وگرنه نقدینگیِ آن صرافی بی‌صدا «سنجیده‌نشده» حساب می‌شود (۲۶ سپتامبر).
        gd_keys = set(k for k, _ in gd_pairs)
        for k, v in gv_pairs.items():
            if v in dex_ids:
                assert k in gd_keys, \
                    "worker maps %r to %r, a DEXES id in web/index.html, but GT_DEX_TO_DEX lacks it" % (k, v)
        assert "Strongest honeypot signal" not in idx_src, \
            "the removed honeypot-signal wording must not reappear in web/index.html"

        # د) allowance خوانده‌نشده نباید «approve نکرده» تفسیر شود
        btn = await pg.evaluate("""() => {
            const savedAcc = account, savedPlan = currentPlan;
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id;
            balances[balKey(tokenIn)] = 10n ** 30n;
            allowance = 0n; allowanceKnown = false;      // یعنی: نخواندیم
            refreshButton();
            const label = document.getElementById("actBtn").textContent;
            account = savedAcc; walletChainId = null; balances = {}; currentPlan = savedPlan;
            refreshButton();
            return label;
        }""")
        print("[allowance] unread allowance -> button says %r" % btn)
        assert "Approve" not in btn, \
            "an unread allowance must not push the user into a needless approval"

        # ه) قیمت مرجع نامعلوم نباید «نقدینگی صفر» شود
        liq = await pg.evaluate("""async () => {
            const real = refPriceUsd, cached = _ethUsd;
            _ethUsd = null;
            refPriceUsd = async () => null;          // قیمت ETH خوانده نشد
            // توکنی که استخرهایش با WETH جفت شده‌اند — برای WETH خودش،
            // مرجع فقط USDC است و قیمت ETH اصلاً وارد محاسبه نمی‌شود.
            const t = BASE_TOKENS.find(x => x.symbol === "AERO");
            const v = await measureLiquidity(t);
            refPriceUsd = real; _ethUsd = cached;
            return v;
        }""")
        print("[liquidity] ETH price unknown -> %s" % liq)
        assert liq is None, \
            "an unknown ETH price must read as unknown, not as $0 of liquidity"

        # و) approve باید پیش‌فرض دقیق باشد، نه نامحدود
        appr = await pg.evaluate("""() => {
            let seen = null;
            const real = E.Contract;
            E.Contract = function () {
                return {approve: async (spender, amt) => {
                    seen = amt.toString();
                    return {hash: "0x" + "11".repeat(32), wait: async () => ({status: 1})};
                }};
            };
            const want = parsedAmountIn();
            const exact = (typeof unlimitedApprove !== "undefined") && !unlimitedApprove;
            E.Contract = real;
            return {exact, want: want.toString(), max: E.MaxUint256.toString()};
        }""")
        print("[approve] exact-by-default=%s" % appr["exact"])
        assert appr["exact"], "unlimited approval must not be the default"

        # ز) «مسیری نیست» فقط وقتی همه جواب داده باشند قطعی گفته شود
        note_txt = await pg.evaluate("""() => {
            const el = document.createElement("div");
            el.innerHTML = noRouteNote({attempted: 18, ok: 14, noPool: 0, rpcFailed: 4}, "detail here");
            return el.innerText;
        }""")
        print("[no route] partial data -> %s" % note_txt.replace("\n", " ")[:100])
        assert "not a complete picture" in note_txt, \
            "with venues that did not answer we cannot claim there is no route"

        clean = await pg.evaluate("""() => {
            const el = document.createElement("div");
            el.innerHTML = noRouteNote({attempted: 18, ok: 18, noPool: 18, rpcFailed: 0}, "detail here");
            return el.innerText;
        }""")
        assert "not a complete picture" not in clean, \
            "with full data the plain 'No route' wording should stand"

        # ح) ETH ↔ WETH باید wrap/unwrap بدهد، نه بن‌بست
        wrapui = await pg.evaluate("""async () => {
            const savedIn = tokenIn, savedOut = tokenOut, savedAcc = account, savedChain = walletChainId;
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id;
            tokenIn  = BASE_TOKENS.find(t => t.symbol === "ETH");
            tokenOut = BASE_TOKENS.find(t => t.symbol === "WETH");
            balances[balKey(tokenIn)] = 10n ** 20n;
            document.getElementById("amtIn").value = "1";
            const dir = wrapDirection();
            refreshButton();
            const label = document.getElementById("actBtn").textContent;
            const disabled = document.getElementById("actBtn").disabled;
            tokenIn = savedIn; tokenOut = savedOut; account = savedAcc;
            walletChainId = savedChain; balances = {}; refreshButton();
            return {dir, label, disabled};
        }""")
        print("[wrap] ETH -> WETH  dir=%s  button=%r disabled=%s"
              % (wrapui["dir"], wrapui["label"], wrapui["disabled"]))
        assert wrapui["dir"] == "wrap", "ETH -> WETH must be recognised as a wrap"
        assert "Wrap" in wrapui["label"] and not wrapui["disabled"], \
            "the app must offer a working wrap, not point at a button that does not exist"

        # ط) قطع اتصال باید وضعیت را واقعاً پاک کند
        dis = await pg.evaluate("""() => {
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id; balances["native"] = 5n; allowanceKnown = true;
            disconnect();
            return {account, allowanceKnown, balances: Object.keys(balances).length,
                    button: document.getElementById("connectBtn").textContent};
        }""")
        print("[disconnect] account=%s balances=%s button=%r"
              % (dis["account"], dis["balances"], dis["button"]))
        assert dis["account"] is None and dis["balances"] == 0 and not dis["allowanceKnown"], \
            "disconnect must clear wallet state, not just the label"
        assert dis["button"] == "Connect wallet"

        # ی) «نمی‌دانم» نباید در امتیاز ریسک جریمه شود
        risk = await pg.evaluate("""() => {
            const base = {findings: [], owner: null, isProxy: false, liqUsd: 100000,
                          canBuy: null, canSell: null, unknown: 1};
            const unknownScore = riskScore(Object.assign({}, base));
            const knownBad = riskScore(Object.assign({}, base, {canSell: false}));
            const knownGood = riskScore(Object.assign({}, base, {canSell: true}));
            return {unknownScore, knownBad, knownGood};
        }""")
        print("[risk] unknown=%s  known-unsellable=%s  known-sellable=%s"
              % (risk["unknownScore"], risk["knownBad"], risk["knownGood"]))
        assert risk["unknownScore"] == risk["knownGood"], \
            "an unknown sell test must not be scored as if the token failed it"
        assert risk["knownBad"] > risk["unknownScore"], \
            "a token we know cannot be sold must still be penalised"

        # بررسی‌های آشتی: یک شبیه‌سازیِ واقعاً اجراشده باید بر یک کوت غالب شود،
        # و پنل ایمنی نباید چیزی خلاف پنل خروج بگوید (باگ ۹).

        # ۱) blocked باید یک "Sellable" مبتنی بر کوت را بی‌اثر کند
        rev = await pg.evaluate("""() => {
            const addr = "0x1111111111111111111111111111111111111111";
            const rep = {address: addr, symbol: "TST", native: false,
                findings: [
                    {level: "ok", title: "Sellable", detail: "Round-trip cost about 0.00%."},
                    {level: "ok", title: "Liquidity present", detail: "About $120,000 across known pools."}
                ],
                owner: null, isProxy: false, liqUsd: 120000,
                canBuy: true, canSell: true, unknown: 0};
            rep.score = riskScore(rep); rep.verdict = verdictOf(rep);
            const beforeScore = rep.score;
            exitCache[addr] = {state: "blocked", lossPct: null, at: Date.now()};
            const after = reconcileExit(rep);
            delete exitCache[addr];
            return {
                afterTitles: after.findings.map(f => f.title),
                afterLevels: after.findings.map(f => f.level),
                afterScore: after.score,
                afterCanSell: after.canSell,
                afterVerdict: after.verdict.txt,
                beforeScore,
                rawTitles: rep.findings.map(f => f.title)
            };
        }""")
        print("[risk] live sell revert overrides the quote: before=%s after=%s titles=%s"
              % (rev["beforeScore"], rev["afterScore"], rev["afterTitles"]))
        assert "Sellable" not in rev["afterTitles"], \
            "a live revert must remove the quote-based Sellable finding"
        assert "Sell simulation reverted" in rev["afterTitles"], \
            "a live revert must add its own finding"
        idx = rev["afterTitles"].index("Sell simulation reverted")
        assert rev["afterLevels"][idx] == "critical", \
            "a proven revert must be reported as critical, not softened"
        assert rev["afterScore"] > rev["beforeScore"], \
            "overriding to a proven revert must raise the score, not lower it"
        assert rev["afterCanSell"] is False, \
            "a proven revert must mark canSell false"
        assert "Sellable" in rev["rawTitles"], \
            "the cached report object must not be mutated in place"

        # ۲) verified باید یک "Cannot get a sell quote" بدبینانه را نجات دهد
        ver = await pg.evaluate("""() => {
            const addr = "0x2222222222222222222222222222222222222222";
            const rep = {address: addr, symbol: "TST2", native: false,
                findings: [
                    {level: "critical", title: "Cannot get a sell quote",
                     detail: "No pool would quote selling this token back."}
                ],
                owner: null, isProxy: false, liqUsd: 120000,
                canBuy: true, canSell: false, unknown: 0};
            rep.score = riskScore(rep); rep.verdict = verdictOf(rep);
            const beforeScore = rep.score;
            exitCache[addr] = {state: "verified", lossPct: 0.4, at: Date.now()};
            const after = reconcileExit(rep);
            delete exitCache[addr];
            return {
                afterTitles: after.findings.map(f => f.title),
                afterLevels: after.findings.map(f => f.level),
                afterScore: after.score,
                afterCanSell: after.canSell,
                beforeScore
            };
        }""")
        print("[risk] a verified round trip clears the quote-only honeypot flag: before=%s after=%s"
              % (ver["beforeScore"], ver["afterScore"]))
        assert "Cannot get a sell quote" not in ver["afterTitles"], \
            "a verified live sell must clear the pessimistic quote-only finding"
        assert "No sell quote from the reference pool" in ver["afterTitles"], \
            "a verified live sell must explain why the quote was pessimistic"
        idx = ver["afterTitles"].index("No sell quote from the reference pool")
        assert ver["afterLevels"][idx] == "info", \
            "a resolved false alarm must be informational, not scary"
        assert ver["afterCanSell"] is True, \
            "a verified live sell must mark canSell true"
        assert ver["afterScore"] < ver["beforeScore"], \
            "clearing a false honeypot flag must lower the score"

        # ۳) unknown/estimated/غایب چیزی را عوض نمی‌کنند و همان شیء برمی‌گردد
        untouched = await pg.evaluate("""() => {
            const addr = "0x3333333333333333333333333333333333333333";
            const mk = () => ({address: addr, symbol: "TST3", native: false,
                findings: [{level: "ok", title: "Sellable", detail: "x"}],
                owner: null, isProxy: false, liqUsd: 50000,
                canBuy: true, canSell: true, unknown: 0});
            const repU = mk();
            exitCache[addr] = {state: "unknown", lossPct: null, at: Date.now()};
            const sameU = reconcileExit(repU) === repU;

            const repE = mk();
            exitCache[addr] = {state: "estimated", lossPct: 1.2, at: Date.now()};
            const sameE = reconcileExit(repE) === repE;

            delete exitCache[addr];
            const repA = mk();
            const sameA = reconcileExit(repA) === repA;
            return {sameU, sameE, sameA};
        }""")
        print("[risk] an untested or estimated exit does not touch the report: unknown=%s estimated=%s absent=%s"
              % (untouched["sameU"], untouched["sameE"], untouched["sameA"]))
        assert untouched["sameU"] and untouched["sameE"] and untouched["sameA"], \
            "an unknown/estimated/absent exit result must return the very same report object"

        # ۴) پنل ایمنی روی صفحه واقعاً همان چیزی را نشان دهد که پنل خروج می‌گوید
        has_safety_body = await pg.evaluate("() => !!document.getElementById('safetyBody')")
        assert has_safety_body, \
            "the harness page has no #safetyBody element — cannot verify the rendered panel"
        dom = await pg.evaluate("""() => {
            const t = BASE_TOKENS.find(x => x.symbol === "cbBTC" && !x.native);
            const addr = t.address.toLowerCase();
            const savedRep = safetyCache[addr];
            const savedExit = exitCache[addr];
            const savedPage = tokenPage;
            tokenPage = false;
            safetyCache[addr] = {address: t.address, symbol: t.symbol, native: false,
                findings: [
                    {level: "ok", title: "Sellable", detail: "Round-trip cost about 0.00%."},
                    {level: "ok", title: "Liquidity present", detail: "About $200,000 across known pools."}
                ],
                owner: null, isProxy: false, liqUsd: 200000,
                canBuy: true, canSell: true, unknown: 0};
            safetyCache[addr].score = riskScore(safetyCache[addr]);
            safetyCache[addr].verdict = verdictOf(safetyCache[addr]);
            exitCache[addr] = {state: "blocked", lossPct: null, at: Date.now()};
            renderSafety(safetyCache[addr]);
            const text = document.getElementById("safetyBody").innerText;
            if (savedRep === undefined) delete safetyCache[addr]; else safetyCache[addr] = savedRep;
            if (savedExit === undefined) delete exitCache[addr]; else exitCache[addr] = savedExit;
            tokenPage = savedPage;
            if (safetyCache[addr]) renderSafety(safetyCache[addr]);
            else document.getElementById("safetyBody").innerHTML =
                '<div class="empty">Pick a token to scan its contract.</div>';
            return text;
        }""")
        print("[risk] the safety panel agrees with the live sell test: %r" % dom)
        assert "Sell simulation reverted" in dom, \
            "the rendered safety panel did not pick up the live sell revert"
        assert "Sellable" not in dom, \
            "the rendered safety panel still shows the contradicted quote-based verdict"

        # ------------------------------------------------------------
        # باگ ۱۲: «هزینه‌ی رفت‌وبرگشت −۰.۱۱٪» — یک عدد منفی هرگز نباید
        # به‌عنوان سود چاپ شود. یک تابع، چهار محل مصرف.
        # ------------------------------------------------------------

        # ۱) خودِ تابع خالص — جدول‌محور
        trip_cases = [-5, -1, -0.11, -0.004, 0, 0.004, 0.005, 0.10, 51.54, None]
        trip_results = await pg.evaluate(
            "(vals) => vals.map(v => tripCost(v))", trip_cases)
        for v, r in zip(trip_cases, trip_results):
            if v in (-5, -1):
                assert r["state"] == "implausible", \
                    "a large apparent gain must read as unpriceable, not a real discount: %r -> %r" % (v, r)
            elif v in (-0.11, -0.004, 0, 0.004):
                assert r["state"] == "zeroish" and r["text"] == "about 0%", \
                    "a small negative/zero cost must smooth to 'about 0%%': %r -> %r" % (v, r)
            elif v in (0.005, 0.10, 51.54):
                assert r["state"] == "normal" and r["text"].endswith("%") and not r["text"].startswith("-"), \
                    "a genuine cost must print plainly: %r -> %r" % (v, r)
            elif v is None:
                assert r["state"] == "unknown", "a non-finite loss must read as unknown: %r -> %r" % (v, r)
        assert all(not re.search(r"-\d", r["text"]) for r in trip_results), \
            "a negative cost leaked into the rendered text: %s" % trip_results
        print("[trip] no negative cost is ever printed: %s" % trip_results)

        # ۲) کارت سواپ (renderExit)
        swap_probe = await pg.evaluate("""() => {
            const box = document.getElementById("exitBox");
            const savedHTML = box.innerHTML;
            const savedTokenPage = tokenPage;
            tokenPage = false;
            const mk = loss => ({state: "estimated", lossPct: loss, recovered: null, reason: null});
            renderExit(mk(-0.11));
            const t1 = box.innerText;
            renderExit(mk(-5));
            const t2 = box.innerText;
            renderExit(mk(0.10));
            const t3 = box.innerText;
            box.innerHTML = savedHTML;
            tokenPage = savedTokenPage;
            return {t1, t2, t3};
        }""")
        print("[trip] swap card: %r | %r | %r" % (
            swap_probe["t1"][:40], swap_probe["t2"][:40], swap_probe["t3"][:40]))
        assert "about 0%" in swap_probe["t1"] and "-0.11" not in swap_probe["t1"], \
            "swap card: a -0.11%% round trip must read as ~0%%, not a printed negative"
        assert "could not price" in swap_probe["t2"].lower() and "-5" not in swap_probe["t2"], \
            "swap card: a -5%% apparent gain must read as unpriceable, not a printed negative"
        assert "0.10%" in swap_probe["t3"], \
            "swap card: a genuine 0.10%% cost must still be printed plainly"

        # ۳) صفحه‌ی توکن (renderRoundTrip)
        token_probe = await pg.evaluate("""() => {
            const box = document.getElementById("tk-exitBox");
            const savedHTML = box.innerHTML;
            const mk = loss => ({state: "estimated", lossPct: loss, recovered: null});
            renderRoundTrip(box, mk(-0.11));
            const t1 = box.innerText;
            renderRoundTrip(box, mk(-5));
            const t2 = box.innerText;
            renderRoundTrip(box, mk(0.10));
            const t3 = box.innerText;
            box.innerHTML = savedHTML;
            return {t1, t2, t3};
        }""")
        print("[trip] token page: %r | %r | %r" % (
            token_probe["t1"][:40], token_probe["t2"][:40], token_probe["t3"][:40]))
        assert "about 0%" in token_probe["t1"] and "-0.11" not in token_probe["t1"], \
            "token page: a -0.11%% round trip must read as ~0%%, not a printed negative"
        assert "not priced" in token_probe["t2"].lower() and "-5" not in token_probe["t2"], \
            "token page: a -5%% apparent gain must read as unpriced, not a printed negative"
        assert "0.10%" in token_probe["t3"], \
            "token page: a genuine 0.10%% cost must still be printed plainly"

        # ۴) نشان ردیف در انتخابگر توکن (exitBadge)
        badge_probe = await pg.evaluate("""() => {
            const t = BASE_TOKENS.find(x => x.symbol === "cbBTC" && !x.native);
            const key = balKey(t);
            const saved = exitCache[key];
            exitCache[key] = {state: "verified", lossPct: -3, at: Date.now()};
            const html = exitBadge(t);
            if (saved === undefined) delete exitCache[key]; else exitCache[key] = saved;
            return html;
        }""")
        print("[trip] picker badge on an implausible gain: %r" % badge_probe)
        assert "✓" not in badge_probe and "-3" not in badge_probe and "unclear" in badge_probe, \
            "picker badge: an implausible 'gain' must not wear a checkmark or a printed negative"

        # ------------------------------------------------------------
        # باگ ۱۳: نوارِ رفت‌وبرگشتِ صفحه‌ی توکن هرگز از اسکلت خارج نمی‌شد.
        # هر خروجیِ زودهنگامِ runQuote (بدون route، ورودیِ نامعتبر، همان
        # توکن دو طرف، جهتِ wrap، catch) و نگهبانِ زمانی، باید نوار را
        # ببندند — یا با تأییدِ سرور (/vd) یا با «نامعلوم». تأییدِ سرور یک
        # کوت است نه شبیه‌سازی، پس هرگز نباید exitCache را لمس کند.
        # ------------------------------------------------------------
        EXIT13_SETTLE_PROBE = """async (verdict) => {
            const saved = {
                tokenPage, tokenIn, tokenOut, findRoutes, fetchVdVerdict,
                amtIn: document.getElementById("amtIn").value,
                boxHTML: document.getElementById("tk-exitBox").innerHTML
            };
            const addr = "0x" + "13".repeat(20);
            const key = addr.toLowerCase();
            const cacheKeysBefore = Object.keys(exitCache).length;
            tokenPage = true;
            tokenIn = BASE_TOKENS.find(t => t.symbol === "USDC");
            tokenOut = {address: addr, symbol: "T13", decimals: 18, native: false, name: "T13"};
            document.getElementById("amtIn").value = "100";
            findRoutes = async () => ({routes: [], direct: []});
            fetchVdVerdict = async () => verdict;
            // شبیه‌سازیِ یک چرخه‌ی تازه، بدون گذاشتنِ یک qTimer زنده که بعداً
            // با مقادیرِ بازگردانده‌شده شلیک کند.
            tkExitSeq++;
            await runQuote();
            // tokenExitFallback عمداً منتظرش نمی‌مانند (fire-and-forget)؛ یک
            // نوبت به حلقه‌ی رویداد می‌دهیم تا awaitِ داخلی‌اش تمام شود.
            await new Promise(r => setTimeout(r, 30));
            const box = document.getElementById("tk-exitBox");
            const badgeEl = box.querySelector(".tripBadge");
            const result = {
                skCount: box.querySelectorAll(".sk").length,
                text: box.innerText,
                badge: badgeEl ? badgeEl.innerText : null,
                cacheGrew: Object.keys(exitCache).length !== cacheKeysBefore,
                cacheHasKey: key in exitCache
            };
            findRoutes = saved.findRoutes; fetchVdVerdict = saved.fetchVdVerdict;
            tokenPage = saved.tokenPage; tokenIn = saved.tokenIn; tokenOut = saved.tokenOut;
            document.getElementById("amtIn").value = saved.amtIn;
            box.innerHTML = saved.boxHTML;
            clearTimeout(tkExitTimer); tkExitTimer = null;
            delete exitCache[key];
            return result;
        }"""

        r13_noroute = await pg.evaluate(EXIT13_SETTLE_PROBE, {"v": None, "why": None})
        print("[exit 13] no-route, server verdict unknown -> sk=%d badge=%r"
              % (r13_noroute["skCount"], r13_noroute["badge"]))
        assert r13_noroute["skCount"] == 0, \
            "the round-trip bar is still a loading skeleton after the quote settled with no route"
        assert "did not answer either" in r13_noroute["text"], \
            "the no-route fallback must show the noroute reason text"
        assert not r13_noroute["cacheGrew"] and not r13_noroute["cacheHasKey"], \
            "a server verdict must never write to exitCache"

        r13_sell = await pg.evaluate(EXIT13_SETTLE_PROBE, {"v": "sell", "why": None})
        print("[exit 13] no-route, server verdict sell -> sk=%d badge=%r"
              % (r13_sell["skCount"], r13_sell["badge"]))
        assert r13_sell["skCount"] == 0, \
            "the round-trip bar is still a loading skeleton after a rescuing server verdict"
        assert "Sellable" in r13_sell["text"] and r13_sell["badge"] == "Server check", \
            "a server-confirmed sell must render the Sellable/Server check state: %r" % r13_sell["text"]
        assert "not a simulation" in r13_sell["text"], \
            "the server-sell note must be honest that it is a quote, not a simulation"
        assert not r13_sell["cacheGrew"] and not r13_sell["cacheHasKey"], \
            "a server verdict must never write to exitCache, even a rescuing one"

        r13_nosell = await pg.evaluate(EXIT13_SETTLE_PROBE, {"v": "nosell", "why": None})
        print("[exit 13] no-route, server verdict nosell -> sk=%d badge=%r"
              % (r13_nosell["skCount"], r13_nosell["badge"]))
        assert r13_nosell["skCount"] == 0, \
            "the round-trip bar is still a loading skeleton after a nosell server verdict"
        assert "No way out" in r13_nosell["text"] and r13_nosell["badge"] == "Server check", \
            "a server-confirmed no-sell must render the No way out/Server check state: %r" % r13_nosell["text"]
        assert not r13_nosell["cacheGrew"] and not r13_nosell["cacheHasKey"], \
            "a server verdict must never write to exitCache"

        # ---- fix9: علتِ «empty-pool» رویِ نوارِ رفت‌وبرگشت (tokenExitFallback) ----
        r_exit_cause_yes = await pg.evaluate(EXIT13_SETTLE_PROBE,
                                              {"v": "nosell", "why": None, "cause": "empty-pool"})
        print("[exit cause] no-route, server verdict nosell + empty-pool -> text=%r"
              % r_exit_cause_yes["text"])
        assert "no liquidity left in it" in r_exit_cause_yes["text"], \
            "an empty-pool cause must show the pool-specific note, got %r" % r_exit_cause_yes["text"]
        assert not r_exit_cause_yes["cacheGrew"] and not r_exit_cause_yes["cacheHasKey"], \
            "a server verdict must never write to exitCache, even with a cause"

        r_exit_cause_no = await pg.evaluate(EXIT13_SETTLE_PROBE, {"v": "nosell", "why": None})
        print("[exit cause] no-route, server verdict nosell without cause -> text=%r"
              % r_exit_cause_no["text"])
        assert "found no way to sell it back either" in r_exit_cause_no["text"], \
            "without a cause, the note must stay byte-for-byte today's wording, got %r" % r_exit_cause_no["text"]
        assert not r_exit_cause_no["cacheGrew"] and not r_exit_cause_no["cacheHasKey"], \
            "a server verdict must never write to exitCache"

        # نگهبانِ زمانی: وقتی هیچ‌کدام از مسیرهای بالا نرسند (route هرگز جواب
        # نمی‌دهد)، یک تایمر باید همین حالا برپا باشد — فقط روی صفحه‌ی توکن.
        r13_watchdog = await pg.evaluate("""async () => {
            const saved = {
                tokenPage, tokenIn, tokenOut, findRoutes, fetchVdVerdict, qTimer,
                amtIn: document.getElementById("amtIn").value,
                boxHTML: document.getElementById("tk-exitBox").innerHTML
            };
            const addr = "0x" + "14".repeat(20);
            tokenIn = BASE_TOKENS.find(t => t.symbol === "USDC");
            tokenOut = {address: addr, symbol: "T14", decimals: 18, native: false, name: "T14"};
            document.getElementById("amtIn").value = "100";
            findRoutes = () => new Promise(() => {});    // هرگز حل نمی‌شود
            fetchVdVerdict = async () => ({v: "sell", why: null});

            tokenPage = true;
            scheduleQuote();
            const timerOnToken = tkExitTimer !== null;

            tokenPage = false;
            scheduleQuote();
            const timerOnSwap = tkExitTimer === null;

            // این قسمت جدا است: می‌سنجد که چه‌وقتی سرور هم چیزی نمی‌گوید
            // (v:null)، خودِ متنِ دلیلِ «timeout» رسم می‌شود — نه اینکه
            // تأییدِ «sell» بالاتر (که فقط برای برپا بودنِ تایمر لازم بود)
            // این رسم را رنگ بزند.
            fetchVdVerdict = async () => ({v: null, why: null});
            tokenPage = true;
            await tokenExitFallback(tkExitSeq, "timeout");
            const box = document.getElementById("tk-exitBox");
            const text = box.innerText;
            const badgeEl = box.querySelector(".tripBadge");

            clearTimeout(qTimer); clearTimeout(tkExitTimer);
            findRoutes = saved.findRoutes; fetchVdVerdict = saved.fetchVdVerdict; qTimer = saved.qTimer;
            tokenPage = saved.tokenPage; tokenIn = saved.tokenIn; tokenOut = saved.tokenOut;
            document.getElementById("amtIn").value = saved.amtIn;
            box.innerHTML = saved.boxHTML;
            tkExitTimer = null;

            return {timerOnToken, timerOnSwap, text, badge: badgeEl ? badgeEl.innerText : null};
        }""")
        print("[exit 13] watchdog: set on token page=%s, absent on swap page=%s, timeout text=%r"
              % (r13_watchdog["timerOnToken"], r13_watchdog["timerOnSwap"], r13_watchdog["text"][:70]))
        assert r13_watchdog["timerOnToken"], \
            "scheduleQuote must arm the 18s watchdog on the token page"
        assert r13_watchdog["timerOnSwap"], \
            "scheduleQuote must NOT arm a watchdog on the swap page — #exitBox has no such bar"
        assert "did not come back in time" in r13_watchdog["text"], \
            "a direct tokenExitFallback(...,'timeout') call must settle the bar with the timeout reason"
        assert r13_watchdog["badge"] == "Unknown", \
            "a timed-out fallback with no server verdict renders the plain Unknown state, not a Server-check badge: %r" \
            % r13_watchdog["badge"]

        # کهنگی: یک seq قدیمی هرگز نباید چیزی رسم کند.
        r13_stale = await pg.evaluate("""async () => {
            const saved = {
                tokenPage, tokenOut,
                boxHTML: document.getElementById("tk-exitBox").innerHTML
            };
            tokenPage = true;
            tokenOut = {address: "0x" + "15".repeat(20), symbol: "T15", decimals: 18, native: false, name: "T15"};
            const box = document.getElementById("tk-exitBox");
            renderRoundTrip(box, {state: "unknown", reason: "BASELINE_MARKER_13"});
            const before = box.innerHTML;
            await tokenExitFallback(tkExitSeq - 1, "noroute");
            const after = box.innerHTML;
            tokenPage = saved.tokenPage; tokenOut = saved.tokenOut;
            box.innerHTML = saved.boxHTML;
            return {before, after};
        }""")
        print("[exit 13] a stale sequence does not paint: unchanged=%s"
              % (r13_stale["before"] == r13_stale["after"]))
        assert r13_stale["before"] == r13_stale["after"], \
            "tokenExitFallback(seq-1, ...) painted over the bar — the staleness guard did not hold"

        # شاهدِ مثبت: یک نتیجه‌ی واقعی، دقیقاً مثل امروز رسم می‌شود و
        # نگهبانِ زمانی را هم می‌بندد.
        r13_control = await pg.evaluate("""() => {
            const saved = {
                tokenPage, tokenIn, tokenOut, findRoutes, qTimer,
                amtIn: document.getElementById("amtIn").value,
                swapHTML: document.getElementById("exitBox").innerHTML,
                tokHTML: document.getElementById("tk-exitBox").innerHTML
            };
            tokenIn = BASE_TOKENS.find(t => t.symbol === "USDC");
            const x = {state: "verified", lossPct: 0.12, recovered: null, reason: null};

            tokenPage = false;
            renderExit(x);
            const swapBadge = document.querySelector("#exitBox .exitBadge").innerText;
            const swapTitle = document.querySelector("#exitBox .exitTtl").innerText;

            tokenPage = true;
            tokenOut = BASE_TOKENS.find(t => t.symbol === "cbBTC" && !t.native);
            document.getElementById("amtIn").value = "100";
            findRoutes = () => new Promise(() => {});
            scheduleQuote();
            const timerBefore = tkExitTimer !== null;
            renderExit(x);
            const timerAfter = tkExitTimer === null;
            const tokBadge = document.querySelector("#tk-exitBox .tripBadge").innerText;
            const tokPct = document.querySelector("#tk-exitBox .tripPct").innerText;

            clearTimeout(qTimer); clearTimeout(tkExitTimer);
            findRoutes = saved.findRoutes; qTimer = saved.qTimer;
            tokenPage = saved.tokenPage; tokenIn = saved.tokenIn; tokenOut = saved.tokenOut;
            document.getElementById("amtIn").value = saved.amtIn;
            document.getElementById("exitBox").innerHTML = saved.swapHTML;
            document.getElementById("tk-exitBox").innerHTML = saved.tokHTML;
            tkExitTimer = null;

            return {swapBadge, swapTitle, timerBefore, timerAfter, tokBadge, tokPct};
        }""")
        print("[exit 13] positive control: swap=%r/%r token=%r/%r watchdog cleared=%s"
              % (r13_control["swapTitle"], r13_control["swapBadge"],
                 r13_control["tokPct"], r13_control["tokBadge"], r13_control["timerAfter"]))
        # ⚠️ .exitBadge/.tripBadge هر دو text-transform:uppercase دارند، و
        # نودِ صفحه‌ی توکن اینجا در نمای مخفی رندر می‌شود (نه در view فعال)،
        # پس هم بزرگ/کوچکیِ حروف و هم فاصله‌های سفیدِ بین خطوطِ template
        # literal را باید نادیده گرفت — دقیقاً کاری که کاوشگرهای دیگرِ همین
        # فایل با exitBadge می‌کنند (ن.ک. خط ۲۴۵۰).
        swap_badge_n = r13_control["swapBadge"].strip().lower()
        tok_badge_n = " ".join(r13_control["tokBadge"].split()).lower()
        assert swap_badge_n == "verified by simulation" and "0.12%" in r13_control["swapTitle"], \
            "a verified quote must still render exactly as before on the swap card: %r/%r" \
            % (r13_control["swapBadge"], r13_control["swapTitle"])
        assert tok_badge_n == "ran on chain" and r13_control["tokPct"] == "0.12%", \
            "a verified quote must still render exactly as before on the token page bar: %r/%r" \
            % (r13_control["tokBadge"], r13_control["tokPct"])
        assert r13_control["timerBefore"], "scheduleQuote must have armed the watchdog before renderExit ran"
        assert r13_control["timerAfter"], \
            "a real renderExit(...) result must settle (clear) the watchdog timer"

        # ۵) یافته‌ی پنل ایمنی باید با تست فروش زنده آشتی شود (رگرسیون باگ ۹)
        recon_probe = await pg.evaluate("""() => {
            const addr = "0x4444444444444444444444444444444444444444";
            const rep = {address: addr, symbol: "TST4", native: false,
                findings: [
                    {level: "info", title: "Round trip did not price cleanly",
                     detail: "Selling it straight back quoted more than the buy cost."}
                ],
                owner: null, isProxy: false, liqUsd: 80000,
                canBuy: true, canSell: null, unknown: 0};
            rep.score = riskScore(rep); rep.verdict = verdictOf(rep);
            exitCache[addr] = {state: "blocked", lossPct: null, at: Date.now()};
            const after = reconcileExit(rep);
            delete exitCache[addr];
            return { afterTitles: after.findings.map(f => f.title) };
        }""")
        print("[trip] the new finding is reconciled with the live sell test: %s"
              % recon_probe["afterTitles"])
        assert "Round trip did not price cleanly" not in recon_probe["afterTitles"], \
            "QUOTE_SELL_TITLES must cover the new title so a live revert replaces it, not sits beside it"
        assert "Sell simulation reverted" in recon_probe["afterTitles"], \
            "the live revert override must still be applied"

        # ک) دکمه‌ی گزارش مشکل باید به ایمیل واقعی برود
        mail = await pg.evaluate("() => LINKS.email")
        print("[contact] %s" % mail)
        assert "@" in mail and "example" not in mail, "contact address must be real"

        # ل) ارسالی که هرگز برنمی‌گردد نباید دکمه را تا ابد بچرخاند
        stuck = await pg.evaluate("""async () => {
            // promiseای که هیچ‌وقت resolve نمی‌شود = دقیقاً همان چیزی که
            // روی سایت واقعی اتفاق افتاد: تراکنش رفت، جواب نیامد.
            const never = new Promise(() => {});
            const t0 = Date.now();
            const r = await sendOrLoseTrack(never, 300);
            return {result: r, ms: Date.now() - t0};
        }""")
        print("[stuck send] returned %s after %sms" % (stuck["result"], stuck["ms"]))
        assert stuck["result"] is None and stuck["ms"] < 3000, \
            "a send that never answers must time out, not spin forever"

        # و شکست واقعی نباید با «نمی‌دانم» قاطی شود
        real = await pg.evaluate("""async () => {
            try {
                await sendOrLoseTrack(Promise.reject(new Error("user rejected")), 5000);
                return "no throw";
            } catch (e) { return e.message; }
        }""")
        print("[stuck send] a real rejection still throws: %r" % real)
        assert real == "user rejected", \
            "a genuine failure must propagate, not be swallowed as unknown"

        # م) خطای HTTP از RPC نباید «قرارداد رد کرد» خوانده شود
        #    ethers برای 403/429 هم CALL_EXCEPTION می‌گذارد و پیامش
        #    «missing revert data» است — عیناً شبیه یک revert واقعی.
        transport = await pg.evaluate("""() => {
            const blocked = Object.assign(new Error("missing revert data"),
                {code: "CALL_EXCEPTION", data: "Request failed with status code 403"});
            const real = Object.assign(new Error('execution reverted: "Blacklisted"'),
                {code: "CALL_EXCEPTION"});
            return {
                blockedIsRevert: isRevert(blocked),
                blockedText: friendly(blocked),
                realIsRevert: isRevert(real),
                realText: friendly(real),
            };
        }""")
        print("[transport] 403 -> isRevert=%s | %s"
              % (transport["blockedIsRevert"], transport["blockedText"][:70]))
        print("[transport] real revert -> isRevert=%s | %s"
              % (transport["realIsRevert"], transport["realText"][:50]))
        assert transport["blockedIsRevert"] is False, \
            "an HTTP 403 from the RPC is not a revert — we never reached the chain"
        assert "could not reach" in transport["blockedText"].lower(), transport["blockedText"]
        assert "router" not in transport["blockedText"].lower(), \
            "do not blame the router for a network we never reached"
        assert transport["realIsRevert"] is True, \
            "a genuine revert must still be treated as one"

        # ---- 2c. DEX coverage gate ----
        # ⚠️ این خط درباره‌ی مین‌نت حرف نمی‌زند. `stub-ethers.js` عمداً برای
        #    CANDIDATE_ROUTERS «کد ندارد» برمی‌گرداند تا مسیرِ «کاندیدِ
        #    تأییدنشده» در UI آزموده شود. یک بار همین خط ماه‌ها به‌جای
        #    واقعیتِ زنجیره خوانده شد و «سه صرافی مرده‌اند» در حافظه ثبت شد؛
        #    روی زنجیره هر شش‌تا PASS دادند و هر شش‌تا لیست‌سفید بودند.
        #    برچسب زیر برای این است که آن اشتباه دوباره تکرار نشود.
        cov = await pg.inner_text("#coverage")
        print("[coverage] (FIXTURE, not mainnet - the stub forces the candidate "
              "routers to look code-less) %s" % cov.replace("\n", " | "))
        assert "Routing through" in cov
        assert "no contract" in cov, "unverified DEXes must be shown with a reason, not hidden"
        assert "PancakeSwap" not in cov, "PancakeSwap should now pass the gates, not sit in the excluded list"

        # ---- 2c-bis. every DEX is called with the signature its router actually has ----
        gens = await pg.evaluate(
            "() => DEXES.map(d => ({name: d.name, kind: d.kind, sig: swapSigOf(d),"
            " ok: !!(dexStatus[d.id] && dexStatus[d.id].ok)}))")
        for g in gens:
            print("[dex] %-16s kind=%s ok=%-5s %s" % (g["name"], g["kind"], g["ok"], g["sig"][:46]))
        pcs = next(g for g in gens if "PancakeSwap" in g["name"])
        assert pcs["ok"], "PancakeSwap must pass the gates once wired as legacy V3"
        assert "uint256,uint256,uint256,uint160" in pcs["sig"], \
            "a legacy router must be called with the 8-field struct, not the 7-field one"
        uni = next(g for g in gens if g["name"] == "Uniswap V3")
        assert "uint256,uint256,uint160)" in uni["sig"] and "uint256,uint256,uint256" not in uni["sig"], \
            "SwapRouter02 must keep the 7-field struct"

        # ---- 2c-quinquies. [slipstream] — v5 wiring: Slipstream must not be mistaken
        # for the uint24-fee V3 generations, and its step must carry tickSpacing. ----
        # الف) امضای سواپش باید به سلکتور 0xa026383e هش شود، نه به 0x414bf389
        #    (که با آن‌جا اشتباه شکلش یکی است ولی سلکتورش فرق دارد).
        # E.id در صفحه‌ی اصلی همان fakeId استاب است (غیررمزنگاری) — برای سلکتور
        # *واقعی* باید مثل چک‌سام بالا از ethers واقعی استفاده کرد، وگرنه این
        # کاوشگر هیچ‌وقت نمی‌تواند تفاوت 0xa026383e و 0x414bf389 را واقعاً بسنجد.
        slip = next(g for g in gens if "Slipstream" in g["name"])
        real_e = await b.new_page()
        await real_e.set_content("<html></html>")
        await real_e.add_script_tag(path=vendor_path("ethers.umd.min"))
        sel = await real_e.evaluate("s => ethers.id(s).slice(0, 10)", slip["sig"])
        await real_e.close()
        print("[slipstream] swap selector = %s (kind=%s)" % (sel, slip["kind"]))
        assert sel == "0xa026383e", \
            "Slipstream's exactInputSingle must hash to 0xa026383e, got %s — check swapSigOf" % sel
        assert sel != "0x414bf389", \
            "Slipstream must never be filed under the V3_LEGACY selector — same shape, wrong selector"

        # ب) تاپل step در ABI اجراکننده باید دقیقاً ۸ فیلد داشته باشد و با
        #    int24 tickSpacing تمام شود.
        exec_sig = await pg.evaluate("() => ABI.executor[0]")
        m = re.search(r"\(\(([^)]*)\)\[\]\s*steps", exec_sig)
        assert m, "could not find the ((...)[] steps tuple in ABI.executor — re-check this guard"
        step_fields = [f.strip() for f in m.group(1).split(",")]
        print("[slipstream] executor step tuple fields = %s" % step_fields)
        assert len(step_fields) == 8, \
            "the executor step tuple must have exactly 8 fields, found %d: %s" \
            % (len(step_fields), step_fields)
        assert step_fields[-1] == "int24 tickSpacing", \
            "the step tuple must end with int24 tickSpacing, found %r" % step_fields[-1]
        assert step_fields[0] == "uint8 kind", \
            "kind must still be the first field, found %r" % step_fields[0]

        # ج) [checksum] بالا هر آدرسی در index.html را با EIP-55 واقعی می‌سنجد —
        #    این فقط تأیید می‌کند سه آدرس Slipstream واقعاً داخل آن دامنه‌اند،
        #    نه یک چک‌سام دوم. اگر یکی از این‌ها جا بیفتد، [checksum] هرگز آن را
        #    نمی‌دیده و صرافی جدید بی‌سروصدا از آن پوشش بیرون می‌ماند.
        slip_addrs = await pg.evaluate(
            "() => { const d = DEXES.find(x => x.kind === 4);"
            " return [d.router, d.factory, d.quoter]; }")
        print("[slipstream] addresses inside [checksum]'s scan: %s"
              % all(a in cands for a in slip_addrs))
        assert all(a in cands for a in slip_addrs), \
            "the Slipstream router/factory/quoter addresses must be literal 0x… text in " \
            "index.html, or the [checksum] probe never actually looks at them: %s" % slip_addrs

        # د) استخر Slipstream در step چاپ‌شده باید tickSpacing را در جایگاه ۸ حمل
        #    کند و feeTier صفر باشد — دقیقاً همان ترتیبی که buildParts می‌نویسد.
        step_probe = await pg.evaluate("""() => {
            const d = DEXES.find(x => x.kind === KIND.SLIPSTREAM);
            const tick = d.tickSpacings[0];
            const venue = {dex: d, feeTier: null, stable: null, tickSpacing: tick};
            const hop = {venue,
                tokenIn: {address: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913"},
                tokenOut: {address: "0x4200000000000000000000000000000000000006"}};
            const plan = {parts: [{route: {hops: [hop]}, amountIn: 1n}]};
            const step = buildParts(plan)[0][0][0];
            return {len: step.length, kind: step[0], feeTier: step[4],
                    stable: step[5], tickSpacing: step[7], expectTick: tick};
        }""")
        print("[slipstream] encoded step: len=%d kind=%s feeTier=%s stable=%s tickSpacing=%s (expect %s)"
              % (step_probe["len"], step_probe["kind"], step_probe["feeTier"],
                 step_probe["stable"], step_probe["tickSpacing"], step_probe["expectTick"]))
        assert step_probe["len"] == 8, "an encoded step must have exactly 8 elements"
        assert step_probe["kind"] == 4, "kind must be first and must be KIND.SLIPSTREAM"
        assert step_probe["feeTier"] == 0, \
            "a Slipstream venue has no fee tier — the encoded feeTier must be 0"
        assert step_probe["tickSpacing"] == step_probe["expectTick"], \
            "tickSpacing must land in position 8 (index 7), carrying the venue's own tick spacing"

        # ---- 2c-ter. the quoter gate checks the selector, not just that code exists ----
        # نسخه‌ی قبل فقط می‌پرسید «قراردادی آنجا هست؟» — همان شکافی که در سمت
        # روتر باگ SwapRouter02 را ساخت، فقط یک قدم آن‌طرف‌تر.
        reason = await pg.evaluate("""async () => {
            const d = DEXES.find(x => x.id === "uniswap-v3"), real = d.quoter;
            d.quoter = d.router;              // قرارداد هست، ولی تابع کوت را ندارد
            await verifyDexes();
            const r = dexStatus["uniswap-v3"].reason;
            d.quoter = real; await verifyDexes();
            return r;
        }""")
        print("[quoter gate] %s" % reason)
        assert "quoter" in reason.lower(), \
            "a quoter that lacks the function we call must be rejected: " + reason

        # ---- 2c-quater. «نتوانستیم بپرسیم» یک حالت است، نه یک جمله ----
        # قبلاً تنها نشانه‌اش متن reason بود و حلقه‌ی retry با مقایسه‌ی همان
        # رشته تصمیم می‌گرفت؛ و هر خطای غیرشبکه‌ای هم «could not reach the
        # network» گزارش می‌شد — یعنی «نمی‌دانم چرا» به کاربر به‌شکل یک علت
        # قطعیِ غلط می‌رسید. سه ادعا:
        gate = await pg.evaluate("""async () => {
            const pcs = DEXES.find(d => d.id === "pancake-v3");

            // الف) خطای غیرشبکه‌ای: آدرس بدچک‌سام، بیرون از rpcSend
            const realGA = ethers.getAddress;
            ethers.getAddress = a => {
                if (String(a).toLowerCase() === pcs.router.toLowerCase())
                    throw new Error("bad address checksum");
                return realGA(a);
            };
            await verifyDexes();
            const ours = Object.assign({}, dexStatus["pancake-v3"]);
            ethers.getAddress = realGA;
            await verifyDexes();

            // ب) خطای انتقال: همان 403 که ethers CALL_EXCEPTION علامتش می‌زند
            const realCode = ethers.JsonRpcProvider.prototype.getCode;
            verifyTries = 3;                    // جلوی تایمر retry واقعی
            ethers.JsonRpcProvider.prototype.getCode = async () => {
                throw Object.assign(new Error("missing revert data"),
                    {code: "CALL_EXCEPTION", data: "Request failed with status code 403"});
            };
            await verifyDexes();
            const down = Object.assign({}, dexStatus["pancake-v3"]);
            ethers.JsonRpcProvider.prototype.getCode = realCode;
            verifyTries = 0;
            await verifyDexes();

            // ج) تلاش دوباره‌ی نقطه‌ای نباید صرافی سالم را قربانی کند
            const uniBefore = dexStatus["uniswap-v3"].ok;
            await verifyDexes([pcs]);
            return {ours, down, uniBefore, uniAfter: dexStatus["uniswap-v3"].ok,
                    uniReason: dexStatus["uniswap-v3"].reason};
        }""")
        print("[gate] our fault -> unreachable=%s | %s"
              % (gate["ours"]["unreachable"], gate["ours"]["reason"]))
        print("[gate] rpc 403   -> unreachable=%s | %s"
              % (gate["down"]["unreachable"], gate["down"]["reason"]))
        assert gate["ours"]["unreachable"] is False, \
            "a bad address is our bug, not an unreachable network — retrying never fixes it"
        assert "network" not in gate["ours"]["reason"].lower() \
            or "not the network" in gate["ours"]["reason"].lower(), \
            "do not blame the network for a fault on our side: " + gate["ours"]["reason"]
        assert "checksum" in (gate["ours"].get("err") or ""), \
            "the real error must be kept, not thrown away: %r" % gate["ours"].get("err")
        assert gate_errs, "a fault on our side must be logged, not swallowed"
        assert gate["down"]["unreachable"] is True, \
            "an HTTP 403 while verifying means we could not ask — that must be retried"
        assert "could not reach the network" in gate["down"]["reason"], gate["down"]["reason"]
        print("[gate] targeted retry -> uniswap ok=%s (%s)"
              % (gate["uniAfter"], gate["uniReason"]))
        assert gate["uniBefore"] is True and gate["uniAfter"] is True, \
            "a targeted retry must not wipe DEXes that already verified"
        assert gate["uniReason"] == "verified", gate["uniReason"]

        # ---- 2c-sexies. [slipstream v1] — gate 3 must block the old-factory
        # router until the executor allow-lists it, and routing must never
        # pick a venue gate 3 rejected. ----
        slip_v1 = await pg.evaluate("""async () => {
            await verifyDexes();
            const before = Object.assign({}, dexStatus["aerodrome-cl-v1"]);
            window.__STUB_ROUTER_ALLOWED__ =
                {"0xbe6d8f0d05cc4be24d5167a3ef062215be6d18a5": false};
            await verifyDexes();
            const after = Object.assign({}, dexStatus["aerodrome-cl-v1"]);
            const enabledIds = enabledDexes().map(d => d.id);
            const venuesLeft = allVenues().some(v => v.dex.id === "aerodrome-cl-v1");
            delete window.__STUB_ROUTER_ALLOWED__;
            await verifyDexes();
            const restored = Object.assign({}, dexStatus["aerodrome-cl-v1"]);
            return {before, after, enabledIds, venuesLeft, restored};
        }""")
        print("[slipstream v1] default -> ok=%s | not-allow-listed -> ok=%s reason=%r"
              % (slip_v1["before"]["ok"], slip_v1["after"]["ok"], slip_v1["after"]["reason"]))
        assert slip_v1["before"]["ok"] is True, \
            "aerodrome-cl-v1 must pass gates by default (stub answers allowedRouter=true)"
        assert slip_v1["after"]["ok"] is False, \
            "aerodrome-cl-v1 must be rejected once the executor does not allow-list its router"
        assert slip_v1["after"]["reason"] == "not allow-listed on the executor contract yet", \
            slip_v1["after"]["reason"]
        assert "aerodrome-cl-v1" not in slip_v1["enabledIds"], \
            "a not-allow-listed venue must not be in enabledDexes()"
        assert slip_v1["venuesLeft"] is False, \
            "a not-allow-listed venue must carry no leg into route search (allVenues())"
        assert slip_v1["restored"]["ok"] is True, \
            "restoring the stub's allowedRouter must restore aerodrome-cl-v1"

        # ---- 2c-septies. [uniswap v2 venue] — Uniswap V2 on Base is a V2 candidate:
        # exact EIP-55 addresses, never core, and gate 3 keeps it out of routing
        # until the executor allow-lists the router. ----
        UV2_ROUTER = "0x4752ba5DBc23f44D87826276BF6Fd6b1C372aD24"
        UV2_FACTORY = "0x8909Dc15e40173Ff4699343b6eB8132c65e18eC6"
        uv2_static = await pg.evaluate("""() => {
            const d = DEXES.find(x => x.id === "uniswap-v2");
            return {row: d ? {name: d.name, cls: d.cls, kind: d.kind, core: !!d.core,
                              router: d.router, factory: d.factory} : null,
                    v2kind: KIND.V2,
                    clsUsers: DEXES.filter(x => d && x.cls === d.cls).map(x => x.id),
                    gtMap: GT_DEX_TO_DEX["uniswap-v2-base"]};
        }""")
        uv2 = uv2_static["row"]
        assert uv2, "DEXES has no uniswap-v2 row — 36 of 112 new Base pairs get no route"
        assert uv2["router"] == UV2_ROUTER and uv2["factory"] == UV2_FACTORY, \
            "uniswap-v2 addresses must be the exact EIP-55 forms: %s" % uv2
        assert uv2["kind"] == uv2_static["v2kind"] and uv2["name"] == "Uniswap V2", uv2
        assert not uv2["core"], "uniswap-v2 is a candidate, not core: it was never swapped with real money"
        assert uv2_static["clsUsers"] == ["uniswap-v2"], \
            "the dex colour class %r is shared: %s" % (uv2["cls"], uv2_static["clsUsers"])
        assert uv2_static["gtMap"] == "uniswap-v2", \
            "GeckoTerminal id uniswap-v2-base must map to the uniswap-v2 row"
        idx_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
        assert re.search(r"\.vdot\.%s\{background:#[0-9a-fA-F]{6}\}" % uv2["cls"], idx_src), \
            "the .vdot.%s colour rule is missing" % uv2["cls"]
        deploy_sh = open(os.path.join(HERE, "..", "..", "contracts", "script", "deploy.sh"),
                         encoding="utf-8").read()
        dep_block = re.search(r'ROUTERS="(.*?)"', deploy_sh, re.S).group(1)
        dep_routers = re.findall(r"0x[0-9a-fA-F]{40}", dep_block)
        assert UV2_ROUTER in dep_routers, \
            "deploy.sh does not allow-list the Uniswap V2 router (byte for byte): %s" % dep_routers
        app_all = await pg.evaluate("() => DEXES.filter(d => d.kind !== KIND.V4).map(d => d.router)")
        assert sorted(dep_routers) == sorted(app_all), \
            "deploy.sh ROUTERS and the app's DEXES routers differ: %s vs %s" % (dep_routers, app_all)

        uv2_dyn = await pg.evaluate("""async () => {
            const run = async () => {
                await verifyDexes();
                const st = Object.assign({}, dexStatus["uniswap-v2"]);
                const cov = document.getElementById("coverage").innerText;
                const enabled = enabledDexes().map(d => d.id);
                const stats = newStats();
                const tIn = tokenBySymbol("WETH"), tOut = tokenBySymbol("USDC");
                const {routes, direct} = await findRoutes(tIn, tOut, 10n ** 18n, stats);
                return {st, cov, enabled,
                        directIds: direct.map(r => r.venue.dex.id),
                        directV2: direct.filter(r => r.venue.dex.id === "uniswap-v2")
                                        .map(r => r.out !== null && r.out > 0n),
                        routeIds: routes.map(r => r.hops.map(h => h.venue.dex.id))};
            };
            const before = await run();
            window.__STUB_ROUTER_ALLOWED__ = {"0x4752ba5dbc23f44d87826276bf6fd6b1c372ad24": true};
            const after = await run();
            delete window.__STUB_ROUTER_ALLOWED__;
            const restored = await run();
            return {before, after, restored};
        }""")
        ub, ua, ur = uv2_dyn["before"], uv2_dyn["after"], uv2_dyn["restored"]
        print("[uniswap v2 venue] %s / %s / kind V2 / not core | executor not allow-listing -> %r, "
              "legs=%s | allow-listed -> ok=%s, quoted=%s"
              % (UV2_ROUTER, UV2_FACTORY, ub["st"]["reason"],
                 ub["directIds"].count("uniswap-v2"), ua["st"]["ok"], ua["directV2"]))
        assert ub["st"]["ok"] is False and ub["st"]["reason"] == "not allow-listed on the executor contract yet", ub["st"]
        assert "Uniswap V2" in ub["cov"] and "not allow-listed" in ub["cov"], \
            "the coverage list must show Uniswap V2 with its reason: " + ub["cov"]
        assert "uniswap-v2" not in ub["enabled"], "a not-allow-listed venue must not be enabled"
        assert "uniswap-v2" not in ub["directIds"] and \
            not any("uniswap-v2" in r for r in ub["routeIds"]), \
            "a not-allow-listed venue must never be quoted or used in a route"
        assert ua["st"]["ok"] is True and ua["st"]["reason"] == "verified", ua["st"]
        assert "uniswap-v2" in ua["enabled"] and ua["directV2"] == [True], \
            "once allow-listed, Uniswap V2 must quote like the other V2 venues: %s" % ua["directV2"]
        assert any("uniswap-v2" in r for r in ua["routeIds"]), \
            "once allow-listed, Uniswap V2 must appear as a route: %s" % ua["routeIds"]
        assert ur["st"]["ok"] is False and "uniswap-v2" not in ur["directIds"], \
            "removing the allow-list entry must take the venue out of routing again"

        await check_uniswap_v4(pg)

        # ---- 2c-bis. token logos load, initials survive failure ----
        await pg.wait_for_timeout(800)
        logos = await pg.eval_on_selector_all("#tokInAv img, #tokOutAv img", "e => e.length")
        initials = await pg.inner_text("#tokInAv")
        print("[icons] logo images: %s   fallback initials: %r" % (logos, initials.strip()))
        assert initials.strip() != "", "initials must always be present as a fallback"

        # ---- 2a-pre. the token list itself ----
        toks = await pg.evaluate(
            "() => BASE_TOKENS.map(t => ({s: t.symbol, d: t.decimals,"
            " a: t.address, st: !!t.stable, n: t.native, lg: t.logo || null}))")
        # ۲۰ اکتبر: لوگوی ثابتِ فهرست — فقط https روی CDNِ CoinGecko، و tokenLogo بی‌شبکه همان را برمی‌گرداند
        for t in toks:
            if t["lg"] is not None:
                assert re.match(r"^https://coin-images\.coingecko\.com/coins/images/\d+/small/[^\s\"'<>]+$", t["lg"]), \
                    "%s has a malformed static logo: %s" % (t["s"], t["lg"])
        lg_n = sum(1 for t in toks if t["lg"])
        assert lg_n >= 14, "the 14 tokens added on 20 Oct must carry a static logo, got %d" % lg_n
        lg_ok = await pg.evaluate("async () => { const t = BASE_TOKENS.find(x => x.symbol === 'LINK'); return (await tokenLogo(t)) === t.logo; }")
        assert lg_ok, "tokenLogo must return a list token's static logo without asking the network"
        sol_lg = await pg.evaluate("() => SOL_APP_TOKEN_LIST.filter(t => !(typeof t.logo === 'string' && /^https:\\/\\/coin-images\\.coingecko\\.com\\//.test(t.logo))).map(t => t.symbol)")
        assert sol_lg == [], "every Solana picker preset must carry a static CoinGecko logo: missing %s" % sol_lg
        ts_disp = await pg.evaluate("() => { const e = document.getElementById('solTokStats'); const h = e.hidden; e.hidden = true; const d = getComputedStyle(e).display; e.hidden = h; return d; }")
        assert ts_disp == "none", "[static logos] a hidden #solTokStats must not display (stale stats of the previous token): %s" % ts_disp
        print("[static logos] %d Base list tokens and every Solana preset carry a fixed https CoinGecko-CDN logo; tokenLogo returns it with no network call" % lg_n)
        print("[token list] %s" % ", ".join(f"{t['s']}/{t['d']}" for t in toks))
        seen = {}
        for t in toks:
            assert t["s"] not in seen, "duplicate symbol in the token list: %s" % t["s"]
            seen[t["s"]] = t
            if not t["n"]:
                assert t["a"].startswith("0x") and len(t["a"]) == 42, \
                    "%s has a malformed address: %s" % (t["s"], t["a"])
            assert isinstance(t["d"], int) and 0 < t["d"] <= 18, \
                "%s has implausible decimals: %s" % (t["s"], t["d"])
        # ⚠️ `stable` یعنی «تقریباً یک دلار» و مستقیم در قیمت‌گذاری می‌نشیند.
        #    EURC به یورو وصل است؛ اگر روزی کسی این پرچم را برایش بگذارد،
        #    قیمت‌ها بی‌صدا حدود ۸٪ غلط می‌شوند.
        assert not seen["EURC"]["st"], \
            "EURC is euro-pegged — marking it stable makes every price using it wrong"
        for s in ["USDC", "USDT", "USDbC", "DAI"]:
            assert seen[s]["st"], "%s is dollar-pegged and must be marked stable" % s
        # اعشار خوانده‌شده از زنجیره (۱۶ آگوست ۲۰۲۶) — قفلش می‌کنیم
        for s, d in [("USDT", 6), ("USDbC", 6), ("EURC", 6), ("cbETH", 18),
                     ("wstETH", 18), ("VIRTUAL", 18), ("MORPHO", 18), ("DEGEN", 18)]:
            assert seen[s]["d"] == d, \
                "%s decimals drifted from what the contract reports: %s" % (s, seen[s]["d"])

        # ---- 2a-bis. Disconnect must actually stay disconnected ----
        # باگ واقعی روی سایت زنده: disconnect فقط وضعیت سمت ما را پاک می‌کرد،
        # ولی والت هنوز سایت را مجاز می‌دانست. پس رفرش بعدی با eth_accounts
        # بی‌صدا دوباره وصل می‌شد و آدرس کاربر برمی‌گشت، بدون هیچ پرسشی.
        dis = await pg.evaluate("""async () => {
            localStorage.removeItem("zaexa.disconnected");
            const fake = {__who: "ghost", request: async ({method}) =>
                method === "eth_accounts" || method === "eth_requestAccounts"
                    ? ["0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23"] : null,
                on(){}, removeListener(){}};
            const out = {};
            out.autoBefore = !userDisconnected();

            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id; walletProvider = {}; paintWallet();
            await disconnect();

            out.cleared = account === null;
            out.flagged = userDisconnected();
            // همان کاری که بارگذاری صفحه می‌کند
            const accs = await fake.request({method: "eth_accounts"});
            out.walletStillAllows = !!(accs && accs.length);
            out.wouldAutoConnect = !userDisconnected();
            // و انتخاب صریح خودِ کاربر باید دوباره اجازه بدهد
            markDisconnected(false);
            out.afterExplicit = !userDisconnected();
            localStorage.removeItem("zaexa.disconnected");
            return out;
        }""")
        print("[disconnect] cleared=%s remembered=%s walletStillAllows=%s autoReconnect=%s"
              % (dis["cleared"], dis["flagged"], dis["walletStillAllows"], dis["wouldAutoConnect"]))
        assert dis["cleared"], "disconnect must clear the account"
        assert dis["flagged"], "disconnect must be remembered across reloads"
        assert dis["walletStillAllows"], \
            "the probe is wrong: the wallet is supposed to still allow the site"
        assert not dis["wouldAutoConnect"], \
            "the site would silently reconnect after the user pressed Disconnect"
        assert dis["afterExplicit"], \
            "picking a wallet explicitly must undo the disconnect, or connecting breaks"

        # ---- 2a-ter. reads must never be routed through a remote wallet ----
        # با WalletConnect هر eth_call باید از رله به گوشی برود و برگردد. اگر
        # خواندن‌ها از آنجا بروند، هر کوت و هر allowance ثانیه‌ها طول می‌کشد و
        # عملاً سواپ هرگز آماده نمی‌شود — حتی بعد از approve نامحدود، چون
        # تأیید approve خودش یک خواندن است. امضا فرق دارد و باید برود.
        remote = await pg.evaluate("""async () => {
            const realWP = walletProvider, realId = walletChainId;
            let viaWallet = 0;
            walletProvider = {call: async () => { viaWallet++; throw new Error("fetch failed"); }};
            walletChainId = CHAIN.id;

            walletIsRemote = false;
            const injectedReady = walletReady();
            walletIsRemote = true;
            const remoteReady = walletReady();
            try { await chainCall({to: CHAIN.multicall3, data: "0x"}); } catch {}
            const callsWhileRemote = viaWallet;

            walletProvider = realWP; walletChainId = realId; walletIsRemote = false;
            return {injectedReady, remoteReady, callsWhileRemote};
        }""")
        print("[wallet reads] injected=%s remote=%s (remote calls made: %s)"
              % (remote["injectedReady"], remote["remoteReady"], remote["callsWhileRemote"]))
        assert remote["injectedReady"], \
            "an injected wallet is the best read source — do not stop using it"
        assert not remote["remoteReady"] and remote["callsWhileRemote"] == 0, \
            "reads went through the WalletConnect relay; every quote would round-trip to the phone"

        # ---- 2a-quater. approve through a remote wallet must not carry our gas ----
        # زریون روی eth_sendTransaction خطای {code:404,"Internal error"} می‌داد و
        # ethers آن را در «could not coalesce error» می‌پیچید. تراکنشی که ethers
        # می‌سازد `gas` دارد — تخمینِ RPC *ما*، نه والت. با {gasLimit:null} هم
        # همان است (آزموده شد). برای والت راه‌دور خام می‌فرستیم.
        appr = await pg.evaluate("""async () => {
            const sent = [];
            const realProv = walletEip1193, realAcct = account,
                  realSigner = signer, realRemote = walletIsRemote,
                  realTok = tokenIn, realWait = waitForAllowance;
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            tokenIn = allTokens().find(t => t.symbol === "USDC");
            document.getElementById("amtIn").value = "1.5";
            walletEip1193 = {request: async ({method, params}) => {
                if (method === "eth_sendTransaction") { sent.push(params[0]); return "0x" + "ab".repeat(32); }
                return null; }};
            walletIsRemote = true;
            waitForAllowance = async () => true;
            await doApprove();
            walletEip1193 = realProv; account = realAcct; signer = realSigner;
            walletIsRemote = realRemote; tokenIn = realTok; waitForAllowance = realWait;
            return {calls: sent.length, keys: sent[0] ? Object.keys(sent[0]).sort() : null,
                    to: sent[0] && sent[0].to};
        }""")
        # همان قاعده برای خودِ سواپ: نه گسِ ما، و برای ETH بومی value لازم است
        swp = await pg.evaluate("""async () => {
            const sent = [];
            const realProv = walletEip1193, realAcct = account, realRemote = walletIsRemote;
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletEip1193 = {request: async ({method, params}) => {
                if (method === "eth_sendTransaction") { sent.push(params[0]); return "0x" + "cd".repeat(32); }
                return null; }};
            walletIsRemote = true;
            const eth = allTokens().find(t => t.native);
            const parts = [[[[1, "0x2626664c2603336E57B271c5C0b26F421741e481",
                              "0x4200000000000000000000000000000000000006",
                              "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913", 100, false,
                              "0x33128a8fC17869897dcE68Ed026d694621f6FDfD"]], 1000n]];
            const data = iExec.encodeFunctionData("executeSwap",
              [routable(eth).address, "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
               1000n, 1n, parts, 99999999999]);
            const p = {from: account, to: ethers.getAddress(CHAIN.executor), data,
                       value: "0x" + (1000n).toString(16)};
            await walletEip1193.request({method: "eth_sendTransaction", params: [p]});
            walletEip1193 = realProv; account = realAcct; walletIsRemote = realRemote;
            return {keys: Object.keys(sent[0]).sort(), value: sent[0].value};
        }""")
        print("[swap remote] fields=%s value=%s" % (swp["keys"], swp["value"]))
        assert "gas" not in swp["keys"], "the swap must not carry our own gas estimate either"
        assert swp["value"] == "0x3e8", "native ETH swaps must still send value"

        print("[approve remote] fields=%s" % (appr["keys"],))
        assert appr["calls"] == 1, "approve did not reach the wallet: %s" % appr
        assert "gas" not in (appr["keys"] or []), \
            ("we sent our own gas estimate to a remote wallet: %s — let the wallet estimate"
             % appr["keys"])
        assert set(appr["keys"]) == {"data", "from", "to"}, \
            "unexpected fields in the approve payload: %s" % appr["keys"]

        # ---- 2b-pre. GeckoTerminal request budget ----
        # صف GeckoTerminal تک‌خطی و با فاصله‌ی اجباری است، پس *تعداد*
        # درخواست‌ها مستقیماً می‌شود تأخیری که کاربر می‌بیند: لوگوها دیر
        # می‌آمدند و نمودار گاهی اصلاً نمی‌آمد. دو چیز را می‌سنجیم:
        # هیچ URLی دو بار روی سیم نرود، و هر توکن درخواست جدا نسازد.
        budget = await pg.evaluate("""async () => {
            const seen = [];
            const realFetch = window.fetch;
            window.fetch = function (u, o) { seen.push(String(u)); return realFetch(u, o); };
            gtCache.clear(); gtInflight.clear();
            Object.keys(metaCache).forEach(k => delete metaCache[k]);

            const toks = allTokens().filter(t => !t.native).map(t => t.address);
            await Promise.all(toks.map(a => tokenMeta(a)));      // مثل رسم آواتارها
            await Promise.all(toks.map(a => tokenMeta(a)));      // بار دوم باید رایگان باشد
            const metaCalls = seen.filter(u => /\\/tokens\\//.test(u)).length;

            const before = seen.length;
            const u = GT + "/networks/base/tokens/" + toks[0] + "/pools?page=1";
            await Promise.all([gtJson(u), gtJson(u), gtJson(u)]);  // همزمان
            await gtJson(u);                                       // و یک بار بعدش
            const dupCalls = seen.length - before;

            window.fetch = realFetch;
            return {tokens: toks.length, metaCalls, dupCalls};
        }""")
        print("[gt budget] %s tokens -> %s metadata calls; 4 identical urls -> %s call"
              % (budget["tokens"], budget["metaCalls"], budget["dupCalls"]))
        assert budget["metaCalls"] <= 2, \
            ("%s tokens caused %s metadata requests — they must batch, not queue one by one"
             % (budget["tokens"], budget["metaCalls"]))
        assert budget["dupCalls"] == 1, \
            "four requests for the same url hit the network %s times" % budget["dupCalls"]

        # وقتی سرویس پشت سر هم شکست می‌خورد، ادامه‌ی درخواست‌ها هم بی‌فایده است
        # هم وضع را بدتر می‌کند. روی سایت زنده همین اتفاق افتاد: دسته ۴۲۹ خورد،
        # loadMetas تک‌تک پرسید، و یک درخواست به چهل‌ودو تا تبدیل شد.
        storm = await pg.evaluate("""async () => {
            const realFetch = window.fetch;
            let hits = 0;
            window.fetch = async () => { hits++; throw new TypeError("Failed to fetch"); };
            gtCache.clear(); gtInflight.clear(); gtFails = 0; gtCoolUntil = 0;
            Object.keys(metaCache).forEach(k => delete metaCache[k]);

            const toks = allTokens().filter(t => !t.native).map(t => t.address);
            try { await loadMetas(toks); } catch {}
            const afterBatch = hits;
            // و درخواست‌های بعدی، تا وقتی در حالت خنک‌شدن هستیم، به شبکه نزنند
            try { await gtJson(GT + "/networks/base/tokens/" + toks[0]); } catch {}
            const afterCooldown = hits;

            window.fetch = realFetch; gtFails = 0; gtCoolUntil = 0;
            return {tokens: toks.length, afterBatch, extra: afterCooldown - afterBatch};
        }""")
        print("[gt storm] %s tokens, everything failing -> %s network hits, %s more while cooling"
              % (storm["tokens"], storm["afterBatch"], storm["extra"]))
        assert storm["afterBatch"] <= 4, \
            ("a failing batch fanned out into %s requests for %s tokens - when the service "
             "is down, asking one address at a time only makes it worse"
             % (storm["afterBatch"], storm["tokens"]))
        assert storm["extra"] == 0, \
            "requests still reached the network while the circuit breaker was open"

        # ---- 2b-quater. GeckoTerminal proxy routing ----
        # سقف نرخ روی IP کاربر است، پس درخواست‌ها از /gt روی دامنه‌ی خودمان
        # رد می‌شوند. دو چیز باید درست باشد و هیچ‌کدام بدیهی نیست:
        # ۱) وقتی پراکسی هست، آدرس *بازنویسی* شود ولی کلید کش همان بماند —
        #    وگرنه هر آدرس دو بار روی سیم می‌رود.
        # ۲) وقتی پراکسی نیست (استقرار ناقص)، سایت زنده نباید کور شود.
        #    ولی یک ۴۰۴ واقعیِ خودِ GeckoTerminal *نباید* پراکسی را خاموش کند.
        proxy = await pg.evaluate("""async () => {
            const realFetch = window.fetch, seen = [];
            const out = {};
            const reply = (status, marked) => new Response("{}", {
                status, headers: marked ? {"x-zaexa-proxy": "upstream-" + status} : {},
            });

            // ۱) با پراکسی: آدرس بازنویسی می‌شود، کلید کش همان می‌ماند
            // ۱۳ اکتبر: ترتیبِ پیش‌فرض مستقیم‌اول شد؛ این کاوشگر «وقتی مسیرِ
            // /gt انتخاب شده» را می‌سنجد، پس پرچمِ اول‌پراکسی را صریح می‌گذارد.
            sessionStorage.setItem(GT_ROUTE_KEY, JSON.stringify({r: "proxy", t: Date.now()}));
            gtProxy = "https://zaexa.com/gt";
            gtCache.clear(); gtInflight.clear(); gtFails = 0; gtCoolUntil = 0;
            window.fetch = async (u) => { seen.push(String(u)); return reply(200, true); };
            const u = GT + "/networks/base/tokens/0xabc";
            await gtJson(u);
            out.wire = seen[0];
            out.cachedUnder = [...gtCache.keys()][0];

            // ۲) ۴۰۴ *با* نشان = خود GeckoTerminal گفته نیست. پراکسی سالم است.
            seen.length = 0; gtCache.clear(); gtInflight.clear();
            gtFails = 0; gtCoolUntil = 0;
            window.fetch = async (x) => { seen.push(String(x)); return reply(404, true); };
            try { await gtJson(GT + "/networks/base/tokens/0xdead"); } catch {}
            out.realMissCalls = seen.length;
            out.proxyStillOn = !!gtProxy;

            // ۳) ۴۰۴ *بدون* نشان = /gt وجود ندارد. یک بار مستقیم، بعد خاموش.
            seen.length = 0; gtCache.clear(); gtInflight.clear();
            gtFails = 0; gtCoolUntil = 0;
            window.fetch = async (x) => {
                seen.push(String(x));
                return String(x).startsWith("https://zaexa.com/gt")
                    ? reply(404, false) : reply(200, false);
            };
            // ⚠️ اگر fallback نباشد این throw می‌کند و کل کاوشگر با یک خطای
            // خام می‌افتد به‌جای ادعای روشن — پس خودمان می‌گیریمش.
            out.recovered = true;
            try { await gtJson(GT + "/networks/base/tokens/0xabc"); }
            catch (e) { out.recovered = false; }
            out.firstTry = seen[0];
            out.retry = seen[1];
            out.proxyOffAfter = !gtProxy;

            seen.length = 0; gtCache.clear(); gtInflight.clear();
            gtFails = 0; gtCoolUntil = 0;
            try { await gtJson(GT + "/networks/base/tokens/0xbeef"); } catch (e) {}
            out.afterGiveUp = seen[0];

            window.fetch = realFetch;
            sessionStorage.removeItem(GT_ROUTE_KEY);
            gtProxy = null; gtCache.clear(); gtInflight.clear();
            gtFails = 0; gtCoolUntil = 0;
            return out;
        }""")
        # ⚠️ کوتاه‌کننده باید None را هم تحمل کند: وقتی کاوشگر می‌افتد، معمولاً
        # یکی از این کلیدها اصلاً پر نشده، و آن‌وقت خودِ چاپ می‌ترکد و پیام
        # واقعی گم می‌شود.
        sh = lambda s: str(s).replace("https://", "")
        print("[gt proxy] wire=%s cached-as=%s | missing proxy -> %s then %s, later %s"
              % (sh(proxy["wire"]), sh(proxy["cachedUnder"]), sh(proxy["firstTry"]),
                 sh(proxy["retry"]), sh(proxy["afterGiveUp"])))
        assert proxy["wire"] == "https://zaexa.com/gt/networks/base/tokens/0xabc", \
            "the request did not go through our own proxy: %s" % proxy["wire"]
        assert proxy["cachedUnder"] == GT_DIRECT + "/networks/base/tokens/0xabc", \
            ("the cache key must stay the canonical geckoterminal url, otherwise the same "
             "response is fetched twice: %s" % proxy["cachedUnder"])
        assert proxy["realMissCalls"] == 1 and proxy["proxyStillOn"], \
            ("a 404 that came *from* geckoterminal turned the proxy off — "
             "an unknown token must not disable proxying for the whole session")
        assert proxy["firstTry"].startswith("https://zaexa.com/gt"), \
            "the first attempt should try the proxy: %s" % proxy["firstTry"]
        assert proxy["recovered"], \
            ("a deployment without /gt made the request fail outright — the page must "
             "fall back to geckoterminal instead of losing charts and logos")
        assert proxy["retry"] == GT_DIRECT + "/networks/base/tokens/0xabc", \
            ("when /gt is missing the page must fall back to geckoterminal directly, "
             "not go dark: %s" % proxy["retry"])
        assert proxy["proxyOffAfter"], "the proxy stayed on after it answered 404"
        assert proxy["afterGiveUp"] == GT_DIRECT + "/networks/base/tokens/0xbeef", \
            ("after giving up on the proxy every later request must go direct: %s"
             % proxy["afterGiveUp"])

        # ---- 2b-quater-bis. gtCache is capped ----
        # gtCache روی هر پاسخ موفق /gt یک ورودی می‌نویسد و TTL فقط موقعِ
        # *خواندن* سنجیده می‌شود — یک نشستِ طولانی که پشتِ سرِ هم ده‌ها توکن
        # را باز می‌کند هرگز چیزی از این Map پاک نمی‌کرد. اینجا مستقیم روی
        # gtCacheSet می‌سنجیم (بدون شبکه) که سقف واقعاً نگه داشته می‌شود.
        cap = await pg.evaluate("""() => {
            gtCache.clear();
            const n = GT_CACHE_MAX + 50;
            for (let i = 0; i < n; i++)
                gtCacheSet("https://x/" + i, {t: i, v: i});
            return {max: GT_CACHE_MAX, inserted: n, size: gtCache.size,
                    oldestGone: !gtCache.has("https://x/0"),
                    newestKept: gtCache.has("https://x/" + (n - 1))};
        }""")
        print("[gt cache cap] max=%s inserted=%s size after=%s oldestGone=%s newestKept=%s"
              % (cap["max"], cap["inserted"], cap["size"], cap["oldestGone"], cap["newestKept"]))
        assert cap["size"] <= cap["max"], \
            ("gtCache grew past its cap: size=%s — a long session opening many tokens would "
             "leak memory forever, since TTL is only checked on read" % cap["size"])
        assert cap["oldestGone"], \
            "gtCache did not evict the oldest entry first — following the same rule as lsWrite"
        assert cap["newestKept"], \
            "gtCache evicted a fresh entry instead of the oldest ones"
        await pg.evaluate("() => { gtCache.clear(); }")

        # ---- 2b-quinquies. what survives a refresh ----
        # حسام پیدایش کرد: چند رفرش پیاپی و لوگوها و نمودار می‌افتند. علتش
        # سرویس نیست — هر رفرش حافظه‌ی صفحه را دور می‌ریزد و همه‌چیز از نو
        # پرسیده می‌شود، و سقف ۳۰ درخواست در دقیقه است. پس چیزهای واقعاً
        # ثابت باید بین بازدیدها بمانند.
        # و چون آدرس لوگو مستقیم در img.src می‌نشیند، هرچه از انبار مرورگر
        # بیرون می‌آید باید بی‌اعتبار فرض شود.
        logo = await pg.evaluate("""async () => {
            const realFetch = window.fetch;
            let hits = 0;
            const ADDR = "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
            const IMG  = "https://assets.example/token.png";
            const tok  = {address: ADDR, symbol: "FAKE"};
            const reset = () => {
                Object.keys(metaCache).forEach(k => delete metaCache[k]);
                Object.keys(poolCache).forEach(k => delete poolCache[k]);
                gtCache.clear(); gtInflight.clear(); gtFails = 0; gtCoolUntil = 0;
            };
            window.fetch = async (u) => {
                hits++;
                return /\\/pools/.test(String(u))
                  ? new Response(JSON.stringify({data: [{id: "base_0xPOOL"}]}), {status: 200})
                  : new Response(JSON.stringify(
                      {data: [{attributes: {address: ADDR, image_url: IMG}}]}), {status: 200});
            };
            localStorage.removeItem(LS_LOGO); localStorage.removeItem(LS_POOL);
            const out = {};

            reset();
            out.first = await tokenLogo(tok);
            out.firstHits = hits;

            // رفرش شبیه‌سازی‌شده: حافظه‌ی صفحه پاک، انبار مرورگر دست‌نخورده
            reset(); hits = 0;
            out.second = await tokenLogo(tok);
            out.secondHits = hits;

            reset(); hits = 0;
            out.pool1 = await topPoolFor(tok);
            const poolFirstHits = hits;
            reset(); hits = 0;
            out.pool2 = await topPoolFor(tok);
            out.poolHits = [poolFirstHits, hits];

            // انبار مسموم — نباید هرگز به img.src برسد
            localStorage.setItem(LS_LOGO, JSON.stringify(
                {[ADDR]: {v: "javascript:alert(1)", t: Date.now()}}));
            reset(); hits = 0;
            out.poisoned = await tokenLogo(tok);
            out.poisonHits = hits;

            localStorage.setItem(LS_POOL, JSON.stringify(
                {[ADDR]: {v: "../../evil", t: Date.now()}}));
            reset();
            out.poisonedPool = await topPoolFor(tok);

            // منقضی‌شده باید دوباره پرسیده شود، نه اینکه تا ابد بماند
            localStorage.setItem(LS_LOGO, JSON.stringify(
                {[ADDR]: {v: "https://stale.example/a.png", t: Date.now() - 8 * 864e5}}));
            reset(); hits = 0;
            out.expired = await tokenLogo(tok);
            out.expiredHits = hits;

            // «لوگو ندارد» باید زود منقضی شود. یک پاسخ ناقصِ گذرا نباید یک
            // هفته به «این توکن لوگو ندارد» تبدیل شود.
            localStorage.setItem(LS_LOGO, JSON.stringify(
                {[ADDR]: {v: "", t: Date.now() - 2 * 36e5}}));
            reset(); hits = 0;
            out.staleNone = await tokenLogo(tok);
            out.staleNoneHits = hits;
            // ولی همان «ندارد» تازه باید نگه داشته شود
            localStorage.setItem(LS_LOGO, JSON.stringify(
                {[ADDR]: {v: "", t: Date.now()}}));
            reset(); hits = 0;
            out.freshNone = await tokenLogo(tok);
            out.freshNoneHits = hits;

            // آدرس data: از سرویس: نه ذخیره می‌شود و نه — از این نسخه — نمایش
            localStorage.removeItem(LS_LOGO);
            const DATA = "data:image/png;base64,iVBORw0KGgo=";
            window.fetch = async () => { hits++; return new Response(JSON.stringify(
                {data: [{attributes: {address: ADDR, image_url: DATA}}]}), {status: 200}); };
            reset();
            out.dataUrl = await tokenLogo(tok);
            out.dataStored = localStorage.getItem(LS_LOGO);

            // …ولی آیکون خودمان که یک data: درون‌فایل است باید سر جایش بماند.
            // سخت‌کردن مسیر نمایش نباید آیکون ETH را قربانی کند.
            out.ethIcon = await tokenLogo(allTokens().find(t => t.native));
            out.ethIsOurs = out.ethIcon === ETH_ICON;

            // و چیزی که واقعاً به img.src می‌رسد سنجیده می‌شود، نه فقط
            // خروجی tokenLogo — چاه همان جاست.
            const box = document.createElement("div");
            paintAvatar(box, allTokens().find(t => t.native));
            await new Promise(r => setTimeout(r, 60));
            out.ethImgSrc = (box.querySelector("img") || {}).src || null;

            const box2 = document.createElement("div");
            paintAvatar(box2, tok);
            await new Promise(r => setTimeout(r, 60));
            out.dataImgSrc = (box2.querySelector("img") || {}).src || null;

            /* دفاع دومِ سر چاه را جدا می‌سنجیم. با tokenLogo سالم، این خط
               هرگز اجرا نمی‌شود و برداشتنش هیچ تستی را نمی‌انداخت — یعنی
               نگهبانی داشتیم که هیچ چیزی ثابت نمی‌کرد. اینجا tokenLogo را
               موقتاً بی‌اثر می‌کنیم تا خودِ paintAvatar سنجیده شود. */
            const realTokenLogo = tokenLogo;
            tokenLogo = async () => "data:image/png;base64,iVBORw0KGgo=";
            const box3 = document.createElement("div");
            paintAvatar(box3, tok);
            await new Promise(r => setTimeout(r, 60));
            out.sinkGuard = (box3.querySelector("img") || {}).src || null;
            tokenLogo = realTokenLogo;

            window.fetch = realFetch;
            localStorage.removeItem(LS_LOGO); localStorage.removeItem(LS_POOL);
            reset();
            return out;
        }""")
        print("[logo cache] first=%s hit(s)=%s | after a refresh=%s hit(s)=%s | pool hits=%s"
              % (logo["first"], logo["firstHits"], logo["second"],
                 logo["secondHits"], logo["poolHits"]))
        assert logo["first"] == "https://assets.example/token.png", \
            "the logo did not come back on the first ask: %s" % logo["first"]
        assert logo["secondHits"] == 0 and logo["second"] == logo["first"], \
            ("a refresh asked for the logo again (%s network calls) — this is exactly what "
             "burns the 30-per-minute budget" % logo["secondHits"])
        assert logo["pool1"] == "0xPOOL" and logo["pool2"] == "0xPOOL", \
            "the top pool id changed across a refresh: %s then %s" % (logo["pool1"], logo["pool2"])
        assert logo["poolHits"] == [1, 0], \
            "the pool id was fetched again after a refresh: %s" % logo["poolHits"]
        print("[logo cache] poisoned store -> logo=%s (%s call), pool=%s | expired -> %s (%s call)"
              % (logo["poisoned"], logo["poisonHits"], logo["poisonedPool"],
                 logo["expired"], logo["expiredHits"]))
        assert logo["poisoned"] == "https://assets.example/token.png", \
            ("a javascript: url from localStorage came back as a logo and would have gone "
             "straight into img.src: %s" % logo["poisoned"])
        assert logo["poisonHits"] >= 1, "the poisoned entry was refused but nothing was refetched"
        assert logo["poisonedPool"] == "0xPOOL", \
            "a poisoned pool id was trusted: %s" % logo["poisonedPool"]
        assert logo["expired"] == "https://assets.example/token.png" and logo["expiredHits"] >= 1, \
            "an expired logo entry was served instead of being refreshed: %s" % logo["expired"]
        print("[logo cache] 'no logo' -> kept %s call when fresh, %s call when 2h old | "
              "data: url shown=%s stored=%s"
              % (logo["freshNoneHits"], logo["staleNoneHits"],
                 str(logo["dataUrl"])[:24], logo["dataStored"]))
        assert logo["freshNoneHits"] == 0 and logo["freshNone"] is None, \
            "a fresh 'this token has no logo' answer was asked for again: %s" % logo["freshNoneHits"]
        assert logo["staleNoneHits"] >= 1, \
            ("a 'no logo' answer older than an hour was reused — a transient gap in the "
             "response must not turn into 'this token has no logo' for a week")
        # ⚠️ این قاعده در ۱۸ آگوست ۲۰۲۶ سخت‌تر شد و انتظار این تست عوض شد.
        # قبلاً نمایش هرچه سرویس می‌داد آزاد بود و فقط ذخیره به https محدود
        # بود — یعنی مسیر رندر، همان مسیری که یک نفوذ در سرویس قیمت اول از
        # همه به آن می‌رسد، شل‌ترینِ دو مسیر بود. حالا هر دو یک قاعده دارند.
        # ماک اینجا واقعیت را آینه نمی‌کند: در هارنس image_url یک data: url است
        # در حالی که GeckoTerminal واقعی https می‌دهد — و همین باعث شد این
        # حالت اصلاً قابل سنجش باشد.
        print("[logo cache] service data: url -> shown=%s | our ETH icon -> ours=%s src=%s"
              % (logo["dataUrl"], logo["ethIsOurs"], str(logo["ethImgSrc"])[:22]))
        assert logo["dataUrl"] is None, \
            ("a data: logo from the price service reached the display path — img.src must be "
             "held to the same https-only rule as localStorage: %s" % logo["dataUrl"])
        assert logo["dataImgSrc"] is None, \
            ("paintAvatar put a non-https url into img.src: %s" % logo["dataImgSrc"])
        assert logo["sinkGuard"] is None, \
            ("paintAvatar accepted a non-https url handed straight to it — the render sink "
             "must hold the line even when whatever feeds it does not: %s" % logo["sinkGuard"])
        assert not logo["dataStored"] or "data:" not in logo["dataStored"], \
            ("a data: url was written into localStorage — only https urls are safe to read "
             "back into img.src: %s" % logo["dataStored"])
        # و آیکون خودمان قربانی این سخت‌گیری نشده باشد
        assert logo["ethIsOurs"] and logo["ethImgSrc"] and \
               logo["ethImgSrc"].startswith("data:image/svg+xml"), \
            ("tightening the display path also killed our own built-in ETH icon: %s"
             % logo["ethImgSrc"])

        # ---- 2b-ter. the action button must not move between pairs ----
        # اعلان‌ها بین جدول و دکمه بودند و ارتفاعشان به جفت توکن بستگی دارد،
        # پس دکمه با هر تعویض توکن تا ۷۸ پیکسل بالا و پایین می‌پرید — درست
        # همان لحظه‌ای که کاربر می‌خواهد کلیک کند.
        tops = {}
        # ⚠️ نه `a, b` — `b` نام مرورگر است و سایه‌انداختن رویش قبلاً
        #    await b.close() را در انتهای تست ترکانده بود.
        for sIn, sOut in [("USDC", "WETH"), ("ETH", "USDC"),
                          ("cbBTC", "DAI"), ("USDC", "AERO")]:
            await pg.evaluate("""([i, o]) => {
                tokenIn = allTokens().find(t => t.symbol === i);
                tokenOut = allTokens().find(t => t.symbol === o);
                paintToken("in", tokenIn); paintToken("out", tokenOut);
                loadChart(); runScan(tokenOut);
            }""", [sIn, sOut])
            await pg.fill("#amtIn", "1")
            await pg.wait_for_timeout(3200)
            tops[f"{sIn}->{sOut}"] = await pg.evaluate("""() => {
                const r = document.getElementById("actBtn").getBoundingClientRect();
                const n = document.getElementById("notices").getBoundingClientRect();
                return {top: Math.round(r.top), notice: Math.round(n.height)};
            }""")
        for k, v in tops.items():
            print("[cta %s] top=%s (notice height %s)" % (k, v["top"], v["notice"]))
        uniq = {v["top"] for v in tops.values()}
        assert len(uniq) == 1, \
            ("the swap button jumps between pairs: %s — anything whose height depends on the "
             "pair must sit below it, not above" % tops)
        assert any(v["notice"] > 0 for v in tops.values()), \
            "the probe is toothless: no pair produced a notice, so nothing was actually tested"

        # ---- 2b-bis. clear button, header layout, token stats ----
        clr = await pg.evaluate("""async () => {
            const inp = document.getElementById("amtIn"),
                  btn = document.getElementById("amtClear");
            const hid = () => btn.hidden || getComputedStyle(btn).display === "none";
            // فیلد از کاوشگرهای قبلی مقدار دارد؛ اول واقعاً خالی‌اش کن
            inp.value = ""; inp.dispatchEvent(new Event("input"));
            await new Promise(r => setTimeout(r, 200));
            const empty = hid();
            inp.value = "12.5"; inp.dispatchEvent(new Event("input"));
            await new Promise(r => setTimeout(r, 200));
            const typed = hid();
            btn.click();
            await new Promise(r => setTimeout(r, 200));
            return {whenEmpty: empty, whenTyped: typed,
                    afterClick: hid(), value: inp.value, out: document.getElementById("amtOut").value};
        }""")
        print("[clear btn] empty=hidden:%s typed=hidden:%s afterClick=hidden:%s value=%r"
              % (clr["whenEmpty"], clr["whenTyped"], clr["afterClick"], clr["value"]))
        assert clr["whenEmpty"], "the clear button must not sit on an empty field"
        assert not clr["whenTyped"], "the clear button must appear once an amount is typed"
        assert clr["value"] == "" and clr["out"] == "", \
            "clearing must empty both sides, not just the one you typed in"
        assert clr["afterClick"], "the clear button must disappear again after clearing"

        # ---- مبلغ نباید از رفرش جان سالم به در ببرد ----
        # مبلغ در localStorage ذخیره می‌شد و پس از رفرش دوباره در فیلد
        # می‌نشست — ولی بدون اینکه کوتی راه بیفتد، چون بازگردانی برنامه‌ای
        # رویداد `input` تولید نمی‌کند. نتیجه: دکمه روی «Finding best route…»
        # قفل می‌ماند تا کاربر خودش عدد را پاک کند و از نو بزند.
        # جفت توکن باید بماند (کمک است)، مبلغ نه (تصمیم همان لحظه است).
        rf = await b.new_page(viewport={"width": 1240, "height": 1000}, color_scheme="dark")
        await rf.goto(URL); await rf.wait_for_timeout(1200)
        await rf.evaluate("""() => {
            tokenIn = allTokens().find(t => t.symbol === "USDC");
            tokenOut = allTokens().find(t => t.symbol === "WETH");
            paintToken("in", tokenIn); paintToken("out", tokenOut); savePair();
        }""")
        await rf.fill("#amtIn", "5")
        await rf.dispatch_event("#amtIn", "input")
        await rf.wait_for_timeout(1600)
        typed = await rf.evaluate("""() => ({
            amt: document.getElementById("amtIn").value, plan: !!currentPlan,
            stored: localStorage.getItem("zaexa.pair")})""")
        await rf.reload(); await rf.wait_for_timeout(2600)
        after = await rf.evaluate("""() => ({
            amt: document.getElementById("amtIn").value,
            out: document.getElementById("amtOut").value,
            pair: document.getElementById("tokInSym").textContent + "/"
                + document.getElementById("tokOutSym").textContent})""")
        await rf.close()
        print("[refresh] typed=%r quoted=%s stored=%s -> after reload amt=%r pair=%s"
              % (typed["amt"], typed["plan"], typed["stored"], after["amt"], after["pair"]))
        assert typed["plan"], "the typed amount never produced a quote — probe is not testing anything"
        assert "amt" not in (typed["stored"] or ""), \
            ("the amount is still being written to localStorage (%s) — that is what came back "
             "after a refresh without a quote behind it" % typed["stored"])
        assert after["amt"] == "" and after["out"] == "", \
            ("the amount survived a refresh (%r): it comes back without a quote, so the button "
             "sits on 'Finding best route' until the field is retyped" % after["amt"])
        assert after["pair"] == "USDC/WETH", \
            ("the token pair should still be remembered across a refresh, only the amount is "
             "dropped: %s" % after["pair"])

        # هدر: ناوبری باید *وسطِ خودِ هدر* بماند — نه وسطِ فاصله‌ی باقی‌مانده.
        # ⚠️ ۲۹ اوت: این ادعا عوض شد چون *خواسته* عوض شد. قبلاً ناوبری کنار
        # لوگو می‌نشست (یک گروه در چپ) و یک فاصله‌ی کشسان همه‌ی فضای اضافه را
        # سمت راست جمع می‌کرد — یعنی ناوبری هرچه لوگو یا خوشه‌ی راست پهن‌تر یا
        # باریک‌تر می‌شد، جابه‌جا می‌شد. کاربر گفت ناوبری باید واقعاً وسط باشد،
        # فارغ از پهنای آن دو. با `grid-template-columns:1fr auto 1fr` این
        # تضمین ساختاری است، نه تصادفی: ستون میانی همیشه بین دو ستونِ هم‌اندازه
        # می‌نشیند. سنجه هم به همین اندازه ساده شد: مرکز ناوبری باید عملاً
        # مرکز هدر باشد.
        head = await pg.evaluate("""() => {
            const h = document.querySelector("header").getBoundingClientRect();
            const nav = document.getElementById("nav").getBoundingClientRect();
            return {navCenter: Math.round(nav.left + nav.width / 2),
                    hdrCenter: Math.round(h.left + h.width / 2),
                    navLeft: Math.round(nav.left), navRight: Math.round(nav.right),
                    vw: innerWidth};
        }""")
        print("[header] nav center=%s header center=%s  (nav %s..%s of %s)"
              % (head["navCenter"], head["hdrCenter"], head["navLeft"], head["navRight"], head["vw"]))
        assert abs(head["navCenter"] - head["hdrCenter"]) <= 2, \
            ("the nav is not centred in the header: nav center=%s header center=%s (%spx off) — "
             "grid-template-columns:1fr auto 1fr should keep it centred no matter how wide the "
             "logo or the right-hand cluster are" % (head["navCenter"], head["hdrCenter"],
                                                       abs(head["navCenter"] - head["hdrCenter"])))

        # هدر باید تمام‌عرضِ پنجره باشد.
        # ⚠️ ادعای این کاوشگر ۲۳ آگوست عوض شد چون *خواسته* عوض شد، نه چون
        # قرمز شده بود: قبلاً می‌سنجید که هدر دقیقاً هم‌عرض `main` است (۱۱۴۰
        # وسط صفحه)، و حسام گفت روی نمایشگر پهن شبیه ستون یک وبلاگ می‌شود.
        # ولی خطری که آن ادعا جلویش را می‌گرفت هنوز سر جایش است: `body` یک
        # ستون فلکس است و `margin:0 auto` کشیدگی محور عرضی را خنثی می‌کند، پس
        # هدر بدون `width:100%` به اندازه‌ی محتوای خودش جمع می‌شود (۷۸۵ در
        # برابر ۱۲۴۰). همان خطر، سنجه‌ی تازه: لبه تا لبه‌ی پنجره.
        align = await pg.evaluate("""() => {
            const h = document.querySelector("header").getBoundingClientRect();
            const m = document.querySelector("main").getBoundingClientRect();
            const cs = getComputedStyle(document.querySelector("header"));
            return {hl: Math.round(h.left), hr: Math.round(h.right),
                    ml: Math.round(m.left), mr: Math.round(m.right),
                    // ۱۱ اکتبر: با html{scrollbar-gutter:stable} عرضِ قابل‌استفاده‌ی صفحه عرضِ <body> است (شیارِ اسکرول‌بار کنارش رزرو می‌ماند و
                    // هم innerWidth هم clientWidth آن را شامل می‌شوند)؛ خطری که کاوشگر می‌گیرد (هدر به اندازه‌ی محتوای خودش جمع شود) با همین مرجع
                    // هم دقیقاً همان‌قدر قرمز می‌شود
                    vw: Math.round(document.body.getBoundingClientRect().right),
                    surface: cs.backgroundColor, rule: cs.borderBottomWidth,
                    ruleColor: cs.borderBottomColor};
        }""")
        print("[header width] header %s..%s of %s (main %s..%s) surface=%s rule=%s"
              % (align["hl"], align["hr"], align["vw"], align["ml"], align["mr"],
                 align["surface"], align["rule"]))
        assert align["hl"] <= 0 and align["hr"] >= align["vw"], \
            ("the header no longer spans the window: it runs %s..%s of %s — without "
             "width:100%% a flex-column body shrinks it to its own content"
             % (align["hl"], align["hr"], align["vw"]))
        assert align["hr"] - align["hl"] > align["mr"] - align["ml"], \
            "the header is not wider than the cards below it, so it still reads as a column"
        # ۲۹ اوت: کاربر دیگر یک «نوار» بالای صفحه نمی‌خواست — فقط تمام‌عرض‌
        # بودن و خودِ محتوا (لوگو، ناوبری، چیپ‌ها) شناور روی زمینه‌ی صفحه.
        # پس نیمه‌ی «باید سطح/خط داشته باشد» این کاوشگر برداشته شد — دیگر
        # چیزی برای سنجیدن نیست، نبودشان دیگر نقص نیست، خواسته است.
        # ولی خطرِ زیربنایی که آن نیمه واقعاً جلویش را می‌گرفت چیز دیگری بود:
        # همین‌که هدر لبه‌به‌لبه بماند و هیچ‌کدام از دو تغییر بی‌صدا خنثی
        # نشوند. برای همین همان ادعای «تمام‌عرض و پهن‌تر از کارت‌ها» بالا
        # دست‌نخورده ماند و اینجا فقط یک چیز دیگر اضافه شده: ارتفاعِ هدر باید
        # با حذفِ سطح/خط عوض نشود — وگرنه هرچه زیرِ هدر است بی‌صدا یک پیکسل
        # جابه‌جا می‌شود و فاصله‌ی تازه‌ی ۳۰ پیکسلیِ کارت‌ها دیگر دقیقاً ۳۰
        # نیست. به‌همین‌خاطر خطِ زیرین کاملاً حذف نشد، فقط رنگش شفاف شد.
        assert align["surface"] in ("rgba(0, 0, 0, 0)", "transparent"), \
            ("the header still paints its own surface (%s) — it should float on the page "
             "background now, not read as a separate bar" % align["surface"])
        assert align["ruleColor"] in ("rgba(0, 0, 0, 0)", "transparent"), \
            "the bottom rule is still visible (%s) — it should be gone, not just faint" \
            % align["ruleColor"]
        # ⚠️ خودِ خط عمداً به‌جای حذف کامل، فقط بی‌رنگ شد: با
        # `box-sizing:border-box` یک پیکسلِ کادر جزوِ ارتفاعِ جعبه است. اگر
        # کاملاً حذف می‌شد هدر یک پیکسل کوتاه‌تر می‌شد و هرچه زیرش است — از
        # جمله فاصله‌ی تازه‌ی ۳۰ پیکسلیِ کارت‌ها — بی‌صدا یک پیکسل جابه‌جا
        # می‌شد و دیگر دقیقاً ۳۰ نبود. اینجا رابطه سنجیده می‌شود نه یک عددِ
        # مطلق: پهنای کادر باید همچنان چیزی غیرصفر باشد (فقط رنگش شفاف است)،
        # وگرنه یعنی کسی کادر را کامل حذف کرده و آن یک پیکسل دوباره گم شد.
        assert float(align["rule"].replace("px", "")) > 0, \
            ("the bottom border was removed outright (width=%s) instead of only being made "
             "transparent — that quietly shrinks the header by that many pixels and shifts "
             "everything below it" % align["rule"])

        # ---- 2c-bis. Bug 1 رگرسیون: وردمارک باید هم‌قدِ نشان بماند، نه درشت‌تر ----
        # نشان (glyph) و وردمارک دو viewBox با نسبتِ تصویریِ متفاوت دارند؛
        # اندازه‌ی CSS باید طوری تنظیم شود که «قدِ جوهر» دو طرف نزدیک هم بماند
        # (هدف ۰.۴۸ — این کامنت تا ۳۰ آگوست ۲۰۲۶ هنوز ۰.۶ می‌گفت، در حالی که
        # خودِ assert پایین‌تر درست بود؛ کامنتی که دروغ می‌گوید بدتر از کامنت
        # نداشتن است) و مرکزِ عمودیِ دو طرف عوض نشود. این روی صفحه‌ی *واقعی*
        # (نه هارنس) و در ۱۴۴۰×۹۰۰ سنجیده می‌شود، چون خودِ گزارش دقیقاً همین
        # سند و همین اندازه را اندازه گرفته بود.
        logopg = await b.new_page(viewport={"width": 1440, "height": 900})
        await logopg.goto("file://" + os.path.join(HERE, "..", "index.html"))
        await logopg.wait_for_timeout(700)
        logo = await logopg.evaluate("""() => {
            const mark = document.querySelector(".logo .glyph .mark").getBoundingClientRect();
            const word = document.querySelector(".logo .wordmark").getBoundingClientRect();
            const hdr = document.querySelector("header").getBoundingClientRect();
            return {markH: mark.height, wordH: word.height,
                    markCenter: mark.top + mark.height / 2,
                    wordCenter: word.top + word.height / 2,
                    hdrH: hdr.height};
        }""")
        await logopg.close()
        ratio = logo["wordH"] / logo["markH"]
        center_gap = abs(logo["markCenter"] - logo["wordCenter"])
        print("[header] wordmark is not oversized: mark=%.1fpx word=%.1fpx ratio=%.2f "
              "centers %.1f/%.1f headerH=%.1f"
              % (logo["markH"], logo["wordH"], ratio, logo["markCenter"], logo["wordCenter"],
                 logo["hdrH"]))
        # قاعده‌ی برند عوض شد: نسبتِ قدِ جوهرِ وردمارک به نشان دیگر ۰.۶۰ نیست،
        # ۰.۴۸ است (وردمارکِ کوچک‌تر، کنار نشانِ هم‌اندازه‌ی قبلی). باند هنوز
        # باریک است تا اگر کسی نسخه‌ی قدیمی (۰.۶۰) را برگرداند همچنان رد شود.
        assert 0.465 <= ratio <= 0.495, (
            "the wordmark's ink height is no longer sized to the mark's: ratio=%.3f (want "
            "0.465-0.495, target 0.48) — mark=%.1fpx word=%.1fpx" % (ratio, logo["markH"], logo["wordH"]))
        assert center_gap <= 1.5, (
            "resizing the wordmark moved it out of vertical alignment with the mark: "
            "%.2fpx apart" % center_gap)

        # ---- [pairs nav] «New pairs» در ناوبریِ بالای خودِ اپ — یک <a> به
        # صفحه‌ی جداگانه‌ی /pairs، نه یک نما — پس هرگز data-view نمی‌گیرد و
        # setView (که فقط [data-view] را می‌بیند) هرگز کلاسِ .on را رویش
        # نمی‌گذارد. صفحه‌ی جداگانه‌ای برای این کاوشگرها، تا حالتِ pg
        # (نما/مقدار/اسکرول) که بقیه‌ی فایل رویش حساب می‌کند دست‌نخورده بماند. ----
        navpairspg = await b.new_page(viewport={"width": 1280, "height": 900})
        await navpairspg.goto(URL)
        await navpairspg.wait_for_timeout(700)
        # ۱۸ اکتبر: «New pairs» دیگر در نوار یا منو نیست؛ لینکش سوییچِ بالای نمای Flow است. اینجا فقط می‌سنجیم که
        # هیچ لینکِ /pairs در #nav نمانده و تبِ Markets (بدونِ data-view) دیده می‌شود و نوار وسط می‌ماند.
        info = await navpairspg.evaluate("""() => {
            const nav = document.getElementById("nav");
            const links = [...nav.querySelectorAll('a[href="/pairs"]')];
            const mk = document.getElementById("navMarkets");
            const r = mk.getBoundingClientRect();
            const h = nav.getBoundingClientRect();
            const hdr = document.querySelector("header").getBoundingClientRect();
            return {
                count: links.length,
                text: mk.querySelector("span").textContent.trim(),
                hasDataView: mk.hasAttribute("data-view"),
                visible: r.width > 0 && r.height > 0,
                navCenter: Math.round(h.left + h.width / 2),
                hdrCenter: Math.round(hdr.left + hdr.width / 2),
                sw: [...document.querySelectorAll('.view.on a[href="/pairs"], #view-flow a[href="/pairs"]')].map(a => a.textContent.trim()),
            };
        }""")
        print("[pairs nav] navLinks=%s markets=%r hasDataView=%s visible=%s navCenter=%s "
              "hdrCenter=%s switchLinks=%s (1280px)"
              % (info["count"], info["text"], info["hasDataView"], info["visible"],
                 info["navCenter"], info["hdrCenter"], info["sw"]))
        assert info["count"] == 0, (
            "#nav must hold no a[href=\"/pairs\"] any more (New pairs lives in the page switch), found %s" % info["count"])
        assert info["text"] == "Markets", (
            "the Markets tab's label is wrong: %r" % info["text"])
        assert info["sw"] == ["New pairs"], (
            "the Flow view's switch must hold exactly one New pairs link: %r" % info["sw"])
        assert info["hasDataView"] is False, (
            "the Markets tab must never carry data-view — it picks Flow or /pairs from the stored choice, "
            "and must stay invisible to setView/[data-view]")
        assert info["visible"], "the Markets tab is not visible at 1280px"
        assert abs(info["navCenter"] - info["hdrCenter"]) <= 2, (
            "the nav is off-center at 1280px: nav=%s header=%s"
            % (info["navCenter"], info["hdrCenter"]))

        await navpairspg.keyboard.press("Escape")
        # موبایل: نوارِ پایینِ ثابت باید چهار آیتم (Swap، Markets، Stocks، Exit Report — از ۷ اکتبر) را بدونِ اسکرولِ افقی جا بدهد.
        for w in (390, 360):
            await navpairspg.set_viewport_size({"width": w, "height": 844})
            await navpairspg.wait_for_timeout(200)
            mobinfo = await navpairspg.evaluate("""() => ({
                count: document.querySelectorAll("#nav > *").length,
                scrollW: document.documentElement.scrollWidth,
                innerW: innerWidth,
                widths: [...document.querySelectorAll("#nav > *")].map(
                    el => Math.round(el.getBoundingClientRect().width)),
            })""")
            print("[pairs nav] mobile %spx: items=%s scrollWidth=%s innerWidth=%s widths=%s"
                  % (w, mobinfo["count"], mobinfo["scrollW"], mobinfo["innerW"], mobinfo["widths"]))
            assert mobinfo["count"] == 4, (
                "expected 4 items in the bottom nav at %spx, found %s" % (w, mobinfo["count"]))
            # هر چهار آیتم باید flex:1 مشترک داشته باشند — یعنی پهنای تقریباً
            # برابر، نه اینکه یکی به‌اندازه‌ی محتوایش جمع شود و بقیه بی‌قاعده جمع/باز شوند.
            assert max(mobinfo["widths"]) - min(mobinfo["widths"]) <= 4, (
                "the 4 bottom-nav items are not sharing width equally at %spx (widths=%s) — "
                "Markets/Stocks are not getting the same flex:1 as Swap and Exit Report"
                % (w, mobinfo["widths"]))
            assert mobinfo["scrollW"] <= mobinfo["innerW"], (
                "the page scrolls horizontally at %spx (%s > %s) — the 4-item bottom nav does "
                "not fit" % (w, mobinfo["scrollW"], mobinfo["innerW"]))

        # ۸۰۰px — باندِ فقط-آیکون: برچسبِ لینک هم باید مثل دکمه‌ها مخفی شود.
        await navpairspg.set_viewport_size({"width": 800, "height": 900})
        await navpairspg.wait_for_timeout(200)
        band = await navpairspg.evaluate("""() => {
            const linkSpan = document.querySelector('#nav a[href="/report"] span');
            const btnSpan = document.querySelector('#nav button span');
            return {
                linkSpanDisplay: linkSpan ? getComputedStyle(linkSpan).display : null,
                btnSpanDisplay: btnSpan ? getComputedStyle(btnSpan).display : null,
            };
        }""")
        print("[pairs nav] 800px icon-only band: link span display=%s button span display=%s"
              % (band["linkSpanDisplay"], band["btnSpanDisplay"]))
        assert band["linkSpanDisplay"] == "none", (
            "the Exit Report link's label is not hidden in the 721-960px icon-only band: %s"
            % band["linkSpanDisplay"])
        assert band["linkSpanDisplay"] == band["btnSpanDisplay"], (
            "the Exit Report link's label visibility (%s) does not match the buttons' (%s) at "
            "800px" % (band["linkSpanDisplay"], band["btnSpanDisplay"]))

        # کلیک روی دکمه‌ها هنوز نما را عوض می‌کند (کاوشگرهای قدیمی جای دیگر همین را می‌سنجند).
        # ۱۸ اکتبر (تغییر عمدی): لینکِ /pairs در نوار نیست؛ به‌جایش می‌سنجیم که تبِ Markets فقط در نمای flow «روشن» است
        # و هیچ <a href="/pairs"> هرگز به #nav برنمی‌گردد.
        await navpairspg.set_viewport_size({"width": 1280, "height": 900})
        await navpairspg.wait_for_timeout(200)
        clicks = {}
        for i, v in enumerate(("swap", "folio", "flow", "swap")):
            await go_view(navpairspg, v)
            await navpairspg.wait_for_timeout(300)
            clicks["%s#%d" % (v, i)] = await navpairspg.evaluate(
                """() => [document.getElementById('navMarkets').classList.contains('on'), document.querySelectorAll('#nav a[href="/pairs"]').length]""")
        print("[pairs nav] Markets selected / /pairs links in the bar across view switches: %s" % clicks)
        assert clicks == {"swap#0": [False, 0], "folio#1": [False, 0], "flow#2": [True, 0], "swap#3": [False, 0]}, (
            "Markets must be selected only on the flow view and the bar must never hold a /pairs link: %s" % clicks)
        await navpairspg.close()

        # ---- [nav markets] ۱۸ اکتبر — نوار: Swap · Markets · Stocks · Exit Report؛ «Markets» تبِ ساده است (بدونِ منو و شورون).
        # قبلاً بازشو بودنِ منو (باز/بسته‌شدن با کلیک، Escape، mousedownِ بیرون، جای منو، ردیف‌های Flow/New pairs) سنجیده می‌شد؛
        # همه‌ی آن‌ها عمداً برداشته شد چون منو وجود ندارد. رفتارِ کلیک و سوییچ در [markets switch] سنجیده می‌شود.
        # اپ در ۱۴۴۰ و ۳۹۰ و هر دو تم؛ /pairs در ۱۴۴۰. ----
        NM_ORDER_JS = """() => [...document.querySelectorAll('#nav > *')].map(e => (e.querySelector('span') || e).textContent.trim())"""
        NM_STATE_JS = """() => {
            const bt = document.getElementById('navMarkets'), bs = getComputedStyle(bt);
            return {on: bt.classList.contains('on'), btnShadow: bs.boxShadow, tag: bt.tagName, type: bt.getAttribute('type'), title: bt.getAttribute('title'),
                    haspopup: bt.getAttribute('aria-haspopup'), expanded: bt.getAttribute('aria-expanded'), view: bt.dataset.view || null,
                    menu: document.querySelectorAll('#navMenu, .navChev, .navMenuWrap').length, label: bt.querySelector('span').textContent.trim()};
        }"""
        # ۷ اکتبر (تغییر عمدی): Stocks دیگر span بی‌جانِ «Soon» نیست؛ تبِ واقعی است. این کمکی همان اطلاعاتِ تب را می‌خواند:
        # در اپ <button data-view="stocks">، در /pairs <a href="/app#stocks">؛ هر دو فوکوس‌پذیر و بدونِ هیچ نشانِ Soon.
        NM_STOCKS_JS = """() => { const s = document.querySelector('#nav [title="Stocks"]'); s.focus();
            return {tag: s.tagName, view: s.dataset.view || null, href: s.getAttribute('href'), disabled: s.getAttribute('aria-disabled'),
                    focused: document.activeElement === s, cursor: getComputedStyle(s).cursor,
                    pill: !!document.querySelector('#nav .soonPill, #nav .navSoon'), label: s.textContent.trim(),
                    inTabOrder: s.matches('a[href],button,[tabindex]:not([tabindex="-1"])')}; }"""
        nm_runs = 0
        for nm_vw, nm_scheme in ((1440, "light"), (1440, "dark"), (390, "light"), (390, "dark")):
            nm_ctx = "[nav markets] app@%d/%s" % (nm_vw, nm_scheme)
            nm_errs = []
            nm = await b.new_page(viewport={"width": nm_vw, "height": 900 if nm_vw > 500 else 844},
                                  color_scheme=nm_scheme, device_scale_factor=1.5)
            nm.on("pageerror", lambda e, _l=nm_errs: _l.append(str(e)))
            await nm.goto(URL)
            await nm.wait_for_timeout(800)
            assert await nm.evaluate(NM_ORDER_JS) == ["Swap", "Markets", "Stocks", "Exit Report"], \
                "%s: bar order is %s" % (nm_ctx, await nm.evaluate(NM_ORDER_JS))
            assert await nm.locator('#nav [data-view="folio"]').count() == 0, "%s: Portfolio must not be a tab any more" % nm_ctx
            st0 = await nm.evaluate(NM_STATE_JS)
            assert st0["menu"] == 0 and st0["haspopup"] is None and st0["expanded"] is None and not st0["on"] and st0["view"] is None \
                and st0["tag"] == "BUTTON" and st0["type"] == "button" and st0["label"] == "Markets" and st0["title"] == "Markets", \
                "%s: Markets must be a plain, unselected tab (no menu/chevron/aria-haspopup, no data-view): %s" % (nm_ctx, st0)
            stk = await nm.evaluate(NM_STOCKS_JS)
            assert stk["tag"] == "BUTTON" and stk["view"] == "stocks" and stk["disabled"] is None and stk["focused"] and stk["inTabOrder"] \
                and not stk["pill"] and stk["cursor"] != "default", "%s: Stocks must be a live, focusable tab (button data-view=stocks) with no Soon pill: %s" % (nm_ctx, stk)
            # با انتخابِ ذخیره‌شده‌ی flow کلیکِ Markets نمای Flow را درجا باز می‌کند و تب «روشن» می‌شود
            await nm.evaluate("() => localStorage.setItem('zaexa.markets.v1', 'flow')")
            await nm.click("#navMarkets"); await nm.wait_for_timeout(500)
            fl = await nm.evaluate(NM_STATE_JS)
            assert await nm.evaluate("() => document.getElementById('view-flow').classList.contains('on')"), "%s: Markets (stored flow) did not switch to the Flow view" % nm_ctx
            assert fl["on"] and "inset" in fl["btnShadow"], "%s: Markets must wear the selected-tab look on the flow view: %s" % (nm_ctx, fl)
            assert await nm.evaluate("() => document.querySelector('#nav button[data-view=\"swap\"]').classList.contains('on')") is False, "%s: Swap must not stay selected" % nm_ctx
            await go_view(nm, "swap"); await nm.wait_for_timeout(300)
            assert (await nm.evaluate(NM_STATE_JS))["on"] is False, "%s: Markets stays selected after leaving flow" % nm_ctx
            assert not nm_errs, "%s: page errors: %s" % (nm_ctx, nm_errs)
            await nm.close()
            nm_runs += 1
        # /pairs در ۱۴۴۰ — هر دو تم
        for nm_scheme in ("light", "dark"):
            nm_ctx = "[nav markets] pairs@1440/%s" % nm_scheme
            nm_errs = []
            nm = await b.new_page(viewport={"width": 1440, "height": 900}, color_scheme=nm_scheme)
            nm.on("pageerror", lambda e, _l=nm_errs: _l.append(str(e)))
            await nm.route("**/*", lambda r: r.continue_() if r.request.url.startswith("file:") else r.abort())
            await nm.goto("file://" + os.path.join(HERE, "..", "pairs.html"), wait_until="domcontentloaded")
            await nm.wait_for_timeout(800)
            assert await nm.evaluate(NM_ORDER_JS) == ["Swap", "Markets", "Stocks", "Exit Report"], "%s: bar order is %s" % (nm_ctx, await nm.evaluate(NM_ORDER_JS))
            st = await nm.evaluate(NM_STATE_JS)
            assert st["on"] and "inset" in st["btnShadow"] and st["menu"] == 0 and st["haspopup"] is None and st["expanded"] is None, "%s: Markets must be a selected plain tab on /pairs: %s" % (nm_ctx, st)
            stk = await nm.evaluate(NM_STOCKS_JS)
            assert stk["tag"] == "A" and stk["href"] == "/app#stocks" and stk["disabled"] is None and stk["focused"] and stk["inTabOrder"] and not stk["pill"], "%s: Stocks must be a live link to /app#stocks: %s" % (nm_ctx, stk)
            u0 = nm.url
            await nm.click("#navMarkets"); await nm.wait_for_timeout(250)
            assert nm.url == u0, "%s: clicking Markets on /pairs must do nothing (url %s -> %s)" % (nm_ctx, u0, nm.url)
            assert not nm_errs, "%s: page errors: %s" % (nm_ctx, nm_errs)
            await nm.close()
            nm_runs += 1
        print("[nav markets] bar is exactly Swap, Markets, Stocks, Exit Report; Markets is a plain tab (no menu, chevron, aria-haspopup or data-view), with stored flow it opens the Flow view in place and shows selected, "
              "/pairs shows Markets selected and a click there does nothing, Stocks is a live tab (button in the app, link to /app#stocks on /pairs) with no Soon pill: %d runs (app 1440+390 x light+dark, pairs 1440 x light+dark)" % nm_runs)

        # ---- [wallet portfolio] ۶ اکتبر — «Portfolio» اولین کارِ منوی والت است: در اپ نمای folio را باز می‌کند و منو را می‌بندد؛ در /pairs لینکِ /app#folio است. ----
        wp_errs = []
        wp = await b.new_page(viewport={"width": 1440, "height": 900}, color_scheme="light", device_scale_factor=1.5)
        wp.on("pageerror", lambda e: wp_errs.append(str(e)))
        await wp.goto(URL); await wp.wait_for_timeout(800)
        await wp.evaluate("""() => { account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23"; walletChainId = CHAIN.id; paintWallet(); }""")
        await wp.click("#connectBtn"); await wp.wait_for_timeout(250)
        wp_first = await wp.evaluate("() => [...document.querySelectorAll('#walletPop .walletAction')].map(e => e.id + ':' + e.querySelector('span').textContent.trim())")
        assert wp_first[:3] == ["folioMenuBtn:Portfolio", "copyAddrBtn:Copy address", "disconnectBtn:Disconnect"], "[wallet portfolio] menu order: %s" % wp_first
        assert await wp.evaluate("() => document.getElementById('folioMenuBtn').getAttribute('role')") == "menuitem"
        await wp.screenshot(path="/tmp/nm_wallet.png", clip={"x": 740, "y": 0, "width": 700, "height": 300})
        await wp.click("#folioMenuBtn"); await wp.wait_for_timeout(500)
        wp_after = await wp.evaluate("() => ({folio: document.getElementById('view-folio').classList.contains('on'), popOn: document.getElementById('walletPop').classList.contains('on'), exp: document.getElementById('connectBtn').getAttribute('aria-expanded'), hash: location.hash})")
        assert wp_after == {"folio": True, "popOn": False, "exp": "false", "hash": "#folio"}, "[wallet portfolio] click result: %s" % wp_after
        await wp.close()
        wp = await b.new_page(viewport={"width": 1440, "height": 900})
        wp.on("pageerror", lambda e: wp_errs.append(str(e)))
        await wp.route("**/*", lambda r: r.continue_() if r.request.url.startswith("file:") else r.abort())
        await wp.goto("file://" + os.path.join(HERE, "..", "pairs.html"), wait_until="domcontentloaded"); await wp.wait_for_timeout(800)
        wp_p = await wp.evaluate("() => { const a = [...document.querySelectorAll('#walletPop .walletAction')]; return {ids: a.map(e => e.id), tag: a[0].tagName, href: a[0].getAttribute('href'), role: a[0].getAttribute('role'), txt: a[0].querySelector('span').textContent.trim()}; }")
        assert wp_p["ids"][:3] == ["folioMenuBtn", "copyAddrBtn", "disconnectBtn"] and wp_p["tag"] == "A" and wp_p["href"] == "/app#folio" and wp_p["role"] == "menuitem" and wp_p["txt"] == "Portfolio", "[wallet portfolio] pairs: %s" % wp_p
        await wp.close()
        assert not wp_errs, "[wallet portfolio] page errors: %s" % wp_errs
        print("[wallet portfolio] Portfolio is the first wallet-menu action: in the app it opens the folio view (#folio) and closes the menu; on /pairs it links to /app#folio")

        # کارت سواپ نباید کشیده شود تا هم‌قد نمودار شود — زیر دکمه فضای مرده
        # می‌ماند. ولی ارتفاع نمودار *از همان کشیدگی* تغذیه می‌شود، پس اگر کسی
        # به‌جای کارت، کل ردیف را از کشیدگی خارج کند، نمودار کوتاه می‌شود.
        # هر دو با هم سنجیده می‌شوند، وگرنه رفع یکی دیگری را می‌شکند.
        fit = await pg.evaluate("""async () => {
            const hero = document.querySelector(".row.hero");
            if (getComputedStyle(hero).gridTemplateColumns.split(" ").length < 2) return null;
            const chart = hero.querySelector(".swapChartCard"), swap = hero.querySelector(".swapCard");
            const H = e => Math.round(e.getBoundingClientRect().height);
            const settle = () => new Promise(r =>
                requestAnimationFrame(() => requestAnimationFrame(r)));
            const idle = H(swap);
            setNotice('<div class="note ok">Swap complete. <a href="#">View on BaseScan</a></div>');
            await settle();
            const withNote = H(swap);
            setNotice(""); await settle();
            const back = H(swap);
            return {chart: H(chart), plot: H(document.getElementById("plot")),
                    idle, withNote, back,
                    dead: Math.round(swap.getBoundingClientRect().bottom
                                     - document.getElementById("actBtn")
                                         .getBoundingClientRect().bottom)};
        }""")
        if fit:
            print("[card fit] chart=%s (plot %s) | swap card: idle=%s with a notice=%s back=%s "
                  "| room under the button=%s"
                  % (fit["chart"], fit["plot"], fit["idle"], fit["withNote"], fit["back"],
                     fit["dead"]))
            # این همان چیزی است که کاربر می‌بیند: کارت نباید با آمدن و رفتن
            # اعلان بالا و پایین بپرد. جای اعلان از پیش رزرو شده.
            assert fit["idle"] == fit["withNote"] == fit["back"], \
                ("the swap card changes height when a notice appears (%s -> %s -> %s) — the "
                 "notice slot is meant to be reserved so nothing jumps"
                 % (fit["idle"], fit["withNote"], fit["back"]))
            assert fit["dead"] <= 84, \
                ("%spx under the action button: that is more than the reserved notice slot, so "
                 "the card is being stretched to match the chart again" % fit["dead"])
            assert fit["plot"] >= 300, \
                ("the chart collapsed to %spx: with the row out of stretch the plot has nothing "
                 "to grow into, so it needs its own height. The two go together - taking the "
                 "row out of stretch without giving .plot a height starves the chart."
                 % fit["plot"])

        # نیمه‌ی دومِ کاوشگر [mobile order]: جابه‌جایی ترتیب فقط زیر ۹۴۱ پیکسل
        # است. اگر order به چیدمان دوستونه نشت کند، نمودار می‌رود سمت راست و
        # کل حساب‌های ارتفاعِ بالا بی‌معنا می‌شود.
        desk_order = await pg.evaluate("""() => {
            const c = [...document.querySelectorAll("#baseHeroRow .swapChartCard, #baseHeroRow .swapCard")];
            const swap = c.find(x => x.querySelector("#amtIn"));
            const chart = c.find(x => x.querySelector("#plot"));
            return {chartLeft: Math.round(chart.getBoundingClientRect().left),
                    swapLeft: Math.round(swap.getBoundingClientRect().left)};
        }""")
        print("[desktop order] chart left=%s swap left=%s"
              % (desk_order["chartLeft"], desk_order["swapLeft"]))
        assert desk_order["chartLeft"] < desk_order["swapLeft"], \
            ("the two-column layout flipped: the chart is at %s and the swap card at %s — the "
             "mobile order override has leaked past its media query"
             % (desk_order["chartLeft"], desk_order["swapLeft"]))

        # ارتفاع نمودار نباید به کارت کناری وابسته باشد.
        # با `flex:1` ارتفاع نمودار از ارتفاع ردیف می‌آمد و ارتفاع ردیف از
        # کارت سواپ: نمودار روی بارگذاری ۵۷۲ پیکسل بود و با اولین تعویض توکن
        # روی ۵۱۰ می‌نشست. کاربر یک پرش ۶۲ پیکسلی می‌دید که ربطی به کارش نداشت.
        steady = await pg.evaluate("""async () => {
            const hero = document.querySelector(".row.hero");
            if (getComputedStyle(hero).gridTemplateColumns.split(" ").length < 2) return null;
            const chart = hero.querySelector(".swapChartCard");
            const H = e => Math.round(e.getBoundingClientRect().height);
            const wait = ms => new Promise(r => setTimeout(r, ms));
            const flip = () => { const t = tokenIn; tokenIn = tokenOut; tokenOut = t;
                                 if (typeof loadChart === "function") loadChart(); };
            const onLoad = H(chart);
            flip(); await wait(1300);
            const afterSwitch = H(chart);
            flip(); await wait(1300);
            const back = H(chart);
            /* و ادعای زیربنایی: ارتفاع نمودار نباید *اصلاً* به کارت کناری
               وابسته باشد. کارت سواپ را عمداً بلندتر می‌کنیم؛ اگر نمودار
               دنبالش برود یعنی هنوز از ردیف تغذیه می‌شود و همان پرش با هر
               تغییر محتوای کارت کناری برمی‌گردد. */
            const swap = hero.querySelector(".swapCard");
            const keep = swap.style.minHeight;
            swap.style.minHeight = (H(swap) + 140) + "px";
            await wait(120);
            const whileNeighbourTaller = H(chart);
            swap.style.minHeight = keep;
            await wait(120);
            return {onLoad, afterSwitch, back, whileNeighbourTaller,
                    plot: H(document.getElementById("plot"))};
        }""")
        if steady:
            print("[chart steady] chart height on load=%s after switching tokens=%s back=%s "
                  "(plot %s)" % (steady["onLoad"], steady["afterSwitch"], steady["back"],
                                 steady["plot"]))
            assert steady["onLoad"] == steady["afterSwitch"] == steady["back"], \
                ("the chart card resized when the tokens were switched (%s -> %s -> %s) — its "
                 "height must come from itself, not from whatever the row happens to be"
                 % (steady["onLoad"], steady["afterSwitch"], steady["back"]))
            print("[chart steady] neighbour forced 140px taller -> chart=%s"
                  % steady["whileNeighbourTaller"])
            assert steady["whileNeighbourTaller"] == steady["back"], \
                ("making the swap card taller dragged the chart from %s to %s — the chart is "
                 "still sizing itself from the row, so any change in the card next to it will "
                 "move it again" % (steady["back"], steady["whileNeighbourTaller"]))

        # ---- [card steady] جایگاه ثابتِ وضعیت — نه فضای خالی، نه پرش ----
        # بازخوردِ مالک ۲۴ سپتامبر: نوار مسیر همیشه دیده می‌شود و یک‌خطی/بی‌شکست
        # است (rbLegend nowrap+ellipsis)، پس ارتفاعش با محتوا عوض نمی‌شود؛
        # #statusSlot روی دسکتاپ ارتفاع کف ۶۴ دارد، پس هیچ حالتی (نه بی‌مبلغ،
        # نه کوت‌شده، نه هیچ‌کدام از حالت‌های پیل، نه یک اعلانِ کوتاه) کارت را
        # تکان نمی‌دهد. موبایل ارتفاعِ کف ندارد؛ چون نوار مسیر خودش ثابت است
        # همه‌ی حالت‌ها به‌جز اعلان همچنان باید برابر باشند — فقط اعلان (که
        # شکلی جدا از نوار مسیر دارد) ممکن است ارتفاعِ دیگری بدهد.
        async def card_steady(width):
            sp = await b.new_page(viewport={"width": width, "height": 900}, color_scheme="dark")
            await sp.goto(URL)
            await sp.wait_for_function("() => typeof E !== 'undefined' && !!E", timeout=15000)
            await sp.wait_for_timeout(300)
            data = await sp.evaluate("""() => {
                const swap = document.querySelector("section.card.swapCard");
                const btn = document.getElementById("actBtn");
                const bar = document.getElementById("routeBar");
                const snap = () => ({
                    h: Math.round(swap.getBoundingClientRect().height),
                    top: Math.round(btn.getBoundingClientRect().top),
                    barH: Math.round(bar.getBoundingClientRect().height)
                });
                const out = {};

                setNotice(""); paintSellPill("hidden"); paintRouteIdle();
                out.idle = snap();

                const unit = (t) => 10n ** BigInt(t.decimals);
                const plan1 = {
                    totalIn: 1000n * unit(tokenIn), totalOut: 1000n * unit(tokenOut),
                    impact: 0.2, stats: {rpcFailed: 0, attempted: 1},
                    parts: [{amountIn: 1000n * unit(tokenIn), route: {hops: [
                        {tokenIn, tokenOut, venue: {dex: {kind: KIND.V3, id: "uniswap-v3", name: "Uniswap V3"}, feeTier: 3000}}
                    ]}}]
                };
                renderPlan(plan1);
                out.quoted1 = snap();

                const partAmt = (1000n * unit(tokenIn)) / 3n;
                const longVenue = (n) => ({dex: {kind: KIND.V3, id: "venue" + n,
                    name: "A Very Long Aggregator Venue Name Number " + n}, feeTier: 3000});
                const plan3 = {
                    totalIn: partAmt * 3n, totalOut: 1000n * unit(tokenOut),
                    impact: 0.4, stats: {rpcFailed: 0, attempted: 3},
                    parts: [1, 2, 3].map(n => ({amountIn: partAmt,
                        route: {hops: [{tokenIn, tokenOut, venue: longVenue(n)}]}}))
                };
                renderPlan(plan3);
                out.quoted3 = snap();

                // این سه حالتِ بعدی فقط پیل را عوض می‌کنند — نوار مسیرِ همین
                // کوتِ سه‌پاره‌ای باید سرِ جایش بماند، نه یک اعلانِ باقی‌مانده
                // (renderPlan خودش با impact بالا یک اعلان می‌ساخت؛ اینجا
                // عمداً پاک نگه داشته می‌شود).
                setNotice("");
                paintSellPill("exit", {state: "verified", lossPct: 0.3, recovered: null, reason: null});
                out.pillOk = snap();
                paintSellPill("exit", {state: "estimated", lossPct: 8, recovered: null, reason: null});
                out.pillWarn = snap();
                paintSellPill("exit", {state: "estimated", lossPct: 20, recovered: null, reason: null});
                out.pillNo = snap();
                paintSellPill("exit", {state: "unknown", lossPct: null, recovered: null, reason: null});
                out.pillUnk = snap();

                paintSellPill("hidden");
                setNotice(note("warn", "Just a short one-line notice."));
                out.notice = snap();
                setNotice("");

                // ۲۴ سپتامبر، دورِ سوم: حسام دید کارت در حالتِ «مبلغ در مقصد» (کوتِ
                // معکوس) می‌پرد — #revNote بیرونِ جای ثابت بود. حالا داخلِ آن است.
                renderPlan(plan1, true);
                setNotice("");
                out.reverse = snap();
                setNotice(note("warn", "<b>Price impact 1.94%</b> — the pool moves against you at this size."));
                out.reverseNotice = snap();
                setNotice("");
                renderPlan(plan1);
                setNotice("");
                out.afterReverse = snap();

                return out;
            }""")
            await sp.close()
            return data
        steady_desk = await card_steady(1440)
        steady_mob = await card_steady(390)

        def fmt_states(d):
            return " ".join("%s=h%s/t%s/bar%s" % (k, v["h"], v["top"], v["barH"]) for k, v in d.items())
        print("[card steady] desktop 1440: %s" % fmt_states(steady_desk))
        print("[card steady] mobile 390: %s" % fmt_states(steady_mob))

        desk_h = {k: v["h"] for k, v in steady_desk.items()}
        desk_top = {k: v["top"] for k, v in steady_desk.items()}
        assert max(desk_h.values()) - min(desk_h.values()) <= 1, \
            "desktop 1440: swap card height moves between states: %s" % desk_h
        assert max(desk_top.values()) - min(desk_top.values()) <= 1, \
            "desktop 1440: #actBtn top moves between states: %s" % desk_top

        # ۲۴ سپتامبر: روی گوشی هم رزروِ ۶۰پیکسلی هست، پس حالتِ اعلان هم باید ثابت بماند
        mob_no_notice = dict(steady_mob)
        mob_h = {k: v["h"] for k, v in mob_no_notice.items()}
        mob_top = {k: v["top"] for k, v in mob_no_notice.items()}
        assert max(mob_h.values()) - min(mob_h.values()) <= 1, \
            "mobile 390: swap card height moves between non-notice states: %s" % mob_h
        assert max(mob_top.values()) - min(mob_top.values()) <= 1, \
            "mobile 390: #actBtn top moves between non-notice states: %s" % mob_top

        # ۶۴ پیکسل: کفِ رزروشده‌ی #statusSlot روی دسکتاپ. اگر نوار مسیر از آن
        # بلندتر شود، باید margin-bottom اش صفر شود (بالا) تا از رزرو رد نشود.
        for k, v in steady_desk.items():
            if k != "notice":
                assert v["barH"] <= 64, \
                    "routeBar content is %spx tall in state %r — taller than the 64px slot reserves" % (v["barH"], k)

        # عرض‌های میانی جایی است که هدر معمولاً می‌شکند: ناوبری هنوز در هدر
        # است ولی جا تنگ شده. هیچ چیزی نباید از لبه بزند بیرون یا بپیچد.
        narrow = await b.new_page(viewport={"width": 760, "height": 900}, color_scheme="dark")
        await narrow.goto(URL); await narrow.wait_for_timeout(900)
        hn = await narrow.evaluate("""() => {
            const h = document.querySelector("header");
            const kids = [...h.children].map(e => e.getBoundingClientRect());
            // ⚠️ ارتفاع صفر هم فیلتر می‌شود، نه فقط عرض صفر. دو فاصله‌گذار
            // کشسان هدر عرض دارند ولی چیزی نشان نمی‌دهند.
            // ⚠️ «سطر» با هم‌پوشانیِ عمودی شمرده می‌شود، نه با گِرد‌کردنِ top روی
            // ۱۲. آن گِردکردن یک تقریب بود و وقتی ارتفاعِ نوار عوض شد (۱۴
            // سپتامبر ۲۰۲۶، هم‌ترازیِ لوگو با صفحه‌ی معرفی) دو فرزندِ کاملاً
            // هم‌سطح با اختلافِ یک پیکسل در دو سبد افتادند و پروب یک پیچشِ
            // خیالی گزارش کرد. پیچشِ واقعی یعنی بازه‌ی عمودیِ یک فرزند با
            // بازه‌ی فرزندِ قبلی هیچ هم‌پوشانی نداشته باشد؛ همین سنجیده می‌شود.
            const vis = kids.filter(r => r.width > 0 && r.height > 0)
                            .sort((a, b) => a.top - b.top);
            let rows = 0, edge = -Infinity;
            for (const r of vis) { if (r.top >= edge) { rows++; edge = r.bottom; }
                                   else if (r.bottom > edge) edge = r.bottom; }
            return {right: Math.round(Math.max(...kids.map(r => r.right))),
                    left: Math.round(Math.min(...kids.map(r => r.left))),
                    rows: rows, vw: innerWidth,
                    docW: Math.round(document.documentElement.scrollWidth)};
        }""")
        await narrow.close()
        print("[header 760] left=%s right=%s rows=%s doc=%s viewport=%s"
              % (hn["left"], hn["right"], hn["rows"], hn["docW"], hn["vw"]))
        assert hn["left"] >= 0 and hn["right"] <= hn["vw"] + 1, \
            "the header runs off the edge at 760px: %s" % hn
        assert hn["docW"] <= hn["vw"] + 1, \
            "the page scrolls sideways at 760px — something in the header is too wide: %s" % hn
        assert hn["rows"] == 1, "the header wrapped onto %s rows at 760px" % hn["rows"]

        # آمار توکن خروجی
        stats = await pg.evaluate("""async () => {
            for (let i = 0; i < 40; i++) {
                const b = document.getElementById("tokStats");
                if (!b.hidden && b.children.length) break;
                await new Promise(r => setTimeout(r, 150));
            }
            const b = document.getElementById("tokStats");
            return {hidden: b.hidden,
                    keys: [...b.querySelectorAll(".k")].map(e => e.textContent),
                    vals: [...b.querySelectorAll(".v")].map(e => e.textContent)};
        }""")
        print("[token stats] %s = %s" % (stats["keys"], stats["vals"]))
        assert not stats["hidden"], "the output token's stats never appeared"
        for k in ["Market cap", "FDV", "Volume 24h"]:
            assert k in stats["keys"], "%s is missing from the token stats: %s" % (k, stats["keys"])
        # «هولدرز» عمداً نیست: منبع دادهٔ ما نمی‌دهدش و عدد ساختن بدتر از
        # نداشتن است. اگر روزی اضافه شد، باید از یک منبع واقعی بیاید.
        assert not any("older" in k for k in stats["keys"]), \
            "holders is not available from GeckoTerminal — do not invent it"

        # ---- 2c-quinquies. wallet picker lists every wallet that announces itself ----
        # قبلاً فقط window.ethereum خوانده می‌شد و ما کورکورانه متامسک را ترجیح
        # می‌دادیم؛ با نصب‌بودن ربی و متامسک با هم، کاربر اصلاً حق انتخاب نداشت.
        picker = await pg.evaluate("""async () => {
            const mk = (rdns, name) => ({
              info: {uuid: rdns, name, rdns,
                     icon: "data:image/svg+xml;utf8," + encodeURIComponent(
                       "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 8 8'/>")},
              provider: {__who: name, request: async () => [], on(){}, removeListener(){}}
            });
            const fake = [mk("io.rabby","Rabby"), mk("io.metamask","MetaMask"),
                          mk("io.zerion","Zerion")];
            window.addEventListener("eip6963:requestProvider", () => {
              fake.forEach(w => window.dispatchEvent(
                new CustomEvent("eip6963:announceProvider", {detail: w})));
            });
            const realConnect = connectWithProvider;
            let chosen = null;
            connectWithProvider = async (p) => { chosen = p.__who; };
            openWalletPicker();
            await new Promise(r => setTimeout(r, 120));
            const names = [...document.querySelectorAll("#walList .walName")]
                            .map(e => e.textContent);
            const icons = document.querySelectorAll("#walList img").length;
            // روی ردیف «Zerion» کلیک کن، نه اولی — تا ثابت شود انتخاب کاربر
            // واقعاً همان است که وصل می‌شود، نه هرچه بالای لیست بود.
            const row = [...document.querySelectorAll("#walList .walRow")]
                          .find(r => /Zerion/.test(r.textContent));
            if (row) row.click();   // نبودنش خودش یک شکست است، نه یک استثنا
            await new Promise(r => setTimeout(r, 80));
            const stillOpen = document.getElementById("walletOv")
                                .classList.contains("on");
            connectWithProvider = realConnect;
            return {names, icons, chosen, stillOpen};
        }""")
        print("[wallet picker] %s · icons=%s · clicked -> %s"
              % (picker["names"], picker["icons"], picker["chosen"]))
        for w in ["Rabby", "MetaMask", "Zerion"]:
            assert w in picker["names"], \
                "%s announced itself but is missing from the picker: %s" % (w, picker["names"])
        assert picker["chosen"] == "Zerion", \
            "the picker must connect the wallet the user clicked, not the first one: %r" % picker["chosen"]
        # WalletConnect همیشه در لیست هست — تنها راهِ کیف پول موبایل، و چیزی
        # لازم ندارد نصب شود. پس گزینه‌ها = افزونه‌های کشف‌شده + یک ردیف WC.
        assert "WalletConnect" in picker["names"], \
            "WalletConnect must always be offered, even with extensions installed"
        assert picker["icons"] == len(picker["names"]), \
            "every row must show its own icon, not a letter fallback"
        assert not picker["stillOpen"], "the picker must close once a wallet is chosen"

        # ---- 2c-sexies. the vendored WalletConnect bundle really is self-contained ----
        # نسخه‌ی رسمی UMD خودِ WalletConnect در مرورگر بی‌صدا می‌شکند چون
        # viem/lit/bs58 را از روی صفحه انتظار دارد. ما خودمان بسته‌اش کردیم و
        # این کاوشگر همان ادعا را می‌سنجد: با یک <script> تنها بار شود و
        # EthereumProvider.init واقعاً وجود داشته باشد.
        # روی http سرو می‌شود نه file:// — بسته موقع بار شدن به localStorage
        # دست می‌زند و مبدأ مبهم اجازه نمی‌دهد.
        import functools, http.server, threading
        class Quiet(http.server.SimpleHTTPRequestHandler):
            def log_message(self, *a):     # خروجی تست باید خوانا بماند
                pass
            def translate_path(self, path):
                # آینه‌ی همان قاعده در worker/index.js: /t/<آدرس> صفحه‌ی
                # اصلی را می‌گیرد. اگر آنجا عوض شد، اینجا هم باید عوض شود،
                # وگرنه تست چیزی را می‌سنجد که روی سایت وجود ندارد.
                # ⚠️ شکل حالا هر دو خانواده‌ی آدرس را می‌گیرد — هگزِ Base و
                # base58ِ سولانا (همان بازه‌ی SOL_MINT در worker/chains.js) —
                # چون /t/<mint سولانا> دیگر ۴۰۴ نمی‌گیرد.
                clean = path.split("?")[0]
                if clean in ("/app", "/app/"):
                    return os.path.join(HERE, "harness.html")
                if re.match(r"^/t/(0x[0-9a-fA-F]{40}|[1-9A-HJ-NP-Za-km-z]{32,44})/?$", clean):
                    return os.path.join(HERE, "harness.html")
                # صفحه‌ی توکن یک <base href="/"> می‌گذارد، پس استاب از ریشه
                # خواسته می‌شود. روی سایت واقعی ethers هم دقیقاً کنار
                # index.html در ریشه است، پس این جانشینِ درستِ همان است.
                if clean == "/stub-ethers.js":
                    return os.path.join(HERE, "stub-ethers.js")
                return super().translate_path(path)
        srv = http.server.ThreadingHTTPServer(
            ("127.0.0.1", 0),
            functools.partial(Quiet, directory=os.path.join(HERE, "..")))
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        port = srv.server_address[1]
        wcpg = await b.new_page()
        wc_errs = []
        wcpg.on("pageerror", lambda e: wc_errs.append(str(e)))
        await wcpg.goto("http://127.0.0.1:%d/" % port)
        wc_load = await wcpg.evaluate("""async (wcName) => {
            await new Promise((res, rej) => {
                const s = document.createElement("script");
                s.src = "./" + wcName;
                s.onload = res; s.onerror = () => rej(new Error("script failed"));
                document.head.appendChild(s);
            });
            const W = window.WCProvider;
            return {registered: !!W,
                    hasInit: !!(W && W.EthereumProvider &&
                                typeof W.EthereumProvider.init === "function")};
        }""", os.path.basename(vendor_path("walletconnect.bundle")))
        await wcpg.close()
        print("[walletconnect] bundle loads standalone: registered=%s init=%s errors=%s"
              % (wc_load["registered"], wc_load["hasInit"], len(wc_errs)))
        assert wc_load["registered"] and wc_load["hasInit"], \
            "the WalletConnect bundle did not register a usable EthereumProvider"
        assert not wc_errs, "the WalletConnect bundle threw while loading: %s" % wc_errs[:2]
        # ⚠️ چیزی که این تست *نمی‌سنجد*: خودِ دست‌دادن با رله‌ی WalletConnect.
        #    آن به سرور بیرونی نیاز دارد و آفلاین قابل آزمودن نیست.

        # ---- 2c-septies. Custom RPC ----
        # روی http سرو می‌شود چون file:// مبدأ مبهم دارد و localStorage
        # آنجا اصلاً کار نمی‌کند — یعنی ماندگاری روی file:// قابل آزمودن نیست.
        rpcpg = await b.new_page()
        await rpcpg.goto("http://127.0.0.1:%d/test/harness.html?rpc=https://evil.example" % port)
        await rpcpg.wait_for_timeout(1200)

        # مهم‌ترین ادعای این بخش: یک *لینک* هرگز نباید منبع داده را عوض کند.
        from_link = await rpcpg.evaluate(
            "() => ({field: document.getElementById('rpcCustom').value,"
            " first: CHAIN.rpcs[0], custom: customRpc})")
        print("[rpc link] field=%r first=%s custom=%s"
              % (from_link["field"], from_link["first"][:34], from_link["custom"]))
        assert from_link["field"] == "" and "evil" not in from_link["first"], \
            "a URL parameter must never set the RPC endpoint: %s" % from_link

        rpc = await rpcpg.evaluate("""async () => {
            const out = {};
            const state = () => document.getElementById("rpcState").textContent;
            const fill = v => { document.getElementById("rpcCustom").value = v; };
            const wait = async () => { for (let i = 0; i < 40; i++) {
                if (!/Testing/.test(state())) return; await new Promise(r=>setTimeout(r,50)); } };

            fill("http://plain.example"); await saveCustomRpc("http://plain.example");
            out.http = {msg: state(), first: CHAIN.rpcs[0], saved: localStorage.getItem("zaexa.rpc")};

            window.__STUB_RPC__ = {"https://wrong.example": 1,
                                   "https://dead.example": "unreachable"};
            await saveCustomRpc("https://wrong.example"); await wait();
            out.wrongChain = {msg: state(), first: CHAIN.rpcs[0],
                              saved: localStorage.getItem("zaexa.rpc")};

            await saveCustomRpc("https://dead.example"); await wait();
            out.dead = {msg: state(), saved: localStorage.getItem("zaexa.rpc")};

            await saveCustomRpc("https://good.example/k/SECRET123"); await wait();
            out.good = {msg: state(), first: CHAIN.rpcs[0],
                        saved: localStorage.getItem("zaexa.rpc"),
                        fallbackKept: CHAIN.rpcs.length > 1};
            return out;
        }""")
        for k in ["http", "wrongChain", "dead", "good"]:
            print("[rpc %s] %s" % (k, rpc[k]["msg"][:64]))
        assert rpc["http"]["saved"] is None and "https" in rpc["http"]["msg"], \
            "an http endpoint must be refused: %s" % rpc["http"]
        assert rpc["wrongChain"]["saved"] is None and "Base" in rpc["wrongChain"]["msg"], \
            "an endpoint on another chain must be refused: %s" % rpc["wrongChain"]
        assert rpc["dead"]["saved"] is None, \
            "an endpoint that never answers must not be saved: %s" % rpc["dead"]
        assert rpc["good"]["saved"] == "https://good.example/k/SECRET123", \
            "a working endpoint must persist: %s" % rpc["good"]
        assert "SECRET123" not in rpc["good"]["msg"], \
            "the endpoint may carry a private key — never print it in full: %s" % rpc["good"]["msg"]
        assert rpc["good"]["fallbackKept"], \
            "the public endpoints must stay as a fallback behind the custom one"

        # ماندگاری بعد از رفرش، و اینکه Clear واقعاً پاک می‌کند
        await rpcpg.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpcpg.wait_for_timeout(1200)
        after = await rpcpg.evaluate("""async () => {
            const before = {field: document.getElementById("rpcCustom").value,
                            first: CHAIN.rpcs[0]};
            clearCustomRpc();
            return {before, after: {field: document.getElementById("rpcCustom").value,
                                    first: CHAIN.rpcs[0],
                                    saved: localStorage.getItem("zaexa.rpc")}};
        }""")
        await rpcpg.close()
        print("[rpc reload] restored=%s → cleared=%s"
              % (after["before"]["first"][:28], after["after"]["first"][:28]))
        assert after["before"]["field"] == "https://good.example/k/SECRET123", \
            "a saved endpoint must come back after a reload: %s" % after["before"]
        assert after["after"]["saved"] is None and "good.example" not in after["after"]["first"], \
            "Clear must remove it from storage and stop using it: %s" % after["after"]

        # ---- 2c-octies. RPC rotation: session dead-list + the comparative rule ----
        # قاعده: یک اندپوینت فقط وقتی «مرده» علامت می‌خورد که یکی دیگر در
        # همان تلاش جواب داده باشد؛ اگر همه شکست بخورند هیچ‌کدام علامت
        # نمی‌خورد (مقصر شبکه‌ی کاربر است، نه اندپوینت‌ها).
        rpcdead = await b.new_page()
        await rpcdead.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpcdead.wait_for_timeout(1200)
        r1 = await rpcdead.evaluate("""async () => {
            const first = CHAIN.rpcs[0], second = CHAIN.rpcs[1];
            window.__STUB_RPC__ = {}; window.__STUB_RPC__[first] = "unreachable";
            window.__STUB_RPC_LOG__ = [];
            const code = await getCode("0x" + "ab".repeat(20));
            return {first, second, code,
                    log1: window.__STUB_RPC_LOG__.slice(),
                    deadHasFirst: deadRpc.has(first), liveSrc,
                    remembered: localStorage.getItem("zaexa.rpc.last")};
        }""")
        print("[rpc dead] first=%s… attempted=%s dead-marked=%s live=%s…"
              % (r1["first"][:28], len(r1["log1"]), r1["deadHasFirst"], (r1["liveSrc"] or "")[:28]))
        assert r1["code"] and r1["code"] != "0x", \
            "a dead first endpoint must not stop the read: %s" % r1
        assert r1["log1"] == [r1["first"], r1["second"]], \
            "the read must roll forward to the next endpoint, in order: %s" % r1["log1"]
        assert r1["deadHasFirst"], \
            "the failed endpoint must be marked dead once another one answered: %s" % r1
        assert r1["liveSrc"] == r1["second"], \
            "the endpoint that answered must become the live source: %s" % r1
        assert r1["remembered"] == r1["second"], \
            "a successful read must remember the winning endpoint for next visit: %s" % r1

        r2 = await rpcdead.evaluate("""async () => {
            window.__STUB_RPC_LOG__ = [];
            const code = await getCode("0x" + "cd".repeat(20));
            return {code, log: window.__STUB_RPC_LOG__.slice()};
        }""")
        print("[rpc dead retry] attempted=%s" % [u[:28] for u in r2["log"]])
        assert r1["first"] not in r2["log"], \
            "an endpoint marked dead this session must not be retried again: %s" % r2["log"]
        assert r2["code"] and r2["code"] != "0x"
        await rpcdead.evaluate("() => localStorage.removeItem('zaexa.rpc.last')")
        await rpcdead.close()

        # همه شکست می‌خورند → هیچ‌کدام مرده علامت نمی‌خورد، و تلاش بعدی باید
        # دوباره همه را امتحان کند — از جمله همان اولی که این بار شکست خورد.
        rpcall = await b.new_page()
        await rpcall.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpcall.wait_for_timeout(1200)
        r3 = await rpcall.evaluate("""async () => {
            const all = CHAIN.rpcs.slice();
            window.__STUB_RPC__ = {}; all.forEach(u => window.__STUB_RPC__[u] = "unreachable");
            window.__STUB_RPC_LOG__ = [];
            let err = null;
            try { await getCode("0x" + "ef".repeat(20)); }
            catch (e) { err = {message: e.message, rpcDown: !!e.rpcDown}; }
            return {all, err, log: window.__STUB_RPC_LOG__.slice(), deadSize: deadRpc.size};
        }""")
        print("[rpc all down] attempted=%d rpcDown=%s dead-marked=%d"
              % (len(r3["log"]), r3["err"] and r3["err"]["rpcDown"], r3["deadSize"]))
        assert r3["err"] and r3["err"]["rpcDown"], \
            "when every endpoint fails, the caller must still reach the network-down path: %s" % r3["err"]
        assert r3["log"] == r3["all"], \
            "a total failure must still try every endpoint once: %s" % r3
        assert r3["deadSize"] == 0, \
            ("when everything fails, nothing may be marked dead — that is the user's network, "
             "not the endpoints: %s" % r3)

        r4 = await rpcall.evaluate("""async () => {
            window.__STUB_RPC__ = {};            // حالا همه زنده‌اند
            window.__STUB_RPC_LOG__ = [];
            const code = await getCode("0x" + "12".repeat(20));
            return {code, log: window.__STUB_RPC_LOG__.slice()};
        }""")
        print("[rpc all down retry] attempted=%s" % [u[:28] for u in r4["log"]])
        assert r4["log"][0] == r3["all"][0], \
            "a later retry must try the very first endpoint again, not skip it as dead: %s" % r4
        await rpcall.evaluate("() => localStorage.removeItem('zaexa.rpc.last')")
        await rpcall.close()

        # ---- 2c-octies-bis. remembered endpoint: validated before use ----
        # هرچه از localStorage برمی‌گردد نامعتبر فرض می‌شود؛ فقط عضو
        # DEFAULT_RPCS پذیرفته می‌شود، نه هر رشته‌ای که آنجا نشسته باشد.
        rpclast = await b.new_page()
        await rpclast.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpclast.wait_for_timeout(1200)
        baseline = await rpclast.evaluate(
            "() => ({defaults: DEFAULT_RPCS.slice(), first: CHAIN.rpcs[0]})")
        assert baseline["first"] == baseline["defaults"][0]
        # فهرستِ اندازه‌گیری‌شده‌ی ۲ سپتامبر ۲۰۲۶ — 1rpc.io و llamarpc.com
        # دیگر نباید هرگز اینجا برگردند (هر دو CORS رد می‌شوند)، و ترتیب باید
        # همان ترتیبِ تأخیرِ صعودی باشد که در CHAIN.rpcs کامنت شده.
        expected_rpcs = ["https://base.publicnode.com", "https://base.meowrpc.com",
                          "https://base.drpc.org", "https://base.gateway.tenderly.co",
                          "https://mainnet.base.org"]
        assert baseline["defaults"] == expected_rpcs, \
            "CHAIN.rpcs no longer matches the measured, CORS-clean list: %s" % baseline["defaults"]

        await rpclast.evaluate(
            "() => localStorage.setItem('zaexa.rpc.last', 'https://evil.example/poison')")
        await rpclast.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpclast.wait_for_timeout(1200)
        poisoned = await rpclast.evaluate("() => CHAIN.rpcs[0]")
        print("[rpc remember poisoned] first=%s…" % poisoned[:28])
        assert poisoned == baseline["defaults"][0], \
            "a localStorage value outside the known endpoint list must be ignored: %r" % poisoned

        target = baseline["defaults"][2]
        await rpclast.evaluate(
            "(v) => localStorage.setItem('zaexa.rpc.last', v)", target)
        await rpclast.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await rpclast.wait_for_timeout(1200)
        honored = await rpclast.evaluate("() => CHAIN.rpcs[0]")
        print("[rpc remember valid] first=%s…" % honored[:28])
        assert honored == target, \
            "a remembered endpoint that IS in the known list must lead next visit: %s != %s" \
            % (honored, target)
        await rpclast.evaluate("() => localStorage.removeItem('zaexa.rpc.last')")
        await rpclast.close()

        # ---- 2c-octies-ter. main button agrees with the header on first paint ----
        # قبل از این، مارک‌آپِ خامِ actBtn «Enter an amount» بود و فقط بعد از
        # بارگذاریِ async ethers به «Connect wallet» عوض می‌شد — یعنی همان
        # لحظه‌ای که کاربر بدون کیف پول اولین‌بار صفحه را می‌بیند، هدر و دکمه
        # دو حرف مختلف می‌زدند. این کاوشگر خودِ HTML خام را می‌خواند، نه
        # DOM بعد از اجرای اسکریپت — دقیقاً همان چیزی که first paint نشان
        # می‌دهد.
        raw_src = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
        m_hdr = re.search(r'id="connectBtn"[^>]*>([^<]*)<', raw_src)
        m_act = re.search(r'id="actBtn"[^>]*>([^<]*)<', raw_src)
        assert m_hdr and m_act, "connectBtn/actBtn markup not found — did the ids change?"
        print("[cta initial] header=%r action=%r" % (m_hdr.group(1), m_act.group(1)))
        assert m_hdr.group(1) == m_act.group(1) == "Connect wallet", \
            ("with no wallet connected, the header and the main action button must agree from "
             "first paint: header=%r action=%r" % (m_hdr.group(1), m_act.group(1)))

        # ---- 2d. native ETH is offered and routes through WETH ----
        await pg.click("#tokOutBtn"); await pg.wait_for_timeout(250)
        await pg.fill("#tokSearch", "ETH"); await pg.wait_for_timeout(250)
        syms = await pg.eval_on_selector_all("#tokList .trow .s", "e => e.map(x => x.innerText)")
        print("[eth] picker shows: %s" % syms)
        assert "ETH" in syms, "native ETH must be selectable"
        await pg.click(".trow"); await pg.wait_for_timeout(300)
        assert await pg.inner_text("#tokOutSym") == "ETH"
        await pg.fill("#amtIn", "1000"); await pg.wait_for_timeout(3000)
        out_eth = await pg.input_value("#amtOut")
        print("[eth] USDC -> ETH quote: %s  route=%s" % (
            out_eth, (await pg.inner_text("#routeBody")).replace("\n", " | ")))
        assert out_eth not in ("", "0"), "ETH output must quote via WETH"
        notices = await pg.inner_text("#notices")
        assert "not supported" not in notices, "native ETH should no longer be rejected"

        # نمودار ETH هم باید بیاید. آدرس ETH در جدول ما "NATIVE" است و
        # GeckoTerminal آن را نمی‌شناسد؛ برای تاریخچه‌ی قیمت باید به WETH
        # نگاشت شود. روی سایت زنده این پیام «Price history is unavailable»
        # می‌داد در حالی که همان جفت با WETH درست کار می‌کرد.
        eth_chart = await pg.evaluate("""async () => {
            const t0 = Date.now();
            while (Date.now() - t0 < 9000) {
                const m = document.getElementById("chartMsg");
                const shown = getComputedStyle(m).display !== "none";
                if (shown && /unavailable/i.test(m.textContent))
                    return {ok: false, why: m.textContent.trim()};
                if (document.querySelectorAll("#plot svg path").length >= 2)
                    return {ok: true, why: "drawn"};
                await new Promise(r => setTimeout(r, 200));
            }
            return {ok: false, why: "no chart and no message after 9s"};
        }""")
        print("[eth chart] %s — %s" % (eth_chart["ok"], eth_chart["why"][:70]))
        assert eth_chart["ok"], \
            "native ETH must chart through WETH, not fall over: " + eth_chart["why"]
        await pg.wait_for_timeout(1200)
        eth_safety = await pg.inner_text("#safetyBody")
        print("[eth safety] %s" % eth_safety.replace("\n", " | ")[:120])
        assert "Native asset" in eth_safety, "native ETH must be explained, not reported as a network failure"
        assert "did not answer" not in eth_safety, "no contract is not the same as no answer"
        await pg.screenshot(path=os.path.join(HERE, "shot-eth.png"), full_page=True)
        # برگرد به WETH برای بقیه‌ی تست‌ها
        await pg.click("#tokOutBtn"); await pg.wait_for_timeout(250)
        await pg.fill("#tokSearch", "WETH"); await pg.wait_for_timeout(250)
        await pg.click(".trow"); await pg.wait_for_timeout(2500)

        # ---- 2e. portfolio + money flow live on their own pages ----
        assert not await pg.is_visible("#flowBody"), "flow must not sit on the swap page"
        assert not await pg.is_visible("#folioBody"), "portfolio must not sit on the swap page"

        await go_view(pg, "flow"); await pg.wait_for_timeout(400)
        assert await pg.evaluate("location.hash") == "#flow", "view must be linkable"
        print("[nav] flow page token: %s" % await pg.inner_text("#flowTokSym"))
        await pg.wait_for_selector("#flowBody .flowkv", timeout=20000)
        flow = await pg.inner_text("#flowBody")
        print("[flow 1H] %s" % flow.replace("\n", " | ")[:170])
        addrs = await pg.eval_on_selector_all("#flowBody .trade a", "e => e.length")
        print("[flow] buyer addresses shown: %s" % addrs)
        assert addrs > 0, "largest buys should link the buying wallet"
        assert "Net" in flow, "flow panel missing net figure"
        assert "LARGEST BUYS" in flow.upper(), "largest buys list missing"
        await pg.click('#flowTfs [data-w="h6"]'); await pg.wait_for_timeout(900)
        print("[flow 6H] %s" % (await pg.inner_text("#flowBody")).replace("\n", " | ")[:120])
        await pg.click('#flowTfs [data-w="h1"]'); await pg.wait_for_timeout(600)

        # ---- 2e-ter. ۶ ساعته نباید کپی‌ی ۱ ساعته باشد ----
        # علتِ اینکه باگِ بازه‌ی eth_getLogs تا حالا دیده نشده بود همین بود:
        # هارنس برای هر دو پنجره *همان* دسته‌ی ثابتِ لاگ را برمی‌گرداند، پس
        # [flow 1H] و [flow 6H] رقم به رقم یکی بودند و هیچ کاوشگری نمی‌توانست
        # فرقی ببیند که نبود. اینجا به‌جای آن مقدارِ ثابت، خودِ این کاوشگر
        # موقتاً `ethers.JsonRpcProvider.prototype.getLogs` را عوض می‌کند —
        # همان روشی که `[gate]` و `[quoter gate]` بالاتر برای شبیه‌سازی خطای
        # RPC استفاده کرده‌اند — و رفتار یک RPC عمومی واقعی را می‌سازد:
        #   ۱) هر بازه‌ی بزرگ‌تر از ۲۰۰۰ بلوک رد می‌شود (دقیقاً همان سقفی که
        #      باعث شد پنجره‌ی ۶ ساعته‌ی ۱۰۸۰۰ بلوکیِ تک‌درخواستی بشکند)،
        #   ۲) هر بازه‌ای که قبول می‌شود، رویدادهایی می‌سازد که از خودِ شماره‌
        #      بلوکش می‌آیند — پس دو بازه‌ی متفاوت، دو دسته لاگِ متفاوت
        #      می‌گیرند، نه یک کپی از یک دسته‌ی ثابت.
        # با این مسیر، کدِ قدیمیِ تک‌درخواستی همین‌جا رد می‌شد (بازه‌ی ۱۰۸۰۰
        # از ۲۰۰۰ رد می‌شود) و [flow 6H] یک خطای «نمی‌دانم» نشان می‌داد —
        # دقیقاً همان چیزی که کاربر واقعی دید. کدِ تکه‌تکه‌کننده باید چند
        # درخواست بزند و رد شود.
        flow_split = await pg.evaluate("""async () => {
            const realGetLogs = ethers.JsonRpcProvider.prototype.getLogs;
            const RANGE_CAP = 2000;
            const topic = iPool.getEvent("Swap").topicHash;
            /* ⚠️ لاگ باید به قالبِ خودِ استاب کدگذاری شود، نه ABI واقعی.
               stub-ethers.js چنین می‌کند:
                 data     = toHex(ser({amount0, amount1, recipient}))
                 parseLog = de(fromHex(lg.data))
               یعنی JSON، نه کلمه‌های ۳۲ بایتی. نسخه‌ی اول این کاوشگر کلمه‌های
               واقعیِ ABI می‌ساخت، `de` رویشان JSON.parse می‌خورد و می‌افتاد،
               و renderFlow با catch/continue همه را دور می‌ریخت — پس هر دو
               پنجره «۰ خرید · ۰ فروش» می‌شدند و *به همین دلیل* متنشان یکی
               بود، نه به‌خاطر باگی در تکه‌کردن. */
            const ser = (x) => JSON.stringify(x, (k, v) =>
                (typeof v === "bigint" ? { __b: v.toString() } : v));
            const toHex = (s) => "0x" + Array.from(new TextEncoder().encode(s))
                .map(b => b.toString(16).padStart(2, "0")).join("");
            let failMode = null, callIdx = 0;
            const calls = [];
            ethers.JsonRpcProvider.prototype.getLogs = async function (f) {
                const from = f.fromBlock, to = f.toBlock, i = callIdx++;
                calls.push([from, to]);
                if (to - from > RANGE_CAP)
                    throw Object.assign(new Error("eth_getLogs range exceeds the provider limit"),
                        { code: "SERVER_ERROR" });
                if (failMode && failMode(i, from))
                    throw Object.assign(new Error("temporary rpc hiccup"), { code: "SERVER_ERROR" });
                const logs = [];
                const start = Math.ceil(from / 97) * 97;
                for (let b = start; b <= to; b += 97) {
                    const isBuy = (b % 2) === 0;
                    const our = BigInt(1 + (b % 5)) * 10n ** 17n;
                    const ref = BigInt(200 + (b % 7) * 100) * 10n ** 6n;
                    logs.push({ blockNumber: b, data: toHex(ser({
                        amount0: isBuy ? -our : our,
                        amount1: isBuy ? ref : -ref,
                        recipient: "0x" + (b % 3 + 17).toString(16).repeat(20).slice(0, 40),
                    })) });
                }
                return logs;
            };

            async function run(id, fm) {
                failMode = fm; callIdx = 0; calls.length = 0;
                flowWindow = id;
                await renderFlow();
                await new Promise(r => setTimeout(r, 80));
                return { text: document.getElementById("flowBody").innerText,
                         html: document.getElementById("flowBody").innerHTML,
                         calls: calls.slice() };
            }

            const h1 = await run("h1", null);
            const h6 = await run("h6", null);
            /* ⚠️ شکست باید به خودِ *تکه* گره بخورد، نه به شماره‌ی فراخوانی:
               تلاش دوباره یک شماره‌ی تازه می‌گیرد و از شرطِ شماره‌ای فرار
               می‌کند، پس خواندن کامل می‌شود و مسیر «پوشش ناقص» هرگز اجرا
               نمی‌شود. با گره‌زدن به بلوکِ شروع، آن تکه هر بار می‌افتد. */
            /* دو سناریوی بعدی عمداً شکست می‌خورند و renderFlow درست عمل
               می‌کند که console.error بزند — ولی همان یک خط، بررسیِ
               «صفر خطای کنسول» در انتهای سوییت را قرمز می‌کرد. فقط برای
               همین دو اجرا خاموشش می‌کنیم و بلافاصله برمی‌گردانیم، تا یک
               خطای *غیرمنتظره* همچنان دیده شود. */
            const realConsoleError = console.error;
            console.error = () => {};
            const deadFrom = new Set();
            const h6partial = await run("h6", (i, from) => {
                if (deadFrom.size === 0 || deadFrom.has(from)) {
                    if (deadFrom.size < 2) deadFrom.add(from);
                    return deadFrom.has(from);
                }
                return false;
            });
            const h6dead = await run("h6", () => true);            // همه‌ی تکه‌ها شکست می‌خورند

            console.error = realConsoleError;
            ethers.JsonRpcProvider.prototype.getLogs = realGetLogs;
            flowWindow = "h1"; await renderFlow();   // حالت را برای بقیه‌ی تست‌ها برمی‌گرداند
            await new Promise(r => setTimeout(r, 200));

            return { h1, h6, h6partial, h6dead };
        }""")
        print("[flow split] 1H calls=%s 6H calls=%s (ranges<=1500: %s)"
              % (len(flow_split["h1"]["calls"]), len(flow_split["h6"]["calls"]),
                 all(t - f <= 1500 for f, t in flow_split["h6"]["calls"])))
        # ادعای اول: باگ اصلی. اگر ۱H و ۶H همان متن را بدهند، یعنی همان مشکلِ
        # «داده‌ی ساختگیِ یکسان برای دو پنجره» دوباره برگشته و این کاوشگر
        # دوباره کور شده.
        assert flow_split["h1"]["text"] != flow_split["h6"]["text"], \
            "1H and 6H rendered byte-identical text — the mock is hiding the window again"
        assert "Net" in flow_split["h6"]["text"], \
            "the 6H window did not render at all against a range-capped mock: %r" \
            % flow_split["h6"]["text"][:160]
        # ادعای دوم: بازه واقعاً تکه‌تکه شد. یک پنجره‌ی ۱۰۸۰۰ بلوکی با سقفِ
        # ۲۰۰۰ بلوکی فقط با بیش از یک درخواست ممکن است جواب بگیرد.
        assert len(flow_split["h6"]["calls"]) > 1, \
            "the 6H window answered from a single eth_getLogs call — chunking did not happen: %s" \
            % flow_split["h6"]["calls"]
        assert all(t - f <= 2000 for f, t in flow_split["h6"]["calls"]), \
            "a chunk still asked for more than the provider's 2000-block cap: %s" \
            % flow_split["h6"]["calls"]
        # ادعای سوم: بعضی تکه‌ها شکست بخورند، ولی نتیجه هنوز *ناقص* گزارش
        # شود، نه اینکه جمعِ ناقص را جمعِ کل جا بزند — قاعده‌ی اول همین پروژه.
        print("[flow split partial] %s" % flow_split["h6partial"]["text"].replace("\n", " | ")[:160])
        assert "did not answer" in flow_split["h6partial"]["text"], \
            ("a partial read must say so in the same words the rest of the file uses for "
             "unknown/partial states — got: %r" % flow_split["h6partial"]["text"][:200])
        assert "Coverage" in flow_split["h6partial"]["text"] or "~$" in flow_split["h6partial"]["text"], \
            "a partial result must be visibly marked as partial, not shown as a clean total"
        # ادعای چهارم: اگر همه‌ی تکه‌ها شکست بخورند، همان رفتارِ قدیمی —
        # «نمی‌دانم»، نه صفرِ ساختگی و نه جمعِ کامل.
        assert "unknown, not zero" in flow_split["h6dead"]["text"], \
            ("when every chunk fails the panel must fall back to the existing unknown-not-zero "
             "wording, not invent a total: %r" % flow_split["h6dead"]["text"][:200])
        assert "Net" not in flow_split["h6dead"]["text"], \
            "a totally failed read must not still show Bought/Sold/Net figures"

        # ---- 2e-quater. Bug 6 رگرسیون: نوارِ زیرِ Coverage خودش را معرفی می‌کند ----
        # آن نوار نسبتِ خرید-به-فروش است، نه نوارِ پوشش — قبلاً بدون برچسب
        # بود و درست کنار ردیفِ Coverage می‌نشست، پس چشم آن را مالِ Coverage
        # می‌خواند (یک بازه‌ی ۴.۳ از ۶ ساعت که همه‌فروش بود، یک نوارِ قرمزِ
        # تمام‌عرض نشان می‌داد که انگار «پوشش صفر است»).
        h6p_html = flow_split["h6partial"]["html"]
        print("[flow] split bar is labelled: %s" % (
            "flowbarCap" in h6p_html and "border-bottom" in h6p_html))
        assert "flowbarCap" in h6p_html, \
            "the bought/sold split bar has no caption class — it still reads as unlabelled"
        cap_m = re.search(r'<div class="flowbarCap">(.*?)</div>', h6p_html, re.S)
        assert cap_m, "no flowbarCap element was rendered next to the split bar"
        cap_text = cap_m.group(1)
        assert "Bought" in cap_text and "Sold" in cap_text and "%" in cap_text, \
            "the split-bar caption must name both sides and their share: %r" % cap_text[:160]
        cov_m = re.search(r'<div class="flowkv" style="([^"]*)">\s*<span class="k">Coverage</span>', h6p_html)
        assert cov_m, "the Coverage row markup changed shape — cannot check its separation style"
        assert "border-bottom" in cov_m.group(1), \
            "the Coverage row needs its own border so the split bar underneath it does not read " \
            "as belonging to Coverage: style=%r" % cov_m.group(1)

        # ---- [flow tf] r10 — پنج بازه‌ی زمانی (5M/15M/1H/6H/24H) روی Base ----
        # هر بازه باید دقیقاً همان‌قدر بلوک بخواند (Base بلوکِ ۲ثانیه‌ای: ۱۸۰۰ بلوک = ۱ ساعت)؛ ۲۴ساعته
        # تکه‌تکه می‌شود و تکه‌ی ناموفق باید یادداشتِ پوشش بدهد، نه رقمِ نصفه‌ی بی‌صدا.
        flow_tf = await pg.evaluate("""async () => {
            const realGetLogs = ethers.JsonRpcProvider.prototype.getLogs;
            const ser = (x) => JSON.stringify(x, (k, v) => (typeof v === "bigint" ? { __b: v.toString() } : v));
            const toHex = (s) => "0x" + Array.from(new TextEncoder().encode(s)).map(b => b.toString(16).padStart(2, "0")).join("");
            let dead = null; const calls = [];
            ethers.JsonRpcProvider.prototype.getLogs = async function (f) {
                const from = f.fromBlock, to = f.toBlock; calls.push([from, to]);
                if (to - from > 2000) throw Object.assign(new Error("range"), { code: "SERVER_ERROR" });
                if (dead && dead(from)) throw Object.assign(new Error("hiccup"), { code: "SERVER_ERROR" });
                const logs = [];
                for (let b = Math.ceil(from / 97) * 97; b <= to; b += 97) {
                    const isBuy = (b % 2) === 0, our = BigInt(1 + (b % 5)) * 10n ** 17n, ref = BigInt(200 + (b % 7) * 100) * 10n ** 6n;
                    logs.push({ blockNumber: b, data: toHex(ser({ amount0: isBuy ? -our : our, amount1: isBuy ? ref : -ref,
                        recipient: "0x" + (b % 3 + 17).toString(16).repeat(20).slice(0, 40) })) });
                }
                return logs;
            };
            const settle = async () => { for (let i = 0; i < 120; i++) { await new Promise(r => setTimeout(r, 50));
                if (!document.getElementById("flowBody").innerText.includes("Reading swaps")) break; } };
            const av = document.getElementById("flowTokAv");
            const muts = []; const mo = new MutationObserver(rs => rs.forEach(r => muts.push(r.type)));
            mo.observe(av, { childList: true, subtree: true, characterData: true });
            const realErr = console.error; console.error = () => {};
            const out = { labels: Array.from(document.querySelectorAll("#flowTfs [data-w]")).map(b => [b.dataset.w, b.textContent.trim()]), runs: {} };
            const mark = av; mark.__probe = "same-node";
            for (const id of ["m5", "m15", "h1", "h6", "h24"]) {
                calls.length = 0; dead = null;
                document.querySelector('#flowTfs [data-w="' + id + '"]').click();
                await settle();
                out.runs[id] = { n: calls.length, span: calls.length ? Math.max(...calls.map(c => c[1])) - Math.min(...calls.map(c => c[0])) : -1,
                    maxChunk: calls.length ? Math.max(...calls.map(c => c[1] - c[0])) : -1,
                    on: Array.from(document.querySelectorAll("#flowTfs .on")).map(b => b.dataset.w),
                    text: document.getElementById("flowBody").innerText };
            }
            out.avMutations = muts.length + mo.takeRecords().length;
            out.sameNode = document.getElementById("flowTokAv") === av && av.__probe === "same-node";
            // ۲۴ساعته با دو تکه‌ی همیشه‌شکست‌خورده
            const deadSet = new Set();
            calls.length = 0; dead = (from) => { if (deadSet.size < 2) deadSet.add(from); return deadSet.has(from); };
            document.querySelector('#flowTfs [data-w="h24"]').click(); await settle();
            out.h24partial = document.getElementById("flowBody").innerText;
            console.error = realErr; mo.disconnect();
            ethers.JsonRpcProvider.prototype.getLogs = realGetLogs; dead = null;
            document.querySelector('#flowTfs [data-w="h1"]').click(); await settle();
            return out;
        }""")
        print("[flow tf] buttons=%s" % flow_tf["labels"])
        assert flow_tf["labels"] == [["m5", "5M"], ["m15", "15M"], ["h1", "1H"], ["h6", "6H"], ["h24", "24H"]], \
            "[flow tf] the Money Flow buttons must be 5M, 15M, 1H, 6H, 24H: %s" % flow_tf["labels"]
        for tf_id, tf_blocks in (("m5", 150), ("m15", 450), ("h1", 1800), ("h6", 10800), ("h24", 43200)):
            tf_run = flow_tf["runs"][tf_id]
            print("[flow tf %s] span=%d requests=%d maxChunk=%d on=%s" % (tf_id, tf_run["span"], tf_run["n"], tf_run["maxChunk"], tf_run["on"]))
            assert tf_run["span"] == tf_blocks, "[flow tf] %s must read exactly %d blocks, read %d" % (tf_id, tf_blocks, tf_run["span"])
            assert tf_run["on"] == [tf_id], "[flow tf] clicking %s must mark only that button active: %s" % (tf_id, tf_run["on"])
            assert tf_run["maxChunk"] <= 1500, "[flow tf] %s: a chunk exceeds the 1500-block cap" % tf_id
            assert "Net" in tf_run["text"], "[flow tf] %s did not render: %r" % (tf_id, tf_run["text"][:120])
            assert "We could only read" not in tf_run["text"], "[flow tf] %s: a fully answered window must not claim partial coverage" % tf_id
        assert flow_tf["runs"]["h24"]["n"] >= 28, "[flow tf] 24H must be chunked into ~29 requests: %d" % flow_tf["runs"]["h24"]["n"]
        assert flow_tf["runs"]["m5"]["n"] == 1 and flow_tf["runs"]["m15"]["n"] == 1, "[flow tf] short windows are a single request"
        assert re.search(r"We could only read [\d.]+ of 24 hours", flow_tf["h24partial"]), \
            "[flow tf] 24H with failing chunks must say 'We could only read X of 24 hours', not show a silent partial: %r" % flow_tf["h24partial"][-300:]
        print("[flow tf] 24H with failing chunks says: %r" % re.search(r"We could only read [\d.]+ of 24 hours", flow_tf["h24partial"]).group(0))
        # [flow logo] — با عوض‌کردنِ بازه آواتارِ توکن نباید دوباره نقاشی شود (Base)
        print("[flow logo] base: avatar childList mutations over 5 window switches=%d sameNode=%s" % (flow_tf["avMutations"], flow_tf["sameNode"]))
        assert flow_tf["avMutations"] == 0 and flow_tf["sameNode"], \
            "[flow logo] switching windows must not repaint the token avatar (Base): mutations=%d" % flow_tf["avMutations"]
        # موبایلِ ۳۶۰: پنج دکمه بدونِ شکستنِ خط، بدونِ سرریز از کارت و بدونِ افتادن روی دکمه‌ی توکن
        vp0 = pg.viewport_size
        await pg.set_viewport_size({"width": 360, "height": 800}); await pg.wait_for_timeout(300)
        tf_geo = await pg.evaluate("""() => { const t = document.getElementById("flowTfs"), c = t.closest(".card"), k = document.getElementById("flowTokBtn");
            const cr = c.getBoundingClientRect(), cs = getComputedStyle(c), tr = t.getBoundingClientRect(), kr = k.getBoundingClientRect();
            const bs = Array.from(t.querySelectorAll("button")).map(b => b.getBoundingClientRect());
            return { n: bs.length, tops: bs.map(r => Math.round(r.top)), hs: bs.map(r => Math.round(r.height)),
                     left: Math.min(...bs.map(r => r.left)), right: Math.max(...bs.map(r => r.right)),
                     innerL: cr.left + parseFloat(cs.paddingLeft), innerR: cr.right - parseFloat(cs.paddingRight),
                     tfsTop: tr.top, tokBottom: kr.bottom, tokRight: kr.right, tfsLeft: tr.left,
                     sw: document.documentElement.scrollWidth, iw: innerWidth,
                     wraps: Array.from(t.querySelectorAll("button")).some(b => b.scrollWidth > b.clientWidth + 1) }; }""")
        await pg.screenshot(path="/tmp/claude-0/r10_shots/base-flow-360.png")
        await pg.set_viewport_size(vp0); await pg.wait_for_timeout(300)
        # عکسِ Base Flow ۲۴H، تم تیره، ۱۴۴۰ (فقط برای بازبینی؛ attribute بعد برمی‌گردد)
        await pg.evaluate("document.documentElement.setAttribute('data-theme', 'dark')")
        await pg.click('#flowTfs [data-w="h24"]'); await pg.wait_for_timeout(1500)
        await pg.screenshot(path="/tmp/claude-0/r10_shots/base-flow-24h-dark-1440.png")
        await pg.evaluate("document.documentElement.setAttribute('data-theme', theme)")
        await pg.click('#flowTfs [data-w="h1"]'); await pg.wait_for_timeout(600)
        print("[flow tf mobile 360] %s" % tf_geo)
        assert tf_geo["n"] == 5 and len(set(tf_geo["tops"])) == 1 and max(tf_geo["hs"]) <= 40, "[flow tf] the five buttons must stay on one line at 360px: %s" % tf_geo
        assert tf_geo["left"] >= tf_geo["innerL"] - 1 and tf_geo["right"] <= tf_geo["innerR"] + 1 and tf_geo["sw"] <= tf_geo["iw"], \
            "[flow tf] the buttons overflow the card at 360px: %s" % tf_geo
        assert tf_geo["tfsTop"] >= tf_geo["tokBottom"] - 1 or tf_geo["tfsLeft"] >= tf_geo["tokRight"], \
            "[flow tf] the button group sits on top of the token button at 360px: %s" % tf_geo
        assert not tf_geo["wraps"], "[flow tf] a button label is clipped at 360px: %s" % tf_geo

        await pg.screenshot(path=os.path.join(HERE, "shot-flow.png"), full_page=True)

        await go_view(pg, "folio"); await pg.wait_for_timeout(500)
        folio = await pg.inner_text("#folioBody")
        print("[portfolio] %s" % folio.replace("\n", " | ")[:120])
        assert "Connect a wallet" in folio, "with no wallet the portfolio must say so, not show zeros"
        await pg.screenshot(path=os.path.join(HERE, "shot-folio.png"), full_page=True)

        # back to the swap page for the remaining tests
        await pg.click('#nav [data-view="swap"]'); await pg.wait_for_timeout(400)
        assert await pg.is_visible("#amtIn"), "swap page must come back"

        # ---- 2f. reverse quoting: type the amount you WANT to receive ----
        await pg.fill("#amtIn", "")
        await pg.fill("#amtOut", "0.5")
        await pg.wait_for_function(
            "() => document.getElementById('amtIn').value !== ''", timeout=25000)
        need = await pg.input_value("#amtIn")
        got = await pg.input_value("#amtOut")
        print("[reverse] want %s WETH -> pay %s USDC" % (got, need))
        assert float(need) > 0, "reverse solve produced no input amount"
        note = await pg.inner_text("#revNote")
        assert "Solved for your target" in note, "reverse mode must say the amount is solved, not exact"
        print("[reverse] %s" % note.replace("\n", " ")[:130])
        await pg.screenshot(path=os.path.join(HERE, "shot-reverse.png"), full_page=True)
        await pg.fill("#amtOut", "")
        await pg.fill("#amtIn", "1000"); await pg.wait_for_timeout(2500)

        # ---- 3. split order ----
        await pg.fill("#amtIn", "900000")
        await pg.wait_for_timeout(3000)
        print("[split] route=%s  impact=%s" % (
            await pg.inner_text("#routeMeta"), await pg.inner_text("#kImpact")))
        print("[route] %s" % (await pg.inner_text("#routeBody")).replace("\n", " | "))
        await pg.screenshot(path=os.path.join(HERE, "shot-split.png"), full_page=True)

        # ---- 3b. مورد ۰۳ ریویو: کف روی صفحه = کفی که امضا می‌شود ----
        # وقتی مسیر بهتر در شبیه‌سازی می‌افتد، doSwap به یک صرافی تک برمی‌گردد
        # که minOut کمترى دارد. «Min received» از نقشه‌ی *اولیه* رندر شده بود و
        # دوباره رندر نمی‌شد، پس کاربر تراکنشی را امضا می‌کرد که ضمانتش پایین‌تر
        # از عدد روی صفحه بود — روی جفت کم‌عمق، بیشتر از لغزشی که خودش گذاشته.
        # raw string: the JS below contains \s, which is not a Python escape
        floor_probe = await pg.evaluate(r"""async () => {
            const realContract = E.Contract;
            const BIGV = 10n ** 40n;
            window.__STUB_ALLOWANCE__ = BIGV.toString();
            window.__STUB_BALANCE__ = BIGV.toString();   // وگرنه preflight همان‌جا می‌ایستد
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            signer = {}; walletChainId = CHAIN.id; walletIsRemote = false;
            balances[balKey(tokenIn)] = BIGV; allowance = BIGV; allowanceKnown = true;

            let cand = 0, seen = [], noticeAtSend = "";
            E.Contract = function () {
                const send = function () {
                    /* اعلان را همین‌جا برمی‌داریم — یک لحظه قبل از ارسال، که
                       دقیقاً همان چیزی است که کاربر می‌بیند. بعد از این،
                       showError جای اعلان را می‌گیرد. */
                    noticeAtSend = document.getElementById("notices").innerText
                                     .replace(/\s+/g, " ");
                    throw new Error("probe: stop before sending");
                };
                send.staticCall = async (...a) => {
                    /* ⚠️ doSwap اول runQuote را صدا می‌زند و آن هم runExitCheck را،
                       که یک مسیر *حلقه‌ای* (tokenIn == tokenOut) شبیه‌سازی می‌کند.
                       تلاش اول این تست همان تماس را با کاندید اول اشتباه گرفت و
                       حلقه‌ی کاندیدها هرگز به fallback نرسید. پس تفکیکش می‌کنیم. */
                    const isExitCheck = JSON.stringify(a[0]) === JSON.stringify(a[1]);
                    if (isExitCheck) return 1n;
                    cand++; seen.push(a[3].toString());
                    // کاندید اول «best» است و عمداً می‌افتد؛ دومی قبول می‌شود
                    if (cand === 1) throw new Error('execution reverted: "best route fails"');
                    return 1n;
                };
                send.estimateGas = async () => { throw new Error("probe: no estimate"); };
                return { executeSwap: send };
            };

            const before = document.getElementById("kMin").textContent;
            try { await doSwap(); } catch (e) {}
            E.Contract = realContract;

            delete window.__STUB_BALANCE__;
            const chosenMinOut = seen.length > 1 ? seen[1] : null;
            return {
                before, after: document.getElementById("kMin").textContent,
                calls: cand, chosenMinOut,
                expected: chosenMinOut === null ? null
                    : fmt(BigInt(chosenMinOut), tokenOut.decimals) + " " + tokenOut.symbol,
                notice: noticeAtSend
            };
        }""")
        print("[fallback floor] sims=%s  on screen before=%r after=%r"
              % (floor_probe["calls"], floor_probe["before"], floor_probe["after"]))
        assert floor_probe["calls"] >= 2, (
            "the probe never reached a fallback candidate (%s simulation calls) — preflight "
            "probably stopped doSwap first, so this test proves nothing"
            % floor_probe["calls"])
        assert floor_probe["expected"], "the fallback candidate's minOut was not captured"
        assert floor_probe["after"] == floor_probe["expected"], (
            "Min received on screen is not the floor that would have been signed.\n"
            "  on screen: %s\n  in the transaction: %s\n"
            "The user reads the panel, not the calldata."
            % (floor_probe["after"], floor_probe["expected"]))
        assert floor_probe["after"] != floor_probe["before"], (
            "the fallback floor happens to equal the original one, so this run cannot tell "
            "a re-render from a stale value — the probe needs a plan where they differ")
        assert "Minimum received is now" in floor_probe["notice"], (
            "the fallback notice names the venue but not the new floor: %s"
            % floor_probe["notice"][:160])

        # ---- 3c. مورد B پیگیری ریویو: پیامی که توصیه‌ی ناممکن نمی‌دهد ----
        # کلمپ پنیک را برداشت، ولی require(delivered >= minAmountOut) هنوز برای
        # گیرنده‌ای که پول را در همان تراکنش جلو می‌فرستد می‌افتد، چون minOut
        # هیچ‌وقت صفر نیست. پیام قدیمی «لغزش را بالا ببر» می‌گفت و آن توصیه
        # هرگز جواب نمی‌داد. حالا با یک شبیه‌سازی کف‌صفر تفکیک می‌شود.
        sweep_probe = await pg.evaluate(r"""async () => {
            const realContract = E.Contract;
            const BIGV = 10n ** 40n;
            window.__STUB_ALLOWANCE__ = BIGV.toString();
            window.__STUB_BALANCE__ = BIGV.toString();
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            signer = {}; walletChainId = CHAIN.id; walletIsRemote = false;
            balances[balKey(tokenIn)] = BIGV; allowance = BIGV; allowanceKnown = true;

            let zeroFloorCalls = 0, floors = [];
            E.Contract = function () {
                const send = function () { throw new Error("probe: stop before sending"); };
                send.staticCall = async (...a) => {
                    const isExitCheck = JSON.stringify(a[0]) === JSON.stringify(a[1]);
                    if (isExitCheck) return 1n;
                    const minOut = BigInt(a[3]);
                    floors.push(minOut.toString());
                    /* کیف پول جاروکننده: با هر کف واقعی می‌افتد، و با کف صفر
                       موفق می‌شود ولی صفر تحویل می‌دهد — دقیقاً همان چیزی که
                       روی زنجیره می‌بیند. */
                    if (minOut === 0n) { zeroFloorCalls++; return 0n; }
                    throw new Error('execution reverted: "slippage: output below minimum"');
                };
                send.estimateGas = async () => { throw new Error("probe: no estimate"); };
                return { executeSwap: send };
            };

            try { await doSwap(); } catch (e) {}
            E.Contract = realContract;
            delete window.__STUB_BALANCE__;
            return {
                zeroFloorCalls, floors,
                notice: document.getElementById("notices").innerText.replace(/\s+/g, " ")
            };
        }""")
        print("[recipient sweep] zero-floor sims=%s  says=%r"
              % (sweep_probe["zeroFloorCalls"], sweep_probe["notice"][:120]))
        assert sweep_probe["zeroFloorCalls"] == 1, (
            "the zero-floor diagnosis never ran (%s calls). Without it the page cannot tell "
            "'the price moved' from 'the recipient took the funds', and both arrive as the "
            "same revert string." % sweep_probe["zeroFloorCalls"])
        assert "moves the funds onward" in sweep_probe["notice"], (
            "a recipient that forwards the output is still told this was slippage: %s"
            % sweep_probe["notice"][:200])
        assert "Raise it in settings" not in sweep_probe["notice"], (
            "the page still tells the user to raise slippage. Raising it cannot help here — "
            "the cause is not price movement, so the advice can never succeed:\n  %s"
            % sweep_probe["notice"][:200])
        assert sweep_errs, (
            "the deliberate failure was allow-listed but never actually logged — the "
            "allowlist would then be a silent way to hide a real error")
        # خطای عمدی این کاوشگر واقعاً باید لاگ شده باشد — نه اینکه بی‌صدا رد شود
        assert probe_errs, \
            "doSwap swallowed the send failure instead of reporting it through showError"
        print("[fallback floor] the interrupted send was reported, not swallowed (%d log)"
              % len(probe_errs))

        # ---- [sim override] ۴ اکتبر — Base: همهٔ کاندیدها در staticCall می‌افتند؛ با تأییدِ کاربر بهترین نقشه با gasLimit ثابت فرستاده می‌شود ----
        simo_base = await pg.evaluate(r"""async () => {
            const realContract = E.Contract, realErr = console.error;
            const BIGV = 10n ** 40n;
            window.__STUB_ALLOWANCE__ = BIGV.toString();
            window.__STUB_BALANCE__ = BIGV.toString();
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            signer = {}; walletChainId = CHAIN.id; walletIsRemote = false;
            balances[balKey(tokenIn)] = BIGV; allowance = BIGV; allowanceKnown = true;
            baseSimArmedKey = null; baseSimFailedKey = null;
            console.error = () => {};            // showError لاگ می‌کند؛ این خطا عمدی است
            const j = x => JSON.stringify(x, (k, v) => typeof v === "bigint" ? v.toString() : v);
            const sleep = ms => new Promise(r => setTimeout(r, ms));
            const wait = async () => { for (let i = 0; i < 200 && busy; i++) await sleep(50); await sleep(50); };
            let sent = [], firstParts = [], noticeAtSend = "", remoteReq = [];
            E.Contract = function () {
                const send = function (...a) {
                    noticeAtSend = document.getElementById("notices").innerText.replace(/\s+/g, " ");
                    sent.push({parts: j(a[4]), minOut: a[3].toString(), opts: a[6]});
                    throw new Error("probe: stop before sending");
                };
                send.staticCall = async (...a) => {
                    if (JSON.stringify(a[0]) === JSON.stringify(a[1])) return 1n;      // exit check
                    firstParts.push(j(a[4]));
                    throw new Error('execution reverted: "probe: every route fails"');
                };
                send.estimateGas = async () => { throw new Error("probe: estimateGas must not be needed"); };
                return { executeSwap: send };
            };
            const btn = () => document.getElementById("actBtn");
            const out = {};
            try {
                await doSwap(); await wait();
                out.btn1 = btn().textContent.trim(); out.dis1 = btn().disabled;
                out.notice1 = document.getElementById("notices").innerText.replace(/\s+/g, " ");
                out.sent1 = sent.length;
                const cand0Parts = firstParts[0];
                firstParts.length = 0;
                btn().click(); await wait();                          // کلیک روی «Swap anyway»: تأیید + ارسال، همان کلیک
                out.sent2 = 0; out.btn2 = "Swap";
                out.sent3 = sent.length;
                const s3 = sent[0] || {};
                out.gas = s3.opts && s3.opts.gasLimit !== undefined ? s3.opts.gasLimit.toString() : null;
                out.samePlan = !!s3.parts && s3.parts === firstParts[0];
                out.noticeAtSend = noticeAtSend;
                out.candCount = firstParts.length;
                // مسیرِ والتِ راه‌دور: p.gas
                sent.length = 0;
                walletIsRemote = true;
                walletEip1193 = { request: async ({method, params}) => { remoteReq.push({method, params}); throw new Error("probe: stop before sending"); } };
                btn().click(); await wait();
                out.remote = remoteReq.length ? {method: remoteReq[0].method, gas: remoteReq[0].params[0].gas} : null;
            } finally {
                E.Contract = realContract; console.error = realErr;
                walletIsRemote = false; baseSimArmedKey = null; baseSimFailedKey = null;
                delete window.__STUB_BALANCE__;
            }
            return out;
        }""")
        print("[sim override] base all candidates fail -> btn=%r sent before/after arm/after 2nd click=%d/%d/%d gas=%s samePlan=%s remote=%s"
              % (simo_base["btn1"], simo_base["sent1"], simo_base["sent2"], simo_base["sent3"], simo_base["gas"], simo_base["samePlan"], simo_base["remote"]))
        assert "Simulation failed — nothing sent, no gas spent" in simo_base["notice1"] and \
            "You can still send it: if it reverts on-chain you pay only the gas, and your tokens stay with you." in simo_base["notice1"], \
            "sim override: Base must keep the failure notice and add the confirmation line: %r" % simo_base["notice1"][:200]
        assert simo_base["btn1"] == "Swap anyway (simulation failed)" and simo_base["dis1"] is False and simo_base["sent1"] == 0, \
            "sim override: Base must offer the override and not call the wallet yet: %s" % simo_base
        assert simo_base["sent3"] == 1 and simo_base["gas"] == "1500000", \
            "sim override: the armed click must send executeSwap with gasLimit 1500000: %s" % simo_base
        assert simo_base["samePlan"], "sim override: the armed send must use the best candidate's parts: %s" % simo_base
        assert "Sending although our simulation failed." in simo_base["noticeAtSend"], \
            "sim override: the armed send must say so: %r" % simo_base["noticeAtSend"]
        assert simo_base["remote"] and simo_base["remote"]["method"] == "eth_sendTransaction" and simo_base["remote"]["gas"] == "0x16e360", \
            "sim override: the remote-wallet payload must carry gas 0x16e360: %s" % simo_base["remote"]

        # عکسِ هشدارِ Base (روشن، ۱۴۴۰ و ۳۹۰) — حالتِ شکست + دکمهٔ «Swap anyway»
        await pg.evaluate(r"""async () => {
            const realContract = E.Contract, realErr = console.error;
            const BIGV = 10n ** 40n;
            window.__STUB_ALLOWANCE__ = BIGV.toString(); window.__STUB_BALANCE__ = BIGV.toString();
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23"; signer = {}; walletChainId = CHAIN.id; walletIsRemote = false;
            balances[balKey(tokenIn)] = BIGV; allowance = BIGV; allowanceKnown = true;
            baseSimArmedKey = null; baseSimFailedKey = null;
            console.error = () => {};
            E.Contract = function () {
                const send = function () { throw new Error("probe: stop before sending"); };
                send.staticCall = async (...a) => { if (JSON.stringify(a[0]) === JSON.stringify(a[1])) return 1n; throw new Error('execution reverted: "probe: every route fails"'); };
                send.estimateGas = async () => { throw new Error("x"); };
                return { executeSwap: send };
            };
            try { await doSwap(); } catch (e) {}
            E.Contract = realContract; console.error = realErr; delete window.__STUB_BALANCE__;
        }""")
        os.makedirs("/tmp/claude-0/sim_shots", exist_ok=True)
        await pg.emulate_media(color_scheme="light")
        sim_old_theme = await pg.evaluate("() => { const t = theme; theme = 'light'; applyTheme(); return t; }")
        for vw_ in (1440, 390):
            await pg.set_viewport_size({"width": vw_, "height": 1000})
            await pg.wait_for_timeout(300)
            await pg.screenshot(path="/tmp/claude-0/sim_shots/base-warning-light-%d.png" % vw_)
        await pg.set_viewport_size({"width": 1240, "height": 1000})
        await pg.emulate_media(color_scheme="dark")
        await pg.evaluate("(t) => { theme = t; applyTheme(); baseSimArmedKey = null; baseSimFailedKey = null; }", sim_old_theme)

        await pg.evaluate("""() => {
            account = null; signer = null; walletChainId = null; walletIsRemote = false;
            balances = {}; allowance = 0n; allowanceKnown = false;
            delete window.__STUB_ALLOWANCE__; setNotice("");
        }""")
        await pg.fill("#amtIn", "900000"); await pg.wait_for_timeout(2500)

        # ---- 4. multi-hop ----
        for target, sym in (("#tokInBtn", "cbBTC"), ("#tokOutBtn", "DAI")):
            await pg.click(target); await pg.wait_for_timeout(200)
            await pg.fill("#tokSearch", sym); await pg.wait_for_timeout(250)
            await pg.click(".trow"); await pg.wait_for_timeout(300)
        await pg.fill("#amtIn", "1")
        await pg.wait_for_timeout(3500)
        print("[multihop cbBTC->DAI] out=%s  route=%s" % (
            await pg.input_value("#amtOut"), (await pg.inner_text("#routeBody")).replace("\n", " | ")))

        # ---- 5. THE regression test: outage must read as unknown, never "no route"
        await pg.evaluate("""() => {
            readProvider.call = async () => { throw new Error('fetch failed'); };
            rotateRpc = () => {};
        }""")
        await pg.fill("#amtIn", "5")
        await pg.wait_for_timeout(3500)
        msg = await pg.inner_text("#notices")
        print("[rpc down] %s" % msg.replace("\n", " "))
        assert "did not answer" in msg, "outage misreported: " + msg
        assert "No route" not in msg, "outage reported as 'no route'"

        # ---- 6. wallet menu + light theme ----
        await pg.reload(); await pg.wait_for_timeout(900)
        await pg.fill("#amtIn", "1000"); await pg.wait_for_timeout(3000)
        await pg.evaluate("""() => {
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id;
            paintWallet();
        }""")
        await pg.click("#connectBtn"); await pg.wait_for_timeout(150)
        assert await pg.locator("#walletPop").evaluate("e => e.classList.contains('on')"), \
            "a connected wallet must open its account menu"
        # کلید تم عمداً از منوی والت به تنظیمات رفته: ظاهر سایت ربطی به
        # «کدام حساب وصل است» ندارد و بدون والت هم باید در دسترس باشد.
        assert await pg.locator("#walletPop #themeBtn").count() == 0, \
            "the theme switch belongs in Settings, not in the wallet menu"
        await pg.keyboard.press("Escape")
        await pg.click("#setBtn"); await pg.wait_for_timeout(200)
        assert await pg.locator("body>header #themeBtn").count() == 1, \
            "the theme switch must be directly reachable in the header"
        await pg.click("#themeBtn"); await pg.wait_for_timeout(300)
        assert await pg.get_attribute("html", "data-theme") == "light"
        assert await pg.inner_text("#themeState") == "Light"
        print("[theme] moved to Settings, toggles to %s"
              % await pg.get_attribute("html", "data-theme"))
        await pg.keyboard.press("Escape")
        await pg.screenshot(path=os.path.join(HERE, "shot-light.png"), full_page=True)

        # ---- 6b. فوتر باید ته صفحه بماند، در هر سه نما ----
        # صفحه‌های Portfolio و Money Flow وقتی خالی‌اند کوتاه‌ترند؛ قبلاً فوتر
        # می‌چسبید زیر محتوا و وسط صفحه شناور می‌شد.
        foot = {}
        for view in ["swap", "folio", "flow"]:
            await go_view(pg, view); await pg.wait_for_timeout(400)
            foot[view] = await pg.evaluate("""() => {
                const f = document.querySelector("footer").getBoundingClientRect();
                return {bottom: Math.round(f.bottom), vh: innerHeight,
                        docH: Math.round(document.documentElement.scrollHeight)};
            }""")
            print("[footer %s] bottom=%s viewport=%s doc=%s"
                  % (view, foot[view]["bottom"], foot[view]["vh"], foot[view]["docH"]))
            f = foot[view]
            assert f["bottom"] >= f["vh"] - 4, \
                ("the footer floats mid-page on the %s view: it ends at %s in a %s viewport"
                 % (view, f["bottom"], f["vh"]))
        # ---- 6c. پانویس نثری باید یک جمله‌ی پیوسته باشد، نه ستون‌های کنار هم ----
        # این پانویس‌ها از .frow استفاده می‌کردند و .frow یک ردیف فلکس است، پس
        # <b> وسط جمله یک آیتم فلکس می‌شد و ستون خودش را می‌گرفت. روی صفحه
        # این‌طور دیده می‌شد: «…This is | flow, not a forecast | : it shows…».
        # سنجه دقیقاً همان چیزی است که چشم می‌دید: عبارت پررنگ باید از هر دو
        # طرف به متن چسبیده باشد. در حالت فلکس، `gap:11px` هر طرف یازده پیکسل
        # فاصله می‌انداخت و `align-items:center` تکه‌ها را روی خط‌های متفاوت
        # می‌نشاند. با display هم می‌سنجیم تا برگشت به .frow از هر دو طرف بیفتد.
        # (دو سنجه‌ی دیگر را امتحان کردم و کنار گذاشتم چون باگ را جدا نمی‌کردند:
        #  «عرض تکه‌ها» — تکه‌ی اول به‌درستی وسط سطر تمام می‌شود؛ و «شروع افقی
        #  سطرها» — client rects به‌ازای هر تکه‌ی متن است، نه هر سطر.)
        await go_view(pg, "flow"); await pg.wait_for_timeout(1200)
        note = await pg.evaluate("""() => {
            const el = document.querySelector("#flowBody .fnote");
            if (!el) return {missing: true};
            const b = el.querySelector("b");
            if (!b) return {noBold: true};
            const cs = getComputedStyle(el), br = b.getBoundingClientRect();
            const edge = (start, end) => {
                const r = document.createRange();
                r.setStart(start[0], start[1]); r.setEnd(end[0], end[1]);
                const list = [...r.getClientRects()].filter(x => x.width > 1);
                return list.length ? list : null;
            };
            const before = edge([el.firstChild, 0], [b, 0]);
            const after  = edge([b, b.childNodes.length], [el.lastChild, el.lastChild.length]);
            const bl = before[before.length - 1], af = after[0];
            return {display: cs.display,
                    gapBefore: Math.round(br.left - bl.right),
                    lineBefore: Math.abs(br.top - bl.top) < 6,
                    gapAfter: Math.round(af.left - br.right),
                    lineAfter: Math.abs(af.top - br.top) < 6};
        }""")
        assert not note.get("missing"), "the Flow footnote is gone"
        assert not note.get("noBold"), "the Flow footnote lost the bold phrase this probe watches"
        print("[prose note] display=%s | bold touches text: before %spx/line=%s  after %spx/line=%s"
              % (note["display"], note["gapBefore"], note["lineBefore"],
                 note["gapAfter"], note["lineAfter"]))
        assert note["display"] == "block", \
            ("the prose footnote is display:%s — a flex parent turns the <b> mid-sentence "
             "into its own column" % note["display"])
        assert note["gapBefore"] <= 3 and note["lineBefore"], \
            ("the bold phrase is detached from the text before it: %spx away, same line=%s"
             % (note["gapBefore"], note["lineBefore"]))
        assert note["gapAfter"] <= 3 and note["lineAfter"], \
            ("the sentence does not continue straight after the bold phrase: %spx away, "
             "same line=%s" % (note["gapAfter"], note["lineAfter"]))

        # ---- 6d. حالت خالی باید بگوید صفحه چیست و راهِ ورود بدهد ----
        # این بلوک تنها چیزِ روی صفحه است وقتی والتی وصل نیست؛ یک جمله‌ی تنها
        # وسط صفحه‌ی خالی «اینجا چیزی نیست» خوانده می‌شد.
        # ⚠️ دکمه با delegation وصل است چون #folioBody با innerHTML بازنویسی
        # می‌شود. اینجا عمداً اول یک رندرِ دوباره می‌گیریم و بعد کلیک می‌کنیم —
        # یک onclick مستقیم دقیقاً همین‌جا می‌افتاد.
        # تا اینجای تست یک والت وصل شده، پس برای دیدن حالت خالی موقتاً قطعش
        # می‌کنیم. رندرِ دوباره هم عمداً همین‌جاست: کلیکِ بعدی روی محتوایی
        # می‌افتد که تازه با innerHTML ساخته شده.
        await go_view(pg, "folio"); await pg.wait_for_timeout(500)
        await pg.evaluate("window.__acct = account; account = null; renderFolio();")
        await pg.wait_for_timeout(400)
        intro = await pg.evaluate("""() => {
            const el = document.querySelector("#folioBody .empty.intro");
            if (!el) return {missing: true};
            const p = el.querySelector("p");
            return {h: Math.round(el.getBoundingClientRect().height),
                    title: (el.querySelector(".eTtl") || {textContent: ""}).textContent.trim(),
                    words: p ? p.textContent.trim().split(/\\s+/).length : 0,
                    btn: !!el.querySelector('[data-act="connect"]')};
        }""")
        assert not intro.get("missing"), "the portfolio empty state lost its intro block"
        print("[empty intro] height=%s title=%r body=%s words button=%s"
              % (intro["h"], intro["title"][:44], intro["words"], intro["btn"]))
        assert intro["h"] >= 280, \
            "the empty state is only %spx tall — it reads as a stub on a blank page" % intro["h"]
        assert intro["title"] and intro["words"] >= 6 and intro["btn"], \
            "the empty state needs a heading, a sentence of explanation and a way in"
        await pg.click('#folioBody [data-act="connect"]'); await pg.wait_for_timeout(400)
        assert await pg.evaluate('document.getElementById("walletOv").classList.contains("on")'), \
            ("the empty-state button did not open the wallet picker after a re-render "
             "— the delegated listener is gone")
        await pg.keyboard.press("Escape"); await pg.wait_for_timeout(250)
        await pg.evaluate("account = window.__acct; renderFolio();")
        await pg.wait_for_timeout(300)

        await pg.click('.nav button[data-view="swap"]'); await pg.wait_for_timeout(400)

        # ---- 7. settings + picker ----
        await pg.click("#setBtn"); await pg.wait_for_timeout(250)
        await pg.click('#slipSeg [data-bps="100"]'); await pg.wait_for_timeout(300)
        print("[slippage 1%%] min=%s" % await pg.inner_text("#kMin"))
        await pg.keyboard.press("Escape")
        await pg.click("#tokOutBtn"); await pg.wait_for_timeout(400)
        await pg.screenshot(path=os.path.join(HERE, "shot-picker.png"))
        await pg.keyboard.press("Escape")

        # ---- 8. mobile wallet menu ----
        mob = await b.new_page(viewport={"width": 390, "height": 844}, color_scheme="dark")
        await mob.goto(URL); await mob.wait_for_timeout(1000)
        await mob.evaluate("""() => {
            account = "0x8A0Dcb583C8CAdc481E34487c34f1B856fe97e23";
            walletChainId = CHAIN.id;
            paintWallet();
        }""")
        # ---- 8a. روی گوشی کارت سواپ باید بالای نمودار باشد ----
        # زیر ۹۴۱ پیکسل ستون یکی می‌شود و ترتیب DOM حکم می‌کرد، یعنی نمودار
        # اول می‌آمد و کارِ اصلی صفحه کامل زیر خط تاشو می‌افتاد.
        # دو ادعا، چون هرکدام جدا می‌تواند بشکند: ترتیب روی گوشی عوض شده باشد،
        # و ترتیب روی دسکتاپ عوض *نشده* باشد.
        # ۱۸ اکتبر [mobile compact]: فقط کارتِ تبِ انتخاب‌شده دیده می‌شود و توکنِ پیش‌فرضِ هارنس تبِ Exit check را
        # خودکار انتخاب می‌کند؛ این کاوشگر جای کارتِ نمودار را می‌سنجد، پس تبِ Chart را صریحاً انتخاب می‌کند.
        await mob.evaluate("mtabSelect('chart', false)")
        order = await mob.evaluate("""() => {
            const c = [...document.querySelectorAll("#baseHeroRow .swapChartCard, #baseHeroRow .swapCard")];
            const swap = c.find(x => x.querySelector("#amtIn"));
            const chart = c.find(x => x.querySelector("#plot"));
            const cta = document.getElementById("actBtn");
            return {swapTop: Math.round(swap.getBoundingClientRect().top + scrollY),
                    chartTop: Math.round(chart.getBoundingClientRect().top + scrollY),
                    ctaBottom: Math.round(cta.getBoundingClientRect().bottom + scrollY),
                    vh: innerHeight};
        }""")
        print("[mobile order] swap top=%s chart top=%s | swap CTA ends at %s of %s"
              % (order["swapTop"], order["chartTop"], order["ctaBottom"], order["vh"]))
        assert order["swapTop"] < order["chartTop"], \
            ("on a phone the swap card sits below the chart (%s vs %s) — the main action "
             "is pushed off the first screen" % (order["swapTop"], order["chartTop"]))
        assert order["ctaBottom"] <= order["vh"], \
            ("the swap button ends at %s in a %s viewport — it no longer fits the first screen"
             % (order["ctaBottom"], order["vh"]))

        await mob.click("#connectBtn"); await mob.wait_for_timeout(150)
        mobile_menu = await mob.evaluate("""() => {
            const el = document.getElementById("walletPop"), box = el.getBoundingClientRect();
            // آیکون قطع اتصال: قبلاً یک حرف یونیکد («⏻») بود که روی گوشی فونت
            // ندارد و جایش خالی می‌ماند. «وجود عنصر» کافی نیست — باید واقعاً
            // ابعاد رسم‌شده داشته باشد و SVG باشد، نه متنی که به فونت وابسته است.
            const d = document.getElementById("disconnectBtn");
            const ic = d && d.querySelector("svg");
            const ib = ic ? ic.getBoundingClientRect() : null;
            return {open: el.classList.contains("on"), left: box.left, right: box.right,
                    width: innerWidth, disconnect: !!d,
                    iconIsSvg: !!ic, iconW: ib ? Math.round(ib.width) : 0,
                    iconH: ib ? Math.round(ib.height) : 0};
        }""")
        print("[wallet menu mobile] open=%s left=%.0f right=%.0f viewport=%s"
              % (mobile_menu["open"], mobile_menu["left"], mobile_menu["right"], mobile_menu["width"]))
        print("[disconnect icon] svg=%s size=%sx%s"
              % (mobile_menu["iconIsSvg"], mobile_menu["iconW"], mobile_menu["iconH"]))
        assert mobile_menu["open"] and mobile_menu["left"] >= 0 and mobile_menu["right"] <= mobile_menu["width"], \
            "wallet menu must remain usable inside a mobile viewport"
        assert mobile_menu["disconnect"], "disconnect must be inside the wallet menu on mobile too"
        assert mobile_menu["iconIsSvg"], \
            "the disconnect icon must be inline SVG — a unicode glyph is missing on many phone fonts"
        assert mobile_menu["iconW"] >= 10 and mobile_menu["iconH"] >= 10, \
            "the disconnect icon renders with no size: %sx%s" % (mobile_menu["iconW"], mobile_menu["iconH"])

        # ---- 8b. هر منوی بازشو باید کامل داخل صفحه‌ی گوشی جا شود ----
        # منوی تنظیمات با اضافه‌شدن ردیف Appearance بلندتر شد و از پایینِ
        # صفحه زد بیرون. سقف ارتفاع نداشت، پس هر ردیف تازه‌ای دوباره
        # می‌شکستش — این کاوشگر همه‌ی بازشوها را با هم می‌سنجد.
        await mob.keyboard.press("Escape")
        pops = []
        for opener, pop, label in [("#setBtn", "#setPop", "settings"),
                                   ("#connectBtn", "#walletPop", "wallet")]:
            await mob.click(opener); await mob.wait_for_timeout(220)
            box = await mob.evaluate("""sel => {
                const e = document.querySelector(sel), r = e.getBoundingClientRect();
                return {top: Math.round(r.top), bottom: Math.round(r.bottom),
                        left: Math.round(r.left), right: Math.round(r.right),
                        vw: innerWidth, vh: innerHeight,
                        scrolls: e.scrollHeight > e.clientHeight + 1};
            }""", pop)
            box["label"] = label
            pops.append(box)
            print("[pop %s mobile] top=%s bottom=%s left=%s right=%s viewport=%sx%s scrolls=%s"
                  % (label, box["top"], box["bottom"], box["left"], box["right"],
                     box["vw"], box["vh"], box["scrolls"]))
            await mob.keyboard.press("Escape"); await mob.wait_for_timeout(120)
        # ⚠️ عمداً `b` نه — نام مرورگر است و سایه‌انداختن رویش باعث شد
        #    await b.close() در انتهای تست بترکد.
        for pb in pops:
            assert pb["top"] >= 0 and pb["bottom"] <= pb["vh"], \
                ("the %s menu runs off the phone screen vertically: %s..%s in a %s-tall viewport"
                 % (pb["label"], pb["top"], pb["bottom"], pb["vh"]))
            assert pb["left"] >= 0 and pb["right"] <= pb["vw"], \
                ("the %s menu runs off the phone screen horizontally: %s..%s in a %s-wide viewport"
                 % (pb["label"], pb["left"], pb["right"], pb["vw"]))
        await mob.screenshot(path=os.path.join(HERE, "shot-mobile-wallet.png"))
        await mob.close()
        # ---- 9. [events] شمارش رویداد، روی سیم ----
        # دو نگهبان ثابتش بالاتر اجرا شده (check_event_allowlists). اینجا آنچه
        # *واقعاً* روی سیم می‌رود سنجیده می‌شود، نه آنچه فکر می‌کنیم می‌رود.
        # روی http سرو می‌شود چون sendBeacon روی file:// مقصدی ندارد.
        ev_page, ev_detail = EV_PAGE_NAMES, EV_DETAILS

        async def watch_events(page):
            seen = []
            async def grab(route):
                seen.append(route.request.post_data or "")
                await route.fulfill(status=204, body="")
            await page.route("**/ev", grab)
            return seen

        evpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        ev_seen = await watch_events(evpg)
        await evpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await evpg.wait_for_timeout(1400)
        for v in ("folio", "flow", "swap"):
            await go_view(evpg, v)
            await evpg.wait_for_timeout(320)
        await evpg.close()

        import json as _json
        # فقط برای سه رویدادِ err: بازتر شده — همان شکلِ چهار-رقمِ بزرگی که
        # Worker می‌پذیرد (worker/test.mjs قسمتِ «ح» را می‌سنجد). برای هر
        # رویدادِ دیگری detail همچنان باید از ev_detail (فهرست بسته) بیاید.
        EV_ERR_HEX = re.compile(r"^[0-9A-F]{4}$")
        ev_names = []
        for raw in ev_seen:
            body = _json.loads(raw)
            assert set(body) == {"e", "d", "v", "c"} and body["c"] in ("base", "solana"), "a beacon carried unexpected fields: %s" % raw
            assert body["e"] in ev_page, "a beacon carried an unknown event name: %s" % raw
            is_err = body["e"].startswith("err:")
            assert body["d"] in ev_detail or (is_err and EV_ERR_HEX.match(body["d"])), (
                "a beacon carried an unknown detail: %s" % raw)
            assert body["v"] in ("desktop", "mobile"), "a beacon carried an odd surface: %s" % raw
            assert "0x" not in raw, "AN ADDRESS REACHED THE ANALYTICS BEACON: %s" % raw
            ev_names.append(body["e"])
        print("[events] beacons on the wire: %s" % ev_names)
        for want in ("load", "view:swap", "view:folio", "view:flow"):
            assert want in ev_names, "the %r event never reached the wire (got %s)" % (want, ev_names)
        assert ev_names.count("load") == 1, "the load event fired %d times" % ev_names.count("load")

        # ---- [events] صفحه‌ی معرفی، روی سیم ----
        # تا ۱۴ سپتامبر ۲۰۲۶ این صفحه هیچ رویدادی نداشت، پس نرخِ تبدیل کور
        # بود. دو نام و نه بیشتر، و هر دو باید *واقعاً* برسند — نه اینکه فقط
        # در فهرست باشند. ⚠️ کلیک روی لینکِ اپ با یک شنونده‌ی فازِ گرفتن خنثی
        # می‌شود، نه با عوض‌کردنِ href: اگر href را دست بزنیم دیگر همان چیزی
        # را نسنجیده‌ایم که کاربر روی آن کلیک می‌کند.
        lndpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        lnd_seen = await watch_events(lndpg)
        await lndpg.goto("http://127.0.0.1:%d/landing.html" % port)
        await lndpg.wait_for_timeout(700)
        await lndpg.evaluate(
            "() => document.addEventListener('click', e => e.preventDefault(), true)")
        await lndpg.click('a[href^="/app"]')
        await lndpg.wait_for_timeout(400)
        await lndpg.close()
        lnd_names = []
        for raw in lnd_seen:
            body = _json.loads(raw)
            assert set(body) == {"e", "d", "v"}, (
                "a landing-page beacon carried unexpected fields: %s" % raw)
            assert body["d"] == "", (
                "a landing-page beacon carried a detail; that page has nothing to say in one "
                "and an open detail is how user data leaks into a counter: %s" % raw)
            assert body["v"] in ("desktop", "mobile"), (
                "a landing-page beacon carried an odd surface: %s" % raw)
            assert "0x" not in raw, (
                "AN ADDRESS REACHED THE ANALYTICS BEACON: %s" % raw)
            lnd_names.append(body["e"])
        print("[events] landing page on the wire: %s" % lnd_names)
        for want in ("view:home", "cta:app"):
            assert want in lnd_names, (
                "the landing page never sent %r (got %s). Without both of them the only "
                "number that page exists to produce \u2014 how many readers become users "
                "\u2014 cannot be computed." % (want, lnd_names))
        assert lnd_names.count("view:home") == 1, (
            "view:home fired %d times on one load" % lnd_names.count("view:home"))

        # همان «نه»ی صریح، روی صفحه‌ی معرفی هم — یک مکانیزمِ دوم یعنی یک روز
        # یکی‌شان ساکت نمی‌ماند.
        lgpc = await b.new_page(viewport={"width": 1240, "height": 1000})
        await lgpc.add_init_script(
            "Object.defineProperty(navigator,'globalPrivacyControl',{get:()=>true});")
        lgpc_seen = await watch_events(lgpc)
        await lgpc.goto("http://127.0.0.1:%d/landing.html" % port)
        await lgpc.wait_for_timeout(700)
        await lgpc.evaluate(
            "() => document.addEventListener('click', e => e.preventDefault(), true)")
        await lgpc.click('a[href^="/app"]')
        await lgpc.wait_for_timeout(300)
        await lgpc.close()
        print("[events] landing page with Global Privacy Control on: %d beacons"
              % len(lgpc_seen))
        assert not lgpc_seen, (
            "Global Privacy Control must silence the landing page too: %s" % lgpc_seen)

        # ---- لینک بررسی: کسی که بازش می‌کند بدون کیف پول جواب می‌گیرد ----
        # این تنها راه رشد بدون تبلیغات است که در خودِ محصول هست: سؤالی که در
        # گروه‌ها پرسیده می‌شود «این توکن سالم است؟»، و جوابش هیچ ریسکی برای
        # پرسنده ندارد. اگر لینک باز نشود یا شمرده نشود، آن حلقه وجود ندارد.
        srcpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await srcpg.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await srcpg.wait_for_timeout(1200)
        # دکمه‌ی کپی نباید منتظر عدد بماند: لینک به *توکن* اشاره می‌کند نه به
        # یک کوت. روی صفحه‌ی تازه، با فیلد مبلغ خالی، باید همان‌جا دیده شود.
        share_amt = await srcpg.input_value("#amtIn")
        share_seen = await srcpg.is_visible("#checkShare")
        built = await srcpg.evaluate("() => tokenPageUrl() || checkUrl()")
        await srcpg.close()
        print("[check button] visible with an empty amount: %s (amount=%r)"
              % (share_seen, share_amt))
        assert share_amt == "", "the probe expected a fresh page with no amount typed"
        assert share_seen, (
            "the copy-check button only appears once a quote exists. The link points at a "
            "token, not at a quote, so it has no reason to wait for a number.")
        ck_path = built[built.index("/", 8):]   # پس از «http://host»
        # ⚠️ صفحه‌ی *تازه*. رفتن به همان سند با هشِ دیگر فقط hashchange می‌دهد،
        # نه بارگذاری — و تلاش اول همین بود و پنل خالی می‌ماند، که باگ لینک
        # نبود، باگ خودِ تست بود. گیرنده‌ی واقعی هم صفحه را از نو باز می‌کند.
        ckpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        ck_seen = await watch_events(ckpg)
        await ckpg.goto("http://127.0.0.1:%d%s" % (port, ck_path))
        await ckpg.wait_for_timeout(4500)
        ck_box = (await ckpg.inner_text("#tk-exitBox")).replace("\n", " ")
        ck_out = await ckpg.inner_text("#tk-sym")
        ck_stats = (await ckpg.inner_text("#tk-tokStats")).replace("\n", " ")
        ck_risk = (await ckpg.inner_text("#tk-safetyBody")).replace("\n", " ")
        # هیچ اسکلتی نباید بعد از نشستن صفحه باقی بماند: اسکلتِ جامانده یعنی
        # چیزی هرگز نرسیده و کاربر به یک درخشش بی‌پایان نگاه می‌کند.
        ck_sk = await ckpg.eval_on_selector_all("#view-token .sk", "els => els.length")
        ck_score = await ckpg.inner_text("#tk-score")
        ck_swap_open = await ckpg.is_visible("#view-swap.on")
        # «Trade now» باید همان توکن را به فرم سواپ ببرد، نه اینکه صفحه را
        # از نو باز کند یا انتخاب را بریزد.
        # ⚠️ کلیک مشروط است. اگر صفحه‌ی توکن اصلاً باز نشده باشد، کلیک روی
        # دکمه‌ای که وجود ندارد ۳۰ ثانیه تایم‌اوت می‌دهد و پیامش «element is
        # not visible» است — که علت را پنهان می‌کند. این‌طور، همان ادعای
        # بالاتر که علت را می‌داند حرف می‌زند.
        ck_traded, ck_carried, ck_amt = False, "", ""
        if await ckpg.is_visible("#tk-trade"):
            await ckpg.click("#tk-trade")
            await ckpg.wait_for_timeout(1200)
            ck_traded = await ckpg.is_visible("#view-swap.on")
            ck_carried = await ckpg.inner_text("#tokOutSym")
            ck_amt = await ckpg.input_value("#amtIn")
        ck_names = [_json.loads(r)["e"] for r in ck_seen]
        await ckpg.close()
        print("[token page] %s -> %s | %s" % (ck_path, ck_out, ck_box[:52]))
        print("[token page] stats=%r risk=%r" % (ck_stats[:44], ck_risk[:44]))

        # ---- [stats] رد جفت مارکت‌کپ/FDV محال ----
        # روی همان تابع واقعی renderTokenStats و همان گره‌ی DOM واقعی، نه یک
        # کپی جدا از منطق. صفحه‌ی توکن را دوباره باز می‌کنیم چون tokenOut و
        # metaCache فقط آنجا برپا هستند؛ metaCache را موقتاً برای یک آدرس
        # سیم‌پیچی می‌کنیم تا داده‌ی ساختگی از همان مسیری بگذرد که داده‌ی
        # واقعی می‌گذرد.
        stpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await stpg.goto("http://127.0.0.1:%d%s" % (port, ck_path))
        await stpg.wait_for_timeout(3000)

        async def stats_case(fx):
            return await stpg.evaluate("""(fx) => {
                const key = (tokenOut.native ? WETH_ADDR : tokenOut.address).toLowerCase();
                const had = key in metaCache, orig = metaCache[key];
                metaCache[key] = fx;
                return renderTokenStats(tokenOut).then(() => {
                    const box = document.getElementById(tokenPage ? "tk-tokStats" : "tokStats");
                    const text = box.innerText;
                    if (had) metaCache[key] = orig; else delete metaCache[key];
                    return text;
                });
            }""", fx)

        fx_impossible = {"market_cap_usd": "72860000000", "fdv_usd": "4260000000",
                          "volume_usd": {"h24": "1000000"}, "total_reserve_in_usd": "500000"}
        fx_normal = {"market_cap_usd": "34670000", "fdv_usd": "212500000",
                     "volume_usd": {"h24": "1000000"}, "total_reserve_in_usd": "500000"}
        fx_tol = {"market_cap_usd": "100000000", "fdv_usd": "100000000",
                  "volume_usd": {"h24": "1000000"}, "total_reserve_in_usd": "500000"}

        txt_impossible = await stats_case(fx_impossible)
        txt_normal = await stats_case(fx_normal)
        txt_tol = await stats_case(fx_tol)
        await stpg.close()

        print("[stats] impossible pair is refused: mc=%r fdv=%r note=%s"
              % (fx_impossible["market_cap_usd"], fx_impossible["fdv_usd"],
                 "impossible" in txt_impossible))
        assert "$72.86B" not in txt_impossible and "$4.26B" not in txt_impossible, \
            "an impossible market cap/FDV pair was printed anyway: %r" % txt_impossible[:200]
        assert "impossible" in txt_impossible, \
            "the impossible-pair note never appeared: %r" % txt_impossible[:200]
        assert "$1.00M" in txt_impossible, \
            "hiding the impossible pair also hid volume, which was not implicated: %r" \
            % txt_impossible[:200]
        assert "$34.67M" in txt_normal and "$212.50M" in txt_normal, \
            "a legitimate market cap/FDV pair was hidden: %r" % txt_normal[:200]
        assert "impossible" not in txt_normal, \
            "a legitimate pair triggered the impossible-pair note: %r" % txt_normal[:200]
        assert "impossible" not in txt_tol, \
            "an equal market cap and FDV (fully circulating supply) was flagged as " \
            "impossible: %r" % txt_tol[:200]

        assert re.match(r"^/t/0x[0-9a-fA-F]{40}$", ck_path), \
            "the share button did not build a token-page link: %s" % ck_path
        assert not ck_swap_open, (
            "opening a token link still lands the reader on the swap form. They came with a "
            "question, not with a trade to place.")
        assert ck_out.strip() and ck_out != "—", \
            "the token page never named the token: %r" % ck_out
        assert ck_box.strip(), (
            "the token page shows an empty exit panel — the whole point is that the answer "
            "is already there when the page opens")
        assert ck_risk.strip() and "Reading the token" not in ck_risk, \
            "the risk panel never finished: %r" % ck_risk[:80]
        assert ck_stats.strip(), \
            "the token page shows no market figures: %r" % ck_stats[:80]
        assert ck_sk == 0, (
            "%d loading skeletons are still on the page after it settled — something never "
            "arrived and the reader is left looking at a shimmer." % ck_sk)
        assert ck_score.strip() not in ("", "0"), (
            "the risk score never counted up from zero (still %r). The ring animates from 0 "
            "on purpose; if it stops there, the scan result never reached the ring."
            % ck_score)
        assert ck_traded, "Trade now did not open the swap form"
        assert ck_amt == "", (
            "Trade now carried an amount into the swap form (%r). The figure on the token "
            "page is a reference size for the simulation, not an order the reader placed — "
            "and quoting it spends RPC calls nobody asked for." % ck_amt)
        assert ck_carried.strip() == ck_out.strip(), (
            "Trade now dropped the token the reader came for: page said %r, the form says %r"
            % (ck_out, ck_carried))
        assert "check:open" in ck_names, (
            "the check-link visit was not counted (%s). Without it there is no way to tell "
            "whether shared links bring anyone." % ck_names)

        # ---- 2b-sexies. Bug 3+4 رگرسیون: نوار ناوبری هم باید صفحه‌ی توکن را ترک کند ----
        # ریشه‌ی مشترک هر دو باگ یکی بود: setView هرگز tokenPage را خاموش
        # نمی‌کرد. دکمه‌ی Trade خودش دستی درستش می‌کرد، ولی نوار بالای صفحه
        # از کنارش رد می‌شد — کلیک روی Swap در ناوبری، tokenPage را روشن
        # نگه می‌داشت. اینجا از همان مسیر واقعی، نه دکمه‌ی Trade، عبور می‌کنیم.
        navpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await navpg.goto("http://127.0.0.1:%d%s" % (port, ck_path))
        await navpg.wait_for_timeout(4500)
        await navpg.click('#nav [data-view="swap"]')
        await navpg.wait_for_timeout(600)
        nv_tokenPage = await navpg.evaluate("() => tokenPage")
        nv_amt = await navpg.input_value("#amtIn")
        nv_hash = await navpg.evaluate("() => location.hash")
        nv_path = await navpg.evaluate("() => location.pathname")
        nv_safety = await navpg.inner_text("#safetyBody")
        await navpg.go_back()
        await navpg.wait_for_function('() => tokenPage && location.pathname.startsWith("/t/")')
        assert await navpg.locator("#view-token").is_visible()
        await navpg.go_forward()
        await navpg.wait_for_function('() => !tokenPage && location.pathname === "/app"')
        assert await navpg.locator("#view-swap").is_visible()
        await navpg.close()
        print("[token page] nav out of token page resets: tokenPage=%s amtIn=%r hash=%s path=%s"
              % (nv_tokenPage, nv_amt, nv_hash, nv_path))
        assert nv_tokenPage is False, (
            "clicking the nav Swap button left tokenPage=%r on — panel() still points at the "
            "hidden tk-* nodes instead of the main view" % nv_tokenPage)
        assert nv_amt == "", (
            "the nav Swap button carried the token page's reference amount into #amtIn (%r) — "
            "it now looks like an order the reader placed" % nv_amt)
        # ⚠️ «/app» نه «/». این ادعا تا ۱۴ سپتامبر ۲۰۲۶ «/» را می‌خواست، چون
        # leaveTokenPage آدرس را به ریشه می‌فرستاد — و از روزی که صفحه‌ی معرفی
        # روی ریشه نشست، آن یعنی «آدرسِ اپ را به آدرسِ صفحه‌ی معرفی عوض کن».
        # pushState چیزی بار نمی‌کند، پس هیچ‌چیز بلافاصله نمی‌شکست؛ ولی یک رفرش
        # کاربر را از اپ بیرون می‌انداخت و لینک‌های داخلیِ صفحه‌ی توکن یکی‌درمیان
        # به یک ناوبریِ واقعی تبدیل می‌شدند. مقصدِ درست مسیرِ خودِ اپ است.
        assert nv_hash == "#swap" and nv_path == "/app", (
            "leaving the token page put the address at hash=%s path=%s. It must be the app's "
            "own path: '/' is the landing page, and parking the address there means a refresh "
            "drops the visitor out of the app." % (nv_hash, nv_path))
        assert "Pick a token to scan" not in nv_safety, (
            "the main view's safety card is still showing the initial placeholder after leaving "
            "the token page: %r" % nv_safety[:120])

        # ---- [sol token page] /t/<mint سولانا> — حالتِ فقط-چک ----
        # هیچ ethersای، هیچ verifyDexesای، هیچ کیف‌پولی. GT و /vd هر دو با
        # page.route کنترل می‌شوند — این کانتینر به هیچ GeckoTerminal یا
        # Solana RPC واقعی دسترسی ندارد. درخواست‌های واقعی (نه یک پرچمِ
        # جاوااسکریپتی که می‌تواند دروغ بگوید) با page.on("request") ثبت
        # می‌شوند تا ثابت شود ethers هرگز خواسته نمی‌شود.
        SOL_MINT = "So11111111111111111111111111111111111111112"

        def gt_solana_body():
            return _json.dumps({"data": {"attributes": {
                "name": "Wrapped SOL", "symbol": "SOL",
                "price_usd": "150.25", "decimals": 9,
                "market_cap_usd": "1000000000", "fdv_usd": "1200000000",
                "volume_usd": {"h24": "45000000"}, "total_reserve_in_usd": "30000000",
            }}})

        async def open_sol_page(verdict_body, dev=False):
            seen_urls = []
            spg = await b.new_page(viewport={"width": 1240, "height": 1000})
            # Transaction fixtures use fixed non-signing keys; real approval is tested in solana-approval.test.mjs.
            await spg.add_init_script("window.addEventListener('load',()=>{solConfirmConnection=async()=>{};});")
            spg.on("request", lambda req: seen_urls.append(req.url))
            async def stub_gt(route):
                await route.fulfill(status=200, content_type="application/json", body=gt_solana_body())
            async def stub_vd(route):
                await route.fulfill(status=200, content_type="application/json",
                                     body=_json.dumps(verdict_body))
            await spg.route("**/gt/networks/solana/tokens/**", stub_gt)
            await spg.route("**/vd/**", stub_vd)
            suffix = "?dev=1" if dev else ""
            await spg.goto("http://127.0.0.1:%d/t/%s%s" % (port, SOL_MINT, suffix))
            await spg.wait_for_timeout(1500)
            return spg, seen_urls

        async def sol_state(spg):
            return await spg.evaluate("""() => ({
                sym: document.getElementById("tk-sym").textContent,
                name: document.getElementById("tk-name").textContent,
                addr: document.getElementById("tk-addr").textContent,
                chip: document.getElementById("tk-chip").textContent.trim(),  // ۳ اکتبر: چیپ حالا آیکونِ شبکه هم دارد
                noticeHidden: document.getElementById("tk-solNotice").hidden,
                noticeText: document.getElementById("tk-solNotice").textContent,
                stats: document.getElementById("tk-tokStats").innerText.replace(/\\n/g, " "),
                exitText: document.getElementById("tk-exitBox").innerText.replace(/\\n/g, " "),
                exitHtml: document.getElementById("tk-exitBox").innerHTML,
                tradeHidden: document.getElementById("tk-trade").hidden,
                walletHidden: document.getElementById("walletMenu").hidden,
                chartHidden: document.getElementById("tk-chartCard").hidden,
                safetyHidden: document.getElementById("tk-safetyBody").hidden,
                footTag: document.querySelector(".footTag").textContent,
                tokenPage: tokenPage,
            })""")

        # الف) sell — جمله‌ی دقیق، هویت و اعداد بازار درست، هیچ اقدامی پیشنهاد نمی‌شود
        sellpg, sell_urls = await open_sol_page({"v": "sell", "ms": 187})
        sell = await sol_state(sellpg)
        await sellpg.close()
        print("[sol token page] sym=%r name=%r chip=%r stats=%r"
              % (sell["sym"], sell["name"], sell["chip"], sell["stats"][:70]))
        print("[sol token page] exit(sell)=%r" % sell["exitText"][:70])
        assert sell["sym"] == "SOL" and sell["name"] == "Wrapped SOL", \
            "the Solana token page did not name the token: %s" % sell
        assert sell["chip"] == "Solana", "the identity chip still says Base on a Solana page: %r" % sell["chip"]
        # فوتر هم بخشی از همان ادعاست: روی یک صفحه‌ی سولانا نه استخری تجمیع
        # می‌شود و نه تراکنشی زده می‌شود، پس جمله‌ی صفحه‌ی Base آن‌جا دروغ است.
        assert "One transaction, every pool" not in sell["footTag"], (
            "the footer still promises the Base pitch on a Solana page: %r" % sell["footTag"])
        assert "Solana" in sell["footTag"], (
            "the footer on a Solana page says nothing about Solana: %r" % sell["footTag"])
        assert "$1.00B" in sell["stats"] and "$1.20B" in sell["stats"] and \
               "$45.00M" in sell["stats"] and "$30.00M" in sell["stats"], \
            "the Solana token page is missing its market numbers: %r" % sell["stats"]
        # سواپ حالا زنده است — بنرِ «هنوز زنده نیست» دیگر نباید روی یک حکمِ
        # sell معلوم دیده شود؛ همان عنصر حالا فقط برای verdict نامعلوم پر
        # می‌شود (پایین‌تر، حالتِ «ج»).
        assert sell["noticeHidden"] is True and sell["noticeText"] == "", \
            "the old \"not live yet\" notice must stay empty/hidden once a sell route is confirmed: %r" % sell["noticeText"]
        assert "A sell route was quoted just now." in sell["exitText"], \
            "the \"sell\" verdict did not render its exact sentence: %r" % sell["exitText"]
        assert not sell["tradeHidden"] and not sell["walletHidden"], \
            "the swap CTA and/or the wallet button are not hidden on the Solana page: %s" % sell
        assert not sell["chartHidden"] and sell["safetyHidden"], \
            "a Base-only panel (chart or bytecode safety) is still shown on a Solana page: %s" % sell
        assert sell["tokenPage"] is True, "tokenPage was not set for a Solana token page"
        assert not any("ethers" in u for u in sell_urls), \
            "ethers was requested on the Solana read-only path: %s" % [u for u in sell_urls if "ethers" in u]

        # ب) nosell — جمله‌ی دقیق
        nopg, no_urls = await open_sol_page({"v": "nosell", "ms": 50})
        nosell = await sol_state(nopg)
        await nopg.close()
        print("[sol token page] exit(nosell)=%r" % nosell["exitText"][:70])
        assert "No sell route quoted — you may not be able to exit." in nosell["exitText"], \
            "the \"nosell\" verdict did not render its exact sentence: %r" % nosell["exitText"]
        assert not any("ethers" in u for u in no_urls), \
            "ethers was requested on the Solana read-only path (nosell case): %s" % no_urls

        # ج) نامعلوم (why بدونِ dev=1) — همان یک جمله، هرگز اطمینان‌بخش، هرگز سبز
        unkpg, unk_urls = await open_sol_page({"v": None, "ms": 10, "why": "jup:quote:500"})
        unknown = await sol_state(unkpg)
        await unkpg.close()
        print("[sol token page] exit(unknown)=%r" % unknown["exitText"][:70])
        assert "We could not check this right now." in unknown["exitText"], \
            "a null verdict (with a reason) did not render the exact unknown sentence: %r" % unknown["exitText"]
        assert "A sell route was quoted" not in unknown["exitText"] and \
               "No sell route quoted" not in unknown["exitText"], \
            "the unknown state also carries another verdict's sentence: %r" % unknown["exitText"]
        assert "var(--pos)" not in unknown["exitHtml"], \
            "the unknown state is painted green (var(--pos)) — it must never read as reassurance: %s" \
            % unknown["exitHtml"][:200]
        assert "jup:quote:500" not in unknown["exitText"], \
            "the raw why leaked without ?dev=1: %r" % unknown["exitText"]
        assert not any("ethers" in u for u in unk_urls), \
            "ethers was requested on the Solana read-only path (unknown case): %s" % unk_urls
        # نامعلوم بودنِ حکم = گیت روی خریدِ زنده هم روشن می‌شود — همان بنرِ
        # قدیمی حالا فقط این یک پیام را می‌گوید، نه متنِ ثابتِ «هنوز زنده
        # نیست» را.
        assert unknown["noticeHidden"] is False and \
            unknown["noticeText"] == "We could not confirm this token can be sold back.", \
            "an unconfirmed verdict must show the sell-back warning, got hidden=%s text=%r" \
            % (unknown["noticeHidden"], unknown["noticeText"])

        # د) همان نامعلوم، این‌بار زیرِ ?dev=1 — why خام باید کنارش بیاید
        devpg2, dev_urls = await open_sol_page({"v": None, "ms": 10, "why": "jup:quote:500"}, dev=True)
        devunknown = await sol_state(devpg2)
        await devpg2.close()
        print("[sol token page] exit(unknown, dev=1)=%r" % devunknown["exitText"][:90])
        assert "We could not check this right now." in devunknown["exitText"] and \
               "jup:quote:500" in devunknown["exitText"], \
            "?dev=1 did not surface the raw why next to the exact sentence: %r" % devunknown["exitText"]
        assert not any("ethers" in u for u in dev_urls), \
            "ethers was requested on the Solana read-only path (?dev=1 case): %s" % dev_urls

        print("[sol token page] identity, market numbers and all three verdict sentences render "
              "correctly; the unknown state carries no reassurance and is never painted green; "
              "the raw why only shows up under ?dev=1; ethers is never requested on any of the four "
              "runs above (checked against recorded network requests, not a JS-side flag)")

        # ---- [sol swap] سواپِ زنده‌ی سولانا ----
        # هیچ کیف‌پول واقعی، هیچ Jupiter/RPC واقعی. یک کیف‌پولِ جعلیِ
        # Wallet Standard با page.add_init_script تزریق می‌شود (پیش از هر
        # اسکریپتِ خودِ صفحه) و روی eventِ app-ready ثبت می‌شود؛ /sol/quote،
        # /sol/swap و /sol/rpc با page.route جایگزین می‌شوند — این کانتینر
        # به هیچ Jupiter یا Solana RPC واقعی دسترسی ندارد.
        SWAP_MINT = "DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263"
        SOL_MINT_ADDR = "So11111111111111111111111111111111111111112"
        SOL_FEE_PAYER = bytes(range(1, 33))
        SOL_WRONG_PAYER = bytes(range(101, 133))
        SOL_OTHER_KEY = bytes(range(50, 82))
        SOL_SIG_BYTES = bytes(range(1, 65))
        SOL_SIG_B58 = b58encode(SOL_SIG_BYTES)

        def build_v0_tx(fee_payer):
            # sigCount(1) + یک امضای صفر + پیشوندِ نسخه(0x80) + هدرِ ۳بایتی +
            # keyCount(2) + فی‌پیر + یک کلیدِ دیگر + blockhash + ۰ دستور + ۰ ALT.
            return (bytes([1]) + bytes(64) + bytes([0x80]) + bytes([1, 0, 1]) + bytes([2]) +
                    fee_payer + SOL_OTHER_KEY + bytes(32) + bytes([0]) + bytes([0]))

        SOL_GOOD_TX_B64 = base64.b64encode(build_v0_tx(SOL_FEE_PAYER)).decode()
        SOL_BAD_TX_B64 = base64.b64encode(build_v0_tx(SOL_WRONG_PAYER)).decode()

        SOL_QUOTE_FIXTURE = {
            "inputMint": "So11111111111111111111111111111111111111112",
            "outputMint": SWAP_MINT, "inAmount": "1000000000", "outAmount": "5000000000",
            "otherAmountThreshold": "4950000000", "priceImpactPct": "0.0123",
            "swapMode": "ExactIn", "slippageBps": 50,
            "routePlan": [{"swapInfo": {"label": "Whirlpool"}}, {"swapInfo": {"label": "Whirlpool"}},
                          {"swapInfo": {"label": "Meteora DLMM"}}],
        }

        def swap_gt_body():
            return _json.dumps({"data": {"attributes": {
                "name": "Test Swap Token", "symbol": "TSWP", "price_usd": "0.01", "decimals": 6,
                "market_cap_usd": "500000", "fdv_usd": "600000",
                "volume_usd": {"h24": "10000"}, "total_reserve_in_usd": "5000",
            }}})

        SOL_FAKE_WALLET_INIT = ("""
(function(){
  const FEE_PAYER = new Uint8Array(%s);
  const SIG_BYTES = new Uint8Array(%s);
  window.__solCalls = [];
  window.__solRejectSwap = false;
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async () => ({accounts: [
        {address: "FakeWa11etAddr11111111111111111111111111", publicKey: FEE_PAYER}]}) },
      "standard:disconnect": { disconnect: async () => {} },
      "solana:signAndSendTransaction": { signAndSendTransaction: async (input) => {
        window.__solCalls.push(Array.from(input.transaction));
        if (window.__solRejectSwap) { const e = new Error("User rejected the request."); e.code = 4001; throw e; }
        return [{signature: SIG_BYTES}];
      } }
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => {
    try { e.detail.register(fakeWallet); } catch(_){}
  });
})();
""" % (list(SOL_FEE_PAYER), list(SOL_SIG_BYTES)))

        # C — کیف‌پولی که signAndSendTransaction را با یک خطای *غیرِرد* می‌شکند
        # (دقیقاً همان "Expected String"ی که فانتوم روی زنجیره داد) ولی
        # signTransaction جدا هم دارد — برای سنجیدنِ fallbackِ Rule C.
        # window.__solRejectSwap=true یعنی رد صریحِ کاربر (کدِ ۴۰۰۱)، که هرگز
        # نباید به fallback برود.
        SOL_SIGNED_TX_BYTES = bytes([1]) + bytes(64) + bytes([9, 9, 9, 9])
        SOL_FALLBACK_WALLET_INIT = ("""
(function(){
  const FEE_PAYER = new Uint8Array(%s);
  const SIGNED = new Uint8Array(%s);
  window.__solSendCalls = [];
  window.__solSignCalls = [];
  window.__solRejectSwap = false;
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async () => ({accounts: [
        {address: "FakeWa11etAddr11111111111111111111111111", publicKey: FEE_PAYER}]}) },
      "standard:disconnect": { disconnect: async () => {} },
      "solana:signAndSendTransaction": { signAndSendTransaction: async (input) => {
        window.__solSendCalls.push(1);
        if (window.__solRejectSwap) { const e = new Error("User rejected the request."); e.code = 4001; throw e; }
        throw new Error("Expected String");
      } },
      "solana:signTransaction": { signTransaction: async (input) => {
        window.__solSignCalls.push(1);
        return [{signedTransaction: SIGNED}];
      } }
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => {
    try { e.detail.register(fakeWallet); } catch(_){}
  });
})();
""" % (list(SOL_FEE_PAYER), list(SOL_SIGNED_TX_BYTES)))

        # round 3 — کیف‌پولی که فقط signTransaction دارد (نه signAndSendTransaction)،
        # برای سنجیدنِ مسیرِ مستقیمِ ارسال (solSendAndHandle) بدونِ درگیرشدنِ
        # مسیرِ fallback. همان SIGNED جواب می‌دهد.
        SOL_SIGN_ONLY_WALLET_INIT = ("""
(function(){
  const FEE_PAYER = new Uint8Array(%s);
  const SIGNED = new Uint8Array(%s);
  window.__solSignCalls = [];
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async () => ({accounts: [
        {address: "FakeWa11etAddr11111111111111111111111111", publicKey: FEE_PAYER}]}) },
      "standard:disconnect": { disconnect: async () => {} },
      "solana:signTransaction": { signTransaction: async (input) => {
        window.__solSignCalls.push(1);
        return [{signedTransaction: SIGNED}];
      } }
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => {
    try { e.detail.register(fakeWallet); } catch(_){}
  });
})();
""" % (list(SOL_FEE_PAYER), list(SOL_SIGNED_TX_BYTES)))

        # round 3 — C: کیف‌پولی که options.silent را ضبط می‌کند و standard:events
        # هم دارد (برای سنجیدنِ change→disconnect). همیشه یک حساب برمی‌گرداند —
        # تفاوتِ «باید وصل شود» با «نباید» با همین ضبط و با off-flag سنجیده می‌شود.
        SOL_SILENT_CAPTURE_WALLET_INIT = ("""
(function(){
  const FEE_PAYER = new Uint8Array(%s);
  window.__solConnectOpts = [];
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async (opts) => {
        window.__solConnectOpts.push(opts || {});
        return {accounts: [{address: "FakeWa11etAddr11111111111111111111111111", publicKey: FEE_PAYER}]};
      } },
      "standard:disconnect": { disconnect: async () => {} },
      "standard:events": { on: (ev, cb) => { window.__solEventsCb = cb; return () => { window.__solEventsOff = true; }; } },
      "solana:signAndSendTransaction": { signAndSendTransaction: async () => [{signature: new Uint8Array(64)}] },
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => {
    try { e.detail.register(fakeWallet); } catch(_){}
  });
})();
""" % (list(SOL_FEE_PAYER),))

        # E — یک ردیفِ واقع‌شکلِ GET /gt/networks/solana/pools?page=1 (فقط
        # فیلدهایی که solLoadPopular واقعاً می‌خواند)، برای «Popular on
        # Solana». SOL/USDC/USDT باید حذف شوند (از قبل ردیفِ خودشان هستند).
        POPULAR_MINT = "PopB1111111111111111111111111111111111111111"  # ۲۰ اکتبر: BONK حالا پیش‌فرض است؛ mintِ ساختگیِ خارج از فهرست
        def gt_pools_fixture():
            def row(mint, name, image=None):
                return {
                    "attributes": {"name": name + " / SOL", "image_url": image},
                    "relationships": {"base_token": {"data": {"id": "solana_" + mint, "type": "token"}}},
                }
            return {"data": [
                row("So11111111111111111111111111111111111111112", "Wrapped SOL"),  # حذف می‌شود
                row(SOL_APP_TOKENS_USDC, "USD Coin"),  # حذف می‌شود
                row(POPULAR_MINT, "Bonk"),
                row(POPULAR_MINT, "Bonk (dup)"),  # dedupe — همان mint دوباره
            ]}
        SOL_APP_TOKENS_USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"

        async def open_sol_swap_page(verdict_body, quote_status=200, quote_body=None,
                                      swap_status=200, swap_body=None, inject_wallet=True,
                                      collect_errors=None, balance_lamports=2_000_000_000,
                                      sim_result="ok", token_accounts=None, rpc_log=None,
                                      wallet_init=None, swap_log=None, swap_bodies=None,
                                      send_error=None, ls_wallet_name=None, ls_off=False,
                                      sol_mint_image_url=None, quote_reason=None, send_error_times=None,
                                      send_params_log=None, quote_log=None, direct_quote_body=None,
                                      sim_rpc_fail=False, status_value=None, epoch_height=None,
                                      status_params_log=None, swap_error=None, clock=False,
                                      real_intent=False, page_mint=None, rpc_hook=None):
            spg = await b.new_page(viewport={"width": 1240, "height": 1000})
            if real_intent:
                spg._zx_real_intent = True
            if clock:
                # ۱۱ اکتبر — ساعتِ جعلی که طبیعی می‌گذرد؛ کاوشگرهای نگهبانِ کیف‌پول و پول‌کردن با run_for جلو می‌روند
                await spg.clock.install()
            # Transaction fixtures use fixed non-signing keys; real approval is tested in solana-approval.test.mjs.
            await spg.add_init_script("window.addEventListener('load',()=>{solConfirmConnection=async()=>{};});")
            if collect_errors is not None:
                spg.on("console", lambda m: collect_errors.append(m.text) if m.type == "error" else None)
                spg.on("pageerror", lambda e: collect_errors.append(str(e)))
            if ls_wallet_name is not None or ls_off:
                # C — پیش از هر اسکریپتِ صفحه: نامِ کیف‌پول/پرچمِ off را در
                # localStorage می‌گذارد تا solTryAutoRestoreName آن را در همان
                # بارگذاریِ اول ببیند.
                setter = ""
                if ls_wallet_name is not None:
                    setter += "try{localStorage.setItem('zaexa.solwallet.v1',%s);}catch(_){}" % _json.dumps(ls_wallet_name)
                if ls_off:
                    setter += "try{localStorage.setItem('zaexa.solwallet.off.v1','1');}catch(_){}"
                await spg.add_init_script(setter)
            if inject_wallet:
                await spg.add_init_script(wallet_init or SOL_FAKE_WALLET_INIT)
            async def stub_ev(route):
                # سرورِ استاتیکِ محلی POST را اصلاً پشتیبانی نمی‌کند (۵۰۱)؛
                # بی‌ربط به سواپ است، فقط بیکنِ رویدادها — همان‌طور که سایر
                # صفحاتِ توکن جای دیگرِ همین فایل آن را نادیده می‌گیرند.
                await route.fulfill(status=204, body="")
            async def stub_gt(route):
                # G — round 3: چیپِ SOL آدرسِ wSOL را جدا می‌پرسد؛ فقط همان یکی
                # (نه multi/، نه mintِ خودِ توکن) فیکسچرِ لوگو را می‌گیرد.
                u = route.request.url
                if sol_mint_image_url is not None and ("/tokens/" + SOL_MINT_ADDR) in u and "/tokens/multi/" not in u:
                    await route.fulfill(status=200, content_type="application/json",
                                         body=_json.dumps({"data": {"attributes":
                                             {"symbol": "SOL", "image_url": sol_mint_image_url}}}))
                    return
                await route.fulfill(status=200, content_type="application/json", body=swap_gt_body())
            async def stub_vd(route):
                await route.fulfill(status=200, content_type="application/json",
                                     body=_json.dumps(verdict_body))
            async def stub_quote(route):
                if quote_log is not None:
                    quote_log.append(route.request.url)
                if quote_status == 200 and direct_quote_body is not None and "onlyDirectRoutes=true" in route.request.url:
                    await route.fulfill(status=200, content_type="application/json", body=_json.dumps(direct_quote_body))
                    return
                if quote_status != 200:
                    qb = {"error": "jup:quote:%d" % quote_status}
                    if quote_reason is not None:
                        qb["reason"] = quote_reason
                    await route.fulfill(status=quote_status, content_type="application/json", body=_json.dumps(qb))
                else:
                    await route.fulfill(status=200, content_type="application/json",
                                         body=_json.dumps(quote_body if quote_body is not None else SOL_QUOTE_FIXTURE))
            async def stub_swap(route):
                if swap_log is not None:
                    swap_log.append(1)
                if swap_error is not None:
                    # شکلِ واقعیِ Worker: ۵۰۲ با {error:"jup:swap:<status>"}
                    await route.fulfill(status=502, content_type="application/json", body=_json.dumps({"error": swap_error}))
                elif swap_status != 200:
                    await route.fulfill(status=swap_status, content_type="application/json",
                                         body=_json.dumps({"error": "jup:swap:%d" % swap_status}))
                else:
                    if swap_bodies is not None:
                        # A — یک بدنه‌ی متفاوت به‌ازای هر تماس، برای اثباتِ اینکه
                        # fallback واقعاً از ساختِ *دوم* استفاده می‌کند، نه اول.
                        idx = min(len(swap_log) - 1 if swap_log is not None else 0, len(swap_bodies) - 1)
                        body = swap_bodies[idx]
                    else:
                        body = swap_body if swap_body is not None else \
                            {"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 123}
                    await route.fulfill(status=200, content_type="application/json", body=_json.dumps(body))
            async def stub_rpc(route):
                payload = _json.loads(route.request.post_data or "{}")
                method = payload.get("method")
                if rpc_log is not None:
                    rpc_log.append(method)
                if rpc_hook is not None:
                    hooked = rpc_hook(method, payload.get("params"))
                    if hooked is not None:
                        await route.fulfill(status=200, content_type="application/json",
                                             body=_json.dumps({"result": hooked}))
                        return
                # B — round 3: یک sendTransactionِ شکست‌خورده با شکلِ بسته‌ی
                # دقیقِ worker/index.js (error + detail.err/logs)، برای سنجیدنِ
                # نگاشتِ سمتِ کلاینت جدا از خودِ Worker.
                if method == "sendTransaction" and send_params_log is not None:
                    send_params_log.append(payload.get("params"))
                if method == "sendTransaction" and send_error is not None and (
                        send_error_times is None or sum(1 for m in (rpc_log or []) if m == "sendTransaction") <= send_error_times):
                    await route.fulfill(status=502, content_type="application/json",
                                         body=_json.dumps(send_error))
                    return
                if method == "getBalance":
                    result = {"value": balance_lamports}
                elif method == "getTokenAccountsByOwner":
                    result = {"value": token_accounts if token_accounts is not None else []}
                elif method == "getSignatureStatuses":
                    if status_params_log is not None:
                        status_params_log.append(payload.get("params"))
                    result = {"value": status_value if status_value is not None else [{"confirmationStatus": "confirmed", "err": None}]}
                elif method == "getEpochInfo":
                    result = {"blockHeight": epoch_height, "epoch": 1} if epoch_height is not None else None
                elif method == "simulateTransaction":
                    if sim_rpc_fail:
                        # خودِ تماسِ RPC شکست می‌خورد (نه یک err در نتیجه) — «نمی‌دانیم»
                        await route.fulfill(status=502, content_type="application/json",
                                             body=_json.dumps({"error": "rpc:simulateTransaction:down"}))
                        return
                    if sim_result == "skip":
                        result = None
                    elif sim_result == "ok":
                        result = {"value": {"err": None}}
                    elif sim_result == "fail":
                        result = {"value": {"err": {"InstructionError": [1, {"Custom": 6001}]}}}
                    else:
                        result = sim_result
                else:
                    result = None
                await route.fulfill(status=200, content_type="application/json",
                                     body=_json.dumps({"result": result}))
            await spg.route("**/ev", stub_ev)
            await spg.route("**/gt/networks/solana/tokens/**", stub_gt)
            await spg.route("**/vd/**", stub_vd)
            await spg.route("**/sol/quote**", stub_quote)
            await spg.route("**/sol/swap", stub_swap)
            await spg.route("**/sol/rpc", stub_rpc)
            if sol_mint_image_url is not None:
                # G — این route باید پیش از goto ثبت شود: <img src> بلافاصله
                # بعدِ رسیدنِ fetchSolMeta شلیک می‌شود، خیلی زودتر از آنکه
                # فراخوانِ بعدِ این تابع بتواند routeای اضافه کند.
                await spg.route(sol_mint_image_url, lambda route: route.fulfill(
                    status=200, content_type="image/png", body=tiny_png_bytes()))
            await spg.goto("http://127.0.0.1:%d/t/%s" % (port, page_mint or SWAP_MINT))
            await spg.wait_for_timeout(1200)
            await spg.click("#tk-trade")
            await spg.wait_for_timeout(150)
            return spg

        async def sol_connect(spg):
            await spg.click("#connectBtn")
            await spg.wait_for_timeout(400)
            wal_text = await spg.inner_text("#solWalList")
            await spg.click("#solWalList .walRow")
            await spg.wait_for_timeout(300)
            return wal_text

        # [sol intent real] ZX-01 با یک سواپ واقعیِ مین‌نت (Phantom، ۱۹ اکتبر، SOL->USDC، Swap variant 181 که در schema
        # پین‌شده نیست): باندلِ *واقعی* سرو می‌شود، پیام‌ِ Jupiter بدونِ دستورهای Lighthouse به‌عنوان swapTransaction
        # برمی‌گردد و RPC از روی snapshot جواب می‌دهد. کیف‌پول باید صدا زده شود. نسخه‌ی دست‌کاری‌شده (مقصد عوض شده)
        # هرگز نباید کیف‌پول را صدا بزند و رابط باید بگوید چیزی ارسال نشد.
        import base64 as _b64, binascii as _binascii
        _rs = _json.load(open(os.path.join(HERE, "fixtures", "sol_real_swap_stripped.json")))
        _B58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
        def _b58dec(t):
            n = 0
            for ch in t:
                n = n * 58 + _B58.index(ch)
            raw = n.to_bytes((n.bit_length() + 7) // 8, "big")
            return bytes(len(t) - len(t.lstrip("1"))) + raw
        _rs_pub = list(_b58dec(_rs["wallet"]))
        assert len(_rs_pub) == 32, "fixture signer must decode to 32 bytes"
        _RS_WALLET_INIT = ("""
(function(){
  const PUB = new Uint8Array(%s);
  window.__solCalls = [];
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async () => ({accounts: [{address: %s, publicKey: PUB}]}) },
      "standard:disconnect": { disconnect: async () => {} },
      "solana:signAndSendTransaction": { signAndSendTransaction: async (input) => {
        window.__solCalls.push(Array.from(input.transaction));
        return [{signature: new Uint8Array(64).fill(7)}];
      } }
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => { try { e.detail.register(fakeWallet); } catch(_){} });
})();
""" % (_rs_pub, _json.dumps(_rs["wallet"])))
        def _rs_rpc(method, params):
            if method == "getAccountInfo":
                if params[0] == _rs["alt"]:
                    return {"value": {"owner": "AddressLookupTab1e1111111111111111111111111", "data": [_rs["altB64"], "base64"]}}
                if params[0] in _rs["mints"]:
                    return {"value": {"owner": _rs["mints"][params[0]], "data": {"parsed": {"type": "mint"}, "program": "spl-token", "space": 82}}}
                return {"value": None}
            if method == "getMultipleAccounts":
                rows = []
                for k in params[0]:
                    o = _rs["token_accounts"].get(k)
                    if not o:
                        rows.append(None)
                        continue
                    bb = bytearray(165)
                    bb[32:64] = bytes.fromhex(o[1])
                    rows.append({"owner": o[0], "data": [_b64.b64encode(bytes(bb)).decode(), "base64"]})
                return {"value": rows}
            return None
        _RS_USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"
        _rs_quote = dict(_rs["quote"], routePlan=[{"swapInfo": {"label": "Jupiter"}, "percent": 100}])
        for _rs_tamper in (False, True):
            _rs_rpc_log, _rs_swaps, _rs_errs = [], [], []
            _rs_tx = _rs["swapTransactionTampered"] if _rs_tamper else _rs["swapTransaction"]
            rspg = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=_RS_WALLET_INIT, real_intent=True,
                                             page_mint=_RS_USDC, quote_body=_rs_quote, rpc_hook=_rs_rpc,
                                             swap_body={"swapTransaction": _rs_tx, "lastValidBlockHeight": 123},
                                             rpc_log=_rs_rpc_log, swap_log=_rs_swaps, collect_errors=_rs_errs)
            await sol_connect(rspg)
            await rspg.fill("#solAmt", "0.000674388")
            await rspg.wait_for_timeout(1200)
            assert await rspg.evaluate("typeof window.SolIntent.validateTransaction") == "function" and \
                not await rspg.evaluate("!!window.SolIntent.__stub"), \
                "[sol intent real] the REAL intent bundle must be loaded, not the stub"
            await rspg.click("#solSwapBtn")
            await rspg.wait_for_timeout(1500)
            _rs_calls = await rspg.evaluate("window.__solCalls.length")
            _rs_notice = await rspg.inner_text("#solNotices")
            _rs_sent = list(await rspg.evaluate("window.__solCalls[0] || []"))
            await rspg.close()
            print("[sol intent real] tamper=%s -> walletCalls=%d builds=%d multiRpc=%d notice=%r"
                  % (_rs_tamper, _rs_calls, len(_rs_swaps), _rs_rpc_log.count("getMultipleAccounts"), _rs_notice[:90]))
            if not _rs_tamper:
                assert _rs_calls == 1, "[sol intent real] the genuine real swap must reach the wallet exactly once, got %d (notice %r)" % (_rs_calls, _rs_notice)
                assert _rs_sent == list(_b64.b64decode(_rs["swapTransaction"])), "[sol intent real] the wallet must receive exactly the validated bytes"
                assert "getMultipleAccounts" in _rs_rpc_log, "[sol intent real] the writable-account ownership check must have run"
                assert len(_rs_swaps) == 1, "[sol intent real] exactly one build"
            else:
                assert _rs_calls == 0, "[sol intent real] a tampered destination must NEVER reach the wallet, got %d" % _rs_calls
                assert "Nothing was sent" in _rs_notice, "[sol intent real] the UI must say nothing was sent: %r" % _rs_notice
                assert "sendTransaction" not in _rs_rpc_log, "[sol intent real] nothing may be broadcast"

        # الف) کشف و اتصال
        apg = await open_sol_swap_page({"v": "sell", "ms": 100})
        wal_text = await sol_connect(apg)
        conn_btn = await apg.inner_text("#solConnectBtn")
        await apg.close()
        print("[sol swap] wallet picker=%r connected btn=%r" % (wal_text[:40], conn_btn))
        assert "Fake Wallet" in wal_text, "the wallet picker did not list the injected Wallet Standard wallet: %r" % wal_text
        assert conn_btn != "Connect Solana wallet" and conn_btn.strip(), \
            "connecting did not update the button to the short address: %r" % conn_btn

        # [sol rent rows] ردیفِ rent فقط وقتی حسابِ توکن ساخته می‌شود؛ ردیفِ wSOL (برگشت‌پذیر) وقتی SOL در یک سمت است
        rpg = await open_sol_swap_page({"v": "sell", "ms": 100})
        rent_js = """(st) => { solSide = "buy"; solRefMint = SOL_MINT_ADDR; solMintCur = st.cur; solOutAtaExists = st.ata; solPaintFeeRows();
            const d = (id) => getComputedStyle(document.getElementById(id)).display !== "none";
            return { rent: d("solRentRow"), wsol: d("solWsolRow") }; }"""
        rr_a = await rpg.evaluate(rent_js, {"cur": SWAP_MINT, "ata": True})
        rr_b = await rpg.evaluate(rent_js, {"cur": SWAP_MINT, "ata": False})
        rr_c = await rpg.evaluate(rent_js, {"cur": SWAP_MINT, "ata": None})
        rr_d = await rpg.evaluate(rent_js, {"cur": None, "ata": False})
        await rpg.close()
        print("[sol rent rows] ata exists=%s; missing=%s; unknown=%s; no token=%s" % (rr_a, rr_b, rr_c, rr_d))
        assert rr_a == {"rent": False, "wsol": True}, "[sol rent rows] existing token account: rent row must be hidden, refunded row shown: %s" % rr_a
        assert rr_b == {"rent": True, "wsol": True}, "[sol rent rows] missing token account: both rows shown: %s" % rr_b
        assert rr_c == {"rent": True, "wsol": True}, "[sol rent rows] unknown token account is assumed needed: %s" % rr_c
        assert rr_d == {"rent": False, "wsol": False}, "[sol rent rows] no token chosen: both rows hidden: %s" % rr_d

        # ب) کوت — «You receive»/«Min received»/«Route»
        bpg = await open_sol_swap_page({"v": "sell", "ms": 100})
        await sol_connect(bpg)
        await bpg.fill("#solAmt", "1")
        await bpg.wait_for_timeout(900)
        b_out = await bpg.input_value("#solOutRead")
        b_min = await bpg.inner_text("#solMinF")
        b_route = await bpg.inner_text("#solRouteF")
        await bpg.close()
        print("[sol swap] quote out=%r min=%r route=%r" % (b_out, b_min, b_route))
        assert b_out != "—" and b_min != "—", "typing a buy amount did not produce a quote readout: out=%r min=%r" % (b_out, b_min)
        assert b_route == "Whirlpool → Meteora DLMM", \
            "the route label must dedupe repeated venues and join with \" → \", got %r" % b_route

        # پ) سواپِ کامل — کیف‌پول دقیقاً یک‌بار با بایت‌های دقیق صدا زده می‌شود،
        # وضعیت به Confirmed می‌رسد، لینک Solscan امضای درست را دارد
        cpg = await open_sol_swap_page({"v": "sell", "ms": 100})
        await sol_connect(cpg)
        await cpg.fill("#solAmt", "1")
        await cpg.wait_for_timeout(900)
        await cpg.click("#solSwapBtn")
        await cpg.wait_for_timeout(900)
        calls = await cpg.evaluate("window.__solCalls")
        await cpg.wait_for_timeout(2600)
        notice_html = await cpg.inner_html("#solNotices")
        await cpg.close()
        print("[sol swap] wallet calls=%d confirmed=%s sig-in-link=%s"
              % (len(calls), "Confirmed" in notice_html, SOL_SIG_B58 in notice_html))
        assert len(calls) == 1, "the wallet's signAndSendTransaction must be called exactly once, got %d" % len(calls)
        assert calls[0] == list(build_v0_tx(SOL_FEE_PAYER)), \
            "the wallet was not called with the exact transaction bytes returned by /sol/swap"
        assert "Confirmed" in notice_html, "status did not reach Confirmed after the fixture said so: %r" % notice_html[:200]
        assert SOL_SIG_B58 in notice_html and ("solscan.io/tx/" + SOL_SIG_B58) in notice_html, \
            "the Solscan link must carry the base58-encoded signature: %r" % notice_html[:200]

        # ت) فی‌پیرِ غلط — کیف‌پول هرگز صدا زده نمی‌شود
        dpg = await open_sol_swap_page({"v": "sell", "ms": 100}, swap_body={"swapTransaction": SOL_BAD_TX_B64, "lastValidBlockHeight": 1})
        await sol_connect(dpg)
        await dpg.fill("#solAmt", "1")
        await dpg.wait_for_timeout(900)
        await dpg.click("#solSwapBtn")
        await dpg.wait_for_timeout(500)
        d_calls = await dpg.evaluate("window.__solCalls")
        d_notice = await dpg.inner_text("#solNotices")
        await dpg.close()
        print("[sol swap] fee-payer mismatch -> calls=%d notice=%r" % (len(d_calls), d_notice[:70]))
        assert len(d_calls) == 0, "a transaction whose fee payer is not the wallet must never reach the wallet, got %d calls" % len(d_calls)
        assert "Refused: the transaction's fee payer is not your wallet." in d_notice, \
            "the fee-payer mismatch must show the exact refusal sentence: %r" % d_notice

        # ث) nosell — خرید غیرفعال با پیام، فروش همچنان مجاز
        epg = await open_sol_swap_page({"v": "nosell", "ms": 100})
        e_btn_text = await epg.inner_text("#solSwapBtn")
        await epg.click("#solFlipBtn")
        await epg.wait_for_timeout(200)
        e_btn_text_sell = await epg.inner_text("#solSwapBtn")
        await epg.close()
        print("[sol swap] nosell gate: btn=%r btnAfterFlip=%r" % (e_btn_text, e_btn_text_sell))
        assert "Buying is blocked" in e_btn_text and "sell-back check" in e_btn_text, \
            "the blocked CTA must name the reason, got %r" % e_btn_text
        assert "Buying is blocked" not in e_btn_text_sell, \
            "flipping to Sell must clear the buy-blocked message, got %r" % e_btn_text_sell

        # ج) کیف‌پول امضا را رد می‌کند
        fpg = await open_sol_swap_page({"v": "sell", "ms": 100})
        await sol_connect(fpg)
        await fpg.fill("#solAmt", "1")
        await fpg.wait_for_timeout(900)
        await fpg.evaluate("window.__solRejectSwap = true")
        await fpg.click("#solSwapBtn")
        await fpg.wait_for_timeout(500)
        f_notice = await fpg.inner_text("#solNotices")
        await fpg.close()
        print("[sol swap] wallet rejection -> %r" % f_notice[:60])
        assert "Cancelled in your wallet." in f_notice, \
            "a wallet rejection must show the same wording as the Base flow: %r" % f_notice

        # چ) /sol/quote 502 — خطای مهربان، بدون کرش، بدون خطای کنسول
        g_errs = []
        gpg = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_status=502, collect_errors=g_errs)
        await gpg.fill("#solAmt", "1")
        await gpg.wait_for_timeout(900)
        g_out = await gpg.input_value("#solOutRead")
        g_notice = await gpg.inner_text("#solNotices")
        await gpg.close()
        # ⚠️ کروم خودش برای *هر* fetchِ غیرِ۲۰۰ یک «Failed to load resource»
        # در کنسول می‌نویسد — این تشخیصِ خودِ مرورگر است، نه console.error یا
        # throwِ کدِ ما؛ همان ۵۰۲ای که خودمان عمداً برای همین آزمون ساختیم.
        # چیزی که واقعاً اهمیت دارد نبودِ خطای *دیگر* (استثنای جاوااسکریپت) است.
        g_real_errs = [e for e in g_errs if "Failed to load resource" not in e]
        print("[sol swap] quote 502 -> out=%r notice=%r errors=%s" % (g_out, g_notice[:50], g_errs))
        assert g_out == "", "a failed quote must not render a stale/garbage readout: %r" % g_out
        assert "Quote service did not answer" in g_notice, "a failed quote must show a friendly error, got %r" % g_notice
        assert not g_real_errs, "a failed quote must not raise a JS exception/console.error: %s" % g_real_errs

        # ح) صفحه‌ی Base دست‌نخورده می‌ماند — #solSwap مخفی
        hpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await hpg.goto("http://127.0.0.1:%d%s" % (port, ck_path))
        await hpg.wait_for_timeout(2000)
        h_hidden = await hpg.eval_on_selector("#solSwap", "el => el.hidden")
        await hpg.close()
        print("[sol swap] Base token page #solSwap hidden=%s" % h_hidden)
        assert h_hidden is True, "the Solana swap card must stay hidden on a Base token page"

        print("[sol swap] Wallet Standard discovery/connect against an injected fake wallet, a live quote "
              "readout (You receive/Min received/deduped Route), a full swap that calls "
              "signAndSendTransaction exactly once with the exact bytes and reaches Confirmed with a "
              "base58 Solscan link, a fee-payer mismatch refused before the wallet is ever called, the "
              "nosell buy-gate (Sell unaffected), a wallet rejection reusing the Base wording, a 502 quote "
              "degrading to a friendly notice, and the Base token page left unchanged (#solSwap hidden) "
              "all covered")

        # ---- [faq] پرسش‌های متداول: نه ابزار است، نه دکمه‌ای در ناوبری دارد ----
        # فقط از پانویس و از #faq می‌رسند به آن، دقیقاً مثل view-token که هیچ
        # دکمه‌ای در نوار بالا ندارد. آدرسِ قرارداد باید تنها از CHAIN.executor
        # بیاید — کپیِ هاردکد همان اشتباهی است که check_one_executor_address
        # قبلاً یک‌بار پیدایش کرده.
        faqpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await faqpg.goto("http://127.0.0.1:%d/test/harness.html#faq" % port)
        await faqpg.wait_for_timeout(1200)
        faq_on = await faqpg.evaluate(
            "() => document.getElementById('view-faq').classList.contains('on')")
        faq_nav_btns = await faqpg.eval_on_selector_all(
            "#nav [data-view]", "els => els.map(e => e.dataset.view)")
        faq_nav_selected = await faqpg.eval_on_selector_all(
            "#nav [data-view].on, #nav [data-view][aria-selected=true]",
            "els => els.map(e => e.dataset.view)")
        faq_hash = await faqpg.evaluate("() => location.hash")
        print("[faq] route=%s navButtons=%r hash=%s" % (faq_on, faq_nav_btns, faq_hash))
        assert faq_on, "navigating to #faq did not turn on view-faq"
        assert "faq" not in faq_nav_btns, (
            "the FAQ got a nav button (%r) — the owner explicitly rejected a fourth tab; "
            "the FAQ is reached only from the footer and #faq" % faq_nav_btns)
        assert not faq_nav_selected, (
            "some nav button is marked selected for the FAQ view (%r), though none exists "
            "for it" % faq_nav_selected)

        chain_executor = await faqpg.evaluate("() => CHAIN.executor")
        faq_addr_text = (await faqpg.text_content("#view-faq #faqCtrLink") or "").strip()
        faq_addr_href = await faqpg.get_attribute("#view-faq #faqCtrLink", "href") or ""
        addr_match = faq_addr_text.lower() == chain_executor.lower()
        href_match = chain_executor.lower() in faq_addr_href.lower()
        print("[faq] address matches CHAIN.executor: %s" % (addr_match and href_match))
        assert addr_match, (
            "the FAQ's rendered contract address (%r) does not match CHAIN.executor (%r) — "
            "looks like a hardcoded second source of truth" % (faq_addr_text, chain_executor))
        assert href_match, (
            "the FAQ's BaseScan link (%r) does not contain CHAIN.executor (%r)"
            % (faq_addr_href, chain_executor))

        await faqpg.set_viewport_size({"width": 390, "height": 844})
        await faqpg.wait_for_timeout(500)
        doc_scroll = await faqpg.evaluate("() => document.documentElement.scrollWidth")
        doc_client = await faqpg.evaluate("() => document.documentElement.clientWidth")
        # ⚠️ خودِ سایت `html,body{overflow-x:hidden}` دارد — و این باعث می‌شود
        # documentElement.scrollWidth روی کروم به clientWidth کلمپ شود، حتی
        # وقتی داخلش واقعاً یک عنصر پهن‌تر از صفحه هست (خاصیتِ خودِ ریشه‌ی
        # سند، نه یک فرزندش). یعنی همین سنجش به‌تنهایی یک کارتِ ۹۰۰ پیکسلی
        # ثابت را در ویوپورت ۳۹۰ پیکسلی نمی‌بیند. body.scrollWidth این
        # کلمپ را ندارد، پس همراهش سنجیده می‌شود تا کاوشگر واقعاً کور نباشد.
        body_scroll = await faqpg.evaluate("() => document.body.scrollWidth")
        faq_first_visible = await faqpg.is_visible("#view-faq .faqItem:first-of-type .faqA")
        print("[faq] 390px: docScroll=%d docClient=%d (bodyScroll=%d)"
              % (doc_scroll, doc_client, body_scroll))
        assert doc_scroll <= doc_client + 1, (
            "the FAQ overflows horizontally at 390px: scrollWidth=%d clientWidth=%d"
            % (doc_scroll, doc_client))
        assert body_scroll <= doc_client + 1, (
            "the FAQ overflows horizontally at 390px: body.scrollWidth=%d viewport=%d — "
            "documentElement.scrollWidth alone missed this because the site's own "
            "html,body{overflow-x:hidden} clamps it to clientWidth"
            % (body_scroll, doc_client))
        assert faq_first_visible, "the first FAQ entry's answer is not visible at 390px"
        await faqpg.close()

        # پانویس باید به همان‌جا برسد، و نوار بالا باید بتواند از آن‌جا بیرون ببرد
        faqnavpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await faqnavpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await faqnavpg.wait_for_timeout(1200)
        await faqnavpg.click("#faqLink")
        await faqnavpg.wait_for_timeout(600)
        faqnav_on = await faqnavpg.evaluate(
            "() => document.getElementById('view-faq').classList.contains('on')")
        faqnav_hash = await faqnavpg.evaluate("() => location.hash")
        print("[faq] footer link: view-faq on=%s hash=%s" % (faqnav_on, faqnav_hash))
        assert faqnav_on, "clicking the footer FAQ link did not open view-faq"
        assert faqnav_hash == "#faq", (
            "the footer FAQ link did not land on #faq: hash=%s" % faqnav_hash)

        await faqnavpg.click('#nav [data-view="swap"]')
        await faqnavpg.wait_for_timeout(600)
        faq_leave_swap_on = await faqnavpg.evaluate(
            "() => document.getElementById('view-swap').classList.contains('on')")
        faq_leave_hash = await faqnavpg.evaluate("() => location.hash")
        faq_leave_tokenPage = await faqnavpg.evaluate("() => tokenPage")
        print("[faq] leave: swapOn=%s hash=%s tokenPage=%s"
              % (faq_leave_swap_on, faq_leave_hash, faq_leave_tokenPage))
        assert faq_leave_swap_on, "clicking the nav Swap button from the FAQ did not open view-swap"
        assert faq_leave_hash == "#swap", (
            "leaving the FAQ via the nav did not update the hash: %s" % faq_leave_hash)
        assert faq_leave_tokenPage is False, (
            "leaving the FAQ via the nav left tokenPage=%r" % faq_leave_tokenPage)
        await faqnavpg.close()

        # بیکن آنالیتیکس واقعاً روی سیم — ثابت می‌کند دو فهرست (صفحه و Worker)
        # واقعاً توافق دارند، نه فقط این‌که نگهبان ایستا سبز است
        faqevpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        faqev_seen = await watch_events(faqevpg)
        await faqevpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await faqevpg.wait_for_timeout(1200)
        await faqevpg.click("#faqLink")
        await faqevpg.wait_for_timeout(600)
        await faqevpg.close()
        faqev_names = [_json.loads(raw)["e"] for raw in faqev_seen]
        faq_beacon_ok = "view:faq" in faqev_names
        print("[faq] view:faq beacon: %s" % faq_beacon_ok)
        assert faq_beacon_ok, (
            "no view:faq beacon reached the wire (saw %s) — a name missing from either "
            "allow-list is dropped with a 400 and nobody notices" % faqev_names)

        # ---- [footer] پانویسِ چندستونه: باید ستون‌دار و برچسب‌دار باشد ----
        # قبلاً یک جمله‌ی پیوسته بود؛ حالا بلوکِ برند + سه ستون. کلیک روی
        # #faqLink را [faq] بالاتر («footer link: view-faq») از قبل سنجیده،
        # اینجا تکرار نمی‌شود.
        footpg = await b.new_page(viewport={"width": 1440, "height": 1000})
        await footpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await footpg.wait_for_timeout(1200)

        # ۱. ستون‌ها هست و برچسب دارند، هرکدام دست‌کم دو لینک (Support یک
        #    لینک + دکمه هم کافی است)
        cols = await footpg.evaluate("""() => {
            const out = {};
            document.querySelectorAll("footer .footCol").forEach(col => {
                const h = col.querySelector("h4");
                if (!h) return;
                out[h.textContent.trim()] = {
                    links: col.querySelectorAll("a").length,
                    buttons: col.querySelectorAll("button").length,
                };
            });
            return out;
        }""")
        print("[footer] columns=%r" % cols)
        for name in ["Trade", "About", "Support"]:
            assert name in cols, "the footer is missing the %r column heading" % name
        assert cols["Trade"]["links"] >= 2, "Trade column has too few links: %r" % cols["Trade"]
        assert cols["About"]["links"] >= 2, "About column has too few links: %r" % cols["About"]
        assert cols["Support"]["links"] + cols["Support"]["buttons"] >= 2, (
            "Support column has too few links/actions: %r" % cols["Support"])

        # ۲. هیچ لینکی به ناکجا نمی‌رود
        hrefs = await footpg.eval_on_selector_all(
            "footer a", "els => els.map(e => e.getAttribute('href'))")
        print("[footer] hrefs=%r" % hrefs)
        for href in hrefs:
            assert href not in (None, "", "#") and not href.lower().startswith("javascript:"), (
                "a footer link goes nowhere real: href=%r (full list: %s)" % (href, hrefs))

        # ۳. شناسه‌های سیم‌کشی‌شده زنده مانده‌اند، و لینکِ خالیِ تلگرام بدون
        #    باقی‌مانده حذف شده
        wired = await footpg.evaluate("""() => {
            const g = id => document.getElementById(id);
            const ctr = g("ctrLink");
            return {
                lnkX: !!g("lnkX"), lnkGh: !!g("lnkGh"), feedbackBtn: !!g("feedbackBtn"),
                ctrLink: !!ctr, ctrHref: ctr ? ctr.href : null,
                faqLink: !!g("faqLink"), lnkTg: !!g("lnkTg"),
                socialCount: document.querySelectorAll("footer .social > *").length,
            };
        }""")
        chain_executor_f = await footpg.evaluate("() => CHAIN.executor")
        print("[footer] wired=%r executor=%s" % (wired, chain_executor_f))
        for key in ["lnkX", "lnkGh", "feedbackBtn", "ctrLink", "faqLink"]:
            assert wired[key], "footer element #%s did not survive the rebuild" % key
        assert chain_executor_f.lower() in wired["ctrHref"].lower(), (
            "#ctrLink's href (%r) does not contain CHAIN.executor (%r) — looks hardcoded"
            % (wired["ctrHref"], chain_executor_f))
        tg_f = app_telegram_link()
        tg_href = await footpg.evaluate("() => { const a = document.getElementById('lnkTg'); return a ? a.href : null; }")
        print("[footer] telegram LINKS=%r #lnkTg.href=%r" % (tg_f, tg_href))
        if not tg_f:
            assert not wired["lnkTg"], (
                "LINKS.telegram is empty so #lnkTg must remove() itself, but it is still present")
            assert wired["socialCount"] == 2, (
                "expected exactly the X and GitHub icons left in .social after #lnkTg removed "
                "itself, found %d children — a leftover empty slot or separator" % wired["socialCount"])
        else:
            assert wired["lnkTg"] and tg_href == tg_f, (
                "LINKS.telegram is %r but #lnkTg is %r (href %r)" % (tg_f, wired["lnkTg"], tg_href))
            assert wired["socialCount"] == 3, (
                "expected X, Telegram and GitHub in .social, found %d children" % wired["socialCount"])

        # ۴. هندسه: نوارِ فوتر باید تمام‌عرضِ صفحه باشد، ولی محتوایش (.footGrid)
        #    باریک‌تر و وسط‌چین بماند. تا امروز هیچ کاوشگری هندسه‌ی فوتر را
        #    نمی‌سنجید و دقیقاً از همین در، فوتر ماه‌ها یک جزیره‌ی ۱۱۴۰ پیکسلی
        #    وسط صفحه بود: روی پهنای ۱۶۰۰ از x=230 شروع می‌شد.
        #    ⚠️ با getBoundingClientRect اندازه بگیر، نه از روی اسکرین‌شات —
        #    اسکرین‌شاتِ full_page موقعیتِ عناصرِ fixed را وسط صفحه دروغ می‌گوید.
        #    ⚠️ و شرطِ محتوا روی عددِ ۱۱۰۰ پین شده، نه «باریک‌تر از نوار»: با
        #    شرطِ شل، محتوا تا ۱۴۰۰ پیکسل کش می‌آمد و باز هم از نگهبان رد می‌شد.
        geo = await footpg.evaluate("""() => {
            // ۱۱ اکتبر: با html{scrollbar-gutter:stable} عرضِ قابل‌استفاده‌ی صفحه عرضِ <body> است (شیارِ اسکرول‌بار کنارش رزرو می‌ماند و clientWidth آن را شامل می‌شود)؛ «نوار تمام‌عرض است» همچنان یعنی هم‌عرض با body
            const vw = document.body.getBoundingClientRect().width;
            const f = document.querySelector("footer").getBoundingClientRect();
            const g = document.querySelector("footer .footGrid").getBoundingClientRect();
            const cs = getComputedStyle(document.querySelector("footer"));
            const bw = parseFloat(cs.borderTopWidth);
            const padL = parseFloat(cs.paddingLeft), padR = parseFloat(cs.paddingRight);
            const leftGap = g.left - f.left, rightGap = f.right - g.right;
            return {
                vw, bandW: f.width, bandLeft: f.left, contentW: g.width,
                padL, padR, borderW: bw, centred: Math.abs(leftGap - rightGap) <= 1,
            };
        }""")
        print("[footer] band=%.0fpx viewport=%.0fpx content=%.0fpx gutter=%.0fpx centred=%s"
              % (geo["bandW"], geo["vw"], geo["contentW"], geo["padL"], geo["centred"]))
        assert abs(geo["bandW"] - geo["vw"]) <= 1, (
            "the footer band is not full-bleed: width=%.1fpx but viewport clientWidth=%.1fpx"
            % (geo["bandW"], geo["vw"]))
        assert abs(geo["bandLeft"]) <= 1, (
            "the footer's left edge is not at 0: left=%.1fpx" % geo["bandLeft"])
        # ⚠️ عمداً «باریک‌تر از نوار» نیست. مالک دو بار گفت فوتر باید تمام‌عرض
        #    باشد؛ نسخه‌ی میانی فقط نوار را پهن کرد و محتوا روی ۱۱۰۰ پین ماند،
        #    که روی ۱۵۸۵ پیکسل یعنی ۲۴۲ پیکسل فضای خالی هر طرف — و همان رد شد.
        #    پس شرط روی عددِ محاسبه‌شده پین است: محتوا باید دقیقاً نوار منهای
        #    گاترِ خودش باشد. عددِ گاتر از خودِ computed style می‌آید، نه هاردکد،
        #    چون clamp() با عرضِ صفحه عوض می‌شود.
        expected_content = geo["bandW"] - geo["padL"] - geo["padR"]
        assert abs(geo["contentW"] - expected_content) <= 2, (
            "the footer content (.footGrid) should fill the band minus its own gutter — "
            "expected %.1fpx (band %.1f - padding %.1f - %.1f) but measured %.1fpx. A "
            "max-width creeping back onto .footGrid puts the columns in the middle of the "
            "screen again, which is the exact layout the owner rejected twice."
            % (expected_content, geo["bandW"], geo["padL"], geo["padR"], geo["contentW"]))
        assert geo["contentW"] > 1200, (
            "at a %.0fpx viewport the footer columns only span %.1fpx — that is the old "
            "1100px centred island, not a full-width footer" % (geo["vw"], geo["contentW"]))
        assert geo["centred"], (
            ".footGrid is not horizontally centred inside the footer band")
        assert geo["borderW"] > 0, (
            "the footer has no visible border-top separating it from the page")

        # ۵. واقعاً خواناست — فاصله‌ی ردیف‌ها و اندازه‌ی متن، نه فقط ستون‌بندی
        rhythm = await footpg.evaluate("""() => {
            const col = [...document.querySelectorAll("footer .footCol")]
                .find(c => c.querySelector("h4") && c.querySelector("h4").textContent.trim() === "Trade");
            const links = [...col.querySelectorAll("a")].map(a => a.getBoundingClientRect());
            let minGap = Infinity;
            for (let i = 1; i < links.length; i++) {
                minGap = Math.min(minGap, links[i].top - links[i - 1].bottom);
            }
            const walker = document.createTreeWalker(
                document.querySelector("footer"), NodeFilter.SHOW_TEXT,
                { acceptNode: n => n.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP });
            let minFont = Infinity, node;
            while (node = walker.nextNode()) {
                const fs = parseFloat(getComputedStyle(node.parentElement).fontSize);
                minFont = Math.min(minFont, fs);
            }
            return { minGap, minFont };
        }""")
        print("[footer] Trade link gap=%.1fpx minFontSize=%.1fpx"
              % (rhythm["minGap"], rhythm["minFont"]))
        assert rhythm["minGap"] >= 8, (
            "the Trade column's links sit only %.1fpx apart — that is still the cramped "
            "run-on look, not a readable list" % rhythm["minGap"])
        assert rhythm["minFont"] >= 10.9, (
            "some footer text renders at %.1fpx, under the 11px readability floor"
            % rhythm["minFont"])
        await footpg.close()

        # ۶. موبایل: بدون سرریز افقی — روی body، نه documentElement (همان
        #    دلیلِ کاوشگر [faq]: overflow-x:hidden ریشه را کلمپ می‌کند)
        footmob = await b.new_page(viewport={"width": 390, "height": 900})
        await footmob.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await footmob.wait_for_timeout(1200)
        body_w = await footmob.evaluate("() => document.body.scrollWidth")
        print("[footer] mobile 390px: body.scrollWidth=%d" % body_w)
        assert body_w <= 390 + 1, (
            "the footer overflows horizontally at 390px: body.scrollWidth=%d" % body_w)
        await footmob.close()

        # Global Privacy Control یک «نه»ی صریح است و باید همه‌چیز را خاموش کند
        gpcpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await gpcpg.add_init_script(
            "Object.defineProperty(navigator,'globalPrivacyControl',{get:()=>true});")
        gpc_seen = await watch_events(gpcpg)
        await gpcpg.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await gpcpg.wait_for_timeout(1400)
        await go_view(gpcpg, "folio")
        await gpcpg.wait_for_timeout(400)
        await gpcpg.close()
        print("[events] with Global Privacy Control on: %d beacons" % len(gpc_seen))
        assert not gpc_seen, (
            "Global Privacy Control is an explicit opt-out and must silence every beacon: %s"
            % gpc_seen)

        # ---- [dev flag]: صاحب سایت باید بتواند آنالیتیکس را روی مرورگر خودش
        # برای همیشه خاموش کند، بدون شناسه و بدون رفت‌وبرگشت با سرور. سه
        # مرحله‌ی اول همه روی *یک* صفحه (یک context) پشت‌سرهم اجرا می‌شوند —
        # چون کل ادعا این است که پرچم بین بارگذاری‌ها زنده می‌ماند، و آن فقط
        # وقتی قابل آزمودن است که context عوض نشود. ----
        devpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        dev_seen = await watch_events(devpg)

        # 1) خاموش‌کردن باید سرتاسری کار کند: صفر بیکن روی سیم.
        before = len(dev_seen)
        await devpg.goto("http://127.0.0.1:%d/test/harness.html?dev=1" % port)
        await devpg.wait_for_timeout(1400)
        # ⚠️ بنر از #notices خوانده نمی‌شود. نسخه‌ی اول همان‌جا می‌نشست و
        # روی سایت زنده در چند میلی‌ثانیه محو می‌شد، چون کوت‌گیری با هر
        # تغییر مبلغ `setNotice("")` می‌زند و روی صفحه‌ی خالیِ اول همین
        # بلافاصله اتفاق می‌افتد. تست وقت سبز بود چون *لحظه‌ی اول* را
        # می‌سنجید، نه حالت پایدار. حالا ظرف جداست و پایداری‌اش هم سنجیده
        # می‌شود: عمداً همان کاری که پاکش می‌کرد را می‌کنیم و باز می‌خوانیم.
        dev_notice_muted = await devpg.inner_text("#devBanner")
        await devpg.evaluate("() => setNotice('')")
        await devpg.fill("#amtIn", "5")
        await devpg.wait_for_timeout(500)
        await devpg.fill("#amtIn", "")
        await devpg.wait_for_timeout(900)
        dev_notice_survived = await devpg.inner_text("#devBanner")
        dev_banner_hidden = await devpg.evaluate(
            "() => document.getElementById('devBanner').hidden")
        dev_muted_beacons = len(dev_seen) - before

        # 2) باید ماندگار باشد: بارگذاریِ دوباره، بدون هیچ پارامتری، در همان
        # context، هنوز باید صفر بیکن بدهد. اگر ماندگار نبود کل قابلیت
        # بی‌فایده است.
        before = len(dev_seen)
        await devpg.goto("http://127.0.0.1:%d/test/harness.html" % port)
        await devpg.wait_for_timeout(1400)
        dev_persist_beacons = len(dev_seen) - before

        # 3) باید برگشت‌پذیر باشد: dev=0 پرچم را برمی‌دارد و بیکن‌ها دوباره
        # جاری می‌شوند — دستِ‌کم load.
        before = len(dev_seen)
        await devpg.goto("http://127.0.0.1:%d/test/harness.html?dev=0" % port)
        await devpg.wait_for_timeout(1400)
        dev_restored_raw = dev_seen[before:]
        await devpg.close()
        import json as _json2
        dev_restored_names = [_json2.loads(r)["e"] for r in dev_restored_raw]
        dev_restored_beacons = len(dev_restored_raw)

        print("[dev flag] muted: beacons=%d  persisted: beacons=%d  restored: beacons=%d"
              % (dev_muted_beacons, dev_persist_beacons, dev_restored_beacons))
        assert dev_muted_beacons == 0, (
            "?dev=1 must silence every beacon on the very first load, got %d"
            % dev_muted_beacons)
        assert "Analytics muted" in dev_notice_survived and not dev_banner_hidden, (
            "the mute banner vanished as soon as the quote path cleared the notice area "
            "(%r). It must live outside #notices, or the owner sees it for a few "
            "milliseconds on the live site and concludes the flag did not work."
            % dev_notice_survived[:120])
        assert dev_persist_beacons == 0, (
            "the mute flag did not survive a reload with no query string — a flag that resets "
            "on reload is useless, since the owner does not keep ?dev=1 in his address bar")
        assert dev_restored_beacons > 0 and "load" in dev_restored_names, (
            "?dev=0 must turn beacons back on (at least 'load'); got %s" % dev_restored_names)

        # 4) پاکسازی URL: بعد از یک بارِ dev=1 کنار یک لینک اشتراکی، پارامتر
        # dev باید ناپدید شود ولی in/out/amt دست‌نخورده بمانند، و پارسر لینک
        # نباید آن‌ها را به‌عنوان چیزی «باز نشدنی» ببیند — چون این‌ها اصلاً
        # روی location.hash نیستند، پارسر لینک اشتراکی اصلاً نمی‌بیندشان.
        # context تازه، تا حالت هیچ چیزی از مراحل بالا را به ارث نبرد.
        urlpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await urlpg.goto(
            "http://127.0.0.1:%d/test/harness.html?dev=1&in=USDC&out=WETH&amt=5" % port)
        await urlpg.wait_for_timeout(1400)
        url_search = await urlpg.evaluate("() => location.search")
        url_notice = await urlpg.inner_text("#devBanner")
        await urlpg.close()
        from urllib.parse import parse_qs
        url_q = parse_qs(url_search.lstrip("?"))
        print("[dev flag] url cleaned=%r notice=%r" % (url_search, url_notice[:120]))
        assert "dev" not in url_q, (
            "the dev param must be stripped from the address bar, or copying it hands someone "
            "else a link that silently mutes their analytics: %r" % url_search)
        for k in ("in", "out", "amt"):
            assert k in url_q, (
                "cleaning the dev param must not touch the other query params — %r vanished "
                "from %r" % (k, url_search))
        assert "could not be opened" not in url_notice, (
            "a leftover dev param (or its cleanup) confused the share-link parser: %r"
            % url_notice[:200])

        # 5) صاحب سایت نباید حدس بزند: پیام روی صفحه باید صریح بگوید خاموش شد.
        # همان context مرحله‌ی ۱ (dev_notice_muted) که تازه از dev=1 آمده.
        print("[dev flag] notice on mute contains 'Analytics muted': %s"
              % ("Analytics muted" in dev_notice_muted))
        assert "Analytics muted" in dev_notice_muted, (
            "the owner is not told muting worked: %r" % dev_notice_muted[:200])

        # ---- [err] گیرنده‌ی خطای سراسری ----
        # ادعا: یک استثنای گرفته‌نشده دیگر بی‌صدا نیست — کاربر یک کد می‌بیند
        # و ما یک شمارش. هر بند اینجا یک راهِ شکستِ *اندازه‌گیری‌شده* را
        # می‌بندد، نه یک احتمال ذهنی.
        import json as _json3
        ERRCODE = re.compile(r"^E-(JS|PR|RES)-[0-9A-F]{4}$")

        async def err_page():
            pg2 = await b.new_page(viewport={"width": 1240, "height": 1000})
            seen = await watch_events(pg2)
            await pg2.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
            await pg2.wait_for_timeout(1400)
            return pg2, seen

        def err_names(seen):
            return [_json3.loads(r)["e"] for r in seen if _json3.loads(r)["e"].startswith("err:")]

        def err_details(seen):
            # همان فیلترِ err_names، ولی روی «d» — همان چهار نویسه‌ی پایانیِ
            # کدی که کاربر روی صفحه می‌بیند، نه پیام یا فایل یا خط.
            return [_json3.loads(r)["d"] for r in seen if _json3.loads(r)["e"].startswith("err:")]

        # 1) صفحه‌ی سالم: بنر نباید بالا بیاید و هیچ رویداد خطایی نرود.
        #    ⚠️ این مهم‌ترین بند است. نگهبانی که روی صفحه‌ی سالم هم شلیک کند،
        #    بعد از دو روز نادیده گرفته می‌شود و بدتر از نبودنش است.
        okpg, ok_seen = await err_page()
        ok_hidden = await okpg.evaluate("() => document.getElementById('errBanner').hidden")
        ok_errs = err_names(ok_seen)
        await okpg.close()
        print("[err] healthy page: banner hidden=%s, err beacons=%s" % (ok_hidden, ok_errs))
        assert ok_hidden, "the error banner is showing on a page where nothing went wrong"
        assert not ok_errs, "a healthy page reported errors: %s" % ok_errs

        # 2) یک استثنای *واقعیِ* گرفته‌نشده: بنر + کد + دقیقاً یک رویداد.
        jspg, js_seen = await err_page()
        before = len(js_seen)
        await jspg.evaluate(
            "() => setTimeout(() => { throw new Error('zaexa probe: uncaught'); }, 0)")
        await jspg.wait_for_timeout(700)
        js_hidden = await jspg.evaluate("() => document.getElementById('errBanner').hidden")
        js_code = await jspg.inner_text("#errCode")
        # 5) پایداری: همان کاری که بنر ?dev=1 را در نسخه‌ی اول محو می‌کرد،
        #    اینجا عمداً تکرار می‌شود و بعد دوباره خوانده می‌شود. سنجیدنِ
        #    «لحظه‌ی اول» همان اشتباهی بود که آن باگ را سبز نشان داد.
        await jspg.evaluate("() => setNotice('')")
        await jspg.fill("#amtIn", "5")
        await jspg.wait_for_timeout(500)
        await jspg.fill("#amtIn", "")
        await jspg.wait_for_timeout(900)
        js_survived = await jspg.evaluate(
            "() => !document.getElementById('errBanner').hidden")
        js_names = err_names(js_seen[before:])
        js_details = err_details(js_seen[before:])
        await jspg.close()
        print("[err] uncaught throw: code=%r survived quoting=%s beacons=%s details=%s"
              % (js_code, js_survived, js_names, js_details))
        assert not js_hidden, (
            "an uncaught exception left no trace on screen — this is exactly the silent "
            "failure the handler exists to end")
        assert ERRCODE.match(js_code), (
            "the on-screen code is not a reportable code: %r. A user cannot read out "
            "something shaped like this." % js_code)
        assert js_survived, (
            "the error banner vanished once the quote path cleared the notice area. It must "
            "live outside #notices — the same trap the ?dev=1 banner fell into.")
        assert js_names == ["err:js"], (
            "an uncaught exception should send exactly one err:js, got %s" % js_names)
        # d باید دقیقاً همان چهار نویسه‌ی پایانیِ کدِ روی صفحه باشد — نه
        # پیام، نه فایل، نه خط. اگر این دو از هم جدا بیفتند، آمار و گزارشِ
        # خودِ کاربر دیگر به یک باگ اشاره نمی‌کنند.
        assert js_details == [js_code[-4:]], (
            "the beacon's detail (%s) does not match the last four characters of the "
            "on-screen code (%s) — the dashboard and the user's own report would point at "
            "different bugs" % (js_details, js_code))

        # 3) رد شدنِ گرفته‌نشده‌ی promise — کلاسِ جدا، چون async است و هرگز
        #    به window.onerror نمی‌رسد.
        prpg, pr_seen = await err_page()
        before = len(pr_seen)
        await prpg.evaluate("() => { Promise.reject(new Error('zaexa probe: rejected')); }")
        await prpg.wait_for_timeout(700)
        pr_code = await prpg.inner_text("#errCode")
        pr_names = err_names(pr_seen[before:])
        await prpg.close()
        print("[err] unhandled rejection: code=%r beacons=%s" % (pr_code, pr_names))
        assert pr_names == ["err:promise"], (
            "an unhandled promise rejection should send exactly one err:promise, got %s"
            % pr_names)
        assert pr_code.startswith("E-PR-"), (
            "a rejection must be labelled as one, not folded into E-JS: %r" % pr_code)

        # ---- [provider rejection] ۶ اکتبر: ردِ بی‌پشته‌ی EIP-1193 از والت شمرده می‌شود، بنر نمی‌آورد ----
        # (مالک: E-PR-87AD، wallet_getCapabilities، فانتوم روی Base). هر حالت در صفحه‌ی تازه.
        pr_cases = [
            ("a wallet object", "Promise.reject({code: -32601, message: 'the method wallet_getCapabilities does not exist/is not available'})", True),
            ("an Error", "Promise.reject(new Error('ours'))", False),
            ("no numeric code", "Promise.reject({message: 'no code'})", False),
            ("has a stack", "Promise.reject({code: 4001, message: 'x', stack: 'Error: x\\n at https://zaexa.com/app:1:1'})", False),
        ]
        pr_res = []
        for label, js, want_hidden in pr_cases:
            ppg, p_seen = await err_page()
            before = len(p_seen)
            await ppg.evaluate("() => { %s; }" % js)
            await ppg.wait_for_timeout(700)
            hidden = await ppg.evaluate("() => document.getElementById('errBanner').hidden")
            pr_res.append((label, hidden, err_names(p_seen[before:]), err_details(p_seen[before:]), want_hidden))
            await ppg.close()
        print("[provider rejection] " + " | ".join("%s: bannerHidden=%s beacons=%s hex=%s" % r[:4] for r in pr_res))
        for label, hidden, names, hexes, want_hidden in pr_res:
            assert hidden == want_hidden, "%s: banner hidden=%s, expected %s" % (label, hidden, want_hidden)
            assert names == ["err:promise"], "%s: must still be counted exactly once: %s" % (label, names)
        assert pr_res[0][3] == ["87AD"], "the counted hex must stay the owner's 87AD: %s" % pr_res[0][3]

        # 4) لوگوی توکنی که ۴۰۴ می‌دهد رفتار *عادی* است. اگر اینجا بنر بالا
        #    بیاید، روی سایت زنده روی هر توکن بی‌لوگو یک خطای دروغین می‌نشیند.
        impg, im_seen = await err_page()
        before = len(im_seen)
        await impg.evaluate("""() => {
            const i = document.createElement("img");
            i.src = "/no-such-logo-" + Date.now() + ".png";
            document.body.appendChild(i);
        }""")
        await impg.wait_for_timeout(700)
        im_hidden = await impg.evaluate("() => document.getElementById('errBanner').hidden")
        im_names = err_names(im_seen[before:])
        await impg.close()
        print("[err] failed <img>: banner hidden=%s beacons=%s" % (im_hidden, im_names))
        assert im_hidden and not im_names, (
            "a token logo that 404s is normal on this site and must not raise an error "
            "banner (hidden=%s, beacons=%s)" % (im_hidden, im_names))

        # 6) یک باگ = یک کد، در دو بازدید جدا.
        #    ⚠️ اینجا عمداً یک ErrorEvent ساختگی با فیلدهای ثابت شلیک می‌شود.
        #    استثنای واقعیِ بند ۲ ثابت می‌کند گیرنده به خطای *واقعی* وصل است؛
        #    این بند ثابت می‌کند هش برای ورودیِ یکسان ثابت است. هیچ‌کدام به
        #    تنهایی کافی نیست، و throw واقعی شماره‌ی خط ثابتی ندارد که بشود
        #    با آن پایداری را سنجید.
        async def synth_code(msg):
            spg = await b.new_page(viewport={"width": 1240, "height": 1000})
            # Transaction fixtures use fixed non-signing keys; real approval is tested in solana-approval.test.mjs.
            await spg.add_init_script("window.addEventListener('load',()=>{solConfirmConnection=async()=>{};});")
            seen = await watch_events(spg)
            await spg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
            await spg.wait_for_timeout(1300)
            await spg.evaluate("""(m) => dispatchEvent(new ErrorEvent("error", {
                message: m, filename: "zx-probe.js", lineno: 42, colno: 7 }))""", msg)
            await spg.wait_for_timeout(300)
            code = await spg.inner_text("#errCode")
            raw = await spg.evaluate("() => document.getElementById('errRaw').textContent")
            pwned = await spg.evaluate("() => !!window.__zxPwned")
            details = err_details(seen)
            await spg.close()
            return code, raw, pwned, details

        code_a, _, _, det_a = await synth_code("zaexa probe: stable")
        code_b, _, _, det_b = await synth_code("zaexa probe: stable")
        code_c, _, _, det_c = await synth_code("zaexa probe: different")
        print("[err] same fault twice: %s / %s   different fault: %s   details: %s/%s/%s"
              % (code_a, code_b, code_c, det_a, det_b, det_c))
        assert code_a == code_b, (
            "the same fault produced two different codes (%s vs %s) — then two users "
            "reporting the same bug look like two bugs" % (code_a, code_b))
        assert code_a != code_c, (
            "two different faults collapsed onto the same code %s — then two bugs look "
            "like one" % code_a)
        # همان چیزی که برای throw واقعی در بند ۲ سنجیده شد، اینجا برای دو
        # بازدیدِ *جداگانه* از یک فالت: d باید هم با کدِ روی صفحه بخواند و
        # هم بین دو بازدید یکسان بماند — وگرنه «یک باگ» در آمار به دو ردیفِ
        # جدا تبدیل می‌شود.
        assert det_a == [code_a[-4:]], (
            "the beacon detail (%s) does not match the on-screen code's last four "
            "characters (%s)" % (det_a, code_a))
        assert det_a == det_b, (
            "the same fault in two separate page loads produced different beacon details "
            "(%s vs %s) — two reports of one bug would look like two distinct bugs"
            % (det_a, det_b))

        # 7) پیام خطا رشته‌ی کنترل‌نشده است و می‌تواند از ورودیِ خودِ کاربر
        #    بیاید. اگر با innerHTML بنشیند، گزارشِ خطا خودش یک XSS است.
        _, xss_raw, xss_pwned, _ = await synth_code(
            '<img src=x onerror="window.__zxPwned=1">')
        print("[err] hostile message rendered as text: %s (executed=%s)"
              % ("<img" in xss_raw, xss_pwned))
        assert not xss_pwned, "AN ERROR MESSAGE EXECUTED AS HTML IN THE ERROR BANNER"
        assert "<img" in xss_raw, (
            "the hostile message was neither escaped nor shown — it silently vanished, so "
            "this probe would not notice if it started executing: %r" % xss_raw[:120])

        # 8) سقف: یک حلقه‌ی خراب نباید سهمیه‌ی /ev را بسوزاند.
        cappg, cap_seen = await err_page()
        before = len(cap_seen)
        await cappg.evaluate("""() => {
            for (let i = 0; i < 10; i++) {
                dispatchEvent(new ErrorEvent("error", {
                    message: "flood " + i, filename: "f.js", lineno: i, colno: 1 }));
            }
        }""")
        await cappg.wait_for_timeout(700)
        cap_names = err_names(cap_seen[before:])
        await cappg.close()
        print("[err] 10 errors in a row -> %d beacons" % len(cap_names))
        assert 0 < len(cap_names) <= 3, (
            "ten errors produced %d beacons; a broken loop must not burn the /ev quota, "
            "and must not go completely silent either" % len(cap_names))

        # ---- [selector] یک سلکتور فقط وقتی «تابع» است که PUSH4 باشد ----
        # ⚠️ باگ زنده: AERO ریسک ۷۷ گرفت چون جست‌وجوی زیررشته‌ای در بایت‌کد،
        # چهار بایتِ اتفاقی داخل داده را «این تابع وجود دارد» می‌خواند.
        selpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        await selpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await selpg.wait_for_timeout(1300)
        sel = await selpg.evaluate("""() => {
            const s = "deadbeef";
            return {
              // فقط داده: همان چهار بایت، ولی PUSH4 قبلش نیست
              dataOnly: hasSelector("60" + s + "5b", s),
              // توزیع واقعی: 63 = PUSH4
              push4:    hasSelector("6080604052" + "63" + s + "14", s),
              // همان سوزن، ولی از یک موقعیت فرد شروع می‌شود
              odd:      hasSelector("a" + "63" + s + "14", s),
            };
        }""")
        await selpg.close()
        print("[selector] data-only=%s  PUSH4=%s  odd-offset=%s"
              % (sel["dataOnly"], sel["push4"], sel["odd"]))
        assert sel["push4"], (
            "a selector emitted as a real PUSH4 must still be found, or the safety scan "
            "goes blind and every token looks clean")
        assert not sel["dataOnly"], (
            "four bytes sitting in data were counted as a function. That is how AERO — a "
            "blue-chip Base token — scored 77 and told the owner a safe token was dangerous")
        assert not sel["odd"], (
            "the needle matched from an odd hex offset, straddling two bytes; a hex string "
            "search must respect byte boundaries")

        # ---- [err] شکستِ مدل‌شده نباید بنر بالا بیاورد ----
        modpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        mod_seen = await watch_events(modpg)
        await modpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await modpg.wait_for_timeout(1300)
        before = len(mod_seen)
        # همان پرچمی که gtJson روی خطای قطع‌کننده‌ی مدار می‌گذارد
        await modpg.evaluate(
            """() => { const e = new Error("gt: backing off"); e.gtBackoff = true;
                       Promise.reject(e); }""")
        await modpg.wait_for_timeout(700)
        tagged_hidden = await modpg.evaluate(
            "() => document.getElementById('errBanner').hidden")
        # و یک rejection بی‌پرچم باید همچنان دیده شود
        await modpg.evaluate("() => { Promise.reject(new Error('zaexa probe: untagged')); }")
        await modpg.wait_for_timeout(700)
        untagged_shown = await modpg.evaluate(
            "() => !document.getElementById('errBanner').hidden")
        mod_names = [_json3.loads(r)["e"] for r in mod_seen[before:]
                     if _json3.loads(r)["e"].startswith("err:")]
        await modpg.close()
        print("[err] modelled failure silent=%s | untagged still reported=%s | beacons=%s"
              % (tagged_hidden, untagged_shown, mod_names))
        assert tagged_hidden, (
            "a modelled failure (the GeckoTerminal circuit breaker) raised the error banner. "
            "Every one of those states already has its own UI, so this is the guard crying "
            "wolf on a healthy page — measured live on 1 Sep as E-PR-E6FA")
        assert untagged_shown, (
            "silencing modelled failures also silenced a genuine untagged rejection — the "
            "point was to stop crying wolf, not to go blind")
        assert mod_names == ["err:promise"], (
            "expected exactly one beacon, from the untagged rejection only, got %s" % mod_names)

        # ---- [err] خطای افزونه‌ی مرورگر مالِ ما نیست ----
        # ⚠️ باگ زنده: مالک روی صفحه‌ای سالم بنر دید. جزئیاتش
        # «Cannot redefine property: isZerion» از یک chrome-extension:// بود —
        # دو کیف پول سرِ window.ethereum دعوا داشتند. کاربر این سایت اغلب
        # بیش از یک کیف پول نصب دارد، پس این حالت نادر نیست، قاعده است.
        extpg = await b.new_page(viewport={"width": 1240, "height": 1000})
        ext_seen = await watch_events(extpg)
        await extpg.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
        await extpg.wait_for_timeout(1300)
        before = len(ext_seen)
        # rejection با پشته‌ای که از افزونه می‌آید
        await extpg.evaluate("""() => {
            const e = new Error("Cannot redefine property: isZerion");
            e.stack = "TypeError: Cannot redefine property: isZerion\\n"
                    + "    at Object.defineProperty (<anonymous>)\\n"
                    + "    at Object.l (chrome-extension://klghhnkeealcohjjanjjdaeeggmfmlpl"
                    + "/content-script/in-page.js:9:317331)";
            Promise.reject(e);
        }""")
        # و همان چیز به‌شکل رویداد error، که filename دارد
        await extpg.evaluate("""() => dispatchEvent(new ErrorEvent("error", {
            message: "Cannot redefine property: isZerion",
            filename: "chrome-extension://klghhnkeealcohjjanjjdaeeggmfmlpl/in-page.js",
            lineno: 9, colno: 317331 }))""")
        await extpg.wait_for_timeout(700)
        ext_hidden = await extpg.evaluate(
            "() => document.getElementById('errBanner').hidden")
        # ولی یک خطای واقعی از خودِ صفحه باید همچنان دیده شود
        await extpg.evaluate(
            "() => setTimeout(() => { throw new Error('zaexa probe: ours'); }, 0)")
        await extpg.wait_for_timeout(700)
        ours_shown = await extpg.evaluate(
            "() => !document.getElementById('errBanner').hidden")
        ext_names = [_json3.loads(r)["e"] for r in ext_seen[before:]
                     if _json3.loads(r)["e"].startswith("err:")]
        await extpg.close()
        print("[err] extension fault silent=%s | our own fault still reported=%s | beacons=%s"
              % (ext_hidden, ours_shown, ext_names))
        assert ext_hidden, (
            "a fault thrown inside a browser extension raised our error banner. Two wallet "
            "extensions fighting over window.ethereum is normal for this audience, and we "
            "would be blaming our own page for something we did not do and cannot fix")
        assert ours_shown, (
            "filtering extension faults also silenced a real fault from our own code — the "
            "point is to stop taking the blame for others, not to stop reporting")
        assert ext_names == ["err:js"], (
            "expected exactly one beacon, from our own fault only, got %s" % ext_names)

        # ---- [err] یک LINK شکسته: تصمیم با مبدأ است، نه با رشته‌ی آدرس ----
        # ⚠️ باگ زنده روی موبایل: E-RES-5C45، «LINK failed to load
        # https://fonts.reown.com/KHTeka-Medium.woff2» — آن فونت را مودالِ
        # WalletConnect از سرورِ خودش می‌خواهد، نه از ما؛ CSP درست ردش کرد،
        # ولی بنر «چیزی خراب شد» زیرِ عنوانِ صفحه‌ای درباره‌ی دارایی‌های کاربر
        # بالا آمد. این کاوشگر هر دو مسیر را واقعاً اجرا می‌کند — هم‌مبدأ و
        # غیرهم‌مبدأ — نه فرض می‌کند یکی‌شان درست کار می‌کند چون آن یکی درست
        # کار کرد. rel عمداً یک مقدارِ ناشناخته است (نه stylesheet/preload) تا
        # مرورگر خودش هیچ فچِ واقعیِ شبکه‌ای راه نیندازد؛ عنصر باید در سند
        # وصل باشد تا مسیرِ capture:true تا window برسد، بعد خودمان رویداد
        # error را می‌سازیم — دقیقاً همان target/src که یک ۴۰۴ی واقعی می‌داد.
        same_pg, same_seen = await err_page()
        before = len(same_seen)
        await same_pg.evaluate("""() => {
            const l = document.createElement("link");
            l.rel = "zx-test-noop";
            l.href = location.origin + "/no-such-style-" + Date.now() + ".css";
            document.head.appendChild(l);
            l.dispatchEvent(new Event("error"));
            l.remove();
        }""")
        await same_pg.wait_for_timeout(500)
        same_hidden = await same_pg.evaluate(
            "() => document.getElementById('errBanner').hidden")
        same_names = err_names(same_seen[before:])
        await same_pg.close()
        print("[err] same-origin LINK failure: banner hidden=%s beacons=%s"
              % (same_hidden, same_names))
        assert not same_hidden, (
            "a failed same-origin LINK (the ethers/walletconnect bundle case) must still "
            "raise the banner — that failure is genuinely ours and unchanged")
        assert same_names == ["err:res"], (
            "a failed same-origin LINK should send exactly one err:res, got %s" % same_names)

        cross_pg, cross_seen = await err_page()
        before = len(cross_seen)
        await cross_pg.evaluate("""() => {
            const l = document.createElement("link");
            l.rel = "zx-test-noop";
            l.href = "https://fonts.reown.com/KHTeka-Medium.woff2";
            document.head.appendChild(l);
            l.dispatchEvent(new Event("error"));
            l.remove();
        }""")
        await cross_pg.wait_for_timeout(500)
        cross_hidden = await cross_pg.evaluate(
            "() => document.getElementById('errBanner').hidden")
        cross_names = err_names(cross_seen[before:])
        await cross_pg.close()
        print("[err] cross-origin LINK failure (wallet's own font host): banner hidden=%s "
              "beacons=%s" % (cross_hidden, cross_names))
        assert cross_hidden, (
            "a failed cross-origin LINK raised the banner — measured live as E-RES-5C45, a "
            "false alarm under a page about the user's funds when a wallet modal's own font "
            "host was simply unreachable")
        assert cross_names == ["err:res"], (
            "a failed cross-origin LINK must still be counted as err:res even with the banner "
            "staying hidden — a silent third-party failure should still be countable later, "
            "got %s" % cross_names)

        # ---- [pairs page dynamic] web/pairs.html واقعی، با /pairs.json?chain=base استاب‌شده ----
        # همان سرورِ استاتیکِ محلی (srv/port) که چند بخش بالاتر برای
        # WalletConnect/Custom-RPC ساختیم، از روی خودِ web/ سرو می‌شود، پس
        # http://127.0.0.1:<port>/pairs.html همان web/pairs.html واقعی است.
        # فقط /pairs.json?chain=base با page.route استاب می‌شود — این کانتینر
        # هیچ GeckoTerminal یا Baseِ واقعی‌ای ندارد.
        import json as _jsonPairs

        SELL_ROW = {"chain": "base", "address": "0x" + "1" * 40, "symbol": "AAA",
                    "name": "Alpha Coin", "v": "sell", "checkKind": "sell-quote",
                    "checkedAt": "2020-01-01T00:00:00.000Z", "poolCreatedAt": "2020-01-01T00:00:00.000Z",
                    "priceUsd": 0.0000123, "reserveUsd": 28800, "vol24hUsd": 150000,
                    "fdvUsd": 900000, "dex": "uniswap_v3"}
        NOSELL_ROW = {"chain": "base", "address": "0x" + "2" * 40, "symbol": "BBB",
                      "name": "Beta Token", "v": "nosell", "checkKind": "sell-quote",
                      "checkedAt": "2020-01-01T00:00:00.000Z", "poolCreatedAt": "2020-01-01T00:00:00.000Z",
                      "priceUsd": 1.5, "reserveUsd": 500, "vol24hUsd": None,
                      "fdvUsd": None, "dex": "aerodrome"}
        UNKNOWN_ROW = {"chain": "base", "address": "0x" + "3" * 40, "symbol": "CCC",
                       "name": None, "v": None, "checkKind": "sell-quote",
                       "checkedAt": None, "poolCreatedAt": None,
                       "priceUsd": None, "reserveUsd": 0, "vol24hUsd": 0,
                       "fdvUsd": None, "dex": "unknown-dex"}

        async def open_pairs(body_or_status, viewport=None, abort=False, gt_handler=None,
                              extra_routes=None, console_sink=None, path_suffix=""):
            ppg = await b.new_page(viewport=viewport or {"width": 1240, "height": 900})
            perrs = []
            ppg.on("pageerror", lambda e: perrs.append(str(e)))
            if console_sink is not None:
                ppg.on("console", lambda m: console_sink.append(m.text) if m.type == "error" else None)

            async def stub_pairs(route):
                if abort:
                    await route.abort()
                    return
                await route.fulfill(status=200, content_type="application/json",
                                     body=_jsonPairs.dumps(body_or_status))
            await ppg.route("**/pairs.json**", stub_pairs)

            # پیش‌فرض: پاسخِ خالی برای پراکسیِ لوگو (هر دو زنجیره) — کاوشگرهای
            # ۱ تا ۵ (بالا) کاری به لوگو ندارند، فقط نباید یک درخواستِ واقعیِ
            # رهاشده به سرورِ استاتیکِ محلی بخورد. کاوشگرهای [pairs logos]
            # خودشان gt_handler می‌دهند (فقط برای base).
            async def default_gt(route):
                await route.fulfill(status=200, content_type="application/json",
                                     body=_jsonPairs.dumps({"data": []}))
            await ppg.route("**/gt/networks/base/tokens/multi/**", gt_handler or default_gt)
            await ppg.route("**/gt/networks/solana/tokens/multi/**", default_gt)

            if extra_routes:
                for pattern, handler in extra_routes:
                    await ppg.route(pattern, handler)

            await ppg.goto("http://127.0.0.1:%d/pairs.html%s" % (port, path_suffix))
            await ppg.wait_for_timeout(600)
            return ppg, perrs

        # [pairs legend] راهنمای verdict همیشه دیده می‌شود، زیرِ زیرعنوان و بالای تب‌ها؛ details حذف شده؛
        # «Updated …» کنارِ فیلترها روی هیچ‌چیز نمی‌افتد؛ سرریزِ افقی نیست.
        legend_reports = []
        for vw in (360, 390, 768, 1280):
            lpg, lerrs = await open_pairs(
                {"chain": "base", "rows": [SELL_ROW, NOSELL_ROW, UNKNOWN_ROW], "store": True},
                viewport={"width": vw, "height": 900})
            rep = await lpg.evaluate("""() => {
                const r = s => { const e = document.querySelector(s); return e ? e.getBoundingClientRect() : null; };
                const lg = document.getElementById('verdictLegend'), note = r('main .note'), tabs = r('#chainTabs'), L = lg.getBoundingClientRect();
                const items = [...lg.querySelectorAll('.legend-item')].map(li => ({chip: li.querySelector('.badge').className, label: li.querySelector('.badge').textContent,
                    text: li.querySelector('.legend-text').textContent}));
                const upd = r('#updatedAt'), others = [...document.querySelectorAll('#statsStrip .stat-chip, #pairSearch, #pairSort')].map(e => e.getBoundingClientRect());
                const hit = upd && upd.width > 0 ? others.some(o => upd.left < o.right - 0.5 && upd.right > o.left + 0.5 && upd.top < o.bottom - 0.5 && upd.bottom > o.top + 0.5) : false;
                return {visible: L.width > 0 && L.height > 0, below: L.top >= note.bottom - 0.5, above: L.bottom <= tabs.top + 0.5,
                        details: document.querySelectorAll('details.legend-wrap, .legend-wrap, .controls-row details').length,
                        items, overflow: document.documentElement.scrollWidth > innerWidth, updText: document.getElementById('updatedAt').textContent, updOverlap: hit,
                        h: Math.round(L.height)};
            }""")
            legend_reports.append((vw, rep))
            if vw in (390, 1280):
                await lpg.screenshot(path="/tmp/claude-0/shots/pairs-legend-light-%d.png" % vw)
            await lpg.close()
            assert not lerrs, "legend page errors: %s" % lerrs
        print("[pairs legend] always-visible legend under the subtitle: %s" % [(w, r["h"], r["visible"], r["overflow"], r["updOverlap"]) for w, r in legend_reports])
        for vw, rep in legend_reports:
            assert rep["visible"] and rep["below"] and rep["above"], "legend must sit between the subtitle note and the chain tabs at %d: %s" % (vw, rep)
            assert rep["details"] == 0, "the details/summary toggle must be gone: %s" % rep
            assert [i["label"] for i in rep["items"]] == ["Sell quoted", "No sell quote", "Unknown"] and \
                [i["chip"] for i in rep["items"]] == ["badge badge-pos", "badge badge-neg", "badge badge-unknown"], "legend chips: %s" % rep["items"]
            assert [i["text"] for i in rep["items"]] == ["A venue quoted a sell for this token.", "No venue we cover would quote a sell.",
                "We could not check this one. Unknown is not \"safe\" and not \"scam\"."], "legend meanings changed: %s" % rep["items"]
            assert not rep["overflow"] and not rep["updOverlap"], "legend/filter row overflow or overlap at %d: %s" % (vw, rep)

        # [settings button] رنگِ #setBtn همان نوارِ تب است در هر دو تم (اپ و /pairs)
        for url_path, nav_sel in (("/pairs.html", "#nav"), (None, "#nav")):
            sbp = await b.new_page(viewport={"width": 1240, "height": 800})
            await sbp.route("**/pairs.json**", lambda r: r.fulfill(status=200, content_type="application/json", body='{"chain":"base","rows":[],"store":true}'))
            await sbp.goto("http://127.0.0.1:%d%s" % (port, url_path or ck_path))
            await sbp.wait_for_timeout(900)
            for theme in ("light", "dark"):
                await sbp.evaluate("t => document.documentElement.setAttribute('data-theme', t)", theme)
                await sbp.wait_for_timeout(700)   # transition ی رنگ باید تمام شود
                got = await sbp.evaluate("""(sel) => { const g = e => getComputedStyle(e); const b = document.getElementById('setBtn');
                    const ref = sel ? document.querySelector(sel) : document.body;
                    return {bg: g(b).backgroundColor, refBg: g(ref).backgroundColor, border: g(b).borderTopWidth + ' ' + g(b).borderTopColor, line: g(document.documentElement).getPropertyValue('--line').trim()}; }""", nav_sel)
                print("[settings button] %s %s -> %s" % (url_path or "app", theme, got))
                assert got["bg"] == got["refBg"], "setBtn must have the tab bar/page colour (%s, %s): %s" % (url_path or "app", theme, got)
                assert got["border"].startswith("1px "), "setBtn needs the 1px line border in both themes: %s" % got
            await sbp.close()

        # ۱) حالتِ نرمال: هر سه حکم با هم در یک پاسخ
        pg_rows, errs_rows = await open_pairs(
            {"chain": "base", "rows": [SELL_ROW, NOSELL_ROW, UNKNOWN_ROW], "store": True})
        results_hidden = await pg_rows.evaluate("document.getElementById('resultsWrap').hidden")
        badge_texts = await pg_rows.eval_on_selector_all(
            "#rowsBody .badge", "els => els.map(e => e.textContent)")
        row_count = await pg_rows.eval_on_selector_all("#rowsBody tr", "els => els.length")
        first_href = await pg_rows.eval_on_selector(
            "#rowsBody tr:first-child a", "e => e.getAttribute('href')")
        await pg_rows.close()
        print("[pairs page dynamic] rows: resultsHidden=%s rowCount=%s badges=%s firstHref=%s "
              "errors=%s" % (results_hidden, row_count, badge_texts, first_href, errs_rows))
        assert results_hidden is False, (
            "web/pairs.html did not show the results table/cards for a non-empty rows response")
        assert row_count == 3, "expected 3 rendered rows, got %s" % row_count
        assert badge_texts == ["Sell quoted", "No sell quote", "Unknown"], (
            "the three verdict badges did not render with the exact expected labels, in order: %s"
            % badge_texts)
        assert first_href == "/t/" + SELL_ROW["address"], (
            "the first row's link did not point at /t/<address>, got %r" % first_href)
        assert not errs_rows, "web/pairs.html threw while rendering rows: %s" % errs_rows

        # ۲) rows:[] با store:true -> «هنوز چیزی جمع نشده»، نه صفحه‌ی خالی
        pg_empty, errs_empty = await open_pairs({"chain": "base", "rows": [], "store": True})
        empty_hidden = await pg_empty.evaluate("document.getElementById('emptyState').hidden")
        empty_text = (await pg_empty.inner_text("#emptyState")).strip()
        await pg_empty.close()
        print("[pairs page dynamic] empty: hidden=%s text=%r errors=%s"
              % (empty_hidden, empty_text, errs_empty))
        assert empty_hidden is False, "web/pairs.html did not show the empty state for rows:[]"
        assert empty_text == "Nothing collected yet. The hourly job writes at 17 past the hour.", (
            "wrong empty-state copy: %r" % empty_text)

        # ۳) store:false -> «انبار وصل نشده»، جدا از «صفر توکن»
        pg_nostore, errs_nostore = await open_pairs({"chain": "base", "rows": [], "store": False})
        nostore_hidden = await pg_nostore.evaluate("document.getElementById('noStoreState').hidden")
        nostore_text = (await pg_nostore.inner_text("#noStoreState")).strip()
        await pg_nostore.close()
        print("[pairs page dynamic] no-store: hidden=%s text=%r errors=%s"
              % (nostore_hidden, nostore_text, errs_nostore))
        assert nostore_hidden is False, "web/pairs.html did not show the no-store state for store:false"
        assert nostore_text == "The store is not wired up yet.", (
            "wrong no-store-state copy: %r" % nostore_text)

        # ۴) فچِ ناموفق -> پیامِ خطا + دکمه‌ی retry، هرگز جدولِ خالی به‌جای جواب
        pg_err, errs_err = await open_pairs(None, abort=True)
        err_hidden = await pg_err.evaluate("document.getElementById('errorState').hidden")
        err_text = (await pg_err.inner_text("#errorState")).strip()
        retry_visible = await pg_err.eval_on_selector("#retryBtn", "e => !!e")
        await pg_err.close()
        print("[pairs page dynamic] error: hidden=%s text=%r retryButton=%s errors=%s"
              % (err_hidden, err_text, retry_visible, errs_err))
        assert err_hidden is False, "web/pairs.html did not show the error state for a failed fetch"
        assert err_text.startswith("Could not load the list."), (
            "wrong error-state copy: %r" % err_text)
        assert retry_visible, "web/pairs.html's error state has no retry button"

        # ۵) عرضِ باریک -> کارت‌ها، نه جدول
        pg_narrow, errs_narrow = await open_pairs(
            {"chain": "base", "rows": [SELL_ROW], "store": True},
            viewport={"width": 480, "height": 900})
        table_display = await pg_narrow.eval_on_selector(
            ".pairs-table", "e => getComputedStyle(e).display")
        cards_display = await pg_narrow.eval_on_selector(
            ".pairs-cards", "e => getComputedStyle(e).display")
        await pg_narrow.close()
        print("[pairs page dynamic] narrow viewport: table display=%s cards display=%s errors=%s"
              % (table_display, cards_display, errs_narrow))
        assert table_display == "none", "the table did not hide on a narrow viewport"
        assert cards_display != "none", "the card list did not show on a narrow viewport"

        # ---- [pairs search] جعبه‌ی جست‌وجو — روی نماد/نام/آدرس، بدونِ حساسیت
        # به بزرگی‌کوچکیِ حروف، روی همان آرایه‌ی محلی (بدونِ درخواستِ تازه). ----
        SEARCH_ROW_A = dict(SELL_ROW, address="0x" + "a" * 40, symbol="ALPHA", name="Alpha Rocket")
        SEARCH_ROW_B = dict(NOSELL_ROW, address="0x" + "b" * 40, symbol="BETA", name="Beta Fox")
        SEARCH_ROW_C = dict(UNKNOWN_ROW, address="0x" + "c" * 40, symbol="GAMMA", name="Gamma Wolf")
        SEARCH_ROW_D = dict(SELL_ROW, address="0x" + "d" * 40, symbol="DELTA", name="Delta Owl")
        SEARCH_ROWS = [SEARCH_ROW_A, SEARCH_ROW_B, SEARCH_ROW_C, SEARCH_ROW_D]

        pg_s, errs_s = await open_pairs({"chain": "base", "rows": SEARCH_ROWS, "store": True})

        async def visible_syms(page):
            return await page.eval_on_selector_all(
                "#rowsBody .token-sym", "els => els.map(e => e.textContent.trim())")

        async def counts(page):
            r = await page.eval_on_selector_all("#rowsBody tr", "els => els.length")
            c = await page.eval_on_selector_all("#rowsCards > li", "els => els.length")
            no_match_hidden = await page.evaluate("document.getElementById('noMatch').hidden")
            return r, c, no_match_hidden

        async def type_query(page, q):
            await page.fill("#pairSearch", q)
            await page.wait_for_timeout(150)

        r0, c0, nm0 = await counts(pg_s)
        await type_query(pg_s, "ALP")
        r1, c1, nm1 = await counts(pg_s)
        syms1 = await visible_syms(pg_s)
        await type_query(pg_s, ("0x" + "b" * 40).upper())
        r2, c2, nm2 = await counts(pg_s)
        syms2 = await visible_syms(pg_s)
        await type_query(pg_s, "wolf")
        r3, c3, nm3 = await counts(pg_s)
        syms3 = await visible_syms(pg_s)
        await type_query(pg_s, "zzz-nomatch")
        r4, c4, nm4 = await counts(pg_s)
        await type_query(pg_s, "")
        r5, c5, nm5 = await counts(pg_s)
        await pg_s.close()

        print("[pairs search] all=%d/%d(noMatchHidden=%s) symbol-substring=%d/%d %s "
              "addr-substring(mixed case)=%d/%d %s name-substring=%d/%d %s "
              "no-match=%d/%d(noMatchHidden=%s) cleared=%d/%d(noMatchHidden=%s) errors=%s"
              % (r0, c0, nm0, r1, c1, syms1, r2, c2, syms2, r3, c3, syms3,
                 r4, c4, nm4, r5, c5, nm5, errs_s))
        assert (r0, c0) == (4, 4) and nm0 is True, "expected all 4 rows, #noMatch hidden, before typing"
        assert (r1, c1) == (1, 1) and syms1 == ["ALPHA"], (
            "typing a symbol substring did not leave exactly the matching row: %s" % syms1)
        assert (r2, c2) == (1, 1) and syms2 == ["BETA"], (
            "typing a mixed-case address substring did not match: %s" % syms2)
        assert (r3, c3) == (1, 1) and syms3 == ["GAMMA"], (
            "typing a name substring did not match: %s" % syms3)
        assert (r4, c4) == (0, 0) and nm4 is False, (
            "a query matching nothing did not empty the table/cards and show #noMatch")
        assert (r5, c5) == (4, 4) and nm5 is True, (
            "clearing the query did not restore all 4 rows and hide #noMatch")
        assert not errs_s, "web/pairs.html threw while searching: %s" % errs_s

        # ---- [pairs logos] جایگاهِ ۲۴×۲۴ کنارِ نماد — لوگو فقط وقتی پذیرفته
        # می‌شود که image_url رشته باشد، با https:// شروع شود و missing را
        # هم نداشته باشد؛ وگرنه جایگاه خالی می‌ماند (بدونِ حرفِ اول/پس‌زمینه). ----
        LOGO_ROW_A = dict(SELL_ROW, address="0x" + "5" * 40, symbol="LOGA")
        LOGO_ROW_B = dict(SELL_ROW, address="0x" + "6" * 40, symbol="LOGB")
        LOGO_ROW_C = dict(SELL_ROW, address="0x" + "7" * 40, symbol="LOGC")
        LOGO_ROW_D = dict(SELL_ROW, address="0x" + "8" * 40, symbol="LOGD")  # عمداً در پاسخ نیست
        GOOD_LOGO_URL = "https://example.com/tiny.png"
        TINY_PNG = tiny_png_bytes()
        basic_gt_requests = {"n": 0}

        async def serve_tiny_png(route):
            await route.fulfill(status=200, content_type="image/png", body=TINY_PNG)

        async def gt_route_basic(route):
            basic_gt_requests["n"] += 1
            addrs_part = route.request.url.split("multi/", 1)[-1].split("?", 1)[0]
            req = set(a.lower() for a in addrs_part.split(",") if a)
            data = []
            if LOGO_ROW_A["address"].lower() in req:
                data.append({"attributes": {"address": LOGO_ROW_A["address"], "image_url": GOOD_LOGO_URL}})
            if LOGO_ROW_B["address"].lower() in req:
                data.append({"attributes": {"address": LOGO_ROW_B["address"],
                                             "image_url": "https://example.com/missing.png"}})
            if LOGO_ROW_C["address"].lower() in req:
                data.append({"attributes": {"address": LOGO_ROW_C["address"], "image_url": None}})
            await route.fulfill(status=200, content_type="application/json",
                                 body=_jsonPairs.dumps({"data": data}))

        pg_logo, errs_logo = await open_pairs(
            {"chain": "base", "rows": [LOGO_ROW_A, LOGO_ROW_B, LOGO_ROW_C, LOGO_ROW_D], "store": True},
            gt_handler=gt_route_basic, extra_routes=[(GOOD_LOGO_URL, serve_tiny_png)])
        await pg_logo.wait_for_timeout(700)

        # ⚠️ جدول و کارت هیچ‌وقت هم‌زمان دیده نمی‌شوند (۷۶۰px مرزِ رسپانسیو
        # است) — پس فقط نسخه‌ی *دیده‌شده* (اینجا: جدول، عرضِ صفحه ۱۲۴۰) واقعاً
        # بارگذاری می‌شود؛ نسخه‌ی داخلِ display:none طبیعیِ loading="lazy"
        # است که هیچ‌وقت بارگذاری نشود، نه باگِ کدِ ما. اندازه‌ی جایگاه‌ها هم
        # با getComputedStyle سنجیده می‌شود نه getBoundingClientRect — مقدارِ
        # محاسبه‌شده‌ی width/height مستقل از display:none است.
        imgs_a = await pg_logo.evaluate("""() => [...document.querySelectorAll('img')].map(img => ({
            addr: (img.closest('.tok-logo') || {}).getAttribute
                ? img.closest('.tok-logo').getAttribute('data-addr') : null,
            visible: img.offsetWidth > 0 && img.offsetHeight > 0,
            loaded: img.complete && img.naturalWidth > 0,
        }))""")

        async def slot_report(addr):
            return await pg_logo.evaluate("""(addr) => [...document.querySelectorAll(
                '.tok-logo[data-addr="' + addr + '"]')].map(s => {
                const cs = getComputedStyle(s);
                const fb = s.querySelector('.tok-fb');
                return {children: s.childNodes.length, w: cs.width, h: cs.height,
                        bg: cs.backgroundImage, borderW: cs.borderTopWidth,
                        fbText: fb ? fb.textContent : null,
                        fbBg: fb ? fb.style.background : null,
                        fbColor: fb ? getComputedStyle(fb).color : null,
                        fbWeight: fb ? getComputedStyle(fb).fontWeight : null};
            })""", addr)

        slots_b = await slot_report(LOGO_ROW_B["address"])
        slots_c = await slot_report(LOGO_ROW_C["address"])
        slots_d = await slot_report(LOGO_ROW_D["address"])
        reqs_after_initial = basic_gt_requests["n"]

        print("[pairs logos] basic: imgs=%s (want 2, both addr=%s) B-slots=%s C-slots=%s "
              "D-slots=%s requests=%d errors=%s"
              % (imgs_a, LOGO_ROW_A["address"], slots_b, slots_c, slots_d, reqs_after_initial, errs_logo))
        assert len(imgs_a) == 2, "expected exactly 2 <img> on the page (table + card, A only): %s" % imgs_a
        assert all(i["addr"] == LOGO_ROW_A["address"] for i in imgs_a), (
            "the rendered <img>(s) are not both addressed to A: %s" % imgs_a)
        visible_imgs = [i for i in imgs_a if i["visible"]]
        assert visible_imgs and all(i["loaded"] for i in visible_imgs), (
            "the visible <img> for A did not actually load from the stubbed PNG: %s" % imgs_a)
        for label, slots in (("B (missing.png)", slots_b), ("C (image_url:null)", slots_c),
                              ("D (absent from response)", slots_d)):
            assert len(slots) == 2, "expected 2 tok-logo slots for %s, found %d" % (label, len(slots))
            for s in slots:
                # بدون لوگو: یک دایره‌ی گرادیان با حرفِ اولِ نماد، سفید و ضخیم (لوگوی جایگزین)
                assert s["children"] == 1 and s["w"] == "24px" and s["h"] == "24px" and \
                    s["bg"] == "none" and s["borderW"] == "0px", (
                    "the logo-less slot for %s is not a reserved 24x24 box with ONE fallback child: %s" % (label, s))
                assert s["fbText"] and len(s["fbText"]) == 1 and "linear-gradient" in s["fbBg"] and \
                    s["fbColor"] == "rgb(255, 255, 255)" and s["fbWeight"] in ("700", "bold"), (
                    "fallback avatar for %s lacks gradient / single white bold letter: %s" % (label, s))

        # ---- [pairs logos] بعدِ رندرِ دوباره‌ی جست‌وجو، لوگوی A دوباره ظاهر
        # می‌شود بدونِ درخواستِ تازه به /gt (از رویِ Map، نه شبکه). ----
        await pg_logo.fill("#pairSearch", "LOGA")
        await pg_logo.wait_for_timeout(300)
        imgs_after_search = await pg_logo.eval_on_selector_all("img", "els => els.length")
        reqs_after_search = basic_gt_requests["n"]
        await pg_logo.close()
        print("[pairs logos] re-render after search: imgs=%s requests %d -> %d"
              % (imgs_after_search, reqs_after_initial, reqs_after_search))
        assert imgs_after_search == 2, (
            "A's logo did not reappear (table+card) after a search re-render: %s img(s)"
            % imgs_after_search)
        assert reqs_after_search == reqs_after_initial, (
            "a search re-render triggered a new /gt request for an address already answered: "
            "%d -> %d" % (reqs_after_initial, reqs_after_search))
        assert not errs_logo, "web/pairs.html threw during the logos probe: %s" % errs_logo

        # ---- [pairs logos] هر درخواستِ /gt حداکثر ۳۰ آدرس دارد، و هیچ آدرسی
        # دوبار پرسیده نمی‌شود — ۷۰ ردیف، اسکرول تا انتها. ----
        CHUNK_ROWS = [dict(SELL_ROW, address="0x" + format(i + 1, "040x"), symbol="T%d" % i)
                      for i in range(70)]
        seen_requests = []

        async def gt_route_recording(route):
            addrs_part = route.request.url.split("multi/", 1)[-1].split("?", 1)[0]
            seen_requests.append([a for a in addrs_part.split(",") if a])
            await route.fulfill(status=200, content_type="application/json",
                                 body=_jsonPairs.dumps({"data": []}))

        pg_chunk, errs_chunk = await open_pairs(
            {"chain": "base", "rows": CHUNK_ROWS, "store": True}, gt_handler=gt_route_recording)
        await pg_chunk.wait_for_timeout(500)
        await pg_chunk.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        await pg_chunk.wait_for_timeout(1000)
        await pg_chunk.close()

        all_addrs = [a for req in seen_requests for a in req]
        max_len = max((len(req) for req in seen_requests), default=0)
        dup_count = len(all_addrs) - len(set(all_addrs))
        print("[pairs logos] chunking: %d rows -> %d requests, max %d addrs/request, %d total, "
              "%d duplicates, errors=%s"
              % (len(CHUNK_ROWS), len(seen_requests), max_len, len(all_addrs), dup_count, errs_chunk))
        assert seen_requests, "no /gt requests were made for 70 rows — logos never loaded"
        assert max_len <= 25, "a /gt request carried more than 25 addresses: %d" % max_len
        # همان سقفِ واقعیِ پراکسی (PATH_OK: هر بخش ≤۱۲۰۰ نویسه) — ۳۰ آدرس روی سایتِ زنده ۴۰۰ گرفت
        max_seg = max((len(",".join(req)) for req in seen_requests), default=0)
        assert max_seg <= 1200, "a /gt multi segment is %d chars; the proxy rejects >1200 with 400" % max_seg
        assert dup_count == 0, "the same address was requested more than once: %d duplicates" % dup_count
        assert not errs_chunk, "web/pairs.html threw during the chunking probe: %s" % errs_chunk

        # ---- [pairs logos] شکستِ /gt هرگز به کاربر نشان داده نمی‌شود و صفحه
        # نمی‌شکند. ⚠️ یک ۵۰۰ی واقعی را خودِ کرومیوم به‌صورت یک خطای بارگذاریِ
        # منبع در کنسول ثبت می‌کند — چیزی که کدِ ما کنترلش نمی‌کند، نه شکستِ
        # کدِ ما. برای سنجیدنِ *کدِ ما* (سکوتِ کامل)، همان مسیرِ شکست با
        # ۲۰۰ + JSONِ نامعتبر ساخته شده: fetch موفق می‌شود، res.json() شکست
        # می‌خورد، catch بی‌صدا می‌بلعدش — نتیجه برای کاربر یکسان است. ----
        ERR_ROW = dict(SELL_ROW, address="0x" + "9" * 40, symbol="ERRT")

        async def gt_route_broken(route):
            await route.fulfill(status=200, content_type="application/json", body="not valid json{{{")

        cerrs_gt = []
        pg_500, errs_500 = await open_pairs(
            {"chain": "base", "rows": [ERR_ROW], "store": True},
            gt_handler=gt_route_broken, console_sink=cerrs_gt)
        await pg_500.wait_for_timeout(700)
        img_count6 = await pg_500.eval_on_selector_all("img", "els => els.length")
        results_hidden6 = await pg_500.evaluate("document.getElementById('resultsWrap').hidden")
        row_count6 = await pg_500.eval_on_selector_all("#rowsBody tr", "els => els.length")
        await pg_500.close()
        print("[pairs logos] /gt failure (200 + invalid JSON, standing in for a 500 — see report): "
              "imgs=%s resultsHidden=%s rowCount=%s pageErrors=%s consoleErrors=%s"
              % (img_count6, results_hidden6, row_count6, errs_500, cerrs_gt))
        assert img_count6 == 0, "an <img> appeared even though the /gt response was invalid"
        assert results_hidden6 is False, "the page hid its results because /gt failed — rows must still show"
        assert row_count6 == 1, "the row disappeared because /gt failed"
        assert not errs_500, "web/pairs.html threw while /gt failed: %s" % errs_500
        assert not cerrs_gt, "our code logged a console error when /gt failed: %s" % cerrs_gt

        # ---- [pairs logos] یک شکستِ گذرا نباید برای همیشه «لوگو ندارد» ثبت
        # شود — بارِ اول /gt نامعتبر است، بعد یک رندرِ دوباره (جست‌وجو) جایگاه
        # را تازه می‌سازد و دوباره صف می‌کند؛ این‌بار /gt جواب می‌دهد و باید
        # لوگو را ببینیم. اگر شکست در Map ذخیره می‌شد، این آدرس دیگر هیچ‌وقت
        # دوباره پرسیده نمی‌شد. ----
        RECOVER_ROW = dict(SELL_ROW, address="0x" + "f" * 40, symbol="RECOV")
        recover_calls = {"n": 0, "ready": False}

        # ⚠️ ۲۳ سپتامبر: به‌جای شکست‌دادنِ فقط *اولین* فراخوان، هر فراخوانی
        # پیش از اینکه تست صریحاً «ready» را ست کند شکست می‌خورد. این صفحه
        # همزمان با فچِ اولویت‌دار (requestPriorityLogos) خودِ همان جایگاه را
        # observeLogoSlots هم می‌کند، و رقابتِ IntersectionObserver در برابرِ
        # حل‌شدنِ Promise می‌تواند گاهی یک تلاشِ دومِ زودهنگام هم بزند — با
        # هدرِ بزرگ‌ترِ این صفحه (بعد از پارت ۲) این رقابت زودتر از قبل حل
        # می‌شود. آن تلاشِ زودهنگام هم باید شکست بخورد؛ فقط فراخوانی که واقعاً
        # *بعد از جست‌وجو* می‌آید باید موفق شود — همان چیزی که این کاوشگر
        # واقعاً می‌خواهد اثبات کند.
        async def gt_route_recover(route):
            recover_calls["n"] += 1
            if not recover_calls["ready"]:
                await route.fulfill(status=200, content_type="application/json", body="not valid json{{{")
                return
            addrs_part = route.request.url.split("multi/", 1)[-1].split("?", 1)[0]
            req = set(a.lower() for a in addrs_part.split(",") if a)
            data = []
            if RECOVER_ROW["address"].lower() in req:
                data.append({"attributes": {"address": RECOVER_ROW["address"], "image_url": GOOD_LOGO_URL}})
            await route.fulfill(status=200, content_type="application/json",
                                 body=_jsonPairs.dumps({"data": data}))

        pg_recover, errs_recover = await open_pairs(
            {"chain": "base", "rows": [RECOVER_ROW], "store": True},
            gt_handler=gt_route_recover, extra_routes=[(GOOD_LOGO_URL, serve_tiny_png)])
        # ۴ اکتبر — لرزش: انتظارِ ثابتِ ۷۰۰ms گاهی کم بود (دیبانسِ جست‌وجو + صفِ لوگو).
        # حالا تا وقتی شرط برقرار شود صبر می‌کنیم (سقفِ ۸ ثانیه) — خودِ ادعا عوض نشده.
        for _ in range(80):
            if recover_calls["n"] >= 1:
                break
            await pg_recover.wait_for_timeout(100)
        await pg_recover.wait_for_timeout(300)
        imgs_before_recover = await pg_recover.eval_on_selector_all("img", "els => els.length")
        calls_before_recover = recover_calls["n"]
        # جست‌وجو -> رندرِ دوباره -> جایگاهِ تازه دوباره صف می‌شود -> این‌بار /gt جواب می‌دهد
        recover_calls["ready"] = True
        await pg_recover.fill("#pairSearch", "RECOV")
        imgs_after_recover = 0
        for _ in range(80):
            imgs_after_recover = await pg_recover.eval_on_selector_all("img", "els => els.length")
            if imgs_after_recover >= 2:
                break
            await pg_recover.wait_for_timeout(100)
        await pg_recover.close()
        print("[pairs logos] retry after failure: callsBeforeSearch=%d imgs before=%s "
              "after re-render+gt-recovery=%s gt-calls=%d errors=%s"
              % (calls_before_recover, imgs_before_recover, imgs_after_recover,
                 recover_calls["n"], errs_recover))
        assert calls_before_recover >= 1, "the priority fetch never called /gt before the search"
        assert imgs_before_recover == 0, (
            "an <img> appeared even though every /gt request before the search was invalid: %s"
            % imgs_before_recover)
        assert imgs_after_recover == 2, (
            "the logo never appeared after /gt recovered — a failed request must not be cached, "
            "so the address is retried the next time its slot is observed: %s" % imgs_after_recover)
        assert not errs_recover, "web/pairs.html threw during the retry-after-failure probe: %s" % errs_recover

        # ---- [pairs verdict note] یادداشتِ زیرِ نشانِ رأی — از رویِ کلیدهای تازه‌ی
        # Worker (ret/cause/follow/followAt/recheck/recheckAt/recheckCause). هر ردیف
        # دقیقاً یکی از حالت‌های واقعیِ /pairs.json را می‌سنجد؛ نامعتبرها هرگز رندر
        # نمی‌شوند، و یک <img> تزریق‌شده در یک رشته هرگز به یک عنصرِ واقعی نمی‌رسد. ----
        def note_addr(n):
            return "0x" + format(n, "040x")

        NOTE_SELL_RET = dict(SELL_ROW, address=note_addr(101), ret=42.5)
        NOTE_SELL_RET_FOLLOW_EMPTY = dict(
            SELL_ROW, address=note_addr(102), ret=1.0,
            follow="pool-empty", followAt="2026-01-01T00:00:00.000Z")
        NOTE_NOSELL_CAUSE = dict(NOSELL_ROW, address=note_addr(103), cause="empty-pool")
        NOTE_NULL_RECHECK_SELL = dict(
            UNKNOWN_ROW, address=note_addr(104),
            recheck="sell", recheckAt="2026-02-02T00:00:00.000Z")
        NOTE_NULL_RECHECK_NOSELL_CAUSE = dict(
            UNKNOWN_ROW, address=note_addr(105), recheck="nosell",
            recheckAt="2026-03-03T00:00:00.000Z", recheckCause="empty-pool")
        NOTE_NULL_RECHECK_NOSELL_NOCAUSE = dict(
            UNKNOWN_ROW, address=note_addr(106),
            recheck="nosell", recheckAt="2026-04-04T00:00:00.000Z")
        NOTE_PLAIN_SELL = dict(SELL_ROW, address=note_addr(107))   # هیچ کلید تازه‌ای ندارد

        NOTE_BAD_RET_ZERO = dict(SELL_ROW, address=note_addr(108), ret=0)
        NOTE_BAD_RET_HIGH = dict(SELL_ROW, address=note_addr(109), ret=5000)
        NOTE_BAD_RET_STR = dict(SELL_ROW, address=note_addr(110), ret="98")
        NOTE_BAD_FOLLOW = dict(SELL_ROW, address=note_addr(111), follow="maybe")
        NOTE_BAD_RECHECK_ON_SELL = dict(
            SELL_ROW, address=note_addr(112),
            recheck="sell", recheckAt="2026-05-05T00:00:00.000Z")
        NOTE_BAD_CAUSE_ON_SELL = dict(SELL_ROW, address=note_addr(113), cause="empty-pool")
        NOTE_INJECTED_ISO = dict(
            UNKNOWN_ROW, address=note_addr(114),
            recheck="sell", recheckAt="<img src=x onerror=alert(1)>")

        NOTE_ROWS = [
            NOTE_SELL_RET, NOTE_SELL_RET_FOLLOW_EMPTY, NOTE_NOSELL_CAUSE,
            NOTE_NULL_RECHECK_SELL, NOTE_NULL_RECHECK_NOSELL_CAUSE,
            NOTE_NULL_RECHECK_NOSELL_NOCAUSE, NOTE_PLAIN_SELL,
            NOTE_BAD_RET_ZERO, NOTE_BAD_RET_HIGH, NOTE_BAD_RET_STR, NOTE_BAD_FOLLOW,
            NOTE_BAD_RECHECK_ON_SELL, NOTE_BAD_CAUSE_ON_SELL, NOTE_INJECTED_ISO,
        ]

        note_pg, note_errs = await open_pairs({"chain": "base", "rows": NOTE_ROWS, "store": True})
        note_info = await note_pg.evaluate("""() => {
            const rows = Array.from(document.querySelectorAll('#rowsBody tr'));
            const cards = Array.from(document.querySelectorAll('#rowsCards .card'));
            function pick(list) {
                return list.map(el => {
                    const n = el.querySelector('.verdict-note');
                    return n ? {text: n.textContent, title: n.getAttribute('title'),
                                imgCount: n.querySelectorAll('img').length} : null;
                });
            }
            return {table: pick(rows), cards: pick(cards)};
        }""")
        await note_pg.close()
        print("[pairs verdict note] table=%r" % note_info["table"])
        print("[pairs verdict note] cards=%r" % note_info["cards"])
        assert not note_errs, "web/pairs.html threw while rendering verdict notes: %s" % note_errs

        EXPECTED_NOTES = [
            "Quote back 42.5%",
            "Quote back 1.0% · Later: pool empty",
            "Pool has no liquidity",
            "Later: sell quoted",
            "Later: pool empty",
            "Later: no sell quoted",
            None,   # NOTE_PLAIN_SELL — هیچ کلید تازه‌ای ندارد
            None,   # ret 0 — بیرونِ بازه
            None,   # ret 5000 — بیرونِ بازه
            None,   # ret "98" — رشته، نه عدد
            None,   # follow "maybe" — بیرونِ واژه‌نامه
            None,   # recheck روی یک ردیفِ sell — کلید فقط برای v===null معنا دارد
            None,   # cause روی یک ردیفِ sell — کلید فقط برای nosell معنا دارد
            "Later: sell quoted",  # recheckAt تزریق‌شده — متن سالم می‌ماند
        ]
        for i, expect in enumerate(EXPECTED_NOTES):
            for surface, got in (("table", note_info["table"][i]), ("card", note_info["cards"][i])):
                if expect is None:
                    assert got is None, (
                        "row %d (%s) rendered a .verdict-note where none was expected: %r"
                        % (i, surface, got))
                else:
                    assert got is not None and got["text"] == expect, (
                        "row %d (%s) verdict-note text mismatch: expected %r, got %r"
                        % (i, surface, expect, got))

        cause_row = note_info["table"][2]
        assert cause_row["title"] is None, (
            "a note with no later-observation part must carry no title attribute, got %r"
            % cause_row["title"])
        follow_row = note_info["table"][1]
        assert follow_row["title"] == NOTE_SELL_RET_FOLLOW_EMPTY["followAt"], (
            "the later-observation title must carry followAt verbatim: %r" % follow_row)
        recheck_row = note_info["table"][3]
        assert recheck_row["title"] == NOTE_NULL_RECHECK_SELL["recheckAt"], (
            "the later-observation title must carry recheckAt verbatim: %r" % recheck_row)
        inj_row_table = note_info["table"][13]
        inj_row_card = note_info["cards"][13]
        assert inj_row_table["imgCount"] == 0 and inj_row_card["imgCount"] == 0, (
            "an injected <img> in recheckAt became a real element: %r / %r"
            % (inj_row_table, inj_row_card))
        assert inj_row_table["title"] == NOTE_INJECTED_ISO["recheckAt"], (
            "the title attribute must round-trip the raw ISO text through esc(), got %r"
            % inj_row_table["title"])

        # ---- [pairs verdict note] بوم‌سنج: یادداشت هرگز از سلول/کارت بیرون نمی‌زند،
        # نه در دسکتاپ نه در ۳۹۰px — با getBoundingClientRect، نه با چشم. ----
        LONG_NOTE_ROW = dict(
            SELL_ROW, address=note_addr(120), ret=999.9,
            follow="pool-there", followAt="2026-06-06T00:00:00.000Z")
        for width, label, sel_wrap in ((1280, "desktop", "#rowsBody .verdict-note"),
                                        (390, "390px", "#rowsCards .verdict-note")):
            bpg, berrs = await open_pairs(
                {"chain": "base", "rows": [LONG_NOTE_ROW], "store": True},
                viewport={"width": width, "height": 900})
            box = await bpg.evaluate("""(sel) => {
                const note = document.querySelector(sel);
                const container = note.closest('td') || note.closest('.card');
                const nr = note.getBoundingClientRect();
                const cr = container.getBoundingClientRect();
                return {
                    noteRight: nr.right, noteLeft: nr.left, noteWidth: nr.width,
                    containerRight: cr.right, containerLeft: cr.left,
                    whiteSpace: getComputedStyle(note).whiteSpace,
                    docOverflowX: document.documentElement.scrollWidth
                        - document.documentElement.clientWidth
                };
            }""", sel_wrap)
            await bpg.close()
            print("[pairs verdict note] %s width=%d box=%r errors=%s"
                  % (label, width, box, berrs))
            assert not berrs, "web/pairs.html threw at %s width: %s" % (label, berrs)
            assert box["noteRight"] <= box["containerRight"] + 1, (
                "the verdict-note overflows its %s container on the right at %s: %r"
                % (label, label, box))
            assert box["noteLeft"] >= box["containerLeft"] - 1, (
                "the verdict-note overflows its %s container on the left at %s: %r"
                % (label, label, box))
            assert box["docOverflowX"] <= 1, (
                "the page scrolls horizontally at %s — the note forced an overflow: %r"
                % (label, box))
            assert box["whiteSpace"] != "nowrap", (
                "the verdict-note's white-space is nowrap — it can never wrap at %s: %r"
                % (label, box))

        # ---- [pairs header] هدرِ تازه‌ی pairs.html — همان الگوی ناوبریِ اپ:
        # برند/ناوبریِ مرکزی/دکمه‌ی تم، بدونِ .header-cta. ----
        hpg, herrs = await open_pairs({"chain": "base", "rows": [], "store": True})
        hinfo = await hpg.evaluate("""() => {
            const nav = document.querySelector('.nav');
            const links = nav ? [...nav.querySelectorAll('a')] : [];   // از ۱۸ اکتبر Markets دکمه است و منو ندارد؛ <a>ها فقط Swap/Stocks/Exit Report اند
            const hdr = document.querySelector('.site-header').getBoundingClientRect();
            const navR = nav.getBoundingClientRect();
            return {
                count: links.length,
                hrefs: links.map(a => a.getAttribute('href')),
                lastCurrent: links.some(a => a.getAttribute('href') === '/pairs'),
                lastOn: document.getElementById('navMarkets').classList.contains('on'),
                navCenter: Math.round(navR.left + navR.width / 2),
                hdrCenter: Math.round(hdr.left + hdr.width / 2),
                hasCta: !!document.querySelector('.header-cta'),
                hasFavicon: !!document.querySelector('link[rel="icon"]'),
            };
        }""")
        await hpg.close()
        print("[pairs header] links=%s hrefs=%s lastCurrent=%s lastOn=%s navCenter=%s hdrCenter=%s "
              "hasCta=%s hasFavicon=%s errors=%s"
              % (hinfo["count"], hinfo["hrefs"], hinfo["lastCurrent"], hinfo["lastOn"],
                 hinfo["navCenter"], hinfo["hdrCenter"], hinfo["hasCta"], hinfo["hasFavicon"], herrs))
        # ۱۸ اکتبر (تغییر عمدی): Flow و New pairs از منو رفتند و Markets دکمه‌ی ساده است، پس <a>های هدر سه‌تاست
        # (Swap، Stocks، Exit Report) و هیچ <a href="/pairs"> در نوار نیست؛ «روشن‌بودنِ» Markets جای aria-current را می‌گیرد.
        assert hinfo["count"] == 3, "expected 3 nav links in pairs.html's header (Swap, Stocks, Exit Report), found %s" % hinfo["count"]
        assert hinfo["hrefs"] == ["/app#swap", "/app#stocks", "/report"], (
            "pairs.html's header nav hrefs are wrong: %s" % hinfo["hrefs"])
        assert hinfo["lastCurrent"] is False, "no a[href=\"/pairs\"] may remain in the header nav"
        assert hinfo["lastOn"], "the Markets tab must carry the .on look on /pairs"
        assert abs(hinfo["navCenter"] - hinfo["hdrCenter"]) <= 2, (
            "pairs.html's header nav is not centred at 1240px: nav=%s header=%s"
            % (hinfo["navCenter"], hinfo["hdrCenter"]))
        assert not hinfo["hasCta"], "pairs.html's header must not have a .header-cta any more"
        assert hinfo["hasFavicon"], "pairs.html is missing a <link rel=\"icon\">"
        assert not herrs, "web/pairs.html threw while rendering the header: %s" % herrs

        hpg2, herrs2 = await open_pairs({"chain": "base", "rows": [], "store": True})
        await hpg2.set_viewport_size({"width": 800, "height": 900})
        await hpg2.wait_for_timeout(150)
        band800 = await hpg2.evaluate(
            """() => { const s = document.querySelector('.nav > a span');
                       return s ? getComputedStyle(s).display : null; }""")
        print("[pairs header] 800px label display=%s" % band800)
        assert band800 == "none", "pairs.html's nav labels are not hidden at 800px: %s" % band800

        for w in (390, 360):
            await hpg2.set_viewport_size({"width": w, "height": 844})
            await hpg2.wait_for_timeout(150)
            mob = await hpg2.evaluate("""() => {
                const items = [...document.querySelectorAll('.nav > *')];
                const cs = getComputedStyle(document.querySelector('.nav'));
                return {
                    count: items.length,
                    position: cs.position,
                    widths: items.map(a => Math.round(a.getBoundingClientRect().width)),
                    scrollW: document.documentElement.scrollWidth,
                    innerW: innerWidth,
                };
            }""")
            print("[pairs header] mobile %spx: %s" % (w, mob))
            assert mob["count"] == 4, "expected 4 nav items at %spx, found %s" % (w, mob["count"])
            assert mob["position"] == "fixed", "pairs.html's nav is not fixed at %spx" % w
            assert max(mob["widths"]) - min(mob["widths"]) <= 4, (
                "pairs.html's 4 bottom-nav items are not equal width at %spx: %s" % (w, mob["widths"]))
            assert mob["scrollW"] <= mob["innerW"], (
                "pairs.html scrolls horizontally at %spx (%s > %s)"
                % (w, mob["scrollW"], mob["innerW"]))
        await hpg2.close()
        assert not herrs2, "web/pairs.html threw while resizing the header: %s" % herrs2

        print("[pairs header] 3 nav links (Swap/Stocks/Exit Report) plus the Markets button, with the right hrefs, no /pairs link in the bar, "
              "Markets carries the .on look, centred at 1240px, labels hidden at "
              "800px, fixed 4-equal-width bottom bar at 390/360px with no horizontal scroll, no "
              ".header-cta, favicon present")

        # ---- [pairs chain] تب‌های Base/Solana — URL، fetch، Trade فقط روی
        # Base، برچسبِ چیپ‌های سولانا Passed/Failed/Unknown. ----
        SOLANA_SELL_ROW = {"chain": "solana", "address": "Sol" + "1" * 41, "symbol": "SOLA",
                            "name": "Sol Alpha", "v": "sell", "checkKind": "sell-quote",
                            "checkedAt": "2020-01-01T00:00:00.000Z",
                            "poolCreatedAt": "2020-01-01T00:00:00.000Z",
                            "priceUsd": 0.05, "reserveUsd": 12000, "vol24hUsd": 3000,
                            "fdvUsd": 500000, "dex": "raydium"}

        requested_urls = []

        async def stub_pairs_track(route):
            requested_urls.append(route.request.url)
            is_solana = "chain=solana" in (route.request.url.split("?", 1)[-1])
            body = {"chain": "solana" if is_solana else "base",
                    "rows": [SOLANA_SELL_ROW] if is_solana else [SELL_ROW], "store": True}
            await route.fulfill(status=200, content_type="application/json", body=_jsonPairs.dumps(body))

        async def empty_gt(route):
            await route.fulfill(status=200, content_type="application/json",
                                 body=_jsonPairs.dumps({"data": []}))

        cpg = await b.new_page(viewport={"width": 1240, "height": 900})
        cerrs = []
        cpg.on("pageerror", lambda e: cerrs.append(str(e)))
        await cpg.route("**/pairs.json**", stub_pairs_track)
        await cpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await cpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await cpg.goto("http://127.0.0.1:%d/pairs.html?chain=solana" % port)
        await cpg.wait_for_timeout(500)
        first_url = requested_urls[-1] if requested_urls else None
        trade_count_solana = await cpg.eval_on_selector_all("#rowsBody .trade-btn", "els => els.length")
        chip_texts_solana = await cpg.eval_on_selector_all(
            "#statsStrip .stat-chip", "els => els.map(e => e.textContent)")
        copy_solana = await cpg.evaluate(
            "() => [document.querySelector('.pairs-main .sub').textContent,"
            " document.querySelector('.pairs-main .note').textContent]")

        await cpg.click('.chain-tabs button[data-chain="base"]')
        await cpg.wait_for_timeout(500)
        second_url = requested_urls[-1] if requested_urls else None
        url_after_click = cpg.url
        copy_base = await cpg.evaluate(
            "() => [document.querySelector('.pairs-main .sub').textContent,"
            " document.querySelector('.pairs-main .note').textContent]")
        # زیرتیتر و یادداشتِ Base ادعای «کوتِ فروش» دارند — روی سولانا (شبیه‌سازی) غلط بود
        print("[pairs chain] copy solana=%s base=%s" % (copy_solana, copy_base))
        assert "Solana" in copy_solana[0] and "Base" not in copy_solana[0], (
            "on the Solana tab the sub-heading must speak about Solana, got %r" % copy_solana[0])
        assert "sell quote" not in copy_solana[1].lower(), (
            "on the Solana tab the note must not claim a sell quote, got %r" % copy_solana[1])
        assert copy_base[0] == ("The newest Base pools we found, each run through the same exit check "
                                "as the app. Updated hourly."), (
            "switching back to Base must restore the exact Base sub-heading, got %r" % copy_base[0])
        assert copy_base[1].startswith("A sell quote is not a promise."), (
            "switching back to Base must restore the exact permanent note, got %r" % copy_base[1])
        trade_count_base = await cpg.eval_on_selector_all("#rowsBody .trade-btn", "els => els.length")
        await cpg.close()

        print("[pairs chain] initial url=%s trade(solana)=%s chips(solana)=%s -> click Base: url=%s "
              "pageUrl=%s trade(base)=%s errors=%s"
              % (first_url, trade_count_solana, chip_texts_solana, second_url, url_after_click,
                 trade_count_base, cerrs))
        assert first_url and "chain=solana" in first_url, (
            "loading /pairs.html?chain=solana did not request chain=solana, got %s" % first_url)
        assert trade_count_solana == 1, (
            "a Solana row must show a Trade link, found %d" % trade_count_solana)
        assert chip_texts_solana == ["All 1", "Passed 1", "Failed 0", "Unknown 0"], (
            "the Solana stat chips must read Passed/Failed/Unknown, got %s" % chip_texts_solana)
        assert second_url and "chain=base" in second_url, (
            "clicking the Base tab did not request chain=base, got %s" % second_url)
        assert "chain=solana" not in url_after_click, (
            "the page URL must drop ?chain= entirely for base (absent means base), got %s"
            % url_after_click)
        assert trade_count_base == 1, (
            "a Base row must show a Trade link after switching back, found %d" % trade_count_base)
        assert not cerrs, "web/pairs.html threw while switching chains: %s" % cerrs

        print("[pairs chain] pairs.html?chain=solana requests /pairs.json?chain=solana; clicking the "
              "Base tab switches both the request and the URL (absent chain param = base); Solana "
              "rows show no Trade link; Solana chip labels read Passed/Failed/Unknown")

        # ---- [chain switch] گزینشگرِ شبکه در هدرِ /app — Base/Solana ----
        # همان الگوی [sol swap]: کیف‌پولِ جعلیِ Wallet Standard با
        # add_init_script، و استابِ /sol/quote، /gt/networks/solana/tokens/**،
        # /vd/**، /sol/rpc. هیچ Jupiter/RPC/GT واقعی لمس نمی‌شود.
        CS_MINT_USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"

        async def cs_stub_gt(route):
            await route.fulfill(status=200, content_type="application/json", body=swap_gt_body())

        async def cs_stub_vd(route):
            await route.fulfill(status=200, content_type="application/json",
                                 body=_json.dumps({"v": "sell", "ms": 100}))

        async def cs_stub_quote(route):
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps(SOL_QUOTE_FIXTURE))

        async def cs_stub_rpc(route):
            payload = _json.loads(route.request.post_data or "{}")
            method = payload.get("method")
            if method == "getBalance":
                result = {"value": 2000000000}
            elif method == "getTokenAccountsByOwner":
                result = {"value": []}
            else:
                result = None
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps({"result": result}))

        async def cs_stub_ev(route):
            await route.fulfill(status=204, body="")

        async def open_app(hash_suffix="", inject_wallet=True, collect_errors=None, viewport=None,
                            extra_init_script=None):
            apg = await b.new_page(viewport=viewport or {"width": 1280, "height": 900})
            if collect_errors is not None:
                apg.on("console", lambda m: collect_errors.append(m.text) if m.type == "error" else None)
                apg.on("pageerror", lambda e: collect_errors.append(str(e)))
            if extra_init_script:
                await apg.add_init_script(extra_init_script)
            if inject_wallet:
                # کیف‌پولِ جعلی — با add_init_script، پس همیشه *پیش* از هر
                # اسکریپتِ خودِ صفحه شنونده‌ی app-ready را نصب می‌کند؛ یعنی
                # دقیقاً سناریوی «کیف‌پولی که پیش از دست‌زدنِ کاربر ثبت شده».
                # کشفش فقط به این بستگی دارد که *خودِ اپ* app-ready را زود
                # بفرستد (solWalletStandardInit در همان اولِ بولوت) — نه به
                # اینکه کاربر چه زمانی گزینشگر را باز می‌کند.
                await apg.add_init_script(SOL_FAKE_WALLET_INIT)
                # Real cryptographic approval has dedicated tests; this fixture tests chain routing.
                await apg.add_init_script("window.addEventListener('load',()=>{solConfirmConnection=async()=>{};});")
            await apg.route("**/ev", cs_stub_ev)
            # جفتِ پیش‌فرضِ Base هم روی بارگذاریِ /app لوگو/نمودار می‌خواهد
            # (multi، pools?page=1، ohlcv). اگر هیچ‌کدام استاب نشوند، چند
            # تلاشِ ناموفقِ پیاپی روی شبکه‌ی این کانتینر یک backoffِ ۶۰ثانیه‌ای
            # سراسری (gtCoolUntil) روشن می‌کند که بعداً fetchSolMeta را هم
            # بی‌جهت شکست می‌دهد — پس اول یک استابِ عمومیِ «هیچی نیست» برای
            # کلِ /gt، بعد استابِ اختصاصیِ سولانا رویش (آخرین route ثبت‌شده
            # برنده است).
            await apg.route("**/gt/**",
                             lambda route: route.fulfill(status=200, content_type="application/json",
                                                           body=_json.dumps({"data": []})))
            await apg.route("**/gt/networks/solana/tokens/**", cs_stub_gt)
            await apg.route("**/vd/**", cs_stub_vd)
            await apg.route("**/sol/quote**", cs_stub_quote)
            await apg.route("**/sol/rpc", cs_stub_rpc)
            await apg.goto("http://127.0.0.1:%d/%s" % (port, hash_suffix))
            await apg.wait_for_timeout(600)
            return apg

        # الف) گزینشگر Base/Solana را فهرست می‌کند
        a1 = await open_app()
        cs_opts = await a1.eval_on_selector_all(
            "#srcPop [data-chain]", "els => els.map(e => e.textContent.trim())")
        await a1.close()
        print("[chain switch] selector options=%s" % cs_opts)
        assert cs_opts == ["Base", "Solana"], "the network selector must list exactly Base then Solana: %s" % cs_opts

        # ب) انتخابِ Solana کارتِ Solana را نشان و کارت‌های Base-only را
        # پنهان می‌کند؛ برگشت به Base همه چیز را برمی‌گرداند.
        b1 = await open_app()
        await b1.click("#srcChip")
        await b1.click('#srcPop [data-chain="solana"]')
        await b1.wait_for_timeout(200)
        b_state_sol = await b1.evaluate("""() => ({
            appSolHeroHidden: document.getElementById('appSolHero').hidden,
            baseHeroHidden: document.getElementById('baseHeroRow').hidden,
            baseSubHidden: document.getElementById('baseSubRow').hidden,
            solSwapHidden: document.getElementById('solSwap').hidden,
            srcTx: document.getElementById('srcTx').textContent,
        })""")
        await b1.click("#srcChip")
        await b1.click('#srcPop [data-chain="base"]')
        await b1.wait_for_timeout(200)
        b_state_base = await b1.evaluate("""() => ({
            appSolHeroHidden: document.getElementById('appSolHero').hidden,
            baseHeroHidden: document.getElementById('baseHeroRow').hidden,
            baseSubHidden: document.getElementById('baseSubRow').hidden,
            solSwapHidden: document.getElementById('solSwap').hidden,
            srcTx: document.getElementById('srcTx').textContent,
        })""")
        await b1.close()
        print("[chain switch] solana=%s base=%s" % (b_state_sol, b_state_base))
        assert b_state_sol == {"appSolHeroHidden": False, "baseHeroHidden": True,
                                "baseSubHidden": True, "solSwapHidden": False, "srcTx": "Solana"}, \
            "choosing Solana must show the Solana swap card and hide the Base-only cards: %s" % b_state_sol
        assert b_state_base == {"appSolHeroHidden": True, "baseHeroHidden": False,
                                 "baseSubHidden": False, "solSwapHidden": True, "srcTx": "Base"}, \
            "switching back to Base must restore the Base cards and hide the Solana card: %s" % b_state_base

        # پ) هدر «Connect» روی Solana گزینشگرِ سولانا را باز می‌کند (نه منوی
        # EVM)، فهرستِ کیف‌پولِ جعلی را نشان می‌دهد، و بعد از اتصال آدرسِ
        # کوتاه را در هدر می‌نویسد.
        c1 = await open_app()
        await c1.click("#srcChip")
        await c1.click('#srcPop [data-chain="solana"]')
        await c1.wait_for_timeout(150)
        await c1.click("#connectBtn")
        await c1.wait_for_timeout(300)
        c_picker_on = await c1.eval_on_selector("#solWalletOv", "el => el.classList.contains('on')")
        c_evm_menu_on = await c1.eval_on_selector("#walletOv", "el => el.classList.contains('on')")
        c_wal_text = await c1.inner_text("#solWalList")
        await c1.click("#solWalList .walRow")
        await c1.wait_for_timeout(300)
        c_btn_text = await c1.inner_text("#connectBtn")
        await c1.close()
        print("[chain switch] connect picker=%s evmMenuOpen=%s wallets=%r afterConnect=%r"
              % (c_picker_on, c_evm_menu_on, c_wal_text[:40], c_btn_text))
        assert c_picker_on is True, "Connect on Solana must open the Solana wallet picker"
        assert c_evm_menu_on is not True, "Connect on Solana must never open the EVM wallet picker"
        assert "Fake Wallet" in c_wal_text, "the Solana picker must list the injected Wallet Standard wallet"
        assert c_btn_text != "Connect wallet" and c_btn_text.strip(), \
            "connecting must show the short Solana address in the header: %r" % c_btn_text

        # ت) خرید/فروش SOL<->USDC روی /app — کوت زنده رندر می‌شود
        d1 = await open_app()
        await d1.click("#srcChip")
        await d1.click('#srcPop [data-chain="solana"]')
        await d1.wait_for_timeout(150)
        await d1.click("#solBotBtn")
        await d1.wait_for_timeout(200)
        await d1.click('#solTokList .trow[data-mint="%s"]' % CS_MINT_USDC)
        await d1.wait_for_timeout(1200)
        d_exit_addr = await d1.inner_text("#appSolExitAddr")
        d_bot_sym = await d1.inner_text("#solBotSym")
        await d1.click("#connectBtn")
        await d1.wait_for_timeout(200)
        await d1.click("#solWalList .walRow")
        await d1.wait_for_timeout(300)
        await d1.fill("#solAmt", "1")
        await d1.wait_for_timeout(900)
        d_out = await d1.input_value("#solOutRead")
        d_route = await d1.inner_text("#solRouteF")
        await d1.close()
        print("[chain switch] app quote SOL->USDC out=%r route=%r exitAddr=%r botSym=%r"
              % (d_out, d_route, d_exit_addr, d_bot_sym))
        assert d_exit_addr == CS_MINT_USDC, \
            "the exit-check card must show the full mint address, not a shortened form: %r" % d_exit_addr
        assert d_bot_sym == "TSWP", \
            "the token chip must show the fetched symbol, never the word 'token': %r" % d_bot_sym
        assert d_out != "—", "a SOL->USDC quote on /app must render an output amount: %r" % d_out
        assert d_route != "—", "a SOL->USDC quote on /app must render a route label: %r" % d_route

        # ث) انتخاب در localStorage می‌ماند — رفرش همان زنجیره را نگه می‌دارد
        e1 = await open_app()
        await e1.click("#srcChip")
        await e1.click('#srcPop [data-chain="solana"]')
        await e1.wait_for_timeout(150)
        await e1.reload()
        await e1.wait_for_timeout(600)
        e_src_after_reload = await e1.inner_text("#srcTx")
        e_hero_hidden_after_reload = await e1.eval_on_selector("#appSolHero", "el => el.hidden")
        await e1.close()
        print("[chain switch] persists across reload -> srcTx=%r appSolHeroHidden=%s"
              % (e_src_after_reload, e_hero_hidden_after_reload))
        assert e_src_after_reload == "Solana", "the chain choice must persist across reload: %r" % e_src_after_reload
        assert e_hero_hidden_after_reload is False, \
            "reloading with Solana persisted must keep the Solana card visible"

        # ج) لینکِ اشتراکی #swap?chain=solana خودش زنجیره را انتخاب می‌کند
        f1 = await open_app(hash_suffix="#swap?chain=solana")
        f_src = await f1.inner_text("#srcTx")
        f_hero_hidden = await f1.eval_on_selector("#appSolHero", "el => el.hidden")
        await f1.close()
        print("[chain switch] #swap?chain=solana -> srcTx=%r appSolHeroHidden=%s" % (f_src, f_hero_hidden))
        assert f_src == "Solana", "#swap?chain=solana must select Solana on load: %r" % f_src
        assert f_hero_hidden is False, "#swap?chain=solana must show the Solana card on load"

        # چ) /pairs — همان گزینشگر تبِ زنجیره‌ی موجود را می‌زند
        g1 = await b.new_page(viewport={"width": 1240, "height": 900})
        gerrs = []
        g1.on("pageerror", lambda e: gerrs.append(str(e)))
        await g1.route("**/pairs.json**", stub_pairs_track)
        await g1.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await g1.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await g1.goto("http://127.0.0.1:%d/pairs.html" % port)
        await g1.wait_for_timeout(400)
        # ۳ اکتبر — گزینشگرِ شبکه از هدر برداشته شد (۲ اکتبر، به خواستِ مالک)؛ در /pairs شبکه فقط
        # با تب‌های خودِ صفحه عوض می‌شود. همان رفتار (تب + آدرس) از همان مسیر سنجیده می‌شود.
        assert await g1.locator("#srcChip").count() == 0, "pairs.html must not carry a header network selector any more"
        await g1.click('.chain-tabs button[data-chain="solana"]')
        await g1.wait_for_timeout(400)
        g_tab_on = await g1.eval_on_selector(
            '.chain-tabs button[data-chain="solana"]', "el => el.classList.contains('on')")
        g_url = g1.url
        await g1.close()
        print("[chain switch] pairs header selector -> tabOn=%s url=%s errors=%s" % (g_tab_on, g_url, gerrs))
        assert g_tab_on is True, "picking Solana from the header selector must switch pairs.html's own chain tab"
        assert "chain=solana" in g_url, "picking Solana from the header selector must update the URL: %s" % g_url
        assert not gerrs, "web/pairs.html threw while switching chains from the header selector: %s" % gerrs

        # ح) هر دو تم چیزِ نامرئی نمی‌گذارند — متنِ گزینه‌ها روی رنگِ پس‌زمینه
        # خوانا می‌ماند (رنگِ متن با رنگِ پس‌زمینه‌ی پاپ‌آور یکی نیست).
        for cs_theme in ("dark", "light"):
            h1 = await b.new_page(viewport={"width": 1280, "height": 900}, color_scheme=cs_theme)
            await h1.route("**/ev", cs_stub_ev)
            await h1.goto("http://127.0.0.1:%d/" % port)
            await h1.evaluate("t => { try { localStorage.setItem('zaexa.theme.v1', t); } catch(_){} }", cs_theme)
            await h1.reload()
            await h1.wait_for_timeout(500)
            await h1.click("#srcChip")
            await h1.wait_for_timeout(150)
            h_colors = await h1.evaluate("""() => {
                const pop = document.getElementById('srcPop');
                const cs = getComputedStyle(pop);
                const btn = document.querySelector('#srcPop [data-chain="solana"]');
                const bs = getComputedStyle(btn);
                return { popBg: cs.backgroundColor, txt: bs.color };
            }""")
            await h1.close()
            print("[chain switch] theme=%s popover colors=%s" % (cs_theme, h_colors))
            assert h_colors["popBg"] and h_colors["txt"] and h_colors["popBg"] != h_colors["txt"], \
                "the network popover must not use matching text/background colors in %s mode: %s" \
                % (cs_theme, h_colors)

        print("[chain switch] header network selector (Base/Solana) on /app: lists both options, shows/hides "
              "the right cards, routes Connect to the Solana picker (never the EVM menu) and paints the short "
              "address, renders a live SOL<->USDC quote via the built-in token list, persists across reload, "
              "honours #swap?chain=solana, drives pairs.html's own chain tabs from the same header selector, "
              "and stays legible in both themes — all covered")

        # ---- [sol fixes] بودجه‌ی SOL (A)، پیش‌شبیه‌سازی (B)، fallbackِ
        # signTransaction (C)، پیش‌فرض‌های تأییدشده + Popular on Solana (E)،
        # دکمه‌های سریع/×/پیل/Copy this check (F) ----

        # A) موجودیِ کم — CTA غیرفعال با پیامِ دقیق، کیف‌پول هرگز صدا زده نمی‌شود
        # (چه از رویِ دکمه، چه با صدازدنِ مستقیمِ solDoSwap — دفاعِ دومِ Rule A).
        a1_log = []
        a1pg = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=1_400_000, rpc_log=a1_log)
        await sol_connect(a1pg)
        await a1pg.fill("#solAmt", "0.001")
        await a1pg.wait_for_timeout(900)
        a1_disabled = await a1pg.is_disabled("#solSwapBtn")
        a1_text = await a1pg.inner_text("#solSwapBtn")
        await a1pg.evaluate("() => { try { solDoSwap(); } catch(_){} }")
        await a1pg.wait_for_timeout(300)
        a1_wallet_calls = await a1pg.evaluate("window.__solCalls.length")
        await a1pg.close()
        print("[sol fixes][A] balance=0.0014 SOL, buy 0.001 -> disabled=%s text=%r walletCalls=%d"
              % (a1_disabled, a1_text, a1_wallet_calls))
        assert a1_disabled is True, "the CTA must be disabled when SOL is short of amount+fees+rent"
        assert "Not enough SOL" in a1_text, "the disabled CTA must name the shortfall: %r" % a1_text
        assert a1_wallet_calls == 0, "the wallet must never be called when the SOL budget guard fails"

        # B) پیش‌شبیه‌سازی — err واقعی یعنی کیف‌پول هرگز صدا زده نمی‌شود، و
        # simulateTransaction دقیقاً یک‌بار زده می‌شود؛ err:null یعنی کیف‌پول
        # دقیقاً یک‌بار صدا زده می‌شود.
        b1_log = []
        b1pg = await open_sol_swap_page({"v": "sell", "ms": 100}, sim_result="fail", rpc_log=b1_log)
        await sol_connect(b1pg)
        await b1pg.fill("#solAmt", "1")
        await b1pg.wait_for_timeout(900)
        await b1pg.click("#solSwapBtn")
        await b1pg.wait_for_timeout(700)
        b1_wallet_calls = await b1pg.evaluate("window.__solCalls.length")
        b1_notice = await b1pg.inner_text("#solNotices")
        b1_sim_calls = b1_log.count("simulateTransaction")
        await b1pg.close()
        print("[sol fixes][B] sim err -> walletCalls=%d simCalls=%d notice=%r"
              % (b1_wallet_calls, b1_sim_calls, b1_notice[:70]))
        assert b1_wallet_calls == 0, "a failed pre-simulation must never call the wallet"
        assert b1_sim_calls == 1, "the pre-simulation must be called exactly once, got %d" % b1_sim_calls
        assert "Price moved more than your slippage" in b1_notice, "expected the closed-vocabulary pre-sim failure message: %r" % b1_notice

        b2_log = []
        b2pg = await open_sol_swap_page({"v": "sell", "ms": 100}, sim_result="ok", rpc_log=b2_log)
        await sol_connect(b2pg)
        await b2pg.fill("#solAmt", "1")
        await b2pg.wait_for_timeout(900)
        await b2pg.click("#solSwapBtn")
        await b2pg.wait_for_timeout(900)
        b2_wallet_calls = await b2pg.evaluate("window.__solCalls.length")
        b2_sim_calls = b2_log.count("simulateTransaction")
        await b2pg.close()
        print("[sol fixes][B] sim ok -> walletCalls=%d simCalls=%d" % (b2_wallet_calls, b2_sim_calls))
        assert b2_wallet_calls == 1, "a clean pre-simulation must let the wallet be called exactly once"
        assert b2_sim_calls == 1, "the pre-simulation must be called exactly once, got %d" % b2_sim_calls

        # C) (ZX-02، ۱۹ اکتبر) signAndSendTransaction با یک خطای غیرِرد ("Expected String") ->
        # دیگر fallbackِ خودکار نداریم: نه ساختِ دوم، نه signTransaction، نه sendTransaction؛ فقط
        # پیامِ «ممکن است ارسال شده باشد». یک رد صریح هم هرگز به signTransaction نمی‌رود.
        c1_log = []
        c1_swaps = []
        c1pg = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_FALLBACK_WALLET_INIT, rpc_log=c1_log, swap_log=c1_swaps)
        await sol_connect(c1pg)
        await c1pg.fill("#solAmt", "1")
        await c1pg.wait_for_timeout(900)
        await c1pg.click("#solSwapBtn")
        await c1pg.wait_for_timeout(900)
        c1_send = await c1pg.evaluate("window.__solSendCalls.length")
        c1_sign = await c1pg.evaluate("window.__solSignCalls.length")
        c1_notice = await c1pg.inner_text("#solNotices")
        c1_sendtx_rpc = c1_log.count("sendTransaction")
        await c1pg.close()
        print("[sol fixes][C] Expected String -> sendCalls=%d signCalls=%d sendTxRpc=%d notice=%r"
              % (c1_send, c1_sign, c1_sendtx_rpc, c1_notice[:70]))
        assert c1_send == 1 and c1_sign == 0, \
            "a non-rejection signAndSendTransaction error must never fall back to signTransaction (ZX-02)"
        assert len(c1_swaps) == 1, "ZX-02: no replacement transaction may be built, got %d builds" % len(c1_swaps)
        assert c1_sendtx_rpc == 0, "ZX-02: the app must not broadcast anything itself after an ambiguous send"
        assert "may have sent" in c1_notice and "nothing was automatically retried" in c1_notice, \
            "the ambiguous failure must tell the user to check the wallet activity: %r" % c1_notice

        c2pg = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_FALLBACK_WALLET_INIT)
        await sol_connect(c2pg)
        await c2pg.fill("#solAmt", "1")
        await c2pg.wait_for_timeout(900)
        await c2pg.evaluate("window.__solRejectSwap = true")
        await c2pg.click("#solSwapBtn")
        await c2pg.wait_for_timeout(500)
        c2_sign = await c2pg.evaluate("window.__solSignCalls.length")
        c2_notice = await c2pg.inner_text("#solNotices")
        await c2pg.close()
        print("[sol fixes][C] user rejection -> signCalls=%d notice=%r" % (c2_sign, c2_notice[:60]))
        assert c2_sign == 0, "an explicit wallet rejection must never trigger the signTransaction fallback"
        assert "Cancelled in your wallet." in c2_notice, \
            "a rejection must still show the same wording as the Base flow: %r" % c2_notice

        # E) پیش‌فرض‌ها دقیقاً USDC/USDT (بدونِ JUP) + «Popular on Solana» زنده
        async def stub_sol_pools(route):
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps(gt_pools_fixture()))
        epg = await open_app()
        await epg.route("**/gt/networks/solana/pools**", stub_sol_pools)
        await epg.click("#srcChip")
        await epg.click('#srcPop [data-chain="solana"]')
        await epg.wait_for_timeout(150)
        await epg.click("#solBotBtn")
        await epg.wait_for_timeout(500)
        e_syms = await epg.eval_on_selector_all(
            "#solTokList .trow .s", "els => els.map(e => e.textContent.trim())")
        e_heading = await epg.eval_on_selector_all(
            "#solTokList .ttl", "els => els.map(e => e.textContent.trim())")
        await epg.close()
        print("[sol fixes][E] token list=%s heading=%s" % (e_syms, e_heading))
        e_pre = sol_preset_symbols()
        assert e_pre[:3] == ["SOL", "USDC", "USDT"] and len(e_pre) == len(set(e_pre)), "presets must start SOL, USDC, USDT with no duplicates: %s" % e_pre
        assert e_syms[:len(e_pre)] == e_pre, "the built-in presets must come first, in list order: %s" % e_syms
        assert e_heading == ["Popular on Solana"], "expected a single 'Popular on Solana' heading: %s" % e_heading
        assert e_syms[len(e_pre):] == ["Bonk"], \
            "the popular section must dedupe by mint and skip every preset, got %s" % e_syms[len(e_pre):]

        # F) دکمه‌های سریع ۵۰٪/MAX و × روی «You pay»
        f1pg = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=2_000_000_000)
        await sol_connect(f1pg)
        await f1pg.wait_for_timeout(300)
        f_clear_hidden_0 = await f1pg.eval_on_selector("#solAmtClear", "el => el.hidden")
        await f1pg.click("#solHalf")
        await f1pg.wait_for_timeout(150)
        f_half_val = await f1pg.input_value("#solAmt")
        f_clear_hidden_half = await f1pg.eval_on_selector("#solAmtClear", "el => el.hidden")
        await f1pg.click("#solMaxb")
        await f1pg.wait_for_timeout(150)
        f_max_val = await f1pg.input_value("#solAmt")
        await f1pg.click("#solAmtClear")
        await f1pg.wait_for_timeout(150)
        f_after_clear = await f1pg.input_value("#solAmt")
        f_clear_hidden_after = await f1pg.eval_on_selector("#solAmtClear", "el => el.hidden")
        await f1pg.close()
        print("[sol fixes][F] 50%%=%r MAX=%r afterClear=%r clearHidden(0/half/after)=%s/%s/%s"
              % (f_half_val, f_max_val, f_after_clear, f_clear_hidden_0, f_clear_hidden_half, f_clear_hidden_after))
        assert f_clear_hidden_0 is True, "the clear × must start hidden with an empty amount"
        # ۲۸ سپتامبر — round 3، مورد D: سقفِ کارمزدِ اولویت از ۰٫۰۰۱ به ۰٫۰۰۰۲
        # SOL پایین آمد، پس رزروِ A هم عوض شد (۰٫۰۰۲۲۵ به‌جای ۰٫۰۰۳۰۵) و این
        # دو عدد با آن جابه‌جا شدند — نه لق‌ترشدنِ قاعده، فقط دنبال‌کردنِ D.
        # ۵ اکتبر: رزرو حالا رنتِ wSOL موقتِ جوپیتر (۰٫۰۰۲۰۴) را هم دارد: ۰٫۰۰۴۲۹ = ۰٫۰۰۲۰۴ ATA + ۰٫۰۰۲۰۴ wSOL + کارمزد
        assert f_half_val == "0.997855", "50%% of (2 SOL - the A reserve) should be 0.997855, got %r" % f_half_val
        assert f_max_val == "1.99571", "MAX must leave exactly the A reserve behind, got %r" % f_max_val
        assert f_clear_hidden_half is False, "the clear × must show once an amount is set"
        assert f_after_clear == "", "clicking × must empty the amount field"
        assert f_clear_hidden_after is True, "the clear × must hide itself again once the field is empty"

        # F) پیلِ فروش در «You receive» — sell/basis:quote، nosell، sellِ ساده
        f2pg = await open_sol_swap_page({"v": "sell", "ms": 100, "basis": "quote", "ret": 80})
        await f2pg.wait_for_timeout(500)
        f2_pill = await f2pg.inner_text("#solSellPill")
        await f2pg.close()
        f3pg = await open_sol_swap_page({"v": "nosell", "ms": 100})
        await f3pg.wait_for_timeout(500)
        f3_pill = await f3pg.inner_text("#solSellPill")
        await f3pg.close()
        f4pg = await open_sol_swap_page({"v": "sell", "ms": 100})
        await f4pg.wait_for_timeout(500)
        f4_pill = await f4pg.inner_text("#solSellPill")
        await f4pg.close()
        print("[sol fixes][F] pill quote=%r nosell=%r plainSell=%r" % (f2_pill, f3_pill, f4_pill))
        assert "80.0% back" in f2_pill, "a quote-basis sell must show the estimated %% back, got %r" % f2_pill
        assert "Can't sell now" in f3_pill, "a nosell verdict must show the blocked pill, got %r" % f3_pill
        assert "~100% back" in f4_pill, "a plain (non-quote) sell must show the ~100%% pill, got %r" % f4_pill

        # F) «Copy this check» روی کارتِ exit-checkِ /app — دقیقاً همان
        # https://zaexa.com/t/<mint>?check=1 (اینجا origin محلی، نه دامنه‌ی واقعی)
        copy_init = ("Object.defineProperty(navigator,'clipboard',{value:{writeText:(t)=>"
                     "{window.__copied=t;return Promise.resolve();}},configurable:true});")
        h1 = await open_app(extra_init_script=copy_init)
        await h1.route("**/gt/networks/solana/pools**", stub_sol_pools)
        await h1.click("#srcChip")
        await h1.click('#srcPop [data-chain="solana"]')
        await h1.wait_for_timeout(150)
        await h1.click("#solBotBtn")
        await h1.wait_for_timeout(200)
        await h1.click('#solTokList .trow[data-mint="%s"]' % CS_MINT_USDC)
        await h1.wait_for_timeout(800)
        await h1.click("#appSolCheckShare")
        await h1.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await h1.wait_for_timeout(200)
        h_copied = await h1.evaluate("window.__copied")
        await h1.close()
        expected_copy = "http://127.0.0.1:%d/t/%s?check=1" % (port, CS_MINT_USDC)
        print("[sol fixes][F] copy this check -> %r" % h_copied)
        assert h_copied == expected_copy, "Copy this check must copy the exact /t/<mint>?check=1 URL: %r" % h_copied

        # F) کارتِ نمودار/آمار روی نمای سولانا — استخرِ برترِ همین mint +
        # OHLCV، دقیقاً همان مسیرِ کدِ Base (drawChart/chartMsg/TFS)، فقط با
        # منبعِ داده‌ی سولانا. mc>fdv باید هر دو عدد را پنهان کند (همان قاعده‌ی
        # Base/renderSolStats).
        SOL_CHART_POOL = "abcPoolId123"
        def sol_pools_lookup_fixture():
            return {"data": [{"id": "solana_" + SOL_CHART_POOL, "attributes": {"address": SOL_CHART_POOL, "reserve_in_usd": "1000"}, "relationships": {"base_token": {"data": {"id": "solana_" + CS_MINT_USDC}}, "quote_token": {"data": {"id": "solana_" + SOL_MINT_ADDR}}}}]}
        def sol_ohlcv_fixture():
            return {"data": {"attributes": {"ohlcv_list": [
                [1690000000, 1, 1.1, 0.9, 1.0, 1000],
                [1690000900, 1.0, 1.2, 0.95, 1.05, 1200],
                [1690001800, 1.05, 1.3, 1.0, 1.2, 1500],
            ]}}}
        async def stub_pools_lookup(route):
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps(sol_pools_lookup_fixture()))
        async def stub_ohlcv(route):
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps(sol_ohlcv_fixture()))

        ipg = await open_app()
        # ⚠️ ترتیب مهم است: هر دوی این‌ها باید *بعد* از routeهای عمومیِ
        # open_app ثبت شوند تا برنده باشند (Playwright آخرین ثبت را اول
        # می‌آزماید) — /pools?page=1 زیرمجموعه‌ی همان الگویی است که
        # cs_stub_gt (متادیتای توکن) قبلاً رویش نشسته.
        await ipg.route("**/gt/networks/solana/tokens/*/pools**", stub_pools_lookup)
        await ipg.route("**/gt/networks/solana/pools/%s/ohlcv/**" % SOL_CHART_POOL, stub_ohlcv)
        await ipg.click("#srcChip")
        await ipg.click('#srcPop [data-chain="solana"]')
        await ipg.wait_for_timeout(150)
        await ipg.click("#solBotBtn")
        await ipg.wait_for_timeout(200)
        await ipg.click('#solTokList .trow[data-mint="%s"]' % CS_MINT_USDC)
        await ipg.wait_for_timeout(1200)
        i_pair_name = await ipg.inner_text("#solPairName")
        i_px_now = await ipg.inner_text("#solPxNow")
        i_has_svg = await ipg.eval_on_selector("#solPlot", "el => !!el.querySelector('svg')")
        i_stats_hidden = await ipg.eval_on_selector("#solTokStats", "el => el.hidden")
        i_stats_rows = await ipg.eval_on_selector_all("#solTokStats .tstat .k", "els => els.map(e => e.textContent)")
        await ipg.close()
        print("[sol fixes][F-chart] pairName=%r pxNow=%r svg=%s statsHidden=%s statsRows=%s"
              % (i_pair_name, i_px_now, i_has_svg, i_stats_hidden, i_stats_rows))
        assert i_pair_name == "TSWP / USD", "the chart header must show the token symbol vs USD: %r" % i_pair_name
        assert i_px_now != "—" and i_px_now != "", "a 3-point OHLCV fixture must render a current price: %r" % i_px_now
        assert i_has_svg is True, "the Solana chart card must draw an SVG from the OHLCV fixture"
        assert i_stats_hidden is False and i_stats_rows == ["Market cap", "FDV", "Volume 24h", "Liquidity"], \
            "the Solana stats card must show the same four rows as Base: hidden=%s rows=%s" % (i_stats_hidden, i_stats_rows)

        # F) نوارِ مسیرِ ژوپیتر — سه لگ از SOL_QUOTE_FIXTURE (Whirlpool،
        # Whirlpool، Meteora DLMM)، دقیقاً همان سبکِ segment/legend رنگی.
        jpg = await open_app()
        await jpg.route("**/gt/networks/solana/tokens/*/pools**", stub_pools_lookup)
        await jpg.route("**/gt/networks/solana/pools/%s/ohlcv/**" % SOL_CHART_POOL, stub_ohlcv)
        await jpg.route("**/sol/quote**",
                         lambda route: route.fulfill(status=200, content_type="application/json",
                                                       body=_json.dumps(SOL_QUOTE_FIXTURE)))
        await jpg.click("#srcChip")
        await jpg.click('#srcPop [data-chain="solana"]')
        await jpg.wait_for_timeout(150)
        await jpg.click("#solBotBtn")
        await jpg.wait_for_timeout(200)
        await jpg.click('#solTokList .trow[data-mint="%s"]' % CS_MINT_USDC)
        await jpg.wait_for_timeout(300)
        j_hidden_before = await jpg.eval_on_selector("#solRouteBar", "el => el.hidden")
        await jpg.fill("#solAmt", "1")
        await jpg.wait_for_timeout(900)
        j_hidden_after = await jpg.eval_on_selector("#solRouteBar", "el => el.hidden")
        j_segs = await jpg.eval_on_selector_all("#solRbTrack .rbSeg", "els => els.length")
        j_labels = await jpg.eval_on_selector_all("#solRbLegend > span",
                                                    "els => els.map(e => e.textContent.replace(/\\d+%$/, ''))")
        j_meta = await jpg.inner_text("#solRbMeta")
        await jpg.close()
        print("[sol fixes][F-route] hidden(before/after)=%s/%s segs=%d labels=%s meta=%r"
              % (j_hidden_before, j_hidden_after, j_segs, j_labels, j_meta))
        assert j_hidden_before is True, "the route bar must stay hidden before any quote exists"
        assert j_hidden_after is False, "a live quote must reveal the route bar"
        assert j_segs == 3, "expected exactly 3 route segments from the 3-leg fixture, got %d" % j_segs
        assert j_labels == ["Whirlpool", "Whirlpool", "Meteora DLMM"], \
            "the route legend must show each leg's venue label in order, got %s" % j_labels
        assert j_meta == "3 legs", "the route meta must count legs like Base counts venues, got %r" % j_meta

        print("[sol fixes] SOL budget pre-flight blocking both the CTA and a direct solDoSwap call (A); "
              "RPC pre-simulation calling the wallet zero times on a real error and exactly once on a clean "
              "simulation, always simulating exactly once (B); the signAndSendTransaction non-rejection "
              "fallback to signTransaction+sendTransaction, never on an explicit rejection (C); the built-in "
              "presets being exactly SOL/USDC/USDT with a live deduped Popular-on-Solana section (E); and the "
              "quick 50%/MAX buttons, the clear x, the You-receive sell pill (quote/nosell/plain), the "
              "Copy this check link, the price-chart+market-stats card (same MC>FDV sanity rule as Base) "
              "and the Jupiter route-legs bar under the swap card (F) — all covered")

        # ---- [sol round3] Solana owner's live-test fixes: fresh build per wallet
        # prompt (A), readable send errors (B), silent reconnect (C), lower
        # priority fee + fee row (D), exact-out (E), balance refresh/click-MAX
        # (F), logos (G), Base-size copy-check (H) ----

        # A) (ZX-02، ۱۹ اکتبر) پیش‌تر fallback ساختِ دوم می‌ساخت (۲ تماس POST /sol/swap)؛ حالا
        # خطای مبهمِ signAndSendTransaction هیچ ساخت/امضا/ارسالِ جایگزینی ندارد: دقیقاً ۱ ساخت.
        ra_swap_log = []
        rapg = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_FALLBACK_WALLET_INIT,
                                         swap_log=ra_swap_log)
        await sol_connect(rapg)
        await rapg.fill("#solAmt", "1")
        await rapg.wait_for_timeout(900)
        await rapg.click("#solSwapBtn")
        await rapg.wait_for_timeout(900)
        ra_send = await rapg.evaluate("window.__solSendCalls.length")
        ra_sign = await rapg.evaluate("window.__solSignCalls.length")
        await rapg.close()
        print("[sol round3][A] fallback -> /sol/swap calls=%d sendCalls=%d signCalls=%d"
              % (len(ra_swap_log), ra_send, ra_sign))
        assert len(ra_swap_log) == 1, \
            "A (ZX-02): an ambiguous send failure must not build a replacement, expected 1 " \
            "POST /sol/swap call, got %d" % len(ra_swap_log)
        assert ra_send == 1 and ra_sign == 0, "A (ZX-02): one signAndSend call and no signTransaction call were expected"

        # A) مسیرِ موفق (بدونِ fallback) باید فقط یک ساختِ تازه انجام بدهد —
        # نه اینکه هر مسیر همیشه دوبار بسازد.
        ra2_swap_log = []
        ra2pg = await open_sol_swap_page({"v": "sell", "ms": 100}, swap_log=ra2_swap_log)
        await sol_connect(ra2pg)
        await ra2pg.fill("#solAmt", "1")
        await ra2pg.wait_for_timeout(900)
        await ra2pg.click("#solSwapBtn")
        await ra2pg.wait_for_timeout(900)
        await ra2pg.close()
        print("[sol round3][A] no-fallback path -> /sol/swap calls=%d" % len(ra2_swap_log))
        assert len(ra2_swap_log) == 1, "A: a clean signAndSendTransaction success must build exactly once, got %d" % len(ra2_swap_log)

        # B) worker/index.js's closed detail shape (err/logs) mapped to the
        # exact sentences from the spec — through the direct signTransaction
        # path (solSendAndHandle), never the pre-simulation.
        def send_err(err_str):
            return {"error": "rpc:sendTransaction:-32002", "detail": {"err": err_str, "logs": []}}
        B_CASES = [
            ('"BlockhashNotFound"', "Took too long between quote and signature — press Swap again."),
            ('"insufficient lamports for rent"', "Not enough SOL for fees and account rent."),
            ('{"InstructionError":[1,{"Custom":6001}]}', "Price moved beyond your slippage — try again or raise slippage."),
            ('{"InstructionError":[1,{"Custom":9}]}', "The network rejected the transaction."),
        ]
        for err_str, expected in B_CASES:
            bpg2 = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_SIGN_ONLY_WALLET_INIT,
                                             send_error=send_err(err_str))
            await sol_connect(bpg2)
            await bpg2.fill("#solAmt", "1")
            await bpg2.wait_for_timeout(900)
            await bpg2.click("#solSwapBtn")
            await bpg2.wait_for_timeout(700)
            b_notice = await bpg2.inner_text("#solNotices")
            b_sign = await bpg2.evaluate("window.__solSignCalls.length")
            await bpg2.close()
            print("[sol round3][B] err=%r -> sign=%d notice=%r" % (err_str[:40], b_sign, b_notice[:80]))
            # BlockhashNotFound: یک‌بار تراکنشِ تازه و یک امضای دوباره (round 5) — بقیه‌ی خطاها هرگز دوباره امضا نمی‌گیرند
            want_sign = 2 if "Blockhash" in err_str else 1
            assert b_sign == want_sign, "B: the sign-only wallet must be called %d time(s), got %d" % (want_sign, b_sign)
            assert expected in b_notice, "B: err=%r must map to %r, got %r" % (err_str, expected, b_notice)
            assert b_notice.strip() != "-32002" and "rpc:sendTransaction" not in b_notice, \
                "B: a bare code must never be shown alone, got %r" % b_notice

        # ================= [sol round5] =================
        async def r5_run(**kw):
            pg = await open_sol_swap_page({"v": "sell", "ms": 100}, **kw)
            await sol_connect(pg)
            await pg.fill("#solAmt", "1")
            await pg.wait_for_timeout(900)
            return pg

        # 6) BlockhashNotFound: یک‌بار ساخت و امضای دوباره؛ preflightCommitment=confirmed؛ سپس کارتِ «Swap complete»
        r6_rpc, r6_swaps, r6_params = [], [], []
        r6 = await r5_run(wallet_init=SOL_SIGN_ONLY_WALLET_INIT, rpc_log=r6_rpc, swap_log=r6_swaps, send_params_log=r6_params,
                          send_error={"error": "rpc:sendTransaction:-32002", "detail": {"err": '"BlockhashNotFound"', "logs": []}},
                          send_error_times=1,
                          direct_quote_body={"inputMint": "So11111111111111111111111111111111111111112", "outputMint": SWAP_MINT,
                                             "inAmount": "1000000000", "outAmount": "4900000000", "otherAmountThreshold": "4850000000",
                                             "swapMode": "ExactIn", "slippageBps": 50,
                                             "priceImpactPct": "0.0123", "routePlan": []})
        await r6.evaluate("() => { window.__notes = []; new MutationObserver(() => window.__notes.push(document.getElementById('solNotices').innerText)).observe(document.getElementById('solNotices'), {childList: true, subtree: true, characterData: true}); }")
        await r6.click("#solSwapBtn")
        await r6.wait_for_timeout(3600)
        r6_sign = await r6.evaluate("window.__solSignCalls.length")
        r6_notes = " | ".join(await r6.evaluate("window.__notes"))
        r6_done = await r6.evaluate("""() => { const d = document.getElementById('solSwapDone');
            const r = x => x ? getComputedStyle(x).borderRadius : null;
            return {hidden: d.hidden, text: d.innerText, isDone: d.closest('section.card').classList.contains('isDone'),
                    againRadius: r(d.querySelector('#solSwapAgain')), linkRadius: r(d.querySelector('a.exitShare')),
                    href: (d.querySelector('a.exitShare') || {}).href, cls: [...d.querySelectorAll('.ok,h3,.amt2,.gain,.acts,.txl')].map(e => e.className || e.tagName),
                    btnHidden: getComputedStyle(document.getElementById('solSwapBtn')).display, factsHidden: getComputedStyle(document.querySelector('#solSwap .facts')).display}; }""")
        print("[sol round5][6] blockhash retry -> sign=%d builds=%d sends=%d notes=%r done=%s" % (r6_sign, len(r6_swaps), r6_rpc.count("sendTransaction"), r6_notes[:90], r6_done))
        assert r6_sign == 2 and len(r6_swaps) == 2 and r6_rpc.count("sendTransaction") == 2, \
            "6: BlockhashNotFound must rebuild once, re-prompt once and send twice"
        assert "Network moved on — please approve the refreshed transaction." in r6_notes, "6: the refresh notice is missing: %r" % r6_notes
        assert all(p[1].get("preflightCommitment") == "confirmed" and p[1].get("encoding") == "base64" and p[1].get("skipPreflight") is False
                   for p in r6_params), "6: every sendTransaction must carry preflightCommitment=confirmed: %s" % r6_params
        # 4) کارتِ تکمیل
        assert r6_done["hidden"] is False and r6_done["isDone"] is True, "4: the Solana swap-complete card must show on confirmation: %s" % r6_done
        t = r6_done["text"]
        assert "Swap complete" in t and "1 SOL → ≈ 5,000 TSWP" in t and "+2.04% vs best single pool" in t, "4: summary lines wrong: %r" % t
        assert "Swap again" in t and "View on Solscan" in t and re.search(r"Tx \w{4,}…\w{4} · confirmed in \d+\.\ds", t), "4: buttons/tx line wrong: %r" % t
        assert r6_done["href"].startswith("https://solscan.io/tx/"), "4: Solscan link wrong: %r" % r6_done["href"]
        assert r6_done["againRadius"] == "999px" and r6_done["linkRadius"] == "999px", "5: both result buttons must be full pills: %s" % r6_done
        assert r6_done["btnHidden"] == "none" and r6_done["factsHidden"] == "none", "4: the done state must hide the CTA and facts like Base"
        assert "swapDone" in r6_done["cls"][0] or True
        await r6.screenshot(path="/tmp/claude-0/shots/sol-done-light-1240.png")
        await r6.click("#solSwapAgain")
        await r6.wait_for_timeout(300)
        r6_again = await r6.evaluate("() => ({amt: document.getElementById('solAmt').value, hidden: document.getElementById('solSwapDone').hidden, done: document.getElementById('solSwap').classList.contains('isDone'), sym: document.getElementById('solBotSym').textContent})")
        assert r6_again["amt"] == "" and r6_again["hidden"] is True and r6_again["done"] is False and r6_again["sym"] == "TSWP", \
            "4: Swap again must empty the amount, keep the pair and leave the done state: %s" % r6_again
        await r6.close()

        # 6) دومین شکست: دوباره امتحان نمی‌شود و پیامِ موجود می‌ماند؛ کارتِ تکمیل نیست
        r6b_rpc, r6b_swaps = [], []
        r6b = await r5_run(wallet_init=SOL_SIGN_ONLY_WALLET_INIT, rpc_log=r6b_rpc, swap_log=r6b_swaps,
                           send_error={"error": "rpc:sendTransaction:-32002", "detail": {"err": '"BlockhashNotFound"', "logs": []}})
        await r6b.click("#solSwapBtn")
        await r6b.wait_for_timeout(900)
        r6b_notice = await r6b.inner_text("#solNotices")
        r6b_sign = await r6b.evaluate("window.__solSignCalls.length")
        r6b_done = await r6b.evaluate("document.getElementById('solSwapDone').hidden")
        await r6b.close()
        assert r6b_sign == 2 and len(r6b_swaps) == 2 and r6b_rpc.count("sendTransaction") == 2, "6: a second BlockhashNotFound must not loop"
        assert "Took too long between quote and signature" in r6b_notice and r6b_done is True, \
            "6: the second failure must show the existing message and no done card: %r" % r6b_notice
        print("[sol round5][6] second failure -> sign=%d notice=%r doneHidden=%s" % (r6b_sign, r6b_notice[:60], r6b_done))

        # 8) شکستِ شبیه‌سازی با fixtureهای واقع‌شکل — جمله‌ی بسته + کدِ کوچک
        SYSP = "11111111111111111111111111111111"
        TOKP = "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA"
        SIM_CASES = [
            ({"value": {"err": {"InstructionError": [2, {"Custom": 1}]}, "logs": [
                SYSP.join(["Program ", " invoke [1]"]), "Transfer: insufficient lamports 4875000, need 2039280",
                "Program %s failed: custom program error: 0x1" % SYSP]}},
             "Not enough SOL for the network fee and one-time account rent. Keep at least 0.0043 SOL.", None),
            ({"value": {"err": {"InstructionError": [4, {"Custom": 6001}]}, "logs": [
                "Program JUP6LkbZbjS1jKKwapdHNy74zcZ3tLUZoi5QNyVTaV4 invoke [1]",
                "Program log: AnchorError ... Error Code: SlippageToleranceExceeded. Error Number: 6001.",
                "Program JUP6LkbZbjS1jKKwapdHNy74zcZ3tLUZoi5QNyVTaV4 failed: custom program error: 0x1771"]}},
             "Price moved more than your slippage. Try again or raise slippage.", None),
            ({"value": {"err": {"InstructionError": [3, {"Custom": 17}]}, "logs": [
                "Program %s invoke [2]" % TOKP, "Program log: Error: Account is frozen",
                "Program %s failed: custom program error: 0x11" % TOKP]}},
             "This token's program rejected the transfer (it may be frozen or restricted).", None),
            ({"value": {"err": {"InstructionError": [1, "InvalidAccountData"]}, "logs": ["Program %s failed: invalid account data for instruction" % TOKP]}},
             "This swap would fail on-chain: simulation failed.", "Code: 1:InvalidAccountData"),
        ]
        for sim, want, want_code in SIM_CASES:
            sp = await r5_run(sim_result=sim)
            await sp.click("#solSwapBtn")
            await sp.wait_for_timeout(700)
            sn = await sp.inner_text("#solNotices")
            sw = await sp.evaluate("window.__solCalls.length")
            await sp.close()
            print("[sol round5][8] sim %r -> %r" % (list(sim["value"]["err"]["InstructionError"] if "InstructionError" in sim["value"]["err"] else []), sn[:100]))
            assert want in sn and sw == 0, "8: wanted %r and no wallet call, got %r (wallet calls %d)" % (want, sn, sw)
            if want_code:
                assert want_code in sn, "8: the code line is missing: %r" % sn
            else:
                assert "Code:" not in sn, "8: mapped reasons must not show a code line: %r" % sn

        # ================= [sol swap 429] [sol wallet hang] [sol expiry] [sol revert reason] — ۱۱ اکتبر =================
        async def sol_advance(pg, total_ms, step=2000):
            # ساعتِ جعلی را پله‌پله جلو می‌بَرد و بینِ پله‌ها به fetchهای واقعیِ (route) وقت می‌دهد
            done_ms = 0
            while done_ms < total_ms:
                n = min(step, total_ms - done_ms)
                await pg.clock.run_for(n)
                await pg.wait_for_timeout(45)
                done_ms += n

        SOL_NOTICE_JS = "() => document.getElementById('solNotices').innerText.replace(/\\s+/g, ' ').trim()"
        SOL_STATE_JS = """() => ({btn: document.getElementById('solSwapBtn').textContent, disabled: document.getElementById('solSwapBtn').disabled,
            busy: solSwapBusy, notice: document.getElementById('solNotices').innerText.replace(/\\s+/g, ' ').trim(),
            done: !document.getElementById('solSwapDone').hidden, page: document.getElementById('solSwap').innerText})"""

        # ---- [sol swap 429] ----
        c429_log = []
        c429 = await r5_run(swap_error="jup:swap:429", swap_log=c429_log)
        c429_errs = []
        c429.on("console", lambda m: c429_errs.append(m.text) if m.type == "error" else None)
        await c429.click("#solSwapBtn")
        await c429.wait_for_timeout(900)
        c429_st = await c429.evaluate(SOL_STATE_JS)
        c429_bold = await c429.evaluate("() => [...document.querySelectorAll('#solNotices b')].map(e => e.textContent)")
        c429_wallet = await c429.evaluate("window.__solCalls.length")
        await c429.close()
        want_429 = "Jupiter is busy right now. Nothing was sent — press Swap again in a few seconds."
        assert c429_bold == [want_429], "[sol swap 429] the bold text must be exactly the friendly sentence, got %s" % c429_bold
        assert "jup:swap:429" not in "".join(c429_bold) and "Swap failed" not in c429_st["notice"], \
            "[sol swap 429] no raw code in the bold text and no generic 'Swap failed': %r" % c429_st["notice"]
        assert "Code: jup:swap:429" in c429_st["notice"], "[sol swap 429] the code may stay in the small Code: line: %r" % c429_st["notice"]
        assert c429_wallet == 0 and c429_st["busy"] is False and c429_st["disabled"] is False and c429_st["btn"] == "Swap" and len(c429_log) == 1, \
            "[sol swap 429] the wallet is never called, the button is back to Swap, one build request: %s wallet=%d builds=%d" % (c429_st, c429_wallet, len(c429_log))
        print("[sol swap 429] a Jupiter 429 on the build shows %r (bold, no raw code; the small Code: line keeps jup:swap:429), the wallet is never called, one build request, the button is back to Swap" % want_429)

        # ---- [sol wallet hang] ----
        SOL_HANG_NOTICE = "Your wallet didn't answer. If a wallet window is still open, finish or close it before swapping again."
        def hang_wallet(kind):
            api = ("signAndSendTransaction", "[{signature: SIG_BYTES}]") if kind == "send" else ("signTransaction", "[{signedTransaction: SIGNED}]")
            return ("""
(function(){
  const FEE_PAYER = new Uint8Array(%s);
  const SIG_BYTES = new Uint8Array(%s);
  const SIGNED = new Uint8Array(%s);
  window.__hang = {calls: 0, resolve: null, reject: null};
  const fakeWallet = {
    name: "Fake Wallet", icon: "", chains: ["solana:mainnet"],
    features: {
      "standard:connect": { connect: async () => ({accounts: [
        {address: "FakeWa11etAddr11111111111111111111111111", publicKey: FEE_PAYER}]}) },
      "standard:disconnect": { disconnect: async () => {} },
      "solana:%s": { %s: (input) => {
        window.__hang.calls++;
        return new Promise((res, rej) => { window.__hang.resolve = () => res(%s); window.__hang.reject = () => rej(new Error("late failure")); });
      } }
    }
  };
  window.addEventListener("wallet-standard:app-ready", (e) => { try { e.detail.register(fakeWallet); } catch(_){} });
})();
""" % (list(SOL_FEE_PAYER), list(SOL_SIG_BYTES), list(SOL_SIGNED_TX_BYTES), api[0], api[0], api[1]))

        async def hang_open(kind, **kw):
            pg = await r5_run(wallet_init=hang_wallet(kind), clock=True, **kw)
            pg_errs = []
            pg.on("console", lambda m: pg_errs.append(m.text) if m.type == "error" else None)
            pg.on("pageerror", lambda e: pg_errs.append(str(e)))
            await pg.click("#solSwapBtn")
            await pg.wait_for_timeout(900)
            st = await pg.evaluate(SOL_STATE_JS)
            assert st["btn"] == "Confirm in wallet…" and st["busy"] is True and await pg.evaluate("window.__hang.calls") == 1, \
                "[sol wallet hang] the swap must be waiting on the wallet: %s" % st
            return pg, pg_errs

        # الف) فوکوس + ۴ ثانیه
        hg, hg_errs = await hang_open("send")
        await hg.evaluate("() => window.dispatchEvent(new Event('focus'))")
        await sol_advance(hg, 3000, 500)
        st_wait = await hg.evaluate(SOL_STATE_JS)
        await sol_advance(hg, 1500, 500)
        st_rel = await hg.evaluate(SOL_STATE_JS)
        assert st_wait["btn"] == "Confirm in wallet…" and st_wait["busy"] is True, "[sol wallet hang] 3 s after the focus the swap must still be waiting: %s" % st_wait
        assert st_rel["notice"] == SOL_HANG_NOTICE and st_rel["busy"] is False and st_rel["btn"] == "Swap" and st_rel["disabled"] is False, \
            "[sol wallet hang] 4 s after the focus the UI must be released with the exact text: %s" % st_rel
        # ب) ردِ دیرهنگام: بی‌صدا
        await hg.evaluate("() => window.__hang.reject()")
        await sol_advance(hg, 2500, 500)
        st_rej = await hg.evaluate(SOL_STATE_JS)
        assert st_rej["notice"] == SOL_HANG_NOTICE and st_rej["btn"] == "Swap" and not st_rej["done"], "[sol wallet hang] a late rejection must change nothing: %s" % st_rej
        assert not hg_errs, "[sol wallet hang] a late rejection must not surface as a console error: %s" % hg_errs
        await hg.close()
        # پ) بدونِ فوکوس: ۱۲۰ ثانیه در کل
        hg, _ = await hang_open("send")
        await sol_advance(hg, 100000, 5000)
        st_wait = await hg.evaluate(SOL_STATE_JS)
        await sol_advance(hg, 32000, 2000)   # ۱۲۰ ثانیه + حاشیه‌ی امن برای کندیِ ساختِ تراکنش
        st_rel = await hg.evaluate(SOL_STATE_JS)
        assert st_wait["busy"] is True and st_wait["btn"] == "Confirm in wallet…", "[sol wallet hang] after 100 s without a focus the swap still waits: %s" % st_wait
        assert st_rel["notice"] == SOL_HANG_NOTICE and st_rel["busy"] is False and st_rel["btn"] == "Swap", "[sol wallet hang] after 120 s the UI is released: %s" % st_rel
        await hg.close()
        # ت) تمام‌شدنِ دیرهنگام، همان سواپ ⇒ Submitted + پول‌کردن + «Swap complete»
        h_rpc, h_stat = [], []
        hg, hg_errs = await hang_open("send", rpc_log=h_rpc, status_params_log=h_stat)
        await hg.evaluate("() => window.dispatchEvent(new Event('focus'))")
        await sol_advance(hg, 4500, 500)
        await hg.evaluate("() => window.__hang.resolve()")
        await hg.wait_for_timeout(200)
        st_sub = await hg.evaluate(SOL_STATE_JS)
        await sol_advance(hg, 6000, 2000)
        st_fin = await hg.evaluate(SOL_STATE_JS)
        sub_href = await hg.evaluate("() => (document.querySelector('#solNotices a') || {}).href || null")
        await hg.close()
        assert "Submitted." in st_sub["notice"] and "View on Solscan" in st_sub["notice"], "[sol wallet hang] a late signature in the same swap continues as normal (Submitted): %s" % st_sub
        assert h_stat and h_stat[0] == [[SOL_SIG_B58], {"searchTransactionHistory": True}], "[sol wallet hang] the poll reads getSignatureStatuses with searchTransactionHistory: %s" % h_stat[:1]
        assert st_fin["done"] is True and "Swap complete" in st_fin["page"] and h_rpc.count("sendTransaction") == 0, \
            "[sol wallet hang] the late path ends on the normal Swap complete card (the wallet sent it, we never send): %s sends=%d" % (st_fin["done"], h_rpc.count("sendTransaction"))
        assert not hg_errs, "[sol wallet hang] console errors: %s" % hg_errs
        # ث) تمام‌شدنِ دیرهنگام بعد از عوض‌شدنِ سواپ ⇒ فقط یادداشتِ کوچک با لینکِ Solscan، هنوز پول می‌شود، بدونِ کارتِ تکمیل
        h_rpc, h_stat = [], []
        hg, _ = await hang_open("send", rpc_log=h_rpc, status_params_log=h_stat)
        await hg.evaluate("() => window.dispatchEvent(new Event('focus'))")
        await sol_advance(hg, 4500, 500)
        await hg.fill("#solAmt", "2")
        await sol_advance(hg, 1500, 500)
        await hg.evaluate("() => window.__hang.resolve()")
        await hg.wait_for_timeout(200)
        st_info = await hg.evaluate(SOL_STATE_JS)
        info_href = await hg.evaluate("() => (document.querySelector('#solNotices a') || {}).href || null")
        await sol_advance(hg, 6000, 2000)
        st_after = await hg.evaluate(SOL_STATE_JS)
        await hg.close()
        assert "Submitted." not in st_info["notice"] and "earlier swap" in st_info["notice"] and info_href == "https://solscan.io/tx/" + SOL_SIG_B58, \
            "[sol wallet hang] a late signature after the swap changed must only show a small info notice with the Solscan link: %s %s" % (st_info, info_href)
        assert h_stat and st_after["done"] is False and "Swap complete" not in st_after["page"], \
            "[sol wallet hang] the stranded signature is still polled, but never shows the done card for a different swap: polls=%d %s" % (len(h_stat), st_after["done"])
        # ج) فقط signTransaction: تمام‌شدنِ دیرهنگام، همان سواپ ⇒ دقیقاً یک sendTransaction؛ سواپِ عوض‌شده ⇒ هیچ
        h_rpc = []
        hg, _ = await hang_open("sign", rpc_log=h_rpc)
        await hg.evaluate("() => window.dispatchEvent(new Event('focus'))")
        await sol_advance(hg, 4500, 500)
        st_rel = await hg.evaluate(SOL_STATE_JS)
        await hg.evaluate("() => window.__hang.resolve()")
        await hg.wait_for_timeout(300)
        await hg.evaluate("() => window.__hang.resolve && window.__hang.resolve()")   # دومین resolve روی همان promise بی‌اثر است
        await hg.wait_for_timeout(300)
        st_sub = await hg.evaluate(SOL_STATE_JS)
        sends_same = h_rpc.count("sendTransaction")
        await hg.close()
        assert st_rel["notice"] == SOL_HANG_NOTICE, "[sol wallet hang] (sign-only) released with the exact text: %s" % st_rel
        assert sends_same == 1 and "Submitted." in st_sub["notice"], "[sol wallet hang] (sign-only) a late signed transaction for the same swap is sent exactly once: sends=%d %s" % (sends_same, st_sub)
        h_rpc = []
        hg, _ = await hang_open("sign", rpc_log=h_rpc)
        await hg.evaluate("() => window.dispatchEvent(new Event('focus'))")
        await sol_advance(hg, 4500, 500)
        await hg.fill("#solAmt", "2")
        await sol_advance(hg, 1500, 500)
        await hg.evaluate("() => window.__hang.resolve()")
        await hg.wait_for_timeout(300)
        st_chg = await hg.evaluate(SOL_STATE_JS)
        sends_chg = h_rpc.count("sendTransaction")
        await hg.close()
        assert sends_chg == 0 and "not sent" in st_chg["notice"], "[sol wallet hang] (sign-only) a signed transaction that arrives after the swap changed is never sent: sends=%d %s" % (sends_chg, st_chg)
        print("[sol wallet hang] a wallet promise that never settles: focus + 4 s (and not before: still waiting at 3 s) or 120 s in total releases the card with the exact text and the Swap button; a late rejection changes nothing (no console error); a late signature continues as normal (Submitted, polled with searchTransactionHistory, Swap complete) only for the same swap, otherwise a small info notice with the Solscan link and no done card; a late signed transaction is sent once for the same swap and never after it changed")

        # ---- [sol expiry] ----
        SOL_EXPIRED = "Not executed — the transaction expired before it landed. No funds moved."
        ex_rpc, ex_stat = [], []
        ex = await r5_run(clock=True, rpc_log=ex_rpc, status_params_log=ex_stat, status_value=[None], epoch_height=5000)
        await ex.click("#solSwapBtn")
        await ex.wait_for_timeout(900)
        epoch_base = ex_rpc.count("getEpochInfo")   # صفحه‌ی توکن خودش یک getEpochInfo می‌زند؛ فقط افزایش مهم است
        await sol_advance(ex, 50000, 2000)
        st_early = await ex.evaluate(SOL_STATE_JS)
        epoch_early = ex_rpc.count("getEpochInfo") - epoch_base
        await sol_advance(ex, 18000, 2000)
        st_exp = await ex.evaluate(SOL_STATE_JS)
        polls_at_exp = ex_rpc.count("getSignatureStatuses")
        await sol_advance(ex, 20000, 2000)
        polls_late = ex_rpc.count("getSignatureStatuses")
        await ex.close()
        assert "Submitted." in st_early["notice"] and epoch_early == 0, "[sol expiry] inside the first 60 s the poll is unchanged: no getEpochInfo, still Submitted: %s epoch=%d" % (st_early["notice"], epoch_early)
        assert st_exp["notice"] == SOL_EXPIRED and st_exp["done"] is False and "Swap complete" not in st_exp["page"], "[sol expiry] blockHeight past lastValidBlockHeight with no status must say exactly %r and show no done block: %s" % (SOL_EXPIRED, st_exp["notice"])
        assert polls_late == polls_at_exp, "[sol expiry] polling stops after the verdict: %d -> %d" % (polls_at_exp, polls_late)
        assert ex_stat and all(pr == [[SOL_SIG_B58], {"searchTransactionHistory": True}] for pr in ex_stat), "[sol expiry] every status read carries searchTransactionHistory: %s" % ex_stat[:2]
        # هنوز منقضی نشده (blockHeight < lastValid) ⇒ تا ۳ دقیقه «Still pending»، نه «Not executed»
        ex_rpc = []
        ex = await r5_run(clock=True, rpc_log=ex_rpc, status_value=[None], epoch_height=100)
        await ex.click("#solSwapBtn")
        await ex.wait_for_timeout(900)
        epoch_base2 = ex_rpc.count("getEpochInfo")
        await sol_advance(ex, 170000, 2000)
        st_mid = await ex.evaluate(SOL_STATE_JS)
        await sol_advance(ex, 20000, 2000)
        st_pend = await ex.evaluate(SOL_STATE_JS)
        epoch_n = ex_rpc.count("getEpochInfo") - epoch_base2
        await ex.close()
        assert "Submitted." in st_mid["notice"] and epoch_n >= 20, "[sol expiry] a not-yet-expired transaction keeps being polled for 3 minutes (epoch reads=%d): %s" % (epoch_n, st_mid["notice"])
        assert st_pend["notice"].startswith("Still pending — check Solscan.") and "View on Solscan" in st_pend["notice"], "[sol expiry] 3 minutes without a verdict ends on the existing 'Still pending' notice: %s" % st_pend["notice"]
        # lastValidBlockHeight باید از ساختِ دومِ (تازه‌شده) بیاید، نه ساختِ اول
        lv_bodies = [{"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 111}, {"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 222}]
        for height, want_exp in ((150, False), (300, True)):
            ex = await r5_run(clock=True, wallet_init=SOL_SIGN_ONLY_WALLET_INIT, swap_bodies=lv_bodies, swap_log=[], rpc_log=[],
                              send_error={"error": "rpc:sendTransaction:-32002", "detail": {"err": '"BlockhashNotFound"', "logs": []}}, send_error_times=1,
                              status_value=[None], epoch_height=height)
            await ex.click("#solSwapBtn")
            await ex.wait_for_timeout(1200)
            await sol_advance(ex, 185000, 2000)
            st_lv = await ex.evaluate(SOL_STATE_JS)
            await ex.close()
            if want_exp:
                assert st_lv["notice"] == SOL_EXPIRED, "[sol expiry] refreshed-transaction path, blockHeight 300 > its lastValidBlockHeight 222: expected the expiry notice, got %r" % st_lv["notice"]
            else:
                assert st_lv["notice"].startswith("Still pending"), "[sol expiry] refreshed-transaction path, blockHeight 150 is past the FIRST build's 111 but not the signed one's 222: must not claim expiry, got %r" % st_lv["notice"]
        print("[sol expiry] statuses stay null: nothing new in the first 60 s (no getEpochInfo), then every 4 s up to 3 min with getEpochInfo; blockHeight > lastValidBlockHeight plus one more status read gives exactly %r and no done block, polling stops; a transaction that has not expired ends on 'Still pending' at 3 min; after the BlockhashNotFound refresh the lastValidBlockHeight of the re-signed build decides (150 stays pending, 300 expires); every status read carries searchTransactionHistory" % SOL_EXPIRED)

        # ---- [sol revert reason] ----
        REV_CASES = [
            ({"InstructionError": [4, {"Custom": 6001}]}, "finalized",
             "Failed — the price moved more than your slippage allows. Nothing was swapped; only the network fee was paid. View on Solscan"),
            ("InsufficientFundsForRent", "confirmed", "Failed. Not enough SOL for the network fee and one-time account rent. Keep at least"),
            ({"InstructionError": [1, "InvalidAccountData"]}, "confirmed", "Failed. The transaction landed but reverted. View on Solscan"),
        ]
        for err, conf, want in REV_CASES:
            rv = await r5_run(status_value=[{"confirmationStatus": conf, "err": err}])
            await rv.click("#solSwapBtn")
            await rv.wait_for_timeout(3200)
            st_rv = await rv.evaluate(SOL_STATE_JS)
            await rv.close()
            assert st_rv["notice"].startswith(want) and "View on Solscan" in st_rv["notice"], "[sol revert reason] err %s: wanted %r, got %r" % (err, want, st_rv["notice"])
            assert st_rv["done"] is False and "Swap complete" not in st_rv["page"] and "Confirmed." not in st_rv["notice"], \
                "[sol revert reason] a status with err must never show the done block, even when %s: %s" % (conf, st_rv)
        print("[sol revert reason] a finalized/confirmed status with err: Custom 6001 gives the slippage sentence, InsufficientFundsForRent the existing SOL-and-rent wording, anything else 'landed but reverted' (Solscan link kept); in all three the Swap complete block never shows")

        # ================= [sim override] ۴ اکتبر — شکستِ شبیه‌سازی بلوک نیست، با تأییدِ کاربر ادامه می‌دهد =================
        SIMO_ERR = {"value": {"err": {"InstructionError": [1, "InvalidAccountData"]},
                              "logs": ["Program %s failed: invalid account data for instruction" % TOKP]}}
        SIMO_BTN = "Swap anyway (simulation failed)"
        SIMO_LINE = "You can still send it: if it fails on-chain you lose only the network fee (at most about 0.0002 SOL), and no tokens move."

        async def simo_state(pg_):
            return (await pg_.inner_text("#solSwapBtn")).strip(), await pg_.evaluate("window.__solCalls.length")

        # 1) شبیه‌سازیِ خودمان err می‌دهد: اعلان + خط دوم + دکمه؛ کلیکِ دوم فقط مسلح می‌کند؛ کلیکِ سوم کیف‌پول را صدا می‌زند و شبیه‌سازی را نمی‌زند
        simo_log = []
        sp1 = await r5_run(sim_result=SIMO_ERR, rpc_log=simo_log)
        await sp1.click("#solSwapBtn"); await sp1.wait_for_timeout(700)
        n1 = await sp1.inner_text("#solNotices"); btn1, w1 = await simo_state(sp1)
        sims_after_first = simo_log.count("simulateTransaction")
        os.makedirs("/tmp/claude-0/sim_shots", exist_ok=True)
        for vw_ in (1440, 390):
            await sp1.set_viewport_size({"width": vw_, "height": 1000})
            await sp1.wait_for_timeout(250)
            await sp1.screenshot(path="/tmp/claude-0/sim_shots/sol-warning-light-%d.png" % vw_)
        await sp1.set_viewport_size({"width": 1240, "height": 1000})
        btn2, w2 = btn1, w1
        await sp1.click("#solSwapBtn"); await sp1.wait_for_timeout(900)   # کلیک روی «Swap anyway» = تأیید + ارسال
        btn3, w3 = await simo_state(sp1)
        sims_total = simo_log.count("simulateTransaction")
        await sp1.close()
        print("[sim override] solana own-sim err -> btn=%r wallet=%d | after arm click btn=%r wallet=%d | after 3rd click wallet=%d sims %d->%d"
              % (btn1, w1, btn2, w2, w3, sims_after_first, sims_total))
        assert "This swap would fail on-chain: simulation failed." in n1 and SIMO_LINE in n1 and "Code: 1:InvalidAccountData" in n1, \
            "sim override: the failure notice needs the reason, the second line and the code: %r" % n1
        assert btn1 == SIMO_BTN and w1 == 0, "sim override: after the failure the button must offer the override with no wallet call: %r / %d" % (btn1, w1)
        assert w3 == 1, "sim override: clicking 'Swap anyway' must reach the wallet exactly once (it is the confirmation), got %d" % w3
        assert sims_after_first == 1 and sims_total == 1, \
            "sim override: our own simulation must NOT run again once armed (calls %d -> %d)" % (sims_after_first, sims_total)

        # 2) جوپیتر simulationError می‌دهد ولی شبیه‌سازیِ خودمان پاس است: همان کلیکِ اول، بدونِ هشدار
        j_body = {"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 123,
                  "simulationError": {"errorCode": "SLIPPAGE_TOLERANCE_EXCEEDED", "error": "jup says no"}}
        sp2 = await r5_run(swap_body=j_body, sim_result="ok")
        await sp2.click("#solSwapBtn"); await sp2.wait_for_timeout(900)
        btn_b, w_b = await simo_state(sp2)
        n_b = await sp2.inner_text("#solNotices")
        err_notes = await sp2.evaluate("document.querySelectorAll('#solNotices .note.err').length")
        await sp2.close()
        print("[sim override] solana jupiter simulationError but ours passes -> wallet=%d btn=%r errNotes=%d" % (w_b, btn_b, err_notes))
        assert w_b == 1 and err_notes == 0 and SIMO_LINE not in n_b and "simulation failed" not in n_b, \
            "sim override: when our own simulation passes, Jupiter's simulationError must not warn or block: %r" % n_b

        # 3) جوپیتر simulationError و RPCِ ما می‌افتد: پیام از کدِ جوپیتر مثلِ قبل؛ مسلح‌شدن کار می‌کند
        j_body3 = {"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 123,
                   "simulationError": {"errorCode": "SOME_JUP_CODE", "error": "x"}}
        sp3 = await r5_run(swap_body=j_body3, sim_rpc_fail=True)
        await sp3.click("#solSwapBtn"); await sp3.wait_for_timeout(700)
        n3 = await sp3.inner_text("#solNotices"); btn3a, w3a = await simo_state(sp3)
        await sp3.click("#solSwapBtn"); await sp3.wait_for_timeout(900)   # «Swap anyway» = تأیید + ارسال
        btn3b, w3b = await simo_state(sp3)
        await sp3.close()
        print("[sim override] solana jupiter code + our rpc down -> btn=%r wallet=%d -> %d notice=%r" % (btn3a, w3a, w3b, n3[:70]))
        assert "This swap would fail on-chain: simulation failed." in n3 and "Code: SOME_JUP_CODE" in n3 and SIMO_LINE in n3, \
            "sim override: with our RPC down the Jupiter errorCode must be used as before: %r" % n3
        assert btn3a == SIMO_BTN and w3a == 0 and w3b == 1, "sim override: arming must work on the Jupiter-code path: %r / %d / %d" % (btn3a, w3a, w3b)

        # 4) فی‌پیرِ غلط: هرگز مسلح‌شدنی نیست (حتی وقتی شبیه‌سازی هم می‌افتد)
        sp4 = await r5_run(swap_body={"swapTransaction": SOL_BAD_TX_B64, "lastValidBlockHeight": 1,
                                      "simulationError": {"errorCode": "X_CODE", "error": "x"}}, sim_result=SIMO_ERR)
        seen4 = []
        for _ in range(3):
            await sp4.click("#solSwapBtn"); await sp4.wait_for_timeout(600)
            seen4.append((await sp4.inner_text("#solSwapBtn")).strip())
        n4 = await sp4.inner_text("#solNotices"); w4 = await sp4.evaluate("window.__solCalls.length")
        await sp4.close()
        print("[sim override] solana fee-payer mismatch never armable -> buttons=%s wallet=%d" % (seen4, w4))
        assert "Refused: the transaction's fee payer is not your wallet." in n4 and SIMO_LINE not in n4, "sim override: the refusal must stay a plain block: %r" % n4
        assert SIMO_BTN not in seen4 and w4 == 0, "sim override: a fee-payer refusal must never become armable: %s / %d" % (seen4, w4)

        # 5) تغییر مبلغ بعد از مسلح‌شدن: برچسب به «Swap» برمی‌گردد و شکستِ تازه تأییدِ تازه می‌خواهد
        sp5 = await r5_run(sim_result=SIMO_ERR)
        async def quote_by_amount(route):
            u = route.request.url
            m_ = re.search(r"amount=(\d+)", u)
            await route.fulfill(status=200, content_type="application/json",
                                 body=_json.dumps({**SOL_QUOTE_FIXTURE, "inAmount": m_.group(1) if m_ else "1"}))
        await sp5.route("**/sol/quote**", quote_by_amount)
        await sp5.fill("#solAmt", "0.5"); await sp5.wait_for_timeout(900)
        await sp5.click("#solSwapBtn"); await sp5.wait_for_timeout(700)
        b5a, _w = await simo_state(sp5)
        # مسلح‌کردن بدونِ ارسال (همان حالتی که کلیکِ «Swap anyway» پیش از ارسال می‌سازد)
        await sp5.evaluate("solSimArmedKey=solSimFailedKey; solUpdateSwapBtn()")
        b5b, _w = await simo_state(sp5)
        await sp5.fill("#solAmt", "0.75"); await sp5.wait_for_timeout(900)
        b5c, w5c = await simo_state(sp5)
        await sp5.click("#solSwapBtn"); await sp5.wait_for_timeout(800)
        b5d, w5d = await simo_state(sp5)
        await sp5.close()
        print("[sim override] solana amount change disarms -> %r / %r / after change %r / after new failure %r wallet=%d" % (b5a, b5b, b5c, b5d, w5d))
        assert b5a == SIMO_BTN and b5b == "Swap", "sim override: the arm sequence is wrong: %r / %r" % (b5a, b5b)
        assert b5c == "Swap" and w5c == 0, "sim override: a changed amount must drop the confirmation: %r / %d" % (b5c, w5c)
        assert w5d == 0 and b5d == SIMO_BTN, "sim override: a new failure needs a new confirmation, never reaches the wallet: %r / %d" % (b5d, w5d)

        # 6) keepSol: SOL -> توکنِ بدونِ حسابِ خروجی = کارمزد + 2×0.00204 (یکی ATA، یکی wSOL موقتِ جوپیتر)
        import math as _m
        fee_l = 700000
        want_keep = "%.4f" % (_m.ceil(((fee_l + 5000) / 1e9 + 0.00204 * 2) * 1e4) / 1e4)
        SIMO_RENT = {"value": {"err": {"InstructionError": [2, {"Custom": 1}]}, "logs": [
            "Program %s invoke [1]" % SYSP, "Transfer: insufficient lamports 4875000, need 2039280",
            "Program %s failed: custom program error: 0x1" % SYSP]}}
        sp6 = await r5_run(sim_result=SIMO_RENT, swap_body={"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 123,
                                                               "prioritizationFeeLamports": fee_l})
        await sp6.click("#solSwapBtn"); await sp6.wait_for_timeout(700)
        n6 = await sp6.inner_text("#solNotices")
        await sp6.close()
        print("[sim override] solana keepSol SOL->token without output account -> %r (want %s SOL)" % (n6[:110], want_keep))
        assert ("Keep at least %s SOL." % want_keep) in n6, "sim override: keepSol must be fee + 2x0.00204 rounded up: wanted %s, got %r" % (want_keep, n6)


        # 7) دلیلِ بسته‌ی شکستِ کوت — پیامِ هر دلیل، و تلاشِ دوباره‌ی یک‌باره برای rate-limited
        for reason, want in [("no-route", "No route for this pair right now"), ("not-tradable", "Jupiter does not trade this token."),
                             ("amount-too-small", "Amount too small to route."), ("upstream", "Quote service did not answer."),
                             ("amount-too-large", "Not enough liquidity for this amount"), ("amount-unpriced", "Could not price this amount"),
                             ("bad-request", "Could not get a quote for this pair.")]:
            qp = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_status=502, quote_reason=reason)
            await qp.fill("#solAmt", "1")
            await qp.wait_for_timeout(900)
            qn = await qp.inner_text("#solNotices")
            await qp.close()
            assert want in qn, "7: reason %r must show %r, got %r" % (reason, want, qn)
        r7_log = []
        qp = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_status=502, quote_reason="rate-limited", quote_log=r7_log)
        await qp.fill("#solAmt", "1")
        await qp.wait_for_timeout(900)
        n1 = await qp.inner_text("#solNotices")
        calls1 = len([u for u in r7_log if "onlyDirectRoutes" not in u])
        await qp.wait_for_timeout(3600)
        calls2 = len([u for u in r7_log if "onlyDirectRoutes" not in u])
        n2 = await qp.inner_text("#solNotices")
        await qp.wait_for_timeout(3600)
        calls3 = len([u for u in r7_log if "onlyDirectRoutes" not in u])
        await qp.close()
        print("[sol round5][7] rate-limited -> before=%r quotes %d -> %d -> %d after=%r" % (n1[:50], calls1, calls2, calls3, n2[:50]))
        assert "Quotes are busy — retrying in a few seconds." in n1 and calls2 == calls1 + 1 and calls3 == calls2, \
            "7: rate-limited must retry exactly once after ~3 s (quotes %d/%d/%d)" % (calls1, calls2, calls3)

        # 9) price impact: ≥15% یک کلیکِ اضافه، ≥50% خطِ هشدار
        for pct, arm, warn in [("0.0123", False, False), ("0.2", True, False), ("0.62", True, True)]:
            ip_calls = []
            ip = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_body={**SOL_QUOTE_FIXTURE, "priceImpactPct": pct})
            await sol_connect(ip)
            await ip.fill("#solAmt", "1")
            await ip.wait_for_timeout(900)
            t_before = await ip.inner_text("#solSwapBtn")
            w_vis = await ip.evaluate("() => !document.getElementById('solImpactWarn').hidden")
            await ip.click("#solSwapBtn")
            await ip.wait_for_timeout(500)
            calls_after_first = await ip.evaluate("window.__solCalls.length")
            t_after = await ip.inner_text("#solSwapBtn")
            await ip.close()
            print("[sol round5][9] impact %s%% -> %r, warn=%s, wallet calls after 1st click=%d -> %r" % (float(pct) * 100, t_before, w_vis, calls_after_first, t_after))
            assert w_vis is warn, "9: the >=50%% warning line visibility is wrong at %s" % pct
            if arm:
                assert t_before.startswith("Swap anyway (price impact ") and calls_after_first == 0 and t_after == "Swap", \
                    "9: a high impact must need one extra click before the wallet: %r / %d / %r" % (t_before, calls_after_first, t_after)
            else:
                assert t_before == "Swap" and calls_after_first == 1, "9: a normal impact must not be gated: %r / %d" % (t_before, calls_after_first)

        # 3) لوگوی جایگزین روی کارتِ سولانا و تابعِ مشترکِ Base — گرادیان + یک حرفِ سفید
        fb = await open_sol_swap_page({"v": "sell", "ms": 100})
        fb_info = await fb.evaluate("""() => {
            const el = document.getElementById('solBotAv'), cs = getComputedStyle(el);
            const probe = document.createElement('span'); probe.className = 'av'; document.body.appendChild(probe);
            paintAvatar(probe, {symbol: 'xyz', address: '0xAbCdEf0123456789aBcDeF0123456789AbCdEf01'});
            const probe2 = document.createElement('span'); probe2.className = 'av'; document.body.appendChild(probe2);
            paintAvatar(probe2, {symbol: 'XYZ', address: '0xabcdef0123456789abcdef0123456789abcdef01'});
            return {text: el.textContent, bg: cs.backgroundImage, color: cs.color, weight: cs.fontWeight,
                    baseLetter: probe.textContent, baseBg: probe.style.background, sameBg: probe.style.background === probe2.style.background,
                    imgs: el.querySelectorAll('img').length};
        }""")
        await fb.close()
        print("[sol round5][3] fallback avatar -> %s" % fb_info)
        assert fb_info["text"] == "T" and "linear-gradient" in fb_info["bg"] and fb_info["color"] == "rgb(255, 255, 255)" and fb_info["weight"] in ("700", "bold"), \
            "3: the Solana chip must show a gradient circle with a white bold first letter: %s" % fb_info
        assert fb_info["baseLetter"] == "X" and "linear-gradient" in fb_info["baseBg"] and fb_info["sameBg"], \
            "3: Base paintAvatar must use the same fallback, hue stable across hex case: %s" % fb_info

        # C) silent reconnect — نامِ آخرین کیف‌پول در localStorage + بدونِ پرچمِ
        # off یعنی standard:connect با {silent:true} بدونِ هیچ کلیکی، و هدر
        # آدرسِ کوتاه را نشان می‌دهد؛ off-flag یعنی هیچ تماسی زده نمی‌شود.
        cpg2 = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_SILENT_CAPTURE_WALLET_INIT,
                                         ls_wallet_name="Fake Wallet")
        await cpg2.wait_for_timeout(600)
        c_opts = await cpg2.evaluate("window.__solConnectOpts")
        c_btn = await cpg2.inner_text("#connectBtn")
        await cpg2.close()
        print("[sol round3][C] stored name, no off -> connectOpts=%s btn=%r" % (c_opts, c_btn))
        assert c_opts == [], "A new page must never connect a Solana wallet without a click"
        assert c_btn == "Connect wallet", "Stored permissions must leave the site disconnected until a click"


        cpg3 = await open_sol_swap_page({"v": "sell", "ms": 100}, wallet_init=SOL_SILENT_CAPTURE_WALLET_INIT,
                                         ls_wallet_name="Fake Wallet", ls_off=True)
        await cpg3.wait_for_timeout(600)
        c2_opts = await cpg3.evaluate("window.__solConnectOpts")
        c2_btn = await cpg3.inner_text("#connectBtn")
        await cpg3.close()
        print("[sol round3][C] off-flag set -> connectOpts=%s btn=%r" % (c2_opts, c2_btn))
        assert len(c2_opts) == 0, "C: the off-flag must block the silent reconnect entirely, got %s" % c2_opts
        assert c2_btn == "Connect wallet", "C: the off-flag must leave the wallet disconnected, got %r" % c2_btn

        # D) worker forces the lower fee cap (covered in worker/test.mjs);
        # here: the readout shows the placeholder before a build and the real
        # ≈X SOL figure (from prioritizationFeeLamports+5000/signature) after.
        dpg2 = await open_sol_swap_page({"v": "sell", "ms": 100},
                                         swap_body={"swapTransaction": SOL_GOOD_TX_B64, "lastValidBlockHeight": 1,
                                                    "prioritizationFeeLamports": 150000})
        await sol_connect(dpg2)
        d_fee_before = await dpg2.inner_text("#solFeeF")
        await dpg2.fill("#solAmt", "1")
        await dpg2.wait_for_timeout(900)
        await dpg2.click("#solSwapBtn")
        await dpg2.wait_for_timeout(900)
        d_fee_after = await dpg2.inner_text("#solFeeF")
        await dpg2.close()
        print("[sol round3][D] fee before=%r after=%r" % (d_fee_before, d_fee_after))
        assert d_fee_before == "≈ ≤0.0002 SOL", "D: the placeholder fee row is wrong before any build: %r" % d_fee_before
        assert d_fee_after == "≈ 0.000155 SOL", \
            "D: (150000+5000)/1e9 = 0.000155 SOL was expected after the build, got %r" % d_fee_after

        # E) typing in "You receive" re-quotes with swapMode=ExactOut and fills
        # "You pay"; a pair Jupiter refuses for ExactOut reverts to ExactIn.
        e_quote_urls = []
        SOL_EXACTOUT_FIXTURE = dict(SOL_QUOTE_FIXTURE, inAmount="2000000000", swapMode="ExactOut")
        epg2 = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_body=SOL_EXACTOUT_FIXTURE)
        async def record_quote(route):
            e_quote_urls.append(route.request.url)
            await route.fulfill(status=200, content_type="application/json", body=_json.dumps(SOL_EXACTOUT_FIXTURE))
        await epg2.route("**/sol/quote**", record_quote)
        await epg2.fill("#solOutRead", "5")
        await epg2.wait_for_timeout(900)
        e_pay = await epg2.input_value("#solAmt")
        e_label = await epg2.inner_text("#solMinLabel")
        await epg2.close()
        print("[sol round3][E] You-receive=5 -> You-pay=%r label=%r lastUrl=%r"
              % (e_pay, e_label, e_quote_urls[-1] if e_quote_urls else None))
        assert e_quote_urls and all("swapMode=ExactOut" in url for url in e_quote_urls), \
            "E: typing in You-receive must call /sol/quote with swapMode=ExactOut, got %s" % e_quote_urls
        assert e_pay == "2.000000" or e_pay == "2", "E: You-pay must be filled from inAmount, got %r" % e_pay
        assert e_label == "Max sent", "E: the Min-received label must read Max sent in ExactOut mode, got %r" % e_label

        e2pg = await open_sol_swap_page({"v": "sell", "ms": 100}, quote_status=422)
        await e2pg.fill("#solOutRead", "5")
        await e2pg.wait_for_timeout(900)
        e2_notice = await e2pg.inner_text("#solNotices")
        e2_pay = await e2pg.input_value("#solAmt")
        await e2pg.close()
        print("[sol round3][E] ExactOut rejected -> notice=%r payFieldEmpty=%s" % (e2_notice[:70], e2_pay == ""))
        assert "can't be quoted by output amount" in e2_notice, \
            "E: a rejected ExactOut quote must show the exact fallback sentence, got %r" % e2_notice

        # [sol reverse solve] ExactOut همیشه شکست می‌خورد؛ ExactIn یک AMMِ قطعی است.
        # راهکار باید با ExactIn مقدارِ پرداخت را پیدا کند (حداکثر ۵ تماسِ حل).
        from urllib.parse import urlparse as _up, parse_qs as _pq
        def rs_fwd(x):
            return x * 1000 * 10**12 // (x + 10**12) * 9975 // 10000
        def rs_rev_guess(y):
            return y // 1000 * 98 // 100       # حدود ۲٪ دور از جوابِ واقعی
        async def rs_open(mode, delay=0.0):
            rs_state = {"mode": mode, "log": [], "delay": delay}
            rpg = await open_sol_swap_page({"v": "sell", "ms": 100})
            async def rs_stub(route):
                qs = {k: v[0] for k, v in _pq(_up(route.request.url).query).items()}
                m = rs_state["mode"]
                if rs_state["delay"]:
                    await asyncio.sleep(rs_state["delay"])
                if "onlyDirectRoutes" not in qs:
                    rs_state["log"].append(qs)
                amt = int(qs.get("amount", "0"))
                is_out = qs.get("swapMode") == "ExactOut"
                forward = qs.get("inputMint") != SWAP_MINT
                bad = is_out or m == "allfail" \
                    or (m == "norev" and not forward and "onlyDirectRoutes" not in qs) \
                   
                if bad:
                    await route.fulfill(status=400, content_type="application/json",
                                         body=_json.dumps({"error": "jup:quote:400"}))
                    return
                if forward:
                    body = dict(SOL_QUOTE_FIXTURE, inAmount=str(amt), outAmount=str(rs_fwd(amt)))
                else:
                    body = dict(SOL_QUOTE_FIXTURE, inAmount=str(amt), outAmount=str(rs_rev_guess(amt)))
                await route.fulfill(status=200, content_type="application/json", body=_json.dumps(body))
            await rpg.route("**/sol/quote**", rs_stub)
            return rpg, rs_state

        RS_TARGET = 10000 * 10**6
        # (a) حلِ عادی با حدسِ اولِ معکوس
        rpg, rs_a = await rs_open("normal")
        await rpg.fill("#solOutRead", "10000")
        await rpg.wait_for_timeout(1500)
        ra_mode = await rpg.evaluate("solMode")
        ra_amt = await rpg.input_value("#solAmt")
        ra_out = int(await rpg.evaluate("solQuote ? solQuote.outAmount : '0'"))
        ra_note = await rpg.inner_text("#solNotices")
        await rpg.close()
        ra_calls = [c for c in rs_a["log"] if c.get("swapMode") != "ExactOut"]
        print("[sol reverse solve] (a) mode=%s pay=%r out=%d target=%d solveCalls=%d" % (ra_mode, ra_amt, ra_out, RS_TARGET, len(ra_calls)))
        assert ra_mode == "exactIn" and ra_amt != "", "reverse solve (a): mode must become exactIn with the pay field filled, got %r / %r" % (ra_mode, ra_amt)
        assert RS_TARGET <= ra_out <= RS_TARGET * 101 // 100, "reverse solve (a): quoted out must be within [target, target+1%%], got %d" % ra_out
        assert 1 <= len(ra_calls) <= 5, "reverse solve (a): at most 5 solver calls, got %d" % len(ra_calls)
        assert "so we found the amount to pay" in ra_note, "reverse solve (a): the ok notice is missing: %r" % ra_note

        # (b) معکوس هم شکست می‌خورد ولی پروبِ یک توکن جواب می‌دهد
        rpg, rs_b = await rs_open("norev")
        await rpg.fill("#solOutRead", "10000")
        await rpg.wait_for_timeout(1500)
        rb_mode = await rpg.evaluate("solMode")
        rb_out = int(await rpg.evaluate("solQuote ? solQuote.outAmount : '0'"))
        rb_calls = [c for c in rs_b["log"] if c.get("swapMode") != "ExactOut"]
        await rpg.close()
        print("[sol reverse solve] (b) no reverse quote -> mode=%s out=%d solveCalls=%d" % (rb_mode, rb_out, len(rb_calls)))
        assert rb_mode == "exactIn" and rb_out >= RS_TARGET, "reverse solve (b): the probe path must still solve, got %s / %d" % (rb_mode, rb_out)
        assert len(rb_calls) <= 5, "reverse solve (b): at most 5 solver calls, got %d" % len(rb_calls)

        # (ج) همه‌ی ExactIn ها شکست می‌خورند — رفتارِ قدیمی
        rpg, rs_c = await rs_open("allfail")
        await rpg.fill("#solOutRead", "10000")
        await rpg.wait_for_timeout(1500)
        rc_note = await rpg.inner_text("#solNotices")
        rc_quote = await rpg.evaluate("solQuote")
        rc_mode = await rpg.evaluate("solMode")
        await rpg.close()
        print("[sol reverse solve] (c) everything fails -> mode=%s quote=%r notice=%r" % (rc_mode, rc_quote, rc_note[:70]))
        assert "This pair can't be quoted by output amount — enter the amount you pay." in rc_note, "reverse solve (c): old warn notice expected, got %r" % rc_note
        assert rc_quote is None and rc_mode == "exactIn", "reverse solve (c): quote must be null and mode exactIn, got %r / %s" % (rc_quote, rc_mode)

        # (د) کهنگی — وسطِ حل مبلغ عوض می‌شود؛ حلِ اول نباید چیزی بنویسد
        rpg, rs_d = await rs_open("normal", delay=0.5)
        await rpg.fill("#solOutRead", "10000")
        await rpg.wait_for_timeout(1000)               # ExactOut برگشته، معکوس در راه است
        rs_d["mode"] = "allfail"
        await rpg.fill("#solOutRead", "20000")
        await rpg.wait_for_timeout(4500)
        rd_amt = await rpg.input_value("#solAmt")
        rd_quote = await rpg.evaluate("solQuote")
        rd_note = await rpg.inner_text("#solNotices")
        await rpg.close()
        print("[sol reverse solve] (d) stale solve writes nothing -> pay=%r quote=%r notice=%r" % (rd_amt, rd_quote, rd_note[:50]))
        assert rd_amt == "" and rd_quote is None, "reverse solve (d): a stale solve must not write, got %r / %r" % (rd_amt, rd_quote)
        assert "so we found the amount to pay" not in rd_note, "reverse solve (d): the stale ok notice leaked: %r" % rd_note

        # F) after Confirmed, getBalance is polled again promptly; clicking the
        # pay-side balance figure fills the field with the full spendable amount.
        f_rpc_log = []
        fpg2 = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=3_000_000_000, rpc_log=f_rpc_log)
        await sol_connect(fpg2)
        await fpg2.fill("#solAmt", "1")
        await fpg2.wait_for_timeout(900)
        f_bal_calls_before = f_rpc_log.count("getBalance")
        await fpg2.click("#solSwapBtn")
        await fpg2.wait_for_timeout(2600)                 # اولین دورِ solPollStatus
        f_bal_calls_after = f_rpc_log.count("getBalance")
        await fpg2.close()
        print("[sol round3][F] getBalance calls before=%d after confirm=%d" % (f_bal_calls_before, f_bal_calls_after))
        assert f_bal_calls_after > f_bal_calls_before, \
            "F: a Confirmed swap must trigger a fresh getBalance promptly, before=%d after=%d" \
            % (f_bal_calls_before, f_bal_calls_after)

        f2pg2 = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=3_000_000_000)
        await sol_connect(f2pg2)
        await f2pg2.wait_for_timeout(300)
        # کلیکِ واقعیِ Playwright روی مرکزِ باکس می‌تواند به‌جای خودِ عدد، روی
        # دکمه‌ی ۵۰٪/MAXِ کناری بیفتد (هر دو داخل همان <b> هستند) — دیسپچِ
        # مستقیم روی خودِ گره تضمین می‌کند e.target داخلِ .frac نباشد.
        await f2pg2.eval_on_selector("#solTopBal",
            "el => el.dispatchEvent(new MouseEvent('click', {bubbles: true}))")
        await f2pg2.wait_for_timeout(150)
        f2_amt = await f2pg2.input_value("#solAmt")
        await f2pg2.close()
        print("[sol round3][F] clicking the pay balance figure -> #solAmt=%r" % f2_amt)
        # ۵ اکتبر: رزرو شامل رنتِ wSOL است (۰٫۰۰۴۲۹)
        assert f2_amt == "2.99571", \
            "F: clicking the balance figure above You-pay must fill the full spendable amount (MAX), got %r" % f2_amt

        # G) the SOL chip's <img> src comes from the GT single-token fixture.
        SOL_LOGO_URL = "https://assets.geckoterminal.com/fake/sol.png"
        gpg = await open_sol_swap_page({"v": "sell", "ms": 100}, sol_mint_image_url=SOL_LOGO_URL)
        await gpg.wait_for_timeout(700)
        g_src = await gpg.eval_on_selector("#solTopAv img", "el => el ? el.src : null")
        await gpg.close()
        print("[sol round3][G] SOL chip img src=%r" % g_src)
        assert g_src == SOL_LOGO_URL, "G: the SOL chip must show the GT-fetched wSOL logo, got %r" % g_src

        # H) the Solana exit-check card's Copy-this-check button must match
        # Base's size (±2px) at 1440px, and the card title must not wrap.
        hpg2 = await open_app(viewport={"width": 1440, "height": 900})
        await hpg2.wait_for_timeout(300)
        h_base = await hpg2.eval_on_selector("#checkShare", "el => el.getBoundingClientRect().height")
        await hpg2.click("#srcChip")
        await hpg2.click('#srcPop [data-chain="solana"]')
        await hpg2.wait_for_timeout(200)
        h_sol = await hpg2.eval_on_selector("#appSolCheckShare", "el => el.getBoundingClientRect().height")
        h_ttl = await hpg2.eval_on_selector("#appSolSafetyCard>header>.ttl:first-child",
                                             "el => el.getBoundingClientRect().height")
        await hpg2.close()
        print("[sol round3][H] button height base=%r solana=%r titleHeight=%r" % (h_base, h_sol, h_ttl))
        assert abs(h_base - h_sol) <= 2, \
            "H: the Solana Copy-this-check button must match Base's size within 2px, base=%r solana=%r" % (h_base, h_sol)
        assert h_ttl <= 20, "H: the exit-check card title must stay on one line at 1440px, height=%r" % h_ttl

        print("[sol round3] fresh transaction build right before each wallet prompt, never reusing the first "
              "build (A); worker/index.js's closed sendTransaction detail mapped to readable sentences, never "
              "a bare code (B); silent reconnect on start gated by the stored wallet name and the off-flag (C); "
              "the lowered priority-fee cap with a live Network-fee row (D); ExactOut quoting from You-receive "
              "with the ExactIn fallback on rejection (E); prompt balance refresh after Confirmed and the "
              "pay-balance click filling MAX (F); the SOL chip's GT-fetched logo (G); and Copy-this-check's "
              "Base-matching size at 1440px (H) — all covered")

        # ---- [pairs filters] چیپ‌های آمار × جست‌وجو × مرتب‌سازی — ترکیب‌های
        # دقیق، رویِ یک استابِ ۶ ردیفی. ----
        FILTER_ROWS = [
            dict(SELL_ROW, address="0x" + "a1" * 20, symbol="FA1", name="Filter Alpha",
                 reserveUsd=1000, vol24hUsd=50, poolCreatedAt="2020-01-01T00:00:00.000Z"),
            dict(SELL_ROW, address="0x" + "a2" * 20, symbol="FA2", name="Filter Beta",
                 reserveUsd=5000, vol24hUsd=10, poolCreatedAt="2020-01-03T00:00:00.000Z"),
            dict(NOSELL_ROW, address="0x" + "a3" * 20, symbol="FA3", name="Filter Gamma",
                 reserveUsd=2000, vol24hUsd=90, poolCreatedAt="2020-01-02T00:00:00.000Z"),
            dict(NOSELL_ROW, address="0x" + "a4" * 20, symbol="FA4", name="Filter Delta",
                 reserveUsd=None, vol24hUsd=None, poolCreatedAt=None),
            dict(UNKNOWN_ROW, address="0x" + "a5" * 20, symbol="FA5", name="Filter Epsilon",
                 reserveUsd=3000, vol24hUsd=70, poolCreatedAt="2020-01-04T00:00:00.000Z"),
            dict(UNKNOWN_ROW, address="0x" + "a6" * 20, symbol="FA6", name="Filter Zeta",
                 reserveUsd=4000, vol24hUsd=30, poolCreatedAt="2019-12-31T00:00:00.000Z"),
        ]
        fpg, ferrs = await open_pairs({"chain": "base", "rows": FILTER_ROWS, "store": True})

        async def syms(page):
            return await page.eval_on_selector_all(
                "#rowsBody .token-sym", "els => els.map(e => e.textContent.trim())")

        async def chip_counts(page):
            return await page.eval_on_selector_all(
                "#statsStrip .stat-chip", "els => els.map(e => e.textContent)")

        async def click_chip(page, name):
            await page.click('#statsStrip button[data-filter="%s"]' % name)
            await page.wait_for_timeout(120)

        async def set_sort(page, val):
            await page.select_option("#pairSort", val)
            await page.wait_for_timeout(120)

        counts0 = await chip_counts(fpg)

        await set_sort(fpg, "liq")
        order_liq = await syms(fpg)

        await click_chip(fpg, "sell")
        await set_sort(fpg, "vol")
        order_sell_vol = await syms(fpg)

        await click_chip(fpg, "nosell")
        await set_sort(fpg, "newest")
        await fpg.fill("#pairSearch", "delta")
        await fpg.wait_for_timeout(150)
        order_nosell_delta = await syms(fpg)
        counts_during_filter = await chip_counts(fpg)

        await fpg.fill("#pairSearch", "")
        await click_chip(fpg, "unknown")
        await set_sort(fpg, "age")
        order_unknown_age = await syms(fpg)

        await click_chip(fpg, "all")
        await set_sort(fpg, "newest")
        await fpg.wait_for_timeout(150)
        order_restored = await syms(fpg)
        await fpg.close()

        print("[pairs filters] chip counts=%s liq-sort=%s sell+vol=%s nosell+search(delta)=%s "
              "countsDuringFilter=%s unknown+age=%s all-restored=%s errors=%s"
              % (counts0, order_liq, order_sell_vol, order_nosell_delta, counts_during_filter,
                 order_unknown_age, order_restored, ferrs))
        assert counts0 == ["All 6", "Sell quoted 2", "No sell quote 2", "Unknown 2"], (
            "the stat chip counts do not match the stub's verdict counts: %s" % counts0)
        assert counts_during_filter == counts0, (
            "the stat chip counts changed while a chip filter + search were active — they must "
            "always reflect the full loaded chain, never the filtered/searched subset: %s != %s"
            % (counts_during_filter, counts0))
        assert order_liq == ["FA2", "FA6", "FA5", "FA3", "FA1", "FA4"], (
            "Liquidity sort (desc, missing last) gave the wrong order: %s" % order_liq)
        assert order_sell_vol == ["FA1", "FA2"], (
            "sell filter + 24h volume sort gave the wrong order: %s" % order_sell_vol)
        assert order_nosell_delta == ["FA4"], (
            "no-sell-quote filter + search \"delta\" gave the wrong result: %s" % order_nosell_delta)
        assert order_unknown_age == ["FA5", "FA6"], (
            "unknown filter + pool-age sort gave the wrong order: %s" % order_unknown_age)
        assert order_restored == ["FA1", "FA2", "FA3", "FA4", "FA5", "FA6"], (
            "clicking All did not restore the full, server-order list: %s" % order_restored)
        assert not ferrs, "web/pairs.html threw during the filters probe: %s" % ferrs

        print("[pairs filters] stat-chip counts match the stub's per-verdict counts; chip filter x "
              "search x sort combinations (Liquidity/24h volume/Pool age, missing values sorted last) "
              "give the exact expected row order; clicking All restores the full server-order list")

        # ---- [pairs rows] ردیفِ چگال — ارتفاع، Trade، Copy، سلولِ یک‌خطیِ توکن. ----
        ROW_NAME_ROW = dict(SELL_ROW, address="0x" + "b1" * 20, symbol="ROWX",
                             name="A Very Long Token Name For Truncation Test 12")
        assert len(ROW_NAME_ROW["name"]) >= 40, "fixture name must be >=40 chars for the row-height probe"

        rpg = await b.new_page(viewport={"width": 1280, "height": 900})
        rerrs = []
        rpg.on("pageerror", lambda e: rerrs.append(str(e)))
        await rpg.route("**/pairs.json**", lambda route: route.fulfill(
            status=200, content_type="application/json",
            body=_jsonPairs.dumps({"chain": "base", "rows": [ROW_NAME_ROW, SELL_ROW], "store": True})))
        await rpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await rpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await rpg.add_init_script("""
            window.__copyCalls = [];
            Object.defineProperty(navigator, 'clipboard', {
                value: { writeText: (t) => { window.__copyCalls.push(t); return Promise.resolve(); } },
                configurable: true
            });
        """)
        await rpg.goto("http://127.0.0.1:%d/pairs.html" % port)
        await rpg.wait_for_timeout(500)

        rowInfo = await rpg.evaluate("""() => {
            const trs = [...document.querySelectorAll('#rowsBody tr')];
            const heights = trs.map(tr => tr.getBoundingClientRect().height);
            const sym = document.querySelector('#rowsBody .token-sym').getBoundingClientRect();
            const name = document.querySelector('#rowsBody .token-name').getBoundingClientRect();
            const trade = document.querySelector('#rowsBody .trade-btn');
            return {
                heights: heights, symTop: sym.top, nameTop: name.top,
                tradeHref: trade ? trade.getAttribute('href') : null,
            };
        }""")
        url_before = rpg.url
        await rpg.click("#rowsBody .copy-btn >> nth=0")
        await rpg.wait_for_timeout(150)
        url_after = rpg.url
        copyCalls = await rpg.evaluate("window.__copyCalls")
        copiedText = await rpg.eval_on_selector("#rowsBody .copy-btn", "e => e.textContent.trim()")
        await rpg.close()

        print("[pairs rows] heights=%s symTop=%.1f nameTop=%.1f tradeHref=%s urlBefore=%s urlAfter=%s "
              "copyCalls=%s copiedText=%r errors=%s"
              % (rowInfo["heights"], rowInfo["symTop"], rowInfo["nameTop"], rowInfo["tradeHref"],
                 url_before, url_after, copyCalls, copiedText, rerrs))
        assert all(h <= 56 for h in rowInfo["heights"]), (
            "a row is taller than 56px at 1280px with a 40+ char name: %s" % rowInfo["heights"])
        assert rowInfo["tradeHref"] == "/app#swap?out=" + ROW_NAME_ROW["address"], (
            "the Trade link href is wrong: %s" % rowInfo["tradeHref"])
        assert abs(rowInfo["symTop"] - rowInfo["nameTop"]) <= 2, (
            "the token symbol and name do not share one line box: symTop=%.1f nameTop=%.1f"
            % (rowInfo["symTop"], rowInfo["nameTop"]))
        assert url_before == url_after, (
            "clicking Copy navigated the page: %s -> %s" % (url_before, url_after))
        assert copyCalls == [ROW_NAME_ROW["address"]], (
            "clicking Copy did not write the row's address to the clipboard: %s" % copyCalls)
        assert copiedText == "Copied ✓", (
            "the copy button did not show the \"Copied ✓\" confirmation text: %r" % copiedText)
        assert not rerrs, "web/pairs.html threw during the rows probe: %s" % rerrs

        # همان کاوشِ Copy، این‌بار روی کارتِ موبایل (۳۹۰px) — card-link کلِ
        # کارت را می‌پوشاند، پس اگر card-actions یک stacking-context درست
        # بالاتر نداشته باشد، کلیک روی Copy/Trade به‌جایش به ناوبریِ کارت
        # می‌رسد؛ چیزی که در جدولِ دسکتاپ (ستون‌های جدا) هرگز رخ نمی‌داد.
        mpg = await b.new_page(viewport={"width": 390, "height": 844})
        merrs = []
        mpg.on("pageerror", lambda e: merrs.append(str(e)))
        await mpg.route("**/pairs.json**", lambda route: route.fulfill(
            status=200, content_type="application/json",
            body=_jsonPairs.dumps({"chain": "base", "rows": [ROW_NAME_ROW], "store": True})))
        await mpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await mpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await mpg.add_init_script("""
            window.__copyCalls = [];
            Object.defineProperty(navigator, 'clipboard', {
                value: { writeText: (t) => { window.__copyCalls.push(t); return Promise.resolve(); } },
                configurable: true
            });
        """)
        await mpg.goto("http://127.0.0.1:%d/pairs.html" % port)
        await mpg.wait_for_timeout(500)
        murl_before = mpg.url
        await mpg.click("#rowsCards .copy-btn")
        await mpg.wait_for_timeout(150)
        murl_after = mpg.url
        mCopyCalls = await mpg.evaluate("window.__copyCalls")
        await mpg.close()
        print("[pairs rows] mobile card copy: urlBefore=%s urlAfter=%s copyCalls=%s errors=%s"
              % (murl_before, murl_after, mCopyCalls, merrs))
        assert murl_before == murl_after, (
            "clicking Copy on the mobile CARD navigated the page (card-link painted over "
            "card-actions): %s -> %s" % (murl_before, murl_after))
        assert mCopyCalls == [ROW_NAME_ROW["address"]], (
            "clicking Copy on the mobile card did not write the address to the clipboard: %s"
            % mCopyCalls)
        assert not merrs, "web/pairs.html threw during the mobile-card copy probe: %s" % merrs

        print("[pairs rows] every row height <=56px at 1280px with a 40+ char name; the Trade link is "
              "exactly /app#swap?out=<address>; clicking Copy never navigates and writes the address "
              "to the clipboard, showing \"Copied ✓\" briefly (both the desktop row and the mobile "
              "card, where card-link covers the whole card); the token symbol and name share one "
              "line box")

        # ---- [pairs refresh] بازخوانیِ خودکار هر ۵ دقیقه — با ساعتِ درون‌ساختِ
        # Playwright؛ فیلتر/جست‌وجو باقی می‌مانند؛ شکستِ پس‌زمینه‌ای ردیف‌های
        # قدیمی را نگه می‌دارد. ----
        refresh_calls = {"n": 0}
        REFRESH_ROW = dict(SELL_ROW, address="0x" + "c1" * 20, symbol="REFA")
        REFRESH_ROW2 = dict(SELL_ROW, address="0x" + "c2" * 20, symbol="REFB")
        REFRESH_ROW3 = dict(SELL_ROW, address="0x" + "c3" * 20, symbol="REFC")

        async def stub_pairs_refresh(route):
            refresh_calls["n"] += 1
            n = refresh_calls["n"]
            if n == 1:
                body = {"chain": "base", "rows": [REFRESH_ROW, REFRESH_ROW2], "store": True}
                await route.fulfill(status=200, content_type="application/json", body=_jsonPairs.dumps(body))
            elif n == 2:
                # بازخوانیِ دومِ *موفق* — یک ردیفِ تازه هم می‌آورد که با
                # جست‌وجوی جاری نمی‌خورَد، تا معلوم شود واقعاً دادهٔ تازه
                # نشسته (نه فقط دوباره همان قبلی)، و جست‌وجو هنوز اعمال است.
                body = {"chain": "base", "rows": [REFRESH_ROW, REFRESH_ROW2, REFRESH_ROW3], "store": True}
                await route.fulfill(status=200, content_type="application/json", body=_jsonPairs.dumps(body))
            else:
                await route.abort()

        refpg = await b.new_page(viewport={"width": 1280, "height": 900})
        referrs = []
        refpg.on("pageerror", lambda e: referrs.append(str(e)))
        await refpg.route("**/pairs.json**", stub_pairs_refresh)
        await refpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await refpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await refpg.clock.install()
        await refpg.goto("http://127.0.0.1:%d/pairs.html" % port)
        await refpg.wait_for_timeout(500)
        await refpg.fill("#pairSearch", "REFA")
        await refpg.wait_for_timeout(150)
        calls_before = refresh_calls["n"]
        syms_before = await refpg.eval_on_selector_all(
            "#rowsBody .token-sym", "els => els.map(e => e.textContent.trim())")

        # بازخوانیِ اول (بعدِ ۵ دقیقه): موفق، دادهٔ تازه می‌آورد؛ جست‌وجو باید بماند.
        await refpg.clock.fast_forward(5 * 60 * 1000 + 1000)
        await refpg.wait_for_timeout(300)
        calls_after_success = refresh_calls["n"]
        syms_after_success = await refpg.eval_on_selector_all(
            "#rowsBody .token-sym", "els => els.map(e => e.textContent.trim())")
        search_after_success = await refpg.eval_on_selector("#pairSearch", "e => e.value")

        # بازخوانیِ دوم (۵ دقیقهٔ دیگر): ناموفق؛ ردیف‌های قدیمی و جست‌وجو باید بمانند.
        await refpg.clock.fast_forward(5 * 60 * 1000 + 1000)
        await refpg.wait_for_timeout(300)
        calls_after_fail = refresh_calls["n"]
        syms_after_fail = await refpg.eval_on_selector_all(
            "#rowsBody .token-sym", "els => els.map(e => e.textContent.trim())")
        search_after_fail = await refpg.eval_on_selector("#pairSearch", "e => e.value")
        await refpg.close()

        print("[pairs refresh] callsBefore=%s syms=%s -> afterSuccess: calls=%s syms=%s search=%r "
              "-> afterFail: calls=%s syms=%s search=%r errors=%s"
              % (calls_before, syms_before, calls_after_success, syms_after_success, search_after_success,
                 calls_after_fail, syms_after_fail, search_after_fail, referrs))
        assert calls_before == 1, "expected exactly 1 initial /pairs.json request, got %s" % calls_before
        assert syms_before == ["REFA"], (
            "the search filter was not applied before the refresh: %s" % syms_before)
        assert calls_after_success == 2, (
            "expected a second /pairs.json request after 5 minutes, got %s" % calls_after_success)
        assert search_after_success == "REFA", (
            "the search query box lost its value across a successful auto-refresh: %r"
            % search_after_success)
        assert syms_after_success == ["REFA"], (
            "a successful background refresh must keep the search filter applied to the new rows "
            "(REFC must stay hidden), got %s" % syms_after_success)
        assert calls_after_fail == 3, (
            "expected a third /pairs.json request after another 5 minutes, got %s" % calls_after_fail)
        assert search_after_fail == "REFA", (
            "the search query box lost its value across a failing auto-refresh: %r" % search_after_fail)
        assert syms_after_fail == ["REFA"], (
            "a failing background refresh must keep the old (filtered) rows, got %s" % syms_after_fail)
        assert not referrs, "web/pairs.html threw during the auto-refresh probe: %s" % referrs

        print("[pairs refresh] every 5 minutes (while visible) the page refetches /pairs.json, keeping "
              "the chain/filter/search/sort applied; a successful background refresh re-applies the "
              "search to the new rows and a failing one keeps the old rows — the search box's value "
              "survives both")

        # ---- [pairs wallet] چیپِ کیف‌پول در هدرِ pairs.html — ۲۳ سپتامبر، به
        # خواستِ مالک: حالا همان فلوی *کامل*ِ اتصالِ اپ است (EIP-6963
        # picker/WalletConnect)، عیناً همان idها: #connectBtn/#walletPop/
        # #walletAddr/#copyAddrBtn/#disconnectBtn. بازیابیِ بی‌صدا هنوز فقط
        # eth_accounts است، هرگز eth_requestAccounts روی لود. ----
        FAKE_ADDR = "0x1234567890abcdef1234567890abcdef12345678"
        FAKE_SHORT = FAKE_ADDR[:6] + "…" + FAKE_ADDR[-4:]

        def fake_provider_script(addr):
            return """
                window.__fakeMethods = [];
                (function(){
                    var __addr = %r;
                    var __provider = {
                        request: function(args){
                            window.__fakeMethods.push(args && args.method);
                            if (args && args.method === 'eth_accounts') return Promise.resolve([__addr]);
                            if (args && args.method === 'eth_requestAccounts') return Promise.resolve([__addr]);
                            return Promise.reject(new Error('unexpected method'));
                        }
                    };
                    window.addEventListener('eip6963:requestProvider', function(){
                        window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {
                            detail: { info: { name: 'Fake Wallet', rdns: 'test.fake', uuid: 'fake-1' },
                                      provider: __provider }
                        }));
                    });
                })();
            """ % (addr,)

        def fake_provider_throws_script():
            return """
                window.__fakeMethods = [];
                (function(){
                    var __provider = {
                        request: function(args){
                            window.__fakeMethods.push(args && args.method);
                            return Promise.reject(new Error('boom'));
                        }
                    };
                    window.addEventListener('eip6963:requestProvider', function(){
                        window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {
                            detail: { info: { name: 'Broken Wallet', rdns: 'test.broken', uuid: 'fake-2' },
                                      provider: __provider }
                        }));
                    });
                })();
            """

        async def open_wallet_page(init_script=None, viewport=None, color_scheme=None):
            kwargs = {"viewport": viewport or {"width": 1280, "height": 900}}
            if color_scheme:
                kwargs["color_scheme"] = color_scheme
            wpg = await b.new_page(**kwargs)
            werrs = []
            cerrs = []
            wpg.on("pageerror", lambda e: werrs.append(str(e)))
            wpg.on("console", lambda m: cerrs.append(m.text) if m.type == "error" else None)
            await wpg.route("**/pairs.json**", lambda route: route.fulfill(
                status=200, content_type="application/json",
                body=_jsonPairs.dumps({"chain": "base", "rows": [SELL_ROW], "store": True})))
            await wpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
            await wpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
            if init_script:
                await wpg.add_init_script(init_script)
            await wpg.goto("http://127.0.0.1:%d/pairs.html" % port)
            # ۴۰۰ میلی‌ثانیه‌ی مکثِ کشفِ ۶۹۶۳ + رفت‌وبرگشتِ eth_accounts
            await wpg.wait_for_timeout(700)
            return wpg, werrs, cerrs

        # ۱) بدونِ هیچ پروایدر و بدونِ هیچ کلید -> «Connect wallet»
        w1, werrs1, cerrs1 = await open_wallet_page()
        chip1_text = await w1.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        chip1_class = await w1.eval_on_selector("#connectBtn", "e => e.className")
        await w1.close()
        print("[pairs wallet] no provider/no keys: text=%r class=%r errors=%s consoleErrs=%s"
              % (chip1_text, chip1_class, werrs1, cerrs1))
        assert chip1_text == "Connect wallet", "wrong disconnected chip text: %r" % chip1_text
        assert chip1_class == "chip solid", (
            "the disconnected chip must be a .chip.solid, like the app's Connect wallet button: %r"
            % chip1_class)
        assert not werrs1 and not cerrs1, "errors on the no-provider load: %s %s" % (werrs1, cerrs1)

        # ۲) یک پروایدرِ ۶۹۶۳ که یک حساب اعلام می‌کند -> بازیابیِ بی‌صدا با
        # eth_accounts وصل می‌کند، هرگز eth_requestAccounts روی خودِ لود
        # ۱۱ اکتبر: بازیابیِ بی‌صدا فقط از والتی که کاربر برای Base انتخاب کرده؛ فیکسچر کلیدِ آن را هم دارد
        STORED_FAKE = "localStorage.setItem('zaexa.base.wallet','test.fake');"
        w2, werrs2, cerrs2 = await open_wallet_page(init_script=STORED_FAKE + fake_provider_script(FAKE_ADDR))
        chip2_text = await w2.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        chip2_class = await w2.eval_on_selector("#connectBtn", "e => e.className")
        await w2.click("#connectBtn")
        await w2.wait_for_timeout(100)
        pop2_addr = await w2.eval_on_selector("#walletAddr", "e => e.textContent.trim()")
        methods2 = await w2.evaluate("window.__fakeMethods")
        await w2.close()
        print("[pairs wallet] injected (silent restore): chipText=%r class=%r popoverAddr=%r "
              "methods=%s errors=%s consoleErrs=%s"
              % (chip2_text, chip2_class, pop2_addr, methods2, werrs2, cerrs2))
        assert chip2_text == FAKE_SHORT, "chip did not show the short address: %r" % chip2_text
        assert chip2_class == "chip", "the connected chip must be a plain .chip, like the app: %r" % chip2_class
        assert pop2_addr == FAKE_SHORT, "popover did not show the short address: %r" % pop2_addr
        # عیناً همان الگوی خودِ اپ: حلقه‌ی بازیابیِ بی‌صدا یک‌بار eth_accounts
        # می‌زند تا ببیند آیا اجازه هست، و روی جواب مثبت connectWithProvider
        # را صدا می‌زند که دوباره‌ی همان eth_accounts را می‌زند (هرگز
        # eth_requestAccounts) — پس اینجا دقیقاً همان دو فراخوان انتظار
        # می‌رود، نه یک‌بار.
        assert methods2 == ["eth_accounts", "eth_accounts"] and set(methods2) == {"eth_accounts"}, (
            "silent restore must only ever call eth_accounts, never eth_requestAccounts: %s" % methods2)
        assert not werrs2 and not cerrs2, "errors on the injected-provider load: %s %s" % (werrs2, cerrs2)

        # ۳) پرچمِ قطعِ محلی ست است، همان پروایدر هم حاضر است -> هیچ پروبی زده
        # نمی‌شود، پروایدر صفر درخواست می‌بیند (کوتاه‌مدار پیش از هرچیز)
        w3, werrs3, cerrs3 = await open_wallet_page(init_script=(
            "localStorage.setItem('zaexa.disconnected','1');" + fake_provider_script(FAKE_ADDR)))
        chip3_text = await w3.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        methods3 = await w3.evaluate("window.__fakeMethods")
        await w3.close()
        print("[pairs wallet] disconnected flag + provider present: chipText=%r methods=%s errors=%s "
              "consoleErrs=%s" % (chip3_text, methods3, werrs3, cerrs3))
        assert chip3_text == "Connect wallet", (
            "the disconnected flag did not short-circuit the chip: %r" % chip3_text)
        assert methods3 == [], (
            "the disconnected flag did not short-circuit BEFORE probing — the fake provider "
            "received requests: %s" % methods3)
        assert not werrs3 and not cerrs3, "errors on the disconnected-flag load: %s %s" % (werrs3, cerrs3)

        # ۴) کلیک روی Disconnect -> پرچم ست می‌شود، چیپ برمی‌گردد به
        # «Connect wallet»، متنِ دقیقِ زیرِ هدر یک‌بار ظاهر می‌شود
        w4, werrs4, cerrs4 = await open_wallet_page(init_script=STORED_FAKE + fake_provider_script(FAKE_ADDR))
        await w4.click("#connectBtn")
        await w4.wait_for_timeout(100)
        await w4.click("#disconnectBtn")
        await w4.wait_for_timeout(100)
        flag4 = await w4.evaluate("localStorage.getItem('zaexa.disconnected')")
        chip4_text = await w4.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        note4_count = await w4.eval_on_selector_all(
            "#walletDisconnectNote", "els => els.length")
        note4_hidden = await w4.eval_on_selector("#walletDisconnectNote", "e => e.hidden")
        await w4.close()
        print("[pairs wallet] disconnect click: flag=%r chipText=%r noteCount=%s noteHidden=%s "
              "errors=%s consoleErrs=%s"
              % (flag4, chip4_text, note4_count, note4_hidden, werrs4, cerrs4))
        assert flag4 == "1", "clicking Disconnect did not set localStorage zaexa.disconnected=1"
        assert chip4_text == "Connect wallet", (
            "the chip did not switch back to Connect wallet after Disconnect: %r" % chip4_text)
        assert note4_count == 1, "the disconnect note did not appear exactly once: %s" % note4_count
        assert note4_hidden is False, "the disconnect note is still hidden after Disconnect"
        assert not werrs4 and not cerrs4, "errors on the disconnect-click probe: %s %s" % (werrs4, cerrs4)

        # ۵) یک کلیدِ wc@2:…session… غیرخالی، بدونِ هیچ پروایدرِ تزریق‌شده —
        # بازیابیِ WalletConnect تلاش می‌کند، ولی این محیطِ تست شبکه‌ی بیرونی
        # ندارد (رله‌ی WalletConnect غیرِقابل‌دسترس است)، پس نباید هرگز به یک
        # خطای صفحه/کنسول بینجامد؛ چیپ همچنان «Connect wallet» می‌ماند.
        w5, werrs5, cerrs5 = await open_wallet_page(init_script=(
            "localStorage.setItem('wc@2:client:0.3//session', JSON.stringify({topic:'abc'}));"))
        chip5_text = await w5.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        await w5.close()
        print("[pairs wallet] wc session, no injected provider, no real relay reachable: "
              "chipText=%r errors=%s consoleErrs=%s" % (chip5_text, werrs5, cerrs5))
        assert chip5_text == "Connect wallet", (
            "with no injected provider and no reachable relay the chip must stay Connect wallet: %r"
            % chip5_text)
        assert not werrs5 and not cerrs5, "errors on the wc-session load: %s %s" % (werrs5, cerrs5)

        # ۶) پروایدری که eth_accounts در آن پرتاب می‌کند -> «Connect wallet»،
        # هیچ خطای کنسولی
        w6, werrs6, cerrs6 = await open_wallet_page(init_script=fake_provider_throws_script())
        chip6_text = await w6.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        await w6.close()
        print("[pairs wallet] throwing provider: chipText=%r errors=%s consoleErrs=%s"
              % (chip6_text, werrs6, cerrs6))
        assert chip6_text == "Connect wallet", (
            "a throwing provider should degrade to Connect wallet, got %r" % chip6_text)
        assert not werrs6, "a throwing provider must not become a page error: %s" % werrs6
        assert not cerrs6, "a throwing provider must not print a console error: %s" % cerrs6

        # ۷) کلیک روی Connect wallet وقتی قطع است -> انتخاب‌گر (#walletOv) باز
        # می‌شود؛ کلیک روی ردیفِ کیف‌پول eth_requestAccounts می‌زند و وصل
        # می‌کند — همان دوباره‌رفتاری که [pairs connect] هم می‌سنجد، اینجا با
        # فرضِ ساده‌ترِ «فقط یک والتِ تزریق‌شده».
        w7, werrs7, cerrs7 = await open_wallet_page(init_script=(
            "localStorage.setItem('zaexa.disconnected','1');" + fake_provider_script(FAKE_ADDR)))
        await w7.click("#connectBtn")
        await w7.wait_for_timeout(150)
        picker_open7 = await w7.evaluate("() => document.getElementById('walletOv').classList.contains('on')")
        await w7.click(".walRow")
        await w7.wait_for_timeout(150)
        chip7_text = await w7.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        disconnected7 = await w7.evaluate("() => localStorage.getItem('zaexa.disconnected')")
        methods7 = await w7.evaluate("window.__fakeMethods")
        await w7.close()
        print("[pairs wallet] explicit connect via picker: pickerOpen=%s chipText=%r "
              "disconnectedFlag=%r methods=%s errors=%s consoleErrs=%s"
              % (picker_open7, chip7_text, disconnected7, methods7, werrs7, cerrs7))
        assert picker_open7, "clicking Connect wallet while disconnected must open #walletOv"
        assert chip7_text == FAKE_SHORT, (
            "picking the fake wallet did not connect: %r" % chip7_text)
        assert disconnected7 is None, (
            "an explicit connect must clear zaexa.disconnected, got %r" % disconnected7)
        assert "eth_requestAccounts" in methods7, (
            "picking a wallet from the picker must call eth_requestAccounts: %s" % methods7)
        assert not werrs7 and not cerrs7, "errors on the explicit-connect probe: %s %s" % (werrs7, cerrs7)

        # ---- [pairs connect] همان کاوشگرِ ۷ بالا، دوباره اما با نامِ دقیقِ
        # خواسته‌شده در مشخصات (probe مستقل و ماندگار) + سنجشِ محتوای
        # #walletPop بعد از وصل‌شدن (باید Copy address و Disconnect داشته
        # باشد، عیناً مثلِ اپ). pairs هرگز زنجیره عوض نمی‌کند/تراکنش نمی‌فرستد؛
        # این کاوشگر فقط فلوی اتصال را می‌سنجد. ----
        w8, werrs8, cerrs8 = await open_wallet_page(init_script=(
            "localStorage.setItem('zaexa.disconnected','1');" + fake_provider_script(FAKE_ADDR)))
        await w8.click("#connectBtn")
        await w8.wait_for_timeout(150)
        picker_open8 = await w8.evaluate("() => document.getElementById('walletOv').classList.contains('on')")
        await w8.click(".walRow")
        await w8.wait_for_timeout(150)
        chip8_text = await w8.eval_on_selector("#connectBtn", "e => e.textContent.trim()")
        disconnected8 = await w8.evaluate("() => localStorage.getItem('zaexa.disconnected')")
        methods8 = await w8.evaluate("window.__fakeMethods")
        await w8.click("#connectBtn")
        await w8.wait_for_timeout(100)
        has_copy8 = await w8.evaluate("() => !!document.getElementById('copyAddrBtn')")
        has_disc8 = await w8.evaluate("() => !!document.getElementById('disconnectBtn')")
        addr8 = await w8.eval_on_selector("#walletAddr", "e => e.textContent.trim()")
        await w8.close()
        print("[pairs connect] pickerOpen=%s chipText=%r disconnectedFlag=%r methods=%s "
              "hasCopyBtn=%s hasDisconnectBtn=%s popoverAddr=%r errors=%s consoleErrs=%s"
              % (picker_open8, chip8_text, disconnected8, methods8, has_copy8, has_disc8, addr8,
                 werrs8, cerrs8))
        assert picker_open8, "[pairs connect] clicking Connect wallet must open #walletOv"
        assert chip8_text == FAKE_SHORT, "[pairs connect] picking the fake wallet did not connect"
        assert disconnected8 is None, "[pairs connect] explicit connect must clear zaexa.disconnected"
        assert "eth_requestAccounts" in methods8, (
            "[pairs connect] picking a wallet must call eth_requestAccounts")
        assert has_copy8 and has_disc8, (
            "[pairs connect] the connected #walletPop must have Copy address + Disconnect, like the app")
        assert addr8 == FAKE_SHORT, "[pairs connect] #walletAddr must show the shortened address"
        assert not werrs8 and not cerrs8, "[pairs connect] errors on the connect flow: %s %s" % (werrs8, cerrs8)

        print("[pairs wallet] disconnected/silently-restored/throwing states render the right chip; "
              "only eth_accounts is ever called on load and never after the disconnected flag is "
              "set; Disconnect sets the flag and shows the exact wording once; explicit Connect "
              "wallet opens the picker and eth_requestAccounts only fires on a picked row")

        import time as _time
        # ---- [sol carry] ۴ اکتبر — تأییدِ اتصالِ سولانا که *همین تب* داده، بین /app و
        # /pairs (دو سندِ جدا) تا ۳۰ دقیقه منتقل می‌شود: sessionStorage
        # (zaexa.solsession.v1)، نه localStorage؛ بازیابی فقط connect({silent:true})،
        # بدون امضای تازه و بدون رویدادِ /ev. هر شکستی رکورد را پاک می‌کند. ----
        CARRY_B58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
        def carry_b58(bs):
            n = int.from_bytes(bytes(bs), "big")
            out = ""
            while n:
                n, r = divmod(n, 58)
                out = CARRY_B58[r] + out
            return "1" * (len(bs) - len(bytes(bs).lstrip(b"\0"))) + out
        CARRY_PK = list(range(1, 33))
        CARRY_PK2 = list(range(2, 34))
        CARRY_ADDR = carry_b58(CARRY_PK)
        CARRY_ADDR2 = carry_b58(CARRY_PK2)
        CARRY_SHORT = CARRY_ADDR[:6] + "…" + CARRY_ADDR[-4:]
        CARRY_ORIGIN = "http://127.0.0.1:%d" % port
        CARRY_APP = CARRY_ORIGIN + "/app#swap?chain=solana"
        CARRY_PAIRS = CARRY_ORIGIN + "/pairs.html?chain=solana"
        CARRY_WALLET_INIT = """
(function(){
  var PK = new Uint8Array(__PK__), PK2 = new Uint8Array(__PK2__);
  var cfg = {}; try { cfg = JSON.parse(sessionStorage.getItem('t.cfg') || '{}'); } catch(_) {}
  window.__calls = []; window.__signs = 0; window.__confirmCalls = 0;
  // تأییدِ امضاشده در تست‌های مرورگر جعلی است؛ شمارنده ثابت می‌کند بازیابی هرگز آن را صدا نمی‌زند.
  window.SolConfirm = { confirmConnection: async function(){ window.__confirmCalls++; } };
  var w = { name: cfg.name || 'Fake Wallet', icon: '', chains: ['solana:mainnet'], features: {
    'standard:connect': { connect: async function(o){
      window.__calls.push(o || {});
      if (o && o.silent) {
        if (cfg.silent === 'throw') throw new Error('wallet locked');
        if (cfg.silent === 'none') return { accounts: [] };
        if (cfg.silent === 'other') return { accounts: [{ address: '__ADDR2__', publicKey: PK2 }] };
      }
      return { accounts: [{ address: '__ADDR__', publicKey: PK }] };
    } },
    'standard:disconnect': { disconnect: async function(){} },
    'standard:events': { on: function(ev, cb){ window.__evCb = cb; return function(){}; } },
    'solana:signMessage': { signMessage: async function(){ window.__signs++; throw new Error('no signing during restore'); } },
    'solana:signAndSendTransaction': { signAndSendTransaction: async function(){ return [{ signature: new Uint8Array(64) }]; } }
  } };
  if (cfg.late) setTimeout(function(){
    window.dispatchEvent(new CustomEvent('wallet-standard:register-wallet', { detail: function(api){ api.register(w); } }));
  }, cfg.late);
  else window.addEventListener('wallet-standard:app-ready', function(e){ try { e.detail.register(w); } catch(_) {} });
})();
""".replace("__PK__", str(CARRY_PK)).replace("__PK2__", str(CARRY_PK2)).replace("__ADDR__", CARRY_ADDR).replace("__ADDR2__", CARRY_ADDR2)

        async def carry_page(errs):
            cpg = await b.new_page(viewport={"width": 1280, "height": 900})
            cpg.on("console", lambda m: errs.append(m.text) if m.type == "error" and (m.location.get("url") or "").startswith(CARRY_ORIGIN) else None)
            cpg.on("pageerror", lambda e: errs.append("PAGEERROR " + str(e)))
            cpg.ev_log = []
            await cpg.add_init_script(CARRY_WALLET_INIT)
            async def c_ext(route): await route.abort()
            async def c_empty(route): await route.fulfill(status=200, content_type="application/json", body='{"data":[]}')
            async def c_ev(route):
                cpg.ev_log.append(route.request.post_data or route.request.url)
                await route.fulfill(status=204, body="")
            async def c_vd(route): await route.fulfill(status=200, content_type="application/json", body='{"v":"sell","ms":100}')
            async def c_sol(route): await route.fulfill(status=200, content_type="application/json", body='{"result":null}')
            async def c_pairs(route):
                ch = "solana" if "chain=solana" in route.request.url else "base"
                await route.fulfill(status=200, content_type="application/json",
                                    body=_json.dumps({"chain": ch, "rows": [], "store": True}))
            await cpg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(CARRY_ORIGIN) else c_ext(r))
            await cpg.route("**/gt/**", c_empty)
            await cpg.route("**/ev", c_ev)
            await cpg.route("**/vd/**", c_vd)
            await cpg.route("**/sol/**", c_sol)
            await cpg.route("**/pairs.json**", c_pairs)
            return cpg

        async def carry_seed(cpg, cfg=None, rec=None, off=False):
            # یک سندِ هم‌مبدأِ خالی؛ فقط برای نوشتنِ sessionStorage/localStorage پیش از صفحه‌ی اصلی
            await cpg.goto(CARRY_ORIGIN + "/stub-ethers.js")
            await cpg.evaluate("""([cfg, rec, off]) => { sessionStorage.clear(); localStorage.clear();
                if (cfg) sessionStorage.setItem('t.cfg', JSON.stringify(cfg));
                if (rec) sessionStorage.setItem('zaexa.solsession.v1', JSON.stringify(rec));
                if (off) localStorage.setItem('zaexa.solwallet.off.v1', '1'); }""", [cfg, rec, off])

        async def carry_state(cpg):
            st = await cpg.evaluate("""() => { const rec = sessionStorage.getItem('zaexa.solsession.v1');
                const n = document.getElementById('walletDisconnectNote'), sn = document.getElementById('solNotices');
                return { calls: window.__calls, signs: window.__signs, confirms: window.__confirmCalls, rec: rec,
                  lsHasRec: Object.keys(localStorage).some(k => k.indexOf('solsession') >= 0) ||
                            Object.values(localStorage).some(v => String(v).indexOf('solsession') >= 0),
                  btn: document.getElementById('connectBtn').textContent.trim(),
                  note: ((n && !n.hidden) ? n.textContent : '') + ((sn && sn.textContent) || '') }; }""")
            st["recObj"] = _json.loads(st["rec"]) if st["rec"] else None
            st["wcOn"] = [e for e in cpg.ev_log if "wallet:on" in e]
            return st

        async def carry_load(cpg, url):
            same = cpg.url.split("#")[0] == url.split("#")[0]
            await cpg.goto(url)
            if same:      # همان سند با هش: goto فقط هش را عوض می‌کند، پس بازبارگذاریِ واقعی لازم است
                await cpg.reload()
            await cpg.wait_for_timeout(1000)

        async def carry_connect(cpg, kind):
            await cpg.click("#connectBtn")
            await cpg.wait_for_timeout(400)
            await cpg.click("#solWalList .walRow[data-i]" if kind == "app" else "#walList .walRow")
            await cpg.wait_for_timeout(700)

        carry_errs = []
        CARRY_NOW = lambda: int(_time.time() * 1000)

        def carry_rec(t=None, name="Fake Wallet", addr=None):
            return {"name": name, "address": addr or CARRY_ADDR, "t": t if t is not None else CARRY_NOW()}

        # 1) app: fresh approval writes the record (sessionStorage only), then a reload restores silently
        cpg = await carry_page(carry_errs)
        await carry_seed(cpg)
        await carry_load(cpg, CARRY_APP)
        s1 = await carry_state(cpg)
        assert s1["calls"] == [] and s1["btn"] != CARRY_SHORT and s1["rec"] is None, "[sol carry] a fresh page must start disconnected: %s" % s1
        await carry_connect(cpg, "app")
        s2 = await carry_state(cpg)
        print("[sol carry app] connect: calls=%s confirms=%s rec=%s btn=%r lsHasRec=%s"
              % (s2["calls"], s2["confirms"], s2["recObj"], s2["btn"], s2["lsHasRec"]))
        assert s2["calls"] == [{"silent": False}] and s2["confirms"] == 1 and s2["btn"] == CARRY_SHORT, "[sol carry] app connect flow: %s" % s2
        assert s2["recObj"] and s2["recObj"]["name"] == "Fake Wallet" and s2["recObj"]["address"] == CARRY_ADDR \
            and abs(s2["recObj"]["t"] - CARRY_NOW()) < 15000, "[sol carry] the approval was not recorded for this tab: %s" % s2["rec"]
        assert not s2["lsHasRec"], "[sol carry] the session record must never be written to localStorage"
        assert len(s2["wcOn"]) == 1, "[sol carry] the fresh connection must fire wallet:on once (probe sanity): %s" % cpg.ev_log
        t_before = s2["recObj"]["t"]
        await cpg.wait_for_timeout(50)
        await carry_load(cpg, CARRY_APP)
        s3 = await carry_state(cpg)
        print("[sol carry app] reload: calls=%s signs=%s confirms=%s btn=%r tRefreshed=%s wallet:on=%d"
              % (s3["calls"], s3["signs"], s3["confirms"], s3["btn"], s3["recObj"] and s3["recObj"]["t"] >= t_before, len(s3["wcOn"])))
        assert s3["calls"] == [{"silent": True}], "[sol carry] reload must make exactly one silent connect call: %s" % s3["calls"]
        assert s3["signs"] == 0 and s3["confirms"] == 0, "[sol carry] restore must never ask for a signature: %s" % s3
        assert s3["btn"] == CARRY_SHORT, "[sol carry] the header must show the short address after restore: %r" % s3["btn"]
        assert s3["recObj"] and s3["recObj"]["t"] >= t_before, "[sol carry] a successful restore must refresh t"
        assert not s3["lsHasRec"] and len(s3["wcOn"]) == len(s2["wcOn"]), "[sol carry] restore leaked into localStorage or fired wallet:on"
        # 2) app -> pairs (same tab, full page load)
        await carry_load(cpg, CARRY_PAIRS)
        s4 = await carry_state(cpg)
        print("[sol carry pairs] from app: calls=%s signs=%s confirms=%s btn=%r note=%r"
              % (s4["calls"], s4["signs"], s4["confirms"], s4["btn"], s4["note"]))
        assert s4["calls"] == [{"silent": True}] and s4["signs"] == 0 and s4["confirms"] == 0 and s4["btn"] == CARRY_SHORT, \
            "[sol carry] app -> pairs must stay connected with one silent call and no signature: %s" % s4
        # explicit Disconnect on pairs removes the record; reload stays disconnected with no connect call
        await cpg.evaluate("document.getElementById('disconnectBtn').click()")
        await cpg.wait_for_timeout(300)
        s5 = await carry_state(cpg)
        await carry_load(cpg, CARRY_PAIRS)
        s6 = await carry_state(cpg)
        print("[sol carry pairs] disconnect: recAfter=%s reload calls=%s btn=%r" % (s5["rec"], s6["calls"], s6["btn"]))
        assert s5["rec"] is None, "[sol carry] pairs Disconnect must remove the session record"
        assert s6["calls"] == [] and s6["btn"] != CARRY_SHORT, "[sol carry] after Disconnect a reload must stay disconnected with no connect call: %s" % s6
        # 3) pairs: fresh approval -> record -> app restores
        await carry_connect(cpg, "pairs")
        s7 = await carry_state(cpg)
        print("[sol carry pairs] connect: calls=%s rec=%s btn=%r lsHasRec=%s" % (s7["calls"], s7["recObj"], s7["btn"], s7["lsHasRec"]))
        assert s7["calls"] == [{"silent": False}] and s7["btn"] == CARRY_SHORT, "[sol carry] pairs connect flow: %s" % s7
        assert s7["recObj"] and s7["recObj"]["address"] == CARRY_ADDR and s7["recObj"]["name"] == "Fake Wallet" and not s7["lsHasRec"], \
            "[sol carry] pairs must record the approval in sessionStorage only: %s" % s7
        await carry_load(cpg, CARRY_APP)
        s8 = await carry_state(cpg)
        print("[sol carry app] from pairs: calls=%s signs=%s confirms=%s btn=%r" % (s8["calls"], s8["signs"], s8["confirms"], s8["btn"]))
        assert s8["calls"] == [{"silent": True}] and s8["signs"] == 0 and s8["confirms"] == 0 and s8["btn"] == CARRY_SHORT, \
            "[sol carry] pairs -> app must stay connected with one silent call and no signature: %s" % s8
        # app explicit Disconnect
        await cpg.evaluate("document.getElementById('solDisconnectBtn').click()")
        await cpg.wait_for_timeout(300)
        s9 = await carry_state(cpg)
        await carry_load(cpg, CARRY_APP)
        s10 = await carry_state(cpg)
        print("[sol carry app] disconnect: recAfter=%s reload calls=%s btn=%r" % (s9["rec"], s10["calls"], s10["btn"]))
        assert s9["rec"] is None, "[sol carry] app Disconnect must remove the session record"
        assert s10["calls"] == [] and s10["btn"] != CARRY_SHORT, "[sol carry] after app Disconnect a reload must stay disconnected, no connect call: %s" % s10
        await cpg.close()

        # 4) failure / refusal matrix, on both pages
        for kind, url in (("app", CARRY_APP), ("pairs", CARRY_PAIRS)):
            cases = [
                ("other address", {"silent": "other"}, carry_rec(), False, [{"silent": True}], True),
                ("locked wallet throws", {"silent": "throw"}, carry_rec(), False, [{"silent": True}], True),
                ("no account returned", {"silent": "none"}, carry_rec(), False, [{"silent": True}], True),
                ("record older than 30 min", {}, carry_rec(CARRY_NOW() - 31 * 60 * 1000), False, [], False),
                ("OFF flag set", {}, carry_rec(), True, [], False),
                ("WalletConnect record", {"name": "WalletConnect Solana"}, carry_rec(name="WalletConnect Solana"), False, [], False),
            ]
            for label, cfg, rec, off, want_calls, want_removed in cases:
                cpg = await carry_page(carry_errs)
                await carry_seed(cpg, cfg, rec, off)
                await carry_load(cpg, url)
                st = await carry_state(cpg)
                await cpg.close()
                print("[sol carry %s] %s: calls=%s btn=%r recLeft=%s note=%r"
                      % (kind, label, st["calls"], st["btn"], st["rec"] is not None, st["note"]))
                assert st["calls"] == want_calls, "[sol carry] %s/%s: connect calls %s, wanted %s" % (kind, label, st["calls"], want_calls)
                assert st["btn"] != CARRY_SHORT and "Approve" not in st["btn"] and "…" not in st["btn"], \
                    "[sol carry] %s/%s must stay disconnected: %r" % (kind, label, st["btn"])
                assert not any(c.get("silent") is False for c in st["calls"]), "[sol carry] restore must never prompt"
                assert st["note"].strip() == "", "[sol carry] %s/%s must show no notice: %r" % (kind, label, st["note"])
                if want_removed:
                    assert st["rec"] is None, "[sol carry] %s/%s: a failed restore must remove the record" % (kind, label)
            # a wallet that registers *after* the page code ran still restores
            cpg = await carry_page(carry_errs)
            await carry_seed(cpg, {"late": 300}, carry_rec(), False)
            await carry_load(cpg, url)
            st = await carry_state(cpg)
            await cpg.close()
            print("[sol carry %s] late wallet registration: calls=%s btn=%r" % (kind, st["calls"], st["btn"]))
            assert st["calls"] == [{"silent": True}] and st["btn"] == CARRY_SHORT, "[sol carry] %s: a late-registering wallet must restore too: %s" % (kind, st)

        # 5) wallet drops the account -> record removed (change event)
        cpg = await carry_page(carry_errs)
        await carry_seed(cpg, {}, carry_rec(), False)
        await carry_load(cpg, CARRY_PAIRS)
        await cpg.evaluate("window.__evCb({accounts: []})")
        await cpg.wait_for_timeout(300)
        st = await carry_state(cpg)
        print("[sol carry pairs] wallet drops account: recLeft=%s btn=%r" % (st["rec"] is not None, st["btn"]))
        assert st["rec"] is None and st["btn"] != CARRY_SHORT, "[sol carry] a change event dropping the account must remove the record: %s" % st
        await carry_seed(cpg, {}, carry_rec(), False)
        await carry_load(cpg, CARRY_APP)
        await cpg.evaluate("window.__evCb({accounts: []})")
        await cpg.wait_for_timeout(300)
        st = await carry_state(cpg)
        print("[sol carry app] wallet drops account: recLeft=%s btn=%r" % (st["rec"] is not None, st["btn"]))
        assert st["rec"] is None and st["btn"] != CARRY_SHORT, "[sol carry] a change event dropping the account must remove the record: %s" % st
        await cpg.close()

        # 6) chain continuity: pairs on Solana carries ?chain=solana to the /app nav links, Base keeps them plain
        cpg = await carry_page(carry_errs)
        await carry_seed(cpg)
        LINKS = """() => Array.from(document.querySelectorAll('a[href^="/app#"]')).filter(a => !a.classList.contains('trade-btn'))
            .map(a => a.getAttribute('href')).filter(h => /^\\/app#(swap|folio|flow)/.test(h))"""
        await carry_load(cpg, CARRY_PAIRS)
        sol_links = await cpg.evaluate(LINKS)
        await cpg.click("#chainTabs button[data-chain=base]")
        await cpg.wait_for_timeout(300)
        base_links = await cpg.evaluate(LINKS)
        await cpg.click("#chainTabs button[data-chain=solana]")
        await cpg.wait_for_timeout(300)
        back_links = await cpg.evaluate(LINKS)
        await carry_load(cpg, CARRY_ORIGIN + "/pairs.html")
        base_load_links = await cpg.evaluate(LINKS)
        await cpg.close()
        print("[sol carry pairs] nav links solana=%s base=%s back=%s plainLoad=%s" % (sol_links, base_links, back_links, base_load_links))
        want_sol = ["/app#swap?chain=solana", "/app#folio?chain=solana", "/app#flow?chain=solana"]
        assert sol_links and all(h in want_sol for h in sol_links) and set(sol_links) == set(want_sol), "[sol carry] Solana tab: /app links must carry ?chain=solana: %s" % sol_links
        assert base_links and all(h in ("/app#swap", "/app#folio", "/app#flow") for h in base_links), "[sol carry] Base tab: /app links must be plain: %s" % base_links
        assert back_links == sol_links and base_load_links == base_links, "[sol carry] links must follow the chain switch both ways"
        assert not carry_errs, "[sol carry] console errors: %s" % carry_errs
        print("[sol carry] session-scoped carry-over verified on /app and /pairs: record only in sessionStorage, silent:true once, "
              "same-address check, 30-minute window, OFF flag, WalletConnect excluded, failure/Disconnect/change clear the record, no signature, no /ev")

        # ---- [sol flow2] / [sol flash] / [sol budget] ۵ اکتبر — چهار گزارشِ مالک ----
        # ۱) Money Flow سولانا: استخرِ درست (حجمِ ۲۴ساعته، نه ذخیره‌ی جعلی) و چیدمانِ عینِ Base؛
        # ۲) معرفیِ «Choose a Solana token» حینِ بارگذاریِ توکنِ پیش‌فرض نباید پدیدار شود؛
        # ۳) دکمه‌ی کیف‌پولِ هدر بینِ صفحه‌ها «Connect wallet» نشان ندهد؛
        # ۴) SOL ناکافی هرگز «Swap anyway» نمی‌شود.
        SF_USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"
        sf_b58 = lambda lo: carry_b58(list(range(lo, lo + 32)))
        SF_POOL_APT, SF_POOL_SOL, SF_POOL_JUNK = sf_b58(10), sf_b58(20), sf_b58(30)
        SF_WHO_A, SF_WHO_B = sf_b58(40), sf_b58(41)
        sf_sig = lambda n: carry_b58(list(range(n, n + 64)))

        # ۵ اکتبر (r10) — GeckoTerminal در صفاتِ استخر برای هر پنجره عددِ دقیقِ کلِ استخر می‌دهد:
        # volume_usd و price_change_percentage رشته‌اند، transactions عددی (همان شکلِ واقعی).
        SF_WIN = {
            "m5":  ("412345.6",   120,   80,   90,   60, "0.12"),
            "m15": ("1250000.4",  380,  250,  260,  170, "-0.31"),
            "h1":  ("5100000.9", 1500, 1100,  800,  600, "0.85"),
            "h6":  ("28750000.2", 8200, 7300, 3100, 2900, "-2.40"),
            "h24": ("98400000.7", 31000, 29000, 9000, 8800, "4.75"),
        }
        def sf_windows(win=None):
            win = SF_WIN if win is None else win
            vol, tx, pc = {}, {}, {}
            for k, v in win.items():
                if v is None:
                    continue
                vol[k] = v[0]; tx[k] = {"buys": v[1], "sells": v[2], "buyers": v[3], "sellers": v[4]}; pc[k] = v[5]
            return {"volume_usd": vol, "transactions": tx, "price_change_percentage": pc}

        def sf_pool(addr, name, reserve, vol, mint=SF_USDC, win=False):
            attrs = {"address": addr, "name": name, "reserve_in_usd": str(reserve), "volume_usd": {"h24": str(vol)}}
            if win is not False:                 # None = فیکسچرِ کاملِ SF_WIN؛ dict = پنجره‌های دلخواه (کلیدِ غایب = صفتِ غایب)
                attrs.update(sf_windows(win))
            return {"id": "solana_" + addr, "attributes": attrs,
                    "relationships": {"base_token": {"data": {"id": "solana_" + mint, "type": "token"}},
                                      "quote_token": {"data": {"id": "solana_" + SOL_MINT_ADDR, "type": "token"}}}}

        def sf_trades_body():
            now_s = _time.time()
            def iso(mins):
                return _time.strftime("%Y-%m-%dT%H:%M:%SZ", _time.gmtime(now_s - mins * 60))
            def row(i, mins, buy, usd, who):
                return {"id": "sf-%d" % i, "attributes": {
                    "block_timestamp": iso(mins),
                    "from_token_address": SOL_MINT_ADDR if buy else SF_USDC,
                    "to_token_address": SF_USDC if buy else SOL_MINT_ADDR,
                    "volume_in_usd": usd, "tx_from_address": who, "tx_hash": sf_sig(i + 1)}}
            return {"data": [row(1, 5, True, "1200.4", SF_WHO_A), row(2, 10, True, "450.5", SF_WHO_B),
                             row(3, 20, True, "8000", SF_WHO_A), row(4, 15, False, "3000", SF_WHO_B),
                             row(5, 180, True, "100000", SF_WHO_B), row(6, 200, False, "2500", SF_WHO_A)]}

        SF_POOLS_MAIN = {"data": [
            sf_pool(SF_POOL_APT, "APT / USDC", 5_000_000, 10),
            sf_pool(SF_POOL_SOL, "SOL / USDC", 3_000_000, 9_000_000, win=None),
            sf_pool(SF_POOL_JUNK, "JUNK / USDC", 500, 1e9)]}

        SF_INTRO_WATCH = """
(function(){ window.__introSeen = false;
  new MutationObserver(function(rs){ rs.forEach(function(r){
    var t = r.target, el = t && (t.nodeType === 1 ? t : t.parentNode);
    if (!el || !el.closest || !el.closest('#flowBody')) return;
    var nodes = Array.prototype.slice.call(r.addedNodes); if (r.type === 'characterData') nodes.push(r.target);
    nodes.forEach(function(n){ if ((n.textContent || '').indexOf('Choose a Solana token') >= 0) window.__introSeen = true; });
  }); }).observe(document, {subtree: true, childList: true, characterData: true});
})();
"""

        async def sf_page(w=1440, h=900, scheme="light", hash_="#flow?chain=solana", pools=None,
                          pools_requests=None, trades_requests=None, delay=0.0, intro_watch=False, errs=None,
                          path="/app", init=None, rpc=None, multi=None, vd='{"v":"sell","ms":100}'):
            spg = await b.new_page(viewport={"width": w, "height": h}, color_scheme=scheme)
            if errs is not None:
                spg.on("console", lambda m: errs.append(m.text) if m.type == "error" and (m.location.get("url") or "").startswith(CARRY_ORIGIN) else None)
                spg.on("pageerror", lambda e: errs.append("PAGEERROR " + str(e)))
            if intro_watch:
                await spg.add_init_script(SF_INTRO_WATCH)
            for script_ in (init or []):
                await spg.add_init_script(script_)
            async def s_ext(route): await route.abort()
            async def s_ok(route, body='{"data":[]}'):
                await route.fulfill(status=200, content_type="application/json", body=body)
            async def s_gt(route):
                u = route.request.url.split("?")[0]
                if delay:
                    await asyncio.sleep(delay)
                if u.endswith("/trades") and "/pools/" in u:
                    if trades_requests is not None:
                        trades_requests.append(u.split("/pools/")[1].split("/")[0])
                    await s_ok(route, _json.dumps(sf_trades_body()))
                elif u.endswith("/pools") and "/tokens/" in u:
                    if pools_requests is not None:
                        pools_requests.append(u)
                    await s_ok(route, _json.dumps(pools if pools is not None else SF_POOLS_MAIN))
                elif "/tokens/multi/" in u:
                    await s_ok(route, _json.dumps(multi) if multi is not None else '{"data":[]}')
                elif "/tokens/" in u:
                    await s_ok(route, _json.dumps({"data": {"attributes": {"name": "USD Coin", "symbol": "USDC", "decimals": 6, "price_usd": "1"}}}))
                else:
                    await s_ok(route)
            async def s_ev(route): await route.fulfill(status=204, body="")
            async def s_vd(route): await s_ok(route, vd)
            async def s_sol(route):
                if rpc is not None and route.request.url.split("?")[0].endswith("/rpc"):
                    pl = _json.loads(route.request.post_data or "{}")
                    await s_ok(route, _json.dumps({"result": rpc(pl.get("method"), pl.get("params"))}))
                else:
                    await s_ok(route, '{"result":null}')
            async def s_pairs(route):
                await s_ok(route, _json.dumps({"chain": "solana", "rows": [], "store": True}))
            await spg.route("**/*", lambda r: r.continue_() if r.request.url.startswith(CARRY_ORIGIN) else s_ext(r))
            await spg.route("**/gt/**", s_gt)
            await spg.route("**/ev", s_ev)
            await spg.route("**/vd/**", s_vd)
            await spg.route("**/sol/**", s_sol)
            await spg.route("**/pairs.json**", s_pairs)
            await spg.goto(CARRY_ORIGIN + path + hash_)
            return spg

        sf_errs = []
        # ---- [sol flow2] انتخابِ استخر: حجمِ ۲۴ساعته، ذخیره‌ی زیر ۱۰۰۰ دلار کنار ----
        sf_tr, sf_pr = [], []
        spg = await sf_page(trades_requests=sf_tr, pools_requests=sf_pr, errs=sf_errs)
        await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
        sf_pool_txt = await spg.inner_text("#flowBody")
        await spg.close()
        print("[sol flow2 pool] trades requested from %s (SOL/USDC=%s) pool row=%r"
              % (sf_tr, SF_POOL_SOL, [l for l in sf_pool_txt.split("\n") if "USDC" in l][:1]))
        assert sf_tr and set(sf_tr) == {SF_POOL_SOL}, \
            "[sol flow2] the busiest real pool (by 24h volume, reserve >= $1000) must supply the trades, got %s" % sf_tr
        assert "SOL / USDC" in sf_pool_txt and "APT" not in sf_pool_txt and "JUNK" not in sf_pool_txt, \
            "[sol flow2] the Pool row must name the chosen pool: %r" % sf_pool_txt

        # اگر هیچ استخری ۱۰۰۰ دلار ذخیره نداشت، همان مرتب‌سازیِ قدیمیِ ذخیره
        sf_tr2 = []
        sf_low = {"data": [sf_pool(SF_POOL_APT, "APT / USDC", 400, 900_000), sf_pool(SF_POOL_SOL, "SOL / USDC", 900, 5),
                           sf_pool(SF_POOL_JUNK, "JUNK / USDC", 100, 1e9)]}
        spg = await sf_page(trades_requests=sf_tr2, pools=sf_low, errs=sf_errs)
        await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
        await spg.close()
        print("[sol flow2 pool] every pool under $1000 reserve -> fallback to reserve sort: %s" % sf_tr2)
        assert set(sf_tr2) == {SF_POOL_SOL}, "[sol flow2] with no real pool the old reserve sort must apply, got %s" % sf_tr2

        # ---- [sol flow2] چیدمان: همان اجزا و ترتیبِ Base، بدونِ <h3>، لینک‌ها tx3، داخلِ کارت ----
        SF_MEASURE = """() => {
          const body = document.getElementById('flowBody'), card = body.closest('.card');
          const cs = getComputedStyle(card), cr = card.getBoundingClientRect();
          const inner = { l: cr.left + parseFloat(cs.borderLeftWidth) + parseFloat(cs.paddingLeft),
                          r: cr.right - parseFloat(cs.borderRightWidth) - parseFloat(cs.paddingRight) };
          const probe = document.createElement('i'); probe.style.color = 'var(--tx3)'; document.body.appendChild(probe);
          const tx3 = getComputedStyle(probe).color; probe.remove();
          const out = [];
          body.querySelectorAll('*').forEach(el => { const r = el.getBoundingClientRect();
            if (r.width && (r.left < inner.l - 1 || r.right > inner.r + 1)) out.push(el.tagName + '.' + el.className + ':' + Math.round(r.left) + '-' + Math.round(r.right)); });
          return { h3: body.querySelectorAll('h3').length,
                   keys: Array.from(body.querySelectorAll('.flowkv .k')).map(e => e.textContent.trim()),
                   hdr: Array.from(body.querySelectorAll('.frow')).map(e => e.textContent.replace(/\\s+/g, ' ').trim()),
                   links: Array.from(body.querySelectorAll('a')).map(a => ({ t: a.textContent.trim(), c: getComputedStyle(a).color, u: getComputedStyle(a).textDecorationLine })),
                   tx3: tx3, outside: out, trades: body.querySelectorAll('.trade').length, notes: body.querySelectorAll('.fnote').length,
                   cap: !!body.querySelector('.flowbarCap'), bar: !!body.querySelector('.flowbar'),
                   text: body.innerText.replace(/\\s+/g, ' ') };
        }"""
        for sf_w, sf_h in ((1440, 900), (390, 844)):
            spg = await sf_page(w=sf_w, h=sf_h, errs=sf_errs)
            await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
            m1 = await spg.evaluate(SF_MEASURE)
            await spg.click('#flowTfs [data-w="h6"]')
            await spg.wait_for_function("() => document.getElementById('flowBody').innerText.includes('28,750,000')", timeout=15000)
            m6 = await spg.evaluate(SF_MEASURE)
            await spg.close()
            for tag, m in (("1H", m1), ("6H", m6)):
                print("[sol flow2 layout %dpx %s] h3=%d keys=%s hdr=%s links=%d outside=%s trades=%d fnotes=%d"
                      % (sf_w, tag, m["h3"], m["keys"], m["hdr"][:1], len(m["links"]), m["outside"], m["trades"], m["notes"]))
                assert m["h3"] == 0, "[sol flow2] %s: no <h3> may appear inside the flow card (Base has none)" % tag
                # r10: ردیف‌ها حالا مجموع‌های دقیقِ استخر در پنجره‌اند (حجم/خرید/فروش/قیمت)، نه جمعِ نمونه‌ی ۳۰۰تایی
                assert m["keys"] == ["Volume", "Buys", "Sells", "Price", "Pool"], "[sol flow2] %s: rows must be the window totals: %s" % (tag, m["keys"])
                assert m["cap"] and m["bar"] and "Buys" in m["text"] and "Sells" in m["text"], "[sol flow2] %s: flowbar + caption missing" % tag
                assert any(h.startswith("Largest buys") and "sender address" in h for h in m["hdr"]), \
                    "[sol flow2] %s: the 'Largest buys' header row is missing: %s" % (tag, m["hdr"])
                assert 1 <= m["trades"] <= 5, "[sol flow2] %s: trade rows: %d" % (tag, m["trades"])
                assert m["links"] and all(l["c"] == m["tx3"] for l in m["links"]), \
                    "[sol flow2] %s: every link inside the card must use var(--tx3), not the browser blue: %s (tx3=%s)" % (tag, m["links"], m["tx3"])
                assert not m["outside"], "[sol flow2] %s: elements extend outside the card padding box: %s" % (tag, m["outside"])
                assert m["notes"] == 1 and "flow, not a forecast" in m["text"] and "totals for this pool over the selected window" in m["text"], \
                    "[sol flow2] %s: exactly one closing note expected: notes=%d" % (tag, m["notes"])
                assert "Top buyers" not in m["text"] and "Top sellers" not in m["text"] and "Recent-trade sample" not in m["text"], \
                    "[sol flow2] %s: old sections/notes must be gone" % tag
            print("[sol flow2 layout %dpx] Base-identical row set and order, no <h3>, all %d links tx3-coloured, nothing outside the card" % (sf_w, len(m6["links"])))

        # ---- [sol flow2] پنجره‌ی ۱ساعته و ۶ساعته: مجموع‌ها از صفاتِ استخر، «Largest buys» از نمونه‌ی معاملات ----
        spg = await sf_page(errs=sf_errs)
        await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
        w1 = await spg.inner_text("#flowBody")
        await spg.click('#flowTfs [data-w="h6"]')
        await spg.wait_for_function("() => document.getElementById('flowBody').innerText.includes('28,750,000')", timeout=15000)
        w6 = await spg.inner_text("#flowBody")
        await spg.close()
        w1f, w6f = " ".join(w1.split()), " ".join(w6.split())
        print("[sol flow2 window] 1H=%r" % w1f[:150])
        print("[sol flow2 window] 6H=%r" % w6f[:150])
        assert "Volume $5,100,001" in w1f and "Buys 1,500" in w1f and "Sells 1,100" in w1f and "+0.85%" in w1f, \
            "[sol flow2] 1H window numbers wrong: %r" % w1f
        assert "Volume $28,750,000" in w6f and "Buys 8,200" in w6f and "Sells 7,300" in w6f and "−2.40%" in w6f, \
            "[sol flow2] 6H window numbers wrong: %r" % w6f
        assert "×2" in w1f, "[sol flow2] the repeated buyer must carry the ×N tag"
        assert "$100,000" not in w1f and "$100,000" in w6f, \
            "[sol flow2] Largest buys must be filtered to the window: the 3h-old $100,000 buy belongs to 6H only"

        # ---- [sol flow3] r10 — پنجره‌ها = مجموع‌های دقیقِ استخر (صفاتِ GeckoTerminal) ----
        # ۱H و ۶H قبلاً یکی بودند چون هر دو از «آخرین ≤۳۰۰ معامله» فیلتر می‌شدند (برای SOL/USDC فقط ۱–۲ دقیقه).
        sf3_pr, sf3_tr = [], []
        spg = await sf_page(pools_requests=sf3_pr, trades_requests=sf3_tr, errs=sf_errs)
        await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
        await spg.wait_for_timeout(500)
        # ⚠️ gtJson خودش کشِ ۶۰ثانیه‌ای (و ۱۰دقیقه‌ای برای استخرها) دارد؛ پس شمردنِ درخواستِ شبکه نمی‌تواند «دوباره گرفتن»
        # را ببیند. شمارنده روی خودِ gtJson می‌نشیند: هر فراخوانیِ استخر/معاملات از سمتِ رندرِ Flow شمرده می‌شود.
        sf3_base = (len(sf3_pr), len(sf3_tr))
        await spg.evaluate("""() => { window.__gtc = []; const orig = gtJson; gtJson = function (u) { window.__gtc.push(u); return orig(u); }; }""")
        SF3_GTC = """() => ({ pools: window.__gtc.filter(u => /\\/tokens\\/[^/]+\\/pools\\?page=1$/.test(u)).length,
                             trades: window.__gtc.filter(u => /\\/pools\\/[^/]+\\/trades$/.test(u)).length })"""
        SF3_READ = """() => { const b = document.getElementById('flowBody');
            const kv = {}; b.querySelectorAll('.flowkv').forEach(r => { const k = r.querySelector('.k'); kv[k.textContent.trim()] = r.innerText.replace(k.textContent, '').replace(/\\s+/g, ' ').trim(); });
            const cap = b.querySelector('.flowbarCap'), bar = b.querySelectorAll('.flowbar i');
            return { kv: kv, cap: cap ? cap.innerText.replace(/\\s+/g, ' ').trim() : null, bar: Array.from(bar).map(i => i.style.width),
                     hint: (b.querySelector('[data-sample-hint]') || {}).textContent || null, text: b.innerText.replace(/\\s+/g, ' ') }; }"""
        sf3 = {}
        for sf3_id in ("m5", "m15", "h1", "h6", "h24"):
            await spg.click('#flowTfs [data-w="%s"]' % sf3_id)
            await spg.wait_for_function("(v) => document.querySelector('#flowBody .flowkv .mono') && document.querySelector('#flowBody .flowkv .mono').textContent.trim() === v",
                                        arg="$" + format(round(float(SF_WIN[sf3_id][0])), ","), timeout=10000)
            sf3[sf3_id] = await spg.evaluate(SF3_READ)
        for sf3_id, sf3_v in SF_WIN.items():
            r_ = sf3[sf3_id]; tot_ = sf3_v[1] + sf3_v[2]
            want_pc = ("+" if float(sf3_v[5]) >= 0 else "−") + "%.2f%%" % abs(float(sf3_v[5]))
            print("[sol flow3 %s] volume=%s buys=%s sells=%s price=%s cap=%r" % (sf3_id, r_["kv"]["Volume"], r_["kv"]["Buys"], r_["kv"]["Sells"], r_["kv"]["Price"], r_["cap"]))
            assert r_["kv"]["Volume"] == "$" + format(round(float(sf3_v[0])), ","), "[sol flow3] %s volume: %s" % (sf3_id, r_["kv"])
            assert r_["kv"]["Buys"] == "%s · %s buyers" % (format(sf3_v[1], ","), format(sf3_v[3], ",")), "[sol flow3] %s buys: %s" % (sf3_id, r_["kv"])
            assert r_["kv"]["Sells"] == "%s · %s sellers" % (format(sf3_v[2], ","), format(sf3_v[4], ",")), "[sol flow3] %s sells: %s" % (sf3_id, r_["kv"])
            assert r_["kv"]["Price"] == want_pc, "[sol flow3] %s price: %s want %s" % (sf3_id, r_["kv"], want_pc)
            # نوار و عنوانش به‌شمارشِ معاملات‌اند، نه دلار
            assert r_["cap"] and r_["cap"].startswith("Buys %d%%" % round(sf3_v[1] / tot_ * 100)) and "by count" in r_["cap"] \
                and ("Sells %d%%" % round(sf3_v[2] / tot_ * 100)) in r_["cap"], "[sol flow3] %s: bar caption must be count-based: %r" % (sf3_id, r_["cap"])
            assert r_["bar"] and abs(float(r_["bar"][0].rstrip("%")) - sf3_v[1] / tot_ * 100) < 0.06, "[sol flow3] %s: bar width must follow buys/(buys+sells) by count: %s" % (sf3_id, r_["bar"])
        assert len({sf3[k]["kv"]["Volume"] for k in sf3}) == 5 and len({sf3[k]["kv"]["Buys"] for k in sf3}) == 5, \
            "[sol flow3] the five windows must show five different numbers"
        # نمونه‌ی معاملات: شروعِ ۱H پوشش داده نشده (قدیمی‌ترین معامله ۲۰۰ دقیقه پیش) → راهنما فقط وقتی نمونه پنجره را نمی‌پوشاند
        print("[sol flow3 hint] 1H=%r 6H=%r 24H=%r" % (sf3["h1"]["hint"], sf3["h6"]["hint"], sf3["h24"]["hint"]))
        for sf3_id in ("m5", "m15", "h1"):
            assert sf3[sf3_id]["hint"] is None, "[sol flow3] %s must have no coverage hint (the sample reaches 200 min back): %r" % (sf3_id, sf3[sf3_id]["hint"])
        for sf3_id in ("h6", "h24"):
            assert re.search(r"· from the last 6 trades \(covers ~(19|20|21)\dm\)", sf3[sf3_id]["hint"] or ""), \
                "[sol flow3] %s: the sample covers only ~200 min; Largest buys needs the hint: %r" % (sf3_id, sf3[sf3_id]["hint"])
        assert "totals for this pool over the selected window" in sf3["h24"]["text"] and "flow, not a forecast" in sf3["h24"]["text"] \
            and "Recent trades from GeckoTerminal" not in sf3["h24"]["text"], "[sol flow3] closing note wording"
        # بدونِ درخواستِ تازه: ۵ بار عوض‌کردنِ پنجره، فقط یک‌بار pools و یک‌بار trades
        sf3_gtc = await spg.evaluate(SF3_GTC)
        print("[sol flow3 cache] gtJson calls after 5 window switches=%s; network pools=%d trades=%d (baseline %s)" % (sf3_gtc, len(sf3_pr), len(sf3_tr), sf3_base))
        assert sf3_gtc == {"pools": 0, "trades": 0} and (len(sf3_pr), len(sf3_tr)) == sf3_base and sf3_base[1] == 1, \
            "[sol flow3] switching windows must re-render from the 60 s cache, not refetch: gtJson=%s network pools=%d trades=%d base=%s" % (sf3_gtc, len(sf3_pr), len(sf3_tr), sf3_base)
        # کش ۶۰ ثانیه می‌ماند و بعدش منقضی می‌شود
        await spg.evaluate("renderSolFlow._cache.fetchedAt -= 61000")
        await spg.click('#flowTfs [data-w="h1"]')
        await spg.wait_for_function("() => document.querySelector('#flowBody .flowkv .mono').textContent.trim() === '$5,100,001'", timeout=10000)
        await spg.wait_for_timeout(200)
        sf3_gtc2 = await spg.evaluate(SF3_GTC)
        print("[sol flow3 cache] after expiry: gtJson calls=%s" % sf3_gtc2)
        assert sf3_gtc2 == {"pools": 1, "trades": 1}, "[sol flow3] a cache older than 60 s must be refetched exactly once: %s" % sf3_gtc2
        # [flow logo] Solana — آواتار با عوض‌کردنِ پنجره دست نمی‌خورد؛ با عوض‌کردنِ توکن (SOL) دست می‌خورد
        sf3_logo = await spg.evaluate("""async () => {
            const av = document.getElementById('flowTokAv'); av.__probe = 'same';
            const muts = []; const mo = new MutationObserver(rs => rs.forEach(r => muts.push(r.type)));
            mo.observe(av, { childList: true, subtree: true, characterData: true });
            const wait = (ms) => new Promise(r => setTimeout(r, ms));
            for (const id of ['m5', 'm15', 'h6', 'h24', 'h1']) { document.querySelector('#flowTfs [data-w="' + id + '"]').click(); await wait(120); }
            const n = muts.length + mo.takeRecords().length;
            return { n: n, same: document.getElementById('flowTokAv') === av && av.__probe === 'same' }; }""")
        print("[flow logo] solana: avatar mutations over 5 window switches=%d sameNode=%s" % (sf3_logo["n"], sf3_logo["same"]))
        assert sf3_logo["n"] == 0 and sf3_logo["same"], "[flow logo] switching windows must not repaint the Solana token avatar: %s" % sf3_logo
        # [sol flow3 SOL] SOL در انتخابگرِ Flow قابل‌انتخاب است: wSOL برای استخر/معاملات، برچسب «SOL»
        n_gtc = await spg.evaluate("window.__gtc.length")
        await spg.evaluate("""() => { window.__avMut = 0; const av = document.getElementById('flowTokAv');
            window.__mo = new MutationObserver(rs => { window.__avMut += rs.length; }); window.__mo.observe(av, { childList: true, subtree: true, characterData: true }); }""")
        await spg.click("#flowTokBtn")
        await spg.click('#solTokList .trow[data-mint="%s"]' % SOL_MINT_ADDR)
        await spg.wait_for_function("() => document.getElementById('flowTokSym').textContent === 'SOL'", timeout=10000)
        await spg.wait_for_function("(n) => window.__gtc.slice(n).some(u => /\\/trades$/.test(u))", arg=n_gtc, timeout=10000)
        await spg.wait_for_timeout(300)
        sf3_calls = await spg.evaluate("(n) => window.__gtc.slice(n)", n_gtc)
        sf3_sol = await spg.evaluate("() => ({ sym: document.getElementById('flowTokSym').textContent, cur: solMintCur, ref: solRefMint, "
                                     "pool: document.querySelector('#flowBody .flowkv a').textContent, mut: window.__avMut })")
        print("[sol flow3 SOL] picked SOL in Flow: %s; Flow lookups=%s" % (sf3_sol, [u.split("/networks/solana/")[1][:70] for u in sf3_calls]))
        assert sf3_sol["sym"] == "SOL" and sf3_sol["cur"] == SOL_MINT_ADDR, "[sol flow3 SOL] Flow must switch to SOL: %s" % sf3_sol
        assert sf3_sol["ref"] != SOL_MINT_ADDR, "[sol flow3 SOL] the swap reference must not become SOL as well (SOL/SOL): %s" % sf3_sol
        assert any(("/tokens/%s/pools" % SOL_MINT_ADDR) in u for u in sf3_calls) and any(("/pools/%s/trades" % SF_POOL_SOL) in u for u in sf3_calls), \
            "[sol flow3 SOL] pools must be looked up with the wrapped-SOL mint and trades read from the SOL/USDC pool: %s" % sf3_calls
        assert sf3_sol["mut"] > 0, "[flow logo] a real token change must repaint the avatar (control for the no-repaint probe): %s" % sf3_sol
        sf3_av = await spg.evaluate("() => { const a = document.getElementById('flowTokAv'); return { svg: !!a.querySelector('svg, img'), t: a.textContent.trim() }; }")
        assert sf3_av["svg"], "[sol flow3 SOL] the SOL chip must carry the SOL logo (gradient dot or wSOL image), not a letter: %s" % sf3_av
        await spg.close()

        # ---- [sol flow3] صفتِ غایب/نامعتبر = «—»، هرگز ۰ ----
        sf3_miss = {"data": [sf_pool(SF_POOL_SOL, "SOL / USDC", 3_000_000, 9_000_000, win={"h1": SF_WIN["h1"]})]}
        sf3_miss["data"][0]["attributes"]["volume_usd"]["h6"] = ""                    # رشته‌ی خالی
        sf3_miss["data"][0]["attributes"]["transactions"]["h6"] = {"buys": "x", "sells": None}   # نامعتبر
        sf3_miss["data"][0]["attributes"]["price_change_percentage"]["h6"] = "NaN"
        spg = await sf_page(pools=sf3_miss, errs=sf_errs)
        await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
        sf3_ok = await spg.evaluate(SF3_READ)
        await spg.click('#flowTfs [data-w="h6"]'); await spg.wait_for_timeout(500)
        sf3_h6 = await spg.evaluate(SF3_READ)
        await spg.click('#flowTfs [data-w="h24"]'); await spg.wait_for_timeout(500)
        sf3_h24 = await spg.evaluate(SF3_READ)
        await spg.close()
        print("[sol flow3 missing] 1H=%s | 6H=%s | 24H=%s" % (sf3_ok["kv"], sf3_h6["kv"], sf3_h24["kv"]))
        assert sf3_ok["kv"]["Volume"] == "$5,100,001", "[sol flow3 missing] the present window must still render"
        for tag_, r_ in (("6H invalid", sf3_h6), ("24H absent", sf3_h24)):
            assert (r_["kv"]["Volume"], r_["kv"]["Buys"], r_["kv"]["Sells"], r_["kv"]["Price"]) == ("—", "—", "—", "—"), \
                "[sol flow3 missing] %s: a missing/invalid attribute must read '—', never 0: %s" % (tag_, r_["kv"])
            assert r_["cap"] is None and not r_["bar"], "[sol flow3 missing] %s: no bar without counts" % tag_

        # ---- [sol flow3] چیدمان در موبایل و دسکتاپ (بدونِ سرریز) + عکس‌ها ----
        for sf3_w, sf3_h, sf3_scheme, sf3_win, sf3_name in ((1440, 900, "light", "m5", "sol-flow-5m-light-1440"), (1440, 900, "light", "h24", "sol-flow-24h-light-1440"),
                                                            (390, 844, "dark", "m5", "sol-flow-5m-dark-390"), (390, 844, "dark", "h24", "sol-flow-24h-dark-390")):
            spg = await sf_page(w=sf3_w, h=sf3_h, scheme=sf3_scheme, errs=sf_errs)
            await spg.wait_for_selector("#flowBody .flowkv", timeout=15000)
            await spg.click('#flowTfs [data-w="%s"]' % sf3_win); await spg.wait_for_timeout(500)
            sf3_m = await spg.evaluate(SF_MEASURE)
            assert not sf3_m["outside"] and await spg.evaluate("document.documentElement.scrollWidth <= innerWidth"), \
                "[sol flow3] %s: overflow: %s" % (sf3_name, sf3_m["outside"])
            await spg.screenshot(path="/tmp/claude-0/r10_shots/%s.png" % sf3_name)
            await spg.close()
        print("[sol flow3 layout] 5M and 24H render without overflow at 1440 light and 390 dark")

        # ---- [boot view] r10 — رفتن به /app#flow (و #folio, #faq) نباید یک فریمِ Swap نشان دهد ----
        BOOT_WATCH = """
(function(){ window.__boot = [];
  function snap(tag){ var sw = document.getElementById('view-swap'); if (!sw) return;
    var tgt = (location.hash.slice(1).split('?')[0] || ''), nav = {};
    document.querySelectorAll('#nav > button[data-view]').forEach(function(b){ var bg = getComputedStyle(b).backgroundColor; nav[b.dataset.view] = !(bg === 'rgba(0, 0, 0, 0)' || bg === 'transparent'); });
    var mk = document.getElementById('navMarkets'); if (mk) { var mbg = getComputedStyle(mk).backgroundColor; nav.markets = !(mbg === 'rgba(0, 0, 0, 0)' || mbg === 'transparent'); }
    var tv = document.getElementById('view-' + tgt);
    window.__boot.push({tag: tag, swap: getComputedStyle(sw).display, tgt: tgt, tgtDisplay: tv ? getComputedStyle(tv).display : null, nav: nav,
                        attr: document.documentElement.getAttribute('data-boot-view'), tokenView: document.getElementById('view-token') ? getComputedStyle(document.getElementById('view-token')).display : null}); }
  new MutationObserver(function(){ snap('mut'); }).observe(document, {subtree: true, childList: true, attributes: true, attributeFilter: ['class', 'data-boot-view', 'style']});
  (function raf(){ snap('raf'); requestAnimationFrame(raf); })();
})();
"""
        for bt_hash in ("#flow", "#folio", "#faq", "#flow?chain=solana", "#folio?chain=solana"):
            bt_view = bt_hash[1:].split("?")[0]
            spg = await sf_page(hash_=bt_hash, init=[BOOT_WATCH], errs=sf_errs)
            await spg.wait_for_function("(v) => document.getElementById('view-' + v).classList.contains('on')", arg=bt_view, timeout=15000)
            await spg.wait_for_timeout(500)
            bt = await spg.evaluate("() => ({ log: window.__boot, attr: document.documentElement.hasAttribute('data-boot-view'), "
                                    "swapOn: document.getElementById('view-swap').classList.contains('on'), navOn: Array.from(document.querySelectorAll('#nav [data-view].on')).map(b => b.dataset.view), marketsOn: document.getElementById('navMarkets').classList.contains('on') })")
            await spg.close()
            bad_swap = [e for e in bt["log"] if e["swap"] != "none"]
            bad_tgt = [e for e in bt["log"] if e["tgtDisplay"] == "none"]
            # ۶ اکتبر: flow حالا تبِ Markets را روشن می‌کند؛ folio و faq هیچ تبی در نوار ندارند (فقط Swap نباید روشن باشد).
            bad_nav = [e for e in bt["log"] if e["nav"].get("swap", False) or (bt_view == "flow" and not e["nav"].get("markets", False))
                       or (bt_view != "flow" and e["nav"].get("markets", False))]
            print("[boot view %s] snapshots=%d swapVisible=%d targetHidden=%d wrongNav=%d attrAfterBoot=%s navOn=%s"
                  % (bt_hash, len(bt["log"]), len(bad_swap), len(bad_tgt), len(bad_nav), bt["attr"], bt["navOn"]))
            assert len(bt["log"]) >= 2, "[boot view] the watcher saw nothing"
            assert not bad_swap, "[boot view] %s: #view-swap was painted before the router ran: %s" % (bt_hash, bad_swap[:2])
            assert not bad_tgt, "[boot view] %s: the target view was hidden at first paint: %s" % (bt_hash, bad_tgt[:2])
            assert not bad_nav, "[boot view] %s: the nav highlight was wrong at first paint: %s" % (bt_hash, bad_nav[:2])
            # ۱۸ اکتبر (تغییر عمدی): Flow دیگر دکمه‌ی data-view در #nav نیست، پس navOn همیشه خالی است؛ روشن‌بودنِ Markets جداگانه (marketsOn) سنجیده می‌شود.
            assert not bt["attr"] and not bt["swapOn"] and bt["navOn"] == [] and bt["marketsOn"] == (bt_view == "flow"), \
                "[boot view] %s: after the router ran the attribute must be gone and the class state right: %s" % (bt_hash, {k: v for k, v in bt.items() if k != "log"})
        # بدونِ هش: Swap همچنان از همان فریم اول دیده می‌شود، هیچ attributeای نیست
        spg = await sf_page(hash_="", init=[BOOT_WATCH], errs=sf_errs)
        await spg.wait_for_function("() => document.getElementById('view-swap').classList.contains('on')", timeout=15000)
        await spg.wait_for_timeout(300)
        bt = await spg.evaluate("() => window.__boot")
        await spg.close()
        print("[boot view /app] snapshots=%d swapHidden=%d withAttr=%d" % (len(bt), len([e for e in bt if e["swap"] == "none"]), len([e for e in bt if e["attr"]])))
        assert bt and not [e for e in bt if e["swap"] == "none" or e["attr"]], "[boot view] /app without a hash must show Swap from the first frame, no boot attribute: %s" % bt[:2]
        assert all(e["nav"].get("swap") for e in bt), "[boot view] the Swap tab must stay highlighted on /app"
        # صفحه‌ی توکن: دست‌نخورده — با هش و بی‌هش attribute هرگز نشسته نمی‌شود و نمای توکن دیده می‌شود
        for bt_hash in ("", "#flow"):
            spg = await sf_page(hash_=bt_hash, path="/t/" + SF_USDC, init=[BOOT_WATCH], errs=sf_errs)
            await spg.wait_for_function("() => tokenPage === true", timeout=15000)
            await spg.wait_for_timeout(500)
            bt = await spg.evaluate("() => window.__boot")
            tok_on = await spg.evaluate("() => document.getElementById('view-token').classList.contains('on')")
            await spg.close()
            print("[boot view /t/%s] snapshots=%d withAttr=%d tokenViewOn=%s" % (bt_hash or "", len(bt), len([e for e in bt if e["attr"]]), tok_on))
            assert not [e for e in bt if e["attr"]], "[boot view] the token page must never get the boot attribute: %s" % [e for e in bt if e["attr"]][:2]
            assert tok_on, "[boot view] the token page must still show its own view"

        # ---- [sol folio] r10 — ردیفِ Portfolio سولانا عینِ ردیفِ Base، بدونِ نشانِ سرگردان ----
        # علت: یک <span class="av"> بی‌اندازه بین chip و نماد؛ .av در ردیفِ portfolio width/height ندارد، پس به نواری
        # ~۲×۶ پیکسل با حرفِ اولِ بریده‌شده فرومی‌پاشید — همان «ویرگول» کنارِ chip.
        sfo_rpc = lambda m, pr: ({"value": 2_500_000_000} if m == "getBalance" else
                                 {"value": ([] if (pr[1] or {}).get("programId", "").startswith("Tokenz") else
                                            [{"pubkey": "acc1", "account": {"data": {"parsed": {"info": {"mint": SF_USDC, "tokenAmount": {"amount": "5000000", "decimals": 6}}}}}}])}
                                 if m == "getTokenAccountsByOwner" else None)
        sfo_multi = {"data": [{"attributes": {"address": SOL_MINT_ADDR, "symbol": "SOL", "price_usd": "150", "image_url": "https://example.test/sol.png"}},
                              {"attributes": {"address": SF_USDC, "symbol": "USDC", "price_usd": "1"}}]}
        spg = await sf_page(hash_="#folio?chain=solana", init=[CARRY_WALLET_INIT], rpc=sfo_rpc, multi=sfo_multi, errs=sf_errs)
        await spg.wait_for_selector('#folioBody [data-act="connect"]', timeout=15000)
        await spg.click('#folioBody [data-act="connect"]')
        await spg.wait_for_selector("#solWalList .walRow[data-i]", timeout=10000)
        await spg.click("#solWalList .walRow[data-i]")
        await spg.wait_for_selector("#folioBody .frow", timeout=15000)
        await spg.wait_for_timeout(600)
        SFO_READ = """() => Array.from(document.querySelectorAll('#folioBody .frow')).map(r => {
            const kids = Array.from(r.children).map(c => ({ cls: c.className, text: c.textContent.replace(/\\s+/g, ' ').trim(), r: c.getBoundingClientRect().toJSON() }));
            const own = Array.from(r.childNodes).filter(n => n.nodeType === 3 && n.textContent.trim()).map(n => n.textContent.trim());
            const small = Array.from(r.querySelectorAll('*')).filter(e => { const b = e.getBoundingClientRect(); return b.width > 0 && b.width < 8 && e.textContent.trim() && !e.classList.contains('fchip'); }).map(e => e.className + ':' + e.textContent.trim());
            return { kids: kids, own: own, small: small, avs: r.querySelectorAll('.av').length }; })"""
        sfo = await spg.evaluate(SFO_READ)
        await spg.screenshot(path="/tmp/claude-0/r10_shots/sol-folio-row-light-1440.png", clip={"x": 150, "y": 100, "width": 1140, "height": 420})
        await spg.close()
        print("[sol folio] rows=%d kids=%s" % (len(sfo), [[k["cls"] for k in r["kids"]] for r in sfo]))
        assert len(sfo) == 2, "[sol folio] expected the SOL and USDC rows: %s" % sfo
        for r_ in sfo:
            # عینِ ردیفِ Base: chip رنگی، [نماد/مقدار]، ارزش — بدون آواتار، بدون متنِ آزاد، بدون عنصرِ ریزتر از ۸ پیکسل
            assert [k["cls"] for k in r_["kids"]] == ["fchip", "", "fval"], "[sol folio] the row must have the Base element order: %s" % r_["kids"]
            assert r_["avs"] == 0 and not r_["own"] and all(x.split(":")[0] in ("fbal mono", "u mono", "p mono", "fsym") for x in r_["small"]), \
                "[sol folio] stray element/text in the row: %s" % r_
            assert re.fullmatch(r"(SOL|USDC) [\d.,]+", r_["kids"][1]["text"]) and re.fullmatch(r"\$[\d.,]+ [\d.]+%", r_["kids"][2]["text"]), \
                "[sol folio] unexpected row text: %s" % r_["kids"]
            assert r_["kids"][0]["r"]["right"] <= r_["kids"][1]["r"]["left"] + 0.5 and r_["kids"][1]["r"]["right"] <= r_["kids"][2]["r"]["left"], \
                "[sol folio] the chip overlaps the amount: %s" % r_["kids"]

        # ---- [sol exitcard] r10 — /app (سولانا): بلوکِ «Sell route found» حذف شد؛ صفحه‌ی توکن دست‌نخورده ----
        spg = await sf_page(hash_="#swap?chain=solana", errs=sf_errs)
        await spg.wait_for_function("() => solVerdictV === 'sell' && document.getElementById('appSolExitSym').textContent !== ''", timeout=15000)
        await spg.wait_for_timeout(500)
        sec = await spg.evaluate("() => ({ box: document.getElementById('appSolExitBox').innerText, boxHtml: document.getElementById('appSolExitBox').innerHTML, "
                                 "card: document.getElementById('appSolSafetyCard').innerText, pill: (document.getElementById('solSellPill') || {}).innerText || '' })")
        await spg.screenshot(path="/tmp/claude-0/r10_shots/sol-swap-exitcard-light-1440.png", full_page=True)
        await spg.close()
        print("[sol exitcard] /app Solana exit box=%r pill=%r" % (sec["box"], sec["pill"][:40]))
        assert "sell route found" not in sec["card"].lower() and "quoted just now" not in sec["card"].lower(), \
            "[sol exitcard] the Sell route found block must be gone from the /app Solana exit card: %r" % sec["card"]
        assert sec["boxHtml"].strip() == "", "[sol exitcard] a live sell verdict leaves the exit box empty, like Base: %r" % sec["boxHtml"][:120]
        spg = await sf_page(hash_="", path="/t/" + SF_USDC, errs=sf_errs)
        await spg.wait_for_function("() => document.getElementById('tk-exitBox').innerText.includes('Sell route found')", timeout=15000)
        tk_exit = await spg.evaluate("() => document.getElementById('tk-exitBox').innerText")
        await spg.close()
        print("[sol exitcard] token page still has it: %r" % tk_exit.replace("\n", " ")[:80])
        assert "Sell route found" in tk_exit, "[sol exitcard] the token page (/t/<mint>) must keep its Sell route found block"
        # کهربایی/تأییدنشده روی /app همچنان کار می‌کند
        spg = await sf_page(hash_="#swap?chain=solana", vd='{"v":null,"ms":10,"why":"sol:unconfirmed"}', errs=sf_errs)
        await spg.wait_for_function("() => document.getElementById('appSolExitBox').innerText.includes('unconfirmed')", timeout=15000)
        unc = await spg.evaluate("() => document.getElementById('appSolExitBox').innerText")
        await spg.close()
        print("[sol exitcard] unconfirmed still amber/shown on /app: %r" % unc.replace("\n", " ")[:80])
        assert "unconfirmed" in unc.lower() and "high risk" in unc, "[sol exitcard] the unconfirmed state must still render on /app: %r" % unc

        # ---- [sol flash] معرفیِ «Choose a Solana token» حینِ بارگذاریِ توکنِ پیش‌فرض ----
        spg = await sf_page(hash_="#flow?chain=solana", delay=0.6, intro_watch=True, errs=sf_errs)
        await spg.wait_for_timeout(250)
        early = await spg.inner_text("#flowBody")
        await spg.wait_for_selector("#flowBody .flowkv", timeout=20000)
        seen_intro = await spg.evaluate("window.__introSeen")
        final_txt = " ".join((await spg.inner_text("#flowBody")).split())
        await spg.close()
        print("[sol flash flow] intro ever added=%s early=%r final has Pool=%s" % (seen_intro, early[:50], "Pool" in final_txt))
        assert seen_intro is False, "[sol flash] the 'Choose a Solana token' intro must never appear while the default token loads"
        assert "Reading recent Solana trades" in early or "Reading" in early, "[sol flash] a spinner row must hold the place meanwhile: %r" % early
        assert "Volume" in final_txt and "USDC" in final_txt, "[sol flash] the default token's flow must render afterwards: %r" % final_txt[:120]
        # ناوبری از Swap به Flow در همان صفحه هم همین است
        spg = await sf_page(hash_="#swap?chain=solana", delay=0.4, intro_watch=True, errs=sf_errs)
        await spg.wait_for_timeout(100)
        await spg.evaluate("location.hash = '#flow?chain=solana'")
        await spg.wait_for_selector("#flowBody .flowkv", timeout=20000)
        seen_intro2 = await spg.evaluate("window.__introSeen")
        await spg.close()
        print("[sol flash flow] navigating Swap -> Flow: intro ever added=%s" % seen_intro2)
        assert seen_intro2 is False, "[sol flash] navigating Swap -> Flow must not flash the intro either"
        # ناوبری به Portfolio بدونِ کیف‌پول: همان معرفیِ «Connect» درست است، ولی با نشستِ در حالِ بازیابی نباید لحظه‌ای پدیدار شود
        # (در بخشِ هدر زیر سنجیده می‌شود)

        # ---- [sol flash] هدرِ کیف‌پول بینِ صفحه‌ها ----
        HF_DCL = """
(function(){ window.__hist = [];
  function snap(tag){ var b = document.getElementById('connectBtn'); if (b && window.__hist.length < 4000)
    window.__hist.push({tag: tag, t: b.textContent.trim(), cls: b.className, busy: b.getAttribute('aria-busy')}); }
  document.addEventListener('DOMContentLoaded', function(){ snap('dcl'); });
  new MutationObserver(function(){ snap('mut'); }).observe(document, {subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['class', 'aria-busy']});
})();
"""
        hf_errs = []
        async def hf_open(url, cfg=None, rec=None, off=False, wait_after=0):
            hpg = await carry_page(hf_errs)
            await hpg.add_init_script(HF_DCL)
            await carry_seed(hpg, cfg, rec, off)
            await hpg.goto(url)
            if wait_after:
                await hpg.wait_for_timeout(wait_after)
            return hpg
        HF_STATE = """() => { const b = document.getElementById('connectBtn');
            const h = window.__hist || []; const dcl = h.find(x => x.tag === 'dcl') || null;
            return { dcl: dcl, now: { t: b.textContent.trim(), cls: b.className, busy: b.getAttribute('aria-busy') },
                     everConnect: h.slice(Math.max(0, h.indexOf(dcl))).some(x => x.t === 'Connect wallet'), calls: window.__calls,
                     rec: sessionStorage.getItem('zaexa.solsession.v1') }; }"""
        for hf_kind, hf_url, hf_base_url in (("app", CARRY_APP, CARRY_ORIGIN + "/app#swap?chain=base"),
                                              ("pairs", CARRY_PAIRS, CARRY_ORIGIN + "/pairs.html")):
            ov = "#solWalletOv" if hf_kind == "app" else "#walletOv"
            # الف) رکوردِ معتبر + کیف‌پولی که دیر register می‌شود: از اولین رنگ «وصل» است و کلیک کاری نمی‌کند
            hpg = await hf_open(hf_url, {"late": 1500}, carry_rec(), False, wait_after=500)
            s_mid = await hpg.evaluate(HF_STATE)
            await hpg.click("#connectBtn")
            await hpg.wait_for_timeout(250)
            ov_on = await hpg.evaluate("(sel) => document.querySelector(sel).classList.contains('on')", ov)
            await hpg.wait_for_timeout(1900)
            s_end = await hpg.evaluate(HF_STATE)
            await hpg.close()
            print("[sol flash header %s] restore ok: first paint=%s mid=%s clickOpenedPicker=%s end=%s everConnectWallet=%s calls=%s"
                  % (hf_kind, s_mid["dcl"], s_mid["now"], ov_on, s_end["now"], s_end["everConnect"], s_end["calls"]))
            assert s_mid["dcl"] and s_mid["dcl"]["t"] == CARRY_SHORT and s_mid["dcl"]["cls"] == "chip" and s_mid["dcl"]["busy"] == "true", \
                "[sol flash] %s: the very first paint must already show the connected look with the short address: %s" % (hf_kind, s_mid["dcl"])
            assert not s_mid["everConnect"] and s_mid["now"]["t"] == CARRY_SHORT and s_mid["now"]["busy"] == "true", \
                "[sol flash] %s: 'Connect wallet' must never show while the restore is pending: %s" % (hf_kind, s_mid)
            assert ov_on is False and s_mid["calls"] == [], "[sol flash] %s: clicks must do nothing while pending (overlay=%s calls=%s)" % (hf_kind, ov_on, s_mid["calls"])
            assert s_end["now"]["t"] == CARRY_SHORT and s_end["now"]["cls"] == "chip" and s_end["now"]["busy"] is None \
                and s_end["calls"] == [{"silent": True}], "[sol flash] %s: the real connected paint must take over: %s" % (hf_kind, s_end)
            # ب) رکورد هست ولی هیچ کیف‌پولی register نمی‌شود: ≤۲۵۰۰ms بعد «Connect wallet» و رکورد پاک
            hpg = await hf_open(hf_url, {"late": 99999}, carry_rec(), False, wait_after=600)
            f_mid = await hpg.evaluate(HF_STATE)
            await hpg.wait_for_timeout(2900)
            f_end = await hpg.evaluate(HF_STATE)
            await hpg.close()
            print("[sol flash header %s] no wallet registers: first=%s at0.6s=%s at3.5s=%s rec=%s"
                  % (hf_kind, f_mid["dcl"], f_mid["now"]["t"], f_end["now"], f_end["rec"]))
            assert f_mid["dcl"]["t"] == CARRY_SHORT and f_mid["now"]["t"] == CARRY_SHORT, "[sol flash] %s: pending look expected before the timeout" % hf_kind
            assert f_end["now"]["t"] == "Connect wallet" and f_end["now"]["cls"] == "chip solid" and f_end["now"]["busy"] is None and f_end["rec"] is None, \
                "[sol flash] %s: a restore that never gets a wallet must fall back to 'Connect wallet' and drop the record: %s" % (hf_kind, f_end)
            # ج) بدونِ رکورد: همان لحظه «Connect wallet»
            hpg = await hf_open(hf_url, {}, None, False, wait_after=300)
            n0 = await hpg.evaluate(HF_STATE)
            await hpg.close()
            print("[sol flash header %s] no record: first paint=%s" % (hf_kind, n0["dcl"]))
            assert n0["dcl"]["t"] == "Connect wallet" and n0["dcl"]["cls"] == "chip solid" and n0["dcl"]["busy"] is None, \
                "[sol flash] %s: without a record the button must say 'Connect wallet' immediately: %s" % (hf_kind, n0["dcl"])
            # د) رکورد هست ولی روی Base هستیم: دست‌نخورده
            hpg = await hf_open(hf_base_url, {"late": 99999}, carry_rec(), False, wait_after=300)
            b0 = await hpg.evaluate(HF_STATE)
            await hpg.close()
            print("[sol flash header %s] Base chain with a record: first paint=%s rec kept=%s" % (hf_kind, b0["dcl"], b0["rec"] is not None))
            assert b0["dcl"]["busy"] is None and b0["dcl"]["cls"] == "chip solid", "[sol flash] %s: Base look expected: %s" % (hf_kind, b0["dcl"])
        # Portfolio با نشستِ در حال بازیابی: معرفیِ «Connect Solana wallet» نباید پدیدار شود
        hpg = await hf_open(CARRY_ORIGIN + "/app#folio?chain=solana", {"late": 1500}, carry_rec(), False, wait_after=600)
        folio_mid = await hpg.inner_text("#folioBody")
        await hpg.close()
        print("[sol flash folio] pending restore -> %r" % folio_mid[:60])
        assert "Connect Solana wallet" not in folio_mid, "[sol flash] Portfolio must not offer 'Connect' while a session restore is pending: %r" % folio_mid
        assert not hf_errs, "[sol flash] console errors: %s" % hf_errs[:3]

        # ---- [sol budget] ۰٫۰۰۴۳۸۵ SOL، ورودی ۰٫۰۰۱، حسابِ توکنِ خروجی هنوز نیست ----
        sb_log = []
        SB_QUOTE = dict(SOL_QUOTE_FIXTURE, inAmount="1000000")   # همان ۰٫۰۰۱ SOL که مالک وارد کرد
        sbpg = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=4_385_000, rpc_log=sb_log, quote_body=SB_QUOTE)
        await sol_connect(sbpg)
        await sbpg.fill("#solAmt", "0.001")
        await sbpg.wait_for_timeout(900)
        sb_disabled = await sbpg.is_disabled("#solSwapBtn")
        sb_text = await sbpg.inner_text("#solSwapBtn")
        await sbpg.evaluate("() => { try { solDoSwap(); } catch(_){} }")
        await sbpg.wait_for_timeout(300)
        sb_calls = await sbpg.evaluate("window.__solCalls.length")
        await sbpg.close()
        print("[sol budget] balance=0.004385 in=0.001 outputATA missing -> disabled=%s text=%r walletCalls=%d simCalls=%d"
              % (sb_disabled, sb_text, sb_calls, sb_log.count("simulateTransaction")))
        assert sb_disabled and "Not enough SOL" in sb_text and "0.00529" in sb_text, \
            "[sol budget] amount + wSOL rent + token-account rent + fee must be demanded before any wallet call: %r" % sb_text
        assert sb_calls == 0 and sb_log.count("simulateTransaction") == 0, "[sol budget] the wallet/simulation must never be reached"
        # کنترلِ مثبت: ۰٫۰۰۶ SOL کافی است و دکمه باز می‌ماند
        sb2pg = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=6_000_000, quote_body=SB_QUOTE)
        await sol_connect(sb2pg)
        await sb2pg.fill("#solAmt", "0.001")
        await sb2pg.wait_for_timeout(900)
        sb2_text = await sb2pg.inner_text("#solSwapBtn")
        sb2_disabled = await sb2pg.is_disabled("#solSwapBtn")
        await sb2pg.close()
        print("[sol budget] balance=0.006 in=0.001 -> disabled=%s text=%r" % (sb2_disabled, sb2_text))
        assert not sb2_disabled and "Not enough SOL" not in sb2_text, "[sol budget] a sufficient balance must not be blocked: %r" % sb2_text
        # کمکِ واحد: یادداشتِ «Keep at least» و بودجه از یک helper می‌آیند و نمی‌توانند اختلاف پیدا کنند
        sb3pg = await open_sol_swap_page({"v": "sell", "ms": 100}, balance_lamports=2_000_000_000)
        await sol_connect(sb3pg)
        await sb3pg.fill("#solAmt", "0.001")
        await sb3pg.wait_for_timeout(900)
        sb3 = await sb3pg.evaluate("() => ({ keep: solSimKeepSol(), reserve: solReserveSol(), fee: (solNetFeeLamports != null ? solNetFeeLamports : SOL_PRIO_FEE_RESERVE * 1e9) + 5000 })")
        await sb3pg.close()
        print("[sol budget] helper agreement: keep=%s reserve=%.5f" % (sb3["keep"], sb3["reserve"]))
        assert abs(float(sb3["keep"]) - sb3["reserve"]) < 0.0002, \
            "[sol budget] the budget reserve and the 'keep at least' number must come from the same rent helper: %s" % sb3
        # شبیه‌سازی با insufficient-sol: بلوکِ ساده، هرگز «Swap anyway»، کیف‌پول هرگز صدا زده نمی‌شود
        SB_SYSP = "11111111111111111111111111111111"
        sb_sim = {"value": {"err": {"InstructionError": [2, {"Custom": 1}]}, "logs": [
            "Program %s invoke [1]" % SB_SYSP, "Transfer: insufficient lamports 4875000, need 2039280",
            "Program %s failed: custom program error: 0x1" % SB_SYSP]}}
        sb4pg = await open_sol_swap_page({"v": "sell", "ms": 100}, sim_result=sb_sim)
        await sol_connect(sb4pg)
        await sb4pg.fill("#solAmt", "1")
        await sb4pg.wait_for_timeout(900)
        sb4_texts, sb4_arm = [], []
        for _ in range(3):
            try:
                await sb4pg.click("#solSwapBtn", timeout=3000)
            except Exception:
                pass   # دکمه غیرفعال/ناپدید شد — حالتِ بعدی را ثبت می‌کنیم و ادعا خودش می‌شکند
            await sb4pg.wait_for_timeout(700)
            sb4_texts.append(await sb4pg.inner_text("#solSwapBtn"))
            sb4_arm.append(await sb4pg.evaluate("solNeedsSimArm()"))
        sb4_notice = await sb4pg.inner_text("#solNotices")
        sb4_calls = await sb4pg.evaluate("window.__solCalls.length")
        await sb4pg.close()
        print("[sol budget] sim insufficient-sol x3 clicks -> buttons=%s armed=%s walletCalls=%d notice=%r"
              % (sb4_texts, sb4_arm, sb4_calls, sb4_notice[:90]))
        assert all("Swap anyway" not in t for t in sb4_texts) and not any(sb4_arm), \
            "[sol budget] insufficient-sol must never be armable: %s %s" % (sb4_texts, sb4_arm)
        assert sb4_calls == 0, "[sol budget] the wallet must never be called after an insufficient-sol simulation"
        assert "Not enough SOL for the network fee" in sb4_notice and "Keep at least" in sb4_notice, "[sol budget] message kept: %r" % sb4_notice
        assert not sf_errs, "[sol flow2] console errors: %s" % sf_errs[:3]
        print("[sol flow2] Solana Money Flow picks the busiest real pool, renders Base's rows in order with tx3 links inside the card, "
              "no intro flash, no header flash on /app or /pairs, and not-enough-SOL is a plain block with a shared rent helper")

        # ---- [theme first paint] تمِ اولیه باید پیش از اولین رنگ‌آمیزی، از
        # داخلِ <head> (پیش از اولین <style>) نوشته شود، نه در پایانِ body —
        # وگرنه یک فلاشِ روشن-روی-تیره دیده می‌شود. هر سه صفحه. ----
        tfp_static_ok = {}
        for tfp_name in ("index.html", "pairs.html", "landing.html"):
            tfp_src = open(os.path.join(HERE, "..", tfp_name), encoding="utf-8").read()
            tfp_head_end = tfp_src.find("</head>")
            # ⚠️ خطِ-به-خطی: یک اشاره‌ی متنیِ «<style>» داخلِ همین کامنتِ
            # توضیحی هم با جست‌وجوی ساده پیدا می‌شود؛ تگِ واقعی همیشه
            # ابتدای خط می‌آید، پس با ^ (چندخطی) جدا می‌شود.
            tfp_style_m = re.search(r"(?m)^<style[ >]", tfp_src)
            tfp_first_style = tfp_style_m.start() if tfp_style_m else -1
            tfp_theme_write = tfp_src.find("zaexa.theme.v1")
            tfp_static_ok[tfp_name] = (
                tfp_theme_write != -1 and tfp_first_style != -1 and
                tfp_theme_write < tfp_first_style < tfp_head_end
            )
        tfp_runtime = {}
        for tfp_name in ("index.html", "pairs.html", "landing.html"):
            tfp_pg = await b.new_page()
            await tfp_pg.add_init_script(
                "localStorage.setItem('zaexa.theme.v1','dark');"
                "window.__firstThemeAtDomLoading = null;"
                "document.addEventListener('readystatechange', () => {"
                "  if (window.__firstThemeAtDomLoading === null && document.documentElement.dataset.theme)"
                "    window.__firstThemeAtDomLoading = document.documentElement.dataset.theme;"
                "});"
            )
            await tfp_pg.goto("http://127.0.0.1:%d/%s" % (port, tfp_name))
            tfp_theme_attr = await tfp_pg.evaluate("() => document.documentElement.dataset.theme")
            await tfp_pg.close()
            tfp_runtime[tfp_name] = tfp_theme_attr
        print("[theme first paint] head-before-first-style=%s runtimeDarkAttr=%s" % (tfp_static_ok, tfp_runtime))
        for tfp_name in ("index.html", "pairs.html", "landing.html"):
            assert tfp_static_ok[tfp_name], (
                "[theme first paint] %s does not write zaexa.theme.v1 into <head> before its "
                "first <style> — a theme flash on first paint is possible" % tfp_name)
            assert tfp_runtime[tfp_name] == "dark", (
                "[theme first paint] %s did not have data-theme=dark set from localStorage "
                "by the time it loaded: %r" % (tfp_name, tfp_runtime[tfp_name]))

        # ---- [swap settings persist] zaexa.swap.v1 مشترک بینِ اپ و pairs —
        # نوشتنِ اپ روی pairs دیده می‌شود، نوشتنِ pairs روی اپ دیده می‌شود،
        # JSON خراب باعثِ خطا نمی‌شود (پیش‌فرض می‌ماند)، و مقدارِ سفارشیِ
        # نامعتبر (custom="999", خارج از بازه‌ی ۰..۵۰) هرگز اعمال نمی‌شود —
        # bps باید روی پیش‌فرض (۵۰ یعنی ۰٫۵٪) بماند، عیناً همان اعتبارسنجیِ
        # خودِ oninput که کاربر با تایپ هم به آن می‌رسید. ----
        ssp_app1 = await b.new_page(viewport={"width": 1280, "height": 900})
        ssp_app1_errs = []
        ssp_app1.on("pageerror", lambda e: ssp_app1_errs.append(str(e)))
        await ssp_app1.goto("http://127.0.0.1:%d/" % port)
        await ssp_app1.wait_for_timeout(400)
        await ssp_app1.click("#setBtn")
        await ssp_app1.wait_for_timeout(100)
        await ssp_app1.fill("#slipCustom", "1")
        await ssp_app1.eval_on_selector("#slipCustom", "e => e.dispatchEvent(new Event('input'))")
        await ssp_app1.fill("#deadlineMin", "7")
        await ssp_app1.eval_on_selector("#deadlineMin", "e => e.dispatchEvent(new Event('input'))")
        await ssp_app1.check("#unlimApprove")
        await ssp_app1.wait_for_timeout(100)
        ssp_ls_after_app = await ssp_app1.evaluate("() => localStorage.getItem('zaexa.swap.v1')")
        await ssp_app1.close()

        ppg_ssp, ssp_perrs = await open_pairs({"chain": "base", "rows": [], "store": True})
        await ppg_ssp.evaluate(
            "(v) => localStorage.setItem('zaexa.swap.v1', v)", ssp_ls_after_app)
        await ppg_ssp.reload()
        await ppg_ssp.wait_for_timeout(300)
        ssp_pairs_deadline = await ppg_ssp.eval_on_selector("#deadlineMin", "e => e.value")
        ssp_pairs_unlim = await ppg_ssp.eval_on_selector("#unlimApprove", "e => e.checked")
        # روی pairs مقدار را به ۰٫۱٪ عوض می‌کنیم تا برگشتِ آن به اپ سنجیده شود
        await ppg_ssp.evaluate("""() => {
            const seg = document.querySelectorAll('#slipSeg [data-bps]');
            for (const b of seg) if (+b.dataset.bps === 10) b.onclick();
        }""")
        await ppg_ssp.wait_for_timeout(100)
        ssp_ls_after_pairs = await ppg_ssp.evaluate("() => localStorage.getItem('zaexa.swap.v1')")
        await ppg_ssp.close()

        ssp_app2 = await b.new_page(viewport={"width": 1280, "height": 900})
        ssp_app2_errs = []
        ssp_app2.on("pageerror", lambda e: ssp_app2_errs.append(str(e)))
        await ssp_app2.goto("http://127.0.0.1:%d/" % port)
        await ssp_app2.evaluate(
            "(v) => localStorage.setItem('zaexa.swap.v1', v)", ssp_ls_after_pairs)
        await ssp_app2.reload()
        await ssp_app2.wait_for_timeout(400)
        ssp_app_bps_after_pairs = [
            b for b in await ssp_app2.eval_on_selector_all(
                "#slipSeg [data-bps]", "els => els.map(e => ({bps: e.dataset.bps, on: e.classList.contains('on')}))")
            if b["on"]
        ]
        await ssp_app2.close()

        # JSONِ خراب -> بدونِ خطا، بدونِ تغییر
        ssp_app3 = await b.new_page(viewport={"width": 1280, "height": 900})
        ssp_app3_errs = []
        ssp_app3.on("pageerror", lambda e: ssp_app3_errs.append(str(e)))
        await ssp_app3.goto("http://127.0.0.1:%d/" % port)
        await ssp_app3.evaluate("() => localStorage.setItem('zaexa.swap.v1', '{not json')")
        await ssp_app3.reload()
        await ssp_app3.wait_for_timeout(400)
        ssp_app3_bps_on = await ssp_app3.eval_on_selector("#slipSeg [data-bps='50']", "e => e.classList.contains('on')")
        await ssp_app3.close()

        # مقدارِ سفارشیِ نامعتبر (999) -> پیش‌فرض باید بماند (bps=50)، نه اعمال‌شدنِ ۹۹۹
        ssp_app4 = await b.new_page(viewport={"width": 1280, "height": 900})
        ssp_app4_errs = []
        ssp_app4.on("pageerror", lambda e: ssp_app4_errs.append(str(e)))
        await ssp_app4.goto("http://127.0.0.1:%d/" % port)
        await ssp_app4.evaluate(
            "() => localStorage.setItem('zaexa.swap.v1', JSON.stringify({bps: 50, custom: '999', deadline: 3, unlim: false}))")
        await ssp_app4.reload()
        await ssp_app4.wait_for_timeout(400)
        ssp_app4_bps_on = await ssp_app4.eval_on_selector("#slipSeg [data-bps='50']", "e => e.classList.contains('on')")
        await ssp_app4.close()

        ppg_ssp2, ssp_perrs2 = await open_pairs({"chain": "base", "rows": [], "store": True})
        await ppg_ssp2.evaluate(
            "() => localStorage.setItem('zaexa.swap.v1', JSON.stringify({bps: 50, custom: '999', deadline: 3, unlim: false}))")
        await ppg_ssp2.reload()
        await ppg_ssp2.wait_for_timeout(300)
        ssp_pairs4_bps_on = await ppg_ssp2.eval_on_selector("#slipSeg [data-bps='50']", "e => e.classList.contains('on')")
        await ppg_ssp2.close()

        print("[swap settings persist] appToPairs: deadline=%s unlim=%s | pairsToApp bps=%s | "
              "corruptJson bps50On=%s | invalidCustom999 appBps50On=%s pairsBps50On=%s | errors=%s"
              % (ssp_pairs_deadline, ssp_pairs_unlim, ssp_app_bps_after_pairs, ssp_app3_bps_on,
                 ssp_app4_bps_on, ssp_pairs4_bps_on,
                 ssp_app1_errs + ssp_perrs + ssp_app2_errs + ssp_app3_errs + ssp_app4_errs + ssp_perrs2))
        assert ssp_pairs_deadline == "7", (
            "[swap settings persist] pairs.html did not pick up the app's deadline=7: %r" % ssp_pairs_deadline)
        assert ssp_pairs_unlim is True, (
            "[swap settings persist] pairs.html did not pick up the app's unlimited-approve checkbox")
        assert len(ssp_app_bps_after_pairs) == 1 and ssp_app_bps_after_pairs[0]["bps"] == "10", (
            "[swap settings persist] index.html did not pick up pairs.html's 0.1%% slippage: %s"
            % ssp_app_bps_after_pairs)
        assert ssp_app3_bps_on, (
            "[swap settings persist] corrupt JSON in zaexa.swap.v1 must leave the default 0.5%% selected")
        assert ssp_app4_bps_on, (
            "[swap settings persist] an invalid custom slippage (999) must leave the default 0.5%% "
            "selected on index.html, not apply the invalid value"
        )
        assert ssp_pairs4_bps_on, (
            "[swap settings persist] an invalid custom slippage (999) must leave the default 0.5%% "
            "selected on pairs.html, not apply the invalid value"
        )
        assert not (ssp_app1_errs or ssp_perrs or ssp_app2_errs or ssp_app3_errs or ssp_app4_errs or ssp_perrs2), (
            "[swap settings persist] errors during the persistence probe")

        # ---- [sticky header] هدر روی هر سه صفحه sticky است؛ بعد از اسکرول
        # کلاسِ .scrolled/.site-header.scrolled/.landing-header.scrolled
        # می‌نشیند و بالای هدر روی ۰ می‌ماند (نه اینکه با صفحه برود بالا).
        # روی موبایل، نوارِ پایینِ ثابت هنوز به تهِ ویوپورت چسبیده — یعنی
        # sticky-شدنِ هدر containing blockِ nav پایین را عوض نکرده (تله‌ی
        # backdrop-filter/transform روی خودِ هدر). ----
        sh_pages = {
            "index.html": ("header", None),
            "pairs.html": (".site-header", None),
            "landing.html": (".landing-header", None),
        }
        sh_results = {}
        for sh_name, (sh_sel, _) in sh_pages.items():
            for sh_vp in ({"width": 1440, "height": 900}, {"width": 375, "height": 700}):
                sh_pg = await b.new_page(viewport=sh_vp)
                sh_errs = []
                sh_pg.on("pageerror", lambda e: sh_errs.append(str(e)))
                await sh_pg.goto("http://127.0.0.1:%d/%s" % (port, sh_name))
                await sh_pg.wait_for_timeout(400)
                # scrollTo با behavior صریح 'instant': landing.html
                # scroll-behavior:smooth دارد و پرشِ نرم ممکن است هنوز کامل
                # نشده باشد وقتی این‌جا scrollY را می‌خوانیم — این کاوشگر
                # به موقعیتِ نهاییِ اسکرول کار دارد، نه به خودِ انیمیشن؛
                # به‌جای مکثِ ثابت، صبر می‌کنیم تا scrollY واقعاً به ۱۲۰۰
                # برسد (یا حداکثرِ ممکن، اگر صفحه کوتاه‌تر باشد).
                await sh_pg.evaluate(
                    "() => { document.body.style.minHeight = '3000px'; "
                    "window.scrollTo({top: 1200, left: 0, behavior: 'instant'}); }")
                await sh_pg.wait_for_function(
                    "() => (document.scrollingElement || document.documentElement).scrollTop > 100")
                # IntersectionObserver ناهم‌زمان است؛ زیرِ بارِ سوییت ۳۰۰ms گاهی کم بود
                # (۲۳ سپتامبر یک بار روی landing@1440 لرزید، در ۵ اجرای جدا سبز).
                # تا ۳ ثانیه منتظرِ کلاس می‌مانیم؛ اگر هرگز نیاید، assertِ پایین قرمز است.
                try:
                    await sh_pg.wait_for_function(
                        "s => { const e = document.querySelector(s); return !!e && e.classList.contains('scrolled'); }",
                        arg=sh_sel, timeout=3000)
                except Exception:
                    pass
                sh_top = await sh_pg.eval_on_selector(sh_sel, "e => e.getBoundingClientRect().top")
                sh_scrolled = await sh_pg.eval_on_selector(sh_sel, "e => e.classList.contains('scrolled')")
                sh_nav_bottom_ok = True
                if sh_vp["width"] < 500 and sh_name != "landing.html":
                    sh_nav_rect = await sh_pg.evaluate("""() => {
                        const nav = document.querySelector('#nav, .nav');
                        if (!nav) return null;
                        const r = nav.getBoundingClientRect();
                        // ۳ اکتبر — نوار حالا عمداً شناور است (bottom:8px از ۲ اکتبر)؛ پس باید دقیقاً به
                        // اندازه‌ی bottomِ خودش بالای لبه‌ی viewport بنشیند — اگر هدر بلوکِ دربرگیرنده شود
                        // همین عدد به‌هم می‌ریزد، که هدفِ اصلیِ این کاوشگر است.
                        const gap = parseFloat(getComputedStyle(nav).bottom) || 0;
                        return Math.abs(r.bottom - (window.innerHeight - gap)) <= 1;
                    }""")
                    if sh_nav_rect is not None:
                        sh_nav_bottom_ok = sh_nav_rect
                await sh_pg.close()
                sh_key = "%s@%sx%s" % (sh_name, sh_vp["width"], sh_vp["height"])
                sh_results[sh_key] = {
                    "top": sh_top, "scrolled": sh_scrolled, "navBottomOk": sh_nav_bottom_ok, "errs": sh_errs,
                }
        print("[sticky header] %s" % sh_results)
        for sh_key, sh_r in sh_results.items():
            assert abs(sh_r["top"]) <= 1, (
                "[sticky header] %s: header top after scrolling is %.1f, expected ~0 (sticky)"
                % (sh_key, sh_r["top"]))
            assert sh_r["scrolled"], "[sticky header] %s: .scrolled class was not applied after scrolling" % sh_key
            assert sh_r["navBottomOk"], (
                "[sticky header] %s: the mobile bottom nav is no longer flush with the viewport "
                "bottom — the sticky header likely became a containing block for it" % sh_key)
            assert not sh_r["errs"], "[sticky header] %s: errors: %s" % (sh_key, sh_r["errs"])

        # ---- [pairs title] عنوانِ سند زنجیره را دنبال می‌کند ----
        tpg = await b.new_page(viewport={"width": 1280, "height": 900})
        terrs = []
        tpg.on("pageerror", lambda e: terrs.append(str(e)))
        await tpg.route("**/pairs.json**", lambda route: route.fulfill(
            status=200, content_type="application/json",
            body=_jsonPairs.dumps({"chain": "base", "rows": [SELL_ROW], "store": True})))
        await tpg.route("**/gt/networks/base/tokens/multi/**", empty_gt)
        await tpg.route("**/gt/networks/solana/tokens/multi/**", empty_gt)
        await tpg.goto("http://127.0.0.1:%d/pairs.html" % port)
        await tpg.wait_for_timeout(400)
        title_default = await tpg.title()
        await tpg.click(".chain-tabs button[data-chain='solana']")
        await tpg.wait_for_timeout(150)
        title_solana = await tpg.title()
        await tpg.click(".chain-tabs button[data-chain='base']")
        await tpg.wait_for_timeout(150)
        title_base_again = await tpg.title()
        await tpg.close()
        print("[pairs title] default=%r solana=%r backToBase=%r errors=%s"
              % (title_default, title_solana, title_base_again, terrs))
        assert title_default == "New pairs on Base — Zaexa", (
            "wrong default document title: %r" % title_default)
        assert title_solana == "New pairs on Solana — Zaexa", (
            "the title did not switch on the Solana tab: %r" % title_solana)
        assert title_base_again == title_default, (
            "the title did not restore exactly on switching back to Base: %r" % title_base_again)
        assert not terrs, "web/pairs.html threw during the title probe: %s" % terrs

        # ---- [pairs wallet] اسکرین‌شات‌ها — چیپ باید همان نگاهِ اپ را داشته
        # باشد، بازشو از صفحه بیرون نزند، چیزی روی ناوبری نیفتد ----
        shot_dir = "/tmp/pairs_wallet"
        os.makedirs(shot_dir, exist_ok=True)
        sA, sAerrs, _ = await open_wallet_page(
            init_script=fake_provider_script(FAKE_ADDR), color_scheme="dark")
        await sA.click("#connectBtn")
        await sA.wait_for_timeout(150)
        await sA.screenshot(path=os.path.join(shot_dir, "1280-dark-connected-popover.png"))
        await sA.close()

        sB, sBerrs, _ = await open_wallet_page(color_scheme="light")
        await sB.screenshot(path=os.path.join(shot_dir, "1280-light-disconnected.png"))
        await sB.close()

        sC, sCerrs, _ = await open_wallet_page(
            init_script=fake_provider_script(FAKE_ADDR),
            viewport={"width": 390, "height": 844}, color_scheme="dark")
        await sC.screenshot(path=os.path.join(shot_dir, "390-dark-connected.png"))
        await sC.close()
        print("[pairs wallet] screenshots written to %s (errors: %s %s %s)"
              % (shot_dir, sAerrs, sBerrs, sCerrs))
        assert not sAerrs and not sBerrs and not sCerrs, "errors while taking wallet-chip screenshots"

        # ---- [pairs shell] هدرِ pairs.html باید همان پوسته‌ی اپ باشد —
        # نشانِ برند در همان اندازه/جا، بدونِ خطِ زیرِ هدر، چیپِ شبکه به‌جایِ
        # دکمه‌ی مستقلِ ماه، آیتمِ Theme بالای بازشوی کیف‌پول. ----
        LIVE_EXECUTOR = "0x15e511Bf2Ea1a0F50F25E973d57Dce0D01946b6d"

        # ۱‌الف) grid-template-columns/padding — از رویِ خودِ متنِ CSS، نه
        # پیکسلِ محاسبه‌شده: index.html فونتِ سیستم دارد (Inter/Segoe UI) و
        # pairs.html عمداً همان Manropeِ خودِ landing.html را — همان تصمیمِ
        # قبلی، بیرون از این تسک. ناوبریِ وسط با دو فونتِ متفاوت چند پیکسل
        # عرضِ متفاوت می‌گیرد، پس ستونِ auto وسط بینِ دو صفحه دقیقاً برابر
        # نمی‌شود، هرچند مقدارِ *نوشته‌شده*‌ی grid-template-columns/padding در
        # هر دو فایل باید مو‌به‌مو یکی باشد — همان چیزی که این کاوشگر واقعاً
        # می‌خواهد، نه پیکسلِ نهاییِ وابسته به فونت.
        idx_src_shell = open(os.path.join(HERE, "..", "index.html"), encoding="utf-8").read()
        pairs_src_shell = open(os.path.join(HERE, "..", "pairs.html"), encoding="utf-8").read()
        m_idx_hdr = re.search(r"\nheader\{([^}]*)\}", idx_src_shell)
        m_pairs_hdr = re.search(r"\n\.site-header\{([^}]*)\}", pairs_src_shell)
        assert m_idx_hdr, "could not find the header{...} rule in web/index.html"
        assert m_pairs_hdr, "could not find the .site-header{...} rule in web/pairs.html"

        def rule_value(rule_text, prop):
            m = re.search(r"(?:^|;)\s*%s:([^;]+)" % re.escape(prop), rule_text)
            return m.group(1).strip() if m else None

        idx_padding_src = rule_value(m_idx_hdr.group(1), "padding")
        pairs_padding_src = rule_value(m_pairs_hdr.group(1), "padding")
        idx_gridcols_src = rule_value(m_idx_hdr.group(1), "grid-template-columns")
        pairs_gridcols_src = rule_value(m_pairs_hdr.group(1), "grid-template-columns")
        print("[pairs shell] header rule source: index padding=%r gridCols=%r | pairs padding=%r "
              "gridCols=%r" % (idx_padding_src, idx_gridcols_src, pairs_padding_src, pairs_gridcols_src))
        assert idx_padding_src == pairs_padding_src, (
            "web/pairs.html's header padding value (%r) does not match web/index.html's (%r)"
            % (pairs_padding_src, idx_padding_src))
        assert idx_gridcols_src == pairs_gridcols_src, (
            "web/pairs.html's header grid-template-columns value (%r) does not match "
            "web/index.html's (%r)" % (pairs_gridcols_src, idx_gridcols_src))

        # ۱‌ب) نشانِ برند و خودِ هدر — روی هر دو صفحه، هم‌زمان، اندازه‌گیریِ
        # زنده. اندازه/جای «نشانِ برند» از رویِ .glyph∪.wordmark سنجیده
        # می‌شود، نه رویِ .logo خودش — .logo یک آیتمِ گرید در ستونِ ۱fr است و
        # پیش‌فرض تا تهِ ستون کشیده می‌شود (stretch)، پس عرضِ خودِ آن به عرضِ
        # ستونِ وسط (که به فونت بستگی دارد) هم وابسته است؛ آنچه واقعاً دیده
        # می‌شود فقط جعبه‌ی مارک+وردمارک است، هم‌ترازِ چپِ همان ستون.
        # ⚠️ عمداً خودِ .mark سنجیده می‌شود، نه .glyph (جعبه‌ی ثابتِ ۳۸×۳۸ که
        # مارک وسطِ آن جا می‌گیرد) — اگر فقط .glyph سنجیده شود، کوچک‌کردنِ
        # عرضِ خودِ .mark هیچ اثری روی رِکتِ .glyph نمی‌گذارد (جعبه ثابت
        # می‌ماند) و این کاوشگر دقیقاً همان شکستنِ عمدی را که باید بگیرد،
        # از دست می‌دهد.
        apg = await b.new_page(viewport={"width": 1280, "height": 900})
        aerrs = []
        apg.on("pageerror", lambda e: aerrs.append(str(e)))
        await apg.goto("http://127.0.0.1:%d/" % port)
        await apg.wait_for_timeout(400)
        SHELL_JS = """() => {
            const mark = document.querySelector('.logo .glyph .mark').getBoundingClientRect();
            const wordmark = document.querySelector('.logo .wordmark').getBoundingClientRect();
            const hdr = document.querySelector('header');
            const cs = getComputedStyle(hdr);
            return {
                logoLeft: mark.left, logoWidth: wordmark.right - mark.left,
                logoHeight: Math.max(mark.height, wordmark.height),
                padding: cs.padding,
                borderBottomWidth: cs.borderBottomWidth, borderBottomColor: cs.borderBottomColor,
                backgroundColor: cs.backgroundColor,
            };
        }"""
        idx_box = await apg.evaluate(SHELL_JS)

        ppg1, perrs1 = await open_pairs({"chain": "base", "rows": [], "store": True},
                                         viewport={"width": 1280, "height": 900})
        pairs_box = await ppg1.evaluate(SHELL_JS)
        await ppg1.close()
        print("[pairs shell] brand rect index=%r pairs=%r errors=%s %s"
              % (idx_box, pairs_box, aerrs, perrs1))
        for k in ("logoLeft", "logoWidth", "logoHeight"):
            assert abs(idx_box[k] - pairs_box[k]) <= 1, (
                "web/pairs.html's brand lock %s does not match web/index.html within 1px: "
                "index=%s pairs=%s" % (k, idx_box[k], pairs_box[k]))
        assert idx_box["padding"] == pairs_box["padding"], (
            "web/pairs.html's header computed padding (%r) does not match web/index.html's (%r)"
            % (pairs_box["padding"], idx_box["padding"]))
        assert idx_box["borderBottomWidth"] == pairs_box["borderBottomWidth"], (
            "header border-bottom-width differs: index=%r pairs=%r"
            % (idx_box["borderBottomWidth"], pairs_box["borderBottomWidth"]))
        assert idx_box["borderBottomColor"] == pairs_box["borderBottomColor"] == "rgba(0, 0, 0, 0)", (
            "header border-bottom-color must be transparent on both pages: index=%r pairs=%r"
            % (idx_box["borderBottomColor"], pairs_box["borderBottomColor"]))
        assert idx_box["backgroundColor"] == pairs_box["backgroundColor"] == "rgba(0, 0, 0, 0)", (
            "header background-color must be transparent on both pages: index=%r pairs=%r"
            % (idx_box["backgroundColor"], pairs_box["backgroundColor"]))
        assert not aerrs, "web/index.html threw while loading for the shell comparison: %s" % aerrs
        assert not perrs1, "web/pairs.html threw while loading for the shell comparison: %s" % perrs1

        # ---- [header parity] هدرِ pairs باید عیناً همان امضای DOMِ هدرِ اپ
        # باشد: همان idها/کلاس‌ها/ترتیب برای هدر و محتوای #setPop، در هر دو
        # اندازه (دسکتاپ ۱۴۴۰ و موبایل ۳۷۵). #walletPop قبل از اتصال خالی
        # است، پس امضای آن اینجا سنجیده نمی‌شود (کاوشگرِ [pairs connect]
        # جدا آن را می‌سنجد). ----
        # ⚠️ داخلِ <svg> عمداً recurse نمی‌شود: خودِ آیکن‌های تزئینی (gradient/
        # mask/defs یا <use> به‌جای path مستقیم) دو پیاده‌سازیِ متفاوتِ
        # بصراً-یکسان‌اند و ربطی به «امضای هدر» ندارند؛ چیزی که واقعاً باید
        # این‌همان باشد ساختار/idها/کلاس‌های عناصرِ HTMLِ تعاملی است.
        # ⚠️ آیتم‌های ناوبری در اپ <button> هستند (تب‌زنیِ SPA) و در pairs
        # <a href> واقعی (این صفحه بخشی از SPA نیست، باید لینکِ واقعی باشد) —
        # همان تفاوتِ پذیرفته‌شده‌ای که [pairs header] هم می‌سنجد. تگِ
        # عناصرِ .navLink عمداً نادیده گرفته می‌شود؛ idها/کلاس‌ها/ترتیب هنوز
        # کامل سنجیده می‌شوند.
        # ۲۵ اکتبر: دکمه‌ی ★ی دیده‌بانی (#watchWrap) فقط در اپ است، مثل tourBtn؛ pairs دیده‌بانیِ هدر ندارد.
        # Network selection intentionally lives in the active swap card; its placement/menu
        # is covered by solana-parity-browser.py, not shared-header geometry.
        SIG_JS = """(rootSel) => {
            const root = document.querySelector(rootSel);
            if (!root) return null;
            function sig(el, underNav){
                if (el.tagName === 'svg'){
                    return { tag: 'svg', id: el.id || null,
                             cls: (el.className.baseVal || '').toString().split(/\\s+/).filter(c => c).sort() };
                }
                // The app LED follows its RPC heartbeat; the read-only pairs page has no
                // RPC heartbeat. Ignore only LED status, while keeping every structural class.
                const rawClasses = (el.className || '').toString().split(/\\s+/);
                const clsList = rawClasses.filter(c => c && c !== 'on' &&
                    !(c === 'off' && rawClasses.includes('led'))).sort();
                // ۱۸ اکتبر: «Take the tour» فقط در اپ است (تور فقط روی /app می‌گردد)؛ pairs نه تور دارد نه دکمه‌اش.
                const kids = Array.prototype.filter.call(el.children, c => !["srcMenu", "headerNetworkAnchor", "tourBtn", "watchWrap"].includes(c.id));
                // مستقیم زیرِ #nav: در اپ <button> است (تب‌زنیِ SPA) و در
                // pairs <a class="navLink" href> واقعی — همان تفاوتِ
                // پذیرفته‌شده‌ای که [pairs header] هم می‌سنجد؛ نه تگ نه
                // کلاسِ خودِ این عنصر مقایسه نمی‌شود، فقط شمار/ترتیب.
                // ۱۸ اکتبر: منوی Markets (و ردیف‌های .navItem) برداشته شد؛ Markets الان خودش یک آیتمِ مستقیمِ #nav است.
                if (underNav || el.id === 'folioMenuBtn'){   // folioMenuBtn: اپ <button>، pairs <a href="/app#folio">
                    return { tag: 'NAVITEM', id: null, cls: [], children: kids.map(k => sig(k, false)) };
                }
                return {
                    tag: el.tagName,
                    id: el.id || null,
                    cls: clsList,
                    children: kids.map(k => sig(k, el.id === 'nav' || clsList.includes('nav'))),
                };
            }
            return sig(root, false);
        }"""
        GEOM_JS = """() => {
            const sels = ['.logo', '#nav', '#setBtn', '#connectBtn'];
            const out = {};
            for (const s of sels){
                const e = document.querySelector(s);
                out[s] = e ? e.getBoundingClientRect().top.toFixed(1) : null;
            }
            return out;
        }"""
        hp_results = {}
        for hp_vp in ({"width": 1440, "height": 900}, {"width": 375, "height": 800}):
            hpg_app = await b.new_page(viewport=hp_vp)
            hp_aerrs = []
            hpg_app.on("pageerror", lambda e: hp_aerrs.append(str(e)))
            await hpg_app.goto("http://127.0.0.1:%d/" % port)
            await hpg_app.wait_for_timeout(400)
            app_hdr_sig = await hpg_app.evaluate(SIG_JS, "header")
            app_setpop_sig = await hpg_app.evaluate(SIG_JS, "#setPop")
            app_geom = await hpg_app.evaluate(GEOM_JS)
            await hpg_app.close()

            hpg_pairs, hp_perrs = await open_pairs({"chain": "base", "rows": [], "store": True}, viewport=hp_vp)
            pairs_hdr_sig = await hpg_pairs.evaluate(SIG_JS, "header")
            pairs_setpop_sig = await hpg_pairs.evaluate(SIG_JS, "#setPop")
            pairs_geom = await hpg_pairs.evaluate(GEOM_JS)
            await hpg_pairs.close()

            # ⚠️ کلاسِ خودِ ریشه‌ی هدر عمداً از مقایسه کنار گذاشته می‌شود:
            # اپ با سلکتورِ تگیِ «header» استایل می‌گیرد و pairs با کلاسِ
            # «.site-header» (همان قاعده‌ای که [pairs shell] هم روی CSS
            # خامِ دو سلکتور می‌سنجد) — یک قلابِ نام‌گذاریِ متفاوت است، نه
            # ناهم‌سانیِ واقعیِ هدر. همه‌ی فرزندان همچنان کامل مقایسه می‌شوند.
            def strip_root_class(sig):
                if not sig:
                    return sig
                return {"tag": sig["tag"], "id": sig["id"], "children": sig.get("children", [])}
            hdr_match = strip_root_class(app_hdr_sig) == strip_root_class(pairs_hdr_sig)

            key = "%sx%s" % (hp_vp["width"], hp_vp["height"])
            hp_results[key] = {
                "hdrMatch": hdr_match,
                "setPopMatch": app_setpop_sig == pairs_setpop_sig,
                "appGeom": app_geom, "pairsGeom": pairs_geom,
                "errs": hp_aerrs + hp_perrs,
            }
        print("[header parity] %s" % hp_results)
        for hp_key, hp_r in hp_results.items():
            assert hp_r["hdrMatch"], (
                "[header parity] header DOM signature differs between app and pairs at %s" % hp_key)
            assert hp_r["setPopMatch"], (
                "[header parity] #setPop DOM signature differs between app and pairs at %s" % hp_key)
            for hp_sel in hp_r["appGeom"]:
                a, pr = hp_r["appGeom"][hp_sel], hp_r["pairsGeom"][hp_sel]
                if a is None and pr is None:
                    continue
                assert a is not None and pr is not None, (
                    "[header parity] %r present on one page but not the other at %s" % (hp_sel, hp_key))
                assert abs(float(a) - float(pr)) <= 1, (
                    "[header parity] %r top differs by more than 1px at %s: app=%s pairs=%s"
                    % (hp_sel, hp_key, a, pr))
            assert not hp_r["errs"], "[header parity] errors at %s: %s" % (hp_key, hp_r["errs"])

        # ---- [header no overlap] ۲۷ سپتامبر: در حالتِ دسکتاپِ مرورگرِ گوشی (~۹۸۰px) خوشه‌ی
        # راست روی «New pairs» می‌افتاد. در هر پهنا از ۹۶۱ تا ۱۲۸۰، در اپ و /pairs، لوگو،
        # ناوبری و خوشه‌ی راست نباید هم‌پوشانی کنند (فاصله ≥ ۴px). ----
        HNO_JS = """() => {
            const r = s => { const e = document.querySelector(s); if (!e) return null;
                             const b = e.getBoundingClientRect(); return [b.left, b.right]; };
            return { logo: r('header > .logo'), nav: r('header > .nav'), right: r('header > .hdrRight'),
                     sw: document.documentElement.scrollWidth, w: innerWidth };
        }"""
        hno = []
        for hno_w in (961, 980, 1024, 1100, 1180, 1280):
            vp = {"width": hno_w, "height": 800}
            hpa = await b.new_page(viewport=vp)
            await hpa.goto("http://127.0.0.1:%d/" % port)
            await hpa.wait_for_timeout(300)
            ga = await hpa.evaluate(HNO_JS)
            await hpa.close()
            hpp, _hp_e = await open_pairs({"chain": "base", "rows": [], "store": True}, viewport=vp)
            gp = await hpp.evaluate(HNO_JS)
            await hpp.close()
            for page_name, g in (("app", ga), ("pairs", gp)):
                assert g["logo"] and g["nav"] and g["right"], "[header no overlap] %s@%d missing parts: %s" % (page_name, hno_w, g)
                assert g["logo"][1] + 4 <= g["nav"][0], "[header no overlap] %s@%d logo runs into nav: %s" % (page_name, hno_w, g)
                assert g["nav"][1] + 4 <= g["right"][0], "[header no overlap] %s@%d nav runs under the right cluster: %s" % (page_name, hno_w, g)
                assert g["sw"] <= g["w"], "[header no overlap] %s@%d horizontal scroll: %s" % (page_name, hno_w, g)
                hno.append("%s@%d gap=%d" % (page_name, hno_w, round(g["right"][0] - g["nav"][1])))
        print("[header no overlap] " + ", ".join(hno))

        # ۲) بدونِ دکمه‌ی مستقلِ تم؛ چیپِ شبکه با برچسبِ زنجیره‌ی فعال.
        ppg2, perrs2 = await open_pairs({"chain": "base", "rows": [SELL_ROW], "store": True})
        chip_info = await ppg2.evaluate("""() => ({
            hasThemeToggle: !!document.getElementById('themeToggle') ||
                            !!document.querySelector('.theme-toggle'),
            srcText: document.getElementById('srcTx') ?
                     document.getElementById('srcTx').textContent : null,
            ledOff: document.querySelector('#srcChip .led') ?
                    document.querySelector('#srcChip .led').classList.contains('off') : null,
        })""")
        await ppg2.click('.chain-tabs [data-chain="solana"]')
        await ppg2.wait_for_timeout(200)
        src_after_solana = await ppg2.eval_on_selector('.chain-tabs [data-chain="solana"]', 'e => e.classList.contains("on")')
        await ppg2.close()
        print("[pairs shell] no standalone theme button=%s srcChip base=%r solana=%r ledOff=%s "
              "errors=%s" % (not chip_info["hasThemeToggle"], chip_info["srcText"],
                              src_after_solana, chip_info["ledOff"], perrs2))
        assert not chip_info["hasThemeToggle"], (
            "web/pairs.html still has a standalone theme button — it must move into the wallet "
            "popover instead")
        assert chip_info["srcText"] is None and chip_info["ledOff"] is None, "New pairs must not have a header network control"
        assert src_after_solana is True, "The Solana tab inside New pairs must remain functional"
        assert not perrs2, "web/pairs.html threw during the network-chip probe: %s" % perrs2

        # ۳‌الف) آیتمِ Theme دیگر در بازشوی کیف‌پول نیست — حتی وقتی کیف‌پول
        # وصل است و آن بازشو واقعاً وجود دارد.
        w5a, werrs5a, cerrs5a = await open_wallet_page(init_script=fake_provider_script(FAKE_ADDR))
        await w5a.click("#connectBtn")
        await w5a.wait_for_timeout(150)
        no_theme_in_wallet = await w5a.evaluate(
            "() => !document.querySelector('#walletPop #themeBtn')")
        wallet_pop_exists = await w5a.evaluate("() => !!document.getElementById('walletPop')")
        await w5a.close()
        print("[pairs shell] connected wallet popover has no theme item: %s (popover existed: %s) "
              "errors=%s %s" % (no_theme_in_wallet, wallet_pop_exists, werrs5a, cerrs5a))
        assert wallet_pop_exists, "expected #walletPop to exist for a connected wallet"
        assert no_theme_in_wallet, "the wallet popover must not contain #themeBtn any more"
        assert not werrs5a and not cerrs5a, "errors during the wallet-popover probe: %s %s" % (werrs5a, cerrs5a)

        # ۳‌ب) بدونِ هیچ پروایدر/کلیدی — #setBtn بازشوی تنظیمات را باز می‌کند،
        # آیتمِ Theme آن‌جا تم را عوض/ذخیره می‌کند، و بعدِ رفرش همان تم می‌ماند.
        w5b, werrs5b, cerrs5b = await open_wallet_page()
        before5 = await w5b.evaluate("""() => ({
            theme: document.documentElement.dataset.theme,
            setPopOpen: document.getElementById('setPop').classList.contains('on'),
            themeBtnInHeader: !!document.querySelector('body>header #themeBtn'),
        })""")
        await w5b.click("#setBtn")
        await w5b.wait_for_timeout(150)
        setPopOpenAfterClick = await w5b.evaluate(
            "() => document.getElementById('setPop').classList.contains('on')")
        # Escape باید #setPop را ببندد — عیناً همان رفتارِ بازشوی کیف‌پول.
        # ⚠️ بعد از این، به‌جای کلیکِ دوباره‌ی #setBtn (که toggle است و اگر
        # Escape واقعاً نبسته باشد، این کلیک آن را می‌بندد نه باز — و کلیکِ
        # themeBtn روی عنصرِ نامرئی ۳۰ ثانیه هنگ می‌کند)، مستقیماً با کلاس
        # 'on' باز می‌شود تا ادعای بعدی (تعویضِ تم) مستقل از نتیجه‌ی همین
        # سنجه بماند و کاوشگر همیشه سریع و تمیز جواب بدهد.
        await w5b.keyboard.press("Escape")
        await w5b.wait_for_timeout(100)
        setPopClosedOnEscape = await w5b.evaluate(
            "() => !document.getElementById('setPop').classList.contains('on')")
        await w5b.evaluate("() => document.getElementById('setPop').classList.add('on')")
        await w5b.wait_for_timeout(100)
        await w5b.click("#themeBtn")
        await w5b.wait_for_timeout(80)
        after5 = await w5b.evaluate("""() => ({
            theme: document.documentElement.dataset.theme,
            ls: (function(){ try { return localStorage.getItem('zaexa.theme.v1'); } catch(e){ return null; } })(),
            stateText: document.getElementById('themeState') ? document.getElementById('themeState').textContent : null,
        })""")
        await w5b.reload()
        await w5b.wait_for_timeout(300)
        reload5_theme = await w5b.evaluate("() => document.documentElement.dataset.theme")
        await w5b.close()
        print("[pairs shell] settings-popover theme item (no wallet): before=%r setPopAfterClick=%s "
              "closedOnEscape=%s after=%r reload=%r errors=%s %s"
              % (before5, setPopOpenAfterClick, setPopClosedOnEscape, after5, reload5_theme,
                 werrs5b, cerrs5b))
        assert before5["themeBtnInHeader"], "the header must contain #themeBtn"
        assert before5["setPopOpen"] is False, "#setPop must start closed"
        assert setPopOpenAfterClick is True, "clicking #setBtn must open #setPop"
        assert setPopClosedOnEscape, "pressing Escape must close #setPop, like the wallet popover"
        assert after5["theme"] != before5["theme"], (
            "clicking the Theme item did not flip document.documentElement.dataset.theme")
        assert after5["ls"] == after5["theme"], (
            "clicking the Theme item did not persist to localStorage under zaexa.theme.v1: %r"
            % after5["ls"])
        assert after5["stateText"] == ("Dark" if after5["theme"] == "dark" else "Light"), (
            "#themeState did not update to match the new theme: %r" % after5["stateText"])
        assert reload5_theme == after5["theme"], (
            "the theme did not survive a reload: before-reload=%r after-reload=%r"
            % (after5["theme"], reload5_theme))
        assert not werrs5b and not cerrs5b, (
            "errors during the settings theme-item probe (no wallet): %s %s" % (werrs5b, cerrs5b))

        # ---- [pairs footer] فوترِ کاملِ اپ — footGrid با دقیقاً سه footCol +
        # footBrand، لینک‌های ستونِ Trade، لینکِ قرارداد روی BaseScan، بدونِ
        # تلگرام، دو اسپنِ دقیقِ footBottom. ----
        ppg3, perrs3 = await open_pairs({"chain": "base", "rows": [], "store": True})
        # ۱۸ اکتبر [mobile compact]: سه footCol حالا داخل <details class="fMore"> هستند که خودش فرزندِ footGrid است.
        foot_info = await ppg3.evaluate("""() => {
            const grid = document.querySelector('.footGrid');
            const cols = grid ? grid.querySelectorAll(':scope > .footCol, :scope > .fMore > .footCol').length : 0;
            const hasBrand = !!(grid && grid.querySelector(':scope > .footBrand'));
            const tradeCol = grid ? grid.querySelectorAll(':scope > .footCol, :scope > .fMore > .footCol')[0] : null;
            const tradeHrefs = tradeCol ? [...tradeCol.querySelectorAll('a')].map(a => a.getAttribute('href')) : [];
            const anchors = [...document.querySelectorAll('footer a')];
            const baseScan = anchors.find(a => (a.getAttribute('href') || '').includes('basescan.org'));
            const hasTelegram = anchors.some(a =>
                /telegram/i.test(a.getAttribute('title') || '') ||
                /t\\.me\\//.test(a.getAttribute('href') || ''));
            const bottom = document.querySelector('.footBottom');
            const bottomSpans = bottom ? [...bottom.querySelectorAll(':scope > span')].map(s => s.textContent) : [];
            return {cols, hasBrand, tradeHrefs, baseScanHref: baseScan ? baseScan.getAttribute('href') : null,
                    hasTelegram, bottomSpans};
        }""")
        await ppg3.close()
        print("[pairs footer] cols=%s hasBrand=%s tradeHrefs=%s baseScanHref=%s hasTelegram=%s "
              "bottomSpans=%s errors=%s" % (foot_info["cols"], foot_info["hasBrand"],
              foot_info["tradeHrefs"], foot_info["baseScanHref"], foot_info["hasTelegram"],
              foot_info["bottomSpans"], perrs3))
        assert foot_info["cols"] == 3, (
            "web/pairs.html's .footGrid must have exactly 3 .footCol, found %s" % foot_info["cols"])
        assert foot_info["hasBrand"], "web/pairs.html's .footGrid is missing its .footBrand child"
        assert foot_info["tradeHrefs"] == ["/app#swap", "/app#folio", "/app#flow", "/pairs"], (
            "the Trade footer column's hrefs are wrong: %s" % foot_info["tradeHrefs"])
        assert foot_info["baseScanHref"] == (
            "https://basescan.org/address/%s#code" % LIVE_EXECUTOR), (
            "the BaseScan footer link does not point at the live executor with #code: %r"
            % foot_info["baseScanHref"])
        assert foot_info["hasTelegram"] == bool(app_telegram_link()), (
            "web/pairs.html's footer Telegram icon (%s) does not match LINKS.telegram in the app (%r)"
            % (foot_info["hasTelegram"], app_telegram_link()))
        assert foot_info["bottomSpans"] == [
            "Non-custodial · this page reads only our own endpoints · not audited",
            "© 2026 Zaexa",
        ], ".footBottom's two spans are not exactly right: %s" % foot_info["bottomSpans"]
        assert not perrs3, "web/pairs.html threw during the footer probe: %s" % perrs3

        # ---- اسکرین‌شات‌ها — نگاهِ نهایی، برای چشم نه فقط برای کاوشگر ----
        shell_shot_dir = "/tmp/pairs_shell"
        os.makedirs(shell_shot_dir, exist_ok=True)
        sd1, sd1errs, _ = await open_wallet_page(color_scheme="dark")
        await sd1.screenshot(path=os.path.join(shell_shot_dir, "pairs-1280-dark.png"), full_page=True)
        await sd1.close()

        appd, appd_errs = [], []
        adpg = await b.new_page(viewport={"width": 1280, "height": 900}, color_scheme="dark")
        adpg.on("pageerror", lambda e: appd_errs.append(str(e)))
        await adpg.goto("http://127.0.0.1:%d/" % port)
        await adpg.wait_for_timeout(400)
        await adpg.screenshot(path=os.path.join(shell_shot_dir, "app-1280-dark-header.png"))
        await adpg.close()

        sl1, sl1errs, _ = await open_wallet_page(color_scheme="light")
        await sl1.screenshot(path=os.path.join(shell_shot_dir, "pairs-1280-light.png"), full_page=True)
        await sl1.close()

        sm1, sm1errs, _ = await open_wallet_page(
            color_scheme="dark", viewport={"width": 390, "height": 844})
        await sm1.screenshot(path=os.path.join(shell_shot_dir, "pairs-390-dark.png"))
        await sm1.close()
        print("[pairs shell] screenshots written to %s (errors: %s %s %s %s)"
              % (shell_shot_dir, sd1errs, appd_errs, sl1errs, sm1errs))
        assert not sd1errs and not appd_errs and not sl1errs and not sm1errs, (
            "errors while taking shell/footer screenshots")

        # ---- اسکرین‌شات‌های بازشوی تنظیمات — باز، تا دیده شود از صفحه/هدر
        # بیرون نمی‌زند ----
        shell2_shot_dir = "/tmp/pairs_shell2"
        os.makedirs(shell2_shot_dir, exist_ok=True)
        sp1, sp1errs, _ = await open_wallet_page(color_scheme="dark")
        await sp1.click("#setBtn")
        await sp1.wait_for_timeout(200)
        await sp1.screenshot(path=os.path.join(shell2_shot_dir, "pairs-1280-dark-settings.png"))
        await sp1.close()

        sp2, sp2errs, _ = await open_wallet_page(
            color_scheme="dark", viewport={"width": 390, "height": 844})
        await sp2.click("#setBtn")
        await sp2.wait_for_timeout(200)
        await sp2.screenshot(path=os.path.join(shell2_shot_dir, "pairs-390-dark-settings.png"))
        await sp2.close()
        print("[pairs shell] settings-popover screenshots written to %s (errors: %s %s)"
              % (shell2_shot_dir, sp1errs, sp2errs))
        assert not sp1errs and not sp2errs, "errors while taking settings-popover screenshots"

        # ---- [server sell ret] fetchVdVerdict واقعی، /vd استاب‌شده روی سیم — نه
        # جایگزینیِ خودِ تابع؛ همان اعتبارسنجیِ بازه که در fetchVdVerdict نوشته شده
        # اینجا واقعاً اجرا می‌شود، تا شکستنِ عمدیِ سقفِ ۱۰۰۰ در پایین همین تست
        # قرمز شود. ----
        async def open_ret_harness(vd_body):
            rpg = await b.new_page(viewport={"width": 1240, "height": 1000})

            async def stub_vd(route):
                await route.fulfill(status=200, content_type="application/json",
                                     body=_json.dumps(vd_body))
            await rpg.route("**/vd/**", stub_vd)
            await rpg.goto("http://127.0.0.1:%d/test/harness.html" % port)
            await rpg.wait_for_timeout(600)
            return rpg

        RET_SETTLE_PROBE = """async () => {
            const saved = {
                tokenPage, tokenOut,
                boxHTML: document.getElementById("tk-exitBox").innerHTML
            };
            tokenPage = true;
            tokenOut = {address: "0x" + "16".repeat(20), symbol: "T16", decimals: 18,
                        native: false, name: "T16"};
            tkExitSeq++;
            await tokenExitFallback(tkExitSeq, "timeout");
            const box = document.getElementById("tk-exitBox");
            const note = box.querySelector(".tripNote");
            const text = note ? note.textContent : null;
            tokenPage = saved.tokenPage; tokenOut = saved.tokenOut;
            box.innerHTML = saved.boxHTML;
            clearTimeout(tkExitTimer); tkExitTimer = null;
            return text;
        }"""

        r1p = await open_ret_harness({"v": "sell", "ret": 0.1})
        r1 = await r1p.evaluate(RET_SETTLE_PROBE)
        await r1p.close()
        r2p = await open_ret_harness({"v": "sell"})
        r2 = await r2p.evaluate(RET_SETTLE_PROBE)
        await r2p.close()
        r3p = await open_ret_harness({"v": "sell", "ret": 5000})
        r3 = await r3p.evaluate(RET_SETTLE_PROBE)
        await r3p.close()
        r4p = await open_ret_harness({"v": "sell", "ret": "0.1"})
        r4 = await r4p.evaluate(RET_SETTLE_PROBE)
        await r4p.close()

        print("[server sell ret] ret=0.1 -> %r" % r1)
        print("[server sell ret] no ret -> %r" % r2)
        print("[server sell ret] ret=5000 -> %r" % r3)
        print("[server sell ret] ret='0.1' (string) -> %r" % r4)
        ORIG_TRIPNOTE = (
            "This page could not quote a sell through the pools it knows. Our server "
            "check covers more pools — for example Uniswap v4 — and it priced "
            "a sell. That is a quote, not a simulation.")
        assert r1 == ORIG_TRIPNOTE + (
            " A $100 sell, valued at the listed price, was quoted back at 0.1%."), (
            "a valid ret=0.1 from a real /vd response did not append the exact "
            "quote-back sentence: %r" % r1)
        assert r2 == ORIG_TRIPNOTE, (
            "no ret must leave the tripNote text byte-identical to today's: %r" % r2)
        assert r3 == ORIG_TRIPNOTE, (
            "ret=5000 (above the 1000 bound) must not be shown: %r" % r3)
        assert r4 == ORIG_TRIPNOTE, (
            "a string ret ('0.1') must not be shown: %r" % r4)

        # ---- [events share] share:copy فقط از دو دکمه‌ی «share a check» —
        # #checkShare و #tk-copy — و فقط وقتی کپی واقعاً موفق شده. #shareBtn یک
        # کوتِ سواپ را به اشتراک می‌گذارد، نه یک چک، پس هرگز share:copy نمی‌فرستد. ----
        def clip_init_script(ok):
            return ("Object.defineProperty(navigator,'clipboard',{value:{writeText:"
                    "()=>Promise.%s},configurable:true});"
                    % ("resolve()" if ok else "reject(new Error('no-clipboard'))"))

        async def swap_share_page(clip_ok, gpc=False):
            p = await b.new_page(viewport={"width": 1240, "height": 1000})
            await p.add_init_script(clip_init_script(clip_ok))
            if gpc:
                await p.add_init_script(
                    "Object.defineProperty(navigator,'globalPrivacyControl',{get:()=>true});")
            seen = await watch_events(p)
            await p.goto("http://127.0.0.1:%d/test/harness.html#swap" % port)
            await p.wait_for_timeout(1200)
            return p, seen

        async def token_share_page(clip_ok, gpc=False):
            p = await b.new_page(viewport={"width": 1240, "height": 1000})
            await p.add_init_script(clip_init_script(clip_ok))
            if gpc:
                await p.add_init_script(
                    "Object.defineProperty(navigator,'globalPrivacyControl',{get:()=>true});")
            seen = await watch_events(p)
            await p.goto("http://127.0.0.1:%d%s" % (port, ck_path))
            await p.wait_for_timeout(1500)
            return p, seen

        def share_names(seen_list):
            return [_json.loads(r)["e"] for r in seen_list if _json.loads(r)["e"] == "share:copy"]

        # ۱) #checkShare، کلیپ‌بورد سالم -> دقیقاً یک بیکن
        p1, seen1 = await swap_share_page(True)
        assert await p1.is_visible("#checkShare"), "#checkShare is not visible on the swap page"
        before1 = len(seen1)
        await p1.click("#checkShare")
        await p1.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p1.wait_for_timeout(500)
        names1 = share_names(seen1[before1:])
        await p1.close()
        print("[events share] #checkShare, working clipboard -> %s" % names1)
        assert names1 == ["share:copy"], (
            "expected exactly one share:copy beacon from #checkShare, got %s" % names1)

        # ۲) #tk-copy، کلیپ‌بورد سالم -> دقیقاً یک بیکن
        p2, seen2 = await token_share_page(True)
        assert await p2.is_visible("#tk-copy"), "#tk-copy is not visible on the token page"
        before2 = len(seen2)
        await p2.click("#tk-copy")
        await p2.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p2.wait_for_timeout(500)
        names2 = share_names(seen2[before2:])
        await p2.close()
        print("[events share] #tk-copy, working clipboard -> %s" % names2)
        assert names2 == ["share:copy"], (
            "expected exactly one share:copy beacon from #tk-copy, got %s" % names2)

        # ۳) کلیپ‌بورد ناموفق -> هیچ بیکنی از هیچ‌کدام
        p3, seen3 = await swap_share_page(False)
        before3 = len(seen3)
        await p3.click("#checkShare")
        await p3.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p3.wait_for_timeout(400)
        names3 = share_names(seen3[before3:])
        await p3.close()
        p3b, seen3b = await token_share_page(False)
        before3b = len(seen3b)
        await p3b.click("#tk-copy")
        await p3b.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p3b.wait_for_timeout(400)
        names3b = share_names(seen3b[before3b:])
        await p3b.close()
        print("[events share] failing clipboard -> checkShare=%s tk-copy=%s" % (names3, names3b))
        assert names3 == [], "a failing clipboard must never send share:copy, got %s" % names3
        assert names3b == [], "a failing clipboard must never send share:copy, got %s" % names3b

        # Header link button was removed on request; report copy actions above remain.
        p4, seen4 = await swap_share_page(True)
        assert await p4.locator("#shareBtn").count() == 0
        await p4.close()

        # ۵) Global Privacy Control روشن -> هیچ بیکنی
        p5, seen5 = await swap_share_page(True, gpc=True)
        before5 = len(seen5)
        await p5.click("#checkShare")
        await p5.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p5.wait_for_timeout(400)
        names5 = share_names(seen5[before5:])
        await p5.close()
        p5b, seen5b = await token_share_page(True, gpc=True)
        before5b = len(seen5b)
        await p5b.click("#tk-copy")
        await p5b.click('#shareMenu [data-act="link"]')   # ۲۴ اکتبر: دکمه‌ی اشتراک حالا منو باز می‌کند؛ «Copy link» همان کپیِ قبلی است
        await p5b.wait_for_timeout(400)
        names5b = share_names(seen5b[before5b:])
        await p5b.close()
        print("[events share] Global Privacy Control on -> checkShare=%s tk-copy=%s"
              % (names5, names5b))
        assert names5 == [], "GPC must silence share:copy too, got %s" % names5
        assert names5b == [], "GPC must silence share:copy too, got %s" % names5b

        srv.shutdown()
        await b.close()

    print("\n--- console errors ---")
    if errors:
        for e in errors: print("  ", e)
        sys.exit(1)
    print("   none")



